/// An image marker past what the run decodes is said with both of the run's caps, and as no
/// other refusal (the renderer's check stood in for, the process's budget left alone).
#[test]
fn an_image_marker_past_the_runs_budget_is_said_with_its_caps() {
    let mut s = world();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    let picture = rustgis_map::Picture::new(&base64::Engine::encode(&base64::engine::general_purpose::STANDARD, b"\x89PNG"));
    s.map_mut().layer_mut(id).unwrap().renderer.map_symbols(|sym| sym.marker = rustgis_map::Marker::Picture(picture));
    let spent = |_| Some(rustgis_render::MarkerRefusal::PastRunPixels);
    let said: Vec<String> =
        crate::project::picture_notices_by([s.map().layer(id).unwrap()], [], &spent).iter().map(|n| n.english()).collect();
    assert_eq!(
        said,
        [
            "Image markers in \"Cities\" are past what RustGIS decodes of marker images until it restarts (256 megapixels, 128 MiB) and are drawn as circles"
        ]
    );
}

/// An SVG is a marker's image: `layer.marker` takes one, drawn at its proportions, as an undo
/// step. One with filters, or with more to draw than a 2048 × 2048 image, is refused saying why,
/// and changes nothing.
#[test]
fn layer_marker_takes_an_svg_and_refuses_one_it_cant_draw() {
    use base64::Engine;
    use rustgis_map::{Marker, Picture};
    let svg = |body: &str| {
        let text = format!(r#"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 20">{body}</svg>"#);
        base64::engine::general_purpose::STANDARD.encode(text)
    };
    let mut s = world();
    let marker = |s: &Session| s.map().layer_by_name("Cities").unwrap().symbol(0).marker;
    let depth = s.undo_depth();
    let blurred = svg(r#"<filter id="f"><feGaussianBlur stdDeviation="2"/></filter><rect width="40" height="20" filter="url(#f)"/>"#);
    let piled = svg(&r##"<rect width="40" height="20" fill="#0a0" fill-opacity="0.5"/>"##.repeat(2000));
    for (refused, why) in [
        (
            blurred,
            "this one is an SVG with filters, text, images, animation or links to other files, which RustGIS doesn't draw in marker images",
        ),
        (piled, "this one is an SVG with more to draw than a 2048 × 2048 image"),
    ] {
        let e = s.run("layer.marker", &json!({"layer": "Cities", "image": refused})).unwrap_err();
        assert!(e.to_string().ends_with(why), "{e}");
        assert_eq!((marker(&s), s.undo_depth()), (Marker::Circle, depth));
    }
    let pin = svg(r##"<circle cx="10" cy="10" r="9" fill="#c00"/><rect x="22" y="2" width="16" height="16" fill="#00c"/>"##);
    s.run("layer.marker", &json!({"layer": "Cities", "image": pin, "size": 20})).unwrap();
    assert_eq!((marker(&s), s.undo_depth()), (Marker::Picture(Picture::new(&pin)), depth + 1));
    assert_eq!(rustgis_render::picture_marker_kept_check(Picture::new(&pin)), Ok(0.5));
}

/// An SVG image marker that has too much to draw, or filters, is said with why on reading, apart
/// from the others, each cause its own (#2713) (the renderer's check stood in for).
#[test]
fn svg_image_markers_that_dont_draw_are_said_with_why() {
    use rustgis_render::MarkerRefusal;
    let mut s = world();
    let picture = rustgis_map::Picture::new(&base64::Engine::encode(&base64::engine::general_purpose::STANDARD, "<svg/>"));
    let [cities, rivers] = ["Cities", "Rivers"].map(|name| s.map().layer_by_name(name).unwrap().id);
    for id in [cities, rivers] {
        s.map_mut().layer_mut(id).unwrap().renderer.map_symbols(|sym| sym.marker = rustgis_map::Marker::Picture(picture));
    }
    let layers = [s.map().layer(cities).unwrap(), s.map().layer(rivers).unwrap()];
    for (why, notice) in [
        (
            MarkerRefusal::TooMuchToDraw,
            "Image markers in \"Cities\", \"Rivers\" are SVGs with more to draw than a 2048 × 2048 image and are drawn as circles",
        ),
        (
            MarkerRefusal::SvgUndrawn,
            "Image markers in \"Cities\", \"Rivers\" are SVGs with filters, text, images, animation or links to other files, which RustGIS doesn't draw in marker images, and are drawn as circles",
        ),
        (MarkerRefusal::TooManyBytes, "Image markers in \"Cities\", \"Rivers\" are longer than 2 MiB as base64 and are drawn as circles"),
        (
            MarkerRefusal::SvgTooNested,
            "Image markers in \"Cities\", \"Rivers\" are SVGs with more than 40,000 XML nodes or nested deeper than 64 levels and are drawn as circles",
        ),
        (
            MarkerRefusal::SvgUnknownRadius,
            "Image markers in \"Cities\", \"Rivers\" are SVGs with a radius whose size RustGIS can't know (in em or ex, or in % of a size in em or ex, or of a nested size in % over 100%), and are drawn as circles",
        ),
        (MarkerRefusal::SvgTooSmall, "Image markers in \"Cities\", \"Rivers\" are SVGs too small to draw and are drawn as circles"),
        (MarkerRefusal::SvgNotUtf8, "Image markers in \"Cities\", \"Rivers\" are SVGs that aren't UTF-8 text and are drawn as circles"),
    ] {
        let said: Vec<String> = crate::project::picture_notices_by(layers, [], &|_| Some(why)).iter().map(|n| n.english()).collect();
        assert_eq!(said, [notice]);
    }
    // The caps the notices write out are the renderer's.
    let (nodes, depth) = (rustgis_render::SVG_XML_NODES, rustgis_render::SVG_DEPTH);
    assert_eq!((nodes, depth), (40_000, 64), "the SVG notices and the picker's say 40,000 and 64");
    assert_eq!(rustgis_map::symbology::MAX_PICTURE_BYTES >> 20, 2, "the notice says 2 MiB");
}

/// Saved image markers that are SVGs open drawn, and one with a filter, which RustGIS doesn't draw,
/// opens said and drawn as a circle, its image kept for saving (#2266 part E).
#[test]
fn an_svg_picture_marker_fixture_opens_drawn_or_said() {
    let text = include_str!("../../../schema/fixtures/picture_markers_svg.rgis");
    let mut s = Session::new(Project::default());
    let mark = s.notice_mark();
    s.run("project.openText", &json!({"text": text})).unwrap();
    let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    let glows = "Image markers in \"Glows\" are SVGs with filters, text, images, animation or links to other files";
    assert!(said.iter().any(|n| n.contains(glows)) && !said.iter().any(|n| n.contains("\"Pins\"")), "{said:?}");
    let picture = |i: usize| match &s.project.styles[i].renderer {
        rustgis_map::Renderer::Single(symbol) => match symbol.marker {
            rustgis_map::Marker::Picture(p) => p,
            other => panic!("{other:?}"),
        },
        other => panic!("{other:?}"),
    };
    assert!(rustgis_render::picture_marker_draws(picture(0)));
    assert!(picture(1).base64().starts_with("PHN2Zy") && !rustgis_render::picture_marker_draws(picture(1)));
    // Saving names the SVGs for a reader of PNG and JPEG markers only to refuse (#2266 part E1b).
    assert_eq!(serde_json::to_value(&s.project).unwrap()["requires"], json!(["picture-markers", "svg-markers"]));
}

/// An SVG image marker requires `svg-markers` as well as `picture-markers` wherever it is saved:
/// a symbol's, a stroke's markers, a dot fill, what No Fill hid and a saved style, in a project, a
/// map file and a layer file. A reader of PNG and JPEG markers only would draw it as a circle. A
/// PNG, or text that doesn't start as XML, requires `picture-markers` alone; text that starts as
/// XML counts as an SVG, as the renderer tells one, without reading it (#2266 part E1b).
#[test]
#[cfg(not(target_arch = "wasm32"))]
fn an_svg_image_marker_requires_svg_markers_wherever_it_is_saved() {
    use base64::Engine;
    let b64 = |bytes: &[u8]| base64::engine::general_purpose::STANDARD.encode(bytes);
    let svg = b64(br##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 8 4"><rect width="8" height="4" fill="#c81e1e"/></svg>"##);
    let mut png = Vec::new();
    image::RgbaImage::from_pixel(8, 4, image::Rgba([200, 30, 30, 255]))
        .write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
        .unwrap();
    let png = b64(&png);
    let pictures = json!(["picture-markers"]);
    let both = json!(["picture-markers", "svg-markers"]);
    let requires = |p: &Project| serde_json::to_value(p).unwrap()["requires"].clone();
    // Removed however the test ends, and its own each run (the process id alone can repeat).
    struct Dir(std::path::PathBuf);
    impl Drop for Dir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_nanos());
    let dir = Dir(std::env::temp_dir().join(format!("rustgis-svg-markers-{}-{nanos}", std::process::id())));
    std::fs::create_dir_all(&dir.0).unwrap();
    let file = |s: &mut Session, command: &str, mut params: Value, name: &str| {
        let path = dir.0.join(name);
        params["path"] = json!(path.display().to_string());
        s.run(command, &params).unwrap();
        serde_json::from_slice::<Value>(&std::fs::read(&path).unwrap()).unwrap()["requires"].clone()
    };
    // `<html>`: XML that isn't an SVG, which the renderer refuses when it reads it.
    for (image, expected) in [(png.as_str(), &pictures), (svg.as_str(), &both), ("bm90IGFuIGltYWdl", &pictures), ("PGh0bWw+", &both)] {
        // A symbol's (set directly: the command refuses an image that is neither), in the
        // project, a map file and a layer file.
        let mut s = world();
        let cities = s.map().layer_by_name("Cities").unwrap().id;
        let picture = rustgis_map::Marker::Picture(rustgis_map::Picture::new(image));
        s.map_mut().layer_mut(cities).unwrap().renderer.map_symbols(|sym| sym.marker = picture);
        assert_eq!(&requires(&s.project), expected, "symbol {image}");
        assert_eq!(&file(&mut s, "map.save", json!({}), "map.rgismap"), expected, "map file {image}");
        assert_eq!(&file(&mut s, "layer.save", json!({"layer": "Cities"}), "cities.rgislayer"), expected, "layer file {image}");
        // And the map file a map package holds, for a computer and for a phone.
        for mobile in [false, true] {
            let pkg = dir.0.join("map.rgismpk");
            s.run("map.package", &json!({"path": pkg.display().to_string(), "mobile": mobile})).unwrap();
            let entries = rustgis_data::zip::read_matching(&std::fs::read(&pkg).unwrap(), |n| n.ends_with(".rgismap")).unwrap();
            let packed: Value = serde_json::from_slice(&entries[0].1).unwrap();
            assert_eq!(&packed["requires"], expected, "package {image}, mobile: {mobile}");
        }
        // A saved style keeps it once the layer no longer does.
        s.run("style.new", &json!({"layer": "Cities", "name": "Icons"})).unwrap();
        s.run("layer.marker", &json!({"layer": "Cities", "shape": "circle"})).unwrap();
        assert_eq!(&requires(&s.project), expected, "style {image}");
    }
    for (image, expected) in [(&png, &pictures), (&svg, &both)] {
        // A stroke's markers.
        let mut s = world();
        s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"width": 1}, {"markers": {"image": image}}]})).unwrap();
        assert_eq!(&requires(&s.project), expected, "stroke");
        assert_eq!(&file(&mut s, "layer.save", json!({"layer": "Rivers"}), "rivers.rgislayer"), expected, "stroke layer file");
        // A dot fill, and what No Fill hid of it.
        let (mut s, id) = no_fill_layer(false);
        s.run("layer.fillLayers", &json!({"layer": id, "fills": [{"pattern": "dots", "image": image}]})).unwrap();
        assert_eq!(&requires(&s.project), expected, "dot fill");
        s.run("layer.noFill", &Value::Null).unwrap();
        assert!(s.map().layer(id).unwrap().hidden_fills.is_some());
        assert_eq!(&requires(&s.project), expected, "hidden by No Fill");
    }
}

/// A saved image marker that is a GIF (which the desktop's decoder reads and the web's doesn't)
/// opens said and drawn as a circle on every platform, its image kept for saving.
#[test]
fn a_gif_picture_marker_fixture_opens_said_as_a_circle() {
    let text = include_str!("../../../schema/fixtures/picture_markers_gif.rgis");
    let mut s = Session::new(Project::default());
    let mark = s.notice_mark();
    s.run("project.openText", &json!({"text": text})).unwrap();
    let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(said.iter().any(|n| n.contains("Image markers in \"Schools\" aren't PNG, JPEG or SVG images")), "{said:?}");
    let rustgis_map::Renderer::Single(symbol) = &s.project.styles[0].renderer else { panic!("a single symbol") };
    let rustgis_map::Marker::Picture(picture) = symbol.marker else { panic!("an image marker") };
    assert!(picture.base64().starts_with("R0lGOD") && !rustgis_render::picture_marker_draws(picture));
}

#[test]
#[cfg(not(target_arch = "wasm32"))]
fn an_image_is_a_marker_kept_in_the_project_file_that_an_older_reader_refuses() {
    use base64::Engine;
    use rustgis_map::{Marker, Picture};
    let mut s = world();
    let marker = |s: &Session| s.map().layer_by_name("Cities").unwrap().symbol(0).marker;
    let mut png = Vec::new();
    image::RgbaImage::from_pixel(8, 4, image::Rgba([200, 30, 30, 255]))
        .write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
        .unwrap();
    let b64 = base64::engine::general_purpose::STANDARD.encode(&png);
    let depth = s.undo_depth();
    // One past the pixels a marker's image takes is refused, saying so, and changes nothing.
    let many = too_many_pixels_png();
    let e =
        s.run("layer.marker", &json!({"layer": "Cities", "image": base64::engine::general_purpose::STANDARD.encode(&many)})).unwrap_err();
    assert!(e.to_string().ends_with("this one has more pixels than 2048 × 2048"), "{e}");
    assert_eq!((marker(&s), s.undo_depth()), (Marker::Circle, depth));
    s.run("layer.marker", &json!({"layer": "Cities", "image": format!(" {b64}\n"), "size": 20})).unwrap();
    assert_eq!(marker(&s), Marker::Picture(Picture::new(&b64)));
    assert_eq!(s.undo_depth(), depth + 1);
    // Kept in the project file, which names it for an older reader to refuse; drawn in an export.
    let dir = std::env::temp_dir().join(format!("rustgis-pictures-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("pictures.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let saved: Value = serde_json::from_slice(&std::fs::read(&path).unwrap()).unwrap();
    assert_eq!(saved["requires"], json!(["picture-markers"]));
    // So does the map file a map package holds.
    for mobile in [false, true] {
        let pkg = dir.join(if mobile { "mobile.rgismpk" } else { "map.rgismpk" });
        s.run("map.package", &json!({"path": pkg.display().to_string(), "mobile": mobile})).unwrap();
        let entries = rustgis_data::zip::read_matching(&std::fs::read(&pkg).unwrap(), |n| n.ends_with(".rgismap")).unwrap();
        let packed: Value = serde_json::from_slice(&entries[0].1).unwrap();
        assert_eq!(packed["requires"], json!(["picture-markers"]), "mobile: {mobile}");
    }
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!(marker(&t), Marker::Picture(Picture::new(&b64)));
    t.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    // An image the file gives that isn't kept, or that isn't an image, is said, not drawn as a
    // circle silently; the rest reads, and a clean file says nothing.
    let saved_text = std::fs::read_to_string(&path).unwrap();
    let opened = |text: String| {
        let mut u = Session::new(Project::default());
        let mark = u.notice_mark();
        u.run("project.openText", &json!({"text": text})).unwrap();
        let said: Vec<String> = u.notices_since(mark).iter().map(|n| n.text.clone()).collect();
        (u, said)
    };
    let (_, said) = opened(saved_text.clone());
    assert!(!said.iter().any(|n| n.contains("Image markers")), "{said:?}");
    let too_long = "A".repeat(rustgis_map::symbology::MAX_PICTURE_BYTES + 4);
    let (u, said) = opened(saved_text.replace(&b64, &too_long));
    assert!(said.iter().any(|n| n.contains("Image markers in \"Cities\" weren't kept")), "{said:?}");
    assert!(matches!(marker(&u), Marker::Picture(p) if p.is_dropped()));
    // A PNG cut after its header reads as one until it's decoded. A GIF the desktop's decoder
    // reads isn't taken, as the web's can't read it.
    let cut = base64::engine::general_purpose::STANDARD.encode(&png[..40]);
    let gif = gif_base64();
    for junk in ["bm90IGFuIGltYWdl", cut.as_str(), gif.as_str()] {
        let (_, said) = opened(saved_text.replace(&b64, junk));
        assert!(said.iter().any(|n| n.contains("Image markers in \"Cities\" aren't PNG, JPEG or SVG images")), "{said:?}");
        assert!(!said.iter().any(|n| n.contains("weren't kept")), "{said:?}");
    }
    // So does a map file or a layer file added on its own.
    let map = serde_json::to_string(t.map()).unwrap();
    let layer = serde_json::to_string(t.map().layer_by_name("Cities").unwrap()).unwrap();
    for (command, text) in [("map.import", map), ("layer.addLayerFile", layer)] {
        let said = |text: String| {
            let mut w = world();
            let mark = w.notices_given();
            w.run(command, &json!({"text": text})).unwrap();
            w.notices_since(mark).iter().map(|n| n.text.clone()).collect::<Vec<String>>()
        };
        assert!(!said(text.clone()).iter().any(|n| n.contains("Image markers")), "{command}");
        let lost = said(text.replace(&b64, &too_long));
        assert!(lost.iter().any(|n| n.contains("Image markers in \"Cities\" weren't kept")), "{command}: {lost:?}");
    }
    // And a styles file.
    let mut w = world();
    w.run("layer.marker", &json!({"layer": "Cities", "image": b64})).unwrap();
    w.run("style.new", &json!({"layer": "Cities", "name": "Icons"})).unwrap();
    let styles = serde_json::to_string(&w.project.styles).unwrap().replace(&b64, &too_long);
    let mark = w.notices_given();
    w.run("style.add", &json!({"text": styles})).unwrap();
    let said: Vec<String> = w.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(said.iter().any(|n| n.contains("Image markers in \"Icons\" weren't kept")), "{said:?}");
    // A layer file names it too.
    let layer = dir.join("cities.rgislayer");
    t.run("layer.save", &json!({"layer": "Cities", "path": layer.display().to_string()})).unwrap();
    let saved: Value = serde_json::from_slice(&std::fs::read(&layer).unwrap()).unwrap();
    assert_eq!(saved["requires"], json!(["picture-markers"]));
    std::fs::remove_dir_all(&dir).ok();
    // A shape takes its place, and the file no longer names it.
    s.run("layer.marker", &json!({"layer": "Cities", "shape": "circle"})).unwrap();
    assert_eq!(marker(&s), Marker::Circle);
    assert!(serde_json::to_value(&s.project).unwrap().get("requires").is_none());
    // A saved style keeps its image, and the project names it while it keeps the style.
    s.run("layer.marker", &json!({"layer": "Cities", "image": b64})).unwrap();
    s.run("style.new", &json!({"layer": "Cities", "name": "Icons"})).unwrap();
    s.run("layer.marker", &json!({"layer": "Cities", "shape": "circle"})).unwrap();
    assert_eq!(serde_json::to_value(&s.project).unwrap()["requires"], json!(["picture-markers"]));
    // A task that sets one names it too (once), and one that only sizes doesn't.
    let mut project = s.project.clone();
    project.styles.clear();
    let step = |command: &str, params: Value| {
        serde_json::from_value(json!({"name": "Icons", "steps": [{"title": "Icon", "command": command, "params": params}]})).unwrap()
    };
    let task = |params: Value| step("layer.marker", params);
    project.tasks = vec![task(json!({"size": 9}))];
    assert!(serde_json::to_value(&project).unwrap().get("requires").is_none());
    project.tasks = vec![task(json!({"image": b64})), task(json!({"image": b64}))];
    assert_eq!(serde_json::to_value(&project).unwrap()["requires"], json!(["picture-markers"]));
    // A stroke's markers or a dot fill set to an image by a step too (#2266); shapes don't.
    for (command, plain, image) in [
        (
            "layer.lineStrokes",
            json!({"strokes": [{"markers": {"mark": "star"}}]}),
            json!({"strokes": [{"width": 1}, {"markers": {"image": b64}}]}),
        ),
        ("layer.fillLayers", json!({"fills": [{"pattern": "dots"}]}), json!({"fills": [{"pattern": "dots", "image": b64}]})),
    ] {
        project.tasks = vec![step(command, plain)];
        assert!(serde_json::to_value(&project).unwrap().get("requires").is_none(), "{command}");
        project.tasks = vec![step(command, image)];
        assert_eq!(serde_json::to_value(&project).unwrap()["requires"], json!(["picture-markers"]), "{command}");
    }
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "image": 7}), "PNG, JPEG or SVG image as base64"),
        (json!({"layer": "Cities", "image": "bm90IGFuIGltYWdl"}), "PNG, JPEG or SVG image as base64"),
        (json!({"layer": "Cities", "image": "%%%"}), "PNG, JPEG or SVG image as base64"),
        (json!({"layer": "Cities", "image": gif_base64()}), "PNG, JPEG or SVG image as base64"),
        (json!({"layer": "Cities", "image": ""}), "image is empty"),
        (json!({"layer": "Cities", "image": " ", "shape": "star"}), "image is empty"),
        (json!({"layer": "Cities", "image": "", "shape": "star", "char": "x"}), "image is empty"),
        (json!({"layer": "Cities", "image": "A".repeat(rustgis_map::symbology::MAX_PICTURE_BYTES + 4)}), "at most 2 MiB"),
        (json!({"layer": "Cities", "image": b64, "shape": "star"}), "only one"),
        (json!({"layer": "Cities", "image": b64, "char": "x"}), "only one"),
        // No layer: refused before the image is kept.
        (json!({"layer": "Nowhere", "image": b64}), "Nowhere"),
    ] {
        let err = s.run("layer.marker", &bad).unwrap_err();
        assert!(err.contains(says), "{err}");
    }
    assert_eq!(s.undo_depth(), depth);
    assert_eq!(marker(&s), Marker::Circle);
}

/// An image is a marker along a line, a mark at a point and a dot fill's marker, as it is a
/// point's (#2266), kept the first time and found where it's kept when given again; a call refused
/// for its layer, its class or what it names with the image keeps none.
#[test]
#[cfg(not(target_arch = "wasm32"))]
fn an_image_marks_a_line_a_point_and_a_dot_fill() {
    use base64::Engine;
    use rustgis_map::fills::FillPattern;
    use rustgis_map::{LineMark, Marker, Picture};
    let png = |rgb: [u8; 3]| {
        let mut png = Vec::new();
        image::RgbaImage::from_pixel(8, 4, image::Rgba([rgb[0], rgb[1], rgb[2], 255]))
            .write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png)
            .unwrap();
        base64::engine::general_purpose::STANDARD.encode(&png)
    };
    // Each command is first given an image nothing kept yet, then the same image again.
    let (b64, dots) = (png([12, 34, 56]), png([65, 66, 67]));
    assert_eq!((Picture::kept(&b64), Picture::kept(&dots)), (None, None));
    let mut s = world();
    let depth = s.undo_depth();
    let mark_of = |s: &Session, layer: &str| s.map().layer_by_name(layer).unwrap().line_strokes[0].markers.map(|m| m.mark);
    // Along a line, with or without "mark": "image"; at a point, as one of its marks.
    for markers in [json!({"image": b64, "size": 12}), json!({"mark": "image", "image": b64})] {
        s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"width": 1}, {"markers": markers}]})).unwrap();
        let picture = Marker::Picture(Picture::kept(&b64).expect("kept by the command"));
        assert_eq!(s.map().layer_by_name("Rivers").unwrap().line_strokes[1].markers.map(|m| m.mark), Some(LineMark::Marker(picture)));
    }
    let picture = Marker::Picture(Picture::new(&b64));
    s.run("layer.lineStrokes", &json!({"layer": "Cities", "strokes": [{"markers": {"image": b64}}]})).unwrap();
    assert_eq!(mark_of(&s, "Cities"), Some(LineMark::Marker(picture)));
    // A dot fill's marker.
    for fill in [json!({"pattern": "dots", "image": dots, "size": 6}), json!({"pattern": "dots", "marker": "image", "image": dots})] {
        s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [fill]})).unwrap();
        let picture = Marker::Picture(Picture::kept(&dots).expect("kept by the command"));
        let f = s.map().layer_by_name("Countries").unwrap().fill_layers.clone();
        assert!(matches!(f[0].pattern, FillPattern::Dots { marker, .. } if marker == picture), "{f:?}");
    }
    assert_eq!(s.undo_depth(), depth + 5);
    // Refused, changing nothing; on the wrong layer, or named with something else, before the
    // image is kept.
    let unkept = png([201, 202, 203]);
    let junk = "bm90IGFuIGltYWdl";
    // Kept, as a file gives one, but not an image: refused where it's kept.
    let _ = Picture::new("bm90IGFuIGltYWdlIGVpdGhlcg==");
    let too_long = "A".repeat(rustgis_map::symbology::MAX_PICTURE_BYTES + 4);
    for (layer, markers, says) in [
        ("Rivers", json!({"image": 7}), "PNG, JPEG or SVG image as base64"),
        ("Rivers", json!({"image": junk}), "PNG, JPEG or SVG image as base64"),
        ("Rivers", json!({"image": gif_base64()}), "PNG, JPEG or SVG image as base64"),
        ("Rivers", json!({"image": ""}), "image is empty"),
        ("Rivers", json!({"mark": "circle", "image": ""}), "image is empty"),
        ("Rivers", json!({"image": "bm90IGFuIGltYWdlIGVpdGhlcg=="}), "PNG, JPEG or SVG image as base64"),
        ("Rivers", json!({"image": too_long}), "at most 2 MiB"),
        ("Rivers", json!({"mark": "image"}), "needs its image"),
        ("Rivers", json!({"mark": "circle", "image": unkept}), "only one"),
        ("Rivers", json!({"mark": "hash", "image": unkept}), "only one"),
        ("Rivers", json!({"char": "x", "image": unkept}), "only one"),
        ("Countries", json!({"image": unkept}), "line and point layers"),
    ] {
        let err = s.run("layer.lineStrokes", &json!({"layer": layer, "strokes": [{"markers": markers}]})).unwrap_err();
        assert!(err.contains(says), "{err}");
    }
    for (layer, fill, says) in [
        ("Countries", json!({"pattern": "dots", "image": 7}), "PNG, JPEG or SVG image as base64"),
        ("Countries", json!({"pattern": "dots", "image": junk}), "PNG, JPEG or SVG image as base64"),
        ("Countries", json!({"pattern": "dots", "image": gif_base64()}), "PNG, JPEG or SVG image as base64"),
        ("Countries", json!({"pattern": "dots", "marker": "star", "image": ""}), "image is empty"),
        ("Countries", json!({"pattern": "hatch", "image": " "}), "image is empty"),
        ("Countries", json!({"pattern": "dots", "image": too_long}), "at most 2 MiB"),
        ("Countries", json!({"pattern": "dots", "marker": "image"}), "needs its image"),
        ("Countries", json!({"pattern": "dots", "marker": "star", "image": unkept}), "only one"),
        ("Countries", json!({"pattern": "dots", "char": "x", "image": unkept}), "only one"),
        ("Rivers", json!({"pattern": "dots", "image": unkept}), "containing polygons"),
        // Another pattern would drop it.
        ("Countries", json!({"pattern": "hatch", "image": unkept}), "an image is a dots fill's marker"),
        ("Countries", json!({"image": unkept}), "an image is a dots fill's marker"),
    ] {
        let err = s.run("layer.fillLayers", &json!({"layer": layer, "fills": [fill]})).unwrap_err();
        assert!(err.contains(says), "{err}");
    }
    // A class the layer doesn't have, as the wrong layer.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "index": 99, "strokes": [{"markers": {"image": unkept}}]})).unwrap_err();
    s.run("layer.fillLayers", &json!({"layer": "Countries", "index": 99, "fills": [{"pattern": "dots", "image": unkept}]})).unwrap_err();
    // Two new images and a kept one in one call: each stroke its own.
    let (one, two) = (png([1, 2, 3]), png([4, 5, 6]));
    let strokes = json!([{"markers": {"image": one}}, {"markers": {"image": b64}}, {"markers": {"image": two}}]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": strokes})).unwrap();
    let marks: Vec<_> = s.map().layer_by_name("Rivers").unwrap().line_strokes.iter().map(|st| st.markers.map(|m| m.mark)).collect();
    let image = |b64: &str| Some(LineMark::Marker(Marker::Picture(Picture::kept(b64).expect("kept by the call"))));
    assert_eq!(marks, [image(&one), image(&b64), image(&two)]);
    // An image checked in an earlier stroke or fill, the call refused for a later one.
    let first = json!({"markers": {"image": unkept}});
    for later in [json!({"markers": {"image": ""}}), json!({"cap": "pointed"}), json!({"markers": {"image": junk}})] {
        s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [first, later]})).unwrap_err();
    }
    let first = json!({"pattern": "dots", "image": unkept});
    for later in [json!({"pattern": "dots", "image": ""}), json!({"pattern": "zigzag"}), json!({"pattern": "dots", "image": junk})] {
        s.run("layer.fillLayers", &json!({"layer": "Countries", "fills": [first, later]})).unwrap_err();
    }
    assert_eq!(Picture::kept(&unkept), None, "none of these refused calls kept its image");
    assert_eq!(s.undo_depth(), depth + 6);
}

#[test]
fn a_point_takes_stacked_marks_and_turns_by_a_field() {
    use rustgis_map::{Glyph, LineMark, Marker};
    let mut s = world();
    // A white disc under a black character, and a red square 6 pt right of the point.
    let marks = json!([
        {"color": "#FFFFFF", "markers": {"mark": "circle", "size": 14}},
        {"color": "#000000", "markers": {"mark": "character", "char": "A", "size": 12}},
        {"color": "#FF0000", "markers": {"mark": "square", "size": 4, "offsetAlong": 6}}
    ]);
    let mark = s.notice_mark();
    s.run("layer.lineStrokes", &json!({"layer": "Cities", "strokes": marks})).unwrap();
    assert!(s.notices_since(mark).iter().all(|n| !n.text.contains("ignores")), "every key is read");
    let st = s.map().layer_by_name("Cities").unwrap().line_strokes.clone();
    assert_eq!(st.len(), 3);
    assert_eq!(st[1].markers.unwrap().mark, LineMark::Marker(Marker::Char(Glyph::new('A', ""))));
    assert_eq!(st[2].markers.unwrap().offset_along, 6.0);
    // A line stroke would draw nothing at a point.
    let err = s.run("layer.lineStrokes", &json!({"layer": "Cities", "strokes": [{"width": 2}]})).unwrap_err();
    assert!(err.contains("stroke 1: a point layer's strokes are markers"), "{err}");
    let err = s.run("layer.lineStrokes", &json!({"layer": "Countries", "strokes": marks})).unwrap_err();
    assert!(err.contains("line and point layers"), "{err}");
    // Turned by a numeric field, counterclockwise.
    s.run("layer.markerRotation", &json!({"layer": "Cities", "field": "pop_max", "counterclockwise": true})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    let r = l.marker_rotation.clone().unwrap();
    assert_eq!((r.field.as_str(), r.counterclockwise), ("pop_max", true));
    let fi = l.dataset.field_index("pop_max").unwrap();
    let v = l.dataset.value(0, fi).as_f64().unwrap();
    assert_eq!(l.marker_turn(0), -(v.rem_euclid(360.0) as f32));
    // Drawn in an export.
    let dir = std::env::temp_dir().join(format!("rustgis-marks-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "field": "name"}), "not a numeric field"),
        (json!({"layer": "Cities", "field": "nowhere"}), "no field named"),
        (json!({"layer": "Cities", "field": 3}), "field is a field's name"),
        (json!({"layer": "Rivers", "field": "pop_max"}), "point layers"),
    ] {
        let err = s.run("layer.markerRotation", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // None turns them back.
    s.run("layer.markerRotation", &json!({"layer": "Cities", "field": null})).unwrap();
    assert!(s.map().layer_by_name("Cities").unwrap().marker_rotation.is_none());
}

/// A streamed layer holds the view's features only, so its size range isn't taken from them.
#[test]
fn a_streamed_layer_needs_bounds_for_its_size_mapping() {
    let path = grid_fgb("sized", 4);
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true})).unwrap();
    let v = view_of(&mut s, rustgis_geom::Extent::new(-180.0, -80.0, 180.0, 80.0));
    crate::render::render_png(s.map_mut(), &v).unwrap();
    let id = s.map().layers[0].id;
    s.run("layer.symbology", &json!({"layer": id, "type": "unique", "field": "i"})).unwrap();
    let err = s.run("layer.sizeBy", &json!({"layer": id, "field": "x"})).unwrap_err();
    assert!(err.contains("streamed"), "{err}");
    s.run("layer.sizeBy", &json!({"layer": id, "field": "x", "min": -180, "max": 180})).unwrap();
    assert!(s.map().layers[0].size_by.is_some());
}

/// A field with one value in every row, with no bounds given, says so rather than comparing
/// bounds that weren't given; a bound given is still compared with the other.
#[test]
fn sizing_by_a_field_with_one_value_asks_for_bounds() {
    let mut s = world();
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "field": "name"})).unwrap();
    s.run("edit.addField", &json!({"layer": "Cities", "name": "flat", "type": "double"})).unwrap();
    s.run("edit.calculateField", &json!({"layer": "Cities", "field": "flat", "expression": "5"})).unwrap();
    let err = s.run("layer.sizeBy", &json!({"layer": "Cities", "field": "flat"})).unwrap_err();
    assert_eq!(err, "'flat' has the same value (5) in every row, so give min and max");
    let err = s.run("layer.sizeBy", &json!({"layer": "Cities", "field": "flat", "min": 5})).unwrap_err();
    assert!(err.contains("max (5) must be above min (5)"), "{err}");
}

/// `layer.sizeBy` sizes a classified point layer by a field, keeping what it isn't given, refusing
/// what doesn't fit (without an undo step), and is undone and removed like any style.
#[test]
fn a_classified_point_layer_is_sized_by_a_field() {
    let mut s = world();
    let err = s.run("layer.sizeBy", &json!({"layer": "Cities", "field": "pop_max"})).unwrap_err();
    assert!(err.contains("Unique Values or Graduated Colors"), "{err}");
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "field": "name"})).unwrap();
    let r = s.run("layer.sizeBy", &json!({"layer": "Cities", "field": "pop_max", "max": 2e7, "scaling": "radius"})).unwrap();
    let err = s.run("layer.sizeBy", &json!({"layer": "Cities", "field": "pop_max", "min": -1e308, "max": 1e308})).unwrap_err();
    assert!(err.contains("too wide"), "{err}");
    // Without a field, the mapping keeps its field and takes the new settings; with none to
    // change, it's refused.
    s.run("layer.sizeBy", &json!({"layer": "Cities", "maxSize": 30})).unwrap();
    let by = s.map().layer_by_name("Cities").and_then(|l| l.size_by.clone()).unwrap();
    assert_eq!((by.field.as_str(), by.max_size), ("pop_max", 30.0));
    s.run("layer.sizeBy", &json!({"layer": "Cities", "maxSize": 24})).unwrap();
    // The mapping's field named in another case is still its field: its bounds are kept.
    let id = s.map().layer_by_name("Cities").unwrap().id;
    s.map_mut().layer_mut(id).and_then(|l| l.size_by.as_mut()).unwrap().field = "POP_MAX".into();
    s.run("layer.sizeBy", &json!({"layer": "Cities", "maxSize": 24})).unwrap();
    let by = s.map().layer_by_name("Cities").and_then(|l| l.size_by.clone()).unwrap();
    assert_eq!((by.field.as_str(), by.max), ("pop_max", 2e7));
    let (lo, _) = {
        let l = s.map().layer_by_name("Cities").unwrap();
        l.dataset.numeric_range(l.dataset.field_index("pop_max").unwrap(), &[]).unwrap()
    };
    assert_eq!(r, json!({"field": "pop_max", "min": lo, "max": 2e7, "minSize": 4.0, "maxSize": 24.0, "scaling": "radius"}));
    // What isn't given keeps the mapping's.
    s.run("layer.sizeBy", &json!({"layer": "Cities", "field": "pop_max", "maxSize": 30})).unwrap();
    let by = s.map().layer_by_name("Cities").unwrap().size_by.clone().unwrap();
    assert_eq!((by.max, by.max_size, by.scaling), (2e7, 30.0, rustgis_map::symbol_by::SizeScaling::Radius));
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "field": "name"}), "not a numeric field"),
        (json!({"layer": "Cities", "field": "pop_max", "min": 5, "max": 5}), "must be above min"),
        (json!({"layer": "Cities", "field": "pop_max", "maxSize": 1e4}), "maxSize is from 0"),
        (json!({"layer": "Cities", "field": "pop_max", "scaling": "cube"}), "scaling is"),
        (json!({"layer": "Rivers", "field": "pop_max"}), "point layers"),
    ] {
        let err = s.run("layer.sizeBy", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().size_by.as_ref().map(|b| b.max_size), Some(24.0));
    // A web style has no size mapping: said, and nothing said once there is none.
    let dir = std::env::temp_dir().join(format!("rustgis-size-by-style-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("cities.json").display().to_string();
    let web_style_says = |s: &mut Session| {
        let mark = s.notice_mark();
        s.run("share.webStyle", &json!({"layer": "Cities", "path": path})).unwrap();
        s.notices_since(mark).iter().any(|n| n.text.contains("sizes by pop_max aren't in it"))
    };
    assert!(web_style_says(&mut s));
    // Bins drawn instead of the points: said, whichever comes second.
    let bins_said = |s: &mut Session, command: &str, p: Value| {
        let mark = s.notice_mark();
        s.run(command, &p).unwrap();
        s.notices_since(mark).iter().any(|n| n.text.contains("aggregated into bins"))
    };
    assert!(bins_said(&mut s, "layer.aggregation", json!({"layer": "Cities", "shape": "hexagon"})));
    assert!(bins_said(&mut s, "layer.sizeBy", json!({"layer": "Cities", "maxSize": 24})));
    assert!(!bins_said(&mut s, "layer.aggregation", json!({"layer": "Cities", "shape": "none"})));
    s.run("layer.sizeBy", &json!({"layer": "Cities", "field": null})).unwrap();
    assert!(s.map().layer_by_name("Cities").unwrap().size_by.is_none());
    assert!(!web_style_says(&mut s));
    std::fs::remove_dir_all(&dir).ok();
    let err = s.run("layer.sizeBy", &json!({"layer": "Cities", "maxSize": 30})).unwrap_err();
    assert!(err.contains("no size mapping"), "{err}");
    // A saved project's mapping is read back (the schema fixture `size_by.rgis`).
    let saved = Project::from_json(include_str!("../../../schema/fixtures/size_by.rgis")).unwrap();
    let by = saved.maps[0].layers[0].size_by.clone().unwrap();
    assert_eq!((by.field.as_str(), by.min, by.max, by.max_size), ("mag", 2.5, 7.5, 36.0));
    let invalid = include_str!("../../../schema/fixtures/size_by.rgis").replace("\"radius\"", "\"unknown-scaling\"");
    assert!(Project::from_json(&invalid).is_err(), "unreadable mapping must not be silently discarded");
}

/// Desktop range detection lands a worker result without scanning on the window thread, and
/// rejects a stale result after an edit rather than rescanning on that thread.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_size_field_range_is_prepared_off_the_window_thread() {
    use crate::cmd::reads::{read_ahead, read_land};
    use rustgis_analysis::control::Control;
    let mut s = world();
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "field": "name"})).unwrap();
    s.statistics_need_read_ahead(true);
    let params = json!({"layer": "Cities", "field": "pop_max"});
    assert!(s.run("layer.sizeBy", &params).unwrap_err().contains("background read queue"));
    let read = read_ahead(&mut s, "layer.sizeBy", &params).unwrap();
    assert!(read.reads());
    let read = read.run(&Control::new()).unwrap();
    assert!(read_land(&mut s, read).unwrap()["max"].as_f64().unwrap() > 0.0);
    s.run("layer.sizeBy", &json!({"layer": "Cities", "field": null})).unwrap();
    let read = read_ahead(&mut s, "layer.sizeBy", &params).unwrap().run(&Control::new()).unwrap();
    s.map_mut().layers.iter_mut().find(|l| l.name == "Cities").unwrap().dataset.features.get_mut(0).unwrap().attrs.clear();
    assert!(read_land(&mut s, read).unwrap_err().contains("layer changed"));
}

/// New mappings name their required reader capability in projects and map/layer items. Removing
/// the last mapping removes the requirement, so a plain project names none.
#[test]
fn size_mappings_require_a_reader_that_keeps_them() {
    let project = Project::from_json(include_str!("../../../schema/fixtures/size_by.rgis")).unwrap();
    let mut s = Session::new(project);
    let (text, _) = s.project.saved_text(None).unwrap();
    let saved: Value = serde_json::from_str(&text).unwrap();
    assert_eq!(saved["format"], 2);
    assert_eq!(saved["requires"], json!([crate::project::SIZE_BY_CAPABILITY]));
    assert!(Project::from_json(&text).unwrap().maps[0].layers[0].size_by.is_some());
    for kind in ["map", "layer"] {
        let (_, bytes) = crate::cmd::items::item_bytes(&mut s, kind, &json!({"layer": "Earthquakes"})).unwrap();
        let mut item: Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(item["format"], 2);
        assert_eq!(item["requires"], saved["requires"]);
        crate::project::check_format(&item.to_string(), kind).unwrap();
        item["requires"] = json!(["future-point-size"]);
        assert!(crate::project::check_format(&item.to_string(), kind).unwrap_err().contains("future-point-size"));
    }
    for kind in ["mapPackage", "mobilePackage"] {
        let (_, bytes) = crate::cmd::items::item_bytes(&mut s, kind, &json!({"tolerance": 0})).unwrap();
        let entries = rustgis_data::zip::read(&bytes).unwrap();
        let (_, map) = entries.iter().find(|(name, _)| name.ends_with(".rgismap")).unwrap();
        let map: Value = serde_json::from_slice(map).unwrap();
        assert_eq!(map["requires"], saved["requires"]);
        assert_eq!(map["format"], 2);
    }
    s.map_mut().layers[0].size_by = None;
    let (text, _) = s.project.saved_text(None).unwrap();
    let saved: Value = serde_json::from_str(&text).unwrap();
    assert_eq!(saved["format"], crate::project::FORMAT);
    assert!(saved.get("requires").is_none());
    for kind in ["map", "layer"] {
        let (_, bytes) = crate::cmd::items::item_bytes(&mut s, kind, &json!({"layer": "Earthquakes"})).unwrap();
        let item: Value = serde_json::from_slice(&bytes).unwrap();
        assert!(item.get("requires").is_none());
    }
}

#[test]
fn a_symbol_is_set_by_expressions() {
    let mut s = world();
    let r = s
        .run("layer.symbolBy", &json!({"layer": "Cities", "size": "scale_linear(pop_max, 0, 2e7, 4, 20)", "fill": "if(pop_max > 1e7, '#ff0000', NULL)", "angle": "45"}))
        .unwrap();
    assert_eq!(r["angle"], "45");
    let l = s.map().layer_by_name("Cities").unwrap();
    let fi = l.dataset.field_index("pop_max").unwrap();
    let big = (0..l.dataset.features.len()).find(|r| l.dataset.value(*r, fi).as_f64().is_some_and(|v| v > 1e7)).unwrap();
    let st = l.styler(None);
    assert_eq!(st.symbol(big).fill, rustgis_map::Rgba::new(255, 0, 0, 255));
    assert!(st.symbol(big).size > 4.0);
    assert_eq!(st.marker_turn(big), 45.0);
    // Drawn in an export.
    let dir = std::env::temp_dir().join(format!("rustgis-symbol-by-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "size": "nosuch + 1"}), "size: "),
        (json!({"layer": "Cities", "fill": "'red' ||"}), "fill: "),
        (json!({"layer": "Cities", "stroke": 3}), "stroke is an expression"),
        (json!({"layer": "Rivers", "angle": "10"}), "angle works on point layers"),
        (json!({"layer": "Rivers", "size": "4"}), "size works on point layers"),
    ] {
        let err = s.run("layer.symbolBy", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // A line's width by expression; the Cities keep theirs.
    s.run("layer.symbolBy", &json!({"layer": "Rivers", "strokeWidth": "2.5"})).unwrap();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().symbol_by.angle.as_deref(), Some("45"));
    // A key left out is kept; null removes one, and undo brings it back.
    s.run("layer.symbolBy", &json!({"layer": "Cities", "angle": null, "fill": ""})).unwrap();
    let by = &s.map().layer_by_name("Cities").unwrap().symbol_by;
    assert!(by.size.is_some() && by.fill.is_none() && by.angle.is_none());
    s.undo();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().symbol_by.angle.as_deref(), Some("45"));
}

/// Applied again by its own expression, an imported rule style keeps as many classes as it has
/// (past the first 64 values, up to the 200 an import makes); classes by an expression reading the map's scale are said to be
/// the values given without one.
#[test]
fn unique_values_by_expression_keep_their_classes_and_say_scales() {
    let mut s = world();
    let mut ds = rustgis_data::Dataset::new(
        "many",
        rustgis_data::GeometryType::Point,
        vec![rustgis_data::Field::new("v", rustgis_data::FieldType::Integer)],
    );
    let n = rustgis_map::symbology::MAX_EXPRESSION_CLASSES as i64;
    for i in 0..n {
        ds.push(Some(rustgis_data::Geometry::Point(rustgis_geom::Coord::new(i as f64 / 10.0, 1.0))), vec![rustgis_data::Value::Int(i)]);
    }
    let many = s.map_mut().add_dataset(ds);
    let rules: String =
        (0..n).map(|i| format!(r#"<rule filter="&quot;v&quot; = {i} AND &quot;v&quot; &gt;= 0" symbol="0" label="R{i:03}"/>"#)).collect();
    let qml = format!(
        r#"<qgis version="3.40.0"><renderer-v2 type="RuleRenderer"><rules key="r">{rules}</rules><symbols><symbol type="marker" name="0"><layer class="SimpleMarker" enabled="1"/></symbol></symbols></renderer-v2></qgis>"#
    );
    s.run("style.importQgis", &json!({"layer": many, "text": qml})).unwrap();
    let classes = |s: &Session| match &s.map().layer(many).unwrap().renderer {
        rustgis_map::Renderer::Unique { classes, expression: Some(_), .. } => classes.len(),
        r => panic!("{r:?}"),
    };
    assert_eq!(classes(&s), n as usize);
    let mark = s.notice_mark();
    s.run("layer.symbology", &json!({"layer": many, "type": "unique", "ramp": "Ember"})).unwrap();
    assert_eq!(classes(&s), n as usize, "every rule keeps its class, up to the limit");
    let said = |s: &Session, what: &str| s.notices_since(mark).iter().any(|n| n.text.contains(what));
    assert!(!said(&s, "past the first"), "{:?}", s.notices_since(mark));
    assert!(!said(&s, "without a map scale"));
    // An expression of its own keeps the first 64, and says so.
    s.run("layer.symbology", &json!({"layer": many, "type": "unique", "expression": "'k' || (1000 + v)"})).unwrap();
    assert_eq!(classes(&s), rustgis_map::symbology::MAX_UNIQUE);
    assert!(said(&s, "past the first 64"));
    // One reading the map's scale is classed without one, and says so.
    let mark = s.notice_mark();
    s.run(
        "layer.symbology",
        &json!({"layer": many, "type": "unique", "expression": "CASE WHEN @map_scale < 50000 THEN 'detail' ELSE 'overview' END"}),
    )
    .unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("without a map scale")), "{:?}", s.notices_since(mark));
    // Its classes are what it gives with no scale: 'detail' only at some scales isn't one.
    let rustgis_map::Renderer::Unique { classes: kept, .. } = &s.map().layer(many).unwrap().renderer else { panic!() };
    assert_eq!(kept.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["overview"]);
    // So too with the scale written right after a word, which the expression still reads.
    let mark = s.notice_mark();
    s.run(
        "layer.symbology",
        &json!({"layer": many, "type": "unique", "expression": "CASE WHEN@map_scale < 50000 THEN 'detail' ELSE 'overview' END"}),
    )
    .unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("without a map scale")), "{:?}", s.notices_since(mark));
    let rustgis_map::Renderer::Unique { classes: kept, .. } = &s.map().layer(many).unwrap().renderer else { panic!() };
    assert_eq!(kept.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["overview"]);
}

/// A script runs a line written `id={json}`, as the command line and the user guide write it
/// (#2794), and refuses a script inside it written so.
#[test]
fn a_script_runs_a_line_with_its_parameters_after_an_equals_sign() {
    let mut s = numbered_points(&[1]);
    s.run("script.run", &json!({"script": r#"layer.rename={"layer":"Herds","name":"Cows"}"#})).unwrap();
    assert!(s.map().layer_by_name("Cows").is_some(), "renamed");
    let refused = s.run("script.run", &json!({"script": r#"script.run={"script":""}"#})).unwrap_err();
    assert!(refused.contains("can't run in a script"), "{refused}");
}

/// Where a script run stopped (#2815), read from each error a run can stop with: its line, and for
/// JSON that doesn't read, the column in that line (1-based, in characters).
#[test]
fn a_scripts_error_says_where_it_stopped() {
    use crate::cmd::workflows::script_error_at;
    let stop = |s: &mut Session, script: &str, starts: &str| {
        let e = s.run("script.run", &json!({"script": script})).unwrap_err();
        assert!(e.starts_with(starts), "{e}");
        script_error_at(script, &e)
    };
    let mut s = numbered_points(&[1]);
    // An unknown command, on the last line.
    assert_eq!(stop(&mut s, "map.zoomFull\nno.such {}", "line 2: unknown command"), Some((2, None)));
    // A command its conditions refuse, on the first line.
    assert_eq!(stop(&mut s, "edit.delete {}\nmap.zoomFull", "line 1: edit.delete: "), Some((1, None)));
    // A command its extension refuses (`line N (id)`).
    let script = "extension.disable {\"id\": \"imagery\"}\nimagery.workspace {}";
    assert_eq!(stop(&mut s, script, "line 2 (imagery.workspace): "), Some((2, None)));
    // A command that fails as it runs.
    let script = "map.zoomFull\n\nlayer.rename {\"layer\": \"Nope\", \"name\": \"x\"}";
    assert_eq!(stop(&mut s, script, "line 3: layer.rename: "), Some((3, None)));
    // A command that can't run in a script: its JSON reads, so no column.
    assert_eq!(stop(&mut s, "script.run {}", "line 1: "), Some((1, None)));
    // JSON that doesn't read: the column of its error in the line, after indentation and `id=`.
    assert_eq!(stop(&mut s, "map.zoomFull\n  layer.rename= {\"layer\": }", "line 2: "), Some((2, Some(27))));
    // Counted in characters: `á` is two bytes.
    assert_eq!(stop(&mut s, "layer.rename {\"name\": \"Bogotá\", }", "line 1: "), Some((1, Some(33))));
    // JSON cut short: its last character, never past the line.
    assert_eq!(stop(&mut s, "layer.rename {\"name\": ", "line 1: "), Some((1, Some(21))));
    // An edit to a layer read in place.
    let path = grid_fgb("script-stopped-at", 4);
    let mut streamed = with_streamed(&path);
    let script = "edit.enable {\"on\": true}\nedit.addFeature {\"layer\": \"Streamed\", \"geometry\": {\"type\": \"Point\", \"coordinates\": [1, 2]}}";
    assert_eq!(stop(&mut streamed, script, "line 2: "), Some((2, None)));
    let _ = std::fs::remove_file(path);
    // Errors that name no line of the script.
    let long = "map.zoomFull\n".repeat(crate::cmd::workflows::MAX_SCRIPT_LINES + 1);
    let e = s.run("script.run", &json!({"script": long})).unwrap_err();
    assert_eq!(script_error_at(&long, &e), None, "{e}");
    for e in ["line 3: past the end", "line 0: none", "line : no number", "lines 1: no", "line 1x: no"] {
        assert_eq!(script_error_at("a {}\nb {}", e), None, "{e}");
    }
}

/// A notebook from a file reads a cell's `id={json}` line as a script does (#2794): one that
/// stays in the session runs, and one that writes a file is still refused.
#[test]
fn a_notebook_from_a_file_reads_a_line_with_its_parameters_after_an_equals_sign() {
    let mut s = numbered_points(&[1]);
    let png = std::env::temp_dir().join(format!("rustgis-2794-{}.png", std::process::id()));
    let _ = std::fs::remove_file(&png);
    let cells = [r#"layer.rename={"layer":"Herds","name":"Cows"}"#.to_string(), format!("share.exportMap={}", json!({"path": png}))];
    let cells: Vec<Value> = cells.iter().map(|c| json!({"cell_type": "code", "source": c})).collect();
    let text = json!({"nbformat": 4, "metadata": {"language_info": {"name": "rustgis"}}, "cells": cells}).to_string();
    s.run("notebook.open", &json!({"text": text})).unwrap();
    let name = s.project.notebooks.last().unwrap().name.clone();
    let r = s.run("notebook.run", &json!({"notebook": name})).unwrap();
    assert_eq!(r["error"], 1, "{r}");
    assert!(s.map().layer_by_name("Cows").is_some(), "the first cell ran");
    assert!(!png.exists(), "the second wrote nothing");
}

/// A calculation rule and Calculate Field refuse quoted text past the expression language's length
/// limit, as the language refuses any other expression that long (#2783): no rule is kept and no
/// value changes.
#[test]
fn a_calculation_past_the_length_limit_is_refused_by_rules_and_calculate_field() {
    let mut s = numbered_points(&[1]);
    let long = format!("'{}'", "a".repeat(rustgis_data::query::MAX_LEN - 1));
    let rule = json!({"layer": "Herds", "name": "Long", "kind": "calculation", "field": "name", "expression": long});
    let refused = s.run("data.attributeRule", &rule).err();
    assert_eq!(refused.as_deref(), Some("the expression is too long"), "the rule");
    assert!(s.map().layer_by_name("Herds").unwrap().design.rules.is_empty(), "no rule kept");
    let refused = s.run("edit.calculateField", &json!({"layer": "Herds", "field": "name", "expression": long})).err();
    assert_eq!(refused.as_deref(), Some("the expression is too long"), "Calculate Field");
    let ds = &s.map().layer_by_name("Herds").unwrap().dataset;
    assert_eq!(ds.value(0, ds.field_index("name").unwrap()).to_string(), "h1");
    // One already in a project (an earlier version, a hand-edited file) is a rule that doesn't
    // read, skipped as such: an edit goes through and the rule writes nothing.
    let id = s.map().layer_by_name("Herds").unwrap().id;
    let kept = rustgis_map::design::AttributeRule {
        name: "Long".into(),
        kind: rustgis_map::design::RuleKind::Calculation,
        field: "name".into(),
        expression: long,
    };
    s.map_mut().layer_mut(id).unwrap().design.rules.push(kept);
    // A rule that reads beside it: it computes, and isn't named as skipped.
    let clean = json!({"layer": "Herds", "name": "Code", "kind": "calculation", "field": "code", "expression": "n * 10"});
    s.run("data.attributeRule", &clean).unwrap();
    let mark = s.notice_mark();
    s.run("edit.setValue", &json!({"layer": "Herds", "row": 0, "field": "n", "value": 2})).unwrap();
    let ds = &s.map().layer_by_name("Herds").unwrap().dataset;
    assert_eq!(ds.value(0, ds.field_index("name").unwrap()).to_string(), "h1", "the rule wrote nothing");
    assert_eq!(ds.value(0, ds.field_index("code").unwrap()).to_string(), "20", "the clean rule computed");
    // Said, not silent: the layer, how many, and which.
    let said: Vec<&str> = s.notices_since(mark).iter().map(|n| n.text.as_str()).filter(|t| t.contains("no longer read")).collect();
    assert_eq!(said, ["Herds: 1 calculation rule(s) skipped because they no longer read, so their fields weren't computed: Long"]);
    // Without one that doesn't read, nothing is said.
    s.map_mut().layer_mut(id).unwrap().design.rules.retain(|r| r.name != "Long");
    let mark = s.notice_mark();
    s.run("edit.setValue", &json!({"layer": "Herds", "row": 0, "field": "n", "value": 3})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("no longer read")), "{:?}", s.notices_since(mark));
    // Deleting a field drops the rules that no longer read, and says so: here the long rule,
    // put back, on a field other than the one deleted.
    let rules_before = s.map().layer_by_name("Herds").unwrap().design.rules.len();
    let kept = rustgis_map::design::AttributeRule {
        name: "Long".into(),
        kind: rustgis_map::design::RuleKind::Calculation,
        field: "name".into(),
        expression: format!("'{}'", "a".repeat(rustgis_data::query::MAX_LEN - 1)),
    };
    s.map_mut().layer_mut(id).unwrap().design.rules.push(kept);
    let mark = s.notice_mark();
    let r = s.run("edit.deleteField", &json!({"layer": "Herds", "field": "code"})).unwrap();
    assert_eq!(r["rulesRemoved"], 2, "the long rule and Code, whose field went");
    assert_eq!(s.map().layer_by_name("Herds").unwrap().design.rules.len(), rules_before - 1);
    let said: Vec<&str> = s.notices_since(mark).iter().map(|n| n.text.as_str()).filter(|t| t.contains("rule(s)")).collect();
    assert_eq!(said, ["Herds: deleting field code removed 2 attribute rule(s) that used it or no longer read: Code, Long"]);
    // A field no rule depends on: the rule that reads another stays, and nothing is said.
    let twice = json!({"layer": "Herds", "name": "Twice", "kind": "calculation", "field": "n", "expression": "n * 2"});
    s.run("data.attributeRule", &twice).unwrap();
    let mark = s.notice_mark();
    let r = s.run("edit.deleteField", &json!({"layer": "Herds", "field": "name"})).unwrap();
    assert_eq!(r["rulesRemoved"], 0);
    assert_eq!(s.map().layer_by_name("Herds").unwrap().design.rules.len(), 1, "Twice kept");
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("rule(s)")), "{:?}", s.notices_since(mark));
}

/// A layer of points read from GeoJSON, one for each value given, in that order: the integer
/// field `n` holds it, the text field `code` its digits, the text field `name` "h" and them.
fn numbered_points(values: &[i64]) -> Session {
    let feats: Vec<Value> = values
        .iter()
        .enumerate()
        .map(|(i, n)| {
            json!({"type": "Feature", "geometry": {"type": "Point", "coordinates": [i as f64 * 0.1, 0.0]},
                "properties": {"n": n, "code": n.to_string(), "name": format!("h{n}")}})
        })
        .collect();
    let text = json!({"type": "FeatureCollection", "features": feats}).to_string();
    let (ds, _) = rustgis_data::io::read_geojson(&text, "Herds").unwrap();
    let ty = |f: &str| ds.fields[ds.field_index(f).unwrap()].ty;
    assert_eq!(
        (ty("n"), ty("code"), ty("name")),
        (rustgis_data::FieldType::Integer, rustgis_data::FieldType::Text, rustgis_data::FieldType::Text)
    );
    let mut s = Session::new(Project::default());
    let id = s.map_mut().add_dataset(ds);
    s.active_layer = Some(id);
    s
}

fn herd_legend(s: &Session) -> Vec<String> {
    s.map().layer_by_name("Herds").unwrap().renderer.legend().into_iter().map(|e| e.label).collect()
}

fn herd_classes(s: &Session) -> Vec<String> {
    match &s.map().layer_by_name("Herds").unwrap().renderer {
        rustgis_map::Renderer::Unique { classes, .. } => classes.iter().map(|c| c.0.clone()).collect(),
        r => panic!("{r:?}"),
    }
}

/// #1340: Unique Values on an integer field lists its classes and legend by number, as on a text
/// field holding only numbers; a text field of other text keeps text order.
#[test]
fn unique_values_on_a_number_field_are_in_numeric_order() {
    let herds = [10153, 12490, 14443, 1741, 1910, 19947, 2723, 3076, 3672, 4060, 5985, 7636, 9081, 9627];
    let mut s = numbered_points(&herds);
    let mut sorted = herds.to_vec();
    sorted.sort_unstable();
    let numbers: Vec<String> = sorted.iter().map(i64::to_string).collect();
    let mut legend = numbers.clone();
    legend.push("<all other values>".into());
    for field in ["n", "code"] {
        let mark = s.notice_mark();
        s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": field})).unwrap();
        assert_eq!(herd_classes(&s), numbers, "{field}");
        assert_eq!(herd_legend(&s), legend, "{field}");
        // Every value has a class: nothing to say.
        assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("past the first")), "{:?}", s.notices_since(mark));
    }
    // A renamed class keeps its value's row.
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "n"})).unwrap();
    s.run("layer.classStyle", &json!({"layer": "Herds", "value": "9627", "label": "Most"})).unwrap();
    let mut renamed = legend.clone();
    renamed[sorted.iter().position(|v| *v == 9627).unwrap()] = "Most".into();
    assert_eq!(herd_legend(&s), renamed);
    // Text: text order.
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "name"})).unwrap();
    let mut names: Vec<String> = herds.iter().map(|n| format!("h{n}")).collect();
    names.sort();
    assert_eq!(herd_classes(&s), names);
    names.push("<all other values>".into());
    assert_eq!(herd_legend(&s), names);
}

/// More values than Unique Values keeps: the first by number (or by text, for text) are classes,
/// and the features past them are said, with how many, whether classed by a field or an
/// expression.
#[test]
fn unique_values_on_a_field_say_what_is_past_their_classes() {
    let max = rustgis_map::symbology::MAX_UNIQUE;
    // 100 values, each on two features, in no order.
    let values: Vec<i64> = (0..100).rev().chain(0..100).map(|i| i * 7).collect();
    let mut s = numbered_points(&values);
    let past = 2 * (100 - max);
    let first: Vec<String> = (0..max as i64).map(|i| (i * 7).to_string()).collect();
    for field in ["n", "code"] {
        let mark = s.notice_mark();
        s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": field})).unwrap();
        assert_eq!(herd_classes(&s), first, "{field}");
        let said = format!(
            "Herds: {past} features whose value is past the first {max} values of {field} (by number) are drawn as <all other values>"
        );
        assert!(s.notices_since(mark).iter().any(|n| n.text == said), "{said}\n{:?}", s.notices_since(mark));
    }
    let mark = s.notice_mark();
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "expression": "n"})).unwrap();
    assert_eq!(herd_classes(&s), first);
    let said = format!("Herds: {past} features whose value is past the first {max} values the expression gives (by number)");
    assert!(s.notices_since(mark).iter().any(|n| n.text.starts_with(&said)), "{:?}", s.notices_since(mark));
    // Text: the first in text order.
    let mark = s.notice_mark();
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "name"})).unwrap();
    let mut names: Vec<String> = (0..100).map(|i| format!("h{}", i * 7)).collect();
    names.sort();
    assert_eq!(herd_classes(&s), names[..max]);
    let said = format!("Herds: {past} features whose value is past the first {max} values of name (in text order)");
    assert!(s.notices_since(mark).iter().any(|n| n.text.starts_with(&said)), "{:?}", s.notices_since(mark));
    // A selection of fewer values says nothing.
    let mark = s.notice_mark();
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": "n < 300"})).unwrap();
    s.run("layer.symbology", &json!({"layer": "Herds", "type": "unique", "field": "n"})).unwrap();
    assert_eq!(herd_classes(&s).len(), 43);
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("past the first")), "{:?}", s.notices_since(mark));
}

/// Subtypes draw the layer by Unique Values of the subtype field: past 64 values, the features
/// drawn as <all other values> are said too.
#[test]
fn subtypes_say_what_is_past_their_classes() {
    let max = rustgis_map::symbology::MAX_UNIQUE;
    let subtypes = json!([{"code": 0, "name": "None"}, {"code": 7, "name": "Seven"}]);
    let past = |s: &Session, mark| {
        s.notices_since(mark).iter().filter(|n| n.text.contains("past the first")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    // 100 values, each on two features.
    let values: Vec<i64> = (0..100).rev().chain(0..100).map(|i| i * 7).collect();
    let mut s = numbered_points(&values);
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    let first: Vec<String> = (0..max as i64).map(|i| (i * 7).to_string()).collect();
    assert_eq!(herd_classes(&s), first);
    let said = format!(
        "Herds: {} features whose value is past the first {max} values of n (by number) are drawn as <all other values>",
        2 * (100 - max)
    );
    assert_eq!(past(&s, mark), [said]);
    // Only the features a definition query lets through are drawn, so only they are counted;
    // the classes still come from every feature.
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": "n >= 600"})).unwrap();
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    assert_eq!(herd_classes(&s), first, "classes from every feature");
    let said = format!(
        "Herds: {} features whose value is past the first {max} values of n (by number) are drawn as <all other values>",
        2 * (100 - 600 / 7 - 1)
    );
    assert_eq!(past(&s, mark), [said]);
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": "n < 300"})).unwrap();
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    assert!(past(&s, mark).is_empty(), "every drawn feature has a class");
    s.run("layer.definitionQuery", &json!({"layer": "Herds", "where": ""})).unwrap();
    // Not drawn by them, or with fewer values: nothing to say.
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes, "symbolize": false})).unwrap();
    assert!(past(&s, mark).is_empty());
    let mut s = numbered_points(&[0, 7, 14, 7]);
    let mark = s.notice_mark();
    s.run("data.subtypes", &json!({"layer": "Herds", "field": "n", "subtypes": subtypes})).unwrap();
    assert_eq!(herd_classes(&s), ["0", "7", "14"]);
    assert!(past(&s, mark).is_empty());
}

#[test]
fn unique_values_class_by_an_expression() {
    let mut s = world();
    let e = "CASE WHEN pop_max >= 10000000 THEN 'mega' ELSE 'city' END";
    // Classed by a field that isn't the first, which clearing the expression comes back to.
    let by = s.map().layer_by_name("Cities").unwrap().dataset.fields.last().unwrap().name.clone();
    assert_ne!(Some(&by), s.map().layer_by_name("Cities").unwrap().dataset.fields.first().map(|f| &f.name));
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "field": by})).unwrap();
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": e})).unwrap();
    let keys = |s: &Session| match &s.map().layer_by_name("Cities").unwrap().renderer {
        rustgis_map::Renderer::Unique { classes, .. } => classes.iter().map(|c| c.0.clone()).collect::<Vec<_>>(),
        r => panic!("{r:?}"),
    };
    let expression = |s: &Session| s.map().layer_by_name("Cities").unwrap().renderer.expression().map(str::to_string);
    assert_eq!((keys(&s), expression(&s).as_deref()), (vec!["city".to_string(), "mega".to_string()], Some(e)));
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "type": "unique", "expression": "nosuch + 1"}), "nosuch"),
        (json!({"layer": "Cities", "type": "unique", "expression": e, "field": "name"}), "not both"),
        (json!({"layer": "Cities", "type": "graduated", "expression": e}), "only Unique Values"),
        (json!({"layer": "Cities", "type": "unique", "expression": 5}), "expression is text"),
    ] {
        let err = s.run("layer.symbology", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // Applied again with neither a field nor an expression (another colour scheme): the same
    // expression. Null or blank goes back to a field; undo brings the expression back.
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "ramp": "Ember"})).unwrap();
    assert_eq!(expression(&s).as_deref(), Some(e));
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": null})).unwrap();
    assert!(expression(&s).is_none());
    assert_eq!(s.map().layer_by_name("Cities").unwrap().renderer.field(), Some(by.as_str()), "back to the field it had");
    s.undo();
    assert_eq!(expression(&s).as_deref(), Some(e));
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": "  "})).unwrap();
    assert!(expression(&s).is_none(), "blank text goes back to the field too");
    assert_eq!(s.map().layer_by_name("Cities").unwrap().renderer.field(), Some(by.as_str()));
    s.undo();
    assert_eq!(expression(&s).as_deref(), Some(e));
    // A style shared to the web says it draws one symbol; a map draws the classes.
    let dir = std::env::temp_dir().join(format!("rustgis-unique-by-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.webStyle", &json!({"layer": "Cities", "path": dir.join("cities.json").display().to_string()})).unwrap();
    assert!(s.notices.iter().any(|n| n.text.contains("classes by expression aren't in it")), "{:?}", s.notices.last());
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    // More values than classes: the features past them are said, with how many; a few values
    // say nothing.
    let past = |s: &Session| s.notices.iter().filter(|n| n.text.contains("past the first")).count();
    assert_eq!(past(&s), 0);
    s.run("layer.symbology", &json!({"layer": "Cities", "type": "unique", "expression": "name"})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    let (_, rest) =
        rustgis_map::Renderer::unique_by_counted(&l.dataset, &[], "name", rustgis_map::Ramp::Harbour, l.renderer.base_symbol()).unwrap();
    assert!(rest.features > 0 && !rest.by_number);
    let rest = rest.features;
    let said =
        format!("Cities: {rest} features whose value is past the first {} values the expression gives", rustgis_map::symbology::MAX_UNIQUE);
    assert!(s.notices.iter().any(|n| n.text.starts_with(&said)), "{:?}", s.notices.last());
    s.undo();
    // Shared to the web, the one symbol is one that draws: not a rest without a fill or an outline
    // width.
    let cities = s.map().layer_by_name("Cities").unwrap().id;
    let l = s.map_mut().layer_mut(cities).unwrap();
    let rustgis_map::Renderer::Unique { other, classes, .. } = &mut l.renderer else { panic!() };
    (other.fill, other.stroke, other.stroke_width) = (rustgis_map::Rgba::new(0, 0, 0, 0), rustgis_map::Rgba::rgb(9, 9, 9), 0.0);
    let first = classes[0].1.fill.hex();
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("one.json");
    s.run("share.webStyle", &json!({"layer": "Cities", "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let circle = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "circle").unwrap();
    assert_eq!(circle["paint"]["circle-color"], json!(first));
    assert!(s.notices.iter().any(|n| n.text.contains("one symbol (its first class's)")), "{:?}", s.notices.last());
    // A point's rest of no size draws nothing either, however it is filled.
    let l = s.map_mut().layer_mut(cities).unwrap();
    let rustgis_map::Renderer::Unique { other, .. } = &mut l.renderer else { panic!() };
    (other.fill, other.size) = (rustgis_map::Rgba::rgb(9, 9, 9), 0.0);
    s.run("share.webStyle", &json!({"layer": "Cities", "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let circle = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "circle").unwrap();
    assert_eq!(circle["paint"]["circle-color"], json!(first));
    // A line's colour is its stroke's, as the map draws it.
    let mut ds = rustgis_data::Dataset::new("ways", rustgis_data::GeometryType::Polyline, vec![]);
    ds.push(Some(rustgis_data::Geometry::Line(vec![vec![rustgis_data::Coord::new(0.0, 0.0), rustgis_data::Coord::new(1.0, 1.0)]])), vec![]);
    let ways = s.map_mut().add_dataset(ds);
    let l = s.map_mut().layer_mut(ways).unwrap();
    let mut sym = l.renderer.base_symbol();
    (sym.fill, sym.stroke) = (rustgis_map::Rgba::rgb(1, 2, 3), rustgis_map::Rgba::rgb(200, 100, 50));
    l.renderer = rustgis_map::Renderer::Single(sym);
    s.run("share.webStyle", &json!({"layer": ways, "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let line = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "line").unwrap();
    assert_eq!(line["paint"]["line-color"], json!(sym.stroke.hex()));
    // By expression, a line's rest with a fill but no stroke draws nothing: the first class's.
    let mut ds = rustgis_data::Dataset::new(
        "kinds",
        rustgis_data::GeometryType::Polyline,
        vec![rustgis_data::Field::new("k", rustgis_data::FieldType::Text)],
    );
    ds.push(
        Some(rustgis_data::Geometry::Line(vec![vec![rustgis_data::Coord::new(0.0, 0.0), rustgis_data::Coord::new(1.0, 1.0)]])),
        vec![rustgis_data::Value::Text("a".into())],
    );
    let kinds = s.map_mut().add_dataset(ds);
    s.run("layer.symbology", &json!({"layer": kinds, "type": "unique", "expression": "k || 'x'"})).unwrap();
    let l = s.map_mut().layer_mut(kinds).unwrap();
    let rustgis_map::Renderer::Unique { other, classes, .. } = &mut l.renderer else { panic!() };
    (other.fill, other.stroke) = (rustgis_map::Rgba::rgb(1, 2, 3), rustgis_map::Rgba::new(0, 0, 0, 0));
    let first = classes[0].1.stroke.hex();
    s.run("share.webStyle", &json!({"layer": kinds, "path": path.display().to_string()})).unwrap();
    let style: Value = serde_json::from_str(&std::fs::read_to_string(&path).unwrap()).unwrap();
    let line = style["layers"].as_array().unwrap().iter().find(|l| l["type"] == "line").unwrap();
    assert_eq!(line["paint"]["line-color"], json!(first));
    std::fs::remove_dir_all(&dir).ok();
    // Deleting a field it reads: a single symbol, as for a renderer on that field, and said.
    let mark = s.notice_mark();
    let rustgis_map::Renderer::Unique { classes, .. } = &s.map().layer_by_name("Cities").unwrap().renderer else { panic!() };
    let first_fill = classes[0].1.fill;
    s.run("edit.deleteField", &json!({"layer": "Cities", "field": "pop_max"})).unwrap();
    let rustgis_map::Renderer::Single(drawn) = &s.map().layer_by_name("Cities").unwrap().renderer else { panic!() };
    assert_eq!(drawn.fill, first_fill, "drawn with the first class's symbol");
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("drawn with a single symbol")), "{:?}", s.notices_since(mark));
    // A field nothing draws by goes without a word about the symbols.
    let mark = s.notice_mark();
    s.run("edit.deleteField", &json!({"layer": "Cities", "field": "name"})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("single symbol")), "{:?}", s.notices_since(mark));
}

#[test]
fn qgis_measures_in_project_units_are_left_out() {
    // QGIS's $area is in the project's units, which aren't read: left out, noted, not read as m².
    let mut s = world();
    let qml = |filter: &str| {
        format!(
            r#"<qgis version="3.40.0"><renderer-v2 type="RuleRenderer"><rules key="r">
            <rule filter="{filter}" symbol="0" label="Big"/><rule filter="&quot;pop_est&quot; &gt; 5" symbol="0" label="Kept"/></rules>
            <symbols><symbol type="fill" name="0"><layer class="SimpleFill" enabled="1"/></symbol></symbols></renderer-v2></qgis>"#
        )
    };
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": qml("$area &gt; 2")})).unwrap();
    let said: Vec<&str> = r["notes"].as_array().unwrap().iter().filter_map(|n| n["text"].as_str()).collect();
    assert!(said.iter().any(|n| n.contains("the rule \"Big\"") && n.contains("project's units")), "{said:?}");
    // Named only in quotes, it is text: the rule reads.
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": qml("name &lt;&gt; '$area'")})).unwrap();
    assert!(!r["notes"].to_string().contains("project's units"), "{r}");
}

/// A QGIS project's annotation layers come in as graphics layers, taken to longitude/latitude,
/// the main one on top; a picture is read from its file and fitted to its aspect.
#[test]
fn qgis_annotation_layers_import_as_graphics_layers() {
    let mut s = world();
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../map/testdata/qgis/generated/qgs/annotations-styled.qgs");
    let notes =
        |r: &serde_json::Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    let r = s.run("project.importQgis", &json!({"path": path.to_string_lossy()})).unwrap();
    assert_eq!(r["layers"], json!(["styled annotations", "Annotations"]), "{r}");
    // The main annotation layer on top, both graphics layers.
    let names: Vec<&str> = s.map().layers.iter().map(|l| l.name.as_str()).collect();
    assert_eq!(names, ["Annotations", "styled annotations"]);
    let l = s.map().layer_by_name("styled annotations").unwrap();
    assert!(l.graphics);
    let ds = &l.dataset;
    let row = (0..ds.features.len()).find(|r| rustgis_map::graphics::label(ds, *r) == Some("right, bold, red")).unwrap();
    assert!(rustgis_map::graphics::bold(ds, row));
    // Taken from Swiss LV95 to longitude/latitude (Winterthur).
    let Some(rustgis_data::Geometry::Point(c)) = &ds.features[row].geometry else { panic!() };
    assert!((c.x - 8.73).abs() < 0.02 && (c.y - 47.5).abs() < 0.02, "{c:?}");
    // The picture, read from its file and fitted to its 2:1 aspect.
    let pic = (0..ds.features.len()).find(|r| rustgis_map::graphics::kind(ds, *r) == "picture").unwrap();
    let image = ds.field_index("image").map(|fi| ds.value(pic, fi).clone());
    assert!(matches!(image, Some(rustgis_data::Value::Text(t)) if !t.is_empty()));
    let e = ds.features[pic].geometry.as_ref().unwrap().extent();
    let ratio = (e.max_x - e.min_x) * (47.5f64).to_radians().cos() / (e.max_y - e.min_y);
    assert!((ratio - 2.0).abs() < 0.1, "{ratio}");
    assert!(notes(&r).iter().any(|n| n.contains("an SVG picture annotation")), "{:?}", notes(&r));

    // Given as text with no folder: the relative picture is noted, the rest comes in.
    let text = std::fs::read_to_string(&path).unwrap();
    let r = s.run("project.importQgis", &json!({"text": text})).unwrap();
    assert!(
        notes(&r)
            .iter()
            .any(|n| n.starts_with("a picture annotation's picture, which doesn't read (the first: ../data/picture.png, relative")),
        "{:?}",
        notes(&r)
    );
    let l = s.map().layer_by_name("styled annotations").unwrap();
    assert!((0..l.dataset.features.len()).all(|r| rustgis_map::graphics::kind(&l.dataset, r) != "picture"));
    let texts = (0..l.dataset.features.len()).filter(|r| rustgis_map::graphics::label(&l.dataset, *r).is_some()).count();
    assert_eq!(texts, 8, "the texts come in all the same");
}

/// A QGIS style's raster image markers draw their PNG or JPEG file, read from the style's folder;
/// one that isn't a PNG, JPEG or SVG, doesn't open or is past what a marker keeps is a circle, noted.
#[test]
#[cfg(not(target_arch = "wasm32"))]
fn qgis_raster_image_markers_read_their_files_from_the_style_folder() {
    use base64::Engine;
    use rustgis_map::{Marker, Picture};
    // Removed however the test ends.
    struct Dir(std::path::PathBuf);
    impl Drop for Dir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    let guard = Dir(std::env::temp_dir().join(format!("rustgis-qgis-raster-markers-{}", std::process::id())));
    let dir = guard.0.clone();
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(dir.join("pins")).unwrap();
    let image = image::RgbImage::from_pixel(8, 4, image::Rgb([200, 30, 30]));
    image.save(dir.join("pins/pin.png")).unwrap();
    image.save(dir.join("pins/pin.jpg")).unwrap();
    image.save(dir.join("pins/pin.gif")).unwrap();
    // An SVG goes through the same check as `layer.marker`, so it draws too.
    std::fs::write(
        dir.join("pins/pin.svg"),
        r##"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 8 4"><rect width="8" height="4" fill="#c81e1e"/></svg>"##,
    )
    .unwrap();
    // Past the 2 MiB of base64 a marker keeps (1.5 MiB of file); its start a PNG's.
    let mut big = std::fs::read(dir.join("pins/pin.png")).unwrap();
    big.resize(1600 << 10, 0);
    std::fs::write(dir.join("pins/big.png"), big).unwrap();
    // A few kilobytes, past the pixels a marker's image takes.
    std::fs::write(dir.join("pins/many.png"), too_many_pixels_png()).unwrap();
    let qml = |file: &str| {
        format!(
            r#"<qgis version="4.2.3"><renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1">
            <layer class="RasterMarker" enabled="1"><Option type="Map"><Option name="imageFile" value="{file}"/><Option name="size" value="6"/>
            <Option name="size_unit" value="Point"/></Option></layer></symbol></symbols></renderer-v2></qgis>"#
        )
    };
    let notes =
        |r: &serde_json::Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    let mut s = world();
    let marker = |s: &Session| s.map().layer_by_name("Cities").unwrap().symbol(0).marker;
    for file in ["./pins/pin.png", "pins/pin.jpg", "pins/pin.svg"] {
        let path = dir.join("pins.qml");
        std::fs::write(&path, qml(file)).unwrap();
        let r = s.run("style.importQgis", &json!({"layer": "Cities", "path": path.to_string_lossy()})).unwrap();
        let b64 = base64::engine::general_purpose::STANDARD.encode(std::fs::read(dir.join(file)).unwrap());
        assert_eq!(marker(&s), Marker::Picture(Picture::new(&b64)), "{file}");
        assert!(notes(&r).is_empty(), "{file}: {:?}", notes(&r));
    }
    for (file, note) in [
        ("pins/pin.gif", "raster image markers whose image isn't a PNG, JPEG or SVG RustGIS reads, drawn as circles"),
        ("pins/gone.png", "raster image markers whose image file doesn't open, drawn as circles"),
        ("pins/big.png", "raster image markers whose image is past 2 MiB of base64, drawn as circles"),
        ("pins/many.png", "raster image markers whose image has more pixels than 2048 × 2048, drawn as circles"),
    ] {
        let path = dir.join("pins.qml");
        std::fs::write(&path, qml(file)).unwrap();
        let r = s.run("style.importQgis", &json!({"layer": "Cities", "path": path.to_string_lossy()})).unwrap();
        assert_eq!(marker(&s), Marker::Circle, "{file}");
        assert_eq!(notes(&r), [note], "{file}");
    }
    // An empty file isn't an image.
    std::fs::write(dir.join("pins/empty.png"), b"").unwrap();
    let path = dir.join("pins.qml");
    std::fs::write(&path, qml("pins/empty.png")).unwrap();
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "path": path.to_string_lossy()})).unwrap();
    assert_eq!(notes(&r), ["raster image markers whose image isn't a PNG, JPEG or SVG RustGIS reads, drawn as circles"]);
    // A named pipe isn't opened: opening one waits for a writer, which would hold the import.
    #[cfg(unix)]
    if std::process::Command::new("mkfifo").arg(dir.join("pins/pipe.png")).status().is_ok_and(|s| s.success()) {
        let path = dir.join("pins.qml");
        std::fs::write(&path, qml("pins/pipe.png")).unwrap();
        let r = s.run("style.importQgis", &json!({"layer": "Cities", "path": path.to_string_lossy()})).unwrap();
        assert_eq!(notes(&r), ["raster image markers whose image file doesn't open, drawn as circles"]);
    } else {
        eprintln!("skipped the named pipe: no mkfifo");
    }
    // Embedded in the style, it needs no folder.
    let b64 = base64::engine::general_purpose::STANDARD.encode(std::fs::read(dir.join("pins/pin.png")).unwrap());
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(&format!("base64:{b64}"))})).unwrap();
    assert_eq!(marker(&s), Marker::Picture(Picture::new(&b64)));
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    // An import reads at most so many bytes of images (1 KiB in tests), those that don't draw too:
    // of three of 600 characters that aren't images, the third isn't read.
    let junk = |c: char| {
        format!(
            r#"<layer class="RasterMarker" enabled="1"><Option type="Map"><Option name="imageFile" value="base64:{}"/></Option></layer>"#,
            c.to_string().repeat(600)
        )
    };
    let three = format!(
        r#"<qgis version="4.2.3"><renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1">{}{}{}</symbol></symbols></renderer-v2></qgis>"#,
        junk('A'),
        junk('B'),
        junk('C')
    );
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": three})).unwrap();
    let mut said: Vec<(String, u64)> =
        r["notes"].as_array().unwrap().iter().map(|n| (n["text"].as_str().unwrap().to_string(), n["count"].as_u64().unwrap())).collect();
    said.sort();
    assert_eq!(
        said,
        [
            ("raster image markers past the bytes of images an import reads, drawn as circles".to_string(), 1),
            ("raster image markers whose image isn't a PNG, JPEG or SVG RustGIS reads, drawn as circles".to_string(), 2),
        ]
    );
    // A file past what a marker keeps is charged for what was read of it: two take the budget.
    for name in ["big2.png", "big3.png"] {
        std::fs::copy(dir.join("pins/big.png"), dir.join("pins").join(name)).unwrap();
    }
    let file = |f: &str| {
        format!(
            r#"<layer class="RasterMarker" enabled="1"><Option type="Map"><Option name="imageFile" value="pins/{f}"/></Option></layer>"#
        )
    };
    let path = dir.join("pins.qml");
    std::fs::write(
        &path,
        format!(
            r#"<qgis version="4.2.3"><renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1">{}{}{}</symbol></symbols></renderer-v2></qgis>"#,
            file("big.png"),
            file("big2.png"),
            file("big3.png")
        ),
    )
    .unwrap();
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "path": path.to_string_lossy()})).unwrap();
    let mut said = notes(&r);
    said.sort();
    assert_eq!(
        said,
        [
            "raster image markers past the bytes of images an import reads, drawn as circles",
            "raster image markers whose image is past 2 MiB of base64, drawn as circles",
        ]
    );
    // A file that doesn't open is charged nothing: an image after it still reads.
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let locked = dir.join("pins/locked.png");
        std::fs::copy(dir.join("pins/big.png"), &locked).unwrap();
        std::fs::set_permissions(&locked, std::fs::Permissions::from_mode(0o000)).unwrap();
        // Run as root, it opens anyway.
        if std::fs::File::open(&locked).is_err() {
            std::fs::write(
                &path,
                format!(
                    r#"<qgis version="4.2.3"><renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1">{}{}</symbol></symbols></renderer-v2></qgis>"#,
                    file("locked.png"),
                    file("pin.png")
                ),
            )
            .unwrap();
            let r = s.run("style.importQgis", &json!({"layer": "Cities", "path": path.to_string_lossy()})).unwrap();
            assert_eq!(notes(&r), ["raster image markers whose image file doesn't open, drawn as circles"]);
        } else {
            eprintln!("skipped the unopenable file: it opens as this user");
        }
    }
}

/// A QGIS style's file and its raster image markers' images are read on a thread before the
/// command lands (#2620): the landing needs neither file, says what the inline import says, can be
/// undone, and a style read for a layer that was renamed meanwhile is refused. A cancelled read
/// changes nothing.
#[test]
#[cfg(not(target_arch = "wasm32"))]
fn qgis_style_import_reads_its_files_ahead() {
    use cancellation::contents;
    use rustgis_analysis::control::Control;
    use rustgis_map::Marker;
    // Removed however the test ends.
    struct Dir(std::path::PathBuf);
    impl Drop for Dir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    let guard = Dir(std::env::temp_dir().join(format!("rustgis-qgis-style-ahead-{}", std::process::id())));
    let dir = guard.0.clone();
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(dir.join("pins")).unwrap();
    image::RgbImage::from_pixel(8, 4, image::Rgb([200, 30, 30])).save(dir.join("pins/pin.png")).unwrap();
    std::fs::write(dir.join("pins/pin.gif"), b"GIF89a").unwrap();
    let qml = |files: &[&str]| {
        let layers: String = files
            .iter()
            .map(|f| {
                format!(
                    r#"<layer class="RasterMarker" enabled="1"><Option type="Map"><Option name="imageFile" value="{f}"/><Option name="size" value="6"/></Option></layer>"#
                )
            })
            .collect();
        format!(
            r#"<qgis version="4.2.3"><renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1">{layers}</symbol></symbols></renderer-v2></qgis>"#
        )
    };
    let notes = |r: &Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    let marker = |s: &Session| s.map().layer_by_name("Cities").unwrap().symbol(0).marker;
    let path = dir.join("pins.qml");
    let p = json!({"layer": "Cities", "path": path.to_string_lossy()});
    // A clean style says nothing; a lossy one says what the inline import says, as the same notes.
    for (files, said) in [(&["pins/pin.png"][..], 0), (&["pins/pin.gif"][..], 1)] {
        std::fs::write(&path, qml(files)).unwrap();
        let mut inline = world();
        let inline_notes = notes(&inline.run("style.importQgis", &p).unwrap());
        assert_eq!(inline_notes.len(), said, "{files:?}: {inline_notes:?}");
        let mut s = world();
        let before = marker(&s);
        let ahead = crate::cmd::reads::read_ahead(&mut s, "style.importQgis", &p).unwrap();
        assert!(ahead.reads(), "{files:?}: the style is read ahead");
        let read = ahead.run(&Control::stoppable()).unwrap();
        // Neither file is needed once read.
        std::fs::remove_file(&path).unwrap();
        std::fs::remove_file(dir.join("pins/pin.png")).unwrap();
        let r = crate::cmd::reads::read_land(&mut s, read).unwrap();
        assert_eq!(notes(&r), inline_notes, "{files:?}");
        assert_eq!(marker(&s), marker(&inline), "{files:?}");
        s.run("edit.undo", &Value::Null).unwrap();
        assert_eq!(marker(&s), before, "{files:?}: undone");
        image::RgbImage::from_pixel(8, 4, image::Rgb([200, 30, 30])).save(dir.join("pins/pin.png")).unwrap();
    }
    assert!(matches!(marker(&world()), Marker::Circle));
    // Cancel: no change, and the read looked at Cancel.
    std::fs::write(&path, qml(&["pins/pin.png"])).unwrap();
    let mut s = world();
    let before = contents(&s.project);
    let control = Control::cancelled_once_started();
    let e = crate::cmd::reads::read_ahead(&mut s, "style.importQgis", &p).unwrap().run(&control).err().unwrap();
    assert!(e.contains("cancelled"), "{e}");
    assert!(control.looked() > 0, "never looks at Cancel");
    assert!(contents(&s.project) == before);
    // A Cancel that comes at any check (the file's, each image's, after the parse) is the cancelled
    // error, not a style with its image noted as skipped; read here under the same probe as well.
    let count = Control::cancelled_at_look(u64::MAX);
    crate::cmd::reads::read_ahead(&mut s, "style.importQgis", &p).unwrap().run(&count).unwrap();
    assert!(count.looked() >= 3, "the file, the image and the parse's end look: {}", count.looked());
    for n in 1..=count.looked() {
        let e = crate::cmd::reads::read_ahead(&mut s, "style.importQgis", &p).unwrap().run(&Control::cancelled_at_look(n)).err().unwrap();
        assert!(e.contains("cancelled"), "check {n}: {e}");
    }
    let here = Control::cancelled_at_look(u64::MAX);
    {
        let _probe = rustgis_analysis::control::install_progress(Some(here.clone()));
        s.run("style.importQgis", &p).unwrap();
    }
    s.run("edit.undo", &Value::Null).unwrap();
    assert!(here.looked() >= 3, "read here: {}", here.looked());
    for n in 1..=here.looked() {
        let _probe = rustgis_analysis::control::install_progress(Some(Control::cancelled_at_look(n)));
        let e = s.run("style.importQgis", &p).unwrap_err();
        assert!(e.contains("cancelled"), "check {n}, read here: {e}");
        assert!(contents(&s.project) == before, "check {n}");
    }
    // Renamed while it was read: refused, the layer as it was.
    let read = crate::cmd::reads::read_ahead(&mut s, "style.importQgis", &p).unwrap().run(&Control::stoppable()).unwrap();
    let id = s.layer_id(&p).unwrap();
    s.run("layer.rename", &json!({"layer": id, "name": "Towns"})).unwrap();
    let before = contents(&s.project);
    let e = crate::cmd::reads::read_land(&mut s, read).unwrap_err();
    assert!(e.contains("renamed while its style was read"), "{e}");
    assert!(contents(&s.project) == before);
}

/// Pictures are charged to an import's budget (1 KiB in tests) only once placed: pictures that
/// don't take to longitude and latitude leave it whole, and those past it are left out, noted.
#[test]
fn qgis_annotation_pictures_charge_the_budget_only_once_placed() {
    let mut s = world();
    let png =
        std::fs::read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../map/testdata/qgis/generated/data/picture.png")).unwrap();
    let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, png);
    let picture =
        |y: f64| format!(r#"<item type="picture" path="base64:{b64}" lockAspect="0" xMin="8" yMin="{y}" xMax="9" yMax="{}"/>"#, y + 1.0);
    // Ten pictures past the pole (more than the budget holds), then seven on the map: six fit.
    let items = format!("{}{}", picture(100.0).repeat(10), picture(47.0).repeat(7));
    let qgs = format!(
        r#"<qgis><projectCrs><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></projectCrs><projectlayers>
      <maplayer type="annotation"><id>a</id><layername>P</layername><items>{items}</items></maplayer></projectlayers></qgis>"#
    );
    let r = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let notes: Vec<String> = r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect();
    let l = s.map().layer_by_name("P").unwrap();
    let placed = (0..l.dataset.features.len()).filter(|r| rustgis_map::graphics::kind(&l.dataset, *r) == "picture").count();
    assert_eq!(placed, 1024 / b64.len(), "{notes:?}");
    assert!(notes.iter().any(|n| n.starts_with("10 annotations that don't take to longitude and latitude")), "{notes:?}");
    // One left out (7 − 6): "a picture annotation's picture past the …".
    assert!(notes.iter().any(|n| n.ends_with("picture past the 1 KiB of pictures an import takes")), "{notes:?}");
}

/// A text QGIS draws under a shape of its layer (a lower z) is drawn over it, as RustGIS draws a
/// layer's texts last: noted, with how many. A text on top, or a layer of texts only, isn't.
#[test]
fn qgis_annotation_texts_under_shapes_are_noted() {
    let mut s = world();
    let text = |z: i32| format!(r#"<item type="pointtext" text="t" x="8" y="47" zIndex="{z}"/>"#);
    let marker = |z: i32| format!(r#"<item type="marker" x="8" y="47" zIndex="{z}"/>"#);
    for (items, noted) in [
        (format!("{}{}{}", text(0), text(1), marker(2)), Some("2 annotation texts QGIS draws under other annotations")),
        (format!("{}{}", marker(2), text(0)), Some("an annotation text QGIS draws under other annotations")),
        (format!("{}{}", marker(0), text(1)), None),
        (format!("{}{}", text(0), text(1)), None),
    ] {
        let qgs = format!(
            r#"<qgis><projectCrs><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></projectCrs><projectlayers>
      <maplayer type="annotation"><id>a</id><layername>N</layername><items>{items}</items></maplayer></projectlayers></qgis>"#
        );
        let r = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
        let texts: Vec<&str> = r["notes"].as_array().unwrap().iter().filter_map(|n| n["text"].as_str()).collect();
        let said = texts.iter().find(|t| t.contains("QGIS draws under other annotations"));
        match noted {
            Some(part) => assert!(said.is_some_and(|t| t.contains(part)), "{items}: {texts:?}"),
            None => assert!(said.is_none(), "{items}: {texts:?}"),
        }
    }
}

/// An annotation layer's texts under a layer above that draws more than texts (here a marker)
/// are noted, as RustGIS draws them over it; the top layer's own texts, with nothing above, aren't.
#[test]
fn qgis_annotation_texts_under_layers_above_are_noted() {
    let mut s = world();
    let layer = |id: &str, items: &str| {
        format!(r#"<maplayer type="annotation"><id>{id}</id><layername>{id}</layername><items>{items}</items></maplayer>"#)
    };
    let text = r#"<item type="pointtext" text="t" x="8" y="47"/>"#;
    let marker = r#"<item type="marker" x="8" y="47"/>"#;
    // QGIS lists the top layer first.
    let qgs = format!(
        r#"<qgis><projectCrs><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></projectCrs><projectlayers>{}{}{}</projectlayers></qgis>"#,
        layer("top", &format!("{text}{text}")),
        layer("shapes", marker),
        layer("bottom", &format!("{text}{text}"))
    );
    let r = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let notes: Vec<(String, String)> = r["notes"]
        .as_array()
        .unwrap()
        .iter()
        .map(|n| (n["layer"].as_str().unwrap_or_default().to_string(), n["text"].as_str().unwrap().to_string()))
        .collect();
    let under = |l: &str| notes.iter().any(|(layer, t)| layer == l && t.contains("layers above draw over in QGIS"));
    assert!(under("bottom") && !under("top") && !under("shapes"), "{notes:?}");

    // The marker layer hidden: it covers nothing, and nothing is noted.
    let tree = r#"<layer-tree-group><layer-tree-layer id="top" checked="Qt::Checked"/><layer-tree-layer id="shapes" checked="Qt::Unchecked"/><layer-tree-layer id="bottom" checked="Qt::Checked"/></layer-tree-group>"#;
    let hidden = qgs.replace("<projectlayers>", &format!("{tree}<projectlayers>"));
    let r = s.run("project.importQgis", &json!({"text": hidden})).unwrap();
    let texts: Vec<&str> = r["notes"].as_array().unwrap().iter().filter_map(|n| n["text"].as_str()).collect();
    assert!(!texts.iter().any(|t| t.contains("layers above draw over in QGIS")), "{texts:?}");
}

/// A project's layer tree comes in as nested layer groups: each layer in its group with its own
/// box, the groups' boxes, open state and a group layer's opacity on the groups, the drawing
/// order kept (a group's own layers above and below a subgroup stay there). A web tile layer in a
/// group comes in outside it, noted.
#[test]
fn qgis_layer_tree_groups_import_as_layer_groups() {
    let dir = std::env::temp_dir().join(format!("rustgis-qgis-groups-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let point = r#"{"type":"FeatureCollection","features":[{"type":"Feature","properties":{},"geometry":{"type":"Point","coordinates":[8.7,47.5]}}]}"#;
    let layer = |id: &str| {
        std::fs::write(dir.join(format!("{id}.geojson")), point).unwrap();
        format!(
            r#"<maplayer type="vector"><id>{id}</id><datasource>./{id}.geojson</datasource><layername>{id}</layername><provider>ogr</provider></maplayer>"#
        )
    };
    let layers: String = ["e", "a", "b", "c", "d"].iter().map(|id| layer(id)).collect();
    let qgs = format!(
        r#"<qgis version="4.2.3"><layer-tree-group>
      <layer-tree-group checked="Qt::Checked" expanded="0" name="Outer">
        <layer-tree-layer checked="Qt::Checked" id="e"/>
        <layer-tree-group checked="Qt::Unchecked" expanded="1" name="Inner"><layer-tree-layer checked="Qt::Checked" id="a"/></layer-tree-group>
        <layer-tree-layer checked="Qt::Unchecked" id="b"/>
        <layer-tree-layer checked="Qt::Checked" id="t"/>
      </layer-tree-group>
      <layer-tree-layer checked="Qt::Checked" id="c"/>
      <layer-tree-group checked="Qt::Checked" expanded="1" groupLayer="gl" name="Drawn as one"><layer-tree-layer checked="Qt::Checked" id="d"/><layer-tree-layer checked="Qt::Checked" id="t2"/></layer-tree-group>
      <layer-tree-group checked="Qt::Checked" expanded="1" name="Empty"/>
    </layer-tree-group><projectlayers>{layers}
      <maplayer type="group" hasScaleBasedVisibilityFlag="1" minScale="50000" maxScale="1000"><id>gl</id><layername>Drawn as one</layername><layerOpacity>0.25</layerOpacity><blendMode>0</blendMode></maplayer>
      <maplayer type="raster"><id>t2</id><datasource>type=xyz&amp;url=https://tiles2.example/%7Bz%7D/%7Bx%7D/%7By%7D.png</datasource><layername>Tiles 2</layername><provider>wms</provider></maplayer>
      <maplayer type="raster"><id>t</id><datasource>type=xyz&amp;url=https://tiles.example/%7Bz%7D/%7Bx%7D/%7By%7D.png</datasource><layername>Tiles</layername><provider>wms</provider></maplayer>
    </projectlayers></qgis>"#
    );
    let mut s = world();
    let out = s.run("project.importQgis", &json!({"text": qgs, "dir": dir.display().to_string()})).unwrap();
    let m = s.map();
    let names: Vec<&str> = m.layers.iter().map(|l| l.name.as_str()).collect();
    assert_eq!(names, ["e", "a", "b", "c", "d"], "the tree's order, top first: {out}");
    let group = |name: &str| m.groups.iter().find(|g| g.name == name).unwrap_or_else(|| panic!("{name}: {out}"));
    let (outer, inner, one, empty) = (group("Outer"), group("Inner"), group("Drawn as one"), group("Empty"));
    assert_eq!((outer.visible, outer.expanded, outer.parent), (true, false, None));
    assert_eq!((inner.visible, inner.parent), (false, Some(outer.id)));
    assert_eq!((one.transparency, one.parent), (75.0, None));
    // Its visibility range, in RustGIS's scales.
    let q = rustgis_map::qgis::QGIS_SCALE;
    assert_eq!((one.min_scale, one.max_scale), (Some(50_000.0 * q), Some(1000.0 * q)));
    assert!(empty.children.is_empty(), "kept, as QGIS keeps it");
    let id = |name: &str| m.layer_by_name(name).unwrap().id;
    let visible = |name: &str| m.layer_by_name(name).unwrap().visible;
    assert_eq!(m.group_of(id("a")).map(|g| g.id), Some(inner.id));
    assert_eq!(m.group_of(id("b")).map(|g| g.id), Some(outer.id));
    assert_eq!(m.group_of(id("e")).map(|g| g.id), Some(outer.id));
    assert_eq!(m.group_of(id("c")).map(|g| g.id), None);
    assert_eq!(m.group_of(id("d")).map(|g| g.id), Some(one.id));
    // Its own box: a is checked in its unchecked group (the group hides it), b is unchecked.
    assert_eq!([visible("a"), visible("b"), visible("c"), visible("d")], [true, false, true, true]);
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    assert!(notes.contains("its place in the group Outer: a web tile layer, added outside the group"), "{notes}");
    assert!(notes.contains("its place in the group Drawn as one and the opacity of a group drawn as one holding it"), "{notes}");
    assert!(notes.contains("opacity of groups drawn as one (1: Drawn as one)"), "{notes}");
    assert!(!notes.contains("RustGIS doesn't read QGIS's group layers"), "{notes}");
    std::fs::remove_dir_all(&dir).ok();
}

/// A QGIS project's bookmarks come in at their places (turned as QGIS turns them), its relations
/// as relationships, its map's rotation as the bearing, and its layers' time settings as time
/// slider bindings, the slider left off as QGIS opens a project (every feature drawn).
#[test]
fn qgis_bookmarks_relations_rotation_and_time_import() {
    let dir = std::env::temp_dir().join(format!("rustgis-qgis-structure-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let file = |id: &str, props: &[&str]| {
        let features: Vec<String> = props
            .iter()
            .map(|p| format!(r#"{{"type":"Feature","properties":{p},"geometry":{{"type":"Point","coordinates":[8.5,47.4]}}}}"#))
            .collect();
        std::fs::write(dir.join(format!("{id}.geojson")), format!(r#"{{"type":"FeatureCollection","features":[{}]}}"#, features.join(",")))
            .unwrap();
    };
    file("parcels", &[r#"{"id":1}"#, r#"{"id":2}"#]);
    file("owners", &[r#"{"pid":1}"#, r#"{"pid":2}"#]);
    file("Owners", &[r#"{"pid":1,"when":"soon"}"#]);
    // Two date fields: QGIS's is the second.
    file("events", &[r#"{"made":"2019-01-01","when":"2020-03-01","note":"a"}"#, r#"{"made":"2019-02-01","when":"2021-05-01","note":"b"}"#]);
    // A file of several layers (waypoints, tracks, track points), each with a name field: QGIS's
    // layer is one of them (`layerid`).
    std::fs::write(
        dir.join("trip.gpx"),
        r#"<gpx version="1.1" creator="t" xmlns="http://www.topografix.com/GPX/1/1"><wpt lat="47.4" lon="8.5"><name>a</name></wpt><trk><name>b</name><trkseg><trkpt lat="47.4" lon="8.5"/><trkpt lat="47.5" lon="8.6"/></trkseg></trk></gpx>"#,
    )
    .unwrap();
    let layer = |id: &str, temporal: &str| {
        format!(
            r#"<maplayer type="vector"><id>{id}_1</id><datasource>./{id}.geojson</datasource><layername>{id}</layername><provider>ogr</provider>{temporal}</maplayer>"#
        )
    };
    let on = |field: &str| format!(r#"<temporal enabled="1" mode="1" startField="{field}" accumulate="0" limitMode="0"/>"#);
    let layers = [layer("parcels", &on("nope")), layer("owners", ""), layer("events", &on("when")), layer("Owners", &on("when"))].concat()
        + r#"<maplayer type="vector"><id>trip_1</id><datasource>./trip.gpx|layerid=1</datasource><layername>trip</layername><provider>ogr</provider></maplayer>"#;
    let qgs = format!(
        r#"<qgis version="4.2.3">
      <projectCrs><spatialrefsys><authid>EPSG:3857</authid></spatialrefsys></projectCrs>
      <mapcanvas name="theMapCanvas"><extent><xmin>930000</xmin><ymin>6000000</ymin><xmax>960000</xmax><ymax>6030000</ymax></extent><rotation>15</rotation></mapcanvas>
      <projectlayers>{layers}</projectlayers>
      <relations>
        <relation id="own" name="Owners of parcel" referencedLayer="parcels_1" referencingLayer="owners_1" strength="Association"><fieldRef referencedField="id" referencingField="pid"/></relation>
        <relation id="gone" name="To nowhere" referencedLayer="parcels_1" referencingLayer="missing_1" strength="Association"><fieldRef referencedField="id" referencingField="pid"/></relation>
        <relation id="trip" name="Trip names" referencedLayer="trip_1" referencingLayer="owners_1" strength="Association"><fieldRef referencedField="name" referencingField="pid"/></relation>
        <relation id="points" name="Trip points" referencedLayer="trip_1" referencingLayer="owners_1" strength="Association"><fieldRef referencedField="points" referencingField="pid"/></relation>
        <relation id="self" name="Trip self" referencedLayer="trip_1" referencingLayer="trip_1" strength="Association"><fieldRef referencedField="points" referencingField="track"/></relation>
      </relations>
      <Bookmarks>
        <Bookmark extent="Polygon ((8.4 47.3, 8.6 47.3, 8.6 47.45, 8.4 47.45, 8.4 47.3))" group="" id="a" name="Zurich" rotation="0"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
        <Bookmark extent="Polygon ((900000 5900000, 1000000 5900000, 1000000 6000000, 900000 6000000, 900000 5900000))" group="" id="b" name="Web" rotation="30"/>
        <Bookmark extent="Polygon ((2680000 1240000, 2700000 1240000, 2700000 1260000, 2680000 1260000, 2680000 1240000))" group="" id="c" name="Zurich" rotation="0"><spatialrefsys><authid>EPSG:2056</authid></spatialrefsys></Bookmark>
        <Bookmark extent="Polygon ((1 1, 2 1, 2 2, 1 2, 1 1))" group="" id="d" name="Odd" rotation="0"><spatialrefsys><authid>EPSG:999999</authid></spatialrefsys></Bookmark>
        <Bookmark extent="Polygon ((-400 0, 10 0, 10 10, -400 10, -400 0))" group="" id="e" name="Beyond" rotation="0"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      </Bookmarks>
    </qgis>"#
    );
    let mut s = world();
    let out = s.run("project.importQgis", &json!({"text": qgs, "dir": dir.display().to_string()})).unwrap();
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    let m = s.map();
    let turned = |bearing: f64, by: f64| (bearing + by).rem_euclid(360.0).min((-(bearing + by)).rem_euclid(360.0)) < 1e-9;
    // The map turned 15° clockwise: north 15° east of up.
    assert!(turned(m.camera.bearing, 15.0), "{}", m.camera.bearing);
    let names: Vec<&str> = m.bookmarks.iter().map(|b| b.name.as_str()).collect();
    assert_eq!(names, ["Zurich", "Web", "Zurich 2"], "{notes}");
    let centre = |i: usize| m.to_lonlat(m.bookmarks[i].camera.center).unwrap();
    let (zurich, lv95) = (centre(0), centre(2));
    assert!((zurich.x - 8.5).abs() < 1e-6 && (zurich.y - 47.375).abs() < 0.01, "{zurich:?}");
    // LV95 2690000/1250000 is 8.631°E 47.395°N.
    assert!((lv95.x - 8.631).abs() < 0.001 && (lv95.y - 47.395).abs() < 0.001, "{lv95:?}");
    assert!(turned(m.bookmarks[1].camera.bearing, 30.0), "{}", m.bookmarks[1].camera.bearing);
    assert!(turned(m.bookmarks[0].camera.bearing, 0.0));
    // Fitted facing north whatever came before (the map turned 15°, the bookmark not): the zoom
    // a north-up map fitting the same place takes.
    let mut north = rustgis_map::Map::new("north");
    north.fit_lonlat(&rustgis_geom::Extent::new(8.4, 47.3, 8.6, 47.45), s.view_size.0, s.view_size.1);
    assert!(
        (m.bookmarks[0].camera.res - north.camera.res).abs() < 1e-6 * north.camera.res,
        "{} {}",
        m.bookmarks[0].camera.res,
        north.camera.res
    );
    assert!(notes.contains("its bookmarks in a coordinate system RustGIS can't read (1: Odd)"), "{notes}");
    assert!(notes.contains("its bookmarks whose place lies outside their coordinate system's area (1: Beyond)"), "{notes}");
    let rels = &m.editing.relationships;
    assert_eq!(rels.len(), 2, "{notes}");
    let r = &rels[0];
    assert_eq!(
        (r.name.as_str(), r.origin.as_str(), r.origin_key.as_str(), r.destination.as_str(), r.destination_key.as_str()),
        // Another layer's name differs only by case: layers' names are kept apart, the relation
        // following the one renamed.
        ("Owners of parcel", "parcels", "id", "owners (2)", "pid")
    );
    assert!(notes.contains("its relations between layers that didn't come in or haven't the fields (1: To nowhere)"), "{notes}");
    // Its layer came in as two with the field: not related to either, and said.
    assert!(
        notes
            .contains("its relations to a layer that came in as several tables with the field, any of which it could mean (1: Trip names)"),
        "{notes}"
    );
    // A relation of it to itself whose fields are in two of its tables (tracks and track points):
    // not made, and said why.
    assert!(notes.contains("whose two fields are in two of the tables it came in as, neither holding both (1: Trip self)"), "{notes}");
    // Of its tables, only the tracks have `points` (routes have it too, but this file has none):
    // related to them, said to be a guess.
    assert_eq!((rels[1].name.as_str(), rels[1].origin_key.as_str()), ("Trip points", "points"));
    assert!(notes.contains("related to the one table with the field, QGIS's own not being known (1: Trip points)"), "{notes}");
    assert!(!notes.contains("not being known (2"), "{notes}");
    // Bound, the slider off: every feature shows, as QGIS opens a project.
    let events = m.layer_by_name("events").unwrap();
    assert_eq!(events.time.as_ref().map(|t| t.field.as_str()), Some("when"));
    assert!(m.time.is_none());
    assert!(events.time.as_ref().unwrap().keeps(&events.dataset).is_none());
    assert!(m.layer_by_name("parcels").unwrap().time.is_none());
    assert!(notes.contains("its time settings, by the field nope, which the layer hasn't"), "{notes}");
    assert!(notes.contains("its time settings, by the field when, none of whose values read as dates"), "{notes}");
    // Related Data selects through it.
    let id = s.map().layer_by_name("parcels").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().selection = vec![0];
    s.run("data.related", &json!({"name": "Owners of parcel"})).unwrap();
    assert_eq!(s.map().layer_by_name("owners (2)").unwrap().selection.len(), 1);
    // Turned on for it (as the Time Slider button does), the slider keeps its field and spans its
    // dates.
    let on = s.run("time.bind", &json!({"layer": "events"})).unwrap();
    assert_eq!(on["field"], "when", "{on}");
    assert_eq!((&on["start"], &on["end"]), (&json!("2020-03"), &json!("2021-05")), "{on}");
    // Bound to a field with no dates, it takes one that has them, as before.
    let id = s.map().layer_by_name("events").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().time = Some(rustgis_map::time::TimeBinding::new("note"));
    let on = s.run("time.bind", &json!({"layer": "events"})).unwrap();
    assert_ne!(on["field"], "note", "{on}");
    std::fs::remove_dir_all(&dir).ok();
}

/// QGIS's other sources come in as RustGIS reads them: a GPX file's tracks, a memory layer empty
/// with its fields (as QGIS opens it), a virtual layer on another layer as that layer with the
/// filters of both, vector tiles (by XYZ address and with a MapLibre style) with their style
/// noted, and database tables noted with a saved connection to log in to, made once a database
/// and never with a password. What isn't read is noted.
#[test]
fn qgis_sources_import_as_their_layers() {
    let dir = std::env::temp_dir().join(format!("rustgis-qgis-sources-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(
        dir.join("trip.gpx"),
        r#"<gpx version="1.1" creator="t" xmlns="http://www.topografix.com/GPX/1/1"><wpt lat="47.4" lon="8.5"><name>a</name></wpt><trk><name>b</name><trkseg><trkpt lat="47.4" lon="8.5"/><trkpt lat="47.5" lon="8.6"/></trkseg></trk></gpx>"#,
    )
    .unwrap();
    let point = |kind: &str, value: i32| {
        format!(
            r#"{{"type":"Feature","properties":{{"kind":"{kind}","value":{value}}},"geometry":{{"type":"Point","coordinates":[8.5,47.4]}}}}"#
        )
    };
    let features = [point("x", 1), point("x", 30), point("y", 30)].join(",");
    std::fs::write(dir.join("pts.geojson"), format!(r#"{{"type":"FeatureCollection","features":[{features}]}}"#)).unwrap();
    let layer = |id: &str, kind: &str, provider: &str, source: &str| {
        format!(
            r#"<maplayer type="{kind}"><id>{id}</id><datasource>{source}</datasource><layername>{id}</layername><provider>{provider}</provider></maplayer>"#
        )
    };
    let layers = [
        layer("track", "vector", "gpx", "./trip.gpx?type=track"),
        layer("scratch", "vector", "memory", "memory?geometry=LineString&amp;crs=EPSG:2056&amp;field=name:string(20,0)&amp;field=at:time(0,0)"),
        layer("pts", "vector", "ogr", "./pts.geojson|subset=\"kind\" = 'x'"),
        layer("big", "vector", "virtual", "?layer_ref=pts:p&amp;query=SELECT%20*%20FROM%20p%20WHERE%20value%20%3E%2020"),
        layer("counts", "vector", "virtual", "?layer_ref=pts:p&amp;query=SELECT%20kind,%20count(*)%20FROM%20p%20GROUP%20BY%20kind"),
        layer("tiles", "vector-tile", "xyzvectortiles", "type=xyz&amp;url=https://e.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.pbf&amp;zmax=14&amp;zmin=0"),
        layer("towns", "vector", "postgres", "dbname='gis' host=db.invalid port=5432 user='me' password='secret' sslmode=disable sslrootcert='/k/ca.pem' aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa=1 key='id' srid=2056 type=Point table=\"public\".\"towns\" (geom)"),
        layer("roads", "vector", "postgres", "dbname='gis' host=db.invalid port=5432 user='me' password='secret' sslmode=disable table=\"public\".\"roads\" (geom) sql=\"value\" &gt; 20"),
        layer("sites", "vector", "mssql", "dbname='gis' host=sql.invalid\\main user='me' password='secret' table=\"dbo\".\"sites\" (geom)"),
        layer("named", "vector", "postgres", "service='prod' sslrootcert='/k/x.pem' table=\"public\".\"x\" (geom)"),
        layer("bag", "vector", "memory", "GeometryCollection?crs=EPSG:4326&amp;field=a:integer"),
        layer("served", "vector", "postgres", "service='prod' host=db.invalid table=\"public\".\"y\" (geom)"),
        layer("escaped", "vector", "postgres", r"dbname='gis' host=db.invalid port=5432 user='me' password='p4ss\' table=x' sslmode=disable table=public.z"),
        layer("web mbtiles", "vector-tile", "mbtilesvectortiles", "type=mbtiles&amp;url=https://e.invalid/t.mbtiles"),
        layer("share", "vector-tile", "xyzvectortiles", "type=xyz&amp;url=file://server/share/t.pmtiles"),
        layer("gone", "vector-tile", "mbtilesvectortiles", "type=mbtiles&amp;url=.%2Fnope.mbtiles"),
        layer("look one", "vector-tile", "xyzvectortiles", "type=xyz&amp;url=https://same.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.pbf"),
        layer("look two", "vector-tile", "xyzvectortiles", "type=xyz&amp;url=https://same.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.pbf"),
        // Two layers of one name (each with its own id, as QGIS writes them) on the same tiles.
        layer("osm_1", "raster", "wms", "type=xyz&amp;url=https://twin.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.png").replace("<layername>osm_1<", "<layername>osm<"),
        layer("osm_2", "raster", "wms", "type=xyz&amp;url=https://twin.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.png").replace("<layername>osm_2<", "<layername>osm<"),
        // A memory layer with Z values and a repeated field name; virtual layers on a name
        // none of their sources has, on a layer id the project lacks, and on the latter.
        layer("zm", "vector", "memory", "PointZ?crs=EPSG:4326&amp;field=a:string&amp;field=A:integer"),
        layer("lost", "vector", "virtual", "?layer=ogr:.%2Fpts.geojson:p&amp;query=SELECT%20*%20FROM%20nosuch"),
        layer("orphan", "vector", "virtual", "?layer_ref=gone_1:g&amp;query=SELECT%20*%20FROM%20g"),
        layer("on orphan", "vector", "virtual", "?layer_ref=orphan:o&amp;query=SELECT%20*%20FROM%20o"),
        // On a virtual layer on a memory layer: not a ring, not too deep.
        layer("on mem", "vector", "virtual", "?layer_ref=scratch:s&amp;query=SELECT%20*%20FROM%20s"),
        layer("on on mem", "vector", "virtual", "?layer_ref=on mem:o&amp;query=SELECT%20*%20FROM%20o"),
        // A project layer of a GeoPackage named without a layer, and a virtual layer on it.
        layer("whole gpkg", "vector", "ogr", "./sample.gpkg"),
        layer("on whole gpkg", "vector", "virtual", "?layer_ref=whole gpkg:w&amp;query=SELECT%20*%20FROM%20w"),
        layer("ring a", "vector", "virtual", "?layer_ref=ring b:b&amp;query=SELECT%20*%20FROM%20b"),
        layer("deep 0", "vector", "virtual", "?layer_ref=deep 1:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 1", "vector", "virtual", "?layer_ref=deep 2:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 2", "vector", "virtual", "?layer_ref=deep 3:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 3", "vector", "virtual", "?layer_ref=deep 4:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 4", "vector", "virtual", "?layer_ref=deep 5:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 5", "vector", "virtual", "?layer_ref=deep 6:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 6", "vector", "virtual", "?layer_ref=deep 7:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 7", "vector", "virtual", "?layer_ref=deep 8:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 8", "vector", "virtual", "?layer_ref=deep 9:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 9", "vector", "virtual", "?layer_ref=deep 10:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 10", "vector", "virtual", "?layer_ref=deep 11:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("deep 11", "vector", "virtual", "?layer_ref=pts:p&amp;query=SELECT%20*%20FROM%20p"),
        layer("ring b", "vector", "virtual", "?layer_ref=ring a:a&amp;query=SELECT%20*%20FROM%20a"),
        // A raster PMTiles archive: read as an archive, not as a tile address.
        layer("raster archive", "raster", "wms", "type=xyz&amp;url=.%2Fnone.pmtiles"),
        // A network share's archive, by its Windows path.
        layer("unc share", "vector-tile", "mbtilesvectortiles", "type=mbtiles&amp;url=%5C%5Cserver%5Cshare%5Ct.mbtiles"),
        // Two tile layers on the same tiles, of the name of a file layer added before them.
        layer("dup_1", "raster", "wms", "type=xyz&amp;url=https://dup.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.png").replace("<layername>dup_1<", "<layername>dup<"),
        layer("dup_2", "raster", "wms", "type=xyz&amp;url=https://dup.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.png").replace("<layername>dup_2<", "<layername>dup<"),
        layer("dup_3", "vector", "gpx", "./trip.gpx?type=track").replace("<layername>dup_3<", "<layername>dup<"),
    ]
    .concat();
    let qgs = format!(r#"<qgis version="4.2.3"><projectlayers>{layers}</projectlayers></qgis>"#);
    let mut s = world();
    // A tile layer of the user's own on the twin tiles stays: the import makes a map of its own.
    s.run("map.addTiles", &json!({"url": "https://twin.invalid/{z}/{x}/{y}.png", "name": "mine", "overlay": true})).unwrap();
    let mine = s.project.active_map;
    let before = s.connections.connections.len();
    let out = s.run("project.importQgis", &json!({"text": qgs, "dir": dir.display().to_string()})).unwrap();
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    let m = s.map();
    // The GPX file's tracks alone.
    let track = m.layer_by_name("track").unwrap();
    assert_eq!((track.dataset.geometry_type, track.dataset.features.len()), (rustgis_data::GeometryType::Polyline, 1), "{notes}");
    assert!(m.layers.iter().all(|l| !l.name.contains("waypoints")), "{notes}");
    // Empty, with its fields; the one of a kind RustGIS hasn't as text.
    let scratch = m.layer_by_name("scratch").unwrap();
    let fields: Vec<(&str, rustgis_data::FieldType)> = scratch.dataset.fields.iter().map(|f| (f.name.as_str(), f.ty)).collect();
    assert_eq!(fields, [("name", rustgis_data::FieldType::Text), ("at", rustgis_data::FieldType::Text)]);
    assert!(scratch.dataset.features.is_empty() && scratch.dataset.geometry_type == rustgis_data::GeometryType::Polyline);
    assert!(notes.contains("its fields of kinds RustGIS hasn't, as text (1: at (time))"), "{notes}");
    assert!(scratch.dataset.crs.is_some(), "{notes}");
    // The virtual layer: its base layer's file with both filters, one feature of three.
    let big = m.layer_by_name("big").unwrap();
    let keeps = |l: &rustgis_map::Layer| {
        let q = rustgis_data::query::parse(l.definition_query.as_deref().unwrap(), &l.dataset).unwrap();
        (0..l.dataset.features.len()).filter(|&i| rustgis_data::query::eval(&q, &l.dataset, i)).count()
    };
    assert_eq!(keeps(big), 1, "{:?}", big.definition_query);
    assert!(notes.contains("the virtual layer `SELECT kind, count(*) FROM p GROUP BY kind`"), "{notes}");
    assert!(m.layer_by_name("counts").is_none());
    // Vector tiles, their style noted.
    assert!(m.tiles.iter().any(|t| t.name == "tiles"), "{notes}");
    assert!(notes.contains("its vector tile style: drawn in RustGIS's colours"), "{notes}");
    // One saved connection a database (two tables of one PostGIS database), none for a service
    // name; no password kept.
    assert_eq!(s.connections.connections.len(), before + 2, "{notes}");
    let pg = s.connections.connections.iter().find(|c| c.kind == "postgres").unwrap();
    assert_eq!(pg.address, "postgres:host=db.invalid port=5432 dbname=gis user=me sslmode=disable");
    let sql = s.connections.connections.iter().find(|c| c.kind == "sqlserver").unwrap();
    assert_eq!(sql.address, "mssql://me@sql.invalid/gis?instance=main");
    assert!(!format!("{:?}", s.connections.connections).contains("secret"));
    assert!(!notes.contains("secret") && !notes.contains("p4ss"), "{notes}");
    assert!(notes.contains(&format!("log in to the saved connection '{}' (to db.invalid, sslmode disable;", pg.name)), "{notes}");
    for (table, c) in
        [("PostGIS table public.towns", &pg.name), ("PostGIS table public.roads", &pg.name), ("SQL Server table dbo.sites", &sql.name)]
    {
        assert!(notes.contains(&format!("the {table}: log in to the saved connection '{c}'")), "{table}: {notes}");
    }
    assert!(notes.contains("the PostGIS table public.x (service=prod): connect to the database to add it"), "{notes}");
    assert!(notes.contains("the PostGIS table public.y (service=prod host=db.invalid): connect to the database to add it"), "{notes}");
    assert!(notes.contains("the PostGIS table public.z: log in to the saved connection"), "{notes}");
    assert!(notes.contains("the tile archive at a web address"), "{notes}");
    assert!(notes.contains("the saved connection leaves out these settings of the project's: sslrootcert, and 1 more"), "{notes}");
    // A table's filter (`sql=`) is named among them, not its text.
    assert!(
        notes.contains("the PostGIS table public.roads: log in to the saved connection")
            && notes.contains("settings of the project's: sql"),
        "{notes}"
    );
    assert!(!notes.contains("value\" > 20") && !notes.contains("\"value\" &gt;"), "{notes}");
    // No saved connection: the connection text's left-out settings are named too.
    assert!(
        notes.contains(
            "(service=prod): connect to the database to add it; the connection text leaves out these settings of the project's: sslrootcert"
        ),
        "{notes}"
    );
    assert!(notes.contains("none.pmtiles: no file there"), "{notes}");
    assert!(m.tiles.iter().all(|t| t.name != "raster archive"), "{notes}");
    assert!(!notes.contains("/k/ca.pem"), "{notes}");
    assert!(notes.contains("its geometry (geometrycollection), of a kind RustGIS hasn't: a table without geometry"), "{notes}");
    assert!(notes.contains("the tile archive on a network share"), "{notes}");
    assert!(notes.contains("nope.mbtiles: no file there"), "{notes}");
    // Two layers on the same tiles: the one on top takes the other's place, said; the other
    // isn't listed as added.
    let said = |layer: &str, text: &str| {
        out["notes"].as_array().unwrap().iter().any(|n| n["layer"] == layer && n["text"].as_str().unwrap().contains(text))
    };
    assert!(said("unc share", "the tile archive on a network share"), "{notes}");
    assert!(s.project.maps[mine].tiles.iter().any(|t| t.name == "mine"), "{notes}");
    assert!(said("zm", "its geometry's Z and M values: RustGIS keeps x and y"), "{notes}");
    assert!(said("zm", "its fields of a name an earlier field has (1)"), "{notes}");
    assert!(said("lost", "the layer `nosuch` it selects from isn't in the project"), "{notes}");
    assert!(said("orphan", "the layer with id `gone_1` it selects from isn't in the project"), "{notes}");
    assert!(said("on orphan", "the layer with id `gone_1` it selects from isn't in the project"), "{notes}");
    assert!(said("ring a", "the virtual layers it selects from select from each other"), "{notes}");
    assert!(said("on on mem", "on a layer RustGIS doesn't read as a file's layer"), "{notes}");
    assert!(said("on whole gpkg", "its source names no layer of sample.gpkg, a file that holds several"), "{notes}");
    // A chain deeper than RustGIS follows (each pass resolves one link, as they come after the
    // layers they select from): those near the file come in, the farthest are said.
    assert!(m.layer_by_name("deep 11").is_some(), "{notes}");
    assert!(said("deep 0", "or go deeper than the 8 RustGIS follows"), "{notes}");
    assert!(said("look two", "the layer: the same tiles as look one, which takes its place"), "{notes}");
    assert!(said("osm", "the layer: the same tiles as osm, which takes its place"), "{notes}");
    let listed: Vec<&str> = out["layers"].as_array().unwrap().iter().filter_map(Value::as_str).collect();
    assert!(listed.contains(&"look one") && !listed.contains(&"look two"), "{listed:?}");
    assert_eq!(listed.iter().filter(|n| **n == "osm").count(), 1, "{listed:?}");
    // The file layer named as the replaced tile layer stays listed: the tile layer on top and it.
    assert_eq!(listed.iter().filter(|n| **n == "dup").count(), 2, "{listed:?}");
    assert!(s.map().layer_by_name("dup").is_some(), "{notes}");
    assert_eq!(s.map().tiles.iter().filter(|t| t.name == "osm").count(), 1);
    assert!(m.tiles.iter().all(|t| t.name != "web mbtiles" && t.name != "share"), "{notes}");
    // Imported again: the saved connections are used, none made twice.
    let pg_name = pg.name.clone();
    let mut again = s.run("project.importQgis", &json!({"text": qgs, "dir": dir.display().to_string()})).unwrap();
    assert_eq!(s.connections.connections.len(), before + 2);
    assert!(serde_json::to_string(&again["notes"].take()).unwrap().contains(&format!("log in to the saved connection '{pg_name}'")));
    std::fs::remove_dir_all(&dir).ok();
}

/// Sources that carry over whole give no notes: a GPX file's tracks, a memory layer of kinds
/// RustGIS has, and a virtual layer that filters a file's layer.
#[test]
fn qgis_sources_that_carry_over_whole_are_not_noted() {
    let dir = std::env::temp_dir().join(format!("rustgis-qgis-clean-sources-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(
        dir.join("trip.gpx"),
        r#"<gpx version="1.1" creator="t" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>b</name><trkseg><trkpt lat="47.4" lon="8.5"/><trkpt lat="47.5" lon="8.6"/></trkseg></trk></gpx>"#,
    )
    .unwrap();
    std::fs::write(
        dir.join("pts.geojson"),
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"value":30},"geometry":{"type":"Point","coordinates":[8.5,47.4]}},{"type":"Feature","properties":{"value":10},"geometry":{"type":"Point","coordinates":[8.6,47.4]}}]}"#,
    )
    .unwrap();
    let layer = |id: &str, provider: &str, source: &str| {
        format!(
            r#"<maplayer type="vector"><id>{id}</id><datasource>{source}</datasource><layername>{id}</layername><provider>{provider}</provider></maplayer>"#
        )
    };
    let layers = [
        layer("track", "gpx", "./trip.gpx?type=track"),
        layer(
            "scratch",
            "memory",
            "memory?geometry=Point&amp;crs=EPSG:4326&amp;field=name:string(20,0)&amp;field=n:integer(10,0)&amp;field=d:date",
        ),
        layer("big", "virtual", "?layer=ogr:.%2Fpts.geojson:p&amp;query=SELECT%20*%20FROM%20p%20WHERE%20p.value%20%3E%2020"),
    ]
    .concat();
    let qgs = format!(r#"<qgis version="4.2.3"><projectlayers>{layers}</projectlayers></qgis>"#);
    let mut s = world();
    let out = s.run("project.importQgis", &json!({"text": qgs, "dir": dir.display().to_string()})).unwrap();
    assert_eq!(out["notes"], json!([]), "{}", out["notes"]);
    assert_eq!(out["layers"].as_array().map(Vec::len), Some(3), "{out}");
    // The filter, its field written with the table, keeps one feature of the two.
    let big = s.map().layer_by_name("big").unwrap();
    let q = rustgis_data::query::parse(big.definition_query.as_deref().unwrap(), &big.dataset).unwrap();
    let kept: Vec<usize> = (0..big.dataset.features.len()).filter(|&i| rustgis_data::query::eval(&q, &big.dataset, i)).collect();
    assert_eq!(kept.len(), 1, "{:?}", big.definition_query);
    std::fs::remove_dir_all(&dir).ok();
}

/// An import makes at most 16 saved connections, and none whose address it would have to guess
/// at (a quoted value, a Windows user), each table still noted.
#[test]
fn qgis_database_connections_are_bounded_and_never_guessed() {
    let layer = |i: usize, provider: &str, source: &str| {
        format!(
            r#"<maplayer type="vector"><id>l{i}</id><datasource>{source}</datasource><layername>l{i}</layername><provider>{provider}</provider></maplayer>"#
        )
    };
    // First those no address is made for, then more databases than an import makes connections for.
    let mut layers = vec![
        layer(20, "postgres", r#"dbname='my gis' host=db.invalid table="public"."t" (geom)"#),
        layer(21, "mssql", r#"dbname='gis' host=sql.invalid user='CORP\\me' table="dbo"."t" (geom)"#),
        layer(22, "mssql", r#"dbname='gis' host=,1433 table="dbo"."t" (geom)"#),
        layer(23, "postgres", r#"dbname='gis' host=db.invalid user='a\\b' table="public"."t" (geom)"#),
    ];
    layers
        .extend((0..20).map(|i| layer(i, "postgres", &format!(r#"dbname='gis' host=db{i}.invalid user='me' table="public"."t" (geom)"#))));
    let qgs = format!(r#"<qgis version="4.2.3"><projectlayers>{}</projectlayers></qgis>"#, layers.concat());
    let mut s = world();
    let before = s.connections.connections.len();
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    assert_eq!(s.connections.connections.len(), before + 16, "{notes}");
    assert_eq!(notes.matches("log in to the saved connection").count(), 16, "{notes}");
    assert_eq!(notes.matches("connect to the database to add it").count(), 8, "{notes}");
    // Those past the limit say why no connection was saved; those not guessed at don't.
    assert_eq!(notes.matches("(no connection could be saved: an import makes at most 16)").count(), 4, "{notes}");
    let addresses: Vec<&str> = s.connections.connections.iter().map(|c| c.address.as_str()).collect();
    assert!(!addresses.iter().any(|a| ["my gis", "CORP", "a\\b", "host=,"].iter().any(|t| a.contains(t))), "{addresses:?}");
}

/// A vector tile layer with a MapLibre style keeps its own tiles, its style noted (without the
/// style's address, which may carry a key).
#[test]
fn qgis_vector_tiles_with_a_style_keep_their_tiles() {
    let qgs = r#"<qgis version="4.2.3"><projectlayers><maplayer type="vector-tile"><id>t</id><datasource>styleUrl=https://e.invalid/style.json&amp;type=xyz&amp;url=https://e.invalid/%7Bz%7D/%7Bx%7D/%7By%7D.pbf</datasource><layername>styled</layername><provider>xyzvectortiles</provider></maplayer></projectlayers></qgis>"#;
    let mut s = world();
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    let t = s.map().tiles.iter().find(|t| t.name == "styled").unwrap_or_else(|| panic!("{notes}"));
    assert!(format!("{t:?}").contains("https://e.invalid/{z}/{x}/{y}.pbf"), "{t:?}");
    assert!(notes.contains("its vector tile style, and the MapLibre style QGIS made it from: drawn in RustGIS's colours"), "{notes}");
    assert!(!notes.contains("style.json"), "{notes}");
}

/// A bookmark the map's projection doesn't reach isn't saved with another place's view, and a
/// name past a bookmark's longest is cut, both noted.
#[test]
fn qgis_bookmarks_the_map_cannot_show_or_name_are_noted() {
    let long = "N".repeat(130);
    // A name that fits, twice: the second is shortened to make room for its number.
    let fits = "M".repeat(119);
    let qgs = format!(
        r#"<qgis version="4.2.3"><projectCrs><spatialrefsys><authid>EPSG:32631</authid></spatialrefsys></projectCrs><Bookmarks>
      <Bookmark extent="Polygon ((2.2 48.8, 2.5 48.8, 2.5 48.9, 2.2 48.9, 2.2 48.8))" name="{fits}"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      <Bookmark extent="Polygon ((2.2 48.8, 2.5 48.8, 2.5 48.9, 2.2 48.9, 2.2 48.8))" name="{fits}"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      <Bookmark extent="Polygon ((2.2 48.8, 2.5 48.8, 2.5 48.9, 2.2 48.9, 2.2 48.8))" name="Paris"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      <Bookmark extent="Polygon ((-74.1 40.6, -73.8 40.6, -73.8 40.9, -74.1 40.9, -74.1 40.6))" name="New York"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      <Bookmark extent="Polygon ((2.2 48.8, 2.5 48.8, 2.5 48.9, 2.2 48.9, 2.2 48.8))" name="{long}"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      <Bookmark extent="Polygon ((440000 5400000, 460000 5400000, 460000 5420000, 440000 5420000, 440000 5400000))" name="In the project's"/>
    </Bookmarks></qgis>"#
    );
    let mut s = world();
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    let names: Vec<usize> = s.map().bookmarks.iter().map(|b| b.name.chars().count()).collect();
    assert_eq!(names, [119, 120, 5, 120, 16], "{notes}");
    assert!(s.map().bookmarks[1].name.ends_with("M 2"));
    assert!(notes.contains("its bookmarks whose place the map's projection doesn't reach (1: New York)"), "{notes}");
    assert!(notes.contains("bookmark names cut to 120 characters (2)"), "{notes}");
    // One read in the project's coordinate system, said.
    assert!(notes.contains("its bookmarks with no coordinate system of their own, read in the project's (1: In the project's)"), "{notes}");
    // On a Web Mercator map, one reaching past its 85° is fitted to the part it shows, and said.
    let polar = r#"<qgis version="4.2.3"><projectCrs><spatialrefsys><authid>EPSG:3857</authid></spatialrefsys></projectCrs><Bookmarks>
      <Bookmark extent="Polygon ((10 80, 20 80, 20 89, 10 89, 10 80))" name="Polar"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      <Bookmark extent="Polygon ((10 70, 20 70, 20 80, 10 80, 10 70))" name="Arctic"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
      <Bookmark extent="Polygon ((10 86, 20 86, 20 89, 10 89, 10 86))" name="Pole"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>
    </Bookmarks></qgis>"#;
    let mut s = world();
    let out = s.run("project.importQgis", &json!({"text": polar})).unwrap();
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    assert_eq!(s.map().bookmarks.len(), 2, "{notes}");
    // One wholly past them shows nothing: not added, and said.
    assert!(notes.contains("its bookmarks whose place the map's projection doesn't reach (1: Pole)"), "{notes}");
    assert!(
        notes.contains("its bookmarks reaching past the 85° a Web Mercator map shows, fitted to the part it does (1: Polar)"),
        "{notes}"
    );
}

/// A QGIS style's time settings bind a streamed layer on its date field, though its rows aren't
/// read until it is drawn; a field it hasn't is still refused, and noted.
#[test]
fn qgis_time_settings_bind_a_streamed_layer() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut ds = Dataset::new("dated", GeometryType::Point, vec![Field::new("when", FieldType::Text)]);
    for (i, d) in ["2020-01-01", "2021-06-01"].iter().enumerate() {
        ds.push(Some(Geometry::Point(Coord::new(8.0 + i as f64, 47.0))), vec![V::Text((*d).into())]);
    }
    let path = std::env::temp_dir().join(format!("rustgis-engine-{}-dated.fgb", std::process::id()));
    rustgis_data::io::write_path(&ds, &path).unwrap();
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true})).unwrap();
    assert!(s.map().layers[0].is_streamed() && s.map().layers[0].dataset.features.is_empty());
    let qml = |field: &str| {
        format!(r#"<qgis version="4.2.3"><temporal enabled="1" mode="1" startField="{field}" accumulate="0" limitMode="0"/></qgis>"#)
    };
    let out = s.run("style.importQgis", &json!({"layer": "dated", "text": qml("when")})).unwrap();
    assert_eq!(s.map().layers[0].time.as_ref().map(|t| t.field.as_str()), Some("when"), "{out}");
    // Its dates aren't read yet: said.
    assert!(out.to_string().contains("bound before its features are read"), "{out}");
    s.map_mut().layers[0].time = None;
    let out = s.run("style.importQgis", &json!({"layer": "dated", "text": qml("nope")})).unwrap();
    assert!(s.map().layers[0].time.is_none());
    assert!(out.to_string().contains("its time settings, by the field nope, which the layer hasn't"), "{out}");
    let _ = std::fs::remove_file(path);
}

/// Bookmarks in more coordinate systems than an import reads: those past the first 100 systems
/// are left out, and noted.
#[test]
fn qgis_bookmarks_in_too_many_coordinate_systems_are_noted() {
    let mark = |i: u32, code: u32| {
        format!(
            r#"<Bookmark extent="Polygon ((500000 0, 500100 0, 500100 100, 500000 100, 500000 0))" name="B{i}"><spatialrefsys><authid>EPSG:{code}</authid></spatialrefsys></Bookmark>"#
        )
    };
    // 101 UTM zones, north and south.
    let codes = (32601..=32660).chain(32701..=32741);
    let marks: String = codes.enumerate().map(|(i, c)| mark(i as u32, c)).collect();
    let qgs = format!(r#"<qgis version="4.2.3"><Bookmarks>{marks}</Bookmarks></qgis>"#);
    let mut s = world();
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    assert!(notes.contains("its bookmarks in coordinate systems past the first 100 (1: B100)"), "{notes}");
    assert!(!s.map().bookmarks.iter().any(|b| b.name == "B100"));
}

/// Many bookmarks of one name come in numbered, quickly (each name's next number remembered).
#[test]
fn many_qgis_bookmarks_of_one_name_come_in_numbered() {
    let mark = r#"<Bookmark extent="Polygon ((8.4 47.3, 8.6 47.3, 8.6 47.45, 8.4 47.45, 8.4 47.3))" name="Here"><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></Bookmark>"#;
    let qgs = format!(r#"<qgis version="4.2.3"><Bookmarks>{}</Bookmarks></qgis>"#, mark.repeat(5000));
    let mut s = world();
    let started = std::time::Instant::now();
    s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let m = s.map();
    assert_eq!(m.bookmarks.len(), 5000);
    assert_eq!(
        (m.bookmarks[0].name.as_str(), m.bookmarks[1].name.as_str(), m.bookmarks[4999].name.as_str()),
        ("Here", "Here 2", "Here 5000")
    );
    assert!(started.elapsed().as_secs() < 20, "{:?}", started.elapsed());
}

/// A picture whose aspect is locked keeps it on the map, as QGIS fits it on its canvas: in a
/// project in degrees (drawn as plate carrée) its box in degrees, in a Web Mercator one its box in
/// Mercator metres, has the picture's 2:1 aspect, the layer being in degrees either way.
#[test]
fn qgis_annotation_pictures_keep_their_aspect_on_the_map() {
    let mut s = world();
    let png =
        std::fs::read(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../map/testdata/qgis/generated/data/picture.png")).unwrap();
    let b64 = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, png);
    let mercator = |c: rustgis_geom::Coord| {
        (c.x.to_radians() * 6_378_137.0, (std::f64::consts::FRAC_PI_4 + c.y.to_radians() / 2.0).tan().ln() * 6_378_137.0)
    };
    for (project, on_map) in [("EPSG:4326", false), ("EPSG:3857", true)] {
        let qgs = format!(
            r#"<qgis><projectCrs><spatialrefsys><authid>{project}</authid></spatialrefsys></projectCrs><projectlayers>
      <maplayer type="annotation"><id>a</id><layername>P</layername><srs><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></srs><items><item type="picture" path="base64:{b64}" lockAspect="1" xMin="8" yMin="60" xMax="9" yMax="61"/></items></maplayer></projectlayers></qgis>"#
        );
        let r = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
        let l = s.map().layer_by_name("P").unwrap();
        let ds = &l.dataset;
        let pic = (0..ds.features.len()).find(|r| rustgis_map::graphics::kind(ds, *r) == "picture").unwrap_or_else(|| panic!("{r}"));
        let e = ds.features[pic].geometry.as_ref().unwrap().extent();
        let (w, h) = if on_map {
            let (a, b) = (mercator(rustgis_geom::Coord::new(e.min_x, e.min_y)), mercator(rustgis_geom::Coord::new(e.max_x, e.max_y)));
            (b.0 - a.0, b.1 - a.1)
        } else {
            (e.max_x - e.min_x, e.max_y - e.min_y)
        };
        assert!((w / h - 2.0).abs() < 0.01, "{project}: {w} × {h}");
        assert!(!r["notes"].to_string().contains("whose aspect is locked"), "{r}");
    }
    // A project in an ESRI code (Mollweide) the map takes: fitted on it, nothing noted.
    let qgs = format!(
        r#"<qgis><projectCrs><spatialrefsys><authid>ESRI:54009</authid></spatialrefsys></projectCrs><projectlayers>
      <maplayer type="annotation"><id>a</id><layername>M</layername><srs><spatialrefsys><authid>EPSG:4326</authid></spatialrefsys></srs><items><item type="picture" path="base64:{b64}" lockAspect="1" xMin="8" yMin="60" xMax="9" yMax="61"/></items></maplayer></projectlayers></qgis>"#
    );
    let r = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    assert!(!r["notes"].to_string().contains("whose aspect is locked"), "{r}");
    assert!(
        s.map()
            .layer_by_name("M")
            .is_some_and(|l| (0..l.dataset.features.len()).any(|r| rustgis_map::graphics::kind(&l.dataset, r) == "picture")),
        "{r}"
    );
}

/// A QGIS diagram reaches the layer through `style.importQgis`; categories on fields the layer
/// hasn't are left out, and a diagram left with none removed, each noted with the fields. Undo
/// takes it back.
#[test]
fn qgis_diagrams_import_on_the_fields_the_layer_has() {
    let mut s = world();
    let qml = |attrs: &str| {
        format!(
            r##"<qgis version="3.40.0"><SingleCategoryDiagramRenderer diagramType="Pie"><DiagramCategory enabled="1" direction="0" width="10" sizeType="MM">{attrs}</DiagramCategory></SingleCategoryDiagramRenderer></qgis>"##
        )
    };
    let notes =
        |r: &serde_json::Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    let both = r##"<attribute field="&quot;POP_EST&quot;" color="#ff0000"/><attribute field="gdp_md" color="#0000ff"/>"##;
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": qml(both)})).unwrap();
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    let fields = |s: &Session| {
        s.map()
            .layer_by_name("Countries")
            .unwrap()
            .diagram
            .as_ref()
            .map(|d| d.categories.iter().map(|c| c.field.clone()).collect::<Vec<_>>())
    };
    assert_eq!(fields(&s), Some(vec!["POP_EST".to_string(), "gdp_md".to_string()]));
    // One undo step takes it back.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(fields(&s), None);
    // A category on a field the layer hasn't is left out.
    let r = s
        .run(
            "style.importQgis",
            &json!({"layer": "Countries", "text": qml(&format!(r##"{both}<attribute field="nosuch" color="#00ff00"/>"##))}),
        )
        .unwrap();
    assert!(notes(&r).iter().any(|n| n == "its diagram categories on fields the layer hasn't (nosuch)"), "{:?}", notes(&r));
    assert_eq!(fields(&s), Some(vec!["POP_EST".to_string(), "gdp_md".to_string()]));
    // None left: no diagram, noted.
    let r =
        s.run("style.importQgis", &json!({"layer": "Countries", "text": qml(r##"<attribute field="nosuch" color="#00ff00"/>"##)})).unwrap();
    assert!(notes(&r).iter().any(|n| n == "its diagrams, whose fields the layer hasn't (nosuch)"), "{:?}", notes(&r));
    assert_eq!(fields(&s), None);
    // Sized between two values, a pie losing a category is sized by the rest: noted. One of a
    // fixed size says nothing of its size.
    let scaled = |attrs: &str| {
        format!(
            r##"<qgis version="3.40.0"><LinearlyInterpolatedDiagramRenderer diagramType="Pie" lowerValue="0" upperValue="1000" lowerWidth="0" upperWidth="20" classificationAttributeExpression="&quot;pop_est&quot; + &quot;nosuch&quot;"><DiagramCategory enabled="1" direction="0">{attrs}</DiagramCategory></LinearlyInterpolatedDiagramRenderer></qgis>"##
        )
    };
    let sized = "its diagrams sized by the sum of the categories left, without those on fields the layer hasn't";
    let pair = r##"<attribute field="pop_est" color="#ff0000"/><attribute field="nosuch" color="#00ff00"/>"##;
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": scaled(pair)})).unwrap();
    assert!(notes(&r).iter().any(|n| n == sized), "{:?}", notes(&r));
    assert!(!notes(&r).iter().any(|n| n.contains("not by")), "the sum QGIS sizes by is the categories': {:?}", notes(&r));
    // A missing category excluded by QGIS's classification does not change the sizing sum.
    let matching = scaled(pair).replace("&quot;pop_est&quot; + &quot;nosuch&quot;", "&quot;pop_est&quot;");
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": matching})).unwrap();
    assert!(notes(&r).iter().any(|n| n.contains("fields the layer hasn't (nosuch)")), "{:?}", notes(&r));
    assert!(!notes(&r).iter().any(|n| n.contains("not by") || n == sized), "the retained sum matches QGIS: {:?}", notes(&r));
    let r = s.run("style.importQgis", &json!({"layer": "Countries", "text": qml(pair)})).unwrap();
    assert!(!notes(&r).iter().any(|n| n == sized), "{:?}", notes(&r));
    let r = s
        .run("style.importQgis", &json!({"layer": "Countries", "text": scaled(r##"<attribute field="pop_est" color="#ff0000"/>"##)}))
        .unwrap();
    assert!(!notes(&r).iter().any(|n| n == sized), "nothing dropped: {:?}", notes(&r));
    // A graphics layer takes none: noted as left out.
    s.run("graphics.newLayer", &json!({"name": "Sketch"})).unwrap();
    let r = s.run("style.importQgis", &json!({"layer": "Sketch", "text": qml(both)})).unwrap();
    assert!(notes(&r).iter().any(|n| n == "its diagrams (a graphics layer draws none)"), "{:?}", notes(&r));
    assert!(s.map().layer_by_name("Sketch").unwrap().diagram.is_none());
}

#[test]
fn qgis_import_reports_reach_session_notices_without_clean_import_noise() {
    let mut s = world();
    for field in ["pop_est", "missing_category"] {
        let mark = s.notice_mark();
        let qml = format!(
            r##"<qgis><SingleCategoryDiagramRenderer diagramType="Pie"><DiagramCategory enabled="1" width="2" sizeType="MM"><attribute field="{field}" color="#ff0000"/></DiagramCategory></SingleCategoryDiagramRenderer></qgis>"##
        );
        let result = s.run("style.importQgis", &json!({"layer":"Countries", "text":qml})).unwrap();
        let notes = result["notes"].as_array().unwrap();
        let said = s.notices_since(mark);
        assert_eq!(said.len(), notes.len());
        for note in notes {
            assert!(said.iter().any(|n| n.text.contains(note["text"].as_str().unwrap()) && n.text.contains("count 1")));
        }
        assert_eq!(said.is_empty(), field == "pop_est");
    }
    // Project imports use the same delivery path, including notes for a layer left out.
    for layers in [
        "",
        r#"<maplayer type="vector"><id>x</id><layername>Unsupported</layername><provider>not-a-provider</provider><datasource>x</datasource></maplayer>"#,
    ] {
        let mark = s.notice_mark();
        let result = s.run("project.importQgis", &json!({"text":format!("<qgis><projectlayers>{layers}</projectlayers></qgis>")})).unwrap();
        let said = s.notices_since(mark);
        for note in result["notes"].as_array().unwrap() {
            assert!(said.iter().any(|n| n.text.contains(note["text"].as_str().unwrap()) && n.text.contains("count 1")));
        }
        assert_eq!(said.is_empty(), layers.is_empty());
    }
}

#[test]
fn qgis_import_notices_group_layers_and_bound_the_sample_without_dropping_returned_notes() {
    let mut s = world();
    let layers = (0..10).map(|i| format!(r#"<maplayer type="vector"><id>{i}</id><layername>Unsupported{i}</layername><provider>not-a-provider</provider><datasource>x</datasource></maplayer>"#)).collect::<String>();
    let mark = s.notice_mark();
    let result = s.run("project.importQgis", &json!({"text":format!("<qgis><projectlayers>{layers}</projectlayers></qgis>")})).unwrap();
    let notes = result["notes"].as_array().unwrap();
    assert_eq!(notes.len(), 10, "the returned report remains complete");
    assert!(notes.iter().all(|note| note["kind"] == "skipped"));
    let said: Vec<_> = s.notices_since(mark).iter().filter(|n| n.text.starts_with("QGIS import")).collect();
    assert_eq!(said.len(), 1, "one omission notice across all layers");
    assert!(said[0].text.contains("10 omissions") && said[0].text.contains("affected layers: 10"));
    assert!(
        said[0].text.contains(notes[0]["layer"].as_str().unwrap()) && said[0].text.contains("2 additional notes not listed here"),
        "{}",
        said[0].text
    );
    assert!(!said[0].text.contains(notes[9]["layer"].as_str().unwrap()));
    assert!(said[0].text.len() < 4096);
}

/// A QGIS categorized renderer by an expression classes by it where the expression reads on the
/// layer; where it doesn't, every feature draws with the first category's symbol, noted, as before.
#[test]
fn qgis_categories_by_an_expression_class_by_it_where_it_reads() {
    let mut s = world();
    let qml = |attr: &str, cats: &str| {
        format!(
            r#"<qgis version="3.40.0"><renderer-v2 type="categorizedSymbol" attr="{attr}"><categories>{cats}</categories><symbols>
            <symbol type="marker" name="0"><layer class="SimpleMarker" enabled="1"><prop k="color" v="255,0,0,255"/></layer></symbol>
            <symbol type="marker" name="1"><layer class="SimpleMarker" enabled="1"><prop k="color" v="0,0,255,255"/></layer></symbol>
            </symbols></renderer-v2></qgis>"#
        )
    };
    let notes =
        |r: &serde_json::Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    let cats = r#"<category value="Big" symbol="0" label="Over 5 M"/><category value="" symbol="1" label="Others"/>"#;
    let big = "CASE WHEN &quot;pop_max&quot; &gt; 5000000 THEN 'Big' END";
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(big, cats)})).unwrap();
    let said = notes(&r);
    assert!(!said.iter().any(|n| n.contains("expression")), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert_eq!(l.renderer.expression(), Some("CASE WHEN \"pop_max\" > 5000000 THEN 'Big' END"));
    let c = l.renderer.classer(&l.dataset, None);
    let pop = l.dataset.field_index("pop_max").unwrap();
    for row in 0..l.dataset.features.len() {
        let over = l.dataset.value(row, pop).as_f64().is_some_and(|v| v > 5_000_000.0);
        assert_eq!(l.renderer.unique_class(&l.dataset, row, &c).is_some(), over, "row {row}");
    }
    // Naming a field the layer hasn't: the first category's symbol for every feature, noted
    // with the expression as QGIS wrote it.
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", cats)})).unwrap();
    let said = notes(&r);
    assert!(
        said.iter()
            .any(|n| n.contains("upper(\"nosuch\")") && n.contains("doesn't fit the layer") && n.contains("first category's symbol")),
        "{said:?}"
    );
    let fill = |s: &Session| match &s.map().layer_by_name("Cities").unwrap().renderer {
        rustgis_map::Renderer::Single(sym) => sym.fill.0,
        other => panic!("{other:?}"),
    };
    assert_eq!(fill(&s), [255, 0, 0, 255]);
    // The first category is the first listed, "all other values" too.
    let rest_first = r#"<category value="" symbol="1"/><category value="Big" symbol="0"/>"#;
    s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", rest_first)})).unwrap();
    assert_eq!(fill(&s), [0, 0, 255, 255]);
    // Undone, the style before.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(fill(&s), [255, 0, 0, 255]);
    // A switched-off first category is passed over; with no category to draw, said so.
    let off_first = r#"<category value="X" symbol="1" render="false"/><category value="Big" symbol="0"/>"#;
    s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", off_first)})).unwrap();
    assert_eq!(fill(&s), [255, 0, 0, 255]);
    let none = r#"<category value="Big" symbol="9"/>"#;
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("upper(&quot;nosuch&quot;)", none)})).unwrap();
    assert!(notes(&r).iter().any(|n| n.contains("every feature drawn as the rest, which draws nothing")), "{:?}", notes(&r));
    s.run("edit.undo", &Value::Null).unwrap();

    // A field's name with a space, as QGIS writes it (unquoted): classed by that field.
    // (Add Field takes no space; a file's field can have one.)
    s.run("edit.addField", &json!({"layer": "Cities", "name": "size_class", "type": "text"})).unwrap();
    s.run(
        "edit.calculateField",
        &json!({"layer": "Cities", "field": "size_class", "expression": "CASE WHEN pop_max > 5000000 THEN 'Big' END"}),
    )
    .unwrap();
    let id = s.map().layer_by_name("Cities").unwrap().id;
    if let Some(f) = s.map_mut().layer_mut(id).and_then(|l| l.dataset.fields.iter_mut().find(|f| f.name == "size_class")) {
        f.name = "Size Class".into();
    }
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("size class", cats)})).unwrap();
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(
        matches!(&l.renderer, rustgis_map::Renderer::Unique { field, expression: None, .. } if field == "Size Class"),
        "{:?}",
        l.renderer
    );
    // Each feature over five million is "Big", every other the rest.
    let picks = |l: &rustgis_map::Layer| {
        let c = l.renderer.classer(&l.dataset, None);
        let Some(pop) = l.dataset.field_index("pop_max") else { panic!("pop_max") };
        let Some(classes) = (match &l.renderer {
            rustgis_map::Renderer::Unique { classes, .. } => Some(classes.clone()),
            _ => None,
        }) else {
            panic!("{:?}", l.renderer)
        };
        (0..l.dataset.features.len())
            .map(|row| {
                let over = l.dataset.value(row, pop).as_f64().is_some_and(|v| v > 5_000_000.0);
                (over, l.renderer.unique_class(&l.dataset, row, &c).and_then(|i| classes.get(i)).map(|k| k.0.clone()))
            })
            .collect::<Vec<_>>()
    };
    let rows = picks(l);
    assert!(rows.iter().any(|r| r.0));
    for (row, (over, class)) in rows.iter().enumerate() {
        assert_eq!(class.as_deref(), over.then_some("Big"), "row {row}");
    }
    // Boolean categories (as QGIS writes them) by such a field: matching its text "true" and
    // "false" as they are, a boolean field's values as RustGIS prints them.
    let bools = r#"<category value="true" type="bool" symbol="0"/><category value="false" type="bool" symbol="1"/>"#;
    // (A bare name is a field to the importer itself; one with a space is matched here.)
    for (ty, name) in [("text", "Is Big"), ("boolean", "Big Flag"), ("boolean", "big_bool")] {
        let tmp = name.replace(' ', "_");
        s.run("edit.addField", &json!({"layer": "Cities", "name": tmp, "type": ty})).unwrap();
        let e = if ty == "text" { "CASE WHEN pop_max > 5000000 THEN 'true' ELSE 'false' END" } else { "pop_max > 5000000" };
        s.run("edit.calculateField", &json!({"layer": "Cities", "field": tmp, "expression": e})).unwrap();
        if let Some(f) = s.map_mut().layer_mut(id).and_then(|l| l.dataset.fields.iter_mut().find(|f| f.name == tmp)) {
            f.name = name.into();
        }
        let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(name, bools)})).unwrap();
        assert!(notes(&r).is_empty(), "{:?}", notes(&r));
        let rows = picks(s.map().layer_by_name("Cities").unwrap());
        let (yes, no) = if ty == "text" { ("true", "false") } else { ("True", "False") };
        for (row, (over, class)) in rows.iter().enumerate() {
            assert_eq!(class.as_deref(), Some(if *over { yes } else { no }), "{ty} {name} row {row}");
        }
    }
    // A text category "True" beside boolean ones by a text field: each keeps its own value, the
    // boolean ones matching the field's "true" and "false", the text one only "True".
    let mixed = format!(r#"<category value="True" type="string" symbol="1" label="Text"/>{bools}"#);
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml("Is Big", &mixed)})).unwrap();
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    let l = s.map().layer_by_name("Cities").unwrap();
    let rustgis_map::Renderer::Unique { classes, class_labels, .. } = &l.renderer else { panic!("{:?}", l.renderer) };
    assert_eq!(classes.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["True", "true", "false"], "{:?}", notes(&r));
    assert_eq!(class_labels.get("True").map(String::as_str), Some("Text"));
    for (row, (over, class)) in picks(l).iter().enumerate() {
        assert_eq!(class.as_deref(), Some(if *over { "true" } else { "false" }), "mixed row {row}");
    }
    // By an expression, boolean categories match its value as RustGIS prints it.
    let by_expr = "&quot;pop_max&quot; &gt; 5000000";
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(by_expr, bools)})).unwrap();
    assert!(notes(&r).is_empty(), "{:?}", notes(&r));
    for (row, (over, class)) in picks(s.map().layer_by_name("Cities").unwrap()).iter().enumerate() {
        assert_eq!(class.as_deref(), Some(if *over { "True" } else { "False" }), "expression row {row}");
    }
    // ... unless another category has that value: kept as written, said once with a count.
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(by_expr, &mixed)})).unwrap();
    let said = notes(&r);
    assert!(said.iter().any(|n| n.contains("1 boolean category kept as written (the first: true), as another category")), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    let rustgis_map::Renderer::Unique { classes, .. } = &l.renderer else { panic!("{:?}", l.renderer) };
    assert_eq!(classes.iter().map(|c| c.0.as_str()).collect::<Vec<_>>(), ["True", "true", "False"]);
    // ... or when two categories list the value: drawn as the rest, said.
    let twice = r#"<category value="true" type="bool" symbol="0"/><category value="true" type="bool" symbol="1"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(by_expr, twice)})).unwrap());
    assert!(said.iter().any(|n| n.contains("its value listed by more than one category: its features drawn as the rest")), "{said:?}");

    // The layer's own classes by an expression are left alone by a style that sets no renderer,
    // even one an import couldn't take (it measures: QGIS's measures are in the project's units).
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "unique", "expression": "CASE WHEN $area >= 0 THEN 'Big' END"}))
        .unwrap();
    assert!(s.map().layer_by_name("Countries").unwrap().renderer.expression().is_some_and(|e| e.contains("$area")));
    let before = s.map().layer_by_name("Countries").unwrap().renderer.clone();
    let labels_only = r#"<qgis version="3.40.0"><renderer-v2 type="heatmapRenderer"/></qgis>"#;
    s.run("style.importQgis", &json!({"layer": "Countries", "text": labels_only})).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().renderer, before);
}

#[test]
fn qgis_rules_class_features_and_say_which_several_rules_pick() {
    let mut s = world();
    let qml = |rules: &str| {
        format!(
            r#"<qgis version="3.40.0"><renderer-v2 type="RuleRenderer"><rules key="r">{rules}</rules><symbols>
            <symbol type="marker" name="0"><layer class="SimpleMarker" enabled="1"><prop k="color" v="255,0,0,255"/></layer></symbol>
            <symbol type="marker" name="1"><layer class="SimpleMarker" enabled="1"><prop k="color" v="0,0,255,255"/></layer></symbol>
            </symbols></renderer-v2></qgis>"#
        )
    };
    let notes =
        |r: &serde_json::Value| r["notes"].as_array().unwrap().iter().map(|n| n["text"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    // Every city of more than a million picks both rules, at the same scales.
    let big = s.map().layer_by_name("Cities").unwrap();
    let both = (0..big.dataset.features.len())
        .filter(|r| big.dataset.field_index("pop_max").and_then(|f| big.dataset.value(*r, f).as_f64()).is_some_and(|v| v > 5_000_000.0))
        .count();
    assert!(both > 0);
    let rules = r#"<rule filter="&quot;pop_max&quot; &gt; 1000000 AND length(name) &gt; 0" symbol="0" label="Million"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1" label="Five"/>"#;
    let r = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(rules)})).unwrap();
    let said = notes(&r);
    assert!(said.iter().any(|n| n.contains(&format!("{both} features that more than one of its rules picks"))), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(l.renderer.expression().is_some_and(|e| e.contains("THEN 'Million'")), "{:?}", l.renderer);
    // At scales that never meet, nothing is said.
    let apart = r#"<rule filter="&quot;pop_max&quot; &gt; 1000000 AND length(name) &gt; 0" symbol="0" scalemaxdenom="10000"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1" scalemindenom="20000"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(apart)})).unwrap());
    assert!(!said.iter().any(|n| n.contains("more than one")), "{said:?}");
    // Rules reading the map's scale can't be counted at no scale: said without a count.
    let scaled = r#"<rule filter="$scale &gt; 0 AND &quot;pop_max&quot; &gt; 1000000" symbol="0"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(scaled)})).unwrap());
    assert!(said.iter().any(|n| n.contains("features that more than one of its rules picks (if any)")), "{said:?}");
    // The scale named only in quotes is text: counted.
    let quoted = r#"<rule filter="&quot;pop_max&quot; &gt; 1000000 AND name &lt;&gt; '@map_scale'" symbol="0"/>
        <rule filter="&quot;pop_max&quot; &gt; 5000000" symbol="1"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(quoted)})).unwrap());
    assert!(said.iter().any(|n| n.contains(&format!("{both} features that more than one of its rules picks"))), "{said:?}");
    // Only the features its definition query keeps are counted.
    let cities = s.map().layer_by_name("Cities").unwrap();
    let shown = (0..cities.dataset.features.len())
        .filter(|r| {
            cities.dataset.field_index("pop_max").and_then(|f| cities.dataset.value(*r, f).as_f64()).is_some_and(|v| v > 10_000_000.0)
        })
        .count();
    assert!(shown > 0 && shown < both);
    s.run("layer.definitionQuery", &json!({"layer": "Cities", "where": "pop_max > 10000000"})).unwrap();
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(rules)})).unwrap());
    assert!(said.iter().any(|n| n.contains(&format!("{shown} features that more than one of its rules picks"))), "{said:?}");
    s.run("layer.definitionQuery", &json!({"layer": "Cities", "where": ""})).unwrap();
    // An else rule picks what its siblings don't: nothing two rules pick.
    let rest = r#"<rule filter="&quot;pop_max&quot; &gt; 0"><rule filter="&quot;pop_max&quot; &lt; 1000000" symbol="0"/><rule filter="ELSE" symbol="1"/></rule>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(rest)})).unwrap());
    assert!(!said.iter().any(|n| n.contains("more than one")), "{said:?}");
    // A rule whose filter names a field the layer hasn't: left out by its label, the others kept.
    let gone = r#"<rule filter="&quot;nosuch&quot; + 1 &gt; 2" symbol="0" label="Gone"/><rule filter="&quot;pop_max&quot; &gt; 5" symbol="1" label="Kept"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(gone)})).unwrap());
    assert!(said.iter().any(|n| n.contains("the rule \"Gone\"") && n.contains("nosuch")), "{said:?}");
    // Several that don't fit: one note, with how many and the first.
    let two = format!("{gone}<rule filter=\"&quot;nosuch2&quot; = 1\" symbol=\"0\" label=\"Gone too\"/>");
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(&two)})).unwrap());
    assert_eq!(said.iter().filter(|n| n.contains("fit the layer")).count(), 1, "{said:?}");
    assert!(said.iter().any(|n| n.contains("2 rules whose filters don't fit the layer, the first \"Gone\"")), "{said:?}");
    s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(gone)})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    let rustgis_map::Renderer::Unique { classes, expression: Some(e), .. } = &l.renderer else { panic!("{:?}", l.renderer) };
    assert_eq!((classes.len(), classes[0].0.as_str()), (1, "Kept"));
    assert!(!e.contains("nosuch"), "{e}");
    let styler = l.styler(Some(1e6));
    let drawn = (0..l.dataset.features.len()).filter(|r| styler.symbol(*r).fill == rustgis_map::Rgba::rgb(0, 0, 255)).count();
    assert!(drawn > 0, "the kept rule draws");
    // None that reads: the first rule's symbol for every feature, as before rules were classed.
    let none = r#"<rule filter="&quot;nosuch&quot; = 1" symbol="1"/><rule filter="$area &gt; 2" symbol="0"/>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": qml(none)})).unwrap());
    assert!(said.iter().any(|n| n.contains("none of whose filters fit the layer")), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(matches!(l.renderer, rustgis_map::Renderer::Single(sym) if sym.fill == rustgis_map::Rgba::rgb(0, 0, 255)), "{:?}", l.renderer);
    // A layer's filter that is an expression now carries over.
    let filtered = r#"<qgis version="3.40.0"><labeling type="rule-based"><rules key="r">
        <rule filter="length(&quot;name&quot;) &lt;= 5"><settings><text-style fieldName="name"/></settings></rule></rules></labeling></qgis>"#;
    let said = notes(&s.run("style.importQgis", &json!({"layer": "Cities", "text": filtered})).unwrap());
    assert!(said.is_empty(), "{said:?}");
    let l = s.map().layer_by_name("Cities").unwrap();
    assert_eq!(l.labels.classes.first().and_then(|c| c.where_.as_deref()), Some("length(\"name\") <= 5"));
}

#[test]
fn labels_are_set_by_expressions() {
    let mut s = world();
    let r = s
        .run(
            "labels.by",
            &json!({"layer": "Cities", "text": "upper(name)", "size": "scale_linear(pop_max, 0, 2e7, 8, 20)", "color": "if(pop_max > 1e7, '#ff0000', NULL)", "angle": "30"}),
        )
        .unwrap();
    assert_eq!((r["text"].as_str(), r["angle"].as_str()), (Some("upper(name)"), Some("30")));
    let l = s.map().layer_by_name("Cities").unwrap();
    assert!(l.labels.enabled, "a text expression turns the labels on");
    assert_eq!(l.labels.default.by.color.as_deref(), Some("if(pop_max > 1e7, '#ff0000', NULL)"));
    let depth = s.undo_depth();
    for (bad, says) in [
        (json!({"layer": "Cities", "text": "nosuch || 'x'"}), "text: "),
        (json!({"layer": "Cities", "size": "("}), "size: "),
        (json!({"layer": "Cities", "color": 3}), "color is an expression"),
        (json!({"layer": "Cities", "class": "Nope", "angle": "4"}), "no label class named"),
        (json!({"layer": "Cities"}), "give text, size, color or angle"),
    ] {
        let err = s.run("labels.by", &bad).unwrap_err();
        assert!(err.contains(says), "{bad}: {err}");
    }
    assert_eq!(s.undo_depth(), depth);
    // A class's own; a key left out is kept, null removes one, and undo brings it back.
    s.run("labels.class.add", &json!({"layer": "Cities", "name": "Big", "where": "pop_max > 5000000"})).unwrap();
    s.run("labels.by", &json!({"layer": "Cities", "class": "Big", "text": "name || '!'"})).unwrap();
    s.run("labels.by", &json!({"layer": "Cities", "angle": null, "text": ""})).unwrap();
    let l = s.map().layer_by_name("Cities").unwrap();
    assert_eq!(l.labels.classes[0].by.text.as_deref(), Some("name || '!'"));
    assert!(l.labels.default.by.text.is_none() && l.labels.default.by.angle.is_none() && l.labels.default.by.size.is_some());
    s.undo();
    assert_eq!(s.map().layer_by_name("Cities").unwrap().labels.default.by.angle.as_deref(), Some("30"));
    // A style shared to the web says its label expressions are left out.
    let dir = std::env::temp_dir().join(format!("rustgis-labels-by-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("share.webStyle", &json!({"layer": "Cities", "path": dir.join("cities.json").display().to_string()})).unwrap();
    assert!(s.notices.iter().any(|n| n.text.contains("label expressions aren't in it")), "{:?}", s.notices.last());
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    // Converted, each label keeps its text, size and colour: the annotation draws by its fields.
    s.run("labels.class.clear", &json!({"layer": "Cities"})).unwrap();
    s.run("labels.by", &json!({"layer": "Cities", "text": "upper(name)", "angle": null})).unwrap();
    s.run("labels.convert", &json!({"layer": "Cities"})).unwrap();
    let a = s.map().layer_by_name("Cities Annotation").unwrap();
    let names: Vec<&str> = a.dataset.fields.iter().map(|f| f.name.as_str()).collect();
    assert_eq!(names, ["TEXT", "SIZE", "COLOR"]);
    let by = &a.labels.default.by;
    assert_eq!(
        (by.text.as_deref(), by.size.as_deref(), by.color.as_deref(), by.angle.as_deref()),
        (None, Some("\"SIZE\""), Some("\"COLOR\""), None)
    );
    let fi = |n: &str| a.dataset.field_index(n).unwrap();
    let paris = (0..a.dataset.features.len()).find(|r| a.dataset.value(*r, fi("TEXT")).to_string() == "PARIS").expect("upper-case text");
    assert!(a.dataset.value(paris, fi("SIZE")).as_f64().is_some_and(|v| v > 8.0));
    let red = (0..a.dataset.features.len()).filter(|r| a.dataset.value(*r, fi("COLOR")).to_string() == "255,0,0,255").count();
    assert!(red > 0 && red < a.dataset.features.len(), "only the big cities' red, the rest the class's");
    assert!(!s.notices.iter().any(|n| n.text.contains("cut to")), "short texts aren't cut");
}

/// What label expressions lose is said, and what's reported or kept follows what the map draws:
/// a text cut by Convert To Annotation, the Web Style's notices, Project Info's labels, and the
/// angle a converted label keeps, decided for each feature.
#[test]
fn label_expressions_say_what_they_lose() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as Attr};
    let mut s = world();
    let cities = s.map().layer_by_name("Cities").unwrap().id;
    // A text past its most characters is cut, said once with a count.
    let long = format!("name || '{}'", "x".repeat(rustgis_map::label_by::MAX_LABEL_TEXT));
    s.run("labels.by", &json!({"layer": "Cities", "text": long})).unwrap();
    let n = s.run("labels.convert", &json!({"layer": "Cities"})).unwrap()["annotations"].as_u64().unwrap();
    let said = format!("Cities Annotation: {n} label texts cut to {} characters", rustgis_map::label_by::MAX_LABEL_TEXT);
    assert!(s.notices.iter().any(|x| x.text == said), "{:?}", s.notices.last());
    s.undo();
    // Project Info names the text expression the labels draw by, and the field once it doesn't read.
    s.map_mut().layer_mut(cities).unwrap().labels.default.field = "name".into();
    s.run("labels.by", &json!({"layer": "Cities", "text": "upper(name)"})).unwrap();
    let labels = |s: &mut Session| {
        let info = s.run("info.project", &Value::Null).unwrap();
        info["layers"].as_array().unwrap().iter().find(|l| l["name"] == "Cities").unwrap()["labels"].clone()
    };
    assert_eq!(labels(&mut s), json!("upper(name)"));
    s.map_mut().layer_mut(cities).unwrap().labels.default.by.text = Some("upper(gone)".into());
    assert_eq!(labels(&mut s), json!("name"));
    // Deleting the field Default labels by keeps the labels while its text expression reads, and
    // starts Default again (labels off) once it doesn't.
    s.run("edit.addField", &json!({"layer": "Cities", "name": "spare", "type": "text"})).unwrap();
    for (text, on) in [("'#' || pop_max", true), ("upper(spare)", false)] {
        let l = s.map_mut().layer_mut(cities).unwrap();
        (l.labels.enabled, l.labels.default.field, l.labels.default.by.text) = (true, "spare".into(), Some(text.into()));
        s.run("edit.deleteField", &json!({"layer": "Cities", "field": "spare"})).unwrap();
        let l = s.map().layer(cities).unwrap();
        assert_eq!(l.labels.enabled, on, "{text}");
        assert_eq!(l.labels.default.by.text.is_some(), on, "{text}");
        assert!(l.labels.default.field != "spare");
        s.undo();
    }
    s.map_mut().layer_mut(cities).unwrap().labels.default.by.text = Some("upper(name)".into());
    // Web Style: a Default class labelling by a text expression alone says only that its style has
    // none, even with other classes; one with a size but no text or field says nothing of it.
    let dir = std::env::temp_dir().join(format!("rustgis-labels-lose-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let share = |s: &mut Session| {
        let before = s.notices.len();
        s.run("share.webStyle", &json!({"layer": "Cities", "path": dir.join("c.json").display().to_string()})).unwrap();
        s.notices[before..].iter().map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    let l = s.map_mut().layer_mut(cities).unwrap();
    l.labels.default.field.clear();
    l.labels.default.by.text = Some("upper(name)".into());
    s.run("labels.class.add", &json!({"layer": "Cities", "name": "Big", "where": "pop_max > 5000000"})).unwrap();
    // Project Info lists each class's text expression with its field.
    s.run("labels.by", &json!({"layer": "Cities", "class": "Big", "text": "name || '!'"})).unwrap();
    let info = s.run("info.project", &Value::Null).unwrap();
    let classes = &info["layers"].as_array().unwrap().iter().find(|l| l["name"] == "Cities").unwrap()["labelClasses"];
    assert_eq!(classes[0]["text"], json!("name || '!'"), "{classes}");
    let said = share(&mut s);
    assert!(said.iter().any(|t| t.contains("has no labels: its Default class's text is an expression")), "{said:?}");
    assert!(!said.iter().any(|t| t.contains("labels every feature")), "{said:?}");
    let l = s.map_mut().layer_mut(cities).unwrap();
    (l.labels.default.by.text, l.labels.default.by.size) = (None, Some("8".into()));
    let said = share(&mut s);
    assert!(said.iter().any(|t| t.contains("has no labels: its Default class has no label field")), "{said:?}");
    assert!(!said.iter().any(|t| t.contains("expression") || t.contains("labels every feature")), "{said:?}");
    std::fs::remove_dir_all(&dir).ok();
    // A converted label keeps its angle on a point, and none on a line it is placed along, in a
    // layer of both; a layer of lines alone gets no ANGLE field.
    let line = Geometry::Line(vec![vec![Coord::new(0.0, 0.0), Coord::new(5.0, 0.0)]]);
    let point = Geometry::Point(Coord::new(1.0, 1.0));
    for (geoms, angles) in [(vec![line.clone(), point], Some(vec![Attr::Null, Attr::Float(30.0)])), (vec![line], None)] {
        let mut ds = Dataset::new("ways", GeometryType::Polyline, vec![Field::new("name", FieldType::Text)]);
        for g in geoms {
            ds.push(Some(g), vec![Attr::Text("w".into())]);
        }
        let id = s.map_mut().add_dataset(ds);
        let l = s.map_mut().layer_mut(id).unwrap();
        (l.labels.enabled, l.labels.default.field, l.labels.default.placement) =
            (true, "name".into(), rustgis_map::LabelPlacement::Parallel);
        l.labels.default.by.angle = Some("30".into());
        let a = s.run("labels.convert", &json!({"layer": id})).unwrap()["layer"].as_u64().unwrap() as u32;
        let a = &s.map().layer(a).unwrap().dataset;
        let got = a.field_index("ANGLE").map(|fi| (0..a.features.len()).map(|r| a.value(r, fi).clone()).collect::<Vec<_>>());
        assert_eq!(got, angles);
    }
}

#[test]
fn a_qgis_styles_data_defined_settings_are_kept_where_they_read() {
    let mut s = world();
    // Size by a field Cities has; fill by a QGIS function RustGIS lacks; outline by a field it hasn't.
    let dd = |name: &str, expr: &str| {
        format!(
            r#"<Option type="Map" name="{name}"><Option value="true" type="bool" name="active"/><Option value="{expr}" type="QString" name="expression"/><Option value="3" type="int" name="type"/></Option>"#
        )
    };
    let qml = format!(
        r#"<qgis version="3.40.0"><renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1">
        <layer class="SimpleMarker" enabled="1"><Option type="Map"><Option name="name" value="circle"/><Option name="size_unit" value="Pixel"/></Option>
        <data_defined_properties><Option type="Map"><Option type="Map" name="properties">{}{}{}</Option></Option></data_defined_properties></layer>
        </symbol></symbols></renderer-v2></qgis>"#,
        dd("size", "&quot;pop_max&quot; / 1e6"),
        dd("fillColor", "set_color_part(@symbol_color, 'value', 40)"),
        dd("outlineColor", "&quot;nosuch&quot;"),
    );
    let out = s.run("style.importQgis", &json!({"layer": "Cities", "text": qml})).unwrap();
    let by = &s.map().layer_by_name("Cities").unwrap().symbol_by;
    assert_eq!((by.size.as_deref(), &by.fill, &by.stroke), (Some(r#""pop_max" / 1e6"#), &None, &None), "{by:?}");
    let notes = serde_json::to_string(&out["notes"]).unwrap();
    assert!(
        notes.contains("data-defined symbol fill colour `set_color_part") && notes.contains("outline colour `\\\"nosuch\\\"`"),
        "{notes}"
    );
}

#[test]
fn a_stroke_is_dashed_by_command() {
    let mut s = world();
    let stroke = |dash: Value| json!({"layer": "Rivers", "strokes": [{"color": "#000000", "width": 2, "dash": dash}]});
    s.run("layer.lineStrokes", &stroke(json!([4, 2.5]))).unwrap();
    let dash = |s: &Session| s.map().layer_by_name("Rivers").unwrap().line_strokes[0].dash.map(|d| d.steps().to_vec());
    assert_eq!(dash(&s), Some(vec![4.0, 2.5]));
    let depth = s.undo_depth();
    for bad in [json!([]), json!([0, 0]), json!([-1, 2]), json!([1, "2"]), json!("4 2"), json!([1, 1, 1, 1, 1, 1, 1, 1, 1]), json!([1e9])] {
        assert!(s.run("layer.lineStrokes", &stroke(bad.clone())).is_err(), "{bad}");
    }
    assert_eq!((s.undo_depth(), dash(&s)), (depth, Some(vec![4.0, 2.5])), "a refused pattern changes nothing");
    s.run("layer.lineStrokes", &stroke(Value::Null)).unwrap();
    assert_eq!(dash(&s), None, "null: solid");
}

#[test]
fn a_class_stacks_strokes_of_its_own() {
    use rustgis_map::symbology::ClassRef;
    use rustgis_map::{LineStroke, Rgba};
    let mut s = world();
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "unique", "field": "scalerank"})).unwrap();
    // The layer's one stroke, a casing and core for rivers of rank 1, a thin line for
    // <all other values>; rank 2 keeps the layer's.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": [{"offset": 3}]})).unwrap();
    let depth = s.undo_depth();
    let pair = json!([{"color": "#000000", "width": 6}, {"color": "#FF8C00", "width": 3}]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": "1", "strokes": pair})).unwrap();
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "other": true, "strokes": [{"width": 0.5}]})).unwrap();
    assert_eq!(s.undo_depth(), depth + 2);
    let casing = vec![
        LineStroke { color: Some(Rgba::rgb(0, 0, 0)), width: Some(6.0), ..Default::default() },
        LineStroke { color: Some(Rgba::rgb(0xFF, 0x8C, 0)), width: Some(3.0), ..Default::default() },
    ];
    let layer_own = vec![LineStroke { offset: 3.0, ..Default::default() }];
    let check = |s: &Session| {
        let l = s.map().layer_by_name("Rivers").unwrap();
        let fi = l.dataset.field_index("scalerank").unwrap();
        assert!(l.has_strokes());
        for row in 0..l.dataset.features.len() {
            let want = if l.dataset.value(row, fi).to_string() == "1" { &casing } else { &layer_own };
            assert_eq!(l.strokes(row), want.as_slice(), "row {row}");
            // Classed once, the same as asked apart.
            assert_eq!(l.style(row), (l.symbol(row), want.as_slice()), "row {row}");
        }
        assert_eq!(l.renderer.class_strokes(&ClassRef::Other).unwrap().len(), 1);
    };
    check(&s);
    // A number names the class as the data prints it.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": 1, "strokes": pair})).unwrap();
    check(&s);
    // Kept in the project file, and through applying the same symbology again.
    let dir = std::env::temp_dir().join(format!("rustgis-class-strokes-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("strokes.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    let png = dir.join("map.png");
    t.run("share.exportMap", &json!({"path": png.display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "unique", "field": "scalerank", "ramp": "Ember"})).unwrap();
    check(&s);
    // Junk, a class that isn't there, or a class on the wrong renderer: refused, nothing changes.
    let depth = s.undo_depth();
    for bad in [
        json!({"layer": "Rivers", "value": "7", "strokes": pair}),
        json!({"layer": "Rivers", "index": 0, "strokes": pair}),
        json!({"layer": "Rivers", "value": "1", "index": 0, "strokes": pair}),
        json!({"layer": "Rivers", "value": [1], "strokes": pair}),
        json!({"layer": "Rivers", "value": "1", "strokes": vec![json!({}); 17]}),
        json!({"layer": "Rivers", "value": "1", "strokes": [{"cap": "pointy"}]}),
        json!({"layer": "Cities", "value": "1", "strokes": []}),
    ] {
        assert!(s.run("layer.lineStrokes", &bad).is_err(), "{bad}");
    }
    assert_eq!(s.undo_depth(), depth);
    // [] gives the class back to the layer's strokes; undo brings its own back.
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": "1", "strokes": []})).unwrap();
    assert!(s.map().layer_by_name("Rivers").unwrap().strokes(0).iter().all(|st| st.offset == 3.0));
    s.run("edit.undo", &Value::Null).unwrap();
    check(&s);
    // Another field starts fresh.
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "unique", "field": "name"})).unwrap();
    assert!(!s.map().layer_by_name("Rivers").unwrap().renderer.has_class_strokes());
    // Graduated Colors classes go by index; a single symbol has no classes.
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "graduated", "field": "scalerank", "classes": 2})).unwrap();
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "index": 0, "strokes": pair})).unwrap();
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().renderer.class_strokes(&ClassRef::Index(0)).unwrap(), casing.as_slice());
    assert!(s.run("layer.lineStrokes", &json!({"layer": "Rivers", "index": 9, "strokes": pair})).is_err());
    assert!(s.run("layer.lineStrokes", &json!({"layer": "Rivers", "value": "1", "strokes": pair})).is_err());
    s.run("layer.symbology", &json!({"layer": "Rivers", "type": "single"})).unwrap();
    assert!(s.run("layer.lineStrokes", &json!({"layer": "Rivers", "index": 0, "strokes": pair})).is_err());
}

#[test]
fn strokes_draw_in_levels() {
    let mut s = world();
    let depth = s.undo_depth();
    let strokes = json!([{"color": "#000000", "width": 6, "level": 2}, {"color": "#FFFFFF", "width": 2}]);
    s.run("layer.lineStrokes", &json!({"layer": "Rivers", "strokes": strokes})).unwrap();
    s.run("layer.strokeLevels", &json!({"layer": "Rivers", "on": true})).unwrap();
    assert_eq!(s.undo_depth(), depth + 2);
    let check = |s: &Session| {
        let l = s.map().layer_by_name("Rivers").unwrap();
        assert!(l.stroke_levels);
        assert_eq!(l.line_strokes[0].level, Some(2));
        // Without a level of its own, a stroke draws at its place in the stack.
        assert_eq!((l.line_strokes[0].level_at(0), l.line_strokes[1].level_at(1)), (2, 1));
    };
    check(&s);
    let dir = std::env::temp_dir().join(format!("rustgis-stroke-levels-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("levels.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    t.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for (id, bad) in [
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": 256}]})),
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": -1}]})),
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": 1.5}]})),
        ("layer.lineStrokes", json!({"layer": "Rivers", "strokes": [{"level": "top"}]})),
        ("layer.strokeLevels", json!({"layer": "Rivers"})),
        ("layer.strokeLevels", json!({"layer": "Cities", "on": true})),
    ] {
        assert!(s.run(id, &bad).is_err(), "{id} {bad}");
    }
    assert_eq!(s.undo_depth(), depth);
    s.run("layer.strokeLevels", &json!({"layer": "Rivers", "on": false})).unwrap();
    assert!(!s.map().layer_by_name("Rivers").unwrap().stroke_levels);
    s.run("edit.undo", &Value::Null).unwrap();
    check(&s);
}

#[test]
fn a_reference_scale_is_set_kept_and_undone() {
    let mut s = world();
    let depth = s.undo_depth();
    s.run("layer.referenceScale", &json!({"layer": "Rivers", "scale": 25000})).unwrap();
    // "current" takes the map's scale, rounded.
    let now = s.map().scale().round();
    s.run("layer.referenceScale", &json!({"layer": "Cities", "scale": "current"})).unwrap();
    assert_eq!(s.undo_depth(), depth + 2);
    let check = |s: &Session| {
        let at = |n: &str| s.map().layer_by_name(n).unwrap().reference_scale;
        assert_eq!((at("Rivers"), at("Cities"), at("Lakes")), (Some(25000.0), Some(now), None));
    };
    check(&s);
    let dir = std::env::temp_dir().join(format!("rustgis-reference-scale-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("reference.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    t.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    let depth = s.undo_depth();
    for bad in [
        json!({"layer": "Rivers", "scale": 0}),
        json!({"layer": "Rivers", "scale": -25000}),
        json!({"layer": "Rivers", "scale": 1e12}),
        json!({"layer": "Rivers", "scale": "big"}),
        json!({"layer": "Rivers", "scale": [25000]}),
        json!({"layer": "Nowhere", "scale": 25000}),
    ] {
        assert!(s.run("layer.referenceScale", &bad).is_err(), "{bad}");
    }
    assert_eq!(s.undo_depth(), depth);
    s.run("layer.referenceScale", &json!({"layer": "Rivers", "scale": null})).unwrap();
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().reference_scale, None);
    s.run("edit.undo", &Value::Null).unwrap();
    check(&s);
}

#[test]
fn a_reference_scale_out_of_range_in_a_project_is_left_out_and_said() {
    let mut s = world();
    s.run("layer.referenceScale", &json!({"layer": "Rivers", "scale": 25000})).unwrap();
    let text = serde_json::to_string(&s.project).unwrap();
    let said = |text: &str| {
        let mut t = Session::new(Project::default());
        let mark = t.notices_given();
        t.run("project.openText", &json!({"text": text})).unwrap();
        let notices: Vec<String> = t.notices_since(mark).iter().map(|n| n.text.clone()).collect();
        (t.map().layer_by_name("Rivers").unwrap().reference_scale, notices)
    };
    // One the command takes opens as saved, with nothing to say.
    let (kept, notices) = said(&text);
    assert_eq!(kept, Some(25000.0));
    assert!(!notices.iter().any(|n| n.contains("reference scale")), "{notices:?}");
    // One it would refuse is left out, and the notice names the layer.
    for bad in ["1e39", "-5", "0"] {
        let edited = text.replace("\"reference_scale\":25000.0", &format!("\"reference_scale\":{bad}"));
        assert_ne!(edited, text);
        let (kept, notices) = said(&edited);
        assert_eq!(kept, None, "{bad}");
        assert!(
            notices.iter().any(|n| n.contains("1 layer(s) with a reference scale out of range") && n.contains("'Rivers'")),
            "{bad}: {notices:?}"
        );
    }
    // So does a map file or a layer file added on its own, and a clean one says nothing.
    let map = serde_json::to_string(s.map()).unwrap();
    let layer = serde_json::to_string(s.map().layer_by_name("Rivers").unwrap()).unwrap();
    for (command, text) in [("map.import", map), ("layer.addLayerFile", layer)] {
        let said = |text: String| {
            let mut t = world();
            let mark = t.notices_given();
            t.run(command, &json!({"text": text})).unwrap();
            t.notices_since(mark).iter().map(|n| n.text.clone()).collect::<Vec<String>>()
        };
        let clean = said(text.clone());
        assert!(!clean.iter().any(|n| n.contains("reference scale")), "{command}: {clean:?}");
        let bad = said(text.replace("\"reference_scale\":25000.0", "\"reference_scale\":0"));
        assert!(bad.iter().any(|n| n.contains("reference scale out of range") && n.contains("'Rivers'")), "{command}: {bad:?}");
    }
}

/// `labels.placement` perpendicular (#2263): square to a line or polygon layer by name, its side
/// kept when the layer changes, its layer followed through a rename; refused without a layer to
/// be square to, or with a point layer; a distance out of range held to it, and said.
#[test]
fn cities_are_placed_square_to_a_line_layer() {
    let mut s = world();
    let class = |s: &Session| s.map().layer_by_name("Cities").unwrap().labels.default.clone();
    assert!(s.run("labels.placement", &json!({"layer": "Cities", "position": "perpendicular"})).is_err(), "no line");
    assert!(s.run("labels.placement", &json!({"layer": "Cities", "position": "perpendicular", "to": {"layer": "Cities"}})).is_err());
    assert!(s.run("labels.placement", &json!({"layer": "Cities", "position": "perpendicular", "to": {"layer": "Nowhere"}})).is_err());
    assert!(s.run("labels.placement", &json!({"layer": "Cities", "side": "left"})).is_err(), "side without a line");
    let mark = s.notices_given();
    s.run(
        "labels.placement",
        &json!({"layer": "Cities", "position": "perpendicular", "to": {"layer": "rivers", "within": 900}, "side": "left"}),
    )
    .unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("within 900 points adjusted to 500")));
    let c = class(&s);
    let to = c.square_to.clone().unwrap();
    assert_eq!(
        (c.placement, to.layer.as_str(), to.within, to.side),
        (crate::map::LabelPlacement::Perpendicular, "Rivers", 500.0, crate::map::SquareSide::Left)
    );
    s.run("labels.placement", &json!({"layer": "Cities", "to": {"layer": "Countries"}})).unwrap();
    let to = class(&s).square_to.unwrap();
    assert_eq!((to.layer.as_str(), to.within, to.side), ("Countries", 20.0, crate::map::SquareSide::Left));
    s.run("layer.rename", &json!({"layer": "Countries", "name": "Nations"})).unwrap();
    assert_eq!(class(&s).square_to.unwrap().layer, "Nations");
    assert!(s.run("labels.placement", &json!({"layer": "Cities", "side": "up"})).is_err());
    // Saved and read back with the project.
    let back: crate::map::LabelClass = serde_json::from_value(serde_json::to_value(class(&s)).unwrap()).unwrap();
    assert_eq!(back, class(&s));
    // Its line taken away while it stays perpendicular: refused, the class as it was; with a new
    // position given, taken.
    let before = class(&s);
    let err = s.run("labels.placement", &json!({"layer": "Cities", "to": null})).unwrap_err();
    assert!(err.contains("perpendicular needs a line"), "{err}");
    assert_eq!(class(&s), before);
    // Its line unread (as a project saved so opens): labelled as auto, and other edits taken.
    s.map_mut().layers.iter_mut().find(|l| l.name == "Cities").unwrap().labels.default.square_to = None;
    s.run("labels.placement", &json!({"layer": "Cities", "offset": [2, 0]})).unwrap();
    // Placed elsewhere and cleared.
    s.run("labels.placement", &json!({"layer": "Cities", "position": "above", "to": null})).unwrap();
    assert_eq!(class(&s).square_to, None);
}

/// The line perpendicular labels are square to removed (#2263): the class keeps its name, so a
/// layer of that name brings it back, and its labels are placed as auto meanwhile: said once.
#[test]
fn removing_a_perpendicular_label_line_says_so() {
    let mut s = world();
    s.run("labels.placement", &json!({"layer": "Cities", "position": "perpendicular", "to": {"layer": "Rivers"}})).unwrap();
    let said = |s: &Session, mark| {
        s.notices_since(mark).iter().filter(|n| n.text.contains("perpendicular")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    let mark = s.notices_given();
    s.run("layer.remove", &json!({"layer": "Countries"})).unwrap();
    assert!(said(&s, mark).is_empty());
    let mark = s.notices_given();
    s.run("layer.remove", &json!({"layer": "Rivers"})).unwrap();
    let notes = said(&s, mark);
    assert_eq!(notes.len(), 1, "{notes:?}");
    assert!(notes[0].contains("1 perpendicular labels' line layer 'Rivers' removed"), "{notes:?}");
    let c = s.map().layer_by_name("Cities").unwrap().labels.default.clone();
    assert_eq!((c.placement, c.square_to.unwrap().layer.as_str()), (crate::map::LabelPlacement::Perpendicular, "Rivers"));
}

/// A project whose perpendicular label line doesn't read, names no layer, or is out of range
/// says so on opening, one notice with a count; a good one or none says nothing (#2263).
#[test]
fn opening_a_project_says_when_a_perpendicular_line_is_dropped() {
    let said = |v: &Value| {
        let s = Session::new(Project::from_json(&v.to_string()).unwrap());
        s.notices.iter().filter(|n| n.text.contains("perpendicular label line")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    let clean: Value = serde_json::to_value(&world().project).unwrap();
    assert!(said(&clean).is_empty());
    let mut fine = clean.clone();
    fine["maps"][0]["layers"][0]["labels"]["square_to"] = json!({"layer": "Rivers", "within": 30, "side": "left"});
    assert!(said(&fine).is_empty());
    let mut damaged = clean.clone();
    damaged["maps"][0]["layers"][0]["labels"]["square_to"] = json!({"layer": ""});
    damaged["maps"][0]["layers"][1]["labels"]["square_to"] = json!({"layer": "Rivers", "within": 9000});
    let loaded = Project::from_json(&damaged.to_string()).unwrap();
    assert_eq!(loaded.maps[0].layers[0].labels.default.square_to, None);
    assert_eq!(loaded.maps[0].layers[1].labels.default.square_to.as_ref().map(|t| t.within), Some(500.0));
    let notes = said(&damaged);
    assert_eq!(notes.len(), 1, "{notes:?}");
    assert!(notes[0].contains("2 perpendicular label line setting(s)"), "{notes:?}");
}

/// `labels.placement`'s guide (#2262): a line layer by name and a field both layers have, for
/// point and polygon labels; followed through a rename, said when removed, cleared by null; a
/// project's guide that doesn't read dropped and said once.
#[test]
fn labels_are_guided_along_a_line_layer() {
    let mut s = world();
    let guide = |s: &Session| s.map().layer_by_name("Lakes").unwrap().labels.default.guide.clone();
    let place = |s: &mut Session, layer: &str, g: Value| s.run("labels.placement", &json!({"layer": layer, "guide": g}));
    assert!(place(&mut s, "Rivers", json!({"layer": "Rivers"})).is_err(), "a line's label follows its own line");
    assert!(place(&mut s, "Lakes", json!({"layer": "Countries"})).is_err(), "no lines");
    assert!(place(&mut s, "Lakes", json!({"layer": "Nowhere"})).is_err());
    assert!(place(&mut s, "Lakes", json!({"layer": "Rivers", "field": "nowhere"})).is_err());
    assert!(place(&mut s, "Lakes", json!({"field": "name"})).is_err());
    place(&mut s, "Lakes", json!({"layer": "rivers", "field": "name"})).unwrap();
    assert_eq!(guide(&s), Some(crate::map::LabelGuide { layer: "Rivers".into(), field: Some("name".into()) }));
    place(&mut s, "Cities", json!({"layer": "Rivers", "field": ""})).unwrap();
    let square = json!({"layer": "Cities", "position": "perpendicular", "to": {"layer": "Rivers"}});
    assert!(s.run("labels.placement", &square).is_err(), "square to a line or along a guide, not both");
    let back: crate::map::LabelClass =
        serde_json::from_value(serde_json::to_value(&s.map().layer_by_name("Lakes").unwrap().labels.default).unwrap()).unwrap();
    assert_eq!(back.guide, guide(&s));
    s.run("layer.rename", &json!({"layer": "Rivers", "name": "Waters"})).unwrap();
    assert_eq!(guide(&s).map(|g| g.layer), Some("Waters".into()));
    let mark = s.notices_given();
    s.run("layer.remove", &json!({"layer": "Waters"})).unwrap();
    let said: Vec<_> = s.notices_since(mark).iter().filter(|n| n.text.contains("guide layer")).map(|n| n.text.clone()).collect();
    assert!(said.len() == 1 && said[0].contains("1 guide layer(s) 'Waters' removed"), "{said:?}");
    place(&mut s, "Lakes", Value::Null).unwrap();
    assert_eq!(guide(&s), None);
    let said = |v: &Value| {
        let s = Session::new(Project::from_json(&v.to_string()).unwrap());
        s.notices.iter().filter(|n| n.text.contains("label guide")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    let clean: Value = serde_json::to_value(&world().project).unwrap();
    let mut fine = clean.clone();
    // (Spaces round its layer's name trimmed, as the command keeps it.)
    fine["maps"][0]["layers"][0]["labels"]["guide"] = json!({"layer": " Rivers ", "field": "name"});
    assert!(said(&clean).is_empty() && said(&fine).is_empty());
    let read = Project::from_json(&fine.to_string()).unwrap();
    assert_eq!(read.maps[0].layers[0].labels.default.guide.as_ref().map(|g| g.layer.as_str()), Some("Rivers"));
    let mut damaged = clean.clone();
    damaged["maps"][0]["layers"][0]["labels"]["guide"] = json!({"layer": ""});
    damaged["maps"][0]["layers"][1]["labels"]["guide"] = json!({"layer": "Rivers", "field": 3});
    assert_eq!(Project::from_json(&damaged.to_string()).unwrap().maps[0].layers[1].labels.default.guide, None);
    let notes = said(&damaged);
    assert!(notes.len() == 1 && notes[0].contains("2 label guide setting(s)"), "{notes:?}");
    // A saved guided label (`label_guide.rgis`) reads back as saved, saying nothing.
    let mut saved = Project::from_json(include_str!("../../../schema/fixtures/label_guide.rgis")).unwrap();
    let class = &saved.maps[0].layers[0].labels.default;
    assert_eq!(class.guide, Some(crate::map::LabelGuide { layer: "rios".into(), field: Some("nome".into()) }));
    assert!(saved.take_read_notices(&crate::project::ALL_PARTS).is_empty());
    // Saved, it requires `label-guide`, which an older reader refuses rather than drop.
    assert_eq!(serde_json::to_value(&saved).unwrap()["requires"], json!(["label-guide"]));
    assert!(clean.get("requires").is_none());
}

/// A guide layer read in place from its file (#2262) has only a view's window at hand: refused
/// until it is loaded whole, and said once when a project or map file has one.
#[test]
fn a_guide_layer_read_in_place_is_refused_and_said() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut ds = Dataset::new("cumeadas", GeometryType::Polyline, vec![Field::new("name", FieldType::Text)]);
    for i in 0..4 {
        let y = f64::from(i) * 5.0;
        ds.push(Some(Geometry::Line(vec![vec![Coord::new(-10.0, y), Coord::new(10.0, y + 1.0)]])), vec![V::Text(format!("Serra {i}"))]);
    }
    let path = std::env::temp_dir().join(format!("rustgis-engine-{}-guide-streamed.fgb", std::process::id()));
    rustgis_data::io::write_path(&ds, &path).unwrap();
    let mut s = world();
    s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true})).unwrap();
    assert!(s.map().layer_by_name("cumeadas").unwrap().is_streamed());
    let e = s.run("labels.placement", &json!({"layer": "Lakes", "guide": {"layer": "cumeadas"}})).unwrap_err();
    assert!(e.contains("layer.loadAll"), "{e}");
    // A project that has one anyway (written by hand, or the layer made streamed since): said once.
    for name in ["Lakes", "Cities"] {
        let l = s.map_mut().layers.iter_mut().find(|l| l.name == name).unwrap();
        l.labels.default.guide = Some(crate::map::LabelGuide { layer: "cumeadas".into(), field: None });
    }
    let mut read = Project::from_json(&serde_json::to_string(&s.project).unwrap()).unwrap();
    let said: Vec<String> =
        read.take_read_notices(&crate::project::ALL_PARTS).iter().map(|n| n.english()).filter(|n| n.contains("read in place")).collect();
    assert!(said.len() == 1 && said[0].contains("2 label guide(s) along 'cumeadas'"), "{said:?}");
    // Loaded whole, it guides.
    s.run("layer.loadAll", &json!({"layer": "cumeadas"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Lakes", "guide": {"layer": "cumeadas"}})).unwrap();
    let _ = std::fs::remove_file(path);
}

/// A guide (#2262) its labels can't follow as written, in a project written by hand: along a layer
/// that isn't there or has no lines, by a field one of the two layers lacks, or on a perpendicular
/// label (square to its line where one is near): said once a kind on opening; a clean one isn't.
#[test]
fn a_guide_its_labels_cant_follow_is_said_on_opening() {
    let guided = |s: &Session| {
        let mut read = Project::from_json(&serde_json::to_string(&s.project).unwrap()).unwrap();
        let said: Vec<String> = read.take_read_notices(&crate::project::ALL_PARTS).iter().map(|n| n.english()).collect();
        said.into_iter().filter(|n| n.contains("guide")).collect::<Vec<_>>()
    };
    let mut s = world();
    s.run("labels.placement", &json!({"layer": "Lakes", "guide": {"layer": "Rivers"}})).unwrap();
    assert!(guided(&s).is_empty(), "a clean guide isn't said: {:?}", guided(&s));
    let set = |s: &mut Session, name: &str, layer: &str, field: Option<&str>| {
        let l = s.map_mut().layers.iter_mut().find(|l| l.name == name).unwrap();
        l.labels.default.guide = Some(crate::map::LabelGuide { layer: layer.into(), field: field.map(Into::into) });
    };
    set(&mut s, "Lakes", "Serras", None);
    set(&mut s, "Countries", "Lakes", None);
    let said = guided(&s);
    assert!(said.len() == 1 && said[0].contains("2 label guide(s) along 'Lakes', 'Serras'"), "{said:?}");
    set(&mut s, "Lakes", "Rivers", Some("nome"));
    set(&mut s, "Countries", "Rivers", None);
    let said = guided(&s);
    assert!(said.len() == 1 && said[0].contains("1 label guide field(s)") && said[0].contains("'nome'"), "{said:?}");
    set(&mut s, "Lakes", "Rivers", None);
    s.run("labels.placement", &json!({"layer": "Cities", "position": "perpendicular", "to": {"layer": "Rivers"}})).unwrap();
    set(&mut s, "Cities", "Rivers", None);
    let said = guided(&s);
    assert!(said.len() == 1 && said[0].contains("1 perpendicular label class(es)"), "{said:?}");
}

/// A limited project-map import (#2262) audits the guides of the maps it keeps, as a full open does.
#[test]
fn a_limited_map_import_says_a_guide_it_cant_follow() {
    let mut s = world();
    let lakes = s.map_mut().layers.iter_mut().find(|l| l.name == "Lakes").unwrap();
    lakes.labels.default.guide = Some(crate::map::LabelGuide { layer: "Nowhere".into(), field: None });
    let text = serde_json::to_string(&s.project).unwrap();
    let mut read = Project::from_import_maps_json(&text, None, s.project.maps.len()).unwrap();
    let said: Vec<String> = read.take_read_notices(&crate::project::ALL_PARTS).iter().map(|n| n.english()).collect();
    assert!(said.iter().any(|n| n.contains("guide") && n.contains("Nowhere")), "{said:?}");
}

#[test]
fn rivers_are_labelled_along_their_lines_in_italics() {
    let mut s = world();
    s.run("labels.field", &json!({"layer": "Rivers", "field": "name"})).unwrap();
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "curved"})).unwrap();
    s.run("labels.style", &json!({"layer": "Rivers", "italic": true})).unwrap();
    let check = |s: &Session| {
        let c = &s.map().layer_by_name("Rivers").unwrap().labels.default;
        assert_eq!((c.placement, c.italic), (rustgis_map::LabelPlacement::Curved, true));
    };
    check(&s);
    let dir = std::env::temp_dir().join(format!("rustgis-line-labels-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("labels.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    check(&t);
    t.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    std::fs::remove_dir_all(&dir).ok();
    s.run("labels.placement", &json!({"layer": "Rivers", "position": "parallel"})).unwrap();
    assert_eq!(s.map().layer_by_name("Rivers").unwrap().labels.default.placement, rustgis_map::LabelPlacement::Parallel);
    // Not slanted unless asked: a project from before reads as upright.
    s.run("labels.style", &json!({"layer": "Rivers", "italic": false})).unwrap();
    let text = serde_json::to_string(&s.map().layer_by_name("Rivers").unwrap().labels).unwrap();
    assert!(!text.contains("italic"), "{text}");
}

/// A true/false parameter reads true, false, yes, no, on, off, 1 and 0 in any case; other text is
/// read as false and another number ignored, each named in one notice per command (#1600).
#[test]
fn unread_boolean_parameter_text_is_said() {
    let mut s = world();
    const SAID: &str = "Not read as true or false:";
    let unread = |s: &Session| s.notices.iter().filter(|n| n.text.starts_with(SAID)).count();
    let style = |s: &Session| {
        let c = &s.map().layer_by_name("Rivers").unwrap().labels.default;
        (c.bold, c.italic)
    };
    for (given, expect) in
        [("True", true), (" YES ", true), ("On", true), ("1", true), ("False", false), ("no", false), ("OFF", false), ("0", false)]
    {
        s.run("labels.style", &json!({"layer": "Rivers", "italic": given, "bold": given})).unwrap();
        assert_eq!(style(&s), (expect, expect), "{given}");
    }
    s.run("labels.style", &json!({"layer": "Rivers", "italic": 1, "bold": true})).unwrap();
    assert_eq!(style(&s), (true, true));
    s.run("labels.style", &json!({"layer": "Rivers", "italic": 0, "bold": 0.0})).unwrap();
    assert_eq!(style(&s), (false, false));
    s.run("labels.style", &json!({"layer": "Rivers", "italic": 1, "bold": true})).unwrap();
    assert_eq!(unread(&s), 0, "clean input gives no notice: {:?}", s.notices.last());
    s.run("labels.style", &json!({"layer": "Rivers", "italic": "auto", "bold": "ture"})).unwrap();
    assert_eq!(style(&s), (false, false));
    assert_eq!(unread(&s), 1, "{:?}", s.notices.last());
    let said = s.notices.iter().find(|n| n.text.starts_with(SAID)).map(|n| n.text.clone()).unwrap();
    assert!(said.contains("italic = \"auto\" (read as false)") && said.contains("bold = \"ture\" (read as false)"), "{said}");
    // A number other than 1 or 0 leaves the setting as it was, and says so.
    s.run("labels.style", &json!({"layer": "Rivers", "italic": true})).unwrap();
    s.run("labels.style", &json!({"layer": "Rivers", "italic": 5})).unwrap();
    assert_eq!(style(&s), (false, true));
    assert_eq!(unread(&s), 2, "{:?}", s.notices.last());
    assert!(s.notices.iter().any(|n| n.text.contains("italic = 5 (ignored)")), "{:?}", s.notices.last());
    // A long value is said by its length, not quoted in part; ten distinct values name eight
    // and count the rest once each, however often a command reads them.
    let long = "k".repeat(41);
    s.run("labels.style", &json!({"layer": "Rivers", "italic": long})).unwrap();
    let said = s.notices.iter().rev().find(|n| n.text.starts_with(SAID)).map(|n| n.text.clone()).unwrap();
    assert!(said.contains("italic = a value of 41 characters (read as false)") && !said.contains("kkk"), "{said}");
    let p: Value = (0..10).map(|i| (format!("k{i}"), json!(format!("v{i}")))).collect::<serde_json::Map<_, _>>().into();
    crate::cmd::clear_unread_bools();
    for _ in 0..3 {
        for i in 0..10 {
            assert_eq!(crate::cmd::b(&p, &format!("k{i}")), Some(false));
        }
    }
    let said = crate::cmd::take_unread_bools().unwrap();
    assert!(said.contains("k7 = \"v7\"") && !said.contains("k8 =") && said.contains(", 2 more ("), "{said}");
    // The next clean command says nothing more.
    let before = unread(&s);
    s.run("labels.style", &json!({"layer": "Rivers", "italic": true})).unwrap();
    assert_eq!(unread(&s), before);
}

#[test]
fn a_qgis_project_in_degrees_opens_in_equirectangular() {
    // QGIS draws a project in degrees as plate carrée, longitude and latitude as x and y.
    // A PROJ string goes where QGIS keeps it for a system without an authority code.
    let qgs = |crs: &str| {
        let tag = if crs.starts_with('+') { "proj4" } else { "authid" };
        format!(
            r#"<qgis version="3.10.0"><title>World</title><projectCrs><spatialrefsys><{tag}>{crs}</{tag}></spatialrefsys></projectCrs>
  <mapcanvas name="theMapCanvas"><extent><xmin>5</xmin><ymin>45</ymin><xmax>15</xmax><ymax>50</ymax></extent></mapcanvas><projectlayers/></qgis>"#
        )
    };
    let mut s = world();
    for (crs, datum_note) in [
        ("EPSG:4326", false),
        ("EPSG:4258", false),
        ("OGC:CRS84", false),
        ("EPSG:4314", true),
        // Saved without an authority code: its PROJ string.
        ("+proj=longlat +datum=WGS84 +no_defs", false),
        ("+proj=longlat +datum=WGS84 +pm=0.0 +no_defs", false),
        ("+proj=longlat +ellps=bessel +towgs84=598.1,73.7,418.2,0.202,0.045,-2.455,6.7 +no_defs", true),
    ] {
        let out = s.run("project.importQgis", &json!({"text": qgs(crs)})).unwrap();
        assert_eq!(s.map().projection.code(), "equirectangular", "{crs}");
        let text = serde_json::to_string(&out["notes"]).unwrap();
        assert!(!text.contains("Web Mercator"), "{crs}: {text}");
        assert_eq!(text.contains("drawn in Equirectangular on WGS 84"), datum_note, "{crs}: {text}");
        // The saved view, read in degrees.
        let c = s.map().to_lonlat(s.map().camera.center).unwrap();
        assert!((c.x - 10.0).abs() < 0.5 && (c.y - 47.5).abs() < 0.5, "{crs}: {c:?}");
    }
    // Longitudes from Paris (in grads): drawn the same way, the view left to the data.
    let out = s.run("project.importQgis", &json!({"text": qgs("EPSG:4807")})).unwrap();
    assert_eq!(s.map().projection.code(), "equirectangular");
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("on WGS 84") && text.contains("from Greenwich"), "{text}");
    // A projected one keeps its own projection.
    s.run("project.importQgis", &json!({"text": qgs("EPSG:2056").replace("<xmin>5</xmin>", "<xmin>2600000</xmin>")})).unwrap();
    assert_eq!(s.map().projection.code(), "EPSG:2056");
}

#[test]
fn a_qgis_project_with_a_geographic_proj_string_keeps_its_saved_view() {
    for (crs, datum_note, saved_view) in [
        ("+proj=longlat +datum=WGS84", false, true),
        ("+proj=latlong +datum=WGS84", false, true),
        ("+proj=lonlat +datum=WGS84", false, true),
        ("+proj=latlon +datum=WGS84", false, true),
        ("  +datum=WGS84 +proj=longlat +no_defs", false, true),
        ("+proj=longlat +datum=potsdam", true, true),
        ("+proj=longlat +datum=WGS84 +pm=paris", true, false),
    ] {
        let text = format!(
            r#"<qgis><projectCrs><spatialrefsys><authid></authid><proj4>{crs}</proj4></spatialrefsys></projectCrs>
<mapcanvas><extent><xmin>5</xmin><ymin>45</ymin><xmax>15</xmax><ymax>50</ymax></extent></mapcanvas><projectlayers/></qgis>"#
        );
        let mut s = world();
        let out = s.run("project.importQgis", &json!({"text": text})).unwrap();
        assert_eq!(s.map().projection.code(), "equirectangular", "{crs}");
        let notes = serde_json::to_string(&out["notes"]).unwrap();
        assert!(!notes.contains("Web Mercator"), "{crs}: {notes}");
        assert_eq!(notes.contains("drawn in Equirectangular on WGS 84"), datum_note, "{crs}: {notes}");
        let c = s.map().to_lonlat(s.map().camera.center).unwrap();
        assert_eq!((c.x - 10.0).abs() < 0.5 && (c.y - 47.5).abs() < 0.5, saved_view, "{crs}: {c:?}");
    }
}

#[test]
fn a_qgis_project_opens_as_a_map_and_a_qgis_style_styles_a_layer() {
    let dir = std::env::temp_dir().join(format!("rustgis-qgis-{}", std::process::id()));
    std::fs::create_dir_all(dir.join("data")).unwrap();
    let roads = r#"{"type":"FeatureCollection","features":[
        {"type":"Feature","properties":{"class":"motorway","name":"A1","lanes":3},"geometry":{"type":"LineString","coordinates":[[8.70,47.49],[8.75,47.51]]}},
        {"type":"Feature","properties":{"class":"track","name":"Feldweg","lanes":1},"geometry":{"type":"LineString","coordinates":[[8.71,47.50],[8.74,47.48]]}}]}"#;
    std::fs::write(dir.join("data/roads.geojson"), roads).unwrap();
    std::fs::write(dir.join("data/towns.csv"), "name,lon,lat\nWinterthur,8.72,47.50\n").unwrap();
    let qgs = r#"<!DOCTYPE qgis PUBLIC 'http://mrcc.com/qgis.dtd' 'SYSTEM'>
<qgis version="3.42.0"><title>Winterthur</title>
  <projectCrs><spatialrefsys><authid>EPSG:2056</authid></spatialrefsys></projectCrs>
  <layer-tree-group><layer-tree-layer id="t" checked="Qt::Checked"/><layer-tree-layer id="r" checked="Qt::Unchecked"/><layer-tree-layer id="db" checked="Qt::Checked"/></layer-tree-group>
  <mapcanvas name="theMapCanvas"><extent><xmin>0</xmin><ymin>0</ymin><xmax>10</xmax><ymax>10</ymax></extent></mapcanvas>
  <projectlayers>
    <maplayer type="vector" labelsEnabled="1"><id>r</id><datasource>./data/roads.geojson|subset="lanes" &gt; 0</datasource><layername>Roads</layername><provider>ogr</provider>
      <renderer-v2 type="categorizedSymbol" attr="class" referencescale="25000"><categories><category value="motorway" symbol="0" render="true"/><category value="" symbol="1" render="true"/></categories>
        <symbols><symbol type="line" name="0" alpha="1"><layer class="SimpleLine" enabled="1"><prop k="line_color" v="0,0,0,255"/><prop k="line_width" v="1"/></layer><layer class="SimpleLine" enabled="1"><prop k="line_color" v="250,150,50,255"/><prop k="line_width" v="0.6"/></layer></symbol>
        <symbol type="line" name="1" alpha="1"><layer class="SimpleLine" enabled="1"><prop k="line_color" v="120,120,120,255"/></layer></symbol></symbols></renderer-v2>
      <labeling type="rule-based"><rules key="x"><rule filter="&quot;class&quot; = 'motorway'" description="Big"><settings><text-style fieldName="name" fontSize="9" namedStyle="Italic"/><placement placement="2"/></settings></rule>
        <rule filter="&quot;nofield&quot; = 1" description="Broken"><settings><text-style fieldName="name"/></settings></rule></rules></labeling></maplayer>
    <maplayer type="vector"><id>t</id><datasource>file:./data/towns.csv?type=csv&amp;xField=lon&amp;yField=lat&amp;crs=EPSG:4326</datasource><layername>Towns</layername><provider>delimitedtext</provider>
      <renderer-v2 type="singleSymbol"><symbols><symbol type="marker" name="0" alpha="1"><layer class="SimpleMarker" enabled="1"><prop k="name" v="square"/><prop k="color" v="200,0,0,255"/></layer></symbol></symbols></renderer-v2></maplayer>
    <maplayer type="vector"><id>db</id><datasource>dbname='gis' host=db password='secret' table="public"."parcels" (geom)</datasource><layername>Parcels</layername><provider>postgres</provider></maplayer>
  </projectlayers></qgis>"#;
    let path = dir.join("winterthur.qgs");
    std::fs::write(&path, qgs).unwrap();
    let mut s = world();
    let maps = s.project.maps.len();
    let depth = s.undo_depth();
    let out = s.run("project.importQgis", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!((s.project.maps.len(), s.map().name.as_str()), (maps + 1, "Winterthur"), "a map of its own");
    assert_eq!(s.undo_depth(), depth + 1, "one step");
    assert_eq!(s.map().projection.code(), "EPSG:2056");
    assert_eq!(s.map().basemap, rustgis_map::Basemap::Blank);
    let names: Vec<&str> = s.map().layers.iter().map(|l| l.name.as_str()).collect();
    assert_eq!(names, ["Towns", "Roads"], "top first; the database table isn't added");
    let roads = s.map().layer_by_name("Roads").unwrap();
    assert!(!roads.visible, "unchecked in the layer tree");
    assert_eq!(roads.definition_query.as_deref(), Some("\"lanes\" > 0"));
    assert!(roads.reference_scale.is_some());
    let rustgis_map::Renderer::Unique { field, class_strokes, .. } = &roads.renderer else { panic!("{:?}", roads.renderer) };
    assert_eq!((field.as_str(), class_strokes.get("motorway").map(Vec::len)), ("class", Some(2)));
    let classes: Vec<(&str, bool)> = roads.labels.classes.iter().map(|c| (c.name.as_str(), c.visible)).collect();
    assert_eq!(classes, [("Big", true), ("Broken", false)], "a clause the layer can't read is switched off");
    assert_eq!(roads.labels.classes[0].placement, rustgis_map::LabelPlacement::Parallel);
    let towns = s.map().layer_by_name("Towns").unwrap();
    assert_eq!((towns.dataset.features.len(), towns.renderer.base_symbol().marker), (1, rustgis_map::Marker::Square));
    // What wasn't carried over: the database table, with no password in the note.
    let notes = out["notes"].as_array().unwrap();
    let text = serde_json::to_string(notes).unwrap();
    assert!(text.contains("parcels") && !text.contains("secret"), "{text}");
    assert!(text.contains("Broken"), "{text}");
    // Drawn, and gone again with one undo.
    s.run("share.exportMap", &json!({"path": dir.join("map.png").display().to_string(), "width": 320, "height": 200})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.maps.len(), maps);

    // A style file on a sample layer: Rivers drawn as a cased line.
    let qml = r#"<!DOCTYPE qgis PUBLIC 'http://mrcc.com/qgis.dtd' 'SYSTEM'><qgis version="3.22"><renderer-v2 type="singleSymbol"><symbols><symbol type="line" name="0" alpha="1">
        <layer class="SimpleLine" enabled="1"><Option type="Map"><Option name="line_color" value="20,60,120,255"/><Option name="line_width" value="1.2"/></Option></layer>
        <layer class="SimpleLine" enabled="1"><Option type="Map"><Option name="line_color" value="150,200,255,255"/><Option name="line_width" value="0.5"/></Option></layer>
        </symbol></symbols></renderer-v2><layerOpacity>0.5</layerOpacity></qgis>"#;
    s.run("style.importQgis", &json!({"layer": "Rivers", "text": qml})).unwrap();
    let rivers = s.map().layer_by_name("Rivers").unwrap();
    assert_eq!((rivers.line_strokes.len(), rivers.transparency), (2, 50.0));
    // A raster's style on a feature layer says its colouring is left out.
    let qml = r#"<qgis version="4.2.3" layerType="Raster"><pipe><rasterrenderer type="singlebandgray" grayBand="1"/></pipe></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "Rivers", "text": qml})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("a raster's colouring"), "{out}");
    assert!(s.run("style.importQgis", &json!({"layer": "Rivers", "text": "<nonsense"})).is_err());
    // A style saved from another layer: classes and labels by fields Rivers hasn't are noted, and
    // the label class that has nothing to label from is switched off.
    let qml = r#"<qgis version="3.22" labelsEnabled="1"><renderer-v2 type="categorizedSymbol" attr="nofield"><categories><category value="a" symbol="0" render="true"/></categories>
        <symbols><symbol type="line" name="0" alpha="1"><layer class="SimpleLine" enabled="1"><prop k="line_color" v="0,0,0,255"/></layer></symbol></symbols></renderer-v2>
        <labeling type="simple"><settings><text-style fieldName="nolabelfield"/></settings></labeling></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "Rivers", "text": qml})).unwrap();
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("nofield") && text.contains("nolabelfield"), "{text}");
    let rivers = s.map().layer_by_name("Rivers").unwrap();
    assert!(rivers.labels.classes.iter().chain(std::iter::once(&rivers.labels.default)).all(|c| c.field != "nolabelfield" || !c.visible));
    // A project's web layer keeps its visibility and opacity; its scale range is noted.
    let qgs = r#"<qgis version="3.42.0"><title>Web</title>
  <layer-tree-group><layer-tree-layer id="x" checked="Qt::Unchecked"/></layer-tree-group>
  <projectlayers><maplayer type="raster" hasScaleBasedVisibilityFlag="1" minScale="100000" maxScale="1000"><id>x</id><datasource>type=xyz&amp;url=https://tiles.example/%7Bz%7D/%7Bx%7D/%7By%7D.png&amp;zmax=19&amp;zmin=0</datasource><layername>Tiles</layername><provider>wms</provider>
    <pipe><rasterrenderer opacity="0.25" type="singlebandcolordata"/></pipe><blendMode>6</blendMode></maplayer></projectlayers></qgis>"#;
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let t = s.map().tiles.iter().find(|t| t.name == "Tiles").expect("the web layer is added");
    assert!(!t.visible, "unchecked in the layer tree");
    assert!((t.opacity - 0.25).abs() < 1e-6, "{}", t.opacity);
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("scale range"), "{text}");
    // Web layers are overlays, so they stay in the tree's order, and take the layer's blending.
    let t = s.map().tiles.iter().find(|t| t.name == "Tiles").unwrap();
    assert!(t.overlay);
    assert_eq!(t.blend, rustgis_map::effects::Blend::Multiply);
    // A layer of no provider is noted by its kind; an annotation layer, even an empty one, is a
    // graphics layer.
    let qgs = r#"<qgis version="3.42.0"><title>Notes</title><projectlayers><maplayer type="annotation"><id>a</id><layername>Notes</layername></maplayer>
      <maplayer type="tiled-scene"><id>b</id><layername>Scene</layername></maplayer></projectlayers></qgis>"#;
    let out = s.run("project.importQgis", &json!({"text": qgs})).unwrap();
    let text = serde_json::to_string(&out["notes"]).unwrap();
    assert!(text.contains("doesn't read QGIS's tiled-scene layers"), "{text}");
    assert!(s.map().layer_by_name("Notes").is_some_and(|l| l.graphics && l.dataset.features.is_empty()));
    // A project given as text with no folder: a relative path is noted, not looked for in the
    // working directory.
    let rel = r#"<qgis version="3.42.0"><projectlayers><maplayer type="vector"><id>a</id><datasource>./data/roads.geojson</datasource><layername>Rel</layername><provider>ogr</provider></maplayer></projectlayers></qgis>"#;
    for p in [json!({"text": rel}), json!({"text": rel, "dir": "  "})] {
        let out = s.run("project.importQgis", &p).unwrap();
        assert!(out["layers"].as_array().unwrap().is_empty(), "{p}");
        let text = serde_json::to_string(&out["notes"]).unwrap();
        assert!(text.contains("pass dir"), "{text}");
    }
    // XML past what's parsed (64 MiB) is refused before parsing.
    assert!(s.run("project.importQgis", &json!({"text": " ".repeat((64 << 20) + 1)})).is_err());
    // A path relative to a drive's working directory is noted, with or without a folder.
    let drive = rel.replace("./data/roads.geojson", "C:roads.geojson");
    let out = s.run("project.importQgis", &json!({"text": drive, "dir": dir.display().to_string()})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("drive"), "{out}");
    // A web layer a service offers as features or a coverage comes in as a map layer, which takes
    // the QGIS layer's visibility, opacity, blending and scale range.
    let web = r#"<qgis version="3.42.0"><layer-tree-group><layer-tree-layer id="w" checked="Qt::Unchecked"/></layer-tree-group><projectlayers>
        <maplayer type="raster" hasScaleBasedVisibilityFlag="1" minScale="100000" maxScale="1000"><id>w</id><datasource>url=https://wms.example/wms&amp;layers=a</datasource><layername>Web</layername><provider>wms</provider>
        <pipe><rasterrenderer opacity="0.5" type="singlebandcolordata"/></pipe><blendMode>6</blendMode></maplayer></projectlayers></qgis>"#;
    let mut report = rustgis_map::qgis::Report::default();
    let project = rustgis_map::qgis::read_project(web, "", &mut |_| Err("whose image file doesn't open"), &mut report).unwrap();
    let mut w = world();
    let before = w.active_layer;
    w.active_layer = w.map().layers.iter().map(|l| l.id).find(|id| Some(*id) != before);
    crate::cmd::qgis::web_settings(&mut w, &json!({"name": "Web"}), before, &project.layers[0], &mut report);
    let l = w.map().layers.iter().find(|l| Some(l.id) == w.active_layer).unwrap();
    assert!(!l.visible);
    assert_eq!((l.transparency, l.blend), (50.0, rustgis_map::effects::Blend::Multiply));
    assert!(l.min_scale.is_some() && l.max_scale.is_some());
    // Plugins can't run the import: a project names files and web addresses its layers come from.
    assert!(crate::cmd::plugins::user_only("project.importQgis"));
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn project_save_and_open_roundtrip() {
    let mut s = world();
    let dir = std::env::temp_dir().join(format!("rustgis-test-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("atlas.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!(t.map().layers.len(), 4);
    let png = dir.join("map.png");
    t.run("share.exportMap", &json!({"path": png.display().to_string(), "width": 320, "height": 200})).unwrap();
    assert!(std::fs::metadata(&png).unwrap().len() > 1000);
    std::fs::remove_dir_all(&dir).ok();
}

/// RustGIS files are read only from regular files: a device that reports no size and never ends
/// (`/dev/zero`) would exhaust memory, and a named pipe without a writer would hang the reader.
#[cfg(unix)]
#[test]
fn item_files_refuse_devices_and_pipes() {
    let dir = std::env::temp_dir().join(format!("rustgis-item-pipe-{}", std::process::id()));
    std::fs::remove_dir_all(&dir).ok();
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    for (id, name) in [
        ("style.add", "styles.rgisstyle"),
        ("report.open", "report.rgisreport"),
        ("project.open", "p.rgis"),
        ("project.open", "p.rgispkg"),
        ("project.importQgis", "q.qgz"),
        ("layout.import", "l.rgislayout"),
        ("dl.import", "m.rgisdlpk"),
        ("layer.addData", "l.rgislyr"),
    ] {
        let fifo = dir.join(name);
        assert!(std::process::Command::new("mkfifo").arg(&fifo).status().unwrap().success());
        for path in [std::path::Path::new("/dev/zero"), fifo.as_path()] {
            if id == "layer.addData" && path == std::path::Path::new("/dev/zero") {
                continue; // Without its extension it isn't read as a layer file.
            }
            let error = s.run(id, &json!({"path": path})).unwrap_err();
            assert!(error.contains("isn't a file"), "{id} {}: {error}", path.display());
        }
    }
    std::fs::remove_dir_all(&dir).ok();
}

/// Save As and packaging must not replace readable files with a project above the opening limit.
#[test]
fn oversized_project_save_preserves_file_and_live_state() {
    let dir = std::env::temp_dir().join(format!("rustgis-save-limit-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("existing.rgis");
    let mut s = world();
    s.run("project.saveAs", &json!({"path": path})).unwrap();
    let original = std::fs::read(&path).unwrap();
    let package = dir.join("existing.rgispkg");
    s.run("project.package", &json!({"path": package})).unwrap();
    let original_package = std::fs::read(&package).unwrap();
    s.run("project.rename", &json!({"name": "Unsaved work"})).unwrap();
    let source = dir.join("roads.geojson").display().to_string();
    s.project.maps[0].layers[0].dataset.source = Some(source.clone());
    // A single large value reaches the limit without a large data fixture on disk; the limit is
    // held at 1 MiB here, as it follows this computer's memory (#1615).
    let max = 1 << 20;
    s.project.thumbnail = Some("x".repeat(max as usize));
    let (error, package_error) = crate::project::with_max_bytes(max, || {
        (s.run("project.saveAs", &json!({"path": path})).unwrap_err(), s.run("project.package", &json!({"path": package})).unwrap_err())
    });
    assert!(error.contains("too large to save (maximum 1 MiB"), "{error}");
    assert!(package_error.contains("too large"), "{package_error}");
    assert_eq!(std::fs::read(&path).unwrap(), original);
    assert_eq!(std::fs::read(&package).unwrap(), original_package);
    assert_eq!(s.project.name, "Unsaved work");
    assert_eq!(s.project.maps[0].layers[0].dataset.source.as_deref(), Some(source.as_str()));
    assert_eq!(s.path.as_deref(), Some(path.as_path()));
    assert!(s.dirty(), "a failed save must not mark the project saved");
    s.project.thumbnail = None;
    s.run("project.saveAs", &json!({"path": path})).unwrap();
    assert!(!s.dirty());
    assert!(Project::load(&path).is_ok());
    std::fs::remove_dir_all(&dir).unwrap();
}

/// The project limit follows the computer's memory (#1615): a project as large as the limit saves
/// and opens again on the same computer, and one past it is refused before it is read, saying its
/// size and the limit.
#[test]
fn a_project_within_the_limit_saves_and_opens_and_one_past_it_says_both_sizes() {
    let dir = std::env::temp_dir().join(format!("rustgis-project-limit-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("near.rgis");
    let max: u64 = 2 << 20;
    let mut s = world();
    let small = {
        s.run("project.saveAs", &json!({"path": path})).unwrap();
        std::fs::metadata(&path).unwrap().len()
    };
    // Just under the limit: written and read back whole, the same limit both ways.
    s.project.thumbnail = Some("x".repeat((max - small - 1024) as usize));
    crate::project::with_max_bytes(max, || {
        s.run("project.saveAs", &json!({"path": path})).unwrap();
        assert!(std::fs::metadata(&path).unwrap().len() <= max);
        assert_eq!(Project::load(&path).unwrap().thumbnail.map(|t| t.len()), s.project.thumbnail.as_ref().map(|t| t.len()));
    });
    // Past it (as a project saved on a computer with more memory): refused, saying both sizes.
    let big = dir.join("big.rgis");
    std::fs::write(&big, vec![b' '; (3 << 20) as usize]).unwrap();
    let e = crate::project::with_max_bytes(max, || Project::load(&big).unwrap_err());
    assert!(e.contains("is 3 MiB, more than a project can be (maximum 2 MiB"), "{e}");
    let e = crate::project::with_max_bytes(max, || crate::project::check_format(&" ".repeat(3 << 20), "project").unwrap_err());
    assert!(e.contains("too large (maximum 2 MiB"), "{e}");
    // Import Maps reads a project file under the same limit: the one saved above, not the one past it.
    crate::project::with_max_bytes(max, || {
        assert!(crate::cmd::items::read_text(&json!({"path": path})).is_ok());
        let e = crate::cmd::items::read_text(&json!({"path": big})).unwrap_err();
        assert!(e.contains("too large"), "{e}");
    });
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn project_extension_is_rgis_and_legacy_rgisx_opens() {
    let mut s = world();
    let dir = std::env::temp_dir().join(format!("rustgis-ext-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    s.run("project.saveAs", &json!({"path": dir.join("atlas").display().to_string()})).unwrap();
    let saved = dir.join("atlas.rgis");
    assert!(saved.exists(), "a path without an extension gets .rgis");
    let legacy = dir.join("old.rgisx");
    std::fs::copy(&saved, &legacy).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": legacy.display().to_string()})).unwrap();
    assert_eq!(t.map().layers.len(), 4);
    for (name, is) in [("a.rgis", true), ("A.RGISX", true), ("a.rgismap", false), ("a.rgispkg", false), ("rgis", false)] {
        assert_eq!(crate::project::is_project_file(name), is, "{name}");
    }
    for (name, opens) in [("a.rgis", true), ("A.RGISPKG", true), ("rgispkg", false), ("a.geojson", false), ("a.rgismap", false)] {
        assert_eq!(crate::project::opens_as_project(name), opens, "{name}");
    }
    assert_eq!(crate::project::open_command("dir/a.geojson"), "layer.addData");
    std::fs::remove_dir_all(&dir).ok();
}

/// Save and Save As write only to a project file: a data file or a package path is refused and
/// left as it was, with the session unchanged, while any case of `.rgis`/`.rgisx` saves.
/// Opening project JSON under another extension never exempts that path from validation.
#[test]
fn save_refuses_a_path_that_isnt_a_project_file() {
    let dir = std::env::temp_dir().join(format!("rustgis-save-ext-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    let first = dir.join("atlas.rgis");
    s.run("project.saveAs", &json!({"path": first})).unwrap();
    let name = s.project.name.clone();
    let data = dir.join("roads.geojson");
    std::fs::write(&data, b"keep this data").unwrap();
    let e = s.run("project.saveAs", &json!({"path": data})).unwrap_err();
    assert!(e.contains("a .rgis file, not a .geojson one"), "{e}");
    let e = s.run("project.save", &json!({"path": dir.join("data.GPKG")})).unwrap_err();
    assert!(e.contains("not a .gpkg one"), "{e}");
    // A bare trailing dot, or a folder named like a project, is refused without naming an extension.
    for odd in ["foo.", "a.rgis.", "atlas.rgis/"] {
        let e = s.run("project.saveAs", &json!({"path": format!("{}/{odd}", dir.display())})).unwrap_err();
        assert_eq!(e, "a project saves to a .rgis file", "{odd}");
    }
    let package = dir.join("atlas.rgispkg");
    let e = s.run("project.saveAs", &json!({"path": package})).unwrap_err();
    assert!(e.contains("project.package"), "{e}");
    assert_eq!(std::fs::read(&data).unwrap(), b"keep this data");
    assert!(!package.exists() && !dir.join("data.GPKG").exists());
    assert_eq!(s.path.as_deref(), Some(first.as_path()));
    assert_eq!(s.project.name, name, "a refused Save As keeps the project's name");
    for ok in ["Upper.RGIS", "old.rgisx"] {
        s.run("project.saveAs", &json!({"path": dir.join(ok)})).unwrap();
        assert!(Project::load(&dir.join(ok)).is_ok(), "{ok}");
    }
    // Opening project JSON under another extension does not permit overwriting it.
    let kept = dir.join("atlas.json");
    std::fs::copy(&first, &kept).unwrap();
    s.run("project.open", &json!({"path": kept})).unwrap();
    s.run("project.rename", &json!({"name": "renamed"})).unwrap();
    let before = std::fs::read(&kept).unwrap();
    assert!(s.run("project.save", &Value::Null).is_err());
    assert!(s.run("project.saveAs", &json!({"path": kept})).is_err());
    assert_eq!(std::fs::read(&kept).unwrap(), before);
    assert_eq!(s.project.name, "renamed");
    assert!(s.dirty());
    assert_eq!(s.path.as_deref(), Some(kept.as_path()));
    std::fs::remove_dir_all(&dir).ok();
}

/// A table file picked inside a File Geodatabase stands for the geodatabase, in `layer.addData`
/// and `info.fileLayers` alike; through GDAL when it is installed.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_file_inside_a_geodatabase_adds_the_geodatabase() {
    let dir = std::env::temp_dir().join(format!("rustgis-gdb-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let gdb = dir.join("roads.gdb");
    let table = gdb.join("a00000001.gdbtable").display().to_string();
    let mut s = Session::new(Project::default());
    if rustgis_data::source::gdal::test_runs().unwrap() {
        let geojson = dir.join("cities.geojson");
        std::fs::write(
            &geojson,
            r#"{"type":"FeatureCollection","features":[
{"type":"Feature","properties":{"name":"a"},"geometry":{"type":"Point","coordinates":[8.5,47.4]}},
{"type":"Feature","properties":{"name":"b"},"geometry":{"type":"Point","coordinates":[7.4,46.9]}}]}"#,
        )
        .unwrap();
        let made = std::process::Command::new("ogr2ogr")
            .args(["-f", "OpenFileGDB", "-nln", "cities"])
            .arg(&gdb)
            .arg(&geojson)
            .status()
            .is_ok_and(|st| st.success());
        if made {
            let listed = s.run("info.fileLayers", &json!({"path": table})).unwrap();
            assert_eq!(listed["layers"], json!(["cities"]), "{listed}");
            let added = s.run("layer.addData", &json!({"path": table})).unwrap();
            assert_eq!(added["features"], json!(2), "{added}");
            std::fs::remove_dir_all(&dir).ok();
            return;
        }
    }
    // Without GDAL the geodatabase can't be read, but the error names it, not the table.
    std::fs::create_dir_all(&gdb).unwrap();
    std::fs::write(&table, b"").unwrap();
    for cmd in ["layer.addData", "info.fileLayers"] {
        let e = s.run(cmd, &json!({"path": table})).unwrap_err();
        assert!(e.contains("roads.gdb") && !e.contains("gdbtable"), "{cmd}: {e}");
    }
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn save_clears_dirty_and_open_clears_history() {
    let mut s = world();
    assert!(!s.dirty() && !s.can_undo(), "a fresh sample is clean");
    s.run("layer.color", &json!({"layer": "Countries", "color": "#336699"})).unwrap();
    assert!(s.dirty() && s.can_undo());
    let dir = std::env::temp_dir().join(format!("rustgis-dirty-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("a.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    assert!(!s.dirty(), "saving clears the dirty marker");
    assert!(s.can_undo(), "saving keeps the edit history");
    s.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert!(!s.dirty() && !s.can_undo() && !s.can_redo(), "opening starts a fresh history");
    assert!(s.run("edit.undo", &Value::Null).is_err());
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn degenerate_geometry_and_deleted_fields() {
    let mut s = world();
    for g in [
        json!({"type": "LineString", "coordinates": [[0, 0]]}),
        json!({"type": "MultiPoint", "coordinates": []}),
        json!({"type": "MultiPolygon", "coordinates": []}),
    ] {
        let layer = if g["type"] == "LineString" {
            "Rivers"
        } else if g["type"] == "MultiPoint" {
            "Cities"
        } else {
            "Countries"
        };
        assert!(s.run("edit.addFeature", &json!({"layer": layer, "geometry": g})).is_err(), "{g}");
    }
    // A field the definition query or a display filter reads isn't deleted: without it, they
    // would stop reading and the layer would show the rows they leave out.
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": "pop_est > 1000"})).unwrap();
    let e = s.run("edit.deleteField", &json!({"layer": "Countries", "field": "pop_est"})).unwrap_err();
    assert!(e.contains("definition query (pop_est > 1000) uses 'pop_est'"), "{e}");
    assert_eq!(s.map().layer_by_name("Countries").unwrap().definition_query.as_deref(), Some("pop_est > 1000"));
    // A field the query doesn't read is deleted, and the query keeps the same rows.
    let shown = |s: &Session| s.map().layer_by_name("Countries").unwrap().visible_rows().iter().filter(|v| **v).count();
    let rows = shown(&s);
    s.run("edit.addField", &json!({"layer": "Countries", "name": "spare", "type": "text"})).unwrap();
    s.run("edit.deleteField", &json!({"layer": "Countries", "field": "spare"})).unwrap();
    assert_eq!(shown(&s), rows);
    s.run("layer.definitionQuery", &json!({"layer": "Countries", "where": ""})).unwrap();
    // A query that already didn't read (as an imported project can hold) is kept, text and all,
    // when another field is deleted.
    let broken = Some("no_such_field > 1".to_string());
    s.map_mut().layers.iter_mut().filter(|l| l.name == "Countries").for_each(|l| l.definition_query = broken.clone());
    s.run("edit.addField", &json!({"layer": "Countries", "name": "spare2", "type": "text"})).unwrap();
    s.run("edit.deleteField", &json!({"layer": "Countries", "field": "spare2"})).unwrap();
    assert_eq!(s.map().layer_by_name("Countries").unwrap().definition_query, broken);
    s.map_mut().layers.iter_mut().filter(|l| l.name == "Countries").for_each(|l| l.definition_query = None);
    let filters = json!({"layer": "Countries", "filters": [{"name": "Big", "where": "pop_est > 1000"}]});
    s.run("layer.displayFilters", &filters).unwrap();
    let e = s.run("edit.deleteField", &json!({"layer": "Countries", "field": "pop_est"})).unwrap_err();
    assert!(e.contains("display filter 'Big' uses 'pop_est'"), "{e}");
    // A field the display filter doesn't read is deleted, and the filter is kept as it was.
    s.run("edit.addField", &json!({"layer": "Countries", "name": "spare3", "type": "text"})).unwrap();
    s.run("edit.deleteField", &json!({"layer": "Countries", "field": "spare3"})).unwrap();
    let kept = &s.map().layer_by_name("Countries").unwrap().display_filters;
    assert!(kept.len() == 1 && kept[0].where_ == "pop_est > 1000");
    let l = s.map().layer_by_name("Countries").unwrap();
    assert!(l.dataset.field_index("pop_est").is_some() && l.display_filters.len() == 1);
    s.run("layer.displayFilters", &json!({"layer": "Countries", "filters": []})).unwrap();
    // Two fields named the same but for case: the query reads the first, which deleting `pop`
    // removes; it would otherwise go on to read the second without a word.
    s.run("layer.addDataText", &json!({"fileName": "twins.csv", "text": "lon,lat,Pop,pop\n1,2,5,0\n3,4,0,5\n"})).unwrap();
    s.run("layer.definitionQuery", &json!({"layer": "twins", "where": "pop > 1"})).unwrap();
    let e = s.run("edit.deleteField", &json!({"layer": "twins", "field": "pop"})).unwrap_err();
    assert!(e.contains("definition query (pop > 1) uses 'Pop'"), "{e}");
    // The same with a field named like a keyword: `null` reads the field `Null` while it exists,
    // and would read the other one once it is gone.
    s.run("layer.addDataText", &json!({"fileName": "keywords.csv", "text": "lon,lat,Null,null\n1,2,5,0\n3,4,0,5\n"})).unwrap();
    s.run("layer.definitionQuery", &json!({"layer": "keywords", "where": "null = 5"})).unwrap();
    let e = s.run("edit.deleteField", &json!({"layer": "keywords", "field": "null"})).unwrap_err();
    assert!(e.contains("definition query (null = 5) uses 'Null'"), "{e}");
    s.run("edit.deleteField", &json!({"layer": "Countries", "field": "pop_est"})).unwrap();
    let l = s.map().layer_by_name("Countries").unwrap();
    assert_eq!(l.renderer.kind_label(), "Single Symbol");
    s.run("edit.deleteField", &json!({"layer": "Countries", "field": "name"})).unwrap();
    assert!(!s.map().layer_by_name("Countries").unwrap().labels.enabled);
}

#[test]
fn open_from_text() {
    let mut s = world();
    let text = serde_json::to_string(&s.project).unwrap();
    s.run("layer.addDataText", &json!({"fileName": "pts.csv", "text": "name,lon,lat\nA,1,2\n"})).unwrap();
    assert!(s.map().layer_by_name("pts").is_some());
    assert!(s.run("layer.addDataText", &json!({"fileName": "x.shp", "text": ""})).is_err());
    assert!(s.run("layer.addDataText", &json!({"fileName": "x.geojson", "text": "{"})).is_err());
    assert!(s.run("project.openText", &json!({"text": "not json"})).is_err());
    s.run("project.openText", &json!({"text": text})).unwrap();
    assert!(s.map().layer_by_name("pts").is_none() && !s.dirty() && !s.can_undo());
}

#[test]
fn opened_project_is_named_after_its_file() {
    // Issue #197: a project saved from the sample and renamed kept the sample's name.
    let mut s = world();
    let text = serde_json::to_string(&s.project).unwrap();
    s.run("project.openText", &json!({"text": text, "fileName": "test.rgis"})).unwrap();
    assert_eq!(s.project.name, "test");
    s.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(s.project.name, "World Atlas", "without a file name the project keeps its own");
    s.run("project.openText", &json!({"text": text, "fileName": " .rgis"})).unwrap();
    assert_eq!(s.project.name, "World Atlas", "an empty file name doesn't rename it");
    let dir = std::env::temp_dir().join(format!("rustgis-named-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("Trip plan.rgis");
    std::fs::write(&path, &text).unwrap();
    s.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!(s.project.name, "Trip plan");
    std::fs::remove_dir_all(&dir).ok();
}

#[test]
fn command_ids_are_unique() {
    let s = Session::new(Project::default());
    let mut ids: Vec<&str> = s.registry.commands.iter().map(|c| c.id).collect();
    ids.sort_unstable();
    let n = ids.len();
    ids.dedup();
    assert_eq!(n, ids.len());
}

/// A 3-band 8×6 UTM 17N GeoTIFF near 81°W, 42°N, as base64.
fn utm_tiff_b64() -> String {
    static ENCODED: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    ENCODED
        .get_or_init(|| {
            use base64::Engine;
            use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
            let gt = GeoTransform { origin_x: 497_000.0, origin_y: 4_651_000.0, pixel_width: 500.0, pixel_height: -500.0 };
            let bands = (0..3).map(|b| (0..48).map(|i| ((i * 5 + b * 40) % 256) as f32).collect()).collect();
            let r = Raster::new("utm", 8, 6, bands, gt, Crs::from_epsg(32617).unwrap(), None, ColorHint::Rgb { alpha: false }, "UInt8")
                .unwrap();
            base64::engine::general_purpose::STANDARD.encode(geotiff::write(&r, 0).unwrap())
        })
        .clone()
}

/// The sample world with a streamed layer active.
fn with_streamed(path: &std::path::Path) -> Session {
    let mut s = world();
    s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true, "name": "Streamed"})).unwrap();
    s
}

fn with_raster() -> Session {
    let mut s = world();
    s.run("layer.addDataBytes", &json!({"fileName": "scene.tif", "data": utm_tiff_b64()})).unwrap();
    s
}

/// The pixel identify gives with no feature under the click (Selectable's fallback, and what the
/// spectral profile reads) is the one of the raster drawn on top: a higher depth priority above
/// whatever the order, as the renderer draws them (#2488).
#[test]
fn identify_takes_the_pixel_of_the_raster_drawn_on_top_by_priority() {
    let mut s = with_raster();
    s.run("layer.addDataBytes", &json!({"fileName": "upper.tif", "data": utm_tiff_b64()})).unwrap();
    for l in ["Cities", "Rivers", "Lakes", "Countries"] {
        s.run("layer.visibility", &json!({"layer": l, "visible": false})).unwrap();
    }
    let top = |s: &Session| crate::cmd::raster::identify(s, -81.0, 42.0).map(|v| v["layer"].clone());
    let layers =
        |v: &Value| -> Vec<String> { v["results"].as_array().unwrap().iter().map(|r| r["layer"].as_str().unwrap().to_string()).collect() };
    // Added last, upper is drawn on top.
    assert_eq!(top(&s), Some(json!("upper")));
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": "visible"})).unwrap();
    assert_eq!(layers(&v), ["upper", "scene"], "{v}");
    // A higher priority draws scene over it whatever the order.
    s.run("layer.priority", &json!({"layer": "scene", "value": 1})).unwrap();
    assert_eq!(top(&s), Some(json!("scene")));
    for mode in ["topmost", "selectable"] {
        let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": mode})).unwrap();
        assert_eq!(v["layer"], "scene", "{mode}: {v}");
    }
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": "visible"})).unwrap();
    assert_eq!(layers(&v), ["scene", "upper"], "{v}");
}

/// A raster's pixel answers a topmost click like a feature does (#2488): a WMS layer drawn over the
/// raster is asked, one under it isn't (as under a feature, #808); visible asks it either way.
#[test]
fn identify_asks_a_wms_layer_under_a_raster_only_in_visible_mode() {
    const WMS: &str = r#"<WMS_Capabilities version="1.3.0" xmlns="http://www.opengis.net/wms" xmlns:xlink="http://www.w3.org/1999/xlink">
<Service><Title>Test WMS</Title></Service>
<Capability><Request><GetMap><Format>image/png</Format><DCPType><HTTP><Get><OnlineResource xlink:href="https://maps.example.com/wms?"/></Get></HTTP></DCPType></GetMap>
<GetFeatureInfo><Format>application/geo+json</Format><DCPType><HTTP><Get><OnlineResource xlink:href="https://maps.example.com/info?"/></Get></HTTP></DCPType></GetFeatureInfo></Request>
<Layer queryable="1"><Title>Root</Title><CRS>EPSG:3857</CRS><Layer><Name>roads</Name><Title>Roads</Title></Layer></Layer></Capability></WMS_Capabilities>"#;
    let mut s = with_raster();
    for l in ["Cities", "Rivers", "Lakes", "Countries"] {
        s.run("layer.visibility", &json!({"layer": l, "visible": false})).unwrap();
    }
    s.run("service.add", &json!({"url": "https://maps.example.com/wms", "layer": "roads", "text": WMS})).unwrap();
    let identify = |s: &mut Session, mode: &str| s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": mode})).unwrap();
    let asked = |v: &Value| -> Vec<String> {
        v["featureInfo"].as_array().into_iter().flatten().map(|a| a["tileLayer"].as_str().unwrap_or_default().to_string()).collect()
    };
    // Added last, the WMS layer is drawn over the raster: topmost shows the pixel and asks it.
    let v = identify(&mut s, "topmost");
    assert_eq!((v["layer"].clone(), asked(&v)), (json!("scene"), vec!["Roads".to_string()]), "{v}");
    // Under all the map's layers, the raster is drawn over it: only visible asks it.
    s.run("map.setTiles", &json!({"name": "Roads", "move": "bottom"})).unwrap();
    let v = identify(&mut s, "topmost");
    assert_eq!(v["layer"], "scene", "{v}");
    assert!(asked(&v).is_empty(), "{v}");
    let v = identify(&mut s, "visible");
    assert_eq!((v["layer"].clone(), asked(&v)), (json!("scene"), vec!["Roads".to_string()]), "{v}");
}

/// Identify asks and reads the tile layers in the drawing order, a higher depth priority on top
/// (#2488): a WMS layer drawn over the feature found is asked even when another, earlier in the
/// tile list, is drawn under it.
#[test]
fn identify_asks_the_wms_layer_drawn_over_a_layer_of_higher_priority() {
    const WMS: &str = r#"<WMS_Capabilities version="1.3.0" xmlns="http://www.opengis.net/wms" xmlns:xlink="http://www.w3.org/1999/xlink">
<Service><Title>Test WMS</Title></Service>
<Capability><Request><GetMap><Format>image/png</Format><DCPType><HTTP><Get><OnlineResource xlink:href="https://maps.example.com/wms?"/></Get></HTTP></DCPType></GetMap>
<GetFeatureInfo><Format>application/geo+json</Format><DCPType><HTTP><Get><OnlineResource xlink:href="https://maps.example.com/info?"/></Get></HTTP></DCPType></GetFeatureInfo></Request>
<Layer queryable="1"><Title>Root</Title><CRS>EPSG:3857</CRS><Layer><Name>roads</Name><Title>Roads</Title></Layer><Layer><Name>rails</Name><Title>Rails</Title></Layer></Layer></Capability></WMS_Capabilities>"#;
    let square = |x: f64| {
        format!(
            r#"{{"type":"FeatureCollection","features":[{{"type":"Feature","properties":{{}},"geometry":{{"type":"Polygon","coordinates":[[[{x},46],[{e},46],[{e},47],[{x},47],[{x},46]]]}}}}]}}"#,
            e = x + 1.0
        )
    };
    let mut s = Session::new(Project::default());
    // Area holds the click; Empty, added last and so first in the list, doesn't.
    s.run("layer.addDataText", &json!({"fileName": "area.geojson", "text": square(8.0), "name": "Area"})).unwrap();
    s.run("layer.addDataText", &json!({"fileName": "empty.geojson", "text": square(20.0), "name": "Empty"})).unwrap();
    for layer in ["roads", "rails"] {
        s.run("service.add", &json!({"url": "https://maps.example.com/wms", "layer": layer, "text": WMS})).unwrap();
    }
    let id = |s: &Session, name: &str| s.map().layer_by_name(name).map(|l| l.id);
    let (area, empty) = (id(&s, "Area"), id(&s, "Empty"));
    // Roads, first in the tile list, over Empty; Rails over Area.
    let m = s.map_mut();
    m.tiles.sort_by_key(|t| t.name != "Roads");
    m.tiles.iter_mut().for_each(|t| t.over = if t.name == "Roads" { empty } else { area });
    s.run("map.goToXY", &json!({"lon": 8.5, "lat": 46.5, "scale": 10000})).unwrap();
    let identify = |s: &mut Session, mode: &str| s.run("identify", &json!({"lon": 8.5, "lat": 46.5, "mode": mode})).unwrap();
    let asked = |v: &Value| -> Vec<String> {
        v["featureInfo"].as_array().into_iter().flatten().map(|a| a["tileLayer"].as_str().unwrap_or_default().to_string()).collect()
    };
    // As listed, Empty and Roads are drawn over Area: topmost finds Area and asks Roads.
    let v = identify(&mut s, "topmost");
    assert_eq!((v["layer"].clone(), asked(&v)), (json!("Area"), vec!["Roads".to_string()]), "{v}");
    assert_eq!(asked(&identify(&mut s, "visible")), ["Roads", "Rails"]);
    // A higher priority draws Area, and Rails over it, on top: Rails is the one asked.
    s.run("layer.priority", &json!({"layer": "Area", "value": 1})).unwrap();
    let v = identify(&mut s, "topmost");
    assert_eq!((v["layer"].clone(), asked(&v)), (json!("Area"), vec!["Rails".to_string()]), "{v}");
    assert_eq!(asked(&identify(&mut s, "visible")), ["Rails", "Roads"]);
}

/// A box whose corners the raster's system refuses (#1925) is placed by its part over the raster:
/// a UTM zone 17 scene near 42°N clipped to a box holding it, whose corners on the equator are
/// 91° and 89° from the zone's meridian, is the whole scene, not a window from the north corners
/// alone, which misses it.
#[test]
fn a_raster_clipped_to_a_box_with_refused_corners_keeps_what_the_box_holds() {
    let mut s = with_raster();
    let t = rustgis_data::raster::Crs::from_epsg(32617).unwrap().transformer().unwrap();
    let at = |x, y| t.from_lonlat(rustgis_geom::Coord::new(x, y));
    assert!(at(10.0, 0.0).is_none() && at(-170.0, 0.0).is_none() && at(10.0, 50.0).is_some() && at(-170.0, 50.0).is_some());
    s.run("raster.process", &json!({"layer": "scene", "operation": "clip", "extent": [-170.0, 0.0, 10.0, 50.0], "name": "part"})).unwrap();
    let part = s.map().layer_by_name("part").and_then(|l| l.raster.as_ref()?.data.clone()).unwrap();
    assert_eq!((part.width, part.height), (8, 6));
}

/// A QGIS raster style colours a raster layer; one reading a band the raster hasn't is noted and
/// leaves it as it was.
#[test]
fn a_qgis_raster_style_colours_a_raster() {
    let mut s = with_raster();
    let qml = r#"<qgis version="4.2.3" layerType="Raster"><pipe><rasterrenderer type="multibandcolor" redBand="3" greenBand="2" blueBand="1" opacity="0.5"/>
        <brightnesscontrast brightness="0" contrast="25" gamma="1"/></pipe></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "scene", "text": qml})).unwrap();
    assert_eq!(out["notes"], json!([]));
    let l = s.map().layer_by_name("scene").unwrap();
    let st = &l.raster.as_ref().unwrap().style;
    assert_eq!(
        (&st.renderer, st.contrast, l.transparency),
        (&rustgis_map::raster::RasterRenderer::Rgb { red: 2, green: 1, blue: 0 }, 25.0, 50.0)
    );
    let before = st.clone();
    // A style that reads a band the raster hasn't leaves it as it was, its opacity too.
    let qml = r#"<qgis version="4.2.3" layerType="Raster"><pipe><rasterrenderer type="singlebandgray" grayBand="5"/></pipe><layerOpacity>0.2</layerOpacity></qgis>"#;
    let out = s.run("style.importQgis", &json!({"layer": "scene", "text": qml})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("band 5 of a raster with 3"), "{out}");
    let l = s.map().layer_by_name("scene").unwrap();
    assert_eq!((&l.raster.as_ref().unwrap().style, l.transparency), (&before, 50.0));
    // Pixels not there yet (a remote raster still loading): applied, and noted as unchecked.
    let id = s.map().layer_by_name("scene").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().raster.as_mut().unwrap().data = None;
    let out = s.run("style.importQgis", &json!({"layer": "scene", "text": qml})).unwrap();
    assert!(serde_json::to_string(&out["notes"]).unwrap().contains("before the raster's bands could be checked"), "{out}");
}

/// The parts of a large GeoTIFF the web app reads (#140), opened and kept in a project: a
/// cloud-optimised file read a part at a time, as `parts.rs` reads a picked file.
#[test]
fn geotiff_parts_open_and_survive_a_saved_project() {
    use base64::Engine;
    use rustgis_data::raster::cog::{self, Sparse};
    use rustgis_data::raster::geotiff::{self, Partial};
    let file = cog::example(1024, 256);
    let len = file.len() as u64;
    let mut parts = Sparse::default().with_len(len).with(0, file[..4096].to_vec());
    let mut done = false;
    for _ in 0..100 {
        match geotiff::read_sparse(&parts, "scene").unwrap() {
            Partial::Done(_) => {
                done = true;
                break;
            }
            Partial::Need(a, b) => {
                let end = b.max(a + (64 << 10)).min(len).min(parts.next_start(a).unwrap_or(len));
                parts = parts.with(a, file[a as usize..end as usize].to_vec());
            }
        }
    }
    assert!(done);
    let container = parts.container();
    let mut s = world();
    let data = base64::engine::general_purpose::STANDARD.encode(&container);
    s.run("layer.addDataBytes", &json!({"fileName": "scene.tif", "data": data})).unwrap();
    let value = |s: &Session| s.map().layer_by_name("scene").and_then(|l| l.raster.as_ref()?.data.as_ref()?.value(0, 300, 200));
    // Pixel (x, y) of the example is (x + y) % 256.
    assert_eq!(value(&s), Some(244.0));
    // Saved, the project keeps the parts, not the whole file, and opens the raster again.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.len() < file.len() * 2, "{} for a {}-byte file", text.len(), file.len());
    s.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(value(&s), Some(244.0));
}

/// File-supplied items reject implicit network and reserved actions before their handlers run,
/// while ordinary in-project cells still run. This uses the existing Wasm plugin fixture.
#[test]
fn imported_tasks_and_notebooks_reject_network_and_reserved_actions() {
    let mut s = world();
    plugin("eng-item-containment", &[]);
    for (command, params) in [
        ("layer.geocode", json!({"layer": "Cities", "address": "name"})),
        ("connection.test", json!({"id": "saved-connection"})),
        ("plugin.uninstall", json!({"id": "eng-item-containment"})),
    ] {
        let steps = json!([{"title": "Outside", "command": command, "params": params}]);
        let task = json!({"name": "From a file", "steps": steps});
        let why = s.run("task.import", &json!({"text": task.to_string()})).unwrap_err();
        assert!(why.contains("network") && why.contains("imported"), "{why}");
        // Opened projects and later edits reach the execution check without task.import.
        s.run("task.new", &json!({"name": command, "steps": steps, "imported": true})).unwrap();
        let why = s.run("task.run", &json!({"task": command})).unwrap_err();
        assert!(why.contains("from a file"), "{why}");
    }
    let text = json!({"name": "Shared", "cells": [
        {"kind": "code", "source": "select.all {\"layer\":\"Cities\"}"},
        {"kind": "code", "source": "plugin.uninstall {\"id\":\"eng-item-containment\"}"},
        {"kind": "code", "source": "layer.geocode {\"layer\":\"Cities\",\"address\":\"name\"}"}
    ]})
    .to_string();
    s.run("notebook.open", &json!({"text": text})).unwrap();
    let result = s.run("notebook.run", &json!({"notebook": "Shared"})).unwrap();
    assert_eq!(result["error"], 1);
    let notebook = s.project.notebooks.iter().find(|n| n.name == "Shared").unwrap();
    assert!(!notebook.cells[0].error);
    assert!(notebook.cells[1].error && notebook.cells[1].output.as_deref().unwrap().contains("from a file"));
    assert!(!s.map().layer_by_name("Cities").unwrap().selection.is_empty());
    let result = s.run("notebook.run", &json!({"notebook": "Shared", "cell": 2})).unwrap();
    assert_eq!(result["error"], 2);
    assert!(rustgis_plugins::get("eng-item-containment").is_some(), "no uninstall handler ran");
    rustgis_plugins::unload("eng-item-containment");
}

/// Plugin tools are rejected through all imported item runners, including models' direct tool
/// paths. A locally authored model still runs the same real plugin tool.
#[test]
fn imported_items_reject_resolved_plugin_tools() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::imported_items_reject_resolved_plugin_tools") {
        return;
    }
    let mut s = world();
    plugin("eng-tool-containment", &[]);
    let tool = "plugin:eng-tool-containment/m";
    let params = json!({"input": "Cities"});
    let gp = json!({"tool": tool, "params": params});
    let before = s.map().layers.len();
    let task = json!({"name": "Plugin task", "steps": [{"title": "Run", "command": "gp.run", "params": gp}]});
    assert!(s.run("task.import", &json!({"text": task.to_string()})).unwrap_err().contains("imported"));
    let notebook = json!({"name": "Plugin notebook", "cells": [{"kind": "code", "source": format!("gp.run {gp}")}]});
    s.run("notebook.open", &json!({"text": notebook.to_string()})).unwrap();
    assert_eq!(s.run("notebook.run", &json!({"notebook": "Plugin notebook"})).unwrap()["error"], 0);
    let graph = json!({"nodes": [{"id": "x", "kind": "tool", "tool": tool, "params": params}], "edges": []});
    for (name, body) in [("Plugin steps", json!({"steps": [{"tool": tool, "params": params}]})), ("Plugin graph", json!({"graph": graph}))]
    {
        let mut model = body;
        model["name"] = json!(name);
        s.run("model.import", &json!({"text": model.to_string()})).unwrap();
        let why = s.run("model.run", &json!({"name": name})).unwrap_err();
        assert!(why.contains("from a file"), "{why}");
    }
    assert_eq!(s.map().layers.len(), before, "no untrusted tool ran");
    // The same graph made here is authorized; no plugin interface or manifest policy changes.
    s.run("model.new", &json!({"name": "Made here", "graph": graph})).unwrap();
    s.run("model.run", &json!({"name": "Made here"})).unwrap();
    assert_eq!(s.map().layers.len(), before + 1);
    assert!(s.map().layer_by_name("Made").is_some());
    rustgis_plugins::unload("eng-tool-containment");
}

#[test]
fn imported_tasks_name_outputs_and_steps_are_edited() {
    let mut s = Session::new(sample::world_project());
    // A task from a file may name a tool's output layer, but not write to a path through it.
    let lesson = json!({"name": "Lesson", "steps": [
        {"title": "Buffer the cities", "instructions": "Analyze › Tools › Buffer", "command": "gp.run", "params": {"tool": "buffer", "params": {"input": "Cities", "distance": 100, "output": "Near cities"}}},
        {"title": "Zoom", "command": "layer.zoomTo", "params": {"layer": "Near cities"}},
        {"title": "Clear", "command": "select.clear"}
    ]});
    s.run("task.import", &json!({"text": lesson.to_string()})).unwrap();
    s.run("task.run", &json!({"task": "Lesson", "step": 0})).unwrap();
    assert!(s.map().layer_by_name("Near cities").is_some());
    let to_a_file = json!({"name": "To a file", "steps": [{"title": "Buffer", "command": "gp.run", "params": {"tool": "buffer", "params": {"input": "Cities", "distance": 100, "output": "C:/temp/x.shp"}}}]});
    assert!(s.run("task.import", &json!({"text": to_a_file.to_string()})).is_err());
    assert!(crate::cmd::items::touches_files(&s, "gp.run", &json!({"tool": "buffer", "params": {"output": "../x.shp"}})));
    assert!(!crate::cmd::items::touches_files(&s, "gp.run", &json!({"tool": "buffer", "params": {"output": "Near cities"}})));
    // Spatial Join and Zonal Statistics run their built-in tool with the parameters flat: a
    // plain output name stays in the session there too.
    assert!(!crate::cmd::items::touches_files(&s, "gp.spatialJoin", &json!({"target": "Cities", "join": "Countries", "output": "Joined"})));
    assert!(!crate::cmd::items::touches_files(&s, "gp.zonalStats", &json!({"raster": "dem", "polygons": "Countries", "output": "Zones"})));
    // Only a plain layer name, only gp.run's (and those two's), only for RustGIS's own tools.
    for (command, params) in [
        ("gp.run", json!({"tool": "buffer", "params": {"output": "x.shp"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"output": "sub/x"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"output": "sub\\x"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"output": ".bashrc"}})),
        ("gp.run", json!({"tool": "geolibre:slope", "params": {"output": "slope"}})),
        ("gp.run", json!({"tool": "plugin:kit/hex", "params": {"output": "hex"}})),
        // Not one of RustGIS's own tools, even without a prefix.
        ("gp.run", json!({"tool": "someOtherTool", "params": {"output": "x"}})),
        ("gp.run", json!({"tool": "buffer", "params": {"input": "Cities", "nested": {"output": "x"}}})),
        ("layer.rename", json!({"layer": "Cities", "output": "x"})),
        ("gp.spatialJoin", json!({"target": "Cities", "join": "Countries", "output": "C:/temp/x.shp"})),
        ("gp.zonalStats", json!({"raster": "dem", "polygons": "Countries", "output": "../zones"})),
    ] {
        assert!(crate::cmd::items::touches_files(&s, command, &params), "{command} {params}");
    }

    // `"step": null` runs the whole task, as before; a step that isn't an index is refused.
    s.run("select.all", &json!({"layer": "Cities"})).unwrap();
    let r = s.run("task.run", &json!({"task": "Lesson", "step": null})).unwrap();
    assert_eq!(r["ran"].as_array().unwrap().len(), 3);
    assert!(s.run("task.run", &json!({"task": "Lesson", "step": "two"})).is_err());

    // Steps are edited, moved and deleted, each one undoable.
    s.run(
        "task.editStep",
        &json!({"task": "Lesson", "step": 1, "title": "  Look at it  ", "instructions": "Line one.
Line two."}),
    )
    .unwrap();
    let step = |s: &Session, i: usize| s.project.tasks.iter().find(|t| t.name == "Lesson").unwrap().steps[i].clone();
    assert_eq!(
        (step(&s, 1).title.as_str(), step(&s, 1).instructions.as_str()),
        (
            "Look at it",
            "Line one.
Line two."
        )
    );
    assert_eq!(step(&s, 1).command, "layer.zoomTo", "editing keeps the command");
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 1, "title": " "})).is_err());
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 9, "title": "x"})).is_err());
    s.run("task.moveStep", &json!({"task": "Lesson", "step": 2, "to": 0})).unwrap();
    assert_eq!(step(&s, 0).title, "Clear");
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(step(&s, 0).title, "Buffer the cities");
    s.run("task.removeStep", &json!({"task": "Lesson", "step": 2})).unwrap();
    assert_eq!(s.project.tasks.iter().find(|t| t.name == "Lesson").unwrap().steps.len(), 2);
    assert!(s.run("task.moveStep", &json!({"task": "Lesson", "step": 0, "to": 5})).is_err());
    // Neither changes nothing (which would leave an undo step).
    let depth = s.undo_depth();
    assert!(s.run("task.moveStep", &json!({"task": "Lesson", "step": 1, "to": 1})).is_err());
    let bad = s.run("task.removeStep", &json!({"task": "Lesson", "step": -1})).unwrap_err();
    assert!(bad.contains("whole number"), "{bad}");
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 1})).is_err());
    let same = s.project.tasks.iter().find(|t| t.name == "Lesson").unwrap().steps[1].title.clone();
    assert!(s.run("task.editStep", &json!({"task": "Lesson", "step": 1, "title": format!(" {same} ")})).is_err());
    assert_eq!(s.undo_depth(), depth);
    // Still a task from a file: a step that writes a file stays refused after editing.
    assert!(!s.item_trusted("task", "lesson"));
}

#[test]
fn tissot_indicatrix_reports_the_maps_own_distortion() {
    let mut s = Session::new(sample::world_project());
    let field = |s: &Session, layer: &str, lat: f64, name: &str| -> Value {
        let ds = &s.map().layer_by_name(layer).unwrap().dataset;
        let col = |n: &str| ds.fields.iter().position(|f| f.name == n).unwrap();
        let row = (0..ds.features.len())
            .find(|&r| {
                ds.value(r, col("lat")) == &rustgis_data::Value::Float(lat) && ds.value(r, col("lon")) == &rustgis_data::Value::Float(0.0)
            })
            .unwrap();
        match ds.value(row, col(name)) {
            rustgis_data::Value::Float(v) => json!(v),
            rustgis_data::Value::Text(t) => json!(t),
            v => panic!("{name}: {v:?}"),
        }
    };
    // Web Mercator, the default: area grows to about sec² 60° = 4, shapes are kept.
    s.run("gp.run", &json!({"tool": "tissot", "params": {"output": "merc"}})).unwrap();
    assert_eq!(field(&s, "merc", 60.0, "projection"), json!("Web Mercator"));
    let area = field(&s, "merc", 60.0, "area_scale").as_f64().unwrap();
    assert!((area - 4.0).abs() < 0.05, "{area}");
    assert!(field(&s, "merc", 60.0, "max_angle").as_f64().unwrap() < 0.5);
    // Mollweide is equal-area: about 1 everywhere, while angles bend away from its centre.
    s.run("map.projection", &json!({"type": "mollweide"})).unwrap();
    s.run("gp.run", &json!({"tool": "tissot", "params": {"output": "moll"}})).unwrap();
    for lat in [-60.0, 0.0, 30.0, 60.0] {
        let area = field(&s, "moll", lat, "area_scale").as_f64().unwrap();
        assert!((area - 1.0).abs() < 0.01, "{lat}: {area}");
    }
    assert!(field(&s, "moll", 60.0, "max_angle").as_f64().unwrap() > 10.0);
    // On the globe there's no flat projection to measure: circles only.
    s.run("map.projection", &json!({"type": "globe"})).unwrap();
    s.run("gp.run", &json!({"tool": "tissot", "params": {"output": "globe"}})).unwrap();
    let fields: Vec<String> = s.map().layer_by_name("globe").unwrap().dataset.fields.iter().map(|f| f.name.clone()).collect();
    assert_eq!(fields, ["lat", "lon"]);
    // Map Extent on the globe fills the whole Earth.
    s.run("gp.run", &json!({"tool": "tissot", "params": {"area": "Map Extent", "spacing": 60, "output": "globeView"}})).unwrap();
    // Six columns of 60° and three rows (−60°, 0°, 60°; the poles' rows are left out).
    assert_eq!(s.map().layer_by_name("globeView").unwrap().dataset.features.len(), 18);
}

/// A5 grids (#551) through gp.run: a world grid of equal-area cells, and the sample's cities
/// counted by cell, every city in one.
#[test]
fn a5_grids_and_points_by_cell() {
    let mut s = world();
    let r = s.run("gp.run", &json!({"tool": "a5Grid", "params": {"resolution": 1, "area": "World", "output": "cells"}})).unwrap();
    let cells = s.map().layer_by_name("cells").unwrap_or_else(|| panic!("{r}"));
    let names: Vec<&str> = cells.dataset.fields.iter().map(|f| f.name.as_str()).collect();
    assert_eq!(names, ["a5", "resolution", "area_km2"]);
    assert!(cells.dataset.features.len() > 12);
    let cities = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    s.run("gp.run", &json!({"tool": "a5Aggregate", "params": {"input": "Cities", "resolution": 2, "output": "by cell"}})).unwrap();
    let by = &s.map().layer_by_name("by cell").unwrap().dataset;
    let i = by.field_index("count").unwrap();
    let total: f64 = (0..by.features.len()).map(|r| by.value(r, i).as_f64().unwrap()).sum();
    assert_eq!(total as usize, cities);
    assert!(s.run("gp.run", &json!({"tool": "a5Grid", "params": {"resolution": 13, "area": "World"}})).is_err());
    // A script saved with the names the tools had before they took a system still runs them.
    s.run("gp.run", &json!({"tool": "A5 Grid", "params": {"resolution": 1, "area": "World", "output": "old name"}})).unwrap();
    assert_eq!(s.map().layer_by_name("old name").unwrap().dataset.fields[0].name, "a5");
    s.run("gp.run", &json!({"tool": "Aggregate Points to A5", "params": {"input": "Cities", "resolution": 2, "output": "old by cell"}}))
        .unwrap();
    assert!(s.map().layer_by_name("old by cell").is_some());
}

/// Generate Tessellation and Aggregate Points to Grid through `gp.run` in every system, every
/// city in one cell; the hexagon grid is laid on the map's projection, and on Web Mercator for a
/// globe, and its layer says which.
#[test]
fn tessellations_and_points_by_cell_in_every_system() {
    let mut s = world();
    let cities = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    let counted = |s: &Session, name: &str| {
        let by = &s.map().layer_by_name(name).unwrap().dataset;
        let i = by.field_index("count").unwrap();
        (0..by.features.len()).map(|r| by.value(r, i).as_f64().unwrap()).sum::<f64>() as usize
    };
    for (system, res, key) in [("H3", 1, "h3"), ("S2", 3, "s2"), ("A5", 2, "a5"), ("Hexagon", 2, "hex")] {
        let out = format!("{system} cells");
        let r = s
            .run("gp.run", &json!({"tool": "a5Grid", "params": {"system": system, "resolution": res, "area": "World", "output": out}}))
            .unwrap();
        let cells = s.map().layer_by_name(&out).unwrap_or_else(|| panic!("{r}"));
        assert_eq!(cells.dataset.fields[0].name, key);
        assert!(cells.dataset.features.len() > 12, "{system}");
        let by = format!("{system} by cell");
        s.run("gp.run", &json!({"tool": "a5Aggregate", "params": {"system": system, "input": "Cities", "resolution": res, "output": by}}))
            .unwrap();
        assert_eq!(counted(&s, &by), cities, "{system}");
    }
    let plane = |s: &Session, name: &str| s.map().layer_by_name(name).unwrap().dataset.value(0, 3).to_string();
    assert_eq!(plane(&s, "Hexagon cells"), "Web Mercator");
    // On an equal-area map the hexagons are laid on its plane: no city is near a pole, so every
    // one is counted, in a cell the projection can draw.
    s.run("map.projection", &json!({"type": "mollweide"})).unwrap();
    let r = s
        .run(
            "gp.run",
            &json!({"tool": "a5Aggregate", "params": {"system": "Hexagon", "input": "Cities", "resolution": 6, "output": "moll"}}),
        )
        .unwrap();
    assert!(plane(&s, "moll").contains("ollweide"), "{}", plane(&s, "moll"));
    assert_eq!(counted(&s, "moll"), cities, "{r}");
    // The world on it reaches both poles, where its plane loses the longitude.
    let r = s
        .run(
            "gp.run",
            &json!({"tool": "a5Grid", "params": {"system": "Hexagon", "resolution": 2, "area": "World", "output": "moll world"}}),
        )
        .unwrap();
    assert!(s.map().layer_by_name("moll world").is_some_and(|l| l.dataset.features.len() > 12), "{r}");
    assert!(!r.to_string().contains("85.05"), "{r}");
    // On a map centred on the Pacific the world is cut at the map's edge, 30°W: the same grid as
    // on one centred on Greenwich.
    let mut world_on = |code: &str, out: &str| {
        s.run("map.projection", &json!({"type": code})).unwrap();
        let p = json!({"tool": "a5Grid", "params": {"system": "Hexagon", "resolution": 2, "area": "World", "output": out}});
        let r = s.run("gp.run", &p).unwrap();
        let n = s.map().layer_by_name(out).unwrap_or_else(|| panic!("{code}: {r}")).dataset.features.len();
        assert!(n > 12, "{code}: {r}");
        n
    };
    assert_eq!(world_on("equirectangular", "eqc 0"), world_on("equirectangular +lon_0=150", "eqc 150"));
    s.run("map.projection", &json!({"type": "globe"})).unwrap();
    s.run(
        "gp.run",
        &json!({"tool": "a5Aggregate", "params": {"system": "Hexagon", "input": "Cities", "resolution": 6, "output": "globe"}}),
    )
    .unwrap();
    assert_eq!(plane(&s, "globe"), "Web Mercator");
    assert!(s.run("gp.run", &json!({"tool": "a5Grid", "params": {"system": "H3", "resolution": 7, "area": "World"}})).is_err());
}

#[test]
fn globe_projection_toggles_renders_and_saves() {
    let mut s = with_raster();
    assert_eq!(s.run("map.projection", &Value::Null).unwrap()["projection"], "globe");
    assert_eq!(s.map().projection, rustgis_map::Projection::Globe);
    // The globe draws vectors, rasters and labels, from any side.
    for (lon, lat, res) in [(-81.0, 42.0, 30_000.0), (100.0, -60.0, 60_000.0), (-81.0, 42.0, 50.0), (0.0, 89.0, 160_000.0)] {
        s.map_mut().camera =
            rustgis_map::Camera { center: rustgis_geom::lonlat_to_merc(rustgis_geom::Coord::new(lon, lat)), res, bearing: 0.0, pitch: 0.0 };
        let png = crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap();
        assert!(png.len() > 1000);
    }
    assert!(s.run("map.projection", &json!({"type": "nope"})).is_err());
    s.run("map.projection", &json!({"type": "mercator"})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().projection, rustgis_map::Projection::Globe, "undo restores the globe");
    let json = serde_json::to_string(&s.project).unwrap();
    assert!(Project::from_json(&json).unwrap().map().projection == rustgis_map::Projection::Globe);
}

/// `map.projection` takes ESRI codes (#213): South America Albers, the issue's regional map.
#[test]
fn esri_projection_codes() {
    let mut s = world();
    s.run("map.goToXY", &json!({"lon": -60.0, "lat": -15.0, "scale": 20_000_000})).unwrap();
    let r = s.run("map.projection", &json!({"type": "esri:102033"})).unwrap();
    assert_eq!(r["projection"], "ESRI:102033");
    assert_eq!(r["label"], "ESRI:102033");
    let c = s.map().center_lonlat();
    assert!((c.x + 60.0).abs() < 1e-6 && (c.y + 15.0).abs() < 1e-6, "{c:?}");
    assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000);
    let json = serde_json::to_string(&s.project).unwrap();
    assert_eq!(Project::from_json(&json).unwrap().map().projection.code(), "ESRI:102033");
    // A code that isn't an ESRI projected system RustGIS draws (a Hammer–Aitoff PROJ can't write
    // as a PROJ string) is refused, and the map keeps its projection.
    let e = s.run("map.projection", &json!({"type": "ESRI:54044"})).unwrap_err();
    assert!(e.contains("ESRI:54044"), "{e}");
    assert_eq!(s.map().projection.code(), "ESRI:102033");
    // ESRI's Web Mercator is the default map.
    assert_eq!(s.run("map.projection", &json!({"type": "ESRI:102100"})).unwrap()["projection"], "mercator");
}

/// Presets take a central meridian, and the conics their standard parallels too (#517). The map
/// keeps them, and a bad value changes nothing.
#[test]
fn projection_presets_take_parameters() {
    let mut s = world();
    let r = s.run("map.projection", &json!({"type": "robinson", "lon_0": 150})).unwrap();
    assert_eq!(r["projection"], "robinson +lon_0=150");
    assert_eq!(r["label"], "Robinson (lon_0=150)");
    // Without a type, the values go to the map's own preset. A code with them, as typed, is the same.
    s.run("map.projection", &json!({"lon_0": -20})).unwrap();
    assert_eq!(s.map().projection.code(), "robinson +lon_0=-20");
    s.run("map.projection", &json!({"type": "Albers Equal Area Conic +lat_2=-35 +lon_0=-55 +lat_1=-5"})).unwrap();
    assert_eq!(s.map().projection.code(), "albers +lon_0=-55 +lat_1=-5 +lat_2=-35");
    s.run("map.projection", &json!({"lat_1": 0})).unwrap();
    assert_eq!(s.map().projection.code(), "albers +lon_0=-55 +lat_1=0 +lat_2=-35");
    // The preset's own value drops out.
    s.run("map.projection", &json!({"type": "robinson", "lon_0": 0})).unwrap();
    assert_eq!(s.map().projection.code(), "robinson");
    // Out of range, a parameter the preset doesn't take, not a number, parameters on a code or on
    // Web Mercator, and parallels that make no cone: refused, and the map keeps its projection.
    s.run("map.projection", &json!({"type": "robinson", "lon_0": 150})).unwrap();
    for bad in [
        json!({"lon_0": 200}),
        json!({"lat_1": 10}),
        json!({"lon_0": "east"}),
        json!({"type": "EPSG:3035", "lon_0": 10}),
        json!({"type": "mercator", "lon_0": 10}),
        json!({"type": "robinson +lon_0=999"}),
        json!({"type": "albers", "lat_1": -30, "lat_2": 30}),
    ] {
        assert!(s.run("map.projection", &bad).is_err(), "{bad}");
        assert_eq!(s.map().projection.code(), "robinson +lon_0=150", "{bad}");
    }
    // Saved with the map, and drawn.
    let json = serde_json::to_string(&s.project).unwrap();
    assert_eq!(Project::from_json(&json).unwrap().map().projection.code(), "robinson +lon_0=150");
    let png = crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap();
    assert!(png.len() > 1000);
}

#[test]
fn vn2000_projection_command_and_project_persistence() {
    let mut s = world();
    // Explicit prefixed province syntax works and canonicalizes to the preset
    s.run("map.projection", &json!({"type": "vn2000:danang"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000tm3 +lon_0=107.75");
    assert_eq!(s.map().projection.label(), "VN-2000 / TM-3 (Vietnam) (lon_0=107.75)");

    // Capital Hanoi on central meridian 105.0 drops redundant parameter
    s.run("map.projection", &json!({"type": "vn2000:hanoi"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000tm3");
    assert_eq!(s.map().projection.label(), "VN-2000 / TM-3 (Vietnam)");

    // UTM zones work
    s.run("map.projection", &json!({"type": "vn2000Utm48"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000Utm48");
    assert_eq!(s.map().projection.label(), "VN-2000 / UTM zone 48N");

    s.run("map.projection", &json!({"type": "vn2000Utm49"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000Utm49");
    assert_eq!(s.map().projection.label(), "VN-2000 / UTM zone 49N");

    // Bare province names and "vietnam" are rejected in strict command context
    for bare in ["danang", "vinh", "hanoi", "hue", "hcm", "vietnam"] {
        assert!(s.run("map.projection", &json!({"type": bare})).is_err(), "{bare}");
    }
    // Ambiguous bare VN-2000 is rejected
    for bare in ["vn2000", "VN-2000", "VN2000"] {
        let err = s.run("map.projection", &json!({"type": bare})).unwrap_err();
        assert!(err.contains("ambiguous"), "{bare}: {err}");
    }

    // Set a provincial TM-3 projection and verify project save and reload
    s.run("map.projection", &json!({"type": "VN-2000 / Đà Nẵng"})).unwrap();
    assert_eq!(s.map().projection.code(), "vn2000tm3 +lon_0=107.75");
    let text = serde_json::to_string(&s.project).unwrap();

    // Reload project from serialized JSON text
    let mut s2 = world();
    s2.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(s2.map().projection.code(), "vn2000tm3 +lon_0=107.75");
    assert_eq!(s2.map().projection.label(), "VN-2000 / TM-3 (Vietnam) (lon_0=107.75)");
}

/// A map in NAD27 (EPSG:26717), whose most accurate datum transformation needs a grid RustGIS
/// doesn't have yet: the session says so once, naming the system, however often it draws.
#[test]
fn a_missing_datum_grid_is_said_once() {
    let mut s = world();
    let said = |s: &Session| s.notices.iter().filter(|n| n.text.starts_with("EPSG:26717:") && n.text.contains("grid")).count();
    s.run("map.projection", &json!({"type": "EPSG:26717"})).unwrap();
    assert!(crate::cmd::share::map_png(&mut s, Some(200.0), Some(150.0), None).unwrap().len() > 100);
    s.run("map.zoomIn", &json!({})).unwrap();
    assert_eq!(said(&s), 1, "{:?}", s.notices);
    assert!(crate::cmd::share::map_png(&mut s, Some(200.0), Some(150.0), None).unwrap().len() > 100);
    s.run("map.zoomOut", &json!({})).unwrap();
    assert_eq!(said(&s), 1, "once");
    // An export to NAD27 longitude/latitude says it too, though nothing in the project is in it.
    let mut s = world();
    let dir = std::env::temp_dir().join(format!("rustgis-engine-nad27-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("cities.gpkg");
    s.run("share.exportLayer", &json!({"layer": "Cities", "path": path, "crs": "EPSG:4267"})).unwrap();
    let nad27 = s.notices.iter().filter(|n| n.text.starts_with("EPSG:4267:") && n.text.contains("grid")).count();
    assert_eq!(nad27, 1, "{:?}", s.notices);
    std::fs::remove_dir_all(&dir).ok();
    // WGS 84's UTM has nothing to say.
    let mut s = world();
    s.run("map.projection", &json!({"type": "EPSG:32617"})).unwrap();
    s.run("map.zoomIn", &json!({})).unwrap();
    assert!(s.notices.iter().all(|n| !n.text.starts_with("EPSG:32617:")), "{:?}", s.notices);
}

/// A background export's target system is said as the export lands, as when it runs here; and
/// several systems that need a missing grid are said in one notice, with their count.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn missing_datum_grids_are_said_from_a_background_export_and_counted() {
    use crate::cmd::exports::{export_land, export_start};
    use rustgis_analysis::control::Control;
    let grid = |s: &Session, mark| {
        s.notices_since(mark).iter().filter(|n| n.text.contains("needs a grid")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    let mut s = world();
    let dir = std::env::temp_dir().join(format!("rustgis-engine-nad27-bg-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("cities.gpkg");
    let run = export_start(&mut s, "share.exportLayer", &json!({"layer": "Cities", "path": path, "crs": "EPSG:4267"})).unwrap();
    let (mark, started) = (s.notice_mark(), run.started());
    let wrote = std::thread::spawn(move || run.run(&Control::new())).join().unwrap();
    export_land(&mut s, started, wrote).unwrap();
    let said = grid(&s, mark);
    assert_eq!(said.len(), 1, "{:?}", s.notices);
    assert!(said[0].starts_with("EPSG:4267: "), "{said:?}");
    std::fs::remove_dir_all(&dir).ok();
    // A layer in NAD27 longitude/latitude on a map in NAD27's UTM: both said at once, counted.
    let mut s = world();
    let nad27 = rustgis_data::raster::Crs::from_epsg(4267).unwrap();
    assert!(nad27.transformer().is_ok());
    s.project.maps[0].layers[0].dataset.crs = Some(nad27);
    let mark = s.notice_mark();
    s.run("map.projection", &json!({"type": "EPSG:26717"})).unwrap();
    let said = grid(&s, mark);
    assert_eq!(said.len(), 1, "{said:?}");
    assert!(said[0].starts_with("2 coordinate systems (") && said[0].contains("EPSG:4267") && said[0].contains("EPSG:26717"), "{said:?}");
    // Many at once: a few named, the rest counted, so the notice keeps its explanation.
    let many: Vec<String> = (0..300).map(|i| format!("Custom system {i} {}", "x".repeat(200))).collect();
    let text = rustgis_data::raster::crs::grid_notes_text(many.len(), &crate::names_said(&many));
    assert!(text.starts_with("300 coordinate systems (") && text.contains("and 295 more") && text.contains("10 m"), "{text}");
    assert!(text.len() < 1000, "{}", text.len());
    // A map drawn in a system before any command: the frame after it says it.
    let mut s = world();
    s.project.maps[0].projection = rustgis_map::Projection::Custom("EPSG:26717".into());
    let mark = s.notice_mark();
    assert!(crate::cmd::share::map_png(&mut s, Some(200.0), Some(150.0), None).unwrap().len() > 100);
    s.notice_landed_rasters();
    let said = grid(&s, mark);
    assert!(said.len() == 1 && said[0].starts_with("EPSG:26717: "), "{said:?}");
    // Said once: another frame or command says nothing more.
    let mark = s.notice_mark();
    s.notice_landed_rasters();
    s.run("map.zoomIn", &json!({})).unwrap();
    assert!(grid(&s, mark).is_empty());
}

#[test]
fn custom_projections_switch_keep_scale_query_and_render() {
    let mut s = with_raster();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 50.0, "scale": 5_000_000})).unwrap();
    let before = s.scale();
    let r = s.run("map.projection", &json!({"type": "europeEqualArea"})).unwrap();
    assert_eq!(r["projection"], "europeEqualArea");
    assert!((s.scale() / before - 1.0).abs() < 0.02, "scale kept: {before} vs {}", s.scale());
    let c = s.map().center_lonlat();
    assert!((c.x - 10.0).abs() < 1e-6 && (c.y - 50.0).abs() < 1e-6, "{c:?}");
    // Identify and box select work in the projection's coordinates.
    let v = s.run("identify", &json!({"lon": 2.35, "lat": 48.85, "tolerancePx": 5})).unwrap();
    assert!(!v.is_null(), "something is under Paris");
    let sel = s.run("select.byRect", &json!({"minLon": 5.0, "minLat": 45.0, "maxLon": 15.0, "maxLat": 55.0})).unwrap();
    assert!(sel["selected"].as_u64().unwrap() > 0);
    assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000);
    // An EPSG code; the raster (UTM 17N) in the map's own system draws without reprojection.
    s.run("map.projection", &json!({"type": "EPSG:32617"})).unwrap();
    s.run("layer.zoomTo", &json!({"layer": "scene"})).unwrap();
    assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000);
    assert!(s.run("map.projection", &json!({"type": "EPSG:4326"})).is_err(), "degrees are refused");
    assert!(s.run("map.projection", &json!({"type": "nope"})).is_err());
    // EPSG:8441 (Laborde), refused while its method had no implementation (#208), switches now;
    // an unknown code is refused and the map keeps its projection.
    s.run("map.projection", &json!({"type": "EPSG:8441"})).unwrap();
    assert_eq!(s.map().projection.code(), "EPSG:8441");
    s.run("map.projection", &json!({"type": "EPSG:32617"})).unwrap();
    assert!(s.run("map.projection", &json!({"type": "EPSG:1"})).is_err());
    assert_eq!(s.map().projection.code(), "EPSG:32617");
    assert!(s.run("map.goToXY", &json!({"lon": 100.0, "lat": 0.0})).is_err(), "folded far side of the UTM zone");
    // Undo and save/reload keep the projection.
    s.run("map.projection", &json!({"type": "mollweide"})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().projection.code(), "EPSG:32617");
    let json = serde_json::to_string(&s.project).unwrap();
    assert_eq!(Project::from_json(&json).unwrap().map().projection.code(), "EPSG:32617");
    assert!(s.run("map.projections", &Value::Null).unwrap().as_array().unwrap().len() >= 10);
    // A project naming a projection this version can't use opens in Web Mercator.
    let broken = json.replace("EPSG:32617", "EPSG:9");
    let reopened = Project::from_json(&broken).unwrap();
    assert_eq!(reopened.map().projection, rustgis_map::Projection::WebMercator);
    assert_eq!(reopened.map().camera, rustgis_map::Camera::world(), "UTM metres aren't read as Mercator ones");
    // Bookmarks follow a projection switch, and the extent history doesn't replay old cameras.
    s.run("map.projection", &json!({"type": "mercator"})).unwrap();
    s.run("map.goToXY", &json!({"lon": 10.0, "lat": 50.0, "scale": 5_000_000})).unwrap();
    // The sample has a "Europe" already: the new one is numbered (#351), and found by its name.
    let europe = s.run("bookmark.add", &json!({"name": "Europe"})).unwrap()["name"].clone();
    assert_eq!(europe, "Europe 2");
    s.run("map.goToXY", &json!({"lon": -100.0, "lat": 40.0})).unwrap();
    assert!(s.can_extent_back());
    s.run("map.projection", &json!({"type": "europeEqualArea"})).unwrap();
    assert!(!s.can_extent_back(), "history from Web Mercator is dropped");
    s.run("bookmark.go", &json!({"name": europe})).unwrap();
    let c = s.map().center_lonlat();
    assert!((c.x - 10.0).abs() < 1e-6 && (c.y - 50.0).abs() < 1e-6, "{c:?}");
    assert!((s.scale() / 5_000_000.0 - 1.0).abs() < 0.02, "{}", s.scale());
    // An export at another size measures its scale bar with its own camera.
    let wide = s.map().ground_res_at(&rustgis_map::Camera { res: s.map().camera.res * 3.0, ..s.map().camera });
    assert!((wide / s.map().ground_res() - 3.0).abs() < 1e-9);
    // The built-in world projections (and Equal Earth by its EPSG code) draw the whole world.
    for p in ["robinson", "equalEarth", "naturalEarth", "winkelTripel", "eckertIV", "EPSG:8857"] {
        s.run("map.projection", &json!({"type": p})).unwrap_or_else(|e| panic!("{p}: {e}"));
        s.run("map.zoomFull", &Value::Null).unwrap();
        let c = s.map().center_lonlat();
        assert!(c.x.abs() < 1.0 && c.y.abs() < 30.0, "{p}: {c:?}");
        let v = s.run("identify", &json!({"lon": 2.35, "lat": 48.85, "tolerancePx": 5})).unwrap();
        assert!(!v.is_null(), "{p}: something is under Paris");
        assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000, "{p}");
    }
}

/// Shaded Relief's cast shadows: set, kept when left out, clamped, a new one without; saved with
/// the project only when there are some, and drawn in an export (waited for).
#[test]
fn shaded_relief_keeps_its_cast_shadows() {
    let mut s = with_raster();
    let shadow = |s: &Session| match s.map().layers.first().and_then(|l| l.raster.as_ref()).map(|r| &r.style.renderer) {
        Some(rustgis_map::RasterRenderer::ShadedRelief { shadow, .. }) => *shadow,
        other => panic!("{other:?}"),
    };
    s.run("raster.symbology", &json!({"type": "shadedRelief"})).unwrap();
    assert_eq!(shadow(&s), 0.0);
    let shadows_saved = |s: &mut Session| s.project.saved_text(None).unwrap().0.matches("\"shadow\"").count();
    let before = shadows_saved(&mut s);
    s.run("raster.symbology", &json!({"type": "shadedRelief", "shadow": 0.7})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "azimuth": 200})).unwrap();
    assert_eq!(shadow(&s), 0.7, "left out, kept");
    s.run("raster.symbology", &json!({"type": "shadedRelief", "shadow": 4})).unwrap();
    assert_eq!(shadow(&s), 1.0);
    assert_eq!(shadows_saved(&mut s), before + 1, "saved only when there are some");
    assert!(crate::cmd::share::map_png(&mut s, Some(300.0), Some(200.0), None).unwrap().len() > 1000);
    s.run("raster.symbology", &json!({"type": "stretch"})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief"})).unwrap();
    assert_eq!(shadow(&s), 0.0, "a new Shaded Relief casts none");
}

/// Shaded Relief's sky visibility is set, clamped, kept when left out (the shadows' too), saved
/// with the project only when there is some, and drawn in an export (waited for) with nothing to
/// say.
#[test]
fn shaded_relief_keeps_its_sky_visibility() {
    let mut s = with_raster();
    let light = |s: &Session| match s.map().layers.first().and_then(|l| l.raster.as_ref()).map(|r| &r.style.renderer) {
        Some(rustgis_map::RasterRenderer::ShadedRelief { shadow, sky, .. }) => (*shadow, *sky),
        other => panic!("{other:?}"),
    };
    s.run("raster.symbology", &json!({"type": "shadedRelief"})).unwrap();
    assert_eq!(light(&s), (0.0, 0.0));
    let skies_saved = |s: &mut Session| s.project.saved_text(None).unwrap().0.matches("\"sky\"").count();
    let before = skies_saved(&mut s);
    s.run("raster.symbology", &json!({"type": "shadedRelief", "sky": 0.6, "shadow": 0.5})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "azimuth": 200})).unwrap();
    assert_eq!(light(&s), (0.5, 0.6), "left out, kept");
    s.run("raster.symbology", &json!({"type": "shadedRelief", "sky": -3})).unwrap();
    assert_eq!(light(&s), (0.5, 0.0));
    assert_eq!(skies_saved(&mut s), before, "saved only when there is some");
    s.run("raster.symbology", &json!({"type": "shadedRelief", "sky": 4})).unwrap();
    assert_eq!(light(&s), (0.5, 1.0));
    assert_eq!(skies_saved(&mut s), before + 1);
    s.notices.clear();
    assert!(crate::cmd::share::map_png(&mut s, Some(300.0), Some(200.0), None).unwrap().len() > 1000);
    assert!(s.notices.iter().all(|n| !n.text.contains("sky")), "{:?}", s.notices);
}

/// Shaded Relief's fill light is set, clamped, kept when left out, saved with the project only
/// when there is some, and back when the project is opened again.
#[test]
fn shaded_relief_keeps_its_fill_light() {
    let mut s = with_raster();
    let fill = |s: &Session| match s.map().layers.iter().find_map(|l| l.raster.as_ref()).map(|r| &r.style.renderer) {
        Some(rustgis_map::RasterRenderer::ShadedRelief { fill, .. }) => *fill,
        other => panic!("{other:?}"),
    };
    let fills_saved = |s: &mut Session| s.project.saved_text(None).unwrap().0.matches("\"fill\"").count();
    let before = fills_saved(&mut s);
    s.run("raster.symbology", &json!({"type": "shadedRelief"})).unwrap();
    assert_eq!((fill(&s), fills_saved(&mut s)), (0.0, before), "none, and not saved");
    s.run("raster.symbology", &json!({"type": "shadedRelief", "fill": 0.3})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "azimuth": 200})).unwrap();
    assert_eq!(fill(&s), 0.3, "left out, kept");
    assert_eq!(fills_saved(&mut s), before + 1);
    s.run("raster.symbology", &json!({"type": "shadedRelief", "fill": -2})).unwrap();
    assert_eq!(fill(&s), 0.0);
    s.run("raster.symbology", &json!({"type": "shadedRelief", "fill": 7})).unwrap();
    assert_eq!(fill(&s), 1.0);
    s.run("raster.symbology", &json!({"type": "shadedRelief", "fill": 0.45})).unwrap();
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_nanos());
    let dir = std::env::temp_dir().join(format!("rustgis-fill-{}-{nanos}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("fill.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(fill(&t), 0.45, "back when opened");
}

/// Shaded Relief's ambient and balanced light (#1977) are set, clamped, kept when left out, saved
/// only when set, and back when the project is opened again; a null ambient is the default again.
#[test]
fn shaded_relief_keeps_its_ambient_and_balanced_light() {
    let mut s = with_raster();
    let light = |s: &Session| match s.map().layers.iter().find_map(|l| l.raster.as_ref()).map(|r| &r.style.renderer) {
        Some(rustgis_map::RasterRenderer::ShadedRelief { ambient, balanced, .. }) => (*ambient, *balanced),
        other => panic!("{other:?}"),
    };
    let saved = |s: &mut Session| {
        let text = s.project.saved_text(None).unwrap().0;
        (text.matches("\"ambient\"").count(), text.matches("\"balanced\"").count())
    };
    let (a0, b0) = saved(&mut s);
    s.run("raster.symbology", &json!({"type": "shadedRelief"})).unwrap();
    assert_eq!((light(&s), saved(&mut s)), ((None, false), (a0, b0)), "unset, and not saved");
    s.run("raster.symbology", &json!({"type": "shadedRelief", "ambient": 0.4, "balanced": true})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "azimuth": 200})).unwrap();
    assert_eq!((light(&s), saved(&mut s)), ((Some(0.4), true), (a0 + 1, b0 + 1)), "left out, kept");
    s.run("raster.symbology", &json!({"type": "shadedRelief", "ambient": 3})).unwrap();
    assert_eq!(light(&s), (Some(1.0), true));
    s.run("raster.symbology", &json!({"type": "shadedRelief", "ambient": null})).unwrap();
    assert_eq!(light(&s), (None, true), "null: the default");
    assert!(s.run("raster.symbology", &json!({"type": "shadedRelief", "ambient": "dark"})).is_err());
    s.run("raster.symbology", &json!({"type": "shadedRelief", "ambient": "0.35"})).unwrap();
    assert_eq!(light(&s), (Some(0.35), true), "a number as text, as other keys take");
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_nanos());
    let dir = std::env::temp_dir().join(format!("rustgis-ambient-{}-{nanos}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("ambient.rgis");
    s.run("project.saveAs", &json!({"path": path.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path.display().to_string()})).unwrap();
    let _ = std::fs::remove_dir_all(&dir);
    assert_eq!(light(&t), (Some(0.35), true), "back when opened");
}

/// Shaded Relief's rock on steep slopes (#1913): an object turns it on, its missing keys from the
/// current rock or the defaults; kept when left out; `false` removes it; a `from` not below `to`
/// or a bad colour is refused; saved with the project only when set.
#[test]
fn shaded_relief_keeps_its_rock_on_steep_slopes() {
    use rustgis_map::raster::Rock;
    let mut s = with_raster();
    let rock = |s: &Session| match s.map().layers.first().and_then(|l| l.raster.as_ref()).map(|r| &r.style.renderer) {
        Some(rustgis_map::RasterRenderer::ShadedRelief { rock, .. }) => *rock,
        other => panic!("{other:?}"),
    };
    let rocks_saved = |s: &mut Session| s.project.saved_text(None).unwrap().0.matches("\"rock\"").count();
    s.run("raster.symbology", &json!({"type": "shadedRelief"})).unwrap();
    assert_eq!(rock(&s), None, "off by default");
    let before = rocks_saved(&mut s);
    s.run("raster.symbology", &json!({"type": "shadedRelief", "rock": {}})).unwrap();
    assert_eq!(rock(&s), Some(Rock::DEFAULT));
    s.run("raster.symbology", &json!({"type": "shadedRelief", "rock": {"to": 50, "color": "#806040"}})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "azimuth": 200})).unwrap();
    let want = Rock { from: 25.0, to: 50.0, color: rustgis_map::Rgba::rgb(0x80, 0x60, 0x40) };
    assert_eq!(rock(&s), Some(want), "left out, kept; its missing keys too");
    assert_eq!(rocks_saved(&mut s), before + 1, "saved when set");
    for bad in
        [json!({"from": 40, "to": 30}), json!({"from": 30, "to": 30}), json!({"color": "rock"}), json!({"color": "#B2ACA480"}), json!(3)]
    {
        assert!(s.run("raster.symbology", &json!({"type": "shadedRelief", "rock": bad})).is_err(), "{bad}");
        assert_eq!(rock(&s), Some(want), "{bad}: refused, the rock kept");
    }
    s.run("raster.symbology", &json!({"type": "shadedRelief", "rock": false})).unwrap();
    assert_eq!(rock(&s), None);
    assert_eq!(rocks_saved(&mut s), before, "not saved once removed");
}

/// An export draws the rock on steep slopes: a grey relief whose east half is a 63° wall turns
/// red there with a red rock, and keeps the same pixels on the flat west half.
#[test]
fn an_export_draws_the_rock_on_steep_slopes() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let mut s = world();
    // 41 cells of 30 m a side: flat to column 20, then rising 60 m a cell eastward.
    let wall: Vec<f32> = (0..41 * 41).map(|i| ((i % 41 - 20).max(0) * 60) as f32).collect();
    let gt = GeoTransform { origin_x: 500_000.0, origin_y: 7_000_000.0, pixel_width: 30.0, pixel_height: -30.0 };
    let r = Raster::new("wall", 41, 41, vec![wall], gt, Crs::from_epsg(31983).unwrap(), None, ColorHint::Gray, "Float32").unwrap();
    let bytes = geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "wall", rustgis_map::RasterLayer::from_bytes(r, "wall.tif".to_string(), bytes)).unwrap();
    s.run("layer.zoomTo", &json!({"layer": "wall"})).unwrap();
    let drawn = |s: &mut Session, rock: Value| {
        s.run("raster.symbology", &json!({"layer": "wall", "type": "shadedRelief", "grey": true, "azimuth": 270, "rock": rock})).unwrap();
        let png = crate::cmd::share::map_png(s, Some(200.0), Some(200.0), None).unwrap();
        crate::render::decode_png(&png).unwrap()
    };
    let plain = drawn(&mut s, json!(false));
    let rocky = drawn(&mut s, json!({"from": 10, "to": 20, "color": "#FF0000"}));
    let px = |p: &tiny_skia::Pixmap, x: u32| p.pixel(x, 100).map(|c| [c.red(), c.green(), c.blue()]).unwrap();
    // The flat west half: the same grey. The wall: grey without the rock, red with it.
    assert_eq!(px(&rocky, 70), px(&plain, 70));
    let ([r0, g0, b0], [r1, g1, b1]) = (px(&plain, 130), px(&rocky, 130));
    assert!(r0 == g0 && g0 == b0 && r0 > 0, "a grey wall: {:?}", [r0, g0, b0]);
    assert!(r1 > 0 && g1 == 0 && b1 == 0, "a red wall: {:?}", [r1, g1, b1]);
}

/// An export draws the sky a pit hides: its floor darker with `sky` 1 than with 0, the ground
/// around it (which sees the whole sky) the same. The first export with the sky, from a cold
/// cache, waits for the grid: it is the same image as one drawn once the grid is kept.
#[test]
fn an_export_draws_the_sky_a_pit_hides_and_waits_for_it() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let mut s = world();
    // A round pit 16 cells across and 400 m deep, in flat ground 41 cells of 30 m a side.
    let pit: Vec<f32> =
        (0..41 * 41).map(|i| if f64::from(i % 41 - 20).hypot(f64::from(i / 41 - 20)) <= 8.0 { -400.0 } else { 0.0 }).collect();
    let gt = GeoTransform { origin_x: 500_000.0, origin_y: 7_000_000.0, pixel_width: 30.0, pixel_height: -30.0 };
    let r = Raster::new("pit", 41, 41, vec![pit], gt, Crs::from_epsg(31983).unwrap(), None, ColorHint::Gray, "Float32").unwrap();
    let bytes = geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "pit", rustgis_map::RasterLayer::from_bytes(r, "pit.tif".to_string(), bytes)).unwrap();
    s.run("layer.zoomTo", &json!({"layer": "pit"})).unwrap();
    let drawn = |s: &mut Session, sky: f64| {
        s.run("raster.symbology", &json!({"layer": "pit", "type": "shadedRelief", "grey": true, "sky": sky})).unwrap();
        let png = crate::cmd::share::map_png(s, Some(200.0), Some(200.0), None).unwrap();
        crate::render::decode_png(&png).unwrap()
    };
    let open = drawn(&mut s, 0.0);
    let cold = drawn(&mut s, 1.0);
    let ready = drawn(&mut s, 1.0);
    assert!(cold.data() == ready.data(), "the first export waited for the sky");
    let red = |p: &tiny_skia::Pixmap, x: u32, y: u32| p.pixel(x, y).unwrap().red();
    // The pit's floor, in the middle, sees less sky; flat ground well outside it, all of it.
    assert!(red(&cold, 100, 100) < red(&open, 100, 100), "{} vs {}", red(&cold, 100, 100), red(&open, 100, 100));
    assert_eq!(red(&cold, 170, 100), red(&open, 170, 100));
}

/// A map export that draws a layer without its cast shadows says so, as such (not as a tile layer
/// that failed), in a PNG, a GeoTIFF and the app's map image alike; one with nothing missing says
/// nothing.
#[test]
fn a_map_export_says_a_layer_drawn_without_its_cast_shadows() {
    let mut s = with_raster();
    s.run("layer.zoomTo", &json!({"layer": "scene"})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "shadow": 1})).unwrap();
    let dir = std::env::temp_dir().join(format!("rustgis-cast-notice-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let said =
        |s: &Session| s.notices.iter().filter(|n| n.text.contains("cast shadows aren't drawn")).map(|n| n.text.clone()).collect::<Vec<_>>();
    s.run("share.exportMap", &json!({"path": dir.join("clean.png").display().to_string(), "width": 200, "height": 150})).unwrap();
    assert!(said(&s).is_empty(), "{:?}", said(&s));
    // Read in place with only its overview held: no whole grid to trace.
    let rl = s.map_mut().layers.iter_mut().find_map(|l| l.raster.as_mut()).unwrap();
    rl.in_place = true;
    let mut r = (**rl.data.as_ref().unwrap()).clone();
    r.overview = Some((800, 600));
    rl.data = Some(std::sync::Arc::new(r));
    for name in ["shadowless.png", "shadowless.tif"] {
        let before = said(&s).len();
        s.run("share.exportMap", &json!({"path": dir.join(name).display().to_string(), "width": 200, "height": 150})).unwrap();
        let now = said(&s);
        assert_eq!(now.len(), before + 1, "{name}: {now:?}");
        let last = now.last().unwrap();
        assert!(last.contains("scene: its cast shadows aren't drawn") && last.contains("read in place"), "{name}: {last}");
        assert!(!last.contains("tile layer"), "{name}: {last}");
    }
    // The app's Capture To Clipboard and Export Map download (`map_png`) say it too.
    let before = said(&s).len();
    crate::cmd::share::map_png(&mut s, Some(200.0), Some(150.0), None).unwrap();
    assert_eq!(said(&s).len(), before + 1, "{:?}", said(&s));
    std::fs::remove_dir_all(&dir).ok();
}

/// Whatever draws the map for someone says a layer drawn without its cast shadows, named by the
/// layer: the map's image, PDF and web map, and the exports of a layout, a presentation and a
/// report showing it. Drawn on the interface's thread, which doesn't wait for them, shadows still
/// being worked out are said too.
#[test]
fn every_drawing_of_the_map_says_a_layer_drawn_without_its_cast_shadows() {
    let mut s = with_raster();
    s.run("layer.zoomTo", &json!({"layer": "scene"})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "shadow": 1})).unwrap();
    s.run("layout.new", &json!({"page": "a5", "template": "map"})).unwrap();
    s.run("presentation.new", &json!({"name": "Relief"})).unwrap();
    // First, as a PNG of the presentation is its first page.
    s.run("presentation.mapPage", &json!({"title": "Relief", "at": 0})).unwrap();
    assert_eq!(s.project.presentations[0].pages[0].kind.code(), "map");
    s.run("report.new", &json!({"layer": "Countries", "name": "Relief", "fields": ["name"], "where": "name LIKE 'F%'"})).unwrap();
    s.run("report.newTemplate", &json!({"report": "Relief"})).unwrap();
    // Read in place with only its overview held: no whole grid to trace.
    let rl = s.map_mut().layers.iter_mut().find_map(|l| l.raster.as_mut()).unwrap();
    rl.in_place = true;
    let mut r = (**rl.data.as_ref().unwrap()).clone();
    r.overview = Some((800, 600));
    rl.data = Some(std::sync::Arc::new(r));
    let said = |s: &Session| s.notices.iter().filter(|n| n.text.contains("scene: its cast shadows aren't drawn")).count();
    /// Removed however the test ends.
    struct Dir(std::path::PathBuf);
    impl Drop for Dir {
        fn drop(&mut self) {
            std::fs::remove_dir_all(&self.0).ok();
        }
    }
    let dir = Dir(std::env::temp_dir().join(format!("rustgis-cast-every-{}", std::process::id())));
    std::fs::create_dir_all(&dir.0).unwrap();
    let path = |name: &str| dir.0.join(name).display().to_string();
    let draws: Vec<(&str, Box<dyn Fn(&mut Session)>)> = vec![
        ("map image", Box::new(|s| drop(crate::cmd::share::map_png(s, Some(200.0), Some(150.0), None).unwrap()))),
        ("map PDF", Box::new(|s| drop(crate::cmd::share::map_pdf(s, 72.0).unwrap()))),
        (
            "map export",
            Box::new(|s| drop(s.run("share.exportMap", &json!({"path": path("map.png"), "width": 200, "height": 150})).unwrap())),
        ),
        ("web map", Box::new(|s| drop(crate::cmd::sharing::share_bytes(s, "webMap", &json!({})).unwrap()))),
        ("layout PNG", Box::new(|s| drop(s.run("layout.export", &json!({"layout": 0, "path": path("page.png"), "dpi": 36})).unwrap()))),
        ("layout PDF", Box::new(|s| drop(s.run("layout.export", &json!({"layout": 0, "path": path("page.pdf"), "dpi": 36})).unwrap()))),
        ("presentation PDF", Box::new(|s| drop(s.run("presentation.export", &json!({"path": path("deck.pdf"), "dpi": 36})).unwrap()))),
        ("presentation PNG", Box::new(|s| drop(s.run("presentation.export", &json!({"path": path("deck.png"), "dpi": 36})).unwrap()))),
        (
            "report PDF",
            Box::new(|s| drop(s.run("report.export", &json!({"report": "Relief", "path": path("report.pdf"), "dpi": 36})).unwrap())),
        ),
    ];
    for (what, draw) in &draws {
        // A notice repeating the last one is kept once (two presentation exports in a row).
        s.notices.clear();
        draw(&mut s);
        assert!(said(&s) > 0, "{what}: {:?}", s.notices.iter().map(|n| &n.text).collect::<Vec<_>>());
    }
    // On the interface's thread a new sun's shadows aren't waited for: the image says so.
    let mut s = with_raster();
    s.run("layer.zoomTo", &json!({"layer": "scene"})).unwrap();
    s.run("raster.symbology", &json!({"type": "shadedRelief", "azimuth": 123, "shadow": 1})).unwrap();
    crate::render::on_the_interface_thread();
    // Held before they trace, the shadows are still to come whatever the computer's speed.
    let hold = crate::map::raster::hold_cast_shadows();
    crate::cmd::share::map_png(&mut s, Some(200.0), Some(150.0), None).unwrap();
    assert!(
        s.notices.iter().any(|n| n.text.contains("still being worked out")),
        "{:?}",
        s.notices.iter().map(|n| &n.text).collect::<Vec<_>>()
    );
    // A file exported there (a script's, or while a style's view loads) says it was written
    // without them, a GeoTIFF too.
    for (azimuth, name) in [(124, "here.png"), (125, "here.tif")] {
        s.run("raster.symbology", &json!({"type": "shadedRelief", "azimuth": azimuth, "shadow": 1})).unwrap();
        s.notices.clear();
        let path = path(name);
        s.run("share.exportMap", &json!({"path": path, "width": 200, "height": 150})).unwrap();
        let texts: Vec<&String> = s.notices.iter().map(|n| &n.text).collect();
        assert!(texts.iter().any(|t| t.starts_with(&path) && t.contains("still being worked out")), "{name}: {texts:?}");
    }
    drop(hold);
}

#[test]
fn raster_layers_open_style_identify_and_round_trip() {
    let mut s = with_raster();
    let l = s.map().layers.first().unwrap();
    assert!(l.is_raster(), "a new raster goes on top, as every new layer does (#808)");
    assert_eq!(l.name, "scene");
    assert_eq!(s.active_layer, Some(l.id));
    let e = l.extent();
    assert!((e.center().x + 81.0).abs() < 0.1 && (e.center().y - 42.0).abs() < 0.1, "{e:?}");
    // Rendering, stretches and enhancement.
    for p in [
        json!({"type": "stretch", "band": 2, "ramp": "Terrain"}),
        json!({"type": "classify", "classes": 4, "method": "quantile"}),
        json!({"type": "unique"}),
        json!({"type": "shadedRelief", "azimuth": 270}),
        json!({"type": "rgb"}),
    ] {
        s.run("raster.symbology", &p).unwrap_or_else(|e| panic!("{p}: {e}"));
    }
    // Bounds typed by hand are for Graduated Colors: a raster's classes are worked out.
    assert!(s.run("raster.symbology", &json!({"type": "classify", "method": "manual"})).is_err());
    assert!(s.run("raster.symbology", &json!({"type": "colormap"})).is_err());
    assert!(s.run("raster.symbology", &json!({"band": 9})).is_err());
    s.run("raster.bands", &json!({"red": 3, "green": 2, "blue": 1})).unwrap();
    s.run("raster.symbology", &json!({"type": "rgb"})).unwrap(); // keeps the combination
    assert!(s.run("raster.bands", &json!({"preset": "colorInfrared"})).is_err(), "no band 4");
    s.run("raster.stretch", &json!({"type": "standardDeviation", "n": 2.5})).unwrap();
    s.run("raster.dra", &json!({"on": true})).unwrap();
    s.run("raster.resampling", &json!({"type": "bilinear"})).unwrap();
    s.run("raster.enhance", &json!({"brightness": 20, "contrast": -10, "gamma": 1.4})).unwrap();
    s.run("layer.ramp", &json!({"ramp": "Aurora"})).unwrap();
    let st = s.map().layers.first().unwrap().raster.as_ref().unwrap().style.clone();
    assert_eq!(st.renderer, rustgis_map::RasterRenderer::Rgb { red: 2, green: 1, blue: 0 });
    assert!(st.dra && st.gamma == 1.4);
    // Feature-only commands are off for rasters, and layer conditions follow a named layer.
    assert!(s.run("table.open", &Value::Null).is_err());
    assert!(s.run("labels.enable", &json!({"layer": "scene"})).is_err());
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "single"})).unwrap();
    s.active_layer = s.map().layer_by_name("Countries").map(|l| l.id);
    s.run("raster.info", &json!({"layer": "scene"})).unwrap();
    s.active_layer = s.map().layer_by_name("scene").map(|l| l.id);
    // Identify ranks a raster's pixel with the features by the drawing order (#2488): the scene,
    // added last, is drawn over Lake Erie, so topmost reports its pixel, alone, as before.
    let erie = json!({"lon": -81.0, "lat": 42.0});
    let v = s.run("identify", &erie).unwrap();
    assert_eq!(v["raster"], true, "{v}");
    assert_eq!(v["layer"], "scene", "{v}");
    assert!(v.get("results").is_none(), "a pixel alone answers without a list: {v}");
    // Visible lists the pixel first, then the features drawn under it.
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": "visible"})).unwrap();
    let found: Vec<&str> = v["results"].as_array().unwrap().iter().map(|r| r["layer"].as_str().unwrap()).collect();
    assert_eq!(found.first(), Some(&"scene"), "{v}");
    assert!(found.contains(&"Lakes"), "{v}");
    assert_eq!(v["raster"], true, "the first result's fields stay at the top: {v}");
    // Selectable picks layers by another rule: the lake, the raster's pixel only with no feature.
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": "selectable"})).unwrap();
    assert_eq!(v["layer"], "Lakes", "{v}");
    // Moved to the bottom, the scene gives way: Lake Erie is drawn over it.
    s.run("layer.move", &json!({"layer": "scene", "to": 99})).unwrap();
    let v = s.run("identify", &erie).unwrap();
    assert_eq!(v["layer"], "Lakes", "{v}");
    assert!(v["results"].as_array().unwrap().iter().all(|r| r["raster"] != true), "{v}");
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": "visible"})).unwrap();
    let found: Vec<&str> = v["results"].as_array().unwrap().iter().map(|r| r["layer"].as_str().unwrap()).collect();
    assert_eq!(found.last(), Some(&"scene"), "the pixel comes after the features drawn over it: {v}");
    // A higher depth priority draws the scene over Lake Erie whatever the order, as the renderer
    // and the features' hits do: its pixel answers again.
    s.run("layer.priority", &json!({"layer": "scene", "value": 1})).unwrap();
    let v = s.run("identify", &erie).unwrap();
    assert_eq!(v["layer"], "scene", "{v}");
    assert_eq!(v["raster"], true, "{v}");
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0, "mode": "visible"})).unwrap();
    let found: Vec<&str> = v["results"].as_array().unwrap().iter().map(|r| r["layer"].as_str().unwrap()).collect();
    assert_eq!(found.first(), Some(&"scene"), "a higher priority comes first: {v}");
    assert!(found.contains(&"Lakes"), "{v}");
    s.run("layer.priority", &json!({"layer": "scene", "value": 0})).unwrap();
    s.run("layer.move", &json!({"layer": "scene", "to": 0})).unwrap();
    for l in ["Cities", "Rivers", "Lakes", "Countries"] {
        s.run("layer.visibility", &json!({"layer": l, "visible": false})).unwrap();
    }
    let v = s.run("identify", &json!({"lon": -81.0, "lat": 42.0})).unwrap();
    assert_eq!(v["raster"], true, "{v}");
    assert!(v["attributes"]["Band 1"].is_string());
    let info = s.run("raster.info", &Value::Null).unwrap();
    assert_eq!(info["crs"], "EPSG:32617");
    assert_eq!(info["bands"].as_array().map(Vec::len), Some(3));
    // Export, then reopen from the file.
    let dir = std::env::temp_dir().join(format!("rustgis-raster-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let tif = dir.join("out.tif");
    s.run("share.exportRaster", &json!({"path": tif.display().to_string()})).unwrap();
    s.run("layer.addData", &json!({"path": tif.display().to_string()})).unwrap();
    assert!(s.map().layer_by_name("out").is_some_and(|l| l.raster.as_ref().is_some_and(|r| r.path.is_some())));
    // Save and reload the project: the upload is embedded, the file is reopened by path.
    let proj = dir.join("p.rgis");
    s.run("project.saveAs", &json!({"path": proj.display().to_string()})).unwrap();
    s.run("project.open", &json!({"path": proj.display().to_string()})).unwrap();
    for name in ["scene", "out"] {
        let l = s.map().layer_by_name(name).unwrap();
        assert!(l.raster.as_ref().unwrap().data.is_some(), "{name} reloaded");
    }
    assert!(s.map().layer_by_name("scene").unwrap().raster.as_ref().unwrap().style.dra, "style kept");
    // Undo after a style change restores the previous style.
    s.active_layer = s.map().layer_by_name("scene").map(|l| l.id);
    s.run("raster.dra", &json!({"on": false})).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    assert!(s.map().layer_by_name("scene").unwrap().raster.as_ref().unwrap().style.dra);
    let _ = std::fs::remove_dir_all(&dir);
    // The map renders with rasters.
    assert!(crate::cmd::share::map_png(&mut s, Some(320.0), Some(200.0), None).is_ok());
}

/// #348: `raster.mask` hides pixel values on the fly: values drawn as no data and a range,
/// kept in the project and undone like any style change.
#[test]
fn raster_masks_hide_values() {
    let mut s = with_raster();
    let style = |s: &Session| s.map().layer_by_name("scene").unwrap().raster.as_ref().unwrap().style.clone();
    let info = s.run("raster.info", &Value::Null).unwrap();
    let (lo, hi) = (info["bands"][0]["min"].as_f64().unwrap(), info["bands"][0]["max"].as_f64().unwrap());
    assert!(info["mask"].is_null());
    s.run("raster.mask", &json!({"values": format!("{lo}, {lo} ; {hi}")})).unwrap();
    assert_eq!(style(&s).mask.values, vec![lo, hi], "text, sorted and without repeats");
    let rl = s.map().layer_by_name("scene").unwrap().raster.clone().unwrap();
    let st = rl.masked_stats().unwrap();
    assert!(st[0].min > lo && st[0].max < hi, "{:?}", st[0]);
    // A range on top, then the other way round; a bound given as null is removed.
    s.run("raster.mask", &json!({"min": lo + 1.0, "max": hi - 1.0})).unwrap();
    s.run("raster.mask", &json!({"inside": true, "max": null})).unwrap();
    let m = style(&s).mask;
    assert_eq!((m.min, m.max, m.inside, m.values.len()), (Some(lo + 1.0), None, true, 2));
    assert!(s.run("raster.info", &Value::Null).unwrap()["mask"].as_str().is_some_and(|t| t.contains('≥')));
    // Refused: a reversed range, values that aren't numbers, too many values.
    assert!(s.run("raster.mask", &json!({"min": 5, "max": 1})).is_err());
    assert!(s.run("raster.mask", &json!({"values": "1, x"})).is_err());
    assert!(s.run("raster.mask", &json!({"values": [1, "nan"]})).is_err());
    assert!(s.run("raster.mask", &json!({"min": "x"})).is_err());
    assert!(s.run("raster.mask", &json!({"values": (0..300).collect::<Vec<_>>()})).is_err());
    assert_eq!(style(&s).mask, m, "nothing changed by a refused mask");
    // Class breaks follow the pixels shown.
    s.run("raster.mask", &json!({"clear": true, "min": lo, "max": (lo + hi) / 2.0})).unwrap();
    s.run("raster.symbology", &json!({"type": "classify", "classes": 4})).unwrap();
    let top = |s: &Session| match style(s).renderer {
        rustgis_map::RasterRenderer::Classify { breaks, .. } => breaks.last().copied().unwrap_or_default(),
        _ => f64::NAN,
    };
    assert!(top(&s) <= (lo + hi) / 2.0, "{}", top(&s));
    s.run("raster.mask", &json!({"max": null})).unwrap();
    assert!(top(&s) > (lo + hi) / 2.0, "worked out again without the bound");
    // Masking down to one value collapses the classes; clearing the mask brings back the 4 asked for.
    let classes = |s: &Session| match style(s).renderer {
        rustgis_map::RasterRenderer::Classify { breaks, .. } => breaks.len(),
        _ => 0,
    };
    s.run("raster.mask", &json!({"min": lo, "max": lo})).unwrap();
    assert_eq!(classes(&s), 1);
    s.run("raster.mask", &json!({"clear": true})).unwrap();
    assert_eq!(classes(&s), 4);
    // Undo the clear and the one-value range.
    s.run("edit.undo", &Value::Null).unwrap();
    s.run("edit.undo", &Value::Null).unwrap();
    // Breaks edited by hand are kept.
    let mut edited = style(&s);
    if let rustgis_map::RasterRenderer::Classify { breaks, .. } = &mut edited.renderer {
        breaks[0] += 0.5;
    }
    let id = s.map().layer_by_name("scene").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().raster.as_mut().unwrap().style = edited.clone();
    s.run("raster.mask", &json!({"values": [lo]})).unwrap();
    assert_eq!(style(&s).renderer, edited.renderer);
    // Undo that mask.
    s.run("edit.undo", &Value::Null).unwrap();
    // Undo removing the max bound; then saved and drawn.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(style(&s).mask.max, Some((lo + hi) / 2.0));
    let dir = std::env::temp_dir().join(format!("rustgis-mask-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let proj = dir.join("p.rgis");
    s.run("project.saveAs", &json!({"path": proj.display().to_string()})).unwrap();
    s.run("project.open", &json!({"path": proj.display().to_string()})).unwrap();
    assert_eq!(style(&s).mask.max, Some((lo + hi) / 2.0), "kept in the project");
    let _ = std::fs::remove_dir_all(&dir);
    assert!(crate::cmd::share::map_png(&mut s, Some(320.0), Some(200.0), None).is_ok());
    s.active_layer = s.map().layer_by_name("scene").map(|l| l.id);
    s.run("raster.mask", &json!({"clear": true})).unwrap();
    assert!(style(&s).mask.is_empty());
}

