#[test]
fn service_command_keeps_missing_layer_reason_and_scrubs_every_known_address() {
    const WMS: &str = r#"<WMS_Capabilities version="1.3.0" xmlns="http://www.opengis.net/wms" xmlns:xlink="http://www.w3.org/1999/xlink">
<Service><Title>Test WMS</Title></Service><Capability>
<Request><GetMap><Format>image/png</Format><DCPType><HTTP><Get><OnlineResource xlink:href="https://maps.example.com/wms?"/></Get></HTTP></DCPType></GetMap></Request>
<Layer><Title>Root</Title>
<Layer><Name>roads</Name><Title>Roads</Title></Layer></Layer></Capability></WMS_Capabilities>"#;
    let mut s = Session::new(Project::default());
    for suffix in ["?token=service-secret", "#service-secret", "?token=service-secret secret-tail", "#service-secret secret-tail"] {
        let url = format!("https://maps.example.com/wms{suffix}");
        let missing = format!("{url} again {url}");
        let mark = s.notice_mark();
        let error = s.run("service.add", &json!({"url": url, "type": "wms", "layer": missing, "text": WMS})).unwrap_err();
        if suffix.contains(' ') {
            // Invalid addresses are refused before capabilities are read.
            assert!(error.contains("the address has spaces in it"), "{error}");
        } else {
            assert!(error.contains("no layer '") && error.ends_with("(service.layers lists them)"), "{error}");
            assert_eq!(error.matches("maps.example.com/wms").count(), 3, "{error}");
        }
        assert!(!error.contains("service-secret") && !error.contains("secret-tail"), "{error}");
        assert_eq!(Session::redacted(&error).as_str(), error);
        assert_eq!(s.notices_since(mark).iter().map(|n| n.text.as_str()).collect::<Vec<_>>(), [error.as_str()]);
        assert!(s.diagnostics.records().iter().any(|r| r.source == "service.add" && r.message == error));
    }
    let report = s.diagnostics.report(rustgis_data::diagnostics::Filter::All);
    assert!(!report.contains("service-secret") && !report.contains("secret-tail"), "{report}");
}

#[test]
fn diagnostics_capture_notices_without_an_open_pane_or_project_persistence() {
    use rustgis_data::diagnostics::{Filter, MAX_DETAILS_BYTES, MAX_MESSAGE_BYTES, Severity};
    let mut s = Session::new(Project::default());
    let mark = s.notice_mark();
    s.notify("diagnostics-session-only information", false);
    s.warn("diagnostics-session-only warning");
    s.notify("diagnostics-session-only error Authorization: Bearer never-retain-this", true);
    let notices = s.notices_since(mark);
    assert_eq!(notices.len(), 3);
    assert!(!notices[0].error && !notices[1].error && notices[2].error);
    assert!(!notices[2].text.contains("never-retain-this"));
    let records: Vec<_> = s.diagnostics.records().into_iter().filter(|r| r.message.starts_with("diagnostics-session-only")).collect();
    assert_eq!(records.iter().map(|r| r.severity).collect::<Vec<_>>(), [Severity::Info, Severity::Warning, Severity::Error]);
    assert!(records.iter().all(|r| r.source == "Application" && r.timestamp_ms > 0));
    assert!(!s.diagnostics.report(Filter::All).contains("never-retain-this"));
    // A project's saved text holds none of the history (the docs promise it).
    let saved = serde_json::to_string(&s.project).unwrap();
    assert!(!saved.contains("diagnostics-session-only"));
    s.notify("界".repeat(3000), false);
    // The notice keeps its words to redaction's own bound (8 KiB, an ellipsis at the cut), not
    // the record's 2 KiB; only the history's record copy takes the message bound.
    let notice = &s.notices.last().unwrap().text;
    assert!(notice.len() <= MAX_DETAILS_BYTES && notice.ends_with('…'), "{}", notice.len());
    let last = s.diagnostics.records();
    let record = last.last().unwrap();
    assert!(record.message.len() <= MAX_MESSAGE_BYTES && record.message.ends_with('…'), "{}", record.message.len());
    s.run("project.new", &json!({})).unwrap();
    let records = s.diagnostics.records();
    assert!(records.iter().any(|r| r.message == "diagnostics-session-only information"));
    assert!(records.iter().any(|r| r.message == "diagnostics-session-only warning"));
}

#[test]
fn diagnostics_keep_failed_command_context_without_changing_notice_rollback() {
    use rustgis_data::diagnostics::Severity;
    let mut s = Session::new(Project::default());
    let before = s.project.name.clone();
    let mark = s.notice_mark();
    let result = s.guarded("Diagnostics rollback", true, |s| {
        s.project.name = "not committed".to_string();
        s.notify("diagnostics-rollback information", false);
        s.warn("diagnostics-rollback warning");
        s.notify("diagnostics-rollback error", true);
        Err("diagnostics-rollback failed".to_string())
    });
    assert!(result.is_err());
    assert_eq!(s.project.name, before);
    assert!(s.notices_since(mark).iter().all(|n| n.error));
    let records = s.diagnostics.records();
    for text in
        ["diagnostics-rollback information", "diagnostics-rollback warning", "diagnostics-rollback error", "diagnostics-rollback failed"]
    {
        assert!(records.iter().any(|r| r.message == text), "missing {text}");
    }
    // Registered command ids, not command parameters, identify the source.
    assert!(s.run("layer.rename", &json!({"layer": "diagnostics-missing-layer", "name": "never-copy-parameters"})).is_err());
    assert!(s.diagnostics.records().iter().any(|r| r.source == "layer.rename" && r.severity == Severity::Error));
    s.notify("diagnostics-after-command", false);
    assert!(s.diagnostics.records().iter().any(|r| r.message == "diagnostics-after-command" && r.source == "Application"));
    assert!(!s.diagnostics.report(rustgis_data::diagnostics::Filter::All).contains("never-copy-parameters"));

    // A panic caught inside the command must still restore Application attribution afterward.
    fn panic_run(_: &mut Session, _: &Value) -> crate::CmdResult {
        panic!("diagnostics source restore");
    }
    let command = crate::CommandSpec {
        id: "diagnostics.testSourceRestore",
        label: "Diagnostics source restore",
        mutates: false,
        run: crate::policy::Handler::new(panic_run),
        effects: crate::policy::Effects::NONE,
        ..*s.registry.get("map.zoomIn").unwrap()
    };
    s.registry.commands.push(command);
    assert!(s.run(command.id, &Value::Null).is_err());
    s.notify("diagnostics-after-panic", false);
    assert!(s.diagnostics.records().iter().any(|r| r.message == "diagnostics-after-panic" && r.source == "Application"));
}

#[test]
fn diagnostics_survive_project_replacement_rolled_back_within_a_command() {
    let mut s = Session::new(Project::default());
    let before = s.project.name.clone();
    let result = s.guarded("Diagnostics replacement rollback", true, |s| {
        s.run("project.new", &json!({"name": "temporary replacement"}))?;
        s.notify("diagnostics-replacement context", false);
        Err("diagnostics-replacement failed".to_string())
    });
    assert!(result.is_err());
    assert_eq!(s.project.name, before);
    assert!(s.diagnostics.records().iter().any(|r| r.message == "diagnostics-replacement context"));
    assert!(s.diagnostics.records().iter().any(|r| r.message == "diagnostics-replacement failed"));
}

#[test]
fn diagnostics_network_requests_belong_only_to_the_command_session() {
    use rustgis_data::diagnostics::{Capture, Network, NetworkKind};

    fn failure(message: &str) {
        Capture::current().network_failure(
            "Network",
            message,
            "",
            Network {
                url: "https://session-owned.example.org/request".to_string(),
                method: "GET".to_string(),
                status: Some(503),
                duration_ms: Some(1),
                kind: NetworkKind::Http,
            },
        );
    }

    fn request(_: &mut Session, params: &Value) -> crate::CmdResult {
        let message = params.as_str().unwrap();
        failure(message);
        match message {
            "b error" => Err("command refused".to_string()),
            "b panic" => panic!("command panicked"),
            _ => Ok(Value::Null),
        }
    }

    let mut a = Session::new(Project::default());
    let mut b = Session::new(Project::default());
    let command = crate::CommandSpec {
        id: "diagnostics.testRequest",
        label: "Diagnostics request",
        mutates: false,
        run: crate::policy::Handler::new(request),
        effects: crate::policy::Effects::NONE,
        ..*a.registry.get("map.zoomIn").unwrap()
    };
    a.registry.commands.push(command);
    b.registry.commands.push(command);
    failure("unowned before command");
    a.run(command.id, &json!("a command")).unwrap();
    {
        let _a = a.diagnostics.enter();
        b.run(command.id, &json!("b command")).unwrap();
        assert!(b.run(command.id, &json!("b error")).is_err());
        assert!(b.run(command.id, &json!("b panic")).is_err());
        // Every return path, including a caught command panic, restores A's enclosing scope.
        failure("a restored");
    }
    failure("unowned after command");
    let messages = |s: &Session| s.diagnostics.records().into_iter().filter(|r| r.network.is_some()).map(|r| r.message).collect::<Vec<_>>();
    assert_eq!(messages(&a), ["a command", "a restored"]);
    assert_eq!(messages(&b), ["b command", "b error", "b panic"]);
}

/// The web app's `?blank&projection=EPSG:3010` (discussion #81): an empty project starts in a
/// national grid, and that start is neither an edit to undo nor unsaved work.
#[test]
fn blank_project_starts_in_a_projected_crs() {
    isolate_plugins();
    let mut s = Session::new(Project::default());
    assert!(s.map().layers.is_empty());
    let r = s.run("map.projection", &json!({"type": "EPSG:3010"})).unwrap();
    assert_eq!(r["projection"], "EPSG:3010");
    assert!(s.dirty() && s.can_undo());
    s.clear_history();
    assert!(!s.dirty() && !s.can_undo());
    assert_eq!(s.map().projection.code(), "EPSG:3010");
    // It opens on the country, and reports that view back.
    s.run("map.zoomToExtent", &json!({"extent": [10.5, 55.0, 24.5, 69.5]})).unwrap();
    let e = s.run("map.extent", &Value::Null).unwrap()["extent"].clone();
    let n: Vec<f64> = e.as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
    assert!(n[0] < 11.0 && n[2] > 24.0 && n[1] < 55.5 && n[3] > 69.0 && n[3] - n[1] < 25.0, "{n:?}");
    for bad in [json!(null), json!([1, 2, 3]), json!([20, 50, 10, 60]), json!([0, 0, 200, 10]), json!(["a", 0, 1, 1])] {
        assert!(s.run("map.zoomToExtent", &json!({"extent": bad})).is_err(), "{bad}");
    }
    assert!(crate::cmd::share::map_png(&mut s, Some(400.0), Some(300.0), None).unwrap().len() > 1000);
}

/// CSV and GPX exports say what the format couldn't hold (a line layer's geometry and a
/// multipoint's other points in CSV; other fields, polygons' holes and multipoints in GPX), and
/// Data Interop's KML and GPX the rows without geometry, and Export Table the same for a table
/// that keeps geometry; a layer or table each holds whole gets no such notice.
#[test]
fn csv_and_gpx_exports_say_what_they_leave_out() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let dir = std::env::temp_dir().join(format!("rustgis-engine-csv-gpx-losses-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let square = |x: f64, hole: bool| {
        let ring = |a: f64, b: f64| vec![Coord::new(a, a), Coord::new(b, a), Coord::new(b, b), Coord::new(a, b), Coord::new(a, a)];
        let mut rings = vec![ring(x, x + 4.0)];
        if hole {
            rings.push(ring(x + 1.0, x + 2.0));
        }
        Geometry::Polygon(vec![rings])
    };
    let layer = |name: &str, kind, rows: Vec<(Geometry, Vec<V>)>| {
        let mut ds = Dataset::new(name, kind, vec![Field::new("name", FieldType::Text), Field::new("height", FieldType::Double)]);
        for (g, a) in rows {
            ds.push(Some(g), a);
        }
        ds
    };
    let mut s = Session::new(Project::default());
    s.map_mut().add_dataset(layer("Areas", GeometryType::Polygon, vec![(square(0.0, true), vec![V::Text("A".into()), V::Float(2.5)])]));
    let pts = vec![
        (Geometry::Point(Coord::new(1.0, 2.0)), vec![V::Text("P".into()), V::Null]),
        (Geometry::MultiPoint(vec![Coord::new(3.0, 4.0), Coord::new(5.0, 6.0)]), vec![V::Text("M".into()), V::Null]),
    ];
    s.map_mut().add_dataset(layer("Sites", GeometryType::Point, pts));
    let clean = vec![(Geometry::Point(Coord::new(1.0, 2.0)), vec![V::Text("P".into()), V::Null])];
    s.map_mut().add_dataset(layer("Clean", GeometryType::Point, clean.clone()));
    // Names alone, which GPX holds whole.
    let named = |mut ds: Dataset| {
        ds.fields.truncate(1);
        ds.features.iter_mut().for_each(|f| f.attrs.truncate(1));
        ds
    };
    s.map_mut().add_dataset(named(layer("Names", GeometryType::Point, clean)));
    let said = |s: &mut Session, id: &str, p: Value| {
        let mark = s.notice_mark();
        s.run(id, &p).unwrap();
        s.notices_since(mark).iter().map(|n| n.text.clone()).filter(|t| !t.starts_with("Exported ")).collect::<Vec<_>>()
    };
    let out = |name: &str| dir.join(name).display().to_string();
    let n = said(&mut s, "share.exportLayer", json!({"layer": "Areas", "path": out("areas.csv")}));
    assert!(n.len() == 1 && n[0].contains("the geometry of 1 feature wasn't written"), "{n:?}");
    let n = said(&mut s, "share.exportLayer", json!({"layer": "Sites", "path": out("sites.csv")}));
    assert!(n.len() == 1 && n[0].contains("1 feature has more than one point"), "{n:?}");
    let n = said(&mut s, "share.exportLayer", json!({"layer": "Areas", "path": out("areas.gpx")}));
    assert_eq!(n.len(), 2, "{n:?}");
    assert!(
        n[0].contains("1 field wasn't written: 'height'")
            && n[1].contains("1 polygon was written as tracks")
            && n[1].contains("1 hole left out"),
        "{n:?}"
    );
    let n = said(&mut s, "share.exportLayer", json!({"layer": "Sites", "path": out("sites.gpx")}));
    assert!(n.len() == 2 && n[0].contains("'height'") && n[1].contains("1 multipoint was written as a waypoint for each"), "{n:?}");
    let n = said(&mut s, "data.convert", json!({"layer": "Areas", "format": "gpx"}));
    assert!(n.iter().any(|t| t.contains("'height'")) && n.iter().any(|t| t.contains("tracks")), "{n:?}");
    let n = said(&mut s, "data.convert", json!({"layer": "Areas", "format": "csv"}));
    assert!(n.iter().any(|t| t.contains("wasn't written, only the attributes")), "{n:?}");
    // Both formats count the row without geometry and name the omitted null field.
    let mut rows = layer("Rows", GeometryType::Point, vec![(Geometry::Point(Coord::new(1.0, 2.0)), vec![V::Text("P".into()), V::Null])]);
    rows.push(None, vec![V::Text("no place".into()), V::Null]);
    s.map_mut().add_dataset(rows);
    for format in ["kml", "gpx"] {
        let n = said(&mut s, "data.convert", json!({"layer": "Rows", "format": format}));
        assert!(n.iter().any(|t| t.contains("1 features without drawable geometry were left out")), "{format}: {n:?}");
        assert_eq!(n.len(), 2, "{format}: {n:?}");
        if format == "kml" {
            assert!(n.iter().any(|t| t.contains("KML omitted 1 field with no values in the placemarks written ('height')")), "{n:?}");
        } else {
            assert!(n.iter().any(|t| t.contains("1 field wasn't written: 'height'")), "{n:?}");
        }
    }
    // A standalone table keeps geometry too: Export Table says the same, and nothing for a clean one.
    let areas = layer("Area table", GeometryType::Polygon, vec![(square(0.0, true), vec![V::Text("A".into()), V::Float(2.5)])]);
    let points =
        layer("Point table", GeometryType::Point, vec![(Geometry::Point(Coord::new(1.0, 2.0)), vec![V::Text("P".into()), V::Null])]);
    s.project.tables.push(crate::project::Table::new(9001, areas));
    s.project.tables.push(crate::project::Table::new(9002, points));
    let n = said(&mut s, "share.exportTable", json!({"table": 9001, "path": out("table.csv")}));
    assert!(n.len() == 1 && n[0].contains("the geometry of 1 feature wasn't written"), "{n:?}");
    let n = said(&mut s, "share.exportTable", json!({"table": 9001, "path": out("table.gpx")}));
    assert!(n.iter().any(|t| t.contains("'height'")) && n.iter().any(|t| t.contains("1 hole left out")), "{n:?}");
    let n = said(&mut s, "share.exportTable", json!({"table": 9002, "path": out("clean-table.csv")}));
    assert_eq!(n, Vec::<String>::new());
    // Points alone, their other field empty: CSV holds them whole; GPX names the field it leaves out.
    assert_eq!(said(&mut s, "share.exportLayer", json!({"layer": "Clean", "path": out("clean.csv")})), Vec::<String>::new());
    assert_eq!(said(&mut s, "data.convert", json!({"layer": "Clean", "format": "csv"})), Vec::<String>::new());
    for n in [
        said(&mut s, "share.exportTable", json!({"table": 9002, "path": out("clean-table.gpx")})),
        said(&mut s, "share.exportLayer", json!({"layer": "Clean", "path": out("clean.gpx")})),
        said(&mut s, "data.convert", json!({"layer": "Clean", "format": "gpx"})),
    ] {
        assert!(n.len() == 1 && n[0].contains("1 field wasn't written: 'height'"), "{n:?}");
    }
    // Names alone: GPX holds them whole.
    assert_eq!(said(&mut s, "share.exportLayer", json!({"layer": "Names", "path": out("names.gpx")})), Vec::<String>::new());
    assert_eq!(said(&mut s, "data.convert", json!({"layer": "Names", "format": "gpx"})), Vec::<String>::new());
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn exporting_features_refuses_to_replace_an_existing_geopackage() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-gpkg-preserve-{}", std::process::id()));
    if dir.exists() {
        std::fs::remove_dir_all(&dir).unwrap();
    }
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("county.gpkg");
    let mut s = world();
    s.run("share.exportLayer", &json!({"layer": "Cities", "path": path})).unwrap();
    let conn = rusqlite::Connection::open(&path).unwrap();
    conn.execute_batch(
        "CREATE TABLE zoning (name TEXT);
         INSERT INTO zoning VALUES ('residential');
         INSERT INTO gpkg_contents (table_name, data_type, identifier) VALUES ('zoning', 'attributes', 'zoning');",
    )
    .unwrap();
    drop(conn);
    let before = std::fs::read(&path).unwrap();
    let error = s.run("share.exportLayer", &json!({"layer": "Countries", "path": path})).unwrap_err();
    assert!(error.to_string().contains("Choose a new filename"), "{error}");
    assert_eq!(std::fs::read(&path).unwrap(), before);
    std::fs::remove_dir_all(dir).unwrap();
}

/// A new GeoPackage whose asked-for table name is reserved says what the table is called
/// instead; one written under the name asked for says nothing of it.
#[test]
fn a_new_geopackage_says_when_its_table_name_was_changed() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-gpkg-rename-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    let said = |s: &Session, mark: u64| s.notices_since(mark).iter().filter(|n| n.text.contains("instead of")).count();
    let mark = s.notice_mark();
    let path = dir.join("reserved.gpkg");
    let out = s.run("share.exportLayer", &json!({"layer": "Cities", "path": path, "tableName": "gpkg_cities"})).unwrap();
    assert_eq!(out["table"].as_str(), Some("layer_gpkg_cities"), "{out}");
    assert_eq!(said(&s, mark), 1, "{:?}", s.notices_since(mark));
    let both = |s: &Session, mark: u64| {
        s.notices_since(mark).iter().any(|n| n.text.contains("wrote the table layer_gpkg_cities instead of 'gpkg_cities'"))
    };
    assert!(both(&s, mark), "{:?}", s.notices_since(mark));
    // The default name, the layer's, is said the same way when it is changed.
    s.run("layer.rename", &json!({"layer": "Cities", "name": "gpkg_cities"})).unwrap();
    let mark = s.notice_mark();
    let path = dir.join("default.gpkg");
    let out = s.run("share.exportLayer", &json!({"layer": "gpkg_cities", "path": path})).unwrap();
    assert_eq!(out["table"].as_str(), Some("layer_gpkg_cities"), "{out}");
    assert!(both(&s, mark), "{:?}", s.notices_since(mark));
    s.run("layer.rename", &json!({"layer": "gpkg_cities", "name": "Cities"})).unwrap();
    // A control character in the name asked for is dropped, and shown escaped in the notice.
    let mark = s.notice_mark();
    let path = dir.join("control.gpkg");
    let out = s.run("share.exportLayer", &json!({"layer": "Cities", "path": path, "tableName": "road\nnetwork"})).unwrap();
    assert_eq!(out["table"].as_str(), Some("roadnetwork"), "{out}");
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("instead of 'road\\nnetwork'")), "{:?}", s.notices_since(mark));
    let mark = s.notice_mark();
    let path = dir.join("plain.gpkg");
    let out = s.run("share.exportLayer", &json!({"layer": "Cities", "path": path, "tableName": "towns"})).unwrap();
    assert_eq!(out["table"].as_str(), Some("towns"), "{out}");
    assert_eq!(said(&s, mark), 0, "{:?}", s.notices_since(mark));
    drop(s);
    std::fs::remove_dir_all(dir).unwrap();
}

/// Export Features adds a layer to an existing GeoPackage as one more table, or replaces one of
/// its tables, saying which; a layer read in place from that GeoPackage can go back into it (its
/// filtered copy as another table). `mode` and `tableName` are for GeoPackages only.
#[test]
fn exporting_features_adds_or_replaces_a_table_in_an_existing_geopackage() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-gpkg-add-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("county.gpkg");
    let mut s = world();
    s.run("share.exportLayer", &json!({"layer": "Cities", "path": path})).unwrap();
    let mark = s.notice_mark();
    let out = s.run("share.exportLayer", &json!({"layer": "Countries", "path": path, "mode": "addTable"})).unwrap();
    assert_eq!((out["table"].as_str(), out["replaced"].as_bool()), (Some("Countries"), Some(false)));
    let texts: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(texts.iter().any(|t| t.ends_with("added the table Countries")), "{texts:?}");
    let tables = rustgis_data::source::layers(&path).unwrap();
    assert_eq!(tables, ["Cities", "Countries"]);
    // Taken: refused, unless replacing.
    let e = s.run("share.exportLayer", &json!({"layer": "Cities", "path": path, "mode": "addTable"})).unwrap_err();
    assert!(e.to_string().contains("already has a table Cities"), "{e}");
    let cities = s.map().layer_by_name("Cities").map(|l| l.dataset.features.len()).unwrap();
    let mark = s.notice_mark();
    let out =
        s.run("share.exportLayer", &json!({"layer": "Countries", "path": path, "mode": "replaceTable", "tableName": "Cities"})).unwrap();
    assert_eq!(out["replaced"].as_bool(), Some(true));
    assert!(s.notices_since(mark).iter().any(|n| n.text.contains("replaced its table Cities, dropping")));
    let countries = s.map().layer_by_name("Countries").map(|l| l.dataset.features.len()).unwrap();
    let count = |t: &str| rustgis_data::source::open_path(&path, Some(t)).unwrap().info().count;
    assert_eq!(count("Cities"), Some(countries as u64));
    assert_ne!(cities, countries);
    // Read in place from the GeoPackage, then exported back into it.
    s.run("layer.addData", &json!({"path": path.display().to_string(), "layer": "Countries", "stream": true, "name": "InPlace"})).unwrap();
    s.run("share.exportLayer", &json!({"layer": "InPlace", "path": path, "mode": "addTable", "tableName": "copy"})).unwrap();
    assert_eq!(count("copy"), Some(countries as u64));
    // Replacing the table a layer reads in place makes it read the new table, and says so.
    let kind =
        |s: &Session| s.map().layer_by_name("InPlace").and_then(|l| l.source.as_ref()).and_then(|src| src.info()).map(|i| i.geometry_type);
    s.map_mut().layers.iter_mut().for_each(|l| {
        l.sync_source(&rustgis_geom::Extent::new(-20.0, -20.0, 20.0, 20.0), true);
    });
    assert_eq!(kind(&s), Some(rustgis_data::GeometryType::Polygon));
    let mark = s.notice_mark();
    s.run("share.exportLayer", &json!({"layer": "Cities", "path": path, "mode": "replaceTable", "tableName": "Countries"})).unwrap();
    assert_eq!(kind(&s), Some(rustgis_data::GeometryType::Point), "the new table's");
    let read = s.map().layer_by_name("InPlace").map(|l| l.load_all().map(|ds| ds.features.len()));
    assert_eq!(read, Some(Ok(cities)), "its features are the new table's");
    assert!(s.notices_since(mark).iter().any(|n| n.text.ends_with("1 layer reads Countries in place, now the new table")));
    // A layer loaded for editing from a replaced table keeps its rows and edits, and is named.
    s.run("gpkg.addLayer", &json!({"path": path, "table": "Cities", "name": "Editing"})).unwrap();
    let mark = s.notice_mark();
    s.run("share.exportLayer", &json!({"layer": "Countries", "path": path, "mode": "replaceTable", "tableName": "Cities"})).unwrap();
    assert!(
        s.notices_since(mark)
            .iter()
            .any(|n| n.text.contains("1 layer loaded for editing from Cities still shows") && n.text.ends_with(": Editing")),
        "{:?}",
        s.notices_since(mark)
    );
    // A standalone table goes in as an attribute table.
    s.run("layer.addDataText", &json!({"fileName": "owners.csv", "text": "name,n\nShelby,1\n"})).unwrap();
    let table = s.project.tables.last().map(|t| t.id).unwrap();
    let out = s.run("share.exportTable", &json!({"table": table, "path": path, "mode": "addTable"})).unwrap();
    assert_eq!(out["table"].as_str(), Some("owners"));
    let c = rusqlite::Connection::open(&path).unwrap();
    assert_eq!(
        c.query_row("SELECT data_type FROM gpkg_contents WHERE table_name = 'owners'", [], |r| r.get::<_, String>(0)).unwrap(),
        "attributes"
    );
    drop(c);
    // Other formats take neither; a mode not known is refused.
    let geojson = dir.join("x.geojson");
    for p in [json!({"mode": "addTable"}), json!({"tableName": "x"})] {
        let mut p = p;
        p["path"] = json!(geojson);
        assert!(s.run("share.exportLayer", &p).unwrap_err().to_string().contains("GeoPackage"), "{p}");
    }
    assert!(s.run("share.exportLayer", &json!({"path": path, "mode": "append"})).is_err());
    // Not strings: refused, not taken for the default.
    for p in [json!({"mode": 1}), json!({"mode": "addTable", "tableName": ["x"]})] {
        let mut p = p;
        p["path"] = json!(path);
        assert!(s.run("share.exportLayer", &p).unwrap_err().to_string().contains("must be a string"), "{p}");
    }
    assert!(!geojson.exists());
    // The layer read in place holds the file open, which Windows won't remove.
    drop(s);
    std::fs::remove_dir_all(dir).unwrap();
}

/// A layer whose Z values were dropped on import says so when added, read whole or in place, and
/// again when exported or converted; a 2D layer's export says nothing of it.
#[test]
fn dropped_z_values_are_said_on_import_and_export() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-zm-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let src = dir.join("wells.geojson");
    std::fs::write(
        &src,
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","properties":{},"geometry":{"type":"Point","coordinates":[1,2,30]}}]}"#,
    )
    .unwrap();
    isolate_plugins();
    let mut s = Session::new(Project::default());
    for stream in [false, true] {
        let mark = s.notice_mark();
        let id = s.run("layer.addData", &json!({"path": src, "stream": stream})).unwrap()["layer"].as_u64().unwrap();
        assert!(s.notices_since(mark).iter().any(|n| n.text.contains("Z or M values")), "stream {stream}: {:?}", s.notices_since(mark));
        let said = |s: &Session, mark, path: &std::path::Path| {
            let notes: Vec<_> = s.notices_since(mark).iter().filter(|n| n.text.contains("Z or M")).map(|n| &n.text).collect();
            let loss = if stream {
                format!("wells: {}", rustgis_data::zm_note(Some(1)))
            } else {
                "its geometry has no Z or M values, which were dropped when wells was read".into()
            };
            assert_eq!(notes, [&format!("{}: {loss}", path.display())], "stream {stream}");
        };
        // Every output describes its loss, even after import or an earlier export said it.
        // A counted reader diagnostic replaces the generic export warning, rather than adding one.
        for repeat in 0..2 {
            let out = dir.join(format!("out-{stream}-{repeat}.geojson"));
            let mark = s.notice_mark();
            s.run("share.exportLayer", &json!({"layer": id, "path": out})).unwrap();
            said(&s, mark, &out);
            assert!(std::fs::read_to_string(&out).unwrap().contains("[1.0,2.0]"));
        }
        let converted = dir.join(format!("converted-{stream}.csv"));
        let mark = s.notice_mark();
        s.run("data.convert", &json!({"layer": id, "format": "wkt", "path": converted})).unwrap();
        said(&s, mark, &converted);
    }
    let mut s = world();
    let mark = s.notice_mark();
    s.run("share.exportLayer", &json!({"layer": "Cities", "path": dir.join("cities.geojson")})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("Z or M")), "{:?}", s.notices_since(mark));
    std::fs::remove_dir_all(dir).unwrap();
}

/// A standalone table can hold geometry whose Z values were dropped when it was read (a plugin's
/// output, a project file): exporting it says so, to every format, once the file is written, as
/// `share.exportLayer` does. A table read without Z, and a write that fails, say nothing of it.
#[test]
fn exporting_a_table_says_its_dropped_z_values() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-table-zm-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let src = dir.join("wells.geojson");
    std::fs::write(
        &src,
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"depth":30},"geometry":{"type":"Point","coordinates":[1,2,30]}}]}"#,
    )
    .unwrap();
    isolate_plugins();
    let mut s = Session::new(Project::default());
    let (wells, report) = rustgis_data::io::read_path(&src).unwrap();
    assert!(wells.zm_dropped && report.messages.iter().any(|m| m.contains("Z or M")), "premise: the reader dropped Z");
    s.project.add_table(wells);
    let said = |s: &Session, mark| -> Vec<String> {
        s.notices_since(mark).iter().filter(|n| n.text.contains("Z or M")).map(|n| n.text.clone()).collect()
    };
    for ext in ["geojson", "csv", "shp", "zip"] {
        let out = dir.join(format!("wells.{ext}")).display().to_string();
        let mark = s.notice_mark();
        s.run("share.exportTable", &json!({"table": "wells", "path": out})).unwrap();
        assert_eq!(said(&s, mark), [format!("{out}: its geometry has no Z or M values, which were dropped when wells was read")], ".{ext}");
    }
    // The file holds x and y only.
    assert!(std::fs::read_to_string(dir.join("wells.geojson")).unwrap().contains("[1.0,2.0]"));
    // A project file keeps what the table's read lost, as it does a layer's (the Z or M values,
    // the coordinate system, geometry lost to it), so a table opened from one says it too.
    let crs = rustgis_data::raster::Crs::parse("EPSG:3857").unwrap();
    {
        let wells = s.project.tables.last_mut().unwrap();
        wells.crs = Some(crs);
        wells.crs_incomplete = true;
    }
    let project = dir.join("wells.rgis");
    s.run("project.saveAs", &json!({"path": project.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": project.display().to_string()})).unwrap();
    let opened = &t.project.tables.get(t.table_index(&json!({"table": "wells"})).unwrap()).unwrap().dataset;
    assert!(opened.zm_dropped && opened.crs_incomplete && opened.crs == Some(crs), "{opened:?}");
    let out = dir.join("opened.geojson").display().to_string();
    let mark = t.notice_mark();
    t.run("share.exportTable", &json!({"table": "wells", "path": out})).unwrap();
    assert_eq!(said(&t, mark), [format!("{out}: its geometry has no Z or M values, which were dropped when wells was read")]);
    // A write that fails says nothing of what the file would have lacked.
    let missing = dir.join("missing").join("wells.geojson").display().to_string();
    let mark = s.notice_mark();
    assert!(s.run("share.exportTable", &json!({"table": "wells", "path": missing})).is_err());
    assert!(said(&s, mark).is_empty(), "{:?}", s.notices_since(mark));
    // A table read without Z: no notice.
    std::fs::write(
        dir.join("flat.geojson"),
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"depth":30},"geometry":{"type":"Point","coordinates":[1,2]}}]}"#,
    )
    .unwrap();
    let (flat, _) = rustgis_data::io::read_path(&dir.join("flat.geojson")).unwrap();
    assert!(!flat.zm_dropped, "premise");
    s.project.add_table(flat);
    for ext in ["geojson", "shp"] {
        let mark = s.notice_mark();
        s.run("share.exportTable", &json!({"table": "flat", "path": dir.join(format!("flat.{ext}"))})).unwrap();
        assert!(said(&s, mark).is_empty(), ".{ext}: {:?}", s.notices_since(mark));
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// What an import says about positions, an export says again: a NAD 27 Shapefile whose `.prj`
/// has no shift to WGS 84 (read whole or in place, and after the project is saved and opened)
/// exported to GeoJSON, but not written back to a Shapefile in NAD 27; and a Shapefile without a
/// `.prj` or a CSV whose coordinates aren't longitude/latitude, exported, converted or shared.
/// Sample layers say neither.
#[test]
fn exports_say_what_import_said_about_positions() {
    // NAD 27's ellipsoid under a datum name no one knows a shift of: NAD 27 itself is transformed
    // by its name, as PROJ 9.8.1 does, with nothing to say.
    const NAD27: &str = r#"PROJCS["NAD_1927_UTM_Zone_16N",GEOGCS["GCS_Local",DATUM["D_Local_Survey",SPHEROID["Clarke_1866",6378206.4,294.9786982]],PRIMEM["Greenwich",0.0],UNIT["Degree",0.0174532925199433]],PROJECTION["Transverse_Mercator"],PARAMETER["False_Easting",500000.0],PARAMETER["False_Northing",0.0],PARAMETER["Central_Meridian",-87.0],PARAMETER["Scale_Factor",0.9996],PARAMETER["Latitude_Of_Origin",0.0],UNIT["Meter",1.0]]"#;
    let dir = std::env::temp_dir().join(format!("rustgis-engine-positions-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    isolate_plugins();
    let pt = dir.join("pt.geojson");
    std::fs::write(
        &pt,
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","properties":{"id":1},"geometry":{"type":"Point","coordinates":[-89.9,35.1]}}]}"#,
    )
    .unwrap();
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": pt, "name": "pt"})).unwrap();
    let (nad27, bare) = (dir.join("nad27.shp"), dir.join("bare.shp"));
    s.run("share.exportLayer", &json!({"layer": "pt", "path": nad27, "crs": "EPSG:32616"})).unwrap();
    std::fs::write(nad27.with_extension("prj"), NAD27).unwrap();
    s.run("share.exportLayer", &json!({"layer": "pt", "path": bare, "crs": "EPSG:32616"})).unwrap();
    std::fs::remove_file(bare.with_extension("prj")).unwrap();
    let csv = dir.join("utm.csv");
    std::fs::write(&csv, "id,x,y\n1,500000,3800000\n").unwrap();

    let said = |s: &Session, mark, what: &str| s.notices_since(mark).iter().any(|n| n.text.contains(what));
    const APPROXIMATE: &str = "are approximate, possibly a few hundred metres off";
    const NOT_LONLAT: &str = "aren't longitude/latitude, so they're out of place";
    for stream in [false, true] {
        let mut s = Session::new(Project::default());
        let mark = s.notice_mark();
        let id = s.run("layer.addData", &json!({"path": nad27, "stream": stream})).unwrap()["layer"].as_u64().unwrap();
        assert!(said(&s, mark, "has no conversion to WGS 84"), "stream {stream}: {:?}", s.notices_since(mark));
        let mark = s.notice_mark();
        s.run("share.exportLayer", &json!({"layer": id, "path": dir.join(format!("nad27-{stream}.geojson"))})).unwrap();
        assert!(said(&s, mark, APPROXIMATE), "stream {stream}: {:?}", s.notices_since(mark));
        let mark = s.notice_mark();
        s.run("share.exportLayer", &json!({"layer": id, "path": dir.join(format!("back-{stream}.shp"))})).unwrap();
        assert!(!said(&s, mark, APPROXIMATE), "stream {stream}: {:?}", s.notices_since(mark));
        let mark = s.notice_mark();
        let id = s.run("layer.addData", &json!({"path": bare, "stream": stream})).unwrap()["layer"].as_u64().unwrap();
        assert!(said(&s, mark, "not longitude/latitude"), "stream {stream}");
        let mark = s.notice_mark();
        s.run("share.exportLayer", &json!({"layer": id, "path": dir.join(format!("bare-{stream}.geojson"))})).unwrap();
        assert!(said(&s, mark, NOT_LONLAT), "stream {stream}: {:?}", s.notices_since(mark));
    }

    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": nad27, "name": "nad27"})).unwrap();
    s.run("layer.addData", &json!({"path": csv, "name": "utm"})).unwrap();
    let saved = s.project.saved_text(None).unwrap().0;
    let mut s = Session::new(Project::from_json(&saved).unwrap());
    let mark = s.notice_mark();
    s.run("share.exportLayer", &json!({"layer": "nad27", "path": dir.join("reopened.geojson")})).unwrap();
    assert!(said(&s, mark, APPROXIMATE), "{:?}", s.notices_since(mark));
    for (cmd, params) in [
        ("share.exportLayer", json!({"layer": "utm", "path": dir.join("utm.geojson")})),
        ("data.convert", json!({"layer": "utm", "format": "geojson"})),
    ] {
        let mark = s.notice_mark();
        s.run(cmd, &params).unwrap();
        assert!(said(&s, mark, NOT_LONLAT), "{cmd}: {:?}", s.notices_since(mark));
    }
    for (layer, expected) in [("nad27", APPROXIMATE), ("utm", NOT_LONLAT)] {
        let mut dataset = s.map().layer_by_name(layer).unwrap().dataset.clone();
        dataset.name = format!("table-{layer}");
        s.project.add_table(dataset);
        let mark = s.notice_mark();
        s.run("share.exportTable", &json!({"table":format!("table-{layer}"),"path":dir.join(format!("table-{layer}.geojson"))})).unwrap();
        assert!(said(&s, mark, expected), "{layer}: {:?}", s.notices_since(mark));
    }
    let mark = s.notice_mark();
    s.run("share.webMap", &json!({"path": dir.join("map.html")})).unwrap();
    let notes: Vec<_> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert_eq!(notes.iter().filter(|n| n.contains(APPROXIMATE) || n.contains(NOT_LONLAT)).count(), 2, "{notes:?}");

    let mut s = world();
    let mark = s.notice_mark();
    s.run("share.exportLayer", &json!({"layer": "Cities", "path": dir.join("cities.geojson")})).unwrap();
    assert!(!said(&s, mark, APPROXIMATE) && !said(&s, mark, NOT_LONLAT), "{:?}", s.notices_since(mark));
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn rounded_raster_values_are_said_on_import_and_export() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-rounded-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let grid = |name: &str, values: &str| {
        let path = dir.join(name);
        std::fs::write(&path, format!("ncols 2\nnrows 2\nxllcorner 10\nyllcorner 40\ncellsize 1\n{values}")).unwrap();
        path
    };
    let mut s = Session::new(Project::default());
    for (path, rounded) in
        [(grid("ids.asc", "16777217 100000001\n1234567.891 7"), true), (grid("clean.asc", "16777216 12.3\n123.4567 7"), false)]
    {
        let mark = s.notice_mark();
        let id = s.run("layer.addData", &json!({"path": path})).unwrap()["layer"].as_u64().unwrap();
        let said = |s: &Session, mark, text: &str| s.notices_since(mark).iter().any(|n| n.text.contains(text));
        assert_eq!(said(&s, mark, "3 values were rounded as the file was read"), rounded, "{:?}", s.notices_since(mark));
        let mark = s.notice_mark();
        let out = dir.join(format!("out-{id}.tif"));
        s.run("share.exportRaster", &json!({"layer": id, "path": out})).unwrap();
        assert_eq!(said(&s, mark, "3 values in it were rounded to 32-bit floats"), rounded, "{:?}", s.notices_since(mark));
        // The exported file holds the values as they were held: 16777217 is 16777216.
        assert_eq!(rustgis_data::raster::read_path(&out).unwrap().value(0, 0, 0), Some(16_777_216.0));
        // A fresh candidate discloses the new file's losses, not the previous pixels' report.
        let values = if rounded { "9 2\n3 4" } else { "16777217 100000001\n1234567.891 7" };
        std::fs::write(&path, format!("ncols 2\nnrows 2\nxllcorner 10\nyllcorner 40\ncellsize 1\n{values}")).unwrap();
        let mark = s.notice_mark();
        s.run("layer.reloadData", &json!({"layer": id})).unwrap();
        assert_eq!(said(&s, mark, "3 values were rounded as the file was read"), !rounded, "{:?}", s.notices_since(mark));
        let pixel = s.map().layer(id as u32).unwrap().raster.as_ref().unwrap().data.as_ref().unwrap().value(0, 0, 0);
        assert_eq!(pixel, Some(if rounded { 9.0 } else { 16_777_216.0 }));
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// Downloads and files made by mosaic/warp report the rounded values they actually write.
#[test]
fn raster_download_mosaic_and_warp_report_export_losses() {
    let dir = std::env::temp_dir().join(format!("rustgis-raster-export-notes-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    for (name, values, rounded) in [("rounded", "16777217 100000001\n1234567.891 7", true), ("clean", "1 2\n3 4", false)] {
        let mut s = Session::new(Project::default());
        let path = dir.join(format!("{name}.asc"));
        std::fs::write(&path, format!("ncols 2\nnrows 2\nxllcorner 10\nyllcorner 40\ncellsize 1\n{values}")).unwrap();
        let id = s.run("layer.addData", &json!({"path": path, "name": name})).unwrap()["layer"].as_u64().unwrap();
        for cog in [false, true] {
            let mark = s.notice_mark();
            let (_, bytes) = crate::cmd::raster::geotiff_bytes(&mut s, &json!({"layer": id, "cog": cog})).unwrap();
            assert_eq!(rustgis_data::raster::read_bytes("download.tif", &bytes).unwrap().width, 2);
            let notes = s.notices_since(mark);
            assert_eq!(
                notes.iter().filter(|n| n.text.contains("3 values in it were rounded to 32-bit floats")).count(),
                usize::from(rounded),
                "download, cog={cog}: {notes:?}"
            );
        }
        let points = [[0, 0, 10, 42], [2, 0, 12, 42], [0, 2, 10, 40]];
        for (command, mut params) in [
            ("raster.mosaic", json!({"inputs": [name, name], "name": "mosaic"})),
            ("raster.georeference", json!({"layer": name, "transform": "affine", "points": points, "name": "warped"})),
        ] {
            let output = dir.join(format!("{name}-{command}.tif"));
            params["path"] = json!(output);
            let mark = s.notice_mark();
            s.run(command, &params).unwrap();
            assert!(rustgis_data::raster::read_path(&output).is_ok());
            let notes = s.notices_since(mark);
            assert_eq!(
                notes.iter().filter(|n| n.text.contains("some values in it may have been rounded to 32-bit floats")).count(),
                usize::from(rounded),
                "{command}: {notes:?}"
            );
            assert!(!notes.iter().any(|n| n.text.contains("3 values in it")), "{command}: {notes:?}");
        }
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// Metadata limits are reported from downloads, mosaics and warped files, with the files checked.
#[test]
fn raster_export_paths_report_band_class_and_credit_changes() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let dir = std::env::temp_dir().join(format!("rustgis-raster-export-metadata-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = Session::new(Project::default());
    let gt = GeoTransform { origin_x: 10.0, origin_y: 42.0, pixel_width: 1.0, pixel_height: -1.0 };
    let mut r =
        Raster::new("Metadata", 2, 2, vec![vec![1.0; 4]; 5], gt, Crs::LonLat, None, ColorHint::Rgb { alpha: false }, "Float32").unwrap();
    r.bands[0].name = "red\u{1}name".into();
    r.bands[0].classes = vec!["zero".into(), "one\u{2}name".into()];
    r.bands[1].classes = vec!["zero".into(), "green class".into()];
    r.copyright = Some("© Owner".into());
    let mut other = r.clone();
    other.name = "Other".into();
    other.copyright = Some("Another owner".into());
    let bytes = geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "Metadata", rustgis_map::RasterLayer::from_bytes(r, "metadata.tif", bytes)).unwrap();
    let bytes = geotiff::write(&other, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "Other", rustgis_map::RasterLayer::from_bytes(other, "other.tif", bytes)).unwrap();
    let check = |s: &Session, mark, bytes: &[u8]| {
        let notes = s.notices_since(mark).iter().map(|n| n.text.as_str()).collect::<Vec<_>>().join("\n");
        for text in [
            "3 of its 5 bands written",
            "class names of band(s) 2 aren't written",
            "Copyright tag holds ASCII",
            "2 band or class name(s) held control characters",
        ] {
            assert!(notes.contains(text), "missing {text}: {notes}");
        }
        let written = rustgis_data::raster::read_bytes("written.tif", bytes).unwrap();
        assert_eq!(written.band_count(), 3);
        assert_eq!(written.bands[0].name, "red name");
        assert_eq!(written.bands[0].classes, ["zero", "one name"]);
        assert_eq!(written.copyright.as_deref(), Some("(c) Owner"));
    };
    for cog in [false, true] {
        let mark = s.notice_mark();
        let (_, bytes) = crate::cmd::raster::geotiff_bytes(&mut s, &json!({"layer": "Metadata", "cog": cog})).unwrap();
        check(&s, mark, &bytes);
    }
    let points = [[0, 0, 10, 42], [2, 0, 12, 42], [0, 2, 10, 40]];
    for (cmd, mut params) in [
        ("raster.mosaic", json!({"inputs": ["Metadata", "Metadata"], "name": "mosaic"})),
        (
            "raster.georeference",
            json!({"layer": "Metadata", "transform": "affine", "points": points, "resampling": "nearest", "name": "warped"}),
        ),
    ] {
        let path = dir.join(format!("{cmd}.tif"));
        params["path"] = json!(path);
        let mark = s.notice_mark();
        s.run(cmd, &params).unwrap();
        check(&s, mark, &std::fs::read(path).unwrap());
    }
    for (second, changed) in [("Metadata", false), ("Other", true)] {
        let mark = s.notice_mark();
        let out = s.run("raster.mosaic", &json!({"inputs": ["Metadata", second], "name": "rights"})).unwrap();
        assert_eq!(out_raster(&s, &out).copyright.as_deref(), Some("© Owner"));
        assert_eq!(s.notices_since(mark).iter().any(|n| n.text.contains("copyright differs")), changed, "{:?}", s.notices_since(mark));
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// Given both an extent and a cellSize, Project Raster takes the grid as given: a source whose
/// footprint can't be placed whole in the output's system (the whole world in the south polar
/// stereographic one, which can't hold the North Pole) is projected onto it, where without them it
/// is refused for want of a footprint.
#[test]
fn raster_project_takes_a_given_grid_without_the_sources_footprint() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    use rustgis_data::{Coord, Dataset, Geometry, GeometryType};
    let mut s = Session::new(Project::default());
    let gt = GeoTransform { origin_x: -180.0, origin_y: 90.0, pixel_width: 10.0, pixel_height: -10.0 };
    let r = Raster::new("World", 36, 18, vec![vec![1.0; 36 * 18]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let bytes = rustgis_data::raster::geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "World", rustgis_map::RasterLayer::from_bytes(r, "World.tif".to_string(), bytes)).unwrap();
    let e = s.run("raster.project", &json!({"layer": "World", "crs": 3031})).unwrap_err();
    assert!(e.contains("can't be placed in"), "{e}");
    let v = s.run("raster.project", &json!({"layer": "World", "crs": 3031, "extent": [-180, -90, 180, -60], "cellSize": 500_000})).unwrap();
    assert!(v["width"].as_u64().is_some_and(|w| w > 0), "{v}");
    // An extent layer read in place (only the part in view) is refused, as for Polygons to Raster.
    let mut part = Dataset::new("part", GeometryType::Polygon, vec![]);
    part.push(
        Some(Geometry::Polygon(vec![vec![vec![
            Coord::new(0.0, -80.0),
            Coord::new(10.0, -80.0),
            Coord::new(10.0, -70.0),
            Coord::new(0.0, -80.0),
        ]]])),
        vec![],
    );
    part.windowed = true;
    crate::cmd::layer::add_dataset(&mut s, part);
    let e = s.run("raster.project", &json!({"layer": "World", "crs": 3031, "extent": "part", "cellSize": 500_000})).unwrap_err();
    assert!(e.contains("part: load all its features first"), "{e}");
    // The whole world reaches every cell of the grid, as projected: each takes its value.
    let id = v["layer"].as_u64().unwrap() as u32;
    let out = s.map().layer(id).and_then(|l| l.raster.as_ref()).and_then(|r| r.data.clone()).unwrap();
    assert_eq!(out.crs, rustgis_data::raster::Crs::from_epsg(3031).unwrap());
    assert!(out.bands[0].data.iter().all(|c| *c == 1.0), "{:?}", &out.bands[0].data[..8]);
}

/// Class labels describe source values; interpolating or averaging those values drops the labels
/// with a notice, while nearest, mode and palette-safe sampling retain them.
#[test]
fn raster_resampling_class_names_follow_the_values_and_report_losses() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let dir = std::env::temp_dir().join(format!("rustgis-resampled-classes-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = Session::new(Project::default());
    let labels: Vec<String> = ["unknown", "one", "two", "water", "snow", "forest"].map(str::to_owned).to_vec();
    let gt = GeoTransform { origin_x: 10.0, origin_y: 42.0, pixel_width: 1.0, pixel_height: -1.0 };
    for (name, color, labelled, data_type) in [
        ("Classes", ColorHint::Gray, true, "Float32"),
        ("Palette", ColorHint::Palette((0..6).map(|i| [i * 30, 0, 0, 255]).collect()), true, "UInt8"),
        ("Clean", ColorHint::Gray, false, "Float32"),
    ] {
        let mut r = Raster::new(name, 2, 2, vec![vec![3.0, 5.0, 5.0, 3.0]], gt, Crs::LonLat, None, color, data_type).unwrap();
        if labelled {
            r.bands[0].classes = labels.clone();
        }
        let bytes = geotiff::write(&r, 0).unwrap();
        crate::cmd::raster::add_raster(&mut s, name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
    }
    let points = [[0, 0, 10, 42], [2, 0, 12, 42], [0, 2, 10, 40]];
    let params = |cmd: &str, layer: &str| {
        if cmd == "raster.georeference" {
            json!({"layer":layer, "transform":"affine", "points":points, "cellSize":0.5})
        } else {
            json!({"layer":layer, "crs":4326, "extent":[10,40,12,42], "cellSize":2})
        }
    };
    let lost = |n: &&crate::Notice| n.text.contains("class names of") && n.text.contains("not kept under");
    for (cmd, requested, method, keep) in [
        ("raster.georeference", None, "bilinear", false),
        ("raster.georeference", Some("nearest"), "nearest", true),
        ("raster.georeference", Some("cubic"), "cubic", false),
        ("raster.project", Some("nearest"), "nearest", true),
        ("raster.project", Some("bilinear"), "bilinear", false),
        ("raster.project", Some("cubic"), "cubic", false),
        ("raster.project", Some("average"), "average", false),
        ("raster.project", Some("mode"), "mode", true),
    ] {
        for file in [false, true] {
            let mut p = params(cmd, "Classes");
            p["name"] = json!(format!("{cmd}-{method}-{file}"));
            if let Some(method) = requested {
                p["resampling"] = json!(method);
            }
            let path = dir.join(format!("{cmd}-{method}.tif"));
            if file {
                p["path"] = json!(path);
            }
            let mark = s.notice_mark();
            let answer = s.run(cmd, &p).unwrap();
            let out = out_raster(&s, &answer);
            if keep {
                assert_eq!(out.bands[0].classes, labels, "{cmd}/{method}");
            } else {
                assert!(out.bands[0].classes.is_empty(), "{cmd}/{method}: labels no longer describe the values");
                assert!(out.bands[0].data.iter().any(|v| v.is_finite() && *v != 3.0 && *v != 5.0), "{cmd}/{method}: values really mixed");
            }
            let notes: Vec<_> = s.notices_since(mark).iter().filter(lost).collect();
            assert_eq!(notes.len(), usize::from(!keep), "{cmd}/{method}: {:?}", s.notices_since(mark));
            if !keep {
                assert!(notes[0].text.contains("1 band(s) (1)") && notes[0].text.contains(method), "{:?}", notes[0]);
            }
            if file {
                let written = rustgis_data::raster::read_bytes("written.tif", &std::fs::read(path).unwrap()).unwrap();
                assert_eq!(written.bands[0].classes, out.bands[0].classes);
            }
        }
    }
    // Palette requests use value-preserving methods, and report the effective method.
    for (cmd, requested, effective) in
        [("raster.georeference", "bilinear", "nearest"), ("raster.project", "bilinear", "nearest"), ("raster.project", "average", "mode")]
    {
        let mut p = params(cmd, "Palette");
        p["name"] = json!(format!("palette-{cmd}-{requested}"));
        p["resampling"] = json!(requested);
        let mark = s.notice_mark();
        let answer = s.run(cmd, &p).unwrap();
        assert_eq!(answer["resampling"], effective);
        assert_eq!(out_raster(&s, &answer).bands[0].classes, labels);
        assert!(!s.notices_since(mark).iter().any(|n| lost(&n)));
    }
    for cmd in ["raster.georeference", "raster.project"] {
        let mark = s.notice_mark();
        s.run(cmd, &params(cmd, "Clean")).unwrap();
        assert!(!s.notices_since(mark).iter().any(|n| lost(&n)));
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn raster_export_review_tool_notice_preserves_path_and_band_guidance() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let dir = std::env::temp_dir().join(format!("rustgis-mosaic-band-guidance-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let filename = if cfg!(target_os = "windows") { "mosaic.tif" } else { "give \"band\" for another.tif" };
    let path = dir.join(filename);
    let gt = GeoTransform { origin_x: 0.0, origin_y: 2.0, pixel_width: 1.0, pixel_height: -1.0 };
    let r = Raster::new(
        "Multi",
        2,
        2,
        vec![vec![1.0, 2.0, 3.0, 4.0], vec![5.0, 6.0, 7.0, 8.0]],
        gt,
        Crs::LonLat,
        None,
        ColorHint::Gray,
        "Float32",
    )
    .unwrap();
    let bytes = geotiff::write(&r, 0).unwrap();
    let mut s = Session::new(Project::default());
    crate::cmd::raster::add_raster(&mut s, "Multi", rustgis_map::RasterLayer::from_bytes(r, "multi.tif", bytes)).unwrap();
    let mark = s.notice_mark();
    s.run("raster.mosaic", &json!({"inputs":["Multi","Multi"],"name":"Mosaic","path":path})).unwrap();
    assert!(path.is_file());
    let notes = s.notices_since(mark);
    let note = &notes.iter().find(|n| n.text.starts_with("Exported ")).unwrap().text;
    assert!(note.starts_with(&format!("Exported {}", path.display())), "{note}");
    assert!(note.contains("1 of its 2 bands written"), "{note}");
    let instruction = "export the resulting layer with share.exportRaster and give \"band\" for another";
    assert_eq!(note.matches(instruction).count(), 1, "{note}");
    std::fs::remove_dir_all(dir).unwrap();
}

/// A raster clipped, resampled, mosaicked, warped or pixel-edited from one with values rounded when it
/// was read keeps a mark
/// of them, with no count (it holds an unknown share), and its export says so; one made from a
/// clean raster says nothing of rounding (#1614).
#[test]
fn rasters_made_from_rounded_ones_keep_the_rounded_note() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-rounded-part-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    const SOME: &str = "some values in it may have been rounded to 32-bit floats";
    let raster = |s: &Session, name: &str| s.map().layer_by_name(name).and_then(|l| l.raster.as_ref()?.data.clone()).unwrap();
    let mut s = Session::new(Project::default());
    for (file, values, rounded) in
        [("ids.asc", "16777217 100000001\n1234567.891 7", true), ("clean.asc", "16777216 12.3\n123.4567 7", false)]
    {
        let path = dir.join(file);
        std::fs::write(&path, format!("ncols 2\nnrows 2\nxllcorner 10\nyllcorner 40\ncellsize 1\n{values}")).unwrap();
        let id = s.run("layer.addData", &json!({"path": path})).unwrap()["layer"].as_u64().unwrap();
        let name = s.map().layer(id as u32).unwrap().name.clone();
        let clip = format!("{name}_part");
        s.run("raster.process", &json!({"layer": name, "operation": "clip", "extent": [10.2, 41.2, 10.8, 41.8], "name": clip})).unwrap();
        let clipped = raster(&s, &clip);
        assert_eq!((clipped.width, clipped.height, clipped.rounded.is_empty()), (1, 1, true), "{file}");
        assert_eq!(clipped.rounded_some, if rounded { vec![true] } else { vec![] }, "{file}");
        let (half, joined) = (format!("{name}_half"), format!("{name}_joined"));
        s.run("raster.process", &json!({"layer": name, "operation": "resample", "factor": 2, "name": half})).unwrap();
        s.run("raster.mosaic", &json!({"inputs": [clip, name], "name": joined})).unwrap();
        let warped = format!("{name}_warped");
        let points = [[0, 0, 10, 42], [2, 0, 12, 42], [0, 2, 10, 40]];
        let fit = json!({"layer": name, "transform": "affine", "crs": 4326, "pointsCrs": 4326, "points": points, "name": warped});
        s.run("raster.georeference", &fit).unwrap();
        let projected = format!("{name}_projected");
        let projected_file = format!("{name}_projected_file");
        for (output, file) in [(&projected, false), (&projected_file, true)] {
            let mut p = json!({"layer":name, "crs":4326, "extent":[10,40,12,42], "cellSize":0.5, "name":output});
            if file {
                p["path"] = json!(dir.join(format!("{output}.tif")));
            }
            let mark = s.notice_mark();
            s.run("raster.project", &p).unwrap();
            assert_eq!(
                s.notices_since(mark).iter().any(|n| n.text.contains(SOME)),
                file && rounded,
                "{output}: {:?}",
                s.notices_since(mark)
            );
        }
        s.run(
            "raster.editPixels",
            &json!({"layer": name, "polygon": [[10.1, 40.1], [10.9, 40.1], [10.9, 40.9], [10.1, 40.9]], "value": 1}),
        )
        .unwrap();
        for layer in
            [clip.as_str(), half.as_str(), joined.as_str(), warped.as_str(), projected.as_str(), projected_file.as_str(), name.as_str()]
        {
            let mark = s.notice_mark();
            s.run("share.exportRaster", &json!({"layer": layer, "path": dir.join(format!("{layer}.tif"))})).unwrap();
            let notes = s.notices_since(mark);
            assert_eq!(notes.iter().any(|n| n.text.contains(SOME)), rounded, "{layer}: {notes:?}");
            // No count is given: the whole file's would be wrong for a part of it.
            assert!(!notes.iter().any(|n| n.text.contains("3 values in it")), "{layer}: {notes:?}");
        }
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// A raster derived from a multiband grey one (resampled, clipped, pixel-edited) keeps every band
/// in the project: saved and reopened, its bands are as they were.
#[test]
fn derived_multiband_rasters_keep_every_band_in_the_project() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let dir = std::env::temp_dir().join(format!("rustgis-engine-derived-bands-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let gt = GeoTransform { origin_x: 10.0, origin_y: 42.0, pixel_width: 0.5, pixel_height: -0.5 };
    let bands = vec![(0..16).map(|i| i as f32).collect(), (0..16).map(|i| 100.0 + i as f32).collect()];
    let r = Raster::new("two", 4, 4, bands, gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let path = dir.join("two.tif");
    std::fs::write(&path, geotiff::write_all(&r).unwrap()).unwrap();
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": path})).unwrap();
    s.run("raster.process", &json!({"layer": "two", "operation": "resample", "factor": 2, "name": "half"})).unwrap();
    s.run("raster.process", &json!({"layer": "two", "operation": "clip", "extent": [10.0, 40.0, 11.0, 41.0], "name": "part"})).unwrap();
    s.run("raster.editPixels", &json!({"layer": "two", "polygon": [[10.1, 41.6], [10.4, 41.6], [10.4, 41.9], [10.1, 41.9]], "value": 1}))
        .unwrap();
    let bands = |s: &Session, name: &str| {
        let r = s.map().layer_by_name(name).and_then(|l| l.raster.as_ref()?.data.clone()).unwrap();
        r.bands.iter().map(|b| b.data.iter().map(|v| v.to_bits()).collect::<Vec<_>>()).collect::<Vec<_>>()
    };
    let before: Vec<_> = ["half", "part", "two"].iter().map(|name| bands(&s, name)).collect();
    assert!(before.iter().all(|b| b.len() == 2));
    // Each derived band comes from its own source band: the first's values are under 16, the
    // second's 100 or more (NaN where a cell has none).
    for (name, bands) in ["half", "part"].iter().zip(&before) {
        let values = |b: usize| bands[b].iter().map(|v| f32::from_bits(*v)).filter(|v| v.is_finite()).collect::<Vec<_>>();
        assert!(!values(1).is_empty() && values(0).iter().all(|v| *v < 16.0) && values(1).iter().all(|v| *v >= 100.0), "{name}");
        // Clipping and resampling are linear, so each derived cell keeps band 2 = band 1 + 100.
        let (first, second) = (&bands[0], &bands[1]);
        assert!(
            first.iter().zip(second).all(|(a, b)| {
                let (a, b) = (f32::from_bits(*a), f32::from_bits(*b));
                (a.is_nan() && b.is_nan()) || (b - a - 100.0).abs() < 1e-3
            }),
            "{name}"
        );
    }
    // The edit set its pixel (the top-left one) in both bands and left the next one alone.
    let pixel = |band: usize, i: usize| before[2][band][i];
    assert_eq!([pixel(0, 0), pixel(1, 0), pixel(1, 1)], [1.0f32, 1.0, 101.0].map(f32::to_bits));
    let proj = dir.join("bands.rgis");
    s.run("project.saveAs", &json!({"path": proj})).unwrap();
    s.run("project.open", &json!({"path": proj})).unwrap();
    for (name, before) in ["half", "part", "two"].iter().zip(before) {
        assert_eq!(bands(&s, name), before, "{name}");
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// Equidistant Cylindrical typed as WKT, on a layer's inputs (Define Projection, a CSV's `crs`,
/// an export), says which formula it is read with, once; typed by its EPSG code it says nothing.
#[test]
fn projection_review_typed_layer_inputs_report_the_formula_choice() {
    let wkt = include_str!("../../data/src/raster/wkt2_corpus.tsv")
        .lines()
        .find(|row| row.starts_with("EPSG:4087\t"))
        .unwrap()
        .split('\t')
        .nth(5)
        .unwrap();
    let dir = std::env::temp_dir().join(format!("rustgis-typed-eqc-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    for (definition, expected) in [(wkt, 1), ("EPSG:4087", 0)] {
        for mode in ["define", "csv", "export"] {
            let mut session = world();
            let mark = session.notice_mark();
            match mode {
                "define" => {
                    session.run("layer.defineProjection", &json!({"layer":"Cities","crs":definition})).unwrap();
                }
                "csv" => {
                    let path = dir.join("point.csv");
                    std::fs::write(&path, "e,n\n0,4984944.377977743\n").unwrap();
                    let result = session.run("layer.addData", &json!({"path":path,"x":"e","y":"n","crs":definition})).unwrap();
                    let layer = session.map().layer(result["layer"].as_u64().unwrap() as u32).unwrap();
                    let lonlat = layer.dataset.in_lonlat().unwrap();
                    assert!((lonlat.features[0].geometry.as_ref().unwrap().label_point().unwrap().y - 45.0).abs() < 1e-9);
                }
                _ => {
                    session
                        .run(
                            "share.exportLayer",
                            &json!({"layer":"Cities","path":dir.join(format!("export-{expected}.shp")),"crs":definition}),
                        )
                        .unwrap();
                }
            }
            assert_eq!(
                session.notices_since(mark).iter().filter(|notice| notice.text.contains("EPSG method 1028")).count(),
                expected,
                "{mode}: {:?}",
                session.notices_since(mark)
            );
        }
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// A grid typed WKT gives (UTM zone 17N on NAD 27, bound to WGS 84 by the NTv2 grid `conus`, as
/// PROJ 9.8.1 writes it) isn't applied, which a CSV's `crs`, Define Projection and an export's
/// `crs` each say; a code (EPSG:32617) says nothing of it (#1678).
#[test]
fn a_typed_crs_says_its_grid_isnt_applied() {
    let bound = r#"BOUNDCRS[SOURCECRS[PROJCRS["unknown",BASEGEOGCRS["unknown",DATUM["North American Datum 1927",ELLIPSOID["Clarke 1866",6378206.4,294.978698213898,LENGTHUNIT["metre",1]],ID["EPSG",6267]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8901]]],CONVERSION["UTM zone 17N",METHOD["Transverse Mercator",ID["EPSG",9807]],PARAMETER["Latitude of natural origin",0,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8801]],PARAMETER["Longitude of natural origin",-81,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8802]],PARAMETER["Scale factor at natural origin",0.9996,SCALEUNIT["unity",1],ID["EPSG",8805]],PARAMETER["False easting",500000,LENGTHUNIT["metre",1],ID["EPSG",8806]],PARAMETER["False northing",0,LENGTHUNIT["metre",1],ID["EPSG",8807]],ID["EPSG",16017]],CS[Cartesian,2],AXIS["(E)",east,ORDER[1],LENGTHUNIT["metre",1,ID["EPSG",9001]]],AXIS["(N)",north,ORDER[2],LENGTHUNIT["metre",1,ID["EPSG",9001]]]]],TARGETCRS[GEOGCRS["WGS 84",DATUM["World Geodetic System 1984",ELLIPSOID["WGS 84",6378137,298.257223563,LENGTHUNIT["metre",1]]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433]],CS[ellipsoidal,2],AXIS["latitude",north,ORDER[1],ANGLEUNIT["degree",0.0174532925199433]],AXIS["longitude",east,ORDER[2],ANGLEUNIT["degree",0.0174532925199433]],ID["EPSG",4326]]],ABRIDGEDTRANSFORMATION["unknown to WGS84",METHOD["NTv2",ID["EPSG",9615]],PARAMETERFILE["Latitude and longitude difference file","conus",ID["EPSG",8656]]]]"#;
    let said =
        "crs: the definition's NTv2 transformation to WGS 84 (conus) isn't applied, so positions may be off by as much as that shift";
    let dir = std::env::temp_dir().join(format!("rustgis-typed-grid-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let csv = dir.join("point.csv");
    std::fs::write(&csv, "e,n\n500000,4800000\n").unwrap();
    for (definition, expected) in [(bound, 1), ("EPSG:32617", 0)] {
        let mut s = Session::new(Project::default());
        // The notice, and every notice of a transformation not applied or missing: only it, or none.
        let count = |s: &Session, mark| {
            let notices = s.notices_since(mark);
            let of = |text: &str| notices.iter().filter(|n| n.text.contains(text)).count();
            let shifts = notices.iter().filter(|n| n.text.contains("isn't applied") || n.text.contains("has no transformation")).count();
            (of(said), shifts)
        };
        let mark = s.notice_mark();
        let added = s.run("layer.addData", &json!({"path": csv, "x": "e", "y": "n", "crs": definition})).unwrap();
        let id = added["layer"].as_u64().unwrap() as u32;
        // On UTM zone 17N's central meridian, 81°W.
        let at = s.map().layer(id).unwrap().dataset.in_lonlat().unwrap().features[0].geometry.as_ref().unwrap().label_point().unwrap();
        assert!((at.x + 81.0).abs() < 1e-3, "{at:?}");
        assert_eq!(count(&s, mark), (expected, expected), "csv {definition}: {:?}", s.notices_since(mark));
        let mark = s.notice_mark();
        s.run("layer.defineProjection", &json!({"layer": id, "crs": definition})).unwrap();
        assert_eq!(count(&s, mark), (expected, expected), "define {definition}: {:?}", s.notices_since(mark));
        let mark = s.notice_mark();
        s.run("share.exportLayer", &json!({"layer": id, "path": dir.join(format!("out-{expected}.shp")), "crs": definition})).unwrap();
        assert_eq!(count(&s, mark), (expected, expected), "export {definition}: {:?}", s.notices_since(mark));
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn projection_review_layout_grid_reports_the_formula_choice() {
    let wkt = include_str!("../../data/src/raster/wkt2_corpus.tsv")
        .lines()
        .find(|row| row.starts_with("EPSG:4087\t"))
        .unwrap()
        .split('\t')
        .nth(5)
        .unwrap();
    for (definition, expected) in [(wkt, 1), ("EPSG:4087", 0)] {
        let mut session = world();
        session.run("layout.new", &json!({"template":"map"})).unwrap();
        let frame = session.project.layouts[0].elements.iter().find(|element| element.kind.code() == "mapFrame").unwrap().id;
        for (command, params) in [
            ("layout.addElement", json!({"kind":"grid","type":"measured","crs":definition})),
            ("layout.update", json!({"element":frame,"grid":{"type":"measured","crs":definition}})),
        ] {
            let mark = session.notice_mark();
            session.run(command, &params).unwrap();
            assert_eq!(
                session.notices_since(mark).iter().filter(|notice| notice.text.contains("EPSG method 1028")).count(),
                expected,
                "{command}"
            );
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn projection_review_zarr_parameters_report_the_formula_choice() {
    let _cache = zarr_cache_lock();
    let wkt = include_str!("../../data/src/raster/wkt2_corpus.tsv")
        .lines()
        .find(|row| row.starts_with("EPSG:4087\t"))
        .unwrap()
        .split('\t')
        .nth(5)
        .unwrap();
    let (dir, path) = zarr_store_over_time("eqc-input-notice");
    // Projected coordinates with no declared CRS, so the supplied definition is actually used.
    let store = std::path::Path::new(&path);
    let mut metadata: Value = serde_json::from_str(&std::fs::read_to_string(store.join(".zmetadata")).unwrap()).unwrap();
    let objects = metadata["metadata"].as_object_mut().unwrap();
    for (old, new) in [("lat", "y"), ("lon", "x")] {
        let array = objects.remove(&format!("{old}/.zarray")).unwrap();
        objects.insert(format!("{new}/.zarray"), array);
        objects.remove(&format!("{old}/.zattrs"));
        objects.insert(format!("{new}/.zattrs"), json!({"_ARRAY_DIMENSIONS":[new],"units":"m"}));
        std::fs::rename(store.join(old), store.join(new)).unwrap();
    }
    objects.get_mut("t/.zattrs").unwrap()["_ARRAY_DIMENSIONS"] = json!(["time", "y", "x"]);
    std::fs::write(store.join(".zmetadata"), metadata.to_string()).unwrap();
    for (definition, expected) in [(wkt, 1), ("EPSG:4087", 0)] {
        for following in [false, true] {
            let mut session = Session::new(Project::default());
            let result = session
                .run("layer.addZarr", &json!({"path":path,"variable":"t","index":{"time":0},"crs":definition,"time":following}))
                .unwrap();
            let layer = session.map().layer(result["layer"].as_u64().unwrap() as u32).unwrap();
            assert_eq!(layer.raster.as_ref().unwrap().data.as_ref().unwrap().crs, rustgis_data::raster::Crs::parse(definition).unwrap());
            assert_eq!(
                session.notices.iter().filter(|notice| notice.text.contains("EPSG method 1028")).count(),
                expected,
                "following={following}: {:?}",
                session.notices
            );
        }
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn projection_review_ascii_grid_keeps_its_datum_notice() {
    let dir = std::env::temp_dir().join(format!("rustgis-ascii-datum-note-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("nad27.asc");
    std::fs::write(&path, "ncols 1\nnrows 1\nxllcorner -80\nyllcorner 40\ncellsize 1\n7\n").unwrap();
    // A datum no one knows a shift of (NAD 27 itself is transformed by its name, as PROJ 9.8.1 does).
    std::fs::write(path.with_extension("prj"), r#"GEOGCS["GCS_Local",DATUM["D_Local_Survey",SPHEROID["Clarke_1866",6378206.4,294.9786982]],PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433]]"#).unwrap();
    let mut session = Session::new(Project::default());
    session.run("layer.addData", &json!({"path":path})).unwrap();
    assert_eq!(session.notices.iter().filter(|notice| notice.text.contains("has no conversion to WGS 84")).count(), 1);
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn ascii_grid_reports_declared_method_1028_compatibility() {
    let dir = std::env::temp_dir().join(format!("rustgis-ascii-eqc-note-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let projected = include_str!("../../data/src/raster/wkt2_corpus.tsv")
        .lines()
        .find(|row| row.starts_with("EPSG:4087\t"))
        .unwrap()
        .split('\t')
        .nth(5)
        .unwrap();
    let geographic = r#"GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433]]"#;
    for (name, wkt, y, expected) in [("projected", projected, 4_984_944.377_977_743, 1), ("geographic", geographic, 40.0, 0)] {
        let path = dir.join(format!("{name}.asc"));
        std::fs::write(&path, format!("ncols 1\nnrows 1\nxllcorner 0\nyllcorner {y}\ncellsize 1\n7\n")).unwrap();
        std::fs::write(path.with_extension("prj"), wkt).unwrap();
        let mut session = Session::new(Project::default());
        session.run("layer.addData", &json!({"path":path})).unwrap();
        let notices = session.notices.iter().filter(|notice| notice.text.contains("EPSG method 1028")).collect::<Vec<_>>();
        assert_eq!(notices.len(), expected, "{name}: {:?}", session.notices);
        assert!(notices.iter().all(|notice| notice.text.contains("the .prj file") && !notice.text.contains("read as longitude/latitude")));
        if expected > 0 {
            let raster = rustgis_data::raster::read_path(&path).unwrap();
            let point = raster.crs.transformer().unwrap().to_lonlat(rustgis_data::Coord::new(0.0, y)).unwrap();
            assert!((point.y - 45.0).abs() < 1e-9);
        }
    }
    std::fs::remove_dir_all(dir).unwrap();
}

/// An ASCII grid whose `.prj` can't be read is added in longitude/latitude, and adding it says so;
/// one whose `.prj` is read says nothing of it.
#[test]
fn an_ascii_grid_s_unread_prj_is_said_when_added() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-asc-prj-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = Session::new(Project::default());
    for (name, prj, said) in [
        (
            "geocentric",
            r#"GEOCCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["metre",1]]"#,
            true,
        ),
        (
            "wgs84",
            r#"GEOGCS["WGS 84",DATUM["WGS_1984",SPHEROID["WGS 84",6378137,298.257223563]],PRIMEM["Greenwich",0],UNIT["degree",0.0174532925199433]]"#,
            false,
        ),
    ] {
        let path = dir.join(format!("{name}.asc"));
        std::fs::write(&path, "ncols 2\nnrows 2\nxllcorner 10\nyllcorner 40\ncellsize 1\n1 2\n3 4\n").unwrap();
        std::fs::write(dir.join(format!("{name}.prj")), prj).unwrap();
        let mark = s.notice_mark();
        s.run("layer.addData", &json!({"path": path})).unwrap();
        let notes: Vec<&str> = s.notices_since(mark).iter().map(|n| n.text.as_str()).filter(|t| t.contains("the .prj file")).collect();
        assert_eq!(notes.len(), usize::from(said), "{name}: {:?}", s.notices_since(mark));
        assert!(notes.iter().all(|n| n.contains(name)), "{notes:?}");
        if said {
            assert!(notes[0].contains("GEOCCS") && notes[0].contains("WGS 84"), "{notes:?}");
            assert!(!notes[0].contains("it doesn't say its coordinate system"), "{notes:?}");
        }
    }
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn layers_export_to_geopackage_geoparquet_shapefile_and_kmz() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-export-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = world();
    let want = s.map().layers.iter().find(|l| l.name == "Countries").unwrap().dataset.features.len();
    for ext in ["gpkg", "parquet", "shp", "kmz", "zip"] {
        let path = dir.join(format!("countries.{ext}")).display().to_string();
        let r = s.run("share.exportLayer", &json!({"layer": "Countries", "path": path})).unwrap();
        assert_eq!((r["features"].as_u64(), r["leftOut"].as_u64()), (Some(want as u64), Some(0)), "{ext}");
        if matches!(ext, "kmz" | "zip") {
            assert!(std::fs::metadata(&path).unwrap().len() > 0);
            continue;
        }
        // Added back, drawn and saved in a project that reopens.
        let r = s.run("layer.addData", &json!({"path": path})).unwrap();
        let id = r["layer"].as_u64().unwrap() as u32;
        let l = s.map().layer(id).unwrap();
        let n = if l.is_streamed() { l.load_all().unwrap().features.len() } else { l.dataset.features.len() };
        assert_eq!(n, want, "{ext}");
    }
    let project = dir.join("p.rgis").display().to_string();
    s.run("project.saveAs", &json!({"path": project})).unwrap();
    s.run("project.open", &json!({"path": project})).unwrap();
    s.run("share.exportMap", &json!({"path": dir.join("m.png").display().to_string()})).unwrap();
    // Not a format it writes.
    assert!(s.run("share.exportLayer", &json!({"layer": "Countries", "path": dir.join("x.dwg").display().to_string()})).is_err());
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn layers_export_in_the_system_they_were_read_in() {
    // Issue #514: squares in ETRS89 / UTM zone 32N came out of every export in EPSG:4326.
    let dir = std::env::temp_dir().join(format!("rustgis-engine-export-crs-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let csv = dir.join("squares.csv");
    std::fs::write(&csv, "side;wkt\n1 km;POLYGON ((500000 5700000, 501000 5700000, 501000 5701000, 500000 5701000, 500000 5700000))\n")
        .unwrap();
    let mut s = Session::new(Project::default());
    let add = json!({"path": csv.display().to_string(), "name": "squares", "wkt": "wkt", "crs": "EPSG:25832", "delimiter": ";"});
    s.run("layer.addData", &add).unwrap();
    let path = |name: &str| dir.join(name).display().to_string();
    for (file, crs, want) in [
        ("out.gpkg", None, "EPSG:25832"),
        ("out.shp", None, "EPSG:25832"),
        ("out.fgb", None, "EPSG:25832"),
        ("out4647.gpkg", Some("EPSG:4647"), "EPSG:4647"),
        ("out4326.shp", Some("EPSG:4326"), "EPSG:4326"),
        ("out.geojson", None, "EPSG:4326"),
    ] {
        let mut p = json!({"layer": "squares", "path": path(file)});
        if let Some(c) = crs {
            p["crs"] = json!(c);
        }
        let r = s.run("share.exportLayer", &p).unwrap();
        assert_eq!(r["crs"], want, "{file}");
        // Added back, it is in the same place and remembers its system.
        let r = s.run("layer.addData", &json!({"path": path(file)})).unwrap();
        let l = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
        let ds = if l.is_streamed() { l.load_all().unwrap() } else { l.dataset.clone() };
        assert_eq!(ds.crs.map(|c| c.label()).unwrap_or_else(|| "EPSG:4326".into()), want, "{file}");
        let e = ds.lonlat_extent();
        assert!((e.min_x - 9.0).abs() < 1e-6 && (e.min_y - 51.451_18).abs() < 1e-5 && e.width() > 0.0139, "{file}: {e:?}");
    }
    // The .prj says the system, by its parameters and its code.
    let prj = std::fs::read_to_string(dir.join("out.prj")).unwrap();
    assert!(prj.contains("PARAMETER[\"central_meridian\",9]") && prj.contains("AUTHORITY[\"EPSG\",\"25832\"]"), "{prj}");
    // GeoJSON is longitude/latitude only; an unknown system is an error.
    assert!(s.run("share.exportLayer", &json!({"layer": "squares", "path": path("x.geojson"), "crs": "EPSG:25832"})).is_err());
    assert!(s.run("share.exportLayer", &json!({"layer": "squares", "path": path("x.gpkg"), "crs": "EPSG:1"})).is_err());
    let _ = std::fs::remove_dir_all(&dir);
}

/// A Shapefile whose `.prj` names its system without an EPSG code (State Plane by its parameters)
/// exports to GeoPackage and FlatGeobuf in that system, as the guide says; a system with no WKT
/// form is written in WGS 84, and a notice names it. Reads the files back for where they are.
#[test]
fn a_system_without_an_epsg_code_is_exported_in_its_own_system() {
    let dir = std::env::temp_dir().join(format!("rustgis-engine-export-prj-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = |name: &str| dir.join(name).display().to_string();
    // A point in Memphis, written to a Shapefile in EPSG:2274, whose `.prj` is then the text
    // for NAD83 / Tennessee (ftUS) that has no `AUTHORITY`.
    let prj = r#"PROJCS["NAD_1983_StatePlane_Tennessee_FIPS_4100_Feet",GEOGCS["GCS_North_American_1983",DATUM["D_North_American_1983",SPHEROID["GRS_1980",6378137.0,298.257222101]],PRIMEM["Greenwich",0.0],UNIT["Degree",0.0174532925199433]],PROJECTION["Lambert_Conformal_Conic"],PARAMETER["False_Easting",1968500.0],PARAMETER["False_Northing",0.0],PARAMETER["Central_Meridian",-86.0],PARAMETER["Standard_Parallel_1",35.25],PARAMETER["Standard_Parallel_2",36.41666666666666],PARAMETER["Latitude_Of_Origin",34.33333333333334],UNIT["Foot_US",0.3048006096012192]]"#;
    std::fs::write(dir.join("sites.csv"), "name,longitude,latitude\nMemphis,-90.049,35.1495\n").unwrap();
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": path("sites.csv"), "name": "seed"})).unwrap();
    s.run("share.exportLayer", &json!({"layer": "seed", "path": path("sites.shp"), "crs": "EPSG:2274"})).unwrap();
    std::fs::write(dir.join("sites.prj"), prj).unwrap();
    s.run("layer.addData", &json!({"path": path("sites.shp"), "name": "sites"})).unwrap();
    let own = s.map().layers.iter().find(|l| l.name == "sites").and_then(|l| l.dataset.crs).unwrap();
    assert_eq!(own.epsg(), 0, "the .prj has no authority: {}", own.label());
    for file in ["sites.gpkg", "sites.fgb", "again.shp"] {
        let mark = s.notice_mark();
        let r = s.run("share.exportLayer", &json!({"layer": "sites", "path": path(file)})).unwrap();
        assert_eq!(r["crs"], own.label(), "{file}");
        let said: Vec<_> = s.notices_since(mark).iter().map(|n| n.text.clone()).filter(|t| !t.starts_with("Exported ")).collect();
        assert!(said.is_empty(), "{file}: {said:?}");
        // Added back, the point is where it was and the layer is in the same system.
        let r = s.run("layer.addData", &json!({"path": path(file)})).unwrap();
        let l = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
        let ds = if l.is_streamed() { l.load_all().unwrap() } else { l.dataset.clone() };
        assert_eq!(ds.crs.map(|c| c.label()), Some(own.label()), "{file}");
        let at = ds.in_lonlat().unwrap().features[0].geometry.as_ref().unwrap().extent();
        assert!((at.min_x + 90.049).abs() < 1e-6 && (at.min_y - 35.1495).abs() < 1e-6, "{file}: {at:?}");
    }
    // A system WKT1 has no name for can't be written into either: WGS 84, and the notice says so.
    let gnomonic = "+proj=gnom +lat_0=35 +lon_0=-90 +datum=WGS84 +units=m +no_defs";
    s.run("layer.addData", &json!({"path": path("sites.csv"), "name": "far", "x": "longitude", "y": "latitude", "crs": gnomonic})).unwrap();
    for file in ["far.gpkg", "far.fgb"] {
        let mark = s.notice_mark();
        let r = s.run("share.exportLayer", &json!({"layer": "far", "path": path(file)})).unwrap();
        assert_eq!(r["crs"], "EPSG:4326", "{file}");
        let said: Vec<_> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
        assert!(said.iter().any(|t| t.contains("WGS 84") && t.contains(file) && t.contains("far")), "{file}: {said:?}");
    }
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn zipped_shapefiles_add_as_layers() {
    use base64::Engine;
    // The sample's countries and cities as Shapefiles in one zip, under a folder.
    let dir = std::env::temp_dir().join(format!("rustgis-engine-zip-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut entries = Vec::new();
    for (name, text) in [("countries", crate::sample::countries()), ("cities", crate::sample::CITIES)] {
        let (ds, _) = rustgis_data::io::read_bytes(&format!("{name}.geojson"), text.as_bytes()).unwrap();
        let (zipped, _) = rustgis_data::io::write_bytes(&ds, "shp").unwrap();
        for (n, b) in rustgis_data::zip::read(&zipped).unwrap() {
            entries.push((format!("world/{n}"), b));
        }
    }
    let zip = rustgis_data::zip::write(&entries).unwrap();
    // Uploaded (the web app).
    let mut s = Session::new(Project::default());
    let data = base64::engine::general_purpose::STANDARD.encode(&zip);
    let r = s.run("layer.addDataBytes", &json!({"fileName": "world.zip", "data": data})).unwrap();
    assert_eq!(r["layers"].as_array().map(Vec::len), Some(2), "{r}");
    let names: Vec<&str> = s.map().layers.iter().map(|l| l.name.as_str()).collect();
    assert!(names.contains(&"cities") && names.contains(&"countries"), "{names:?}");
    // From disk (the desktop app), saved and reopened with the project.
    let path = dir.join("world.zip");
    std::fs::write(&path, &zip).unwrap();
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addData", &json!({"path": path.display().to_string(), "name": "Towns"})).unwrap();
    assert!(r["features"].as_u64().unwrap() > 10, "{r}");
    assert_eq!(s.map().layers.iter().filter(|l| l.name == "Towns").count(), 1);
    let project = dir.join("p.rgis").display().to_string();
    s.run("project.saveAs", &json!({"path": project})).unwrap();
    s.run("project.open", &json!({"path": project})).unwrap();
    assert_eq!(s.map().layers.len(), 2);
    let _ = std::fs::remove_dir_all(&dir);
}

/// A request read whole: its head and as much body as its `Content-Length` says. A server that
/// answers and closes with part of the request unread has its connection reset on Windows and
/// macOS, and the client sees the reset in place of the answer.
fn read_request(s: &mut std::net::TcpStream) -> String {
    use std::io::Read;
    let _ = s.set_read_timeout(Some(std::time::Duration::from_secs(5)));
    let mut req = Vec::new();
    let mut buf = [0u8; 4096];
    let mut want = None;
    while want.is_none_or(|n| req.len() < n) && req.len() < 1 << 20 {
        let Ok(read) = s.read(&mut buf) else { break };
        if read == 0 {
            break;
        }
        req.extend_from_slice(&buf[..read]);
        if want.is_none()
            && let Some(end) = req.windows(4).position(|w| w == b"\r\n\r\n")
        {
            let head = String::from_utf8_lossy(&req[..end]).to_ascii_lowercase();
            let body = head.lines().find_map(|l| l.strip_prefix("content-length:")).and_then(|n| n.trim().parse::<usize>().ok());
            want = Some(end + 4 + body.unwrap_or(0));
        }
    }
    String::from_utf8_lossy(&req).into_owned()
}

/// Serves each request by the first route its path starts with (`{base}` in a body becomes the
/// server's address; other paths are 404); returns the base address.
fn serve_routes(routes: Vec<(&'static str, String)>, n: usize) -> String {
    use std::io::Write;
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let b = base.clone();
    std::thread::spawn(move || {
        for stream in listener.incoming().take(n) {
            let Ok(mut s) = stream else { continue };
            let req = read_request(&mut s);
            let path = req.split_whitespace().nth(1).unwrap_or("/").to_string();
            match routes.iter().find(|(p, _)| path.starts_with(p)) {
                Some((_, body)) => {
                    let body = body.replace("{base}", &b);
                    let _ = write!(s, "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}", body.len());
                }
                None => {
                    let _ = write!(s, "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
                }
            }
        }
    });
    base
}

/// A STAC API (a local one): its collections, a search adding the footprints, and an item's
/// asset added by its address; assets elsewhere than the web are refused by name.
#[test]
fn stac_search_and_assets() {
    let item = r#"{"type": "Feature", "id": "S2_1", "collection": "s2", "bbox": [7, 46, 8, 47],
        "geometry": {"type": "Polygon", "coordinates": [[[7, 46], [8, 46], [8, 47], [7, 47], [7, 46]]]},
        "properties": {"datetime": "2024-06-02T10:30:00Z", "eo:cloud_cover": 3.5},
        "links": [{"rel": "self", "href": "{base}/v1/collections/s2/items/S2_1"}],
        "assets": {"places": {"href": "{base}/data/places.geojson", "type": "application/geo+json", "roles": ["data"]},
                   "b04": {"href": "s3://bucket/B04.tif", "type": "image/tiff; application=geotiff", "roles": ["data"]}}}"#;
    let geojson = r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {"n": 1}, "geometry": {"type": "Point", "coordinates": [7.5, 46.5]}}]}"#;
    let base = serve_routes(
        vec![
            ("/v1/collections/s2/items/", item.to_string()),
            ("/v1/collections", r#"{"collections": [{"id": "s2", "title": "Sentinel-2"}]}"#.to_string()),
            (
                "/v1/search",
                format!(
                    r#"{{"type": "FeatureCollection", "features": [{item}], "links": [{{"rel": "next", "href": "{{base}}/v1/search?page=2"}}]}}"#
                ),
            ),
            ("/data/places.geojson", geojson.to_string()),
        ],
        6,
    );
    let api = format!("{base}/v1");
    let mut s = Session::new(Project::default());
    let r = s.run("stac.collections", &json!({"url": api})).unwrap();
    assert_eq!(r["collections"][0]["id"], "s2");
    let r = s.run("stac.search", &json!({"url": format!("{api}/search"), "collections": "s2", "bbox": [7, 46, 8, 47], "datetime": "2024-06-01/2024-06-30", "maxCloud": 20})).unwrap();
    assert_eq!(r["count"], 1);
    assert_eq!(r["next"], format!("{base}/v1/search?page=2"));
    let l = s.map().layer_by_name("STAC footprints").unwrap();
    assert_eq!(l.dataset.features.len(), 1);
    assert_eq!(l.dataset.geometry_type, rustgis_data::GeometryType::Polygon);
    // The item as the search gave it: its data asset (no visual one, no GeoTIFF on the web).
    let found = r["items"][0].clone();
    let e = s.run("stac.addAsset", &json!({"item": found, "asset": "b04"})).unwrap_err();
    assert!(e.contains("s3://"), "{e}");
    // Given whole, an item came from no address: its assets may only be public, and this one is
    // on the local network.
    let e = s.run("stac.addAsset", &json!({"item": found})).unwrap_err();
    assert!(e.contains("local network"), "{e}");
    // By the item's address (a server the user named): its local assets are fine.
    let r = s.run("stac.addAsset", &json!({"url": format!("{api}/collections/s2/items/S2_1"), "name": "Again"})).unwrap();
    assert_eq!(r["features"], 1, "{r}");
    assert!(s.map().layer_by_name("Again").is_some());
    for bad in [
        json!({"url": api, "bbox": [0, 50, 1, 40]}),
        json!({"url": api, "datetime": "last week"}),
        json!({"url": "file:///etc"}),
        json!({"item": 7}),
        json!({"item": {"type": "Feature", "id": "x", "assets": {}}}),
    ] {
        assert!(s.run("stac.search", &bad).is_err() || s.run("stac.addAsset", &bad).is_err(), "{bad}");
    }
    assert!(s.run("stac.addAsset", &json!({"item": {"type": "Feature", "id": "x", "assets": {}}})).is_err());
}

/// A single STAC asset whose metadata names codes for a failed retrieval (JAXA Earth's
/// `je:rasters` `dn.error`) draws them as values, and says so; an asset without them says nothing.
#[test]
fn a_stac_asset_with_retrieval_codes_says_they_draw_as_values() {
    let item = |id: &str, extra: &str| {
        format!(
            r#"{{"type": "Feature", "id": "{id}", "collection": "c", "bbox": [7, 46, 8, 47], "geometry": null,
               "properties": {{"datetime": "2024-06-02T10:30:00Z"}},
               "assets": {{"places": {{"href": "{{base}}/data/places.geojson", "type": "application/geo+json", "roles": ["data"]{extra}}}}}}}"#
        )
    };
    let geojson = r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {"n": 1}, "geometry": {"type": "Point", "coordinates": [7.5, 46.5]}}]}"#;
    let base = serve_routes(
        vec![
            ("/items/clean", item("clean", "")),
            ("/items/coded", item("coded", r#", "je:rasters": {"dn": {"error": [5.0, 7.0]}}"#)),
            ("/items/unread", item("unread", r#", "je:rasters": {"dn": {"error": [5.0, "x"]}}"#)),
            ("/data/places.geojson", geojson.to_string()),
        ],
        6,
    );
    let mut s = Session::new(Project::default());
    let mark = s.notice_mark();
    s.run("stac.addAsset", &json!({"url": format!("{base}/items/clean"), "name": "Clean"})).unwrap();
    let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(!said.iter().any(|t| t.contains("failed retrieval")), "clean input tells nothing: {said:?}");
    let mark = s.notice_mark();
    s.run("stac.addAsset", &json!({"url": format!("{base}/items/coded"), "name": "Coded"})).unwrap();
    let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(said.iter().any(|t| t.contains("Coded: its metadata marks failed retrievals with 2 code(s) (5, 7)")), "{said:?}");
    // Codes that can't be read whole (a word among them) say so.
    let mark = s.notice_mark();
    s.run("stac.addAsset", &json!({"url": format!("{base}/items/unread"), "name": "Unread"})).unwrap();
    let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(
        said.iter().any(|t| t.contains("Unread: its metadata's codes for a failed retrieval (je:rasters dn.error) couldn't be read whole")),
        "{said:?}"
    );
}

/// The Print Map PDF keeps a map within the vector budget as vectors and says nothing, a
/// colour-vision view too (exports don't simulate it, so it needn't be a picture).
#[test]
fn the_map_pdf_keeps_vectors_and_says_nothing_with_or_without_colour_vision() {
    let mut s = Session::new(crate::sample::world_project());
    for mode in ["normal", "deuteranopia"] {
        s.run("map.colorVision", &json!({"mode": mode})).unwrap();
        let mark = s.notice_mark();
        let pdf = crate::cmd::share::map_pdf(&mut s, 96.0).unwrap();
        let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
        assert!(!said.iter().any(|t| t.contains("one picture")), "{mode}: {said:?}");
        let text = String::from_utf8_lossy(&pdf);
        assert!(!text.contains("/Subtype /Image"), "{mode}: the map as vectors, not a picture");
    }
}

/// Directions through a routing server of one's own (a local Valhalla answer here): the route
/// and its steps as layers; the app's answer can be passed in instead, and nothing is fetched.
#[test]
fn directions_between_places() {
    const ANSWER: &str = r#"{"code":"Ok","routes":[{"duration":302.776,"distance":1921.553,"legs":[{"summary":"Pariser Platz","steps":[
        {"geometry":"g~idcBwjpoXl@InGo@","name":"Pariser Platz","distance":17.553,"duration":6.327,"maneuver":{"instruction":"Drive south on Pariser Platz.","type":"depart","location":[13.378236,52.51634]}},
        {"geometry":"itidcBqlpoXiD}mAYsKe@cS","name":"Pariser Platz","distance":1904.0,"duration":296.448,"maneuver":{"modifier":"left","instruction":"Turn left to stay on Pariser Platz.","type":"continue","location":[13.378265,52.516181]}},
        {"geometry":"ycqdcBurdqX??","name":"","distance":0.0,"duration":0.0,"maneuver":{"instruction":"You have arrived at your destination.","type":"arrive","location":[13.404987,52.520013]}}]}]}]}"#;
    let base = serve(ANSWER.as_bytes(), 1);
    let mut s = Session::new(Project::default());
    let r = s
        .run("map.route", &json!({"from": "52.5163, 13.3777", "to": [13.405, 52.52], "via": [{"lon": 13.39, "lat": 52.517}], "mode": "drive", "avoid": ["tolls"], "url": base}))
        .unwrap();
    assert_eq!(r["duration"], "5 min");
    assert_eq!(r["steps"].as_array().map(Vec::len), Some(3));
    assert_eq!(r["steps"][1]["modifier"], "left");
    let line = s.map().layer_by_name("Route (1.9 km)").unwrap();
    assert_eq!(line.dataset.geometry_type, rustgis_data::GeometryType::Polyline);
    let steps = s.map().layer_by_name("Route steps").unwrap();
    assert_eq!(steps.dataset.features.len(), 3);
    // The camera went to the route.
    let c = s.map().to_lonlat(s.map().camera.center).unwrap();
    assert!((c.x - 13.39).abs() < 0.05 && (c.y - 52.518).abs() < 0.05, "{c:?}");
    // The app's answer: nothing is fetched (the server above answered once only).
    let r = s.run("map.route", &json!({"answer": ANSWER, "mode": "walk", "zoom": false})).unwrap();
    assert!(r["layer"].is_u64());
    assert!(s.map().layer_by_name("Route (1.9 km) (2)").is_some());
    for bad in [
        json!({}),
        json!({"from": [13.0, 52.0]}),
        json!({"from": [200, 0], "to": [0, 0], "url": base}),
        json!({"from": [0, 0], "to": [1, 1], "mode": "teleport"}),
        json!({"from": [0, 0], "to": [1, 1], "avoid": ["mountains"]}),
        json!({"from": [0, 0], "to": [1, 1], "via": 7}),
        json!({"from": [0, 0], "to": [1, 1], "url": "file:///etc/passwd"}),
        json!({"answer": "<html>"}),
        json!({"answer": ANSWER, "route": 3}),
        json!({"answer": ANSWER, "route": u64::MAX}),
        // More names than one call looks up (refused before any is).
        json!({"from": "a", "to": "b", "via": ["c", "d", "e", "f"]}),
    ] {
        assert!(s.run("map.route", &bad).is_err(), "{bad}");
    }
}

/// Places found by name, and a table's addresses turned into points, through a geocoder of one's
/// own (a local Nominatim answer here); the app's answers can be passed in instead.
#[test]
fn geocoding_places_and_addresses() {
    use crate::render::rustgis_tiles::geocode::Geocoder;
    const ANSWER: &[u8] = br#"[{"lat": "48.8584", "lon": "2.2945", "display_name": "Tour Eiffel, Paris", "boundingbox": ["48.857", "48.859", "2.293", "2.296"]}]"#;
    let base = serve(ANSWER, 4);
    let mut s = Session::new(Project::default());
    let r = s.run("map.findPlace", &json!({"query": "Eiffel Tower", "url": base})).unwrap();
    assert_eq!(r["count"], 1);
    assert_eq!(r["places"][0]["name"], "Tour Eiffel, Paris");
    assert!(s.run("map.findPlace", &json!({"query": " "})).is_err());
    assert!(s.run("map.findPlace", &json!({"query": "x", "provider": "google"})).is_err());
    // Two rows share an address, asked once; a row without one has no point.
    let csv = "id,street,city\n1,Champ de Mars,Paris\n2,Champ de Mars,Paris\n3,5 Av. Anatole,Paris\n4,,\n";
    s.run("layer.addDataText", &json!({"fileName": "sites.csv", "text": csv})).unwrap();
    assert!(s.project.tables.iter().any(|t| t.name == "sites"), "a table of addresses");
    let r = s.run("layer.geocode", &json!({"table": "sites", "address": ["street", "city"], "url": base})).unwrap();
    assert_eq!((r["matched"].as_u64(), r["unmatched"].as_u64()), (Some(3), Some(1)), "{r}");
    let l = s.map().layer_by_name("sites (geocoded)").unwrap();
    assert_eq!(l.dataset.features.len(), 4);
    assert_eq!(l.dataset.fields[l.dataset.fields.len() - 2].name, "geocoded");
    let status = l.dataset.field_index("match_status").unwrap();
    assert_eq!((0..4).map(|r| l.dataset.value(r, status).to_string()).collect::<Vec<_>>(), ["matched", "matched", "matched", "unmatched"]);
    assert!(l.dataset.features[3].geometry.is_none());
    // The app's own answers: one address found, the other not.
    let places = json!({"Champ de Mars, Paris": {"lon": 2.29, "lat": 48.85, "name": "Champ de Mars"}, "5 Av. Anatole, Paris": null});
    let r = s.run("layer.geocode", &json!({"layer": "sites", "address": "street, city", "places": places, "name": "G"})).unwrap();
    assert_eq!((r["matched"].as_u64(), r["unmatched"].as_u64()), (Some(2), Some(2)));
    let l = s.map().layer_by_name("G").unwrap();
    let status = l.dataset.field_index("match_status").unwrap();
    assert_eq!(
        (0..4).map(|r| l.dataset.value(r, status).to_string()).collect::<Vec<_>>(),
        ["matched", "matched", "unmatched", "unmatched"]
    );
    for bad in
        [json!({"layer": "sites"}), json!({"layer": "sites", "address": "nope"}), json!({"layer": "sites", "address": "id", "places": 7})]
    {
        assert!(s.run("layer.geocode", &bad).is_err(), "{bad}");
    }
    // A server that refuses: the requests are failures, not "not found".
    let refusing = format!("{}/missing", serve(ANSWER, 2));
    let e = s.run("layer.geocode", &json!({"table": "sites", "address": ["street", "city"], "url": refusing})).unwrap_err();
    assert!(e.contains("none of the addresses"), "{e}");
    assert!(s.notices.iter().any(|n| n.error && n.text.contains("2 addresses couldn't be looked up")));
    // A public server takes a hundred addresses a run.
    let g = Geocoder::new(None, None).unwrap();
    assert!(crate::cmd::geocode::check_batch(&g, 101).unwrap_err().contains("100"));
}

/// Status is per source row, including duplicate, empty and unfound addresses; colliding input
/// columns keep their names and values, and the unmatched notice still counts rows, not queries.
#[test]
fn geocoding_match_status_preserves_fields_and_unmatched_notice() {
    let mut s = Session::new(Project::default());
    let csv = "id,address,geocoded,MATCH_STATUS,match_status_\n1,A,old one,reviewed,kept\n2,A,old two,reviewed,kept\n3,B,old three,reviewed,kept\n4,,old four,reviewed,kept\n";
    s.run("layer.addDataText", &json!({"fileName":"addresses.csv", "text":csv})).unwrap();
    for (name, b, statuses, unmatched) in [
        ("mixed", Value::Null, ["matched", "matched", "unmatched", "unmatched"], 2),
        ("clean", json!({"lon":-77.1,"lat":38.1,"name":"B"}), ["matched", "matched", "matched", "unmatched"], 1),
    ] {
        let mark = s.notice_mark();
        let result = s
            .run(
                "layer.geocode",
                &json!({"table":"addresses", "address":"address", "name":name,
            "places":{"A":{"lon":-77.0,"lat":38.0,"name":""}, "B":b}}),
            )
            .unwrap();
        assert_eq!(result["unmatched"], unmatched);
        let ds = &s.map().layer_by_name(name).unwrap().dataset;
        let names: Vec<_> = ds.fields.iter().map(|f| f.name.as_str()).collect();
        assert_eq!(names, ["id", "address", "geocoded", "MATCH_STATUS", "match_status_", "geocoded_", "match_status__"]);
        assert_eq!(ds.features.len(), 4);
        for (r, status) in statuses.iter().enumerate() {
            assert_eq!(ds.value(r, 6).to_string(), *status);
            assert_eq!(ds.features[r].geometry.is_some(), *status == "matched");
            for c in 0..5 {
                assert_eq!(ds.value(r, c), s.project.tables[0].dataset.value(r, c));
            }
        }
        // A usable point counts as a match even if the provider gave no display name.
        assert_eq!(ds.value(0, 5), &rustgis_data::Value::Text(String::new()));
        let notices = s.notices_since(mark);
        assert_eq!(notices.len(), 1);
        assert_eq!(notices[0].text, format!("{unmatched} of 4 rows weren't found; they are in the table without a point"));
    }
    let mark = s.notice_mark();
    s.run(
        "layer.geocode",
        &json!({"table":"addresses", "address":"id", "name":"all matched",
        "places":{"1":{"lon":1,"lat":1}, "2":{"lon":2,"lat":2}, "3":{"lon":3,"lat":3}, "4":{"lon":4,"lat":4}}}),
    )
    .unwrap();
    assert!(s.notices_since(mark).is_empty());
}

/// Applying supplied answers does not require a network-capable Census endpoint, including
/// in the browser where the public server lacks CORS.
#[test]
fn geocoding_census_supplied_answers_need_no_fetch() {
    let mut s = Session::new(Project::default());
    s.run("layer.addDataText", &json!({"fileName":"addresses.csv", "text":"address\nA\n"})).unwrap();
    let result = s
        .run(
            "layer.geocode",
            &json!({"provider":"census", "table":"addresses", "address":"address",
        "places":{"A":{"lon":-77.0,"lat":38.0,"name":"A"}}}),
        )
        .unwrap();
    assert_eq!(result["matched"], 1);
}

/// Census's address response through both public commands, served locally so the test needs
/// no network. A malformed candidate is reported; unmatched rows retain their attributes.
#[test]
fn geocoding_with_census() {
    let clean = br#"{"result":{"addressMatches":[{"matchedAddress":"4600 SILVER HILL RD, WASHINGTON, DC, 20233","coordinates":{"x":-76.92748724230096,"y":38.84601622386617}}, {"matchedAddress":"SECOND CANDIDATE","coordinates":{"x":-77,"y":38}}]}}"#;
    let lossy = br#"{"result":{"addressMatches":[{}, {"matchedAddress":"SECOND ADDRESS","coordinates":{"x":-77.0,"y":38.9}}]}}"#;
    let path = |q: &str| format!("/locations/onelineaddress?address={q}&benchmark=Public_AR_Current&format=json");
    let (base, asked) = serve_files(vec![
        (path("4600%20Silver%20Hill%20Rd%2C%20Washington%2C%20DC%2020233"), clean.to_vec()),
        (path("second"), lossy.to_vec()),
        (path("missing"), br#"{"result":{"addressMatches":[]}}"#.to_vec()),
    ]);
    let mut s = Session::new(Project::default());
    let result = s
        .run("map.findPlace", &json!({"provider":"census", "url":base, "query":"4600 Silver Hill Rd, Washington, DC 20233", "limit":1}))
        .unwrap();
    assert_eq!(result["count"], 1);
    assert_eq!(result["places"][0]["lon"], -76.92748724230096);
    assert_eq!(result["places"][0]["lat"], 38.84601622386617);
    assert_eq!(s.notices.len(), 1);
    assert_eq!(s.notices[0].text, "Search candidates not shown: 1 (limit 1).");
    s.run("layer.addDataText", &json!({"fileName":"addresses.csv", "text":"id,address\n1,second\n2,missing\n"})).unwrap();
    let result = s.run("layer.geocode", &json!({"provider":"census", "url":base, "table":"addresses", "address":"address"})).unwrap();
    assert_eq!(result["matched"], 1);
    assert_eq!(result["unmatched"], 1);
    let l = s.map().layer_by_name("addresses (geocoded)").unwrap();
    assert_eq!(l.dataset.features[0].geometry, Some(rustgis_data::Geometry::Point(rustgis_geom::Coord::new(-77.0, 38.9))));
    assert!(l.dataset.features[1].geometry.is_none());
    assert_eq!(l.dataset.value(1, 1).to_string(), "missing");
    assert_eq!(s.notices.iter().filter(|n| n.text.starts_with("1 of the geocoder's places")).count(), 1);
    assert_eq!(asked.lock().unwrap().len(), 3);
}

/// The command reports alternatives omitted by batch geocoding, including the parser cap;
/// an unambiguous match produces no notice.
#[test]
fn geocoding_census_batch_reports_unused_candidates() {
    for count in [1, 3, 25] {
        let p = json!({"matchedAddress":"A", "coordinates":{"x":-77.0,"y":38.0}});
        let response = serde_json::to_vec(&json!({"result":{"addressMatches":vec![p;count]}})).unwrap();
        let (base, _) = serve_files(vec![("/locations/onelineaddress?address=A&benchmark=Public_AR_Current&format=json".into(), response)]);
        let mut s = Session::new(Project::default());
        s.run("layer.addDataText", &json!({"fileName":"addresses.csv", "text":"address\nA\n"})).unwrap();
        let mark = s.notice_mark();
        let result = s.run("layer.geocode", &json!({"provider":"census", "url":base, "table":"addresses", "address":"address"})).unwrap();
        assert_eq!(result["matched"], 1);
        let notices = s.notices_since(mark);
        if count == 1 {
            assert!(notices.is_empty(), "{notices:?}");
        } else {
            assert_eq!(notices.len(), 1);
            assert_eq!(
                notices[0].text,
                format!("{} additional geocoding candidates were not used; the first match was kept for each address.", count - 1)
            );
        }
    }
}

/// PDOK's Locatieserver as the geocoder (a local server answering as it does): places found by
/// name, a table's Dutch addresses turned into points, and the answers' entries without a usable
/// point counted in a notice (and no notice when every entry has one).
#[test]
fn geocoding_with_the_locatieserver() {
    use crate::render::rustgis_tiles::geocode::Geocoder;
    let clean = br#"{"response":{"numFound":2,"start":0,"docs":[
        {"weergavenaam":"Damrak 1, 1012LG Amsterdam","centroide_ll":"POINT(4.89803846 52.37714446)"},
        {"weergavenaam":"Damrak, Amsterdam","centroide_ll":"POINT(4.89580599 52.37513402)"}]}}"#;
    let lossy = br#"{"response":{"numFound":2,"start":0,"docs":[
        {"weergavenaam":"Coolsingel, Rotterdam","centroide_ll":"POINT(4.4795)"},
        {"weergavenaam":"Coolsingel 40, 3011AD Rotterdam","centroide_ll":"POINT(4.47920127 51.92272076)"}]}}"#;
    let nothing = br#"{"response":{"numFound":0,"start":0,"docs":[]}}"#;
    // Each request's path and query exactly as the Locatieserver kind builds them.
    let path = |q: &str, limit: usize| {
        let g = Geocoder::new(Some("locatieserver"), Some("http://127.0.0.1")).unwrap();
        g.url(q, limit).trim_start_matches("http://127.0.0.1").to_string()
    };
    let (base, asked) = serve_files(vec![
        (path("Damrak 1, Amsterdam", 5), clean.to_vec()),
        (path("Damrak 1, Amsterdam", 1), clean.to_vec()),
        (path("Coolsingel 40, Rotterdam", 1), lossy.to_vec()),
        (path("Nergensstraat 9, Nergenshuizen", 1), nothing.to_vec()),
        (path("Kapot", 5), br#"{"response":{"docs":[{"weergavenaam":"x","centroide_ll":"POINT(x y)"}]}}"#.to_vec()),
    ]);
    let url = format!("{base}/free");
    let left_out =
        |s: &Session| s.notices.iter().filter(|n| n.text.contains("no usable position")).map(|n| n.text.clone()).collect::<Vec<_>>();
    let mut s = Session::new(Project::default());
    let r = s.run("map.findPlace", &json!({"query": "Damrak 1, Amsterdam", "provider": "locatieserver", "url": url})).unwrap();
    assert_eq!(r["count"], 2, "{r}");
    assert_eq!(r["places"][0]["name"], "Damrak 1, 1012LG Amsterdam");
    assert_eq!((r["places"][0]["lon"].as_f64(), r["places"][0]["lat"].as_f64()), (Some(4.89803846), Some(52.37714446)));
    // The camera went to the first place, longitude and latitude the right way round.
    let c = s.map().to_lonlat(s.map().camera.center).unwrap();
    assert!((c.x - 4.898).abs() < 0.01 && (c.y - 52.377).abs() < 0.01, "{c:?}");
    assert!(left_out(&s).is_empty(), "a clean answer leaves nothing out: {:?}", left_out(&s));
    // A table of Dutch addresses: one found, one found after an entry without a usable point
    // (counted), one not found.
    let csv = "id,street,city\n1,Damrak 1,Amsterdam\n2,Coolsingel 40,Rotterdam\n3,Nergensstraat 9,Nergenshuizen\n";
    s.run("layer.addDataText", &json!({"fileName": "adressen.csv", "text": csv})).unwrap();
    let r = s
        .run("layer.geocode", &json!({"table": "adressen", "address": ["street", "city"], "provider": "locatieserver", "url": url}))
        .unwrap();
    assert_eq!((r["matched"].as_u64(), r["unmatched"].as_u64()), (Some(2), Some(1)), "{r}");
    let l = s.map().layer_by_name("adressen (geocoded)").unwrap();
    let points: Vec<_> = l.dataset.features.iter().map(|f| f.geometry.clone()).collect();
    assert_eq!(points[0], Some(rustgis_data::Geometry::Point(rustgis_geom::Coord::new(4.89803846, 52.37714446))));
    assert_eq!(points[1], Some(rustgis_data::Geometry::Point(rustgis_geom::Coord::new(4.47920127, 51.92272076))));
    assert_eq!(points[2], None);
    let geocoded = l.dataset.field_index("geocoded").unwrap();
    assert_eq!(l.dataset.value(1, geocoded).to_string(), "Coolsingel 40, 3011AD Rotterdam");
    assert_eq!(left_out(&s).len(), 1, "one notice for the run: {:?}", left_out(&s));
    assert!(left_out(&s)[0].starts_with("1 of the geocoder's places"), "{:?}", left_out(&s));
    // An answer whose every place is unusable is an error, not "nothing found"; a query longer
    // than the Locatieserver takes isn't sent cut short.
    let e = s.run("map.findPlace", &json!({"query": "Kapot", "provider": "locatieserver", "url": url})).unwrap_err();
    assert!(e.contains("none with a usable position"), "{e}");
    let e = s.run("map.findPlace", &json!({"query": "a".repeat(401), "provider": "locatieserver", "url": url})).unwrap_err();
    assert!(e.contains("up to 400"), "{e}");
    // Every request asked the Locatieserver's search, for the kinds of place it is given.
    let asked = asked.lock().unwrap().clone();
    assert_eq!(asked.len(), 5, "{asked:?}");
    assert!(asked.iter().all(|p| p.starts_with("/free?q=") && p.contains("&fq=type%3A%28provincie%20OR")), "{asked:?}");
    // The public server takes a whole table, a few requests a second.
    let g = Geocoder::new(Some("locatieserver"), None).unwrap();
    assert!(crate::cmd::geocode::check_batch(&g, 5000).is_ok());
    assert!(crate::cmd::geocode::check_batch(&g, 10_001).unwrap_err().contains("10000"));
    assert!(g.spacing_ms() > 0);
}

/// Addresses longer than the Locatieserver takes, ahead of one it finds: each fails on its own
/// (counted in the run's notice) and isn't sent, rather than counting as the server refusing
/// requests, which would stop the run before the address it finds.
#[test]
fn geocoding_skips_addresses_too_long_for_the_server() {
    use crate::render::rustgis_tiles::geocode::Geocoder;
    let clean = br#"{"response":{"numFound":1,"start":0,"docs":[
        {"weergavenaam":"Damrak 1, 1012LG Amsterdam","centroide_ll":"POINT(4.89803846 52.37714446)"}]}}"#;
    let g = Geocoder::new(Some("locatieserver"), Some("http://127.0.0.1")).unwrap();
    let path = g.url("Damrak 1, Amsterdam", 1).trim_start_matches("http://127.0.0.1").to_string();
    let (base, asked) = serve_files(vec![(path, clean.to_vec())]);
    let mut csv = "id,address\n".to_string();
    for (i, c) in ["a", "b", "c", "d", "e", "f"].iter().enumerate() {
        csv.push_str(&format!("{i},{}\n", c.repeat(401)));
    }
    csv.push_str("9,\"Damrak 1, Amsterdam\"\n");
    let mut s = Session::new(Project::default());
    s.run("layer.addDataText", &json!({"fileName": "lang.csv", "text": csv})).unwrap();
    let r = s
        .run("layer.geocode", &json!({"table": "lang", "address": "address", "provider": "locatieserver", "url": format!("{base}/free")}))
        .unwrap();
    assert_eq!((r["matched"].as_u64(), r["unmatched"].as_u64()), (Some(1), Some(6)), "{r}");
    let failed: Vec<_> = s.notices.iter().filter(|n| n.text.contains("couldn't be looked up")).map(|n| n.text.clone()).collect();
    assert_eq!(failed.len(), 1, "{failed:?}");
    assert!(failed[0].starts_with("6 addresses") && failed[0].contains("401 characters"), "{failed:?}");
    // Only the address that fits was sent.
    assert_eq!(asked.lock().unwrap().len(), 1);
}

/// The SQL workspace's commands: a query's first rows without a layer, and a database's columns
/// (through DuckDB when it is installed; without it, they say how to get it).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn sql_workspace_rows_and_schema() {
    let mut s = Session::new(Project::default());
    assert!(s.run("sql.query", &json!({})).is_err());
    if !rustgis_data::source::duckdb::test_runs().unwrap() {
        assert!(s.run("sql.query", &json!({"sql": "SELECT 1"})).unwrap_err().contains("need DuckDB"));
        return;
    }
    let before = s.map().layers.len();
    let r = s.run("sql.query", &json!({"sql": "SELECT i AS n, ST_Point(i, 0) AS geom FROM range(150) t(i)"})).unwrap();
    assert_eq!(r["rows"].as_array().map(Vec::len), Some(100), "the default limit");
    assert_eq!((r["geometry"].as_bool(), r["more"].as_bool()), (Some(true), Some(true)));
    assert_eq!(r["columns"][0]["name"], "n");
    assert_eq!(r["rows"][2][1], "POINT (2 0)");
    // A result the app ran is added only for the query it came from, and kept until it is.
    let q = "SELECT 'a' AS name, ST_Point(1, 2) AS geom";
    let out = rustgis_data::source::duckdb::run(&rustgis_data::source::duckdb::Query { sql: q, ..Default::default() }).unwrap();
    let id = s.sql_ran(q, None, out);
    assert!(s.run("layer.addSql", &json!({"sql": "SELECT 2 AS x", "ran": id})).unwrap_err().contains("another query"));
    let r = s.run("layer.addSql", &json!({"sql": q, "ran": id, "name": "Ran"})).unwrap();
    assert_eq!(r["features"], 1);
    assert!(s.run("layer.addSql", &json!({"sql": q, "ran": id})).unwrap_err().contains("no longer kept"));
    s.run("layer.remove", &json!({"layer": "Ran"})).unwrap();
    assert_eq!(s.map().layers.len(), before, "no layer is added");
    let r = s.run("sql.query", &json!({"sql": "SELECT 'a' AS x", "limit": 5000})).unwrap();
    assert_eq!((r["geometry"].as_bool(), r["more"].as_bool()), (Some(false), Some(false)));
    assert!(s.run("sql.query", &json!({"sql": "SELECT * FROM nowhere"})).unwrap_err().contains("nowhere"));
    // A database's tables and their columns.
    let dir = std::env::temp_dir().join(format!("rustgis-engine-sqlws-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let db = dir.join("towns.duckdb");
    let ok = std::process::Command::new(rustgis_data::source::duckdb::program().unwrap())
        .arg(&db)
        .arg("-c")
        .arg("CREATE TABLE towns AS SELECT 'x' AS name, 3 AS pop;")
        .status()
        .unwrap()
        .success();
    assert!(ok);
    let r = s.run("sql.schema", &json!({"database": db.display().to_string()})).unwrap();
    assert_eq!(r["tables"]["towns"], json!(["name", "pop"]));
    let r = s.run("sql.query", &json!({"sql": "SELECT pop FROM towns", "database": db.display().to_string()})).unwrap();
    assert_eq!(r["rows"], json!([[3]]));
    let _ = std::fs::remove_dir_all(dir);
}

/// Serves `body` with byte ranges (`Range: bytes=a-b` answered 206) until the test ends; returns
/// the base address and the count of bytes sent.
fn serve_ranges(body: Vec<u8>) -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    serve_file(body, true)
}

/// [`serve_ranges`], or (`ranges` false) a server that ignores `Range` and answers every request
/// with the whole file.
fn serve_file(body: Vec<u8>, ranges: bool) -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    serve_gated(body, ranges, None)
}

/// [`serve_ranges`] refusing the first `n` requests with a 503 and `Retry-After: 1` (a server
/// busy for a moment), answering the rest.
fn serve_refusing_first(body: Vec<u8>, n: usize) -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    serve_with(body, true, None, n, 0)
}

/// [`serve_ranges`], answering the first `n - 1` requests (a file's header) and refusing the rest
/// with a 500: a file whose header reads but whose tiles can't be.
fn serve_refusing_from(body: Vec<u8>, n: usize) -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    serve_with(body, true, None, 0, n)
}

/// [`serve_file`] holding every answer until `gate` is set (a request still under way, for as long
/// as a test needs).
fn serve_gated(
    body: Vec<u8>,
    ranges: bool,
    gate: Option<std::sync::Arc<std::sync::atomic::AtomicBool>>,
) -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    serve_with(body, ranges, gate, 0, 0)
}

/// [`serve_gated`], refusing the first `refuse` requests (see [`serve_refusing_first`]), and every
/// request from the `refuse_from`th on (see [`serve_refusing_from`]; 0 for none).
fn serve_with(
    body: Vec<u8>,
    ranges: bool,
    gate: Option<std::sync::Arc<std::sync::atomic::AtomicBool>>,
    refuse: usize,
    refuse_from: usize,
) -> (String, std::sync::Arc<std::sync::atomic::AtomicUsize>) {
    use std::io::{Read, Write};
    let refusals = std::sync::Arc::new(std::sync::Mutex::new(refuse));
    let seen = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let sent = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let count = sent.clone();
    let body = std::sync::Arc::new(body);
    std::thread::spawn(move || {
        // Each connection on its own thread: a layer read in place asks for its tiles together,
        // and answering them one by one would hold a fetch worker for each while the others wait
        // (the fetch workers are shared by every test in the process).
        for stream in listener.incoming() {
            let Ok(mut s) = stream else { continue };
            let (body, count, gate, refusals, seen) = (body.clone(), count.clone(), gate.clone(), refusals.clone(), seen.clone());
            std::thread::spawn(move || {
                let mut buf = [0u8; 4096];
                let read = s.read(&mut buf).unwrap_or(0);
                // Refused from the `refuse_from`th request on: a file whose tiles can't be read.
                let nth = seen.fetch_add(1, std::sync::atomic::Ordering::Relaxed) + 1;
                if refuse_from > 0 && nth >= refuse_from {
                    let _ = s.write_all(b"HTTP/1.1 500 Internal Server Error\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
                    return;
                }
                // Refused while there are refusals left: busy, ask again in a second.
                let refused = {
                    let mut left = refusals.lock().unwrap();
                    let refused = *left > 0;
                    *left = left.saturating_sub(1);
                    refused
                };
                if refused {
                    let _ = s
                        .write_all(b"HTTP/1.1 503 Service Unavailable\r\nRetry-After: 1\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
                    return;
                }
                if let Some(g) = &gate {
                    let start = std::time::Instant::now();
                    while !g.load(std::sync::atomic::Ordering::Relaxed) && start.elapsed() < std::time::Duration::from_secs(60) {
                        std::thread::sleep(std::time::Duration::from_millis(5)); // test-wait: hold fixture replies until the release flag is set
                    }
                }
                let req = String::from_utf8_lossy(&buf[..read]).to_ascii_lowercase();
                // A HEAD request is answered with the length alone.
                if req.starts_with("head ") {
                    let _ = write!(s, "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n", body.len());
                    return;
                }
                let range = req.lines().filter(|_| ranges).find_map(|l| l.strip_prefix("range: bytes=")).and_then(|r| {
                    let (a, b) = r.trim().split_once('-')?;
                    // A suffix (`-n`): the last n bytes.
                    if a.is_empty() {
                        let n = b.parse::<usize>().ok()?.min(body.len());
                        return Some((body.len() - n, body.len().saturating_sub(1)));
                    }
                    Some((a.parse::<usize>().ok()?, b.parse::<usize>().ok()?))
                });
                let (status, part) = match range {
                    Some((a, b)) if a < body.len() => ("206 Partial Content", &body[a..=b.min(body.len() - 1)]),
                    Some(_) => ("416 Range Not Satisfiable", &body[..0]),
                    None => ("200 OK", &body[..]),
                };
                count.fetch_add(part.len(), std::sync::atomic::Ordering::Relaxed);
                let _ = write!(s, "HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n", part.len());
                let _ = s.write_all(part);
            });
        }
    });
    (format!("http://{addr}"), sent)
}

/// A static collection laid out by date (JAXA Earth's) as a data cube: no search, the period's
/// date folders read and each item's own file taken, with the scale and no-data in `je:rasters`,
/// on the time slider and in a trend; a document missing is told, and clean input tells nothing.
#[test]
fn a_static_collection_by_date_as_a_data_cube() {
    let (cog, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let months = ["2023-12", "2024-01", "2024-02", "2024-03", "2024-04", "2024-05", "2024-06"];
    let item = |m: &str| {
        format!(
            r#"{{"type": "Feature", "id": "N00.00-N90.00", "collection": "jaxa.cube", "bbox": [0, 0, 90, 90], "geometry": null,
               "properties": {{"datetime": null, "start_datetime": "{m}-01T00:00:00.000000Z"}},
               "assets": {{"V": {{"href": "{cog}/{m}.tiff", "type": "image/tiff; application=geotiff",
                  "je:rasters": {{"dn2value": {{"slope": 0.5, "offset": 0.0}}, "dn": {{"nodata": 255.0, "error": [5.0]}}}}}}}}}}"#
        )
    };
    let catalog = |rel: &str, href: &str| format!(r#"{{"type": "Catalog", "links": [{{"rel": "{rel}", "href": "{href}"}}]}}"#);
    let children: Vec<String> = months.iter().map(|m| format!(r#"{{"rel": "child", "href": "./{m}/catalog.json"}}"#)).collect();
    let leak = |t: String| -> &'static str { Box::leak(t.into_boxed_str()) };
    let mut routes: Vec<(&'static str, String)> = vec![(
        "/c/collection.json",
        format!(
            r#"{{"type": "Collection", "id": "collection", "links": [{}], "summaries": {{"je:stac_date_format": ["YYYY-MM"], "je:cog_level_max": [1]}}}}"#,
            children.join(",")
        ),
    )];
    for m in months {
        routes.push((leak(format!("/c/{m}/catalog.json")), catalog("child", "./1/catalog.json")));
        routes.push((leak(format!("/c/{m}/1/catalog.json")), catalog("child", "./E000.00-E090.00/catalog.json")));
        routes.push((leak(format!("/c/{m}/1/E000.00-E090.00/catalog.json")), catalog("item", "./N00.00-N90.00.json")));
        if m != "2024-03" {
            routes.push((leak(format!("/c/{m}/1/E000.00-E090.00/N00.00-N90.00.json")), item(m)));
        }
    }
    let collection_doc = routes[0].1.clone();
    let url = format!("{}/c/collection.json", serve_routes(routes, 200));
    let cube = |start: &str, end: &str| json!({"url": url, "collection": "jaxa.cube", "asset": "V", "bbox": [10, 45, 11, 46], "start": start, "end": end, "range": [0, 50], "test": "original"});
    let mut s = Session::new(Project::default());
    let mark = s.notice_mark();
    let r = s.run("stac.addCube", &cube("2024-01-01", "2024-02-29")).unwrap();
    assert_eq!((r["items"].as_u64(), r["tiles"].as_u64(), r["dates"].as_u64()), (Some(2), Some(1), Some(2)), "{r}");
    let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
    assert!(!said.iter().any(|t| t.contains("couldn't be read")), "clean input tells no missing document: {said:?}");
    // Its codes for a failed retrieval draw as values on the map, and that is said.
    assert!(said.iter().any(|t| t.contains("2 file(s) mark failed retrievals with codes")), "{said:?}");
    assert!(!said.iter().any(|t| t.contains("left out, as their codes")), "codes read whole leave nothing out: {said:?}");
    let tile = &s.map().tiles[0];
    assert_eq!(tile.time_urls.len(), 2);
    assert!(tile.time_urls[0].1.ends_with("/2024-01.tiff#range=0,100"), "the range through je:rasters' slope: {}", tile.time_urls[0].1);
    // A document missing: its date is left out, and said.
    let mut gap = Session::new(Project::default());
    let mark = gap.notice_mark();
    let r = gap.run("stac.addCube", &cube("2024-02-01", "2024-04-30")).unwrap();
    assert_eq!(r["dates"], 2, "{r}");
    let said: Vec<&str> = gap.notices_since(mark).iter().map(|n| n.text.as_str()).collect();
    assert!(said.iter().any(|t| t.contains("1 document(s) couldn't be read") && t.contains("jaxa.cube")), "{said:?}");
    // In a trend, a stored value that is a code for a failed retrieval is no value; the rest are
    // read through the slope. Pixel (x, y) stores (x + y) % 256, the same at every date.
    let t = s.run("cube.reduce", &json!({"url": url, "collection": "jaxa.cube", "asset": "V", "bbox": [10, 45, 11, 46], "start": "2024-04-01", "end": "2024-06-30", "stat": "mean"})).unwrap();
    let id = t["layers"][0].as_u64().or(t["layer"].as_u64()).unwrap() as u32;
    let data = s.map().layer(id).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    let at = |x: usize, y: usize| data.bands[0].data[y * data.width as usize + x];
    assert!(at(2, 3).is_nan(), "(2 + 3) is the code: {}", at(2, 3));
    assert_eq!(at(3, 3), 3.0, "6 through the slope");
    // Another collection's name, and collections that can't make a cube.
    let mut wrong = cube("2024-01-01", "2024-02-29");
    wrong["collection"] = json!("other");
    let e = Session::new(Project::default()).run("stac.addCube", &wrong).unwrap_err();
    assert!(e.contains("holds jaxa.cube, not other"), "{e}");
    let plain = serve_routes(vec![("/s/collection.json", r#"{"type": "Collection", "links": []}"#.to_string())], 2);
    let mut other = cube("2024-01-01", "2024-02-29");
    other["url"] = json!(format!("{plain}/s/collection.json"));
    let e = Session::new(Project::default()).run("stac.addCube", &other).unwrap_err();
    assert!(e.contains("laid out by date"), "{e}");
    let normal = serve_routes(
        vec![("/n/collection.json", r#"{"type": "Collection", "links": [], "summaries": {"je:stac_date_format": ["MM"]}}"#.to_string())],
        2,
    );
    other["url"] = json!(format!("{normal}/n/collection.json"));
    let e = Session::new(Project::default()).run("stac.addCube", &other).unwrap_err();
    assert!(e.contains("no year"), "{e}");
    // Codes for a failed retrieval that can't be read whole: the item is left out, and said.
    let bad = item("2024-01").replace(r#""error": [5.0]"#, r#""error": [5.0, "x"]"#);
    let mut odd = vec![("/c/collection.json", collection_doc)];
    odd.push(("/c/2024-01/catalog.json", catalog("child", "./1/catalog.json")));
    odd.push(("/c/2024-01/1/catalog.json", catalog("child", "./E000.00-E090.00/catalog.json")));
    odd.push(("/c/2024-01/1/E000.00-E090.00/catalog.json", catalog("item", "./N00.00-N90.00.json")));
    odd.push(("/c/2024-01/1/E000.00-E090.00/N00.00-N90.00.json", bad));
    let odd_url = format!("{}/c/collection.json", serve_routes(odd, 20));
    let mut p = cube("2024-01-01", "2024-01-31");
    p["url"] = json!(odd_url);
    let e = Session::new(Project::default()).run("stac.addCube", &p).unwrap_err();
    assert!(e.contains("1 item(s) left out, as their codes for a failed retrieval"), "{e}");
}

/// A STAC collection's band as a data cube on the time slider (#559), from a local API: a tile
/// layer per grid tile, each a file per date; the slider on over their dates; a fixed range in the
/// band's own units, through its scale; a tile with no date in the window drawn as nothing.
#[test]
fn a_stac_data_cube_on_the_time_slider() {
    let (cog, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let item = |id: &str, tile: &str, date: &str, band: bool| {
        let asset = if band {
            format!(
                r#""NDVI": {{"href": "{cog}/{id}.tif", "type": "image/tiff; application=geotiff; profile=cloud-optimized", "eo:bands": [{{"scale": 0.0001}}]}}"#
            )
        } else {
            format!(r#""EVI": {{"href": "{cog}/{id}.tif"}}"#)
        };
        format!(
            r#"{{"type": "Feature", "id": "{id}", "collection": "cube", "bbox": [10, 45, 11, 46], "geometry": null,
               "properties": {{"datetime": "{date}T00:00:00Z", "bdc:tiles": ["{tile}"]}}, "assets": {{{asset}}}}}"#
        )
    };
    let features = [
        item("a1", "T1", "2024-01-01", true),
        item("a2", "T1", "2024-01-17", true),
        item("b1", "T2", "2024-01-01", true),
        item("b2", "T2", "2024-01-01", true),
        item("c1", "T3", "2024-01-17", false),
    ]
    .join(",");
    let base = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{features}]}}"#))], 4);
    let api = format!("{base}/v1");
    let mut s = Session::new(Project::default());
    let r = s
        .run(
            "stac.addCube",
            &json!({"url": api, "collection": "cube", "asset": "ndvi", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-31", "range": [0, 0.9]}),
        )
        .unwrap();
    assert_eq!(
        (r["items"].as_u64(), r["tiles"].as_u64(), r["dates"].as_u64(), r["layers"].as_u64(), r["skipped"].as_u64()),
        (Some(5), Some(2), Some(2), Some(2), Some(1)),
        "{r}"
    );
    assert_eq!(r["duplicates"], 1, "the second item of T2 on 2024-01-01 is left out and counted");
    assert!(!s.notices.iter().any(|n| n.text.contains("failed retrievals")), "no codes, no notice of them");
    assert!(
        s.registry.get("stac.addCube").is_some_and(|c| c.effects.contains(crate::policy::Effect::Network)),
        "a network command: a plugin needs the network permission to run it"
    );
    // An end given as a year or a month takes all of it: "end": "2024-01" reaches 31 January.
    // Read as 1 January, it would be before this start and refused.
    let mut by_month = Session::new(Project::default());
    let r2 = by_month
        .run(
            "stac.addCube",
            &json!({"url": api, "collection": "cube", "asset": "ndvi", "bbox": [10, 45, 11, 46], "start": "2024-01-15", "end": "2024-01"}),
        )
        .unwrap();
    assert_eq!(r2["dates"], 2, "an end given as a year or a month reaches its last day: {r2}");
    // A slider already on takes the cube's dates in: one over other dates gains these two.
    let mut busy = Session::new(Project::default());
    busy.run("time.set", &json!({"dates": ["2023-06-01", "2023-07-01"]})).unwrap();
    busy.run(
        "stac.addCube",
        &json!({"url": api, "collection": "cube", "asset": "ndvi", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-31"}),
    )
    .unwrap();
    assert_eq!(busy.run("time.info", &Value::Null).unwrap()["steps"], 4, "the slider takes the cube's dates in");
    let tiles = s.map().tiles.clone();
    assert_eq!(tiles.len(), 2);
    let t1 = tiles.iter().find(|t| t.name.ends_with("T1")).unwrap();
    let t2 = tiles.iter().find(|t| t.name.ends_with("T2")).unwrap();
    // A file per date (the first item of a tile and day), the range in stored values (0.9 / 0.0001).
    assert_eq!(t1.time_urls.len(), 2);
    assert_eq!(t2.time_urls.len(), 1);
    assert!(t1.time_urls.iter().all(|(_, u)| u.ends_with("#range=0,9000")), "{:?}", t1.time_urls);
    assert!(t2.time_urls[0].1.contains("/b1.tif"));
    // The slider: on, over the two dates; at the first, both tiles draw.
    assert_eq!(s.run("time.info", &Value::Null).unwrap()["steps"], 2);
    assert!(t1.draws() && t2.draws() && t1.url.contains("/a1.tif"));
    // The second date: T1's second file; T2 has none then and draws nothing.
    s.run("time.goTo", &json!({"step": 1})).unwrap();
    let t1 = s.map().tiles.iter().find(|t| t.name.ends_with("T1")).unwrap();
    let t2 = s.map().tiles.iter().find(|t| t.name.ends_with("T2")).unwrap();
    assert!(t1.url.contains("/a2.tif") && t1.draws(), "{}", t1.url);
    assert!(!t2.draws());
    // Saved and opened again, each tile's dates and the slider's step come back.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t.map().tiles.iter().find(|x| x.name.ends_with("T1")).unwrap();
    assert_eq!(again.time_urls.len(), 2);
    assert!(again.url.contains("/a2.tif"), "{}", again.url);
    // T2, with no file at that step, draws nothing from the start: opening takes the window.
    assert!(!t.map().tiles.iter().find(|x| x.name.ends_with("T2")).unwrap().draws());
    for bad in [
        json!({"url": api, "asset": "ndvi", "start": "2024-01-01", "end": "2024-01-31"}),
        json!({"url": api, "collection": "cube", "start": "2024-01-01", "end": "2024-01-31"}),
        json!({"url": api, "collection": "cube", "asset": "ndvi", "start": "2024-02-01", "end": "2024-01-01"}),
        json!({"url": api, "collection": "cube", "asset": "ndvi", "start": "2024-01-01", "end": "2024-01-31", "range": [1, 0]}),
        json!({"url": api, "collection": "cube", "asset": "ndvi", "start": "June", "end": "2024-01-31"}),
        json!({"url": api, "collection": "cube", "asset": "ndvi", "start": "2024-01-01", "end": "2024-01-31", "range": ["a", 0, 1]}),
        json!({"url": api, "collection": "cube", "asset": "ndvi", "start": "2024-01-01", "end": "2024-01-31", "range": [0, "x", 1]}),
    ] {
        assert!(s.run("stac.addCube", &bad).is_err(), "{bad}");
    }
    // A file read whole (a GeoTIFF that isn't cloud-optimised) can't follow the slider: the cube
    // is refused, and what it added is taken back, the view its first tile framed included.
    let gt = rustgis_data::raster::GeoTransform { origin_x: 10.0, origin_y: 46.0, pixel_width: 0.5, pixel_height: -0.5 };
    let plain = rustgis_data::raster::Raster::new(
        "p",
        2,
        2,
        vec![vec![1.0; 4]],
        gt,
        rustgis_data::raster::Crs::LonLat,
        None,
        rustgis_data::raster::ColorHint::Gray,
        "Float32",
    )
    .unwrap();
    let (file, _) = serve_ranges(rustgis_data::raster::geotiff::write(&plain, 0).unwrap());
    let one = format!(
        r#"{{"type": "Feature", "id": "p1", "collection": "cube", "bbox": [10, 45, 11, 46], "geometry": null,
           "properties": {{"datetime": "2024-01-01T00:00:00Z", "bdc:tiles": ["P"]}}, "assets": {{"NDVI": {{"href": "{file}/p.tif"}}}}}}"#
    );
    let first = item("q1", "A", "2024-01-01", true);
    let plain_api = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{first},{one}]}}"#))], 2);
    s.zoom_to(&rustgis_geom::Extent::new(-60.0, -30.0, -50.0, -20.0));
    let (tiles, layers) = (s.map().tiles.len(), s.map().layers.len());
    let (camera, time) = (s.map().camera, s.map().time.clone());
    let e = s
        .run(
            "stac.addCube",
            &json!({"url": format!("{plain_api}/v1"), "collection": "cube", "asset": "ndvi", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-31"}),
        )
        .unwrap_err();
    assert!(e.contains("not a cloud-optimised"), "{e}");
    assert_eq!((s.map().tiles.len(), s.map().layers.len()), (tiles, layers));
    // The view tile A framed and the slider are put back too.
    assert_eq!(s.map().camera, camera);
    assert_eq!(s.map().time, time);
    // Files stored at another scale partway: one range can't fit them all, so it's refused.
    let rescaled = |id: &str, date: &str, scale: f64| {
        format!(
            r#"{{"type": "Feature", "id": "{id}", "collection": "cube", "bbox": [10, 45, 11, 46], "geometry": null,
               "properties": {{"datetime": "{date}T00:00:00Z", "bdc:tiles": ["T1"]}},
               "assets": {{"NDVI": {{"href": "{cog}/{id}.tif", "type": "image/tiff; profile=cloud-optimized", "eo:bands": [{{"scale": {scale}}}]}}}}}}"#
        )
    };
    let two = [rescaled("r1", "2024-01-01", 0.0001), rescaled("r2", "2024-01-17", 0.001)].join(",");
    let rescaled_api = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{two}]}}"#))], 2);
    let e = s
        .run(
            "stac.addCube",
            &json!({"url": format!("{rescaled_api}/v1"), "collection": "cube", "asset": "ndvi", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-31", "range": [0, 0.9]}),
        )
        .unwrap_err();
    assert!(e.contains("same scale and offset"), "{e}");
    // Files behind signed addresses (Planetary Computer's) are refused before anything is added.
    let signed = r#"{"type": "Feature", "id": "pc1", "collection": "cube", "bbox": [10, 45, 11, 46], "geometry": null,
        "properties": {"datetime": "2024-01-01T00:00:00Z", "bdc:tiles": ["S"]},
        "assets": {"NDVI": {"href": "https://sentinel2l2a01.blob.core.windows.net/sentinel2-l2/a.tif"}}}"#;
    let signed_api = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{signed}]}}"#))], 2);
    let (tiles, layers) = (s.map().tiles.len(), s.map().layers.len());
    let e = s
        .run(
            "stac.addCube",
            &json!({"url": format!("{signed_api}/v1"), "collection": "cube", "asset": "ndvi", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-31"}),
        )
        .unwrap_err();
    assert!(e.contains("signed addresses"), "{e}");
    assert_eq!((s.map().tiles.len(), s.map().layers.len()), (tiles, layers));
}

/// A plugin's command in the app (`leave_downloads`) adds a STAC data cube as the command line
/// does (#2418): a tile layer per grid tile, its files read in place with nothing left to the app,
/// and the slider over their dates; `cube.open` with a STAC entry goes the same way. A file whose
/// address doesn't name a GeoTIFF is left to the app, and the refusal says so; one that isn't
/// cloud-optimised is added, and the map drawing it says so.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_stac_data_cube_from_a_plugin_command_in_the_app() {
    use crate::render::rustgis_tiles::cubes;
    let (cog, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let item = |id: &str, tile: &str, date: &str, href: &str| {
        format!(
            r#"{{"type": "Feature", "id": "{id}", "collection": "cube", "bbox": [10, 45, 11, 46], "geometry": null,
               "properties": {{"datetime": "{date}T00:00:00Z", "bdc:tiles": ["{tile}"]}},
               "assets": {{"NDVI": {{"href": "{cog}/{href}", "eo:bands": [{{"scale": 0.0001}}]}}}}}}"#
        )
    };
    let features =
        [item("a1", "T1", "2024-01-01", "a1.tif"), item("a2", "T1", "2024-01-17", "a2.tif"), item("b1", "T2", "2024-01-01", "b1.tif")]
            .join(",");
    let base = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{features}]}}"#))], 8);
    let api = format!("{base}/v1");
    let cube = json!({"url": api, "collection": "cube", "asset": "ndvi", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-31", "range": [0, 0.9]});
    let mut s = Session::new(Project::default());
    s.leave_downloads = true;
    let r = s.run("stac.addCube", &cube).unwrap();
    assert_eq!((r["tiles"].as_u64(), r["dates"].as_u64(), r["layers"].as_u64()), (Some(2), Some(2), Some(2)), "{r}");
    assert!(s.take_url_requests().is_empty(), "a cube's files are read in place, not left to the app to download");
    let t1 = s.map().tiles.iter().find(|t| t.name.ends_with("T1")).unwrap();
    assert_eq!(t1.time_urls.len(), 2);
    assert!(t1.time_urls.iter().all(|(_, u)| u.ends_with("#range=0,9000")), "{:?}", t1.time_urls);
    assert_eq!(s.map().tiles.iter().filter(|t| !t.time_urls.is_empty()).count(), 2);
    assert_eq!(s.run("time.info", &Value::Null).unwrap()["steps"], 2);
    s.run("time.goTo", &json!({"step": 1})).unwrap();
    assert!(s.map().tiles.iter().find(|t| t.name.ends_with("T1")).unwrap().url.contains("/a2.tif"));
    // cube.open with a STAC entry of cube.catalog runs stac.addCube: the same tile layers.
    let mut entry = cubes::find("bdc-mod13q1-ndvi").unwrap();
    entry.url = api.clone();
    entry.source = cubes::Source::Stac { collection: "cube".into(), asset: "NDVI".into() };
    (entry.bbox, entry.start, entry.end) = ([0.0, 40.0, 20.0, 50.0], "2023-05-01".into(), Some("2024-12-31".into()));
    (entry.range, entry.max_cloud) = (Some([0.0, 0.9]), None);
    let mut opened = Session::new(Project::default());
    opened.leave_downloads = true;
    let r = crate::cmd::cube_catalog::open_entry(
        &mut opened,
        &entry,
        &json!({"bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-31"}),
    )
    .unwrap();
    assert_eq!((r["tiles"].as_u64(), r["layers"].as_u64()), (Some(2), Some(2)), "{r}");
    assert!(opened.take_url_requests().is_empty());
    assert_eq!(opened.run("time.info", &Value::Null).unwrap()["steps"], 2);
    // A file whose address names no GeoTIFF is left to the app to download: said so, nothing kept
    // (the request goes with the failed command), and not taken for one that isn't cloud-optimised.
    let unnamed = item("u1", "U", "2024-01-01", "files/u1");
    let unnamed_api = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{unnamed}]}}"#))], 2);
    let mut odd = cube.clone();
    odd["url"] = json!(format!("{unnamed_api}/v1"));
    let (tiles, layers) = (s.map().tiles.len(), s.map().layers.len());
    let e = s.run("stac.addCube", &odd).unwrap_err();
    assert!(e.contains("left to the app to download") && !e.contains("not a cloud-optimised"), "{e}");
    assert_eq!((s.map().tiles.len(), s.map().layers.len()), (tiles, layers));
    assert!(s.take_url_requests().is_empty(), "the failed command's request is taken back with it");
    // A file that isn't cloud-optimised is added all the same (its header isn't read on the
    // frame); its header's read fails, and the map drawing it says why, as for any tile layer.
    let gt = rustgis_data::raster::GeoTransform { origin_x: 10.0, origin_y: 46.0, pixel_width: 0.5, pixel_height: -0.5 };
    let crs = rustgis_data::raster::Crs::LonLat;
    let plain =
        rustgis_data::raster::Raster::new("p", 2, 2, vec![vec![1.0; 4]], gt, crs, None, rustgis_data::raster::ColorHint::Gray, "Float32")
            .unwrap();
    let (stripped, _) = serve_ranges(rustgis_data::raster::geotiff::write(&plain, 0).unwrap());
    let one = item("p1", "P", "2024-01-01", "p1.tif").replace(&format!("{cog}/"), &format!("{stripped}/"));
    let stripped_api = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{one}]}}"#))], 2);
    let mut flat = Session::new(Project::default());
    flat.leave_downloads = true;
    let mut q = cube.clone();
    q["url"] = json!(format!("{stripped_api}/v1"));
    let r = flat.run("stac.addCube", &q).unwrap();
    assert_eq!(r["layers"], 1, "{r}");
    let address = flat.map().tiles.iter().find(|t| !t.time_urls.is_empty()).map(|t| t.url.clone()).unwrap_or_default();
    assert!(address.contains(&format!("{stripped}/p1.tif")), "{address}");
    let e = crate::render::rustgis_tiles::cog::info_blocking(&address).err().unwrap_or_default();
    assert!(e.contains(crate::render::rustgis_tiles::cog::NOT_COG), "{e}");
    // A GeoTIFF export says the tile layers that failed (on the ground a gap looks like data).
    let tif = std::env::temp_dir().join(format!("rustgis-2418-{}.tif", std::process::id()));
    flat.zoom_to(&rustgis_geom::Extent::new(10.0, 45.0, 11.0, 46.0));
    let n = flat.notices.len();
    let _ = flat.run("share.exportMap", &json!({"path": tif.display().to_string()}));
    std::fs::remove_file(&tif).ok();
    let now = crate::render::rustgis_tiles::cog::info(&address).map(|i| i.is_some());
    assert!(
        flat.notices[n..].iter().any(|n| n.text.contains(crate::render::rustgis_tiles::cog::NOT_COG)),
        "{now:?} {:?}",
        &flat.notices[n..]
    );
}

/// An entry that gives no range, as JAXA Earth's don't, is added with one from a sample of its
/// files (`"range": "auto"`): the same for every date. Its credit goes on the tile layers it
/// added, and its collection's licence comes back with it.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn an_entry_without_a_range_takes_one_from_its_files() {
    use crate::render::rustgis_tiles::cubes;
    let (cog, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let item = |id: &str, date: &str| {
        format!(
            r#"{{"type": "Feature", "id": "{id}", "collection": "cube", "bbox": [10, 45, 11, 46], "geometry": null,
               "properties": {{"datetime": "{date}T00:00:00Z", "bdc:tiles": ["T1"]}},
               "assets": {{"B1": {{"href": "{cog}/{id}.tif", "eo:bands": [{{"scale": 0.0001}}]}}}}}}"#
        )
    };
    let features = [item("a1", "2024-01-01"), item("a2", "2024-01-17")].join(",");
    let licence = r#"{"type": "Collection", "id": "cube", "license": "proprietary", "links": [{"rel": "license", "href": "https://earth.jaxa.jp/en/data/policy/"}]}"#;
    let base = serve_routes(
        vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{features}]}}"#)), ("/v1", licence.to_string())],
        8,
    );
    let mut entry = cubes::find("bdc-mod13q1-ndvi").unwrap();
    entry.url = format!("{base}/v1");
    entry.source = cubes::Source::Stac { collection: "cube".into(), asset: "B1".into() };
    (entry.bbox, entry.start, entry.end) = ([0.0, 40.0, 20.0, 50.0], "2023-05-01".into(), Some("2024-12-31".into()));
    (entry.range, entry.credit) = (None, "JAXA, A test dataset".into());
    let mut s = Session::new(Project::default());
    let r = crate::cmd::cube_catalog::open_entry(&mut s, &entry, &json!({"bbox": [10, 45, 11, 46]})).unwrap();
    // The example's values run 0 to 255 (0 to 0.0255 scaled): its 2nd to 98th percentiles.
    let range: Vec<f64> = r["range"].as_array().unwrap().iter().filter_map(Value::as_f64).collect();
    assert!(range.len() == 2 && range[0] >= 0.0 && range[0] < 0.002 && range[1] > 0.023 && range[1] <= 0.0256, "{r}");
    assert_eq!(r["rangeFrom"], "sample");
    let look = format!("#range={},{}", range[0] / 0.0001, range[1] / 0.0001);
    let tile = &s.map().tiles[0];
    assert!(tile.time_urls.len() == 2 && tile.time_urls.iter().all(|(_, u)| u.ends_with(&look)), "{:?} {look}", tile.time_urls);
    assert_eq!(tile.attribution, "JAXA, A test dataset");
    assert_eq!(
        (r["credit"].as_str(), r["license"]["url"].as_str()),
        (Some("JAXA, A test dataset"), Some("https://earth.jaxa.jp/en/data/policy/"))
    );
    // Opened again over the same files, its new tile layer (in place of the old one) keeps the credit.
    crate::cmd::cube_catalog::open_entry(&mut s, &entry, &json!({"bbox": [10, 45, 11, 46]})).unwrap();
    assert!(s.map().tiles.iter().filter(|t| !t.time_urls.is_empty()).all(|t| t.attribution == "JAXA, A test dataset"));
    assert!(!s.map().tiles.is_empty());
    // A range given takes its place, as for any entry.
    let mut t = Session::new(Project::default());
    let r = crate::cmd::cube_catalog::open_entry(&mut t, &entry, &json!({"bbox": [10, 45, 11, 46], "range": [0, 0.01]})).unwrap();
    assert!(r.get("rangeFrom").is_none() && t.map().tiles[0].time_urls.iter().all(|(_, u)| u.ends_with("#range=0,100")), "{r}");
    // Other text is refused, naming "auto", before anything is read.
    assert!(
        t.run("stac.addCube", &json!({"url": entry.url, "collection": "cube", "asset": "B1", "range": "wide"}))
            .unwrap_err()
            .contains("\"auto\"")
    );
    // A credit longer than a project keeps, or one that isn't text, is refused before anything is
    // read.
    for a in [json!("x".repeat(501)), json!(42), json!(["x"])] {
        let e = t.run("stac.addCube", &json!({"url": entry.url, "collection": "cube", "asset": "B1", "attribution": a})).unwrap_err();
        assert!(e.contains("at most 500"), "{a}: {e}");
    }
    // Files of classes in their own colours take no range, and a notice says so.
    use rustgis_data::raster::cog::{Example, example_with};
    let (classes, _) = serve_ranges(example_with(&Example { size: 512, tile: 256, classes: true, ..Example::default() }));
    let features = [item("a1", "2024-01-01")].join(",").replace(&cog, &classes);
    let base = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{features}]}}"#))], 4);
    let mut u = Session::new(Project::default());
    let mark = u.notices_given();
    let r = u
        .run(
            "stac.addCube",
            &json!({"url": format!("{base}/v1"), "collection": "cube", "asset": "B1", "range": "auto", "bbox": [10, 45, 11, 46], "start": "2023-05-01", "end": "2024-12-31"}),
        )
        .unwrap();
    assert!(r.get("range").is_none() && r.get("rangeFrom").is_none(), "{r}");
    assert!(u.notices_since(mark).iter().any(|n| n.text.contains("classes drawn in their own colours")), "{:?}", u.notices_since(mark));
    // Files whose metadata gives a scale of 0 aren't sampled: no range fits them, and a notice
    // says each file is stretched on its own (a range can't be left out of a catalog entry).
    let features = [item("a1", "2024-01-01")].join(",").replace("\"scale\": 0.0001", "\"scale\": 0");
    let base = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{features}]}}"#))], 4);
    let mut z = Session::new(Project::default());
    let mark = z.notices_given();
    let r = z
        .run(
            "stac.addCube",
            &json!({"url": format!("{base}/v1"), "collection": "cube", "asset": "B1", "range": "auto", "bbox": [10, 45, 11, 46], "start": "2023-05-01", "end": "2024-12-31"}),
        )
        .unwrap();
    assert!(r.get("range").is_none() && !z.map().tiles.is_empty(), "{r}");
    assert!(z.notices_since(mark).iter().any(|n| n.text.contains("gives a scale of 0")), "{:?}", z.notices_since(mark));
    // A collection whose licence can't be read: the cube is still added and credited, and a
    // notice says the licence wasn't read, pointing to JAXA's terms. Opened again, the licence is
    // asked for again (this server answers its second request for it).
    let search = format!(r#"{{"type": "FeatureCollection", "features": [{}]}}"#, [item("a1", "2024-01-01")].join(","));
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let licence = licence.to_string();
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        let mut asked = 0;
        for stream in listener.incoming().take(16) {
            let Ok(mut c) = stream else { continue };
            let mut buf = [0u8; 4096];
            let read = c.read(&mut buf).unwrap_or(0);
            let req = String::from_utf8_lossy(&buf[..read]);
            let path = req.split_whitespace().nth(1).unwrap_or("/");
            let body = if path.starts_with("/v1/search") {
                Some(search.clone())
            } else if path == "/v1" {
                asked += 1;
                (asked > 1).then(|| licence.clone())
            } else {
                None
            };
            let _ = match body {
                Some(b) => write!(c, "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{b}", b.len()),
                None => write!(c, "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n"),
            };
        }
    });
    entry.url = format!("{base}/v1");
    let mut w = Session::new(Project::default());
    let mark = w.notices_given();
    let r = crate::cmd::cube_catalog::open_entry(&mut w, &entry, &json!({"bbox": [10, 45, 11, 46]})).unwrap();
    assert!(r.get("license").is_none() && w.map().tiles[0].attribution == "JAXA, A test dataset", "{r}");
    let said = w.notices_since(mark);
    assert!(said.iter().any(|n| n.text.contains("its collection's licence wasn't read")), "{said:?}");
    let mark = w.notices_given();
    let r = crate::cmd::cube_catalog::open_entry(&mut w, &entry, &json!({"bbox": [10, 45, 11, 46]})).unwrap();
    assert_eq!(r["license"]["url"], "https://earth.jaxa.jp/en/data/policy/", "{r}");
    let said = w.notices_since(mark);
    assert!(!said.iter().any(|n| n.text.contains("licence wasn't read")), "{said:?}");
    // A licence whose server stalls (here 6 s, then a 404) isn't asked for again at the next
    // cube.open: its error is given at once, saying when it will be. The stall must outlast
    // `jaxa::SLOW_READ` (5 s), and the two opens come well within `jaxa::RETRY_AFTER` (10 min).
    let asked = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
    let counted = asked.clone();
    let search = format!(r#"{{"type": "FeatureCollection", "features": [{}]}}"#, [item("a1", "2024-01-01")].join(","));
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    std::thread::spawn(move || {
        use std::io::{Read, Write};
        for stream in listener.incoming().take(16) {
            let Ok(mut c) = stream else { continue };
            let mut buf = [0u8; 4096];
            let read = c.read(&mut buf).unwrap_or(0);
            let req = String::from_utf8_lossy(&buf[..read]);
            let path = req.split_whitespace().nth(1).unwrap_or("/").to_string();
            if path.starts_with("/v1/search") {
                let _ = write!(c, "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{search}", search.len());
            } else {
                if path == "/v1" {
                    counted.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
                }
                std::thread::spawn(move || {
                    std::thread::sleep(std::time::Duration::from_secs(6)); // test-wait: simulate a slow missing range response
                    let _ = write!(c, "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
                });
            }
        }
    });
    entry.url = format!("{base}/v1");
    let mut w = Session::new(Project::default());
    crate::cmd::cube_catalog::open_entry(&mut w, &entry, &json!({"bbox": [10, 45, 11, 46]})).unwrap();
    let (mark, before) = (w.notices_given(), asked.load(std::sync::atomic::Ordering::SeqCst));
    assert!(before >= 1, "the licence was asked for");
    let r = crate::cmd::cube_catalog::open_entry(&mut w, &entry, &json!({"bbox": [10, 45, 11, 46]})).unwrap();
    assert!(r.get("license").is_none(), "{r}");
    assert_eq!(asked.load(std::sync::atomic::Ordering::SeqCst), before, "not asked for again");
    let said = w.notices_since(mark);
    assert!(said.iter().any(|n| n.text.contains("licence wasn't read") && n.text.contains("10 minutes")), "{said:?}");
}

/// The data cube catalog (#683): its entries listed by theme, area and words; one opened as typing
/// its values into `stac.addCube` would (its collection, band, range and cloud cap filled in, its
/// last full year by default), or into `layer.addZarr` following the slider; `cube.trend` and
/// `cube.reduce` taking one by `"cube"`; wrong requests refused before anything is added.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_catalog_entry_opens_as_its_command_would() {
    use crate::render::rustgis_tiles::cubes;
    let mut s = Session::new(Project::default());
    let ids = |r: &Value| r["cubes"].as_array().unwrap().iter().map(|c| c["id"].as_str().unwrap().to_string()).collect::<Vec<_>>();
    // An id not in the list, while JAXA Earth's catalog is unread (as here), says so.
    let e = s.run("cube.open", &json!({"id": "JAXA.Test_daily/B1"})).unwrap_err();
    assert!(e.contains("no data cube") && e.contains("hasn't been read in this run"), "{e}");
    let all = s.run("cube.catalog", &json!({})).unwrap();
    assert_eq!(all["count"].as_u64(), Some(cubes::built_in().len() as u64));
    assert_eq!(all["themes"].as_array().map(Vec::len), Some(cubes::THEMES.len()));
    // MODIS over Piauí: the Brazil Data Cube's NDVI and EVI, each as the list holds it.
    let modis = s.run("cube.catalog", &json!({"theme": "vegetation", "bbox": [-46, -11, -40, -2.5], "query": "MODIS"})).unwrap();
    assert_eq!(ids(&modis), ["bdc-mod13q1-ndvi", "bdc-mod13q1-evi"]);
    assert_eq!(modis["cubes"][0]["collection"], "mod13q1-6.1");
    assert_eq!(modis["cubes"][0]["range"], json!([0.0, 0.9]));
    // No area given is anywhere, not the map's extent.
    assert!(!ids(&s.run("cube.catalog", &json!({"query": "era5"})).unwrap()).is_empty());
    // A filter of another kind is refused, not dropped (which would list every entry).
    for bad in
        [json!({"theme": "forests"}), json!({"theme": ["water"]}), json!({"query": 5}), json!({"bbox": [1, 2]}), json!({"bbox": "here"})]
    {
        assert!(s.run("cube.catalog", &bad).is_err(), "{bad}");
    }
    assert!(
        s.registry.get("cube.open").is_some_and(|c| c.effects.contains(crate::policy::Effect::Network)),
        "a plugin needs the network permission to open a cube"
    );
    // A Zarr entry reaches as layer.addZarr does (a plugin needs files and network); the catalog
    // itself is built in.
    use crate::cmd::plugins::{Reach, reaches};
    let spec = |id: &str| crate::cmd::all().into_iter().find(|c| c.id == id).unwrap();
    assert_eq!(reaches(&spec("cube.open"), &json!({"id": "bdc-mod13q1-ndvi"})), Some(Reach::Network));
    assert_eq!(reaches(&spec("cube.open"), &json!({"id": "era5-2m-temperature"})), Some(Reach::Files));
    assert_eq!(reaches(&spec("cube.catalog"), &json!({"query": "ndvi"})), None);

    // An entry over a local STAC API: opened, it makes the cube stac.addCube makes from its values.
    let (cog, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let item = |id: &str, date: &str| {
        format!(
            r#"{{"type": "Feature", "id": "{id}", "collection": "cube", "bbox": [10, 45, 11, 46], "geometry": null,
               "properties": {{"datetime": "{date}T00:00:00Z", "bdc:tiles": ["T1"]}},
               "assets": {{"NDVI": {{"href": "{cog}/{id}.tif", "eo:bands": [{{"scale": 0.0001}}]}}}}}}"#
        )
    };
    let features = [item("a1", "2024-01-01"), item("a2", "2024-01-17")].join(",");
    let base = serve_routes(vec![("/v1/search", format!(r#"{{"type": "FeatureCollection", "features": [{features}]}}"#))], 6);
    let mut entry = cubes::find("bdc-mod13q1-ndvi").unwrap();
    entry.url = format!("{base}/v1");
    entry.source = cubes::Source::Stac { collection: "cube".into(), asset: "NDVI".into() };
    entry.bbox = [0.0, 40.0, 20.0, 50.0];
    entry.start = "2023-05-01".into();
    entry.end = Some("2024-12-31".into());
    let area = json!({"bbox": [10, 45, 11, 46]});
    let mut by_entry = Session::new(Project::default());
    let r = crate::cmd::cube_catalog::open_entry(&mut by_entry, &entry, &area).unwrap();
    // By default, the entry's last full year: 2024, as it ended that year.
    assert_eq!(
        (r["cube"].as_str(), r["start"].as_str(), r["end"].as_str()),
        (Some("bdc-mod13q1-ndvi"), Some("2024-01-01"), Some("2024-12-31"))
    );
    assert_eq!((r["dates"].as_u64(), r["layers"].as_u64()), (Some(2), Some(1)), "{r}");
    let mut typed = Session::new(Project::default());
    typed
        .run(
            "stac.addCube",
            &json!({"url": entry.url, "collection": "cube", "asset": "NDVI", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-12-31", "range": [0, 0.9]}),
        )
        .unwrap();
    let urls = |s: &Session| s.map().tiles.iter().map(|t| t.time_urls.clone()).collect::<Vec<_>>();
    assert_eq!(urls(&by_entry), urls(&typed), "the same files, the entry's range in stored values");
    assert!(urls(&by_entry)[0].iter().all(|(_, u)| u.ends_with("#range=0,9000")));
    // As one step: undone, the cube goes.
    by_entry.run("edit.undo", &Value::Null).unwrap();
    assert!(by_entry.map().tiles.is_empty());
    // A range and a name given take the entry's place.
    let r =
        crate::cmd::cube_catalog::open_entry(&mut by_entry, &entry, &json!({"bbox": [10, 45, 11, 46], "range": [0, 0.5], "name": "NDVI"}))
            .unwrap();
    assert_eq!(r["layers"], 1);
    assert!(by_entry.map().tiles[0].time_urls.iter().all(|(_, u)| u.ends_with("#range=0,5000")));
    assert_eq!(by_entry.map().tiles[0].name, "NDVI");
    // Refused before anything is added: an area the entry has no data in, a period outside its
    // dates, one end of the period alone.
    let tiles = by_entry.map().tiles.len();
    for (bad, why) in [
        (json!({"bbox": [100, 0, 101, 1]}), "has data in"),
        (json!({"bbox": [10, 45, 11, 46], "start": "2020-01-01", "end": "2022"}), "runs from 2023-05-01 to 2024-12-31"),
        (json!({"bbox": [10, 45, 11, 46], "start": "2025-01-01", "end": "2025-03-01"}), "runs from"),
        (json!({"bbox": [10, 45, 11, 46], "start": "2024-01-01"}), "together"),
    ] {
        let e = crate::cmd::cube_catalog::open_entry(&mut by_entry, &entry, &bad).unwrap_err();
        assert!(e.contains(why), "{bad}: {e}");
    }
    assert_eq!(by_entry.map().tiles.len(), tiles);

    // A Zarr entry: its variable following the slider over the period, named after the entry.
    let (dir, path) = zarr_store_over_time("catalog");
    let mut zarr = cubes::find("era5-2m-temperature").unwrap();
    zarr.url = path;
    zarr.start = "2001-01-01".into();
    zarr.source = cubes::Source::Zarr { variable: "t".into() };
    let mut z = Session::new(Project::default());
    let r =
        crate::cmd::cube_catalog::open_entry(&mut z, &zarr, &json!({"start": "2001-01-15", "end": "2001-12-31", "bbox": "view"})).unwrap();
    let layer = z.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
    assert_eq!(layer.name, zarr.name);
    assert!(r["note"].as_str().unwrap().contains("read whole"), "{r}");
    assert_eq!(z.run("time.info", &Value::Null).unwrap()["steps"], 2, "the two steps in the period");
    // An end given as a year reaches its last moment, as for a STAC entry: all three steps of 2001.
    let mut year = Session::new(Project::default());
    crate::cmd::cube_catalog::open_entry(&mut year, &zarr, &json!({"start": "2001-01-01", "end": "2001"})).unwrap();
    assert_eq!(year.run("time.info", &Value::Null).unwrap()["steps"], 3);
    // A STAC entry's key is refused first, before a period outside the entry's dates.
    for k in ["range", "maxCloud"] {
        let e = crate::cmd::cube_catalog::open_entry(&mut z, &zarr, &json!({k: 1, "start": "1990", "end": "1990"})).unwrap_err();
        assert!(e.contains("STAC entry's"), "{e}");
    }
    // An area given for a Zarr entry is checked, as for a STAC entry.
    let mut far = zarr.clone();
    far.bbox = [0.0, 0.0, 1.0, 1.0];
    let e = crate::cmd::cube_catalog::open_entry(&mut z, &far, &json!({"bbox": [100, 0, 101, 1]})).unwrap_err();
    assert!(e.contains("has data in"), "{e}");
    let _ = std::fs::remove_dir_all(dir);

    // cube.open by id: an unknown one, none.
    assert!(s.run("cube.open", &json!({"id": "nothing"})).unwrap_err().contains("cube.catalog"));
    assert!(s.run("cube.open", &json!({})).is_err());

    // cube.trend and cube.reduce take an entry by "cube": its values filled in, a cell size or
    // cloud cap given kept; data named alongside it refused.
    let p = json!({"cube": "bdc-s2-16d-ndvi", "cellSize": 100, "start": "2020"});
    let q = crate::cmd::cube_catalog::with_entry(&p).unwrap();
    assert_eq!(
        (q["url"].as_str(), q["collection"].as_str(), q["asset"].as_str(), q["cellSize"].as_f64(), q["start"].as_str(), q.get("cube")),
        (Some("https://data.inpe.br/bdc/stac/v1/"), Some("S2-16D-2"), Some("NDVI"), Some(100.0), Some("2020"), None)
    );
    let p = json!({"cube": "earth-search-s2-nir"});
    let q = crate::cmd::cube_catalog::with_entry(&p).unwrap();
    assert_eq!((q["cellSize"].as_f64(), q["maxCloud"].as_f64()), (Some(10.0), Some(20.0)));
    let p = json!({"cube": "era5-soil-moisture"});
    let q = crate::cmd::cube_catalog::with_entry(&p).unwrap();
    assert_eq!(q["variable"], "volumetric_soil_water_layer_1");
    assert!(q.get("collection").is_none() && q.get("cellSize").is_none());
    for (cmd, extra) in [("cube.trend", json!({})), ("cube.reduce", json!({"stat": "mean"}))] {
        for k in ["layer", "url", "collection"] {
            let mut p = json!({"cube": "bdc-mod13q1-ndvi", k: "x"});
            p.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
            let e = s.run(cmd, &p).unwrap_err();
            assert!(e.contains(&format!("leave out {k}")), "{cmd} {k}: {e}");
        }
        assert!(s.run(cmd, &json!({"cube": "nothing", "stat": "mean"})).unwrap_err().contains("cube.catalog"));
    }
}

/// A search's `"bbox": "view"` is the map's view in any case or spacing, as the trend and the data
/// cube read it; any other text is refused, never read as no area at all.
#[test]
fn a_stac_search_takes_view_in_any_case() {
    let s = world();
    let search = |bbox: &str| crate::cmd::stac::search_params(&s, &json!({"bbox": bbox})).unwrap().bbox;
    assert!(search("view").is_some());
    assert_eq!(search(" VIEW "), search("view"));
    for bad in [json!("nowhere"), json!(7), json!({"w": 1}), json!([10, 45, 11, 46, "extra"]), json!([10, 45, 11, "46"])] {
        let e = crate::cmd::stac::search_params(&s, &json!({"bbox": bad})).unwrap_err();
        assert!(e.contains("bbox is"), "{bad}: {e}");
    }
    assert!(crate::cmd::stac::search_params(&s, &json!({})).unwrap().bbox.is_none(), "no bbox, no area");
}

/// A trend given `"bbox": " VIEW "` searches the map's view: its search request carries the box
/// the trend reads, not no area at all.
#[test]
fn a_stac_trend_searches_the_view_it_reads() {
    use std::io::{Read, Write};
    let mut s = world();
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let api = format!("http://{}/v1", listener.local_addr().unwrap());
    let asked = std::sync::Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
    let seen = asked.clone();
    std::thread::spawn(move || {
        for mut c in listener.incoming().take(4).flatten() {
            let mut buf = [0u8; 8192];
            let n = c.read(&mut buf).unwrap_or(0);
            let line = String::from_utf8_lossy(&buf[..n]).lines().next().unwrap_or("").to_string();
            seen.lock().unwrap().push(line);
            let body = r#"{"type": "FeatureCollection", "features": []}"#;
            let _ = write!(c, "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}", body.len());
        }
    });
    let p = json!({"url": api, "collection": "mod", "asset": "NDVI", "bbox": " VIEW ", "start": "2024", "end": "2024"});
    let e = s.run("cube.trend", &p).unwrap_err();
    assert!(e.contains("no item"), "the search was made and found nothing: {e}");
    let lines = asked.lock().unwrap().clone();
    let search = lines.iter().find(|l| l.contains("/search")).unwrap_or_else(|| panic!("{lines:?}"));
    let query = search.split(['?', ' ']).nth(2).unwrap_or_default();
    let bbox = query.split('&').find_map(|kv| kv.strip_prefix("bbox=")).unwrap_or_else(|| panic!("no bbox in {search}"));
    // The commas as sent, or percent-encoded in either case.
    let asked: Vec<f64> = bbox.replace("%2C", ",").replace("%2c", ",").split(',').map(|v| v.parse().unwrap()).collect();
    let view = crate::cmd::stac::search_params(&s, &json!({"bbox": "view"})).unwrap().bbox.unwrap();
    assert_eq!(asked.len(), 4, "{search}");
    for (a, v) in asked.iter().zip(view) {
        assert!((a - v).abs() < 1e-6, "{search} against the view {view:?}");
    }
}

/// A trend over a STAC collection's band (#579), read in place from its files over an area: each
/// date's values scaled as its own metadata says (here date k's scale is k + 1 ten-thousandths,
/// so every cell grows in a straight line), Sen's slope as worked out by hand; the same outputs
/// read whole or in pieces of rows; a coarser cell size read from the files' overviews; and the
/// requests a trend can't take refused.
#[test]
fn a_trend_over_a_stac_collection() {
    use crate::cmd::stac::PIECE_VALUES;
    let (cog, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let dates = ["2024-01-01", "2024-01-17", "2024-02-02", "2024-02-18", "2024-03-05", "2024-03-21"];
    let features: Vec<String> = dates
        .iter()
        .enumerate()
        .map(|(k, d)| {
            format!(
                r#"{{"type": "Feature", "id": "n{k}", "collection": "mod", "bbox": [10, 45, 11, 46], "geometry": null,
                   "properties": {{"datetime": "{d}T00:00:00Z", "bdc:tiles": ["h13v09"]}},
                   "assets": {{"NDVI": {{"href": "{cog}/n{k}.tif", "eo:bands": [{{"scale": {}, "offset": {}}}]}}}}}}"#,
                (k + 1) as f64 * 1e-4,
                k as f64 * 0.01
            )
        })
        .collect();
    let search = format!(r#"{{"type": "FeatureCollection", "features": [{}]}}"#, features.join(","));
    let base = serve_routes(vec![("/v1/search", search)], 16);
    let api = format!("{base}/v1");
    let params = json!({"url": api, "collection": "mod", "asset": "NDVI", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-03", "test": "original"});
    let mut s = Session::new(Project::default());
    let run = |s: &mut Session, p: &Value| {
        let r = s.run("cube.trend", p).unwrap();
        let ids: Vec<u32> = r["layers"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect();
        let raster = |id: u32| s.map().layer(id).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
        (r["dates"].as_u64(), ids.iter().map(|id| raster(*id)).collect::<Vec<_>>())
    };
    let (n, whole) = run(&mut s, &params);
    assert_eq!(n, Some(6));
    let slope = &whole[0];
    assert_eq!((slope.width, slope.height), (512, 512), "the area on the full images' grid");
    // Pixel (x, y) stores (x + y) % 256; with date k's scale (k + 1) ten-thousandths and offset
    // k hundredths, its value grows by that many ten-thousandths and a hundredth a date, 16 days
    // apart: each file's own scale and offset taken.
    let per_year = |x: usize, y: usize| (((x + y) % 256) as f64 * 1e-4 + 0.01) * 365.2425 / 16.0;
    for (x, y) in [(10, 20), (300, 100), (0, 0), (511, 511)] {
        let got = f64::from(slope.bands[0].data[y * 512 + x]);
        assert!((got - per_year(x, y)).abs() < 1e-4, "({x}, {y}): {got} vs {}", per_year(x, y));
    }
    // A straight rise over six dates is significant, (0, 0)'s too: its stored 0 rises by the offsets.
    assert!(whole[3].bands[0].data[20 * 512 + 10].is_finite() && whole[3].bands[0].data[0].is_finite());
    // An area wider than the file: half a degree more to the west, 256 columns no file covers
    // (NaN), and the file's own beside them, in their places.
    let wider = json!({"url": api, "collection": "mod", "asset": "NDVI", "bbox": [9.5, 45, 11, 46], "start": "2024-01-01", "end": "2024-03", "test": "original"});
    let (_, wide) = run(&mut s, &wider);
    let ws = &wide[0];
    assert_eq!((ws.width, ws.height), (768, 512));
    assert!(ws.bands[0].data[20 * 768 + 255].is_nan() && ws.bands[0].data[0].is_nan());
    for (x, y) in [(10, 20), (511, 511)] {
        let got = f64::from(ws.bands[0].data[y * 768 + 256 + x]);
        assert!((got - per_year(x, y)).abs() < 1e-4, "({x}, {y}): {got} vs {}", per_year(x, y));
    }
    // The parameters read without the network are refused before the search: an API on a
    // closed port, never asked.
    for (bad, said) in [
        (json!({"bbox": [11, 45, 10, 46]}), "bbox is"),
        (json!({"cellSize": 0}), "cellSize is"),
        (json!({"resampling": "bilinear"}), "resampling is"),
    ] {
        let mut q = json!({"url": "http://127.0.0.1:9/v1", "collection": "mod", "asset": "NDVI", "bbox": [10, 45, 11, 46], "start": "2024", "end": "2024"});
        for (k, v) in bad.as_object().unwrap() {
            q[k] = v.clone();
        }
        let e = s.run("cube.trend", &q).unwrap_err();
        assert!(e.contains(said), "{e}");
    }
    // An area no file covers (the items only near it) is refused, not four empty rasters.
    let away = json!({"url": api, "collection": "mod", "asset": "NDVI", "bbox": [20, 45, 21, 46], "start": "2024-01-01", "end": "2024-03"});
    let e = s.run("cube.trend", &away).unwrap_err();
    assert!(e.contains("covers the area"), "{e}");
    // Ten tiles, more than the cover probes reach, none covering it: refused once read, not four
    // empty rasters.
    let many: Vec<String> = (0..10)
        .flat_map(|t| {
            let cog = cog.clone();
            dates.iter().enumerate().map(move |(k, d)| {
                format!(
                    r#"{{"type": "Feature", "id": "t{t}n{k}", "collection": "mod", "bbox": [20, 45, 21, 46], "geometry": null,
                       "properties": {{"datetime": "{d}T00:00:00Z", "bdc:tiles": ["t{t}"]}},
                       "assets": {{"NDVI": {{"href": "{cog}/t{t}n{k}.tif"}}}}}}"#
                )
            })
        })
        .collect();
    let search = format!(r#"{{"type": "FeatureCollection", "features": [{}]}}"#, many.join(","));
    let tiles_api = format!("{}/v1", serve_routes(vec![("/v1/search", search)], 16));
    let e = s.run("cube.trend", &json!({"url": tiles_api, "collection": "mod", "asset": "NDVI", "bbox": [20, 45, 21, 46], "start": "2024-01-01", "end": "2024-03"})).unwrap_err();
    assert!(e.contains("covers the area"), "{e}");
    // Read in two pieces (a quarter of the rows' values each would make four; 256-row tiles make
    // it two), the outputs are the same, cell for cell.
    PIECE_VALUES.with(|v| v.set(Some(512 * 300 * 6)));
    let (_, pieces) = run(&mut s, &params);
    PIECE_VALUES.with(|v| v.set(None));
    for (a, b) in whole.iter().zip(&pieces) {
        assert_eq!((a.width, a.height), (b.width, b.height));
        assert!(a.bands[0].data.iter().zip(&b.bands[0].data).all(|(x, y)| x == y || (x.is_nan() && y.is_nan())), "{}", a.name);
        assert!(crate::cmd::cube::same_grid(&a.transform, &b.transform));
    }
    // A summary of the same cube, whole and in pieces: each cell's mean over the six dates, its
    // stored v times 3.5 ten-thousandths and 0.025, the same cell for cell.
    let mut mean = json!({"url": api, "collection": "mod", "asset": "NDVI", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-03", "stat": "mean"});
    let summary = |s: &mut Session, p: &Value| {
        let r = s.run("cube.reduce", p).unwrap();
        s.map().layer(r["layers"][0].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap()
    };
    // Every key a summary of a collection takes is read, none said to be ignored.
    let mark = s.notice_mark();
    let read_whole = summary(&mut s, &mean);
    let ignored: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).filter(|t| t.contains("ignores")).collect();
    assert!(ignored.is_empty(), "{ignored:?}");
    assert_eq!((read_whole.width, read_whole.height), (512, 512));
    for (x, y) in [(10, 20), (300, 100), (511, 511)] {
        let got = f64::from(read_whole.bands[0].data[y * 512 + x]);
        let want = ((x + y) % 256) as f64 * 3.5e-4 + 0.025;
        assert!((got - want).abs() < 1e-5, "({x}, {y}): {got} vs {want}");
    }
    PIECE_VALUES.with(|v| v.set(Some(512 * 300 * 6)));
    let in_pieces = summary(&mut s, &mean);
    // A year at a time: one year here, the same values.
    mean["by"] = json!("year");
    let by_year = summary(&mut s, &mean);
    PIECE_VALUES.with(|v| v.set(None));
    // A STAC cube's dates come as read, eight at a time, so the totals' order (and an output's last
    // bit) can differ from run to run: the same values, within that.
    for other in [&in_pieces, &by_year] {
        let same = |x: &f32, y: &f32| (x - y).abs() <= 1e-6 || (x.is_nan() && y.is_nan());
        assert!(read_whole.bands[0].data.iter().zip(&other.bands[0].data).all(|(x, y)| same(x, y)));
        assert!(crate::cmd::cube::same_grid(&read_whole.transform, &other.transform));
    }
    // Cancelled, the readers stop early and the run says so, rather than work out a block only
    // partly read.
    let job = crate::cmd::cube::trend_start(&mut s, &params).unwrap();
    let e = job.run(&std::sync::atomic::AtomicBool::new(true), &std::sync::atomic::AtomicUsize::new(0)).unwrap_err();
    assert_eq!(e, "cancelled");
    // A row too wide for a piece is said.
    PIECE_VALUES.with(|v| v.set(Some(100)));
    let e = s.run("cube.trend", &params).unwrap_err();
    PIECE_VALUES.with(|v| v.set(None));
    assert!(e.contains("more than a run's block"), "{e}");
    // A coarser cell size reads the overview nearest it: 256 × 256 cells of 1/256°.
    let mut coarse = params.clone();
    coarse["cellSize"] = json!(0.004);
    let (_, half) = run(&mut s, &coarse);
    assert_eq!((half[0].width, half[0].height), (256, 256));
    // Averaged, each 1/256° cell is the mean of its 2 × 2 full pixels, (2x + 2y + 1) where the
    // overview's (nearest) pixel is 2x + 2y.
    coarse["resampling"] = json!("average");
    let (_, mean) = run(&mut s, &coarse);
    assert_eq!((mean[0].width, mean[0].height), (256, 256));
    for (x, y) in [(5, 7), (30, 40)] {
        let (near, avg) = (f64::from(half[0].bands[0].data[y * 256 + x]), f64::from(mean[0].bands[0].data[y * 256 + x]));
        let (unit, offsets) = (1e-4 * 365.2425 / 16.0, 0.01 * 365.2425 / 16.0);
        assert!((near - (2 * x + 2 * y) as f64 * unit - offsets).abs() < 1e-4, "nearest ({x}, {y}): {near}");
        assert!((avg - (2 * x + 2 * y + 1) as f64 * unit - offsets).abs() < 1e-4, "average ({x}, {y}): {avg}");
    }
    let before = s.map().layers.len();
    for bad in [json!("bilinear"), json!(3)] {
        coarse["resampling"] = bad;
        assert!(s.run("cube.trend", &coarse).unwrap_err().contains("resampling"));
    }
    assert_eq!(s.map().layers.len(), before, "refused, nothing added");
    coarse["resampling"] = Value::Null;
    // The level nearest the size asked: 0.0025 is nearer the full images' 1/512° than 1/256°.
    coarse["cellSize"] = json!(0.0025);
    assert_eq!(run(&mut s, &coarse).1[0].width, 512);
    // What can't be read is refused before anything is added.
    let layers = s.map().layers.len();
    for (bad, said) in [
        (json!({"cellSize": -1}), "cellSize"),
        (json!({"cellSize": "fine"}), "cellSize"),
        (json!({"bbox": [11, 45, 10, 46]}), "bbox"),
        (json!({"asset": null}), "asset"),
        (json!({"bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-01-20"}), "dates"),
    ] {
        let mut p = params.clone();
        for (k, v) in bad.as_object().unwrap() {
            p[k] = v.clone();
        }
        let e = s.run("cube.trend", &p).unwrap_err();
        assert!(e.contains(said), "{bad}: {e}");
    }
    assert_eq!(s.map().layers.len(), layers);
}

/// A plugin's command in the app (`leave_downloads`) runs on the frame: a dated GeoTIFF's first
/// file isn't waited for, and the answer says the map wasn't moved to it.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_plugins_dated_cog_is_added_without_waiting() {
    // A server that takes the connection and never answers: a probe would wait its minute.
    let server = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://{}", server.local_addr().unwrap());
    let mut s = Session::new(Project::default());
    let start = std::time::Instant::now();
    let r = s
        .run_leaving_downloads(
            "layer.addUrl",
            &json!({"url": format!("{base}/{{date:YYYY}}.tif?token=RGSYNTH_dated_cog"), "start": 2020, "end": 2021}),
        )
        .unwrap();
    assert!(start.elapsed() < std::time::Duration::from_secs(10), "waited {:?}", start.elapsed());
    assert_eq!(r["inPlace"], true, "{r}");
    assert!(r["warning"].as_str().is_some_and(|w| w.contains("wasn't moved")), "{r}");
    let tile = &s.map().tiles[r["index"].as_u64().unwrap() as usize];
    assert!(
        tile.url.contains(".tif?token=RGSYNTH_dated_cog") && !tile.url.contains("{date"),
        "the live tile keeps the effective private address"
    );
    let clean = ["warning", "url"].map(|key| r[key].as_str().is_some_and(|text| !text.contains("RGSYNTH_dated_cog")));
    assert_eq!(clean, [true, true], "both public warning and URL must omit credentials");
    drop(server);
}

/// A GeoTIFF whose header was just read is framed even if the cache forgot it since (a login
/// ended), and one that can't be read again says why the map wasn't moved to it: where the
/// session waits for reads in place, the command fails instead (see `add_in_place`).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_probed_cog_is_framed_after_the_cache_forgets_it() {
    use crate::render::rustgis_tiles::{cache, cog};
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(512, 128));
    let url = format!("{base}/scene.tif");
    assert_eq!(cog::probe_blocking(&url), Ok(true));
    cache::forget(&url);
    let mut s = Session::new(Project::default());
    let r = crate::cmd::layer::add_cog(&mut s, &json!({}), &url, true).unwrap();
    assert!(r["bounds"].is_array(), "{r}");
    assert!(r.get("warning").is_none(), "{r}");
    // Nothing answers at this address any more: waited for, the command fails.
    let gone = {
        let server = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        format!("http://{}/gone.tif", server.local_addr().unwrap())
    };
    let e = crate::cmd::layer::add_cog(&mut s, &json!({}), &gone, true).unwrap_err();
    assert!(e.contains("gone.tif"), "{e}");
    // Not waited for (the desktop), the layer is added, its read failing as the map draws, and
    // the answer says why the map wasn't moved to it: a header just read that can't be read
    // again, and a failure recorded and not yet tried again. Another test's login ending forgets
    // the record, so it is made again for each try.
    s.in_place_wait = false;
    let r = crate::cmd::layer::add_cog(&mut s, &json!({}), &gone, true).unwrap();
    let warning = r["warning"].as_str().unwrap_or_default();
    assert!(warning.contains("couldn't be read (") && warning.contains("wasn't moved"), "{r}");
    let said = (0..3).any(|_| {
        let _ = crate::cmd::layer::add_cog(&mut s, &json!({}), &gone, true);
        let r = crate::cmd::layer::add_cog(&mut s, &json!({}), &gone, false).unwrap();
        r["warning"].as_str().is_some_and(|w| w.contains("couldn't be read (") && w.contains("wasn't moved"))
    });
    assert!(said, "a recorded failure went unsaid");
}

/// A cloud-optimised GeoTIFF by its address is read in place: its header, then only the tiles a
/// map tile needs, by range; a GeoTIFF in strips is downloaded whole as a raster layer.
#[test]
fn cloud_optimised_geotiffs_are_read_in_place() {
    use crate::render::rustgis_tiles::cache::{self, Payload, State, Want};
    let file = rustgis_data::raster::cog::example(2048, 256);
    let total = file.len();
    let (base, sent) = serve_ranges(file);
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif")})).unwrap();
    assert_eq!(r["inPlace"], true, "{r}");
    // A raster layer like a file's: it holds an overview (1024 pixels a side of the 2048), whose
    // statistics its symbology reads.
    let l = s.map().layers.iter().find(|l| l.name == "scene").unwrap().clone();
    let rl = l.raster.as_ref().unwrap();
    assert!(rl.in_place && rl.path.as_deref() == Some(&*format!("{base}/scene.tif")));
    let d = rl.data.as_ref().unwrap();
    assert_eq!((d.width, d.overview), (1024, Some((2048, 2048))));
    assert!(d.bands[0].stats.count > 0 && d.bands[0].stats.max > 200.0);
    // Framed on the file: 10–11° E, 45–46° N.
    let b = r["bounds"].as_array().unwrap().iter().map(|v| v.as_f64().unwrap()).collect::<Vec<_>>();
    assert!((b[0] - 10.0).abs() < 1e-6 && (b[3] - 46.0).abs() < 1e-6, "{b:?}");
    // Drawn zoomed in past the overview, the part in view is read at full resolution: a few of
    // its tiles, not the whole file. Pixel (x, y) of the full image is (x + y) % 256: neighbouring
    // screen pixels differ by one, finer than the overview's steps of two.
    let before = sent.load(std::sync::atomic::Ordering::Relaxed);
    let c = rustgis_geom::lonlat_to_merc(rustgis_geom::Coord::new(10.5, 45.5));
    s.map_mut().camera.center = c;
    // A metre on the ground is about 1.43 Web Mercator units here: a third of a full pixel's.
    s.map_mut().camera.res = 25.0;
    s.view_size = (64.0, 64.0);
    let png = std::env::temp_dir().join(format!("rustgis-cog-in-place-{}.png", std::process::id()));
    s.run("share.exportMap", &json!({"path": png.to_string_lossy(), "width": 64, "height": 64})).unwrap();
    let img = image::open(&png).unwrap().to_rgba8();
    let _ = std::fs::remove_file(&png);
    let row: Vec<u8> = (0..64).map(|x| img.get_pixel(x, 32)[0]).collect();
    assert!(row.iter().any(|v| *v > 0), "drawn: {row:?}");
    assert!(row.windows(2).any(|w| w[1].abs_diff(w[0]) == 1), "full resolution (steps of one), not the overview's (of two): {row:?}");
    let window = sent.load(std::sync::atomic::Ordering::Relaxed) - before;
    assert!(window > 0 && window < total / 8, "{window} of {total} bytes read for the view");
    // A map tile inside it (zoom 9) is drawn from a few of its tiles, not the whole file (a dated
    // series of GeoTIFFs is drawn so, as a tile layer).
    let (z, lon, lat) = (9u32, 10.5f64, 45.5f64);
    let n = f64::from(1u32 << z);
    let x = ((lon + 180.0) / 360.0 * n) as u32;
    let y = ((1.0 - lat.to_radians().tan().asinh() / std::f64::consts::PI) / 2.0 * n) as u32;
    let tile = format!("cog:{z}/{x}/{y}@{base}/scene.tif");
    let before = sent.load(std::sync::atomic::Ordering::Relaxed);
    let mut got = None;
    for _ in 0..200 {
        match cache::get(&tile, Want::Image) {
            State::Ready(p) => {
                got = Some(p);
                break;
            }
            State::Failed(e) => panic!("{e}"),
            State::Pending => cache::wait(std::time::Duration::from_millis(50)),
        }
    }
    let Some(p) = got else { panic!("the tile never came") };
    let Payload::Image(pm) = &*p else { panic!("not a picture") };
    assert_eq!((pm.width(), pm.height()), (256, 256));
    assert!(pm.pixels().iter().any(|px| px.alpha() == 255));
    let read = sent.load(std::sync::atomic::Ordering::Relaxed) - before;
    assert!(read < total / 4, "{read} of {total} bytes read");
    // A tile outside it is empty.
    assert!(matches!(cache::get(&format!("cog:9/0/0@{base}/scene.tif"), Want::Image), State::Pending | State::Ready(_)));
    // The project keeps the address; asked to, the file is downloaded whole instead.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.contains("\"in_place\":true") && text.contains("scene.tif"));
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif"), "whole": true, "name": "Whole"})).unwrap();
    assert!(r.get("inPlace").is_none(), "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    assert!(s.map().layer(id).is_some_and(|l| l.is_raster()), "{r}");
    // Opened as a scan, it is downloaded whole and has no coordinates, never read in place.
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif"), "as": "scan", "name": "Scan"})).unwrap();
    assert!(r.get("inPlace").is_none(), "{r}");
    assert_eq!(r["georeferenced"], false, "{r}");
    // A dated address is read in place with its coordinates, so it can't be a scan.
    let e = s.run("layer.addUrl", &json!({"url": format!("{base}/{{date:YYYY}}.tif"), "as": "scan"})).unwrap_err();
    assert!(e.contains("scan"), "{e}");
    // Anything else in "as" is refused, not ignored, and tiles can't be a scan.
    for (url, as_) in [("scene.tif", json!("pdf")), ("scene.tif", json!(3)), ("a.pmtiles", json!("scan")), ("a.fgb", json!("scan"))] {
        let e = s.run("layer.addUrl", &json!({"url": format!("{base}/{url}"), "as": as_})).unwrap_err();
        assert!(e.contains("\"as\"") || e.contains("scan"), "{url}: {e}");
    }
    // A GeoTIFF in strips isn't cloud-optimised: downloaded whole, a raster layer.
    let r = rustgis_data::raster::Raster::new(
        "strips",
        8,
        8,
        vec![vec![3.0; 64]],
        rustgis_data::raster::GeoTransform { origin_x: 5.0, origin_y: 50.0, pixel_width: 0.1, pixel_height: -0.1 },
        rustgis_data::raster::Crs::LonLat,
        None,
        rustgis_data::raster::ColorHint::Gray,
        "Float32",
    )
    .unwrap();
    let (base, _) = serve_ranges(rustgis_data::raster::geotiff::write(&r, 0).unwrap());
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/strips.tif")})).unwrap();
    assert!(r.get("inPlace").is_none(), "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    assert!(s.map().layer(id).is_some_and(|l| l.is_raster()), "{r}");
    // So is one at an address without a file name, its first bytes saying GeoTIFF.
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/raster/geotiff?id=1")})).unwrap();
    assert!(r.get("inPlace").is_none(), "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    assert!(s.map().layer(id).is_some_and(|l| l.is_raster()), "{r}");
}

/// A cloud-optimised GeoTIFF from an API whose address names no file (Vantor's
/// `…/ortho-with-overviews/geotiff?…`) is read in place, as one named `.tif` is, not downloaded
/// whole; an address the app has probed (`"cog"`) is read in place without the name either.
#[test]
fn unnamed_cloud_optimised_geotiffs_are_read_in_place() {
    use crate::cmd::layer::is_unnamed_url;
    assert!(is_unnamed_url(
        "https://api.vantor.com/analytics/v1/raster/ortho-with-overviews/geotiff?function=pansharp_ortho&p=crs%3D%22EPSG%3A3857%22"
    ));
    assert!(is_unnamed_url("https://x.org/api/tile/"));
    for named in
        ["https://x.org/a/scene.tif?sig=1", "https://x.org/a.b/data.geojson", "https://x.org", "https://x.org/", "/tmp/geotiff", "geotiff"]
    {
        assert!(!is_unnamed_url(named), "{named}");
    }
    let file = rustgis_data::raster::cog::example(2048, 256);
    let total = file.len();
    let (base, sent) = serve_ranges(file);
    let url =
        format!("{base}/analytics/v1/raster/ortho-with-overviews/geotiff?function=pansharp_ortho&p=bands%3D%22red%2Cgreen%2Cblue%22&key=k");
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addUrl", &json!({"url": url, "name": "Ortho"})).unwrap();
    assert_eq!(r["inPlace"], true, "{r}");
    let l = s.map().layers.iter().find(|l| l.name == "Ortho").unwrap();
    let rl = l.raster.as_ref().unwrap();
    assert!(rl.in_place && rl.path.as_deref() == Some(url.as_str()), "{:?}", rl.path);
    let read = sent.load(std::sync::atomic::Ordering::Relaxed);
    assert!(read < total / 4, "{read} of {total} bytes read: only the header, not the whole file");
    let r = s.run("layer.addUrl", &json!({"url": url, "name": "Probed", "cog": true})).unwrap();
    assert_eq!(r["inPlace"], true, "{r}");
    // `"cog"` holds whatever the name says: a GeoTIFF at a FlatGeobuf's name is read as one,
    // where without it the FlatGeobuf reader refuses it.
    let fgb = format!("{base}/scene.fgb");
    assert!(s.run("layer.addUrl", &json!({"url": fgb, "name": "AsFgb"})).is_err());
    let r = s.run("layer.addUrl", &json!({"url": fgb, "name": "Flagged", "cog": true})).unwrap();
    assert_eq!(r["inPlace"], true, "{r}");
    // Asked to, it is downloaded whole, named by its contents.
    let r = s.run("layer.addUrl", &json!({"url": url, "whole": true, "name": "Whole"})).unwrap();
    assert!(r.get("inPlace").is_none(), "{r}");
    // Anything else at such an address is downloaded as before, and said not to be data.
    let (text, _) = serve_file(b"Unauthorized".to_vec(), false);
    let e = s.run("layer.addUrl", &json!({"url": format!("{text}/api/geotiff?key=bad")})).unwrap_err();
    assert!(e.contains("not a data format"), "{e}");
}

/// A cloud-optimised GeoTIFF read in place is a raster layer like a file's: its first look is what
/// its PhotometricInterpretation says (RGB in colour, a palette by its table, grey (MinIsBlack, as
/// most remote sensing images are) as its first band, but three grey bands as red, green and
/// blue), every band there for the raster commands and the Symbology pane to combine and stretch.
#[test]
fn cog_layers_are_rasters_styled_as_their_photometric_interpretation_says() {
    use rustgis_data::raster::cog::{Example, example_with};
    use rustgis_map::raster::{RasterRenderer, Stretch};
    let e = Example { size: 512, tile: 256, ..Example::default() };
    let rgb = RasterRenderer::Rgb { red: 0, green: 1, blue: 2 };
    let cases: [(&str, Example, usize, Option<RasterRenderer>); 7] = [
        ("Pan", Example { bands: 1, ..e }, 1, None),
        ("PanAlpha", Example { bands: 2, alpha: true, ..e }, 2, None),
        ("Grey3", Example { bands: 3, ..e }, 3, Some(rgb.clone())),
        ("Multispectral", Example { bands: 8, ..e }, 8, None),
        ("Rgb", Example { bands: 3, photometric: 2, ..e }, 3, Some(rgb.clone())),
        ("Rgbn", Example { bands: 4, photometric: 2, ..e }, 4, Some(rgb.clone())),
        ("RgbaNir", Example { bands: 5, photometric: 2, alpha: true, planar: true, ..e }, 5, Some(rgb.clone())),
    ];
    let mut s = Session::new(Project::default());
    for (name, ex, bands, renderer) in cases {
        let (base, _) = serve_ranges(example_with(&ex));
        let r = s.run("layer.addUrl", &json!({"url": format!("{base}/{name}.tif"), "name": name})).unwrap();
        assert_eq!(r["inPlace"], true, "{name}: {r}");
        let id = r["layer"].as_u64().unwrap() as u32;
        let rl = s.map().layer(id).and_then(|l| l.raster.clone()).unwrap();
        assert!(rl.in_place, "{name}");
        assert_eq!(rl.data.as_ref().map(|d| d.band_count()), Some(bands), "{name}");
        match renderer {
            Some(want) => assert_eq!(rl.style.renderer, want, "{name}"),
            None => assert!(matches!(rl.style.renderer, RasterRenderer::Stretch { band: 0, .. }), "{name}: {:?}", rl.style.renderer),
        }
        // The raster commands combine and stretch its bands, as a file's.
        if bands >= 3 {
            let last = bands as u64;
            s.run("raster.bands", &json!({"layer": name, "red": last, "green": 2, "blue": 1})).unwrap();
            let st = s.map().layer(id).and_then(|l| l.raster.as_ref()).map(|r| r.style.clone()).unwrap();
            assert_eq!(st.renderer, RasterRenderer::Rgb { red: bands - 1, green: 1, blue: 0 }, "{name}");
        }
        s.run("raster.stretch", &json!({"layer": name, "type": "standardDeviation", "n": 2})).unwrap();
        let st = s.map().layer(id).and_then(|l| l.raster.as_ref()).map(|r| r.style.clone()).unwrap();
        assert_eq!(st.stretch, Stretch::StandardDeviation { n: 2.0 }, "{name}");
    }
    assert!(s.map().tiles.is_empty(), "no tile layers");
    // A palette image, by its table.
    let (base, _) = serve_ranges(example_with(&Example { classes: true, ..e }));
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/classes.tif")})).unwrap();
    let rl = s.map().layer(r["layer"].as_u64().unwrap() as u32).and_then(|l| l.raster.clone()).unwrap();
    assert_eq!(rl.style.renderer, RasterRenderer::Colormap);
    // Saved and opened again, it is read in place again, its style kept.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let ms = t.map().layers.iter().find(|l| l.name == "Multispectral").and_then(|l| l.raster.clone()).unwrap();
    assert!(ms.in_place && ms.data.is_some() && ms.style.stretch == Stretch::StandardDeviation { n: 2.0 });
}

/// A view of a GeoTIFF read in place zoomed in past its overview shows the level zoomed from while
/// its own tiles are on their way: no holes, no blocks of the overview, then its own pixels.
#[test]
fn cog_windows_stand_in_the_level_kept_until_their_tiles_arrive() {
    use crate::render::rustgis_tiles::cog::raster::window;
    use std::sync::atomic::{AtomicBool, Ordering};
    let gate = std::sync::Arc::new(AtomicBool::new(true));
    let (base, _) = serve_gated(rustgis_data::raster::cog::example(2048, 256), true, Some(gate.clone()));
    let url = format!("{base}/scene.tif");
    let mut s = Session::new(Project::default());
    // Its overview: level 1 (1024 pixels a side), whose tiles are kept.
    s.run("layer.addUrl", &json!({"url": url})).unwrap();
    // Level 0's tiles held back: a window of it is whole, from level 1, and still to come.
    gate.store(false, Ordering::Relaxed);
    let (cols, rows) = ((1000, 1100), (900, 960));
    let gray = rustgis_data::raster::ColorHint::Gray;
    let w = window(&url, 0, cols, rows, &[0], gray.clone()).unwrap();
    let part = w.raster.unwrap();
    assert!(w.pending);
    let v = |r: &rustgis_data::raster::Raster, x: u32, y: u32| r.bands[0].data[((y - rows.0) * (cols.1 - cols.0) + (x - cols.0)) as usize];
    assert!(part.bands[0].data.iter().all(|v| v.is_finite()), "no holes");
    // Level 1's pixel under (1001, 901) is (500, 450): full pixel (1000, 900), (1000 + 900) % 256.
    assert_eq!(v(&part, 1001, 901), ((1000 + 900) % 256) as f32);
    // Its own tiles arrive: its own pixels, (x + y) % 256.
    gate.store(true, Ordering::Relaxed);
    let mut done = None;
    for _ in 0..200 {
        let w = window(&url, 0, cols, rows, &[0], gray.clone()).unwrap();
        if !w.pending {
            done = w.raster;
            break;
        }
        crate::render::rustgis_tiles::cache::wait(std::time::Duration::from_millis(50));
    }
    let part = done.expect("its tiles never came");
    assert_eq!(v(&part, 1001, 901), ((1001 + 901) % 256) as f32);
}

/// A tile a sparse file leaves out (GDAL's: no bytes) is empty, not waited for: a window over it
/// is whole at once and asks for nothing more, and an export of the view over it is written rather
/// than refused after waiting for the tile.
#[test]
fn a_tile_a_sparse_file_leaves_out_is_empty_not_waited_for() {
    use crate::render::rustgis_tiles::cog::raster::window;
    use rustgis_data::raster::cog::{Example, example_with};
    use std::sync::atomic::Ordering;
    let (base, sent) = serve_ranges(example_with(&Example { size: 2048, tile: 256, sparse: true, ..Example::default() }));
    let url = format!("{base}/scene.tif");
    let mut s = Session::new(Project::default());
    // Its overview is level 1 (1024 pixels a side); level 0's first tile has no bytes.
    let r = s.run("layer.addUrl", &json!({"url": url.clone(), "name": "Scene"})).unwrap();
    assert_eq!(r["width"], 1024, "{r}");
    let before = sent.load(Ordering::Relaxed);
    let gray = rustgis_data::raster::ColorHint::Gray;
    for _ in 0..2 {
        let w = window(&url, 0, (0, 64), (0, 64), &[0], gray.clone()).unwrap();
        assert!(!w.pending, "an empty tile isn't waited for");
        assert!(w.raster.unwrap().bands[0].data.iter().all(|v| v.is_nan()), "empty");
    }
    assert_eq!(sent.load(Ordering::Relaxed), before, "nothing is fetched for it");
    // The view over it (the image's north-west corner), zoomed in past the overview: written.
    s.view_size = (64.0, 64.0);
    s.zoom_to(&rustgis_geom::Extent::new(10.02, 45.92, 10.08, 45.98));
    s.map_mut().camera.res = 12.0;
    let png = std::env::temp_dir().join(format!("rustgis-sparse-{}.png", std::process::id()));
    s.run("share.exportMap", &json!({"path": png.to_string_lossy(), "width": 64, "height": 64})).unwrap();
    assert!(png.exists());
    let _ = std::fs::remove_file(png);
}

/// A GeoTIFF whose server refuses its header with a 429 or 503 and a `Retry-After` fails to be
/// added, saying when to ask again, and is read again on a draw once the wait is over. (That it
/// isn't asked for before then, and that the map is asked to draw again by then, so the layer
/// doesn't stay failed until something else draws it: `rustgis_tiles::cog`'s
/// `a_header_refused_with_retry_after_has_the_map_drawn_again_then`, where the gate's state and
/// the alarm can be read; here another test may empty the cache meanwhile.)
#[test]
fn a_header_refused_with_retry_after_is_read_again_when_it_says() {
    use crate::render::rustgis_tiles::{cache, cog};
    use std::sync::atomic::Ordering;
    use std::time::Duration;
    // Refused once (busy: ask again in a second), answered after.
    let (base, sent) = serve_refusing_first(rustgis_data::raster::cog::example(512, 256), 1);
    let url = format!("{base}/scene.tif");
    let mut s = Session::new(Project::default());
    let e = s.run("layer.addUrl", &json!({"url": url.clone(), "name": "Scene"})).unwrap_err();
    assert!(e.contains("retry after 1 s"), "{e}");
    assert_eq!(sent.load(Ordering::Relaxed), 0, "refused: nothing sent");
    // Its wait over, it is read again on a draw, and answered.
    let start = std::time::Instant::now();
    let mut read = None;
    while read.is_none() && start.elapsed() < Duration::from_secs(10) {
        let _ = cache::generation();
        if let Ok(Some(info)) = cog::info(&url) {
            read = Some(info);
        }
        cache::wait(Duration::from_millis(50));
    }
    let width = read.as_ref().and_then(|i| i.layout.levels.first()).map(|l| l.width);
    assert_eq!(width, Some(512), "not read again once its wait was over");
    assert!(sent.load(Ordering::Relaxed) > 0);
}

/// A GeoTIFF's address look (`#bands=…&range=…`) is its layer's once its pixels land, read later
/// (as the browser and an import read them) as when read at once; a palette image stretched by a
/// range is drawn in grey, as its tile layer was, and without a look in its colours.
#[test]
fn an_address_look_holds_when_the_pixels_land_later() {
    use rustgis_data::raster::cog::{Example, example_with};
    use rustgis_map::raster::{AddressLook, RasterLayer, RasterRenderer, Stretch, read_together};
    // A session installs the reader.
    let _s = Session::new(Project::default());
    let (base, _) = serve_ranges(example_with(&Example { size: 512, tile: 256, bands: 8, ..Example::default() }));
    let look = AddressLook { bands: vec![4, 2, 1], range: Some((10.0, 200.0)) };
    let mut rl = RasterLayer::unread_in_place(format!("{base}/scene.tif")).with_look(look);
    assert!(rl.data.is_none());
    assert!(read_together(&mut [&mut rl], true).is_empty());
    assert!(rl.data.is_some());
    assert_eq!(rl.style.renderer, RasterRenderer::Rgb { red: 4, green: 2, blue: 1 });
    assert_eq!(rl.style.stretch, Stretch::custom(10.0, 200.0));
    let (classes, _) = serve_ranges(example_with(&Example { size: 512, tile: 256, classes: true, ..Example::default() }));
    let mut stretched =
        RasterLayer::unread_in_place(format!("{classes}/classes.tif")).with_look(AddressLook { bands: vec![], range: Some((0.0, 100.0)) });
    let mut own = RasterLayer::unread_in_place(format!("{classes}/classes.tif"));
    assert!(read_together(&mut [&mut stretched, &mut own], true).is_empty());
    assert!(matches!(stretched.style.renderer, RasterRenderer::Stretch { band: 0, .. }), "{:?}", stretched.style.renderer);
    assert_eq!(own.style.renderer, RasterRenderer::Colormap);
    // Saved before its pixels landed (the browser, a read that failed), a layer opens in its look,
    // or its own one, still.
    let mut s = Session::new(Project::default());
    let look = AddressLook { bands: vec![4, 2, 1], range: Some((10.0, 200.0)) };
    s.map_mut().add_raster("Scene".to_string(), RasterLayer::unread_in_place(format!("{base}/scene.tif")).with_look(look));
    s.map_mut().add_raster("Classes".to_string(), RasterLayer::unread_in_place(format!("{classes}/classes.tif")));
    let text = serde_json::to_string(&s.project).unwrap();
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text})).unwrap();
    let style =
        |name: &str| s.map().layers.iter().find(|l| l.name == name).and_then(|l| l.raster.as_ref()).map(|r| r.style.clone()).unwrap();
    assert_eq!(style("Scene").renderer, RasterRenderer::Rgb { red: 4, green: 2, blue: 1 });
    assert_eq!(style("Scene").stretch, Stretch::custom(10.0, 200.0));
    assert_eq!(style("Classes").renderer, RasterRenderer::Colormap);
}

/// An in-place address a project keeps is checked as a tile layer's is before anything is asked
/// for: a hand-edited one that isn't http(s) or s3 is refused, and said, on opening and on adding.
#[test]
fn an_unchecked_in_place_address_is_refused() {
    use rustgis_map::raster::RasterLayer;
    let bad = "ftp://127.0.0.1/scene.tif";
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("Odd".to_string(), RasterLayer::unread_in_place(bad));
    let text = serde_json::to_string(&s.project).unwrap();
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text})).unwrap();
    let rl = s.map().layers.iter().find(|l| l.name == "Odd").and_then(|l| l.raster.as_ref()).unwrap();
    assert!(rl.data.is_none() && rl.error.as_deref().is_some_and(|e| e.contains("tile addresses start with")), "{:?}", rl.error);
    assert_eq!(s.notices.iter().filter(|n| n.error && n.text.contains("Odd: couldn't be read in place")).count(), 1);
    // Added directly (the browser's path), refused before the reader is asked.
    let added = RasterLayer::opening_in_place(bad);
    assert!(added.error.is_some() && added.data.is_none());
}

/// A PNG export of a raster read in place whose image can't be read (its tiles, past the overview
/// it holds) is refused, not written from the overview.
#[test]
fn a_png_export_of_an_unreadable_in_place_layer_is_refused() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    let mut overview = Raster::new(
        "gone",
        4,
        4,
        vec![(0..16).map(|v| v as f32).collect()],
        GeoTransform { origin_x: -180.0, origin_y: 80.0, pixel_width: 90.0, pixel_height: -40.0 },
        Crs::LonLat,
        None,
        ColorHint::Gray,
        "Float32",
    )
    .unwrap();
    overview.overview = Some((4096, 4096));
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("Gone".to_string(), rustgis_map::raster::RasterLayer::in_place(overview, "http://127.0.0.1:9/gone.tif"));
    // Zoomed in far past the overview: the image's tiles are needed, and can't be read.
    s.map_mut().camera.center = rustgis_geom::Coord::new(0.0, 0.0);
    s.map_mut().camera.res = 25.0;
    s.view_size = (64.0, 64.0);
    let png = std::env::temp_dir().join(format!("rustgis-in-place-refused-{}.png", std::process::id()));
    let e = s.run("share.exportMap", &json!({"path": png.to_string_lossy(), "width": 64, "height": 64})).unwrap_err();
    assert!(e.contains("isn't written") || e.contains("still on their way"), "{e}");
    assert!(!png.exists());
}

/// A turned layer read in place is drawn from its overview: zoomed in past it, an export is
/// refused rather than written from the overview; zoomed out, it is written.
#[test]
fn a_turned_in_place_layer_is_not_exported_past_its_overview() {
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(2048, 256));
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif"), "name": "Scene"})).unwrap();
    assert_eq!(r["width"], 1024, "{r}");
    let id = s.map().layer_by_name("Scene").unwrap().id;
    s.map_mut().layer_mut(id).and_then(|l| l.raster.as_mut()).unwrap().style.rotation = 15.0;
    let png = std::env::temp_dir().join(format!("rustgis-turned-{}.png", std::process::id()));
    // Zoomed in past the overview (its pixels are about 50 m): refused.
    s.map_mut().camera.res = 12.0;
    s.view_size = (64.0, 64.0);
    let e = s.run("share.exportMap", &json!({"path": png.to_string_lossy(), "width": 64, "height": 64})).unwrap_err();
    assert!(e.contains("turned") && e.contains("isn't written"), "{e}");
    // Zoomed out to the overview's resolution and beyond: written.
    s.map_mut().camera.res = 200.0;
    s.run("share.exportMap", &json!({"path": png.to_string_lossy(), "width": 64, "height": 64})).unwrap();
    assert!(png.exists());
}

/// An address look naming bands the file hasn't (`#bands=9,8,7` on a 3-band file), or two bands
/// (`#bands=1,2`, which no raster look draws), is said, and the layer draws in its own look; its
/// range is kept.
#[test]
fn a_look_naming_bands_the_file_hasnt_is_said() {
    use rustgis_data::raster::cog::{Example, example_with};
    use rustgis_map::raster::{RasterRenderer, Stretch};
    let (base, _) = serve_ranges(example_with(&Example { size: 512, tile: 256, bands: 3, ..Example::default() }));
    let mut s = Session::new(Project::default());
    s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif#bands=9,8,7&range=10,200"), "name": "Scene"})).unwrap();
    let said = |s: &Session| s.notices.iter().filter(|n| n.text.contains("asks for band(s) 9, 8, 7")).count();
    assert_eq!(said(&s), 1, "{:?}", s.notices);
    let rl = s.map().layer_by_name("Scene").and_then(|l| l.raster.as_ref()).unwrap();
    assert_eq!(rl.style.renderer, RasterRenderer::Rgb { red: 0, green: 1, blue: 2 }, "the file's own look: three grey bands as RGB");
    assert_eq!(rl.style.stretch, Stretch::custom(10.0, 200.0));
    s.run("map.zoomIn", &Value::Null).unwrap();
    assert_eq!(said(&s), 1);
    // Two bands: neither grey nor RGB, said as such.
    s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif#bands=1,2&range=10,200"), "name": "Pair"})).unwrap();
    assert_eq!(s.notices.iter().filter(|n| n.text.contains("Pair") && n.text.contains("asks for 2 bands")).count(), 1, "{:?}", s.notices);
    let rl = s.map().layer_by_name("Pair").and_then(|l| l.raster.as_ref()).unwrap();
    assert_eq!(rl.style.renderer, RasterRenderer::Rgb { red: 0, green: 1, blue: 2 });
    assert_eq!(rl.style.stretch, Stretch::custom(10.0, 200.0));
    // A palette image: in grey with the range, as its tile layer draws one whose address names
    // bands (its colours are of one band alone), not in its colours without the range.
    let (classes, _) = serve_ranges(example_with(&Example { size: 512, tile: 256, classes: true, ..Example::default() }));
    s.run("layer.addUrl", &json!({"url": format!("{classes}/classes.tif#bands=9,8,7&range=10,200"), "name": "Classes"})).unwrap();
    let said = s
        .notices
        .iter()
        .filter(|n| n.text.contains("Classes") && n.text.contains("asks for band(s) 9, 8, 7") && n.text.contains("drawn in grey"));
    assert_eq!(said.count(), 1, "{:?}", s.notices);
    let rl = s.map().layer_by_name("Classes").and_then(|l| l.raster.as_ref()).unwrap();
    assert!(matches!(rl.style.renderer, RasterRenderer::Stretch { band: 0, .. }), "{:?}", rl.style.renderer);
    assert_eq!(rl.style.stretch, Stretch::custom(10.0, 200.0));
}

/// A file without overviews whose only image has more tiles than the fetch queue holds (small
/// tiles) is read in place all the same: its overview is asked for a batch at a time, and a tile
/// the queue dropped is asked for again, so the layer lands rather than failing with "dropped".
#[test]
fn an_overview_of_more_tiles_than_the_fetch_queue_holds_lands() {
    // This fixture fills the shared native queue; other tests must keep their own requests.
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::an_overview_of_more_tiles_than_the_fetch_queue_holds_lands") {
        return;
    }
    use rustgis_data::raster::cog::{Example, example_with};
    let (base, _) = serve_ranges(example_with(&Example { size: 1024, tile: 32, no_overviews: true, ..Example::default() }));
    let mut s = Session::new(Project::default());
    s.run("layer.addUrl", &json!({"url": format!("{base}/flat.tif"), "name": "Flat"})).unwrap();
    let rl = s.map().layer_by_name("Flat").and_then(|l| l.raster.as_ref()).unwrap();
    assert!(rl.in_place);
    let d = rl.data.as_ref().unwrap();
    assert_eq!((d.width, d.height), (1024, 1024));
    // Every tile, not a stand-in: pixel (x, y) of band 0 is (x + y) % 256.
    let at = |x: u32, y: u32| d.bands[0].data[(y * d.width + x) as usize];
    assert_eq!((at(0, 1), at(1023, 1023), at(500, 700)), (1.0, 254.0, 176.0));
}

/// A window over more tiles than the fetch queue holds (small tiles) asks for them a batch at a
/// time, the next as the map draws again, rather than all at once (which would push its own first
/// requests out of the queue, to ask for them all again at the next draw), and is pending until
/// the last lands. The batch bound and final pixels are checked; the total fetch count may vary
/// because dropped requests can be tried again.
#[test]
fn a_window_of_more_tiles_than_the_fetch_queue_holds_asks_for_them_in_batches() {
    // This fixture fills the shared native queue; other tests must keep their own requests.
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::a_window_of_more_tiles_than_the_fetch_queue_holds_asks_for_them_in_batches") {
        return;
    }
    use crate::render::rustgis_tiles::{cache, cog};
    use rustgis_data::raster::ColorHint;
    use rustgis_data::raster::cog::{Example, example_with};
    use std::time::Duration;
    let _s = Session::new(Project::default());
    let (base, _) = serve_ranges(example_with(&Example { size: 1024, tile: 32, no_overviews: true, ..Example::default() }));
    let url = format!("{base}/flat.tif");
    // The header first; then the window asks for its first batch.
    let start = std::time::Instant::now();
    let mut w = cog::raster::window(&url, 0, (0, 1024), (0, 1024), &[0], ColorHint::Gray).unwrap();
    while w.raster.is_none() && start.elapsed() < Duration::from_secs(20) {
        cache::wait(Duration::from_millis(20));
        w = cog::raster::window(&url, 0, (0, 1024), (0, 1024), &[0], ColorHint::Gray).unwrap();
    }
    assert!(w.raster.is_some() && w.pending && !w.failed);
    let asked = cog::raster::asked(&url, 0);
    assert!(asked <= 256, "{asked} asked for at once");
    // Drawn again as tiles land, the window asks for the rest, and is whole in the end.
    while w.pending && start.elapsed() < Duration::from_secs(60) {
        cache::wait(Duration::from_millis(20));
        w = cog::raster::window(&url, 0, (0, 1024), (0, 1024), &[0], ColorHint::Gray).unwrap();
    }
    assert!(!w.pending && !w.failed, "still pending after {:?}", start.elapsed());
    let r = w.raster.unwrap();
    let at = |x: u32, y: u32| r.bands[0].data[(y * r.width + x) as usize];
    assert_eq!((at(0, 1), at(1023, 1023), at(500, 700)), (1.0, 254.0, 176.0));
    assert!(r.bands[0].data.iter().all(|v| v.is_finite()), "a gap");
}

/// A palette image's overview without a colour table under a grey full image is read as the full
/// image is, in grey, and nothing is said: a file is what its full image says (as `main` reads a
/// grey full image with a stray colour table as grey), a window over it is read the same way, and
/// the overview's own say is the one thing the reader doesn't take over the full image's.
#[test]
fn a_palette_overview_under_a_grey_full_image_is_read_grey_as_the_full_image_is() {
    use rustgis_data::raster::cog::{Example, example_with};
    use rustgis_map::raster::RasterRenderer;
    // 4096 × 4096 in 256 px tiles: the overview held is the 1024 × 1024 one (a palette image
    // without a table), not the full image (grey, 16 M samples).
    let file = example_with(&Example { size: 4096, tile: 256, classes: true, stray: true, no_table: true, ..Example::default() });
    let (base, _) = serve_ranges(file);
    let mut s = Session::new(Project::default());
    s.run("layer.addUrl", &json!({"url": format!("{base}/stray.tif"), "name": "Stray"})).unwrap();
    let rl = s.map().layer_by_name("Stray").and_then(|l| l.raster.as_ref()).unwrap();
    let d = rl.data.as_ref().unwrap();
    assert_eq!((d.width, d.overview), (1024, Some((4096, 4096))), "the overview held");
    assert!(matches!(rl.style.renderer, RasterRenderer::Stretch { band: 0, .. }), "{:?}", rl.style.renderer);
    assert!(!s.notices.iter().any(|n| n.text.contains("colour table")), "{:?}", s.notices);
}

/// A layer read in place whose overview couldn't be read (its server refused the file's header,
/// saying when to ask again) is read again once its wait is over, as the app draws, and lands then:
/// not before, and failing was said once.
#[test]
fn an_in_place_layers_failed_overview_is_read_again_when_its_wait_is_over() {
    use rustgis_map::raster::RasterLayer;
    use std::sync::atomic::Ordering;
    use std::time::Duration;
    let (base, sent) = serve_refusing_first(rustgis_data::raster::cog::example(512, 256), 2);
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("Scene".to_string(), RasterLayer::unread_in_place(format!("{base}/scene.tif")));
    let text = serde_json::to_string(&s.project).unwrap();
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text})).unwrap();
    let layer = |s: &Session| s.map().layer_by_name("Scene").and_then(|l| l.raster.clone()).unwrap();
    let rl = layer(&s);
    assert!(rl.data.is_none());
    assert!(rl.error.as_deref().is_some_and(|e| e.contains("retry after 1 s")), "{:?}", rl.error);
    assert_eq!(rl.read_failure().map(|(_, _, failures)| failures), Some(1));
    let said = |s: &Session| s.notices.iter().filter(|n| n.error && n.text.contains("Scene: couldn't be read in place")).count();
    assert_eq!(said(&s), 1, "{:?}", s.notices);
    // Not before its wait is over.
    s.read_in_place_again();
    assert!(layer(&s).data.is_none());
    assert_eq!(sent.load(Ordering::Relaxed), 0, "read again before its wait was over");
    // Nor by a repair of the project (a layer file added, maps imported), which reads the layers
    // not read yet together: a failed read is paced, not started over.
    let at = layer(&s).read_failure().map(|(_, at, _)| at).unwrap();
    let mut other = rustgis_map::Map::new("Other");
    let id = other.add_dataset(crate::data::Dataset::new("Empty", crate::data::GeometryType::Point, Vec::new()));
    crate::cmd::layer::add_layer_text(&mut s, &serde_json::to_string(other.layer(id).unwrap()).unwrap()).unwrap();
    assert_eq!(
        layer(&s).read_failure().map(|(_, at, failures)| (at, failures)),
        Some((at, 1)),
        "started over by the repair: {:?}",
        layer(&s).error
    );
    assert_eq!(sent.load(Ordering::Relaxed), 0);
    // Then read again, as the map draws: refused again, it waits twice as long this time (see
    // `cache::backoff`), and isn't said again.
    let view = rustgis_geom::Extent::new(10.0, 45.9, 10.1, 46.0);
    let draw = |s: &mut Session| {
        crate::render::rustgis_tiles::cache::wait(Duration::from_millis(50));
        s.read_in_place_again();
        s.map_mut().sync_sources(&view, 1000.0, false);
        s.notice_landed_rasters();
    };
    let start = std::time::Instant::now();
    while layer(&s).read_failure().is_none_or(|(_, _, failures)| failures < 2) && start.elapsed() < Duration::from_secs(20) {
        draw(&mut s);
    }
    let rl = layer(&s);
    let (_, at, failures) = rl.read_failure().expect("refused again");
    assert_eq!(failures, 2);
    assert_eq!(sent.load(Ordering::Relaxed), 0);
    assert_eq!(said(&s), 1, "{:?}", s.notices);
    // Not before twice its wait is over (looked at while that is still ahead).
    if at.elapsed() < Duration::from_millis(1800) {
        s.read_in_place_again();
        assert!(layer(&s).read_failure().is_some(), "read again before twice its wait was over");
    }
    // Then read a third time, landing as the map draws.
    let start = std::time::Instant::now();
    while layer(&s).data.is_none() && start.elapsed() < Duration::from_secs(20) {
        draw(&mut s);
    }
    let rl = layer(&s);
    assert!(rl.data.is_some(), "{:?}", rl.error);
    assert!(rl.error.is_none() && rl.read_failure().is_none());
    assert!(sent.load(Ordering::Relaxed) > 0);
    assert_eq!(said(&s), 1, "{:?}", s.notices);
}

/// A cloud-optimised GeoTIFF added without waiting before its header is in (the browser, where
/// nothing may wait, so an address isn't probed first as it is natively) answers that it is still
/// being read, with no size yet rather than none; the size comes with the header (see
/// `a_cog_added_without_waiting_lands_as_the_map_draws`).
#[test]
fn a_cog_added_before_its_header_is_in_says_it_is_being_read() {
    use std::sync::atomic::{AtomicBool, Ordering};
    use std::time::Duration;
    let gate = std::sync::Arc::new(AtomicBool::new(false));
    let (base, _) = serve_gated(rustgis_data::raster::cog::example(512, 256), true, Some(gate.clone()));
    let url = format!("{base}/scene.tif");
    let mut s = Session::new(Project::default());
    s.in_place_wait = false;
    // As the browser adds it: straight in place, its header read with its overview.
    let r = crate::cmd::layer::add_cog(&mut s, &json!({"name": "Scene"}), &url, false).unwrap();
    assert_eq!((r["inPlace"].clone(), r["reading"].clone()), (json!(true), json!(true)), "{r}");
    assert!(r["width"].is_null() && r["height"].is_null() && r["bands"].is_null(), "sized before its header is in: {r}");
    assert!(r.get("bounds").is_none(), "{r}");
    // Its header and overview arrive as the map draws.
    gate.store(true, Ordering::Relaxed);
    let layer = |s: &Session| s.map().layer_by_name("Scene").and_then(|l| l.raster.clone()).unwrap();
    let view = rustgis_geom::Extent::new(10.0, 45.0, 11.0, 46.0);
    let start = std::time::Instant::now();
    while layer(&s).data.is_none() && start.elapsed() < Duration::from_secs(20) {
        crate::render::rustgis_tiles::cache::wait(Duration::from_millis(50));
        s.map_mut().sync_sources(&view, 1000.0, false);
        s.notice_landed_rasters();
    }
    let rl = layer(&s);
    assert_eq!(rl.data.as_ref().map(|d| (d.width, d.band_count())), Some((512, 1)), "{:?}", rl.error);
}

/// A raster layer read in place whose read can't start (a project edited by hand keeps an address
/// that can't be read) says so once, and a repair of the project (a layer file added, maps
/// imported) leaves it as it is: not started over, not said again.
#[test]
fn a_read_in_place_that_couldnt_start_isnt_started_over_by_a_repair() {
    use rustgis_map::raster::RasterLayer;
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("Scene".to_string(), RasterLayer::unread_in_place("ftp://files.example.org/scene.tif"));
    let text = serde_json::to_string(&s.project).unwrap();
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text})).unwrap();
    let layer = |s: &Session| s.project.maps[0].layer_by_name("Scene").and_then(|l| l.raster.clone()).unwrap();
    let rl = layer(&s);
    assert!(rl.data.is_none() && rl.read_failure().is_none(), "{rl:?}");
    let error = rl.error.clone().expect("couldn't start");
    assert!(error.contains("start with https://"), "{error}");
    let said = |s: &Session| s.notices.iter().filter(|n| n.error && n.text.contains("Scene: couldn't be read in place")).count();
    assert_eq!(said(&s), 1, "{:?}", s.notices);
    let mut other = rustgis_map::Map::new("Other");
    let id = other.add_dataset(crate::data::Dataset::new("Empty", crate::data::GeometryType::Point, Vec::new()));
    crate::cmd::layer::add_layer_text(&mut s, &serde_json::to_string(other.layer(id).unwrap()).unwrap()).unwrap();
    s.run("map.import", &json!({"text": serde_json::to_string(&rustgis_map::Map::new("Other")).unwrap()})).unwrap();
    s.notice_landed_rasters();
    let rl = layer(&s);
    assert_eq!((rl.error.as_deref(), rl.read_failure().is_none()), (Some(error.as_str()), true), "started over: {rl:?}");
    assert_eq!(said(&s), 1, "said again: {:?}", s.notices);
}

/// Where the session waits for reads in place (the command line, Python), a failed overview is
/// read again by the next command run once its wait is over, and waited for: a long-lived session
/// that doesn't draw has nothing else to ask again.
#[test]
fn a_waiting_sessions_next_command_reads_a_failed_overview_again() {
    use std::sync::atomic::Ordering;
    use std::time::Duration;
    let (base, sent) = serve_refusing_first(rustgis_data::raster::cog::example(512, 256), 1);
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("Scene".to_string(), rustgis_map::raster::RasterLayer::unread_in_place(format!("{base}/scene.tif")));
    let text = serde_json::to_string(&s.project).unwrap();
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text})).unwrap();
    let layer = |s: &Session| s.map().layer_by_name("Scene").and_then(|l| l.raster.clone()).unwrap();
    assert_eq!(layer(&s).read_failure().map(|(_, _, failures)| failures), Some(1), "{:?}", layer(&s).error);
    let said = |s: &Session| s.notices.iter().filter(|n| n.error && n.text.contains("Scene: couldn't be read in place")).count();
    assert_eq!(said(&s), 1, "{:?}", s.notices);
    // A command run before its wait is over doesn't read it.
    s.run("info.project", &json!({})).unwrap();
    assert!(layer(&s).data.is_none() && layer(&s).read_failure().is_some());
    assert_eq!(sent.load(Ordering::Relaxed), 0, "read again before its wait was over");
    // One run after does, waiting for it: the layer holds its overview as the command answers.
    std::thread::sleep(Duration::from_millis(1100)); // test-wait: cross the failed-overview retry backoff
    s.run("info.project", &json!({})).unwrap();
    let rl = layer(&s);
    assert!(rl.data.is_some(), "{:?}", rl.error);
    assert!(rl.error.is_none() && rl.read_failure().is_none());
    assert!(sent.load(Ordering::Relaxed) > 0);
    assert_eq!(said(&s), 1, "{:?}", s.notices);
}

/// A retry belongs to the read which failed, not whichever command happens to run once
/// its server's wait is over. A native read still recovers when the native user asks again.
#[test]
fn permission_policy_raster_retry_keeps_the_original_owner() {
    use crate::policy::{AgentAccess, Effects, Revocation, Scope};
    use std::sync::{
        Arc,
        atomic::{AtomicBool, Ordering::SeqCst},
    };
    use std::time::Duration;
    struct Live;
    impl Revocation for Live {
        fn allows(&self, _: Effects) -> bool {
            true
        }
    }
    let mut failures = Vec::new();
    for (owned, restricted) in [(true, false), (false, true), (false, false)] {
        let (base, sent) = serve_refusing_first(rustgis_data::raster::cog::example(512, 128), 1);
        let mut s = Session::new(Project::default());
        let live = Arc::new(AtomicBool::new(true));
        let flag = live.clone();
        let still = owned.then(|| Arc::new(move || flag.load(SeqCst)) as crate::render::rustgis_tiles::cache::Still);
        let mut raster = rustgis_map::raster::RasterLayer::unread_in_place(format!("{base}/scene.tif"));
        crate::render::rustgis_tiles::cache::with_optional_still(still, || assert!(raster.reload().is_err()));
        assert_eq!(raster.read_failure().map(|(_, _, n)| n), Some(1));
        s.map_mut().add_raster("Scene", raster);
        live.store(false, SeqCst);
        std::thread::sleep(Duration::from_millis(1100)); // test-wait: cross the failed-overview retry backoff
        if restricted {
            let scope = Scope::agent(AgentAccess::Refuse, true, "raster-retry", None, Arc::new(Live));
            s.with_scope(scope, |s| s.run("info.project", &json!({}))).unwrap().unwrap();
        } else {
            s.run("info.project", &json!({})).unwrap();
        }
        let landed = s.map().layer_by_name("Scene").unwrap().raster.as_ref().unwrap().data.is_some();
        if owned || restricted {
            if landed || sent.load(SeqCst) != 0 {
                failures.push(format!("retry escaped its owner: owned={owned}, restricted={restricted}"));
            }
        } else {
            assert!(landed && sent.load(SeqCst) > 0, "native maintenance must keep recovering");
        }
    }
    assert!(failures.is_empty(), "{failures:?}");
}

/// Where the session doesn't wait for reads in place (the desktop app, whose commands run on the
/// window's own thread), a cloud-optimised GeoTIFF is added at once, its header probed as the app
/// does, and its overview lands as the map draws; one that can't be read is added too, and says so
/// once its read fails. A project opens the same way. Waiting, the command fails instead.
#[test]
fn a_cog_added_without_waiting_lands_as_the_map_draws() {
    use std::time::Duration;
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let url = format!("{base}/scene.tif");
    let mut s = Session::new(Project::default());
    s.in_place_wait = false;
    let _ = crate::render::rustgis_tiles::cog::probe_blocking(&url);
    let r = s.run("layer.addUrl", &json!({"url": url, "name": "Scene"})).unwrap();
    assert_eq!((r["inPlace"].as_bool(), r["kind"].as_str()), (Some(true), Some("raster")), "{r}");
    assert_eq!(r["bounds"], json!([10.0, 45.0, 11.0, 46.0]), "framed on the header read: {r}");
    // Sized by the header read, as the answer is once the overview has landed (512 a side: held
    // whole, so not an overview of anything).
    assert_eq!(
        (r["width"].clone(), r["height"].clone(), r["bands"].clone(), r["reading"].clone(), r.get("overviewOf")),
        (json!(512), json!(512), json!(1), json!(true), None),
        "{r}"
    );
    let layer = |s: &Session, name: &str| s.map().layer_by_name(name).and_then(|l| l.raster.clone()).unwrap();
    let rl = layer(&s, "Scene");
    assert!(rl.in_place && rl.data.is_none() && rl.error.is_none(), "added before its overview is in: {rl:?}");
    let view = rustgis_geom::Extent::new(10.0, 45.0, 11.0, 46.0);
    let draw = |s: &mut Session| {
        crate::render::rustgis_tiles::cache::wait(Duration::from_millis(50));
        s.read_in_place_again();
        s.map_mut().sync_sources(&view, 1000.0, false);
        s.notice_landed_rasters();
    };
    let start = std::time::Instant::now();
    while layer(&s, "Scene").data.is_none() && start.elapsed() < Duration::from_secs(20) {
        draw(&mut s);
    }
    let rl = layer(&s, "Scene");
    assert_eq!(rl.data.as_ref().map(|d| (d.width, d.height)), Some((512, 512)), "{:?}", rl.error);
    // One whose header reads (the first request) but whose tiles can't be is added, and says so
    // once its read fails.
    let (broken, _) = serve_refusing_from(rustgis_data::raster::cog::example(512, 256), 2);
    let broken = format!("{broken}/broken.tif");
    s.run("layer.addUrl", &json!({"url": broken, "name": "Broken"})).unwrap();
    let start = std::time::Instant::now();
    while layer(&s, "Broken").error.is_none() && start.elapsed() < Duration::from_secs(20) {
        draw(&mut s);
    }
    assert!(layer(&s, "Broken").error.as_deref().is_some_and(|e| e.contains("500")), "{:?}", layer(&s, "Broken").error);
    let said = |s: &Session| s.notices.iter().filter(|n| n.error && n.text.contains("Broken: couldn't be read in place")).count();
    assert_eq!(said(&s), 1, "{:?}", s.notices);
    // Waiting, the same address fails the command.
    s.in_place_wait = true;
    assert!(s.run("layer.addUrl", &json!({"url": broken, "name": "Again"})).unwrap_err().contains("500"));
    // A project opens the same way: its layers read in place land as the map draws.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.in_place_wait = false;
    t.run("project.openText", &json!({"text": text})).unwrap();
    assert!(layer(&t, "Scene").data.is_none(), "opened before its overview is in");
    let start = std::time::Instant::now();
    while layer(&t, "Scene").data.is_none() && start.elapsed() < Duration::from_secs(20) {
        draw(&mut t);
    }
    assert!(layer(&t, "Scene").data.is_some(), "{:?}", layer(&t, "Scene").error);
}

/// Binding a saved S3 connection to a project's rasters read in place reads their overviews
/// together, in the time of the slowest (see `s3_connections::reopen_where`), not one after the
/// other: the stand-in bucket answers nothing until both files have been asked for, so reads made
/// one at a time would never get their first answer.
#[test]
fn binding_a_connection_reads_its_in_place_rasters_together() {
    // The fixture changes process-wide S3 accounts; keep parallel readers in their own store.
    if isolate_process_test("tests::binding_a_connection_reads_its_in_place_rasters_together") {
        return;
    }
    use rustgis_map::raster::RasterLayer;
    use std::time::Duration;
    let base = serve_s3_together(vec![
        ("a.tif", rustgis_data::raster::cog::example(512, 256)),
        ("b.tif", rustgis_data::raster::cog::example(256, 512)),
    ]);
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("A".to_string(), RasterLayer::unread_in_place("s3://s3-together-bucket/a.tif"));
    s.map_mut().add_raster("B".to_string(), RasterLayer::unread_in_place("s3://s3-together-bucket/b.tif"));
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run(
        "connection.new",
        &json!({"kind": "s3", "name": "Together", "address": base, "options": {"credentials": "none", "buckets": "s3-together-bucket"}}),
    )
    .unwrap();
    let start = std::time::Instant::now();
    t.run("project.openText", &json!({"text": text})).unwrap();
    for (name, width) in [("A", 512), ("B", 256)] {
        let rl = t.map().layer_by_name(name).and_then(|l| l.raster.clone()).unwrap();
        assert_eq!(rl.data.as_ref().map(|d| d.width), Some(width), "{name}: {:?}", rl.error);
    }
    assert!(start.elapsed() < Duration::from_secs(60), "read one after the other: {:?}", start.elapsed());
    t.run("connection.remove", &json!({"id": "Together"})).unwrap();
}

/// Where the session doesn't wait for reads in place (the desktop), a saved S3 connection chosen
/// for a project's rasters read in place starts their overviews reading and says so: they count
/// as `reading` in `connection.resolveS3`'s answer, not as `reopened`, until they land as the map
/// draws. Waiting, the same choice reads them before it answers, and they are reopened.
#[test]
fn a_connection_chosen_without_waiting_counts_its_in_place_rasters_as_reading() {
    // The fixture changes process-wide S3 accounts; keep parallel readers in their own store.
    if isolate_process_test("tests::a_connection_chosen_without_waiting_counts_its_in_place_rasters_as_reading") {
        return;
    }
    use rustgis_map::raster::RasterLayer;
    use std::time::Duration;
    let base = serve_s3_together(vec![
        ("a.tif", rustgis_data::raster::cog::example(512, 256)),
        ("b.tif", rustgis_data::raster::cog::example(256, 512)),
    ]);
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("A".to_string(), RasterLayer::unread_in_place("s3://s3-chosen-bucket/a.tif"));
    s.map_mut().add_raster("B".to_string(), RasterLayer::unread_in_place("s3://s3-chosen-bucket/b.tif"));
    let text = serde_json::to_string(&s.project).unwrap();
    let layer = |s: &Session, name: &str| s.map().layer_by_name(name).and_then(|l| l.raster.clone()).unwrap();
    // The connection lists no bucket, so the project's sources wait for the user's choice of it.
    let open = |wait: bool| {
        let mut t = Session::new(Project::default());
        t.in_place_wait = wait;
        let c =
            t.run("connection.new", &json!({"kind": "s3", "name": "Chosen", "address": base, "options": {"credentials": "none"}})).unwrap();
        let id = c["id"].as_str().unwrap_or_default().to_string();
        assert!(!id.is_empty(), "{c}");
        t.run("project.openText", &json!({"text": text})).unwrap();
        let source = t.s3_pending.first().map(|p| p.source.clone()).unwrap_or_default();
        assert!(!source.is_empty(), "nothing waited for a choice: {:?}", t.notices);
        let r = t.run("connection.resolveS3", &json!({"source": source, "id": id})).unwrap();
        (t, r, id)
    };
    let counts = |r: &Value| (r["reopened"].as_u64(), r["reading"].as_u64(), r["failed"].as_u64());
    let (mut t, r, id) = open(false);
    assert_eq!(counts(&r), (Some(0), Some(2), Some(0)), "{r}");
    assert!(layer(&t, "A").data.is_none() && layer(&t, "B").data.is_none(), "chosen before the overviews are in");
    let view = rustgis_geom::Extent::new(10.0, 45.0, 11.0, 46.0);
    let start = std::time::Instant::now();
    while (layer(&t, "A").data.is_none() || layer(&t, "B").data.is_none()) && start.elapsed() < Duration::from_secs(60) {
        crate::render::rustgis_tiles::cache::wait(Duration::from_millis(50));
        t.read_in_place_again();
        t.map_mut().sync_sources(&view, 1000.0, false);
        t.notice_landed_rasters();
    }
    for (name, width) in [("A", 512), ("B", 256)] {
        assert_eq!(layer(&t, name).data.as_ref().map(|d| d.width), Some(width), "{name}: {:?}", layer(&t, name).error);
    }
    t.run("connection.remove", &json!({"id": id})).unwrap();
    // Waiting, the choice answers once the overviews are in.
    let (mut t, r, id) = open(true);
    assert_eq!(counts(&r), (Some(2), Some(0), Some(0)), "{r}");
    assert!(layer(&t, "A").data.is_some() && layer(&t, "B").data.is_some());
    t.run("connection.remove", &json!({"id": id})).unwrap();
}

/// A stand-in S3 endpoint serving `files` (key, bytes) by range, answering nothing until each key
/// has been asked for once: reads made together get their answers, reads made one after the other
/// never get the first.
fn serve_s3_together(files: Vec<(&'static str, Vec<u8>)>) -> String {
    use std::io::{Read, Write};
    use std::time::Duration;
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let files = std::sync::Arc::new(files);
    let asked: std::sync::Arc<std::sync::Mutex<std::collections::HashSet<&'static str>>> = Default::default();
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut s) = stream else { continue };
            let (files, asked) = (files.clone(), asked.clone());
            std::thread::spawn(move || {
                let mut buf = [0u8; 8192];
                let read = s.read(&mut buf).unwrap_or(0);
                let req = String::from_utf8_lossy(&buf[..read]).to_ascii_lowercase();
                let path = req.split_whitespace().nth(1).unwrap_or("/").split(['?', '#']).next().unwrap_or("/").to_string();
                let Some((key, body)) = files.iter().find(|(k, _)| path.ends_with(&format!("/{k}"))) else {
                    let _ = s.write_all(b"HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
                    return;
                };
                asked.lock().unwrap().insert(key);
                let start = std::time::Instant::now();
                while asked.lock().unwrap().len() < files.len() && start.elapsed() < Duration::from_secs(150) {
                    std::thread::sleep(Duration::from_millis(5)); // test-wait: hold S3 replies until all keys have been requested
                }
                if req.starts_with("head ") {
                    let _ = write!(s, "HTTP/1.1 200 OK\r\nContent-Length: {}\r\nConnection: close\r\n\r\n", body.len());
                    return;
                }
                let range = req.lines().find_map(|l| l.strip_prefix("range: bytes=")).and_then(|r| {
                    let (a, b) = r.trim().split_once('-')?;
                    if a.is_empty() {
                        let n = b.parse::<usize>().ok()?.min(body.len());
                        return Some((body.len() - n, body.len().saturating_sub(1)));
                    }
                    Some((a.parse::<usize>().ok()?, b.parse::<usize>().ok()?))
                });
                let (status, part) = match range {
                    Some((a, b)) if a < body.len() => ("206 Partial Content", &body[a..=b.min(body.len() - 1)]),
                    Some(_) => ("416 Range Not Satisfiable", &body[..0]),
                    None => ("200 OK", &body[..]),
                };
                let _ = write!(s, "HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n", part.len());
                let _ = s.write_all(part);
            });
        }
    });
    base
}

/// A COG tile layer opened as a raster layer takes a numbered name when another layer has its
/// name, as a layer added does.
#[test]
fn a_migrated_cog_layer_takes_a_free_name() {
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let mut s = Session::new(Project::default());
    let empty =
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","geometry":{"type":"Point","coordinates":[0,0]},"properties":{}}]}"#;
    s.run("layer.addDataText", &json!({"fileName": "scene.geojson", "text": empty, "name": "Scene"})).unwrap();
    assert!(s.map().layer_by_name("Scene").is_some());
    let mut text: Value = serde_json::to_value(&s.project).unwrap();
    let tile = serde_json::to_value(rustgis_map::TileLayer::new("Scene", rustgis_map::TileKind::Cog, format!("{base}/scene.tif"))).unwrap();
    match text.pointer_mut("/maps").and_then(Value::as_array_mut) {
        Some(maps) => maps[0]["tiles"] = json!([tile]),
        None => text["map"]["tiles"] = json!([tile]),
    }
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text.to_string()})).unwrap();
    let names: Vec<&str> = t.map().layers.iter().map(|l| l.name.as_str()).collect();
    assert!(names.contains(&"Scene") && names.contains(&"Scene (2)"), "{names:?}");
    assert!(t.map().layer_by_name("Scene (2)").and_then(|l| l.raster.as_ref()).is_some_and(|r| r.in_place));
}

/// A layer read in place that can't be read says so, once, as its project opens.
#[test]
fn an_in_place_layer_that_cant_be_read_says_so() {
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("Gone".to_string(), rustgis_map::raster::RasterLayer::unread_in_place("http://127.0.0.1:9/gone.tif"));
    let text = serde_json::to_string(&s.project).unwrap();
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text})).unwrap();
    let said = |s: &Session| s.notices.iter().filter(|n| n.error && n.text.contains("Gone: couldn't be read in place")).count();
    assert_eq!(said(&s), 1, "{:?}", s.notices.last());
    s.run("map.zoomIn", &Value::Null).unwrap();
    assert_eq!(said(&s), 1);
}

/// A project an older RustGIS saved again (it didn't know `in_place`: the layer was missing there,
/// and saved without the key) reads its cloud-optimised GeoTIFF in place again: a raster layer
/// whose path is a plain web address is read no other way.
#[test]
fn a_project_an_older_rustgis_saved_again_reads_its_cog_in_place() {
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let mut s = Session::new(Project::default());
    s.map_mut().add_raster("Scene".to_string(), rustgis_map::raster::RasterLayer::unread_in_place(format!("{base}/scene.tif")));
    let mut text: Value = serde_json::to_value(&s.project).unwrap();
    // As the older RustGIS saved it: the path, without `in_place`.
    let raster = text.pointer_mut("/maps/0/layers/0/raster").and_then(Value::as_object_mut).unwrap();
    assert_eq!(raster.remove("in_place"), Some(json!(true)));
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text.to_string()})).unwrap();
    let rl = s.map().layer_by_name("Scene").and_then(|l| l.raster.clone()).unwrap();
    assert!(rl.in_place && rl.error.is_none(), "{:?}", rl.error);
    assert_eq!(rl.data.as_ref().map(|d| d.width), Some(512));
}

/// In-place COGs retain header losses and what applying GDAL metadata leaves out (#1812).
#[test]
fn in_place_cog_metadata_losses_are_preserved_and_said_once() {
    use rustgis_data::raster::cog::{Example, example_with};
    let clean = example_with(&Example { size: 64, tile: 16, classes: true, ..Example::default() });
    let lossy = example_with(&Example { size: 64, tile: 16, classes: true, lossy: true, ..Example::default() });
    let mut outside = example_with(&Example { size: 64, tile: 16, wavelengths: true, ..Example::default() });
    let sample = b"sample=\"0\"";
    let at = outside.windows(sample.len()).position(|w| w == sample).unwrap();
    outside[at + 8] = b'9'; // Same tag length, but band 10 does not exist.
    for (file, expected) in [
        (clean, Vec::new()),
        (lossy, vec!["384 entries, short of the 768", "1 CLASS_ item(s)"]),
        (outside, vec!["names or wavelengths for 1 band(s) it doesn't have"]),
    ] {
        let (base, _) = serve_ranges(file);
        let mut s = Session::new(Project::default());
        s.run("layer.addUrl", &json!({"url": format!("{base}/metadata.tif")})).unwrap();
        let data = s.map().layers.iter().find_map(|l| l.raster.as_ref()?.data.as_ref()).unwrap();
        assert_eq!(data.lost.len(), expected.len(), "{:?}", data.lost);
        for message in expected {
            assert!(data.lost.iter().any(|l| l.contains(message)), "{:?}", data.lost);
            assert_eq!(s.notices.iter().filter(|n| n.text.contains(message)).count(), 1, "{:?}", s.notices);
        }
        let mark = s.notice_mark();
        s.notice_landed_rasters();
        s.notice_landed_rasters();
        assert!(s.notices_since(mark).is_empty());
    }
}

/// A palette COG without its colour table is drawn in grey and says so, also when its pixels land
/// after the layer is added (a project opened, as in the browser and an import): once, and not for
/// one with its table.
#[test]
fn a_palette_without_its_table_says_so_when_its_pixels_land() {
    use rustgis_data::raster::cog::{Example, example_with};
    let clean = example_with(&Example { size: 300, tile: 128, classes: true, ..Example::default() });
    let lossy = example_with(&Example { size: 300, tile: 128, classes: true, no_table: true, ..Example::default() });
    let said = |s: &Session| s.notices.iter().filter(|n| n.text.contains("no colour table")).count();
    for (file, want) in [(lossy, 1), (clean, 0)] {
        let (base, _) = serve_ranges(file);
        let mut s = Session::new(Project::default());
        let layer = rustgis_map::raster::RasterLayer::unread_in_place(format!("{base}/classes.tif"));
        s.map_mut().add_raster("Classes".to_string(), layer);
        let text = serde_json::to_string(&s.project).unwrap();
        let mut s = Session::new(Project::default());
        s.run("project.openText", &json!({"text": text})).unwrap();
        assert!(s.map().layers.iter().any(|l| l.raster.as_ref().is_some_and(|r| r.data.is_some())), "read on opening");
        assert_eq!(said(&s), want, "{:?}", s.notices.iter().map(|n| n.text.as_str()).collect::<Vec<_>>());
        // Said once for these pixels, however often asked.
        s.notice_landed_rasters();
        s.run("map.zoomIn", &Value::Null).unwrap();
        assert_eq!(said(&s), want);
    }
}

/// Draws the map as the app does each frame (the view over the example files), until `landed`
/// or 20 seconds, then a few frames more: what lands is said on the frame it lands, and never again.
/// A cloud-optimised GeoTIFF tile layer shown asks for its header, as drawing its tiles does.
fn draw_until(s: &mut Session, landed: impl Fn(&Session) -> bool) {
    use std::time::Duration;
    let view = rustgis_geom::Extent::new(10.0, 45.0, 11.0, 46.0);
    let draw = |s: &mut Session| {
        crate::render::rustgis_tiles::cache::wait(Duration::from_millis(50));
        s.read_in_place_again();
        s.map_mut().sync_sources(&view, 1000.0, false);
        for t in s.map().tiles.iter().filter(|t| t.draws() && t.opacity > 0.0 && t.kind == rustgis_map::tiles::TileKind::Cog) {
            let _ = crate::render::rustgis_tiles::cog::info(&t.url);
        }
        s.notice_landed_rasters();
    };
    let start = std::time::Instant::now();
    while !landed(s) && start.elapsed() < Duration::from_secs(20) {
        draw(s);
    }
    for _ in 0..3 {
        draw(s);
    }
}

/// A cloud-optimised GeoTIFF with losses in its header, added without waiting before its header is
/// in (the browser, where nothing may wait), says them once its pixels land as the map draws: once,
/// however often the map draws after; a clean file says nothing (#1331).
#[test]
fn a_cog_added_before_its_header_is_in_says_its_losses_once_it_lands() {
    use rustgis_data::raster::cog::{Example, example_with};
    use std::sync::atomic::{AtomicBool, Ordering};
    let clean = example_with(&Example { size: 64, tile: 16, classes: true, ..Example::default() });
    let lossy = example_with(&Example { size: 64, tile: 16, classes: true, lossy: true, ..Example::default() });
    for (file, expected) in [(lossy, vec!["384 entries, short of the 768", "1 CLASS_ item(s)"]), (clean, Vec::new())] {
        let gate = std::sync::Arc::new(AtomicBool::new(false));
        let (base, _) = serve_gated(file, true, Some(gate.clone()));
        let mut s = Session::new(Project::default());
        s.in_place_wait = false;
        let mark = s.notice_mark();
        let r = crate::cmd::layer::add_cog(&mut s, &json!({"name": "Classes"}), &format!("{base}/classes.tif"), false).unwrap();
        assert_eq!(r["reading"], json!(true), "{r}");
        s.notice_landed_rasters();
        assert!(s.notices_since(mark).is_empty(), "said before its header is in: {:?}", s.notices_since(mark));
        gate.store(true, Ordering::Relaxed);
        let landed = |s: &Session| s.map().layer_by_name("Classes").and_then(|l| l.raster.as_ref()).is_some_and(|r| r.data.is_some());
        draw_until(&mut s, landed);
        assert!(landed(&s), "{:?}", s.map().layer_by_name("Classes").and_then(|l| l.raster.as_ref()).map(|r| r.error.clone()));
        let said: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).collect();
        for message in &expected {
            assert_eq!(said.iter().filter(|t| t.contains(message)).count(), 1, "{said:?}");
        }
        if expected.is_empty() {
            assert!(said.is_empty(), "{said:?}");
        }
    }
}

/// A cloud-optimised GeoTIFF drawn as a tile layer (here a data cube's file; a dated series and
/// AlphaEarth alike), added before its header is in (the browser), says what its header leaves out
/// once the header lands as the map draws: once, however often the map draws after, and again in
/// a project opened again; a clean file says nothing (#1331).
#[test]
fn a_cog_tile_layer_added_before_its_header_is_in_says_its_losses_once_it_lands() {
    use rustgis_data::raster::cog::{Example, example_with};
    use std::sync::atomic::{AtomicBool, Ordering};
    let clean = example_with(&Example { size: 64, tile: 16, ..Example::default() });
    let lossy = example_with(&Example { size: 64, tile: 16, classes: true, lossy: true, ..Example::default() });
    let lossy_said = vec!["384 entries, short of the 768", "1 CLASS_ item(s)", "drawn in place without its band names"];
    for (file, expected) in [(lossy, lossy_said), (clean, Vec::new())] {
        let gate = std::sync::Arc::new(AtomicBool::new(false));
        let (base, _) = serve_gated(file, true, Some(gate.clone()));
        let mut s = Session::new(Project::default());
        let mark = s.notice_mark();
        let p = json!({"name": "Cube", "cube": true});
        let r = crate::cmd::layer::add_cog(&mut s, &p, &format!("{base}/cube-2020.tif"), false).unwrap();
        assert_eq!(r["kind"], "cog", "{r}");
        let cube = |s: &Session, mark: u64| {
            s.notices_since(mark).iter().map(|n| n.text.clone()).filter(|t| t.starts_with("Cube: ")).collect::<Vec<_>>()
        };
        s.notice_landed_rasters();
        assert!(cube(&s, mark).is_empty(), "said before its header is in: {:?}", cube(&s, mark));
        // The map renamed while the header is being read, the rename undone once it has landed.
        s.run("map.rename", &json!({"name": "Renamed"})).unwrap();
        gate.store(true, Ordering::Relaxed);
        let landed = |s: &Session| s.map().tiles.first().is_some_and(|t| !t.headers_said.is_empty());
        draw_until(&mut s, landed);
        assert!(landed(&s), "its header never landed");
        let check = |said: Vec<String>| {
            for message in &expected {
                assert_eq!(said.iter().filter(|t| t.starts_with("Cube: ") && t.contains(message)).count(), 1, "{said:?}");
            }
            assert_eq!(said.len(), expected.len(), "{said:?}");
        };
        check(cube(&s, mark));
        assert!(s.undo());
        assert_ne!(s.map().name, "Renamed", "the rename wasn't undone");
        s.notice_landed_rasters();
        check(cube(&s, mark));
        // A project opened again says it again, once.
        let text = serde_json::to_string(&s.project).unwrap();
        let mut t = Session::new(Project::default());
        let mark = t.notice_mark();
        t.run("project.openText", &json!({"text": text})).unwrap();
        draw_until(&mut t, landed);
        check(cube(&t, mark));
    }
}

/// A dated series of cloud-optimised GeoTIFFs says what each date's file leaves out of its header,
/// named by the file, each date's once its header lands, the first included, not only the first
/// date's (#1331); a date shown again, or after an undo or a redo, isn't said again; a clean series
/// says nothing.
#[test]
fn a_dated_cog_series_says_each_dates_header_losses_once() {
    use rustgis_data::raster::cog::{Example, example_with};
    let lossy = example_with(&Example { size: 64, tile: 16, classes: true, lossy: true, ..Example::default() });
    let clean = example_with(&Example { size: 64, tile: 16, ..Example::default() });
    // A lossy file's lines: its short colour table, its CLASS_ item, its class names not drawn.
    for (file, per_file) in [(lossy, 3), (clean, 0)] {
        let (base, _) = serve_ranges(file);
        let mut s = Session::new(Project::default());
        let mark = s.notice_mark();
        // A token in the address stays out of what is said: the file is named by its path alone.
        let url = format!("{base}/{{YYYY}}.tif?token=hidden-1331");
        let p = json!({"url": url, "kind": "cog", "name": "Series", "start": 2000, "end": 2001});
        s.run("map.addTiles", &p).unwrap();
        // Said with the date's file: the layer's name says which series, the file which date.
        let said = |s: &Session| s.notices_since(mark).iter().filter(|n| n.text.starts_with("Series (")).count();
        let said_of =
            |s: &Session, file: &str| s.notices_since(mark).iter().filter(|n| n.text.starts_with(&format!("Series ({file}): "))).count();
        let files = |n: usize| move |s: &Session| s.map().tiles.first().is_some_and(|t| t.headers_said.len() >= n);
        draw_until(&mut s, files(1));
        assert!(files(1)(&s), "the first date's header never landed");
        assert_eq!((said(&s), said_of(&s, "2000.tif")), (per_file, per_file), "{:?}", s.notices_since(mark));
        assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("hidden-1331")), "{:?}", s.notices_since(mark));
        // An edit made, then the next date shown and said: undoing and redoing the edit (whose
        // copy of the project predates that date) says nothing again.
        s.run("map.setTiles", &json!({"index": 0, "opacity": 0.5})).unwrap();
        s.run("time.goTo", &json!({"date": 2001})).unwrap();
        draw_until(&mut s, files(2));
        assert!(files(2)(&s), "the second date's header never landed");
        assert_eq!((said(&s), said_of(&s, "2001.tif")), (2 * per_file, per_file), "{:?}", s.notices_since(mark));
        for step in ["undo", "redo"] {
            assert!(if step.starts_with("undo") { s.undo() } else { s.redo() }, "{step}");
            s.notice_landed_rasters();
            assert_eq!(said(&s), 2 * per_file, "said again after {step}: {:?}", s.notices_since(mark));
        }
        s.run("time.goTo", &json!({"date": 2000})).unwrap();
        s.notice_landed_rasters();
        assert_eq!(s.map().tiles[0].headers_said.len(), 2);
        assert_eq!(said(&s), 2 * per_file, "said again for a date shown before: {:?}", s.notices_since(mark));
        assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("hidden-1331")), "{:?}", s.notices_since(mark));
    }
}

/// A dated series' date whose header lands after the slider moved on says what it leaves out
/// then, named by its file, once; the date shown when it lands says its own once too (#1331). A
/// clean series says nothing.
#[test]
fn a_dated_cog_series_says_a_date_whose_header_lands_after_the_slider_moved_on() {
    use rustgis_data::raster::cog::{Example, example_with};
    use std::sync::atomic::{AtomicBool, Ordering};
    let lossy = example_with(&Example { size: 64, tile: 16, classes: true, lossy: true, ..Example::default() });
    let clean = example_with(&Example { size: 64, tile: 16, ..Example::default() });
    for (file, per_file) in [(lossy, 3), (clean, 0)] {
        let gate = std::sync::Arc::new(AtomicBool::new(false));
        let (base, _) = serve_gated(file, true, Some(gate.clone()));
        let mut s = Session::new(Project::default());
        let mark = s.notice_mark();
        let p = json!({"url": format!("{base}/{{YYYY}}.tif"), "kind": "cog", "name": "Series", "start": 2000, "end": 2001});
        s.run("map.addTiles", &p).unwrap();
        // Named by their files, alone or together (dates landing in one frame share a notice).
        let said_of =
            |s: &Session, file: &str| s.notices_since(mark).iter().filter(|n| n.text.contains(&format!("Series ({file})"))).count();
        // 2000's header is asked for (as drawing it does), and the slider moves on before any
        // landing check and before the header is in.
        let url = s.map().tiles[0].url.clone();
        assert!(matches!(crate::render::rustgis_tiles::cog::info(&url), Ok(None)), "2000's header is in already");
        s.run("time.goTo", &json!({"date": 2001})).unwrap();
        gate.store(true, Ordering::Relaxed);
        let files = |s: &Session| s.map().tiles.first().is_some_and(|t| t.headers_said.len() >= 2);
        draw_until(&mut s, files);
        assert!(files(&s), "a header never landed: {:?}", s.map().tiles[0].headers_said);
        assert_eq!((said_of(&s, "2000.tif"), said_of(&s, "2001.tif")), (per_file, per_file), "{:?}", s.notices_since(mark));
        // Both said, nothing is kept waiting for them.
        assert!(s.map().tiles[0].headers_shown.is_empty(), "{:?}", s.map().tiles[0].headers_shown);
    }
}

/// An export of a dated series' time steps draws each date's file, and says what each one's header
/// leaves out, naming its file, once for each loss (#1331); a clean series says nothing.
#[test]
fn exporting_a_dated_cog_series_says_each_dates_header_losses() {
    use rustgis_data::raster::cog::{Example, example_with};
    let lossy = example_with(&Example { size: 64, tile: 16, classes: true, lossy: true, ..Example::default() });
    let clean = example_with(&Example { size: 64, tile: 16, ..Example::default() });
    // A lossy file's lines: its short colour table, its CLASS_ item, its class names not drawn.
    for (n, (file, per_file)) in [(lossy, 3), (clean, 0)].into_iter().enumerate() {
        let (base, _) = serve_ranges(file);
        let mut s = Session::new(Project::default());
        let p = json!({"url": format!("{base}/{{YYYY}}.tif"), "kind": "cog", "name": "Series", "start": 2000, "end": 2002});
        let mark = s.notice_mark();
        s.run("map.addTiles", &p).unwrap();
        let zip = std::env::temp_dir().join(format!("rustgis-cog-series-{}-{n}.zip", std::process::id()));
        let r = s.run("time.export", &json!({"path": zip.display().to_string(), "width": 64, "height": 48})).unwrap();
        let _ = std::fs::remove_file(&zip);
        assert_eq!(r["frames"], 3, "{r}");
        s.notice_landed_rasters();
        let named = |s: &Session, file: &str| s.notices_since(mark).iter().filter(|n| n.text.contains(&format!("Series ({file})"))).count();
        for file in ["2000.tif", "2001.tif", "2002.tif"] {
            assert_eq!(named(&s, file), per_file, "{file}: {:?}", s.notices_since(mark));
        }
        if per_file == 0 {
            assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("Series")), "{:?}", s.notices_since(mark));
        }
    }
}

/// A project's raster that isn't read in place (on S3, so downloaded whole) lands as the map draws,
/// not as the project opens, and says what reading it lost then: once, however often the map draws
/// after; a clean file says nothing (#1331).
#[test]
fn a_project_raster_downloaded_in_the_background_says_its_losses_once_it_lands() {
    // The fixture changes process-wide S3 accounts; keep parallel readers in their own store.
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::a_project_raster_downloaded_in_the_background_says_its_losses_once_it_lands") {
        return;
    }
    use rustgis_data::raster::cog::{Example, example_with};
    let clean = example_with(&Example { size: 64, tile: 16, classes: true, ..Example::default() });
    let lossy = example_with(&Example { size: 64, tile: 16, classes: true, no_table: true, ..Example::default() });
    for (bucket, file, want) in [("s3-landing-lossy", lossy, 1), ("s3-landing-clean", clean, 0)] {
        let pixels = rustgis_data::raster::read_bytes("classes.tif", &file).unwrap();
        let base = serve_s3_together(vec![("classes.tif", file)]);
        let mut s = Session::new(Project::default());
        let layer = rustgis_map::raster::RasterLayer::from_path(pixels, format!("s3://{bucket}/classes.tif"));
        assert!(!layer.in_place);
        s.map_mut().add_raster("Classes".to_string(), layer);
        let text = serde_json::to_string(&s.project).unwrap();
        let mut t = Session::new(Project::default());
        t.in_place_wait = false;
        let c = t
            .run(
                "connection.new",
                &json!({"kind": "s3", "name": bucket, "address": base, "options": {"credentials": "none", "buckets": bucket}}),
            )
            .unwrap();
        let mark = t.notice_mark();
        t.run("project.openText", &json!({"text": text})).unwrap();
        let rl = |t: &Session| t.map().layer_by_name("Classes").and_then(|l| l.raster.clone()).unwrap();
        assert!(rl(&t).data.is_none() && rl(&t).error.is_none(), "not read in the background: {:?}", rl(&t).error);
        let said = |t: &Session| {
            t.notices_since(mark).iter().filter(|n| n.text.ends_with("it is a palette image with no colour table: drawn grey")).count()
        };
        assert_eq!(said(&t), 0, "said before it landed");
        draw_until(&mut t, |t| rl(t).data.is_some());
        assert!(rl(&t).data.is_some(), "{:?}", rl(&t).error);
        assert_eq!(said(&t), want, "{:?}", t.notices_since(mark));
        if want == 0 {
            assert!(!t.notices_since(mark).iter().any(|n| n.text.contains("Classes")), "{:?}", t.notices_since(mark));
        }
        t.run("connection.remove", &json!({"id": c["id"].as_str().unwrap_or_default()})).unwrap();
    }
}

/// A data cube's file (`"cube": true`) is a tile layer, and stays one when its project opens
/// again: its address keeps the marker, which the migration respects.
#[test]
fn a_data_cubes_file_stays_a_tile_layer_when_its_project_reopens() {
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/cube-2020.tif"), "cube": true})).unwrap();
    assert_eq!(r["kind"], "cog", "{r}");
    assert_eq!(s.map().tiles.len(), 1);
    assert!(s.map().tiles[0].url.ends_with("#cube=1"), "{}", s.map().tiles[0].url);
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!((t.map().tiles.len(), t.map().layers.iter().filter(|l| l.raster.is_some()).count()), (1, 0));
}

/// A tile layer's file whose header gives only its bands' wavelengths says they aren't drawn
/// with it, as it says of band and class names.
#[test]
fn a_tile_layer_says_its_wavelengths_need_a_window() {
    use rustgis_data::raster::cog::{Example, example_with};
    let file = example_with(&Example { size: 512, bands: 3, wavelengths: true, ..Example::default() });
    let (base, _) = serve_ranges(file);
    let mut s = Session::new(Project::default());
    let mark = s.notice_mark();
    s.run("layer.addUrl", &json!({"url": format!("{base}/cube-2020.tif"), "cube": true})).unwrap();
    let tail = "drawn in place without its band names, class names or wavelengths: a window (\"bbox\") reads them";
    let said = |s: &Session| s.notices_since(mark).iter().filter(|n| n.text.ends_with(tail)).count();
    assert_eq!(said(&s), 1, "{:?}", s.notices_since(mark));
    // Said as it was added, so not again as the map draws.
    s.notice_landed_rasters();
    s.notice_landed_rasters();
    assert_eq!(said(&s), 1, "{:?}", s.notices_since(mark));
}

/// Dated-series keys given as `null` (a script's unused ones) ask for nothing: the GeoTIFF is a
/// raster layer read in place, not a tile layer.
#[test]
fn null_series_keys_leave_a_geotiff_read_in_place() {
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let mut s = Session::new(Project::default());
    let p = json!({"url": format!("{base}/scene.tif"), "start": null, "end": null, "dates": null});
    let r = s.run("layer.addUrl", &p).unwrap();
    assert_eq!((r["kind"].clone(), r["inPlace"].clone()), (json!("raster"), json!(true)), "{r}");
    assert!(s.map().tiles.is_empty());
}

/// A layer read in place says its statistics and tools read an overview: once when added, once
/// when a project with it opens (its pixels landing then), and not again for the same pixels.
#[test]
fn in_place_layers_say_their_overview_once() {
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(2048, 256));
    let said = |s: &Session| s.notices.iter().filter(|n| n.text.contains("raster tools read a 1024 × 1024 overview")).count();
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif")})).unwrap();
    // The result names the full size, as a file opened from an overview's does.
    assert_eq!((r["width"].clone(), r["overviewOf"].clone()), (json!(1024), json!([2048, 2048])), "{r}");
    s.run("map.zoomIn", &Value::Null).unwrap();
    assert_eq!(said(&s), 1, "{:?}", s.notices.last());
    let text = serde_json::to_string(&s.project).unwrap();
    let mut s = Session::new(Project::default());
    s.run("project.openText", &json!({"text": text})).unwrap();
    s.notice_landed_rasters();
    assert_eq!(said(&s), 1, "{:?}", s.notices.last());
}

/// A project saved when cloud-optimised GeoTIFFs read in place were tile layers opens them as
/// raster layers read in place, each where it was drawn, with its name, visibility, opacity,
/// look, connection and anonymity; a dated series stays a tile layer.
#[test]
fn cog_tile_layers_of_older_projects_open_as_rasters() {
    use rustgis_data::raster::cog::{Example, example_with};
    use rustgis_map::raster::{RasterRenderer, Stretch};
    let (base, _) = serve_ranges(example_with(&Example { size: 512, tile: 256, bands: 8, ..Example::default() }));
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": "points.geojson", "text": "{\"type\":\"FeatureCollection\",\"features\":[]}"})).ok();
    let mut text: Value = serde_json::to_value(&s.project).unwrap();
    let tile = |name: &str, url: String, opacity: f64, visible: bool| {
        let mut l = rustgis_map::TileLayer::new(name, rustgis_map::TileKind::Cog, url);
        // Scene's credit, zoom range, overlay flag and legend: what a raster layer hasn't.
        if name == "Scene" {
            l.attribution = "© Example".into();
            l.min_zoom = 5;
            l.overlay = true;
            l.legends = vec![rustgis_data::ogc::Legend { url: format!("{base}/legend.png"), min_scale: None, max_scale: None }];
            l.connection = "conn-scene".into();
        }
        if name == "Aerial" {
            l.anonymous = true;
        }
        let mut t = serde_json::to_value(l).unwrap();
        t["opacity"] = json!(opacity);
        t["visible"] = json!(visible);
        t
    };
    // Tile layers list the top one first: Scene over Aerial, both under the map's layers.
    let tiles = json!([
        tile("Scene", format!("{base}/scene.tif#bands=5,3,2&range=10,200"), 0.5, false),
        tile("Series", format!("{base}/{{date:YYYY}}.tif"), 1.0, true),
        tile("Aerial", format!("{base}/aerial.tif"), 1.0, true),
    ]);
    let maps = text.pointer_mut("/maps").and_then(Value::as_array_mut);
    match maps {
        Some(maps) => maps[0]["tiles"] = tiles,
        None => text["map"]["tiles"] = tiles,
    }
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text.to_string()})).unwrap();
    let scene = t.map().layers.iter().find(|l| l.name == "Scene").unwrap();
    let rl = scene.raster.as_ref().unwrap();
    assert!(rl.in_place && rl.data.is_some() && rl.path.as_deref() == Some(&*format!("{base}/scene.tif")), "{:?}", rl.path);
    assert_eq!(rl.style.renderer, RasterRenderer::Rgb { red: 4, green: 2, blue: 1 });
    assert_eq!(rl.style.stretch, Stretch::custom(10.0, 200.0));
    assert!(!scene.visible && (scene.opacity() - 0.5).abs() < 1e-6);
    // Read again through the connection it came from; an anonymous layer stays one.
    assert_eq!((scene.connection.as_str(), scene.anonymous), ("conn-scene", false));
    let aerial = t.map().layers.iter().find(|l| l.name == "Aerial").unwrap();
    assert!(aerial.anonymous && aerial.connection.is_empty(), "{aerial:?}");
    // Drawn under the map's layers, as they were, Scene over Aerial.
    let names: Vec<&str> = t.map().layers.iter().map(|l| l.name.as_str()).collect();
    assert_eq!(names[names.len() - 2..], ["Scene", "Aerial"], "{names:?}");
    assert_eq!(t.map().tiles.iter().map(|x| x.name.as_str()).collect::<Vec<_>>(), ["Series"]);
    // Scene's settings a raster layer hasn't are said to be dropped, once; Aerial had none.
    let said = |t: &Session| t.notices.iter().filter(|n| n.text.contains("which have no attribution, legend, overlay, zoom range")).count();
    assert_eq!(said(&t), 1, "{:?}", t.notices.last());
    assert!(t.notices.iter().any(|n| n.text.contains("not kept for Scene") && !n.text.contains("Aerial")), "{:?}", t.notices.last());
    t.run("map.zoomIn", &Value::Null).unwrap();
    assert_eq!(said(&t), 1);
}

/// A plain COG tile layer added this session (`map.addTiles`, kind `cog`) stays a tile layer, with
/// what a raster layer hasn't, through a layer file added and maps imported (each repairs the
/// project): it opens as a raster layer read in place once the project is saved and opened again,
/// as an older project's does. A map file's plain COG tile layers open as raster layers as the map
/// is imported, as a project's do.
#[test]
fn a_cog_tile_layer_added_this_session_stays_one_until_the_project_opens_again() {
    use rustgis_map::{TileKind, TileLayer};
    let (base, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let url = format!("{base}/scene.tif");
    let _ = crate::render::rustgis_tiles::cog::probe_blocking(&url);
    let mut s = Session::new(Project::default());
    s.run("map.addTiles", &json!({"url": url, "kind": "cog", "name": "Scene", "attribution": "© Example"})).unwrap();
    let scene = |s: &Session| s.project.maps[0].tiles.iter().find(|t| t.name == "Scene").map(|t| (t.kind, t.attribution.clone()));
    assert_eq!(scene(&s), Some((TileKind::Cog, "© Example".to_string())), "{:?}", s.project.maps[0].tiles);
    let mut other = rustgis_map::Map::new("Other");
    let id = other.add_dataset(crate::data::Dataset::new("Empty", crate::data::GeometryType::Point, Vec::new()));
    crate::cmd::layer::add_layer_text(&mut s, &serde_json::to_string(other.layer(id).unwrap()).unwrap()).unwrap();
    s.run("map.import", &json!({"text": serde_json::to_string(&other).unwrap()})).unwrap();
    assert_eq!(scene(&s), Some((TileKind::Cog, "© Example".to_string())), "converted by a repair");
    assert!(s.project.maps[0].layer_by_name("Scene").is_none());
    assert!(!s.notices.iter().any(|n| n.text.contains("which have no attribution")), "{:?}", s.notices);
    // An older map file's plain COG tile layer opens as a raster layer read in place as it is
    // imported.
    let mut old = serde_json::to_value(rustgis_map::Map::new("Old")).unwrap();
    old["tiles"] = json!([serde_json::to_value(TileLayer::new("Aerial", TileKind::Cog, format!("{base}/aerial.tif"))).unwrap()]);
    s.run("map.import", &json!({"text": old.to_string()})).unwrap();
    let imported = s.project.maps.iter().find(|m| m.name == "Old").unwrap();
    let rl = imported.layer_by_name("Aerial").and_then(|l| l.raster.as_ref()).unwrap();
    assert!(imported.tiles.is_empty() && rl.in_place && rl.data.is_some(), "{:?}", rl.error);
    // Saved and opened again, Scene is a raster layer read in place too.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let rl = t.project.maps[0].layer_by_name("Scene").and_then(|l| l.raster.as_ref()).unwrap();
    assert!(t.project.maps[0].tiles.is_empty() && rl.in_place && rl.data.is_some(), "{:?}", rl.error);
}

/// A server answering every request with `body`, logging each as `HEAD`, `GET` or `GET <range>`.
/// Its HEAD answers carry `announce` as `X-TIFF-Header-Length`, `kind` as `Content-Type` and,
/// with `ranges`, `Accept-Ranges: bytes`.
fn serve_logged(
    body: Vec<u8>,
    announce: Option<&'static str>,
    kind: Option<&'static str>,
    ranges: bool,
) -> (String, std::sync::Arc<std::sync::Mutex<Vec<String>>>) {
    use std::io::{Read, Write};
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let log = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let kept = log.clone();
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut s) = stream else { continue };
            let mut buf = [0u8; 4096];
            let read = s.read(&mut buf).unwrap_or(0);
            let req = String::from_utf8_lossy(&buf[..read]).to_ascii_lowercase();
            let mut headers = String::new();
            if let Some(k) = kind {
                headers.push_str(&format!("Content-Type: {k}\r\n"));
            }
            if req.starts_with("head ") {
                kept.lock().unwrap().push("HEAD".to_string());
                if let Some(n) = announce {
                    headers.push_str(&format!("X-TIFF-Header-Length: {n}\r\n"));
                }
                if ranges {
                    headers.push_str("Accept-Ranges: bytes\r\n");
                }
                let _ = write!(s, "HTTP/1.1 200 OK\r\n{headers}Content-Length: {}\r\nConnection: close\r\n\r\n", body.len());
                continue;
            }
            let range = req.lines().find_map(|l| l.strip_prefix("range: bytes=")).map(|r| r.trim().to_string());
            kept.lock().unwrap().push(range.as_ref().map_or("GET".to_string(), |r| format!("GET {r}")));
            let bounds = range.as_deref().and_then(|r| {
                let (a, b) = r.split_once('-')?;
                let a = a.parse::<usize>().ok()?;
                Some((a, if b.is_empty() { body.len().saturating_sub(1) } else { b.parse::<usize>().ok()? }))
            });
            let (status, part) = match bounds {
                Some((a, b)) if a < body.len() => ("206 Partial Content", &body[a..=b.min(body.len() - 1)]),
                _ => ("200 OK", &body[..]),
            };
            let _ = write!(s, "HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n", part.len());
            let _ = s.write_all(part);
        }
    });
    (format!("http://{addr}"), log)
}

/// A GeoTIFF made on request (Vantor's Transform API) says how long its header is in its HEAD
/// answer (`X-TIFF-Header-Length`): the header is read in that one request. Without a usable
/// length, the first 64 KiB are read as for any file; a HEAD answer saying JSON skips the
/// GeoTIFF read and downloads it.
#[test]
fn announced_tiff_header_lengths_read_the_header_in_one_request() {
    let file = rustgis_data::raster::cog::example(2048, 256);
    let mut s = Session::new(Project::default());
    let (base, log) = serve_logged(file.clone(), Some("8192"), Some("image/tiff"), true);
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/transform/geotiff?id=1"), "name": "Announced"})).unwrap();
    assert_eq!(r["inPlace"], true, "{r}");
    let asked = log.lock().unwrap().clone();
    assert_eq!(asked.first().map(String::as_str), Some("HEAD"), "{asked:?}");
    assert_eq!(asked.get(1).map(String::as_str), Some("GET 0-8191"), "the header in one read of its announced length: {asked:?}");
    // A length that isn't one: the usual first read.
    let (base, log) = serve_logged(file.clone(), Some("lots"), None, true);
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/transform/geotiff?id=2"), "name": "Unannounced"})).unwrap();
    assert_eq!(r["inPlace"], true, "{r}");
    assert_eq!(log.lock().unwrap().get(1).map(String::as_str), Some("GET 0-65535"));
    // A file named .tif isn't asked for its headers.
    let (base, log) = serve_logged(file.clone(), Some("8192"), None, true);
    s.run("layer.addUrl", &json!({"url": format!("{base}/scene.tif"), "name": "Named"})).unwrap();
    assert!(!log.lock().unwrap().iter().any(|r| r == "HEAD"), "{:?}", log.lock().unwrap());
    // A GeoTIFF labelled as text by a server that answers ranges is still read in place.
    let (base, log) = serve_logged(file, None, Some("text/plain"), true);
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/transform/geotiff?id=3"), "name": "Mislabelled"})).unwrap();
    assert_eq!(r["inPlace"], true, "{r}");
    assert_eq!(log.lock().unwrap().get(1).map(String::as_str), Some("GET 0-65535"));
    // JSON by its HEAD answer, from a server that doesn't say it answers ranges: no GeoTIFF
    // read, downloaded and added.
    let geojson = br#"{"type": "Feature", "properties": {}, "geometry": {"type": "Point", "coordinates": [1, 2]}}"#.to_vec();
    let (base, log) = serve_logged(geojson, None, Some("application/geo+json"), false);
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/api/feature"), "name": "Feature"})).unwrap();
    assert_eq!(r["features"], 1, "{r}");
    assert_eq!(*log.lock().unwrap(), ["HEAD", "GET"], "no GeoTIFF read, then the download");
}

/// OpenStreetMap data for an area through an Overpass server (a local one): a layer per geometry
/// kind; geoBoundaries' GeoJSON given as text; bad requests refused.
#[test]
fn osm_and_boundaries() {
    const ANSWER: &[u8] = br#"{"elements": [
        {"type": "node", "id": 1, "lat": 46.945, "lon": 7.445, "tags": {"amenity": "cafe", "name": "Kaffee"}},
        {"type": "way", "id": 2, "tags": {"building": "yes"}, "geometry": [{"lat": 46.94, "lon": 7.44}, {"lat": 46.94, "lon": 7.441}, {"lat": 46.941, "lon": 7.441}, {"lat": 46.94, "lon": 7.44}]},
        {"type": "way", "id": 3, "tags": {"highway": "residential", "name": "Gasse"}, "geometry": [{"lat": 46.94, "lon": 7.44}, {"lat": 46.945, "lon": 7.445}]}
    ]}"#;
    let base = serve(ANSWER, 1);
    let mut s = Session::new(Project::default());
    let r = s.run("osm.download", &json!({"bbox": [7.44, 46.94, 7.45, 46.95], "tags": "amenity, building, highway", "url": base})).unwrap();
    assert_eq!(r["layers"].as_array().map(Vec::len), Some(3), "{r}");
    let names: Vec<String> = s.map().layers.iter().map(|l| l.name.clone()).collect();
    assert!(names.iter().any(|n| n == "OSM amenity, building, highway (polygons)"), "{names:?}");
    // The app's answer, passed in.
    let r = s
        .run(
            "osm.download",
            &json!({"bbox": [7.44, 46.94, 7.45, 46.95], "preset": "pois", "name": "Cafés", "answer": std::str::from_utf8(ANSWER).unwrap()}),
        )
        .unwrap();
    assert_eq!(r["features"]["points"], 1);
    for bad in [
        json!({"bbox": [7.0, 46.0, 8.0, 47.0], "preset": "roads"}),
        json!({"bbox": [7.44, 46.94, 7.45, 46.95]}),
        json!({"bbox": [7.44, 46.94, 7.45, 46.95], "preset": "x"}),
        json!({"bbox": [7.44, 46.94, 7.45, 46.95], "preset": "roads", "answer": "<html>busy</html>"}),
        json!({"bbox": "here", "preset": "roads"}),
        // An entry that isn't a number isn't dropped: the box is refused.
        json!({"bbox": [7.44, "x", 46.94, 7.45, 46.95], "preset": "roads"}),
        json!({"preset": "roads", "view": false}),
    ] {
        assert!(s.run("osm.download", &bad).is_err(), "{bad}");
    }
    let gj = r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {"shapeName": "Bern"}, "geometry": {"type": "Polygon", "coordinates": [[[7, 46], [8, 46], [8, 47], [7, 46]]]}}]}"#;
    let camera = s.map().camera;
    let r = s.run("boundaries.add", &json!({"country": "che", "level": 1, "text": gj})).unwrap();
    assert_eq!(r["features"], 1);
    assert!(s.map().layer_by_name("CHE ADM1").is_some());
    assert_eq!(s.map().camera, camera, "adding boundaries preserves an occupied map's view");
    let mut empty = Session::new(Project::default());
    empty.run("boundaries.add", &json!({"country":"CHE", "text":gj})).unwrap();
    let center = rustgis_geom::merc_to_lonlat(empty.map().camera.center);
    assert!((center.x - 7.5).abs() < 0.1 && (center.y - 46.5).abs() < 0.1, "{center:?}");
    for bad in [
        json!({}),
        json!({"country": "CH", "text": gj}),
        json!({"country": "CHE", "level": "ADM9", "text": gj}),
        json!({"country": "CHE", "text": "{"}),
    ] {
        assert!(s.run("boundaries.add", &bad).is_err(), "{bad}");
    }
}

/// Search Open Data against a local CKAN site: datasets with their resources (what RustGIS can't
/// add dropped, the best format first), one added by its address; bad requests are refused.
#[test]
fn open_data_portal_search_and_add() {
    let ckan = r#"{"success": true, "result": {"count": 2, "results": [
        {"name": "parks", "title": "Parks", "notes": "<p>City <b>parks</b> &amp; gardens</p>", "organization": {"title": "City"},
         "resources": [{"format": "PDF", "url": "{base}/parks.pdf"}, {"format": "CSV", "url": "{base}/parks.csv"}, {"format": "GeoJSON", "url": "{base}/parks.geojson"}]},
        {"name": "report", "title": "A report", "resources": [{"format": "PDF", "url": "{base}/r.pdf"}]}
    ]}}"#;
    let gj = r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {"n": 1}, "geometry": {"type": "Point", "coordinates": [10, 20]}}]}"#;
    let base = serve_routes(vec![("/api/3/action/package_search", ckan.to_string()), ("/parks.geojson", gj.to_string())], 2);
    let mut s = Session::new(Project::default());
    let r = s.run("portal.search", &json!({"portal": "ckan", "url": base, "query": "parks"})).unwrap();
    assert_eq!(r["count"], 1, "{r}");
    let d = &r["datasets"][0];
    assert_eq!(d["title"], "Parks");
    assert_eq!(d["description"], "City parks & gardens");
    let formats: Vec<&str> = d["resources"].as_array().unwrap().iter().filter_map(|x| x["format"].as_str()).collect();
    assert_eq!(formats, ["GeoJSON", "CSV"]);
    let url = d["resources"][0]["url"].as_str().unwrap();
    let r = s.run("portal.add", &json!({"url": url, "name": "Parks", "portal": base})).unwrap();
    assert_eq!(r["features"], 1, "{r}");
    assert!(s.map().layer_by_name("Parks").is_some());
    for (id, bad) in [
        ("portal.search", json!({"portal": "ckan", "url": base})),
        ("portal.search", json!({"portal": "nope", "query": "parks"})),
        ("portal.search", json!({"portal": "ckan", "url": "file:///etc", "query": "parks"})),
        ("portal.add", json!({})),
        ("portal.add", json!({"url": "file:///etc/passwd"})),
        ("portal.add", json!({"url": "https://example.org/x.geojson", "use": "ftp"})),
        // A public portal's document can't point into the local network.
        ("portal.add", json!({"url": "http://127.0.0.1/x.geojson", "portal": "https://catalog.data.gov"})),
    ] {
        assert!(s.run(id, &bad).is_err(), "{id} {bad}");
    }
}

/// A GeoLens dataset (a local server's) is added with every page of its features, not only the
/// server's first 1,000.
#[test]
fn geolens_datasets_are_added_page_by_page() {
    let page = |from: u32, to: u32, next: Option<&str>| {
        let features: Vec<Value> = (from..to)
            .map(|i| json!({"type": "Feature", "id": i, "properties": {"n": i}, "geometry": {"type": "Point", "coordinates": [f64::from(i % 90), 1.0]}}))
            .collect();
        let mut p = json!({"type": "FeatureCollection", "numberMatched": 1500, "numberReturned": features.len(), "features": features});
        if let Some(h) = next {
            p["links"] = json!([{"rel": "next", "type": "application/geo+json", "href": h}]);
        }
        p.to_string()
    };
    let search = r#"{"type": "FeatureCollection", "features": [{"type": "Feature", "id": "trees",
        "properties": {"title": "Street Trees", "record_type": "vector_dataset", "geometry_type": "POINT", "feature_count": 1500}}]}"#;
    let base = serve_routes(
        vec![
            ("/api/search/datasets/", search.to_string()),
            ("/api/collections/trees/items?limit=1000&after=1000", page(1000, 1500, None)),
            ("/api/collections/trees/items", page(0, 1000, Some("{base}/api/collections/trees/items?limit=1000&after=1000"))),
        ],
        8,
    );
    let mut s = Session::new(Project::default());
    let r = s.run("portal.search", &json!({"portal": "geolens", "url": base, "query": "trees"})).unwrap();
    let resource = &r["datasets"][0]["resources"][0];
    assert_eq!(resource["use"], "features", "{r}");
    let r = s.run("portal.add", &json!({"url": resource["url"], "use": resource["use"], "name": "Street Trees", "portal": base})).unwrap();
    assert_eq!(r["features"], 1500, "{r}");
    assert_eq!(s.map().layer_by_name("Street Trees").unwrap().dataset.features.len(), 1500);
}

/// A LAS 1.2 file of point format 0 in longitude/latitude: (x, y, z, class) per point.
fn las_bytes(points: &[(f64, f64, f64, u8)]) -> Vec<u8> {
    let mut b = vec![0u8; 227];
    b[0..4].copy_from_slice(b"LASF");
    b[24] = 1;
    b[25] = 2;
    b[94..96].copy_from_slice(&227u16.to_le_bytes());
    b[96..100].copy_from_slice(&227u32.to_le_bytes());
    b[105..107].copy_from_slice(&20u16.to_le_bytes());
    b[107..111].copy_from_slice(&(points.len() as u32).to_le_bytes());
    for k in 0..3 {
        b[131 + k * 8..139 + k * 8].copy_from_slice(&1e-6f64.to_le_bytes());
    }
    // max x, min x, max y, min y, max z, min z.
    for (at, v) in [(179, 11.0f64), (187, 10.0), (195, 51.0), (203, 50.0), (211, 400.0), (219, 300.0)] {
        b[at..at + 8].copy_from_slice(&v.to_le_bytes());
    }
    for p in points {
        let mut r = [0u8; 20];
        for (k, v) in [p.0, p.1, p.2].iter().enumerate() {
            r[k * 4..k * 4 + 4].copy_from_slice(&((v / 1e-6).round() as i32).to_le_bytes());
        }
        r[14] = 0x09;
        r[15] = p.3;
        b.extend_from_slice(&r);
    }
    b
}

/// LiDAR point clouds: read in place (a project keeps the file's path, not its points), coloured
/// by ASPRS class, from a path and from an upload.
#[test]
fn lidar_point_clouds() {
    use base64::Engine;
    let dir = std::env::temp_dir().join(format!("rustgis-lidar-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let pts: Vec<(f64, f64, f64, u8)> =
        (0..200).map(|i| (10.0 + f64::from(i) / 200.0, 50.5, 300.0 + f64::from(i % 50), if i % 2 == 0 { 2 } else { 6 })).collect();
    let path = dir.join("scan.las");
    std::fs::write(&path, las_bytes(&pts)).unwrap();
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!(r["streamed"], true, "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    let l = s.map().layer(id).unwrap();
    match &l.renderer {
        rustgis_map::Renderer::Unique { field, classes, .. } => {
            assert_eq!(field, "classification");
            let ground = classes.iter().find(|(v, _)| v == "2").unwrap();
            assert_eq!(ground.1.fill, rustgis_map::Rgba::rgb(0xA6, 0x7C, 0x52));
        }
        other => panic!("{other:?}"),
    }
    // The project names the file; reopened, the points are read from it again.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.contains("scan.las") && text.len() < 20_000, "{}", text.len());
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t.map().layer_by_name("scan").unwrap().source.as_ref().unwrap();
    assert!(again.is_open(), "{:?}", again.error);
    // An upload, and one class only: by elevation.
    let one: Vec<_> = pts.iter().map(|p| (p.0, p.1, p.2, 2)).collect();
    let b64 = base64::engine::general_purpose::STANDARD.encode(las_bytes(&one));
    let r = s.run("layer.addDataBytes", &json!({"fileName": "ground.las", "data": b64})).unwrap();
    let l = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
    assert!(matches!(&l.renderer, rustgis_map::Renderer::Graduated { field, .. } if field == "z"), "{:?}", l.renderer);
    // Not a point cloud.
    assert!(s.run("layer.addDataBytes", &json!({"fileName": "junk.laz", "data": "AAAA"})).is_err());
    let _ = std::fs::remove_dir_all(dir);
}

/// A layer read in place is counted by its source (#2678): `info.project` and `host.layers` give
/// the source's total in `features`, as `layer.addData` did, and what is in memory in `loaded`.
/// A source that can't say gives null, never 0.
#[test]
fn info_project_counts_a_layer_read_in_place_by_its_source() {
    isolate_plugins();
    let dir = std::env::temp_dir().join(format!("rustgis-count-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let pts: Vec<(f64, f64, f64, u8)> = (0..200).map(|i| (10.0 + f64::from(i) / 200.0, 50.5, 300.0, 2)).collect();
    let path = dir.join("scan.las");
    std::fs::write(&path, las_bytes(&pts)).unwrap();
    let mut s = Session::new(Project::default());
    let added = s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    assert_eq!((added["streamed"].as_bool(), added["features"].as_u64()), (Some(true), Some(200)), "{added}");
    let info = s.run("info.project", &json!({"nameFilter": "scan"})).unwrap();
    let scan = &info["layers"][0];
    assert_eq!(
        (scan["features"].as_u64(), scan["loaded"].as_u64(), scan["streamed"].as_bool()),
        (Some(200), Some(0), Some(true)),
        "{scan}"
    );
    plugin("eng-count", &[]);
    let layers = forward(&mut s, "eng-count", "host.layers", json!({})).unwrap();
    let scan = layers.as_array().unwrap().iter().find(|l| l["name"] == "scan").unwrap();
    assert_eq!(
        (scan["features"].as_u64(), scan["loaded"].as_u64(), scan["streamed"].as_bool()),
        (Some(200), Some(0), Some(true)),
        "{scan}"
    );
    // A layer held in memory: both numbers agree.
    let mut w = world();
    let info = w.run("info.project", &json!({"nameFilter": "Cities"})).unwrap();
    let cities = &info["layers"][0];
    assert!(cities["features"].as_u64().is_some_and(|n| n > 0), "{cities}");
    assert_eq!(
        (&cities["features"], &cities["loaded"], &cities["streamed"]),
        (&cities["loaded"], &cities["loaded"], &json!(false)),
        "{cities}"
    );
    // The file is gone when the project opens: the source can't say, so null, not 0.
    let text = serde_json::to_string(&s.project).unwrap();
    std::fs::remove_file(&path).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let info = t.run("info.project", &json!({"nameFilter": "scan"})).unwrap();
    let scan = &info["layers"][0];
    assert!(scan["features"].is_null() && scan["streamed"] == true && scan["loaded"] == 0, "{scan}");
    let _ = std::fs::remove_dir_all(dir);
}

/// A preview of an oversized cloud must never become a successful whole-data result.
#[test]
fn lidar_sample_refuses_exports_and_statistics() {
    let dir = std::env::temp_dir().join(format!("rustgis-lidar-limit-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("oversized.las");
    let count = rustgis_data::lidar::MAX_POINTS as u32 + 1;
    // Only a few records are needed: the header must retain its count even if the file ends early.
    let mut bytes = las_bytes(&[(10.0, 50.0, 300.0, 2), (10.5, 50.5, 310.0, 2)]);
    bytes[107..111].copy_from_slice(&count.to_le_bytes());
    std::fs::write(&path, bytes).unwrap();
    let mut s = Session::new(Project::default());
    let added = s.run("layer.addData", &json!({"path": path})).unwrap();
    assert_eq!(added["streamed"], true);
    let id = added["layer"].as_u64().unwrap() as u32;
    let output = dir.join("out.geojson");
    for (command, params) in [
        ("share.exportLayer", json!({"layer": id, "path": output})),
        ("gp.run", json!({"tool": "summaryStatistics", "params": {"input": "oversized", "field": "z"}})),
        ("layer.loadAll", json!({"layer": id})),
        ("layer.addData", json!({"path": path, "stream": false})),
    ] {
        let error = s.run(command, &params).unwrap_err();
        assert!(error.contains(&count.to_string()), "{command}: {error}");
        assert!(error.contains(&rustgis_data::lidar::MAX_POINTS.to_string()), "{command}: {error}");
    }
    assert!(!output.exists());
    assert_eq!(s.map().layers.len(), 1);
    std::fs::remove_dir_all(dir).unwrap();
}

/// The Zarr tests that read steps share the process's slice cache: one at a time, so another's
/// steps don't push out the one a test expects kept.
#[cfg(not(target_arch = "wasm32"))]
fn zarr_cache_lock() -> std::sync::MutexGuard<'static, ()> {
    static L: std::sync::Mutex<()> = std::sync::Mutex::new(());
    L.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
}

/// A Zarr store in a temporary folder: `t` over three monthly steps (days since 2001-01-01: 0,
/// 31, 59) on a 3 × 4 grid, step `k`'s values `100·k + i`.
#[cfg(not(target_arch = "wasm32"))]
fn zarr_store_over_time(tag: &str) -> (std::path::PathBuf, String) {
    zarr_store_at(tag, &[0, 31, 59])
}

/// A Zarr store of one variable, `t` (time × 3 × 4), with a step at each of `days` since 2001-01-01:
/// step `k`'s cells are `100 k + cell`.
#[cfg(not(target_arch = "wasm32"))]
fn zarr_store_at(tag: &str, days: &[i32]) -> (std::path::PathBuf, String) {
    let n = days.len();
    let dir = std::env::temp_dir().join(format!("rustgis-zarr-{tag}-{}", std::process::id()));
    let store = dir.join("air.zarr");
    let _ = std::fs::remove_dir_all(&dir);
    for d in ["t", "lat", "lon", "time"] {
        std::fs::create_dir_all(store.join(d)).unwrap();
    }
    let arr = |shape: &str, chunks: &str, dtype: &str| {
        serde_json::from_str::<Value>(&format!(
            r#"{{"shape":{shape},"chunks":{chunks},"dtype":"{dtype}","compressor":null,"fill_value":null,"filters":null,"order":"C","zarr_format":2}}"#
        ))
        .unwrap()
    };
    let meta = json!({"metadata": {
        ".zgroup": {"zarr_format": 2},
        "t/.zarray": arr(&format!("[{n},3,4]"), "[1,3,4]", "<f4"),
        "t/.zattrs": {"_ARRAY_DIMENSIONS": ["time","lat","lon"], "units": "K"},
        "lat/.zarray": arr("[3]", "[3]", "<f4"),
        "lat/.zattrs": {"_ARRAY_DIMENSIONS": ["lat"], "units": "degrees_north"},
        "lon/.zarray": arr("[4]", "[4]", "<f4"),
        "lon/.zattrs": {"_ARRAY_DIMENSIONS": ["lon"], "units": "degrees_east"},
        "time/.zarray": arr(&format!("[{n}]"), &format!("[{n}]"), "<i4"),
        "time/.zattrs": {"_ARRAY_DIMENSIONS": ["time"], "units": "days since 2001-01-01"},
    }, "zarr_consolidated_format": 1});
    std::fs::write(store.join(".zmetadata"), meta.to_string()).unwrap();
    std::fs::write(store.join(".zgroup"), r#"{"zarr_format":2}"#).unwrap();
    let f32s = |v: &[f32]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
    std::fs::write(store.join("lat/0"), f32s(&[10.0, 20.0, 30.0])).unwrap();
    std::fs::write(store.join("lon/0"), f32s(&[1.0, 2.0, 3.0, 4.0])).unwrap();
    std::fs::write(store.join("time/0"), days.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>()).unwrap();
    for t in 0..n {
        let v: Vec<f32> = (0..12).map(|i| (t * 100 + i) as f32).collect();
        std::fs::write(store.join(format!("t/{t}.0.0")), f32s(&v)).unwrap();
    }
    let path = store.display().to_string();
    (dir, path)
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn timed_zarr_open_failures_keep_status_without_store_credentials() {
    use ogc_server::{Route, Server};
    let _cache = zarr_cache_lock();
    let (dir, path) = zarr_store_over_time("private-open-errors");
    let store = std::path::Path::new(&path);
    let mut routes = Vec::new();
    for case in ["first", "selected"] {
        let root = format!("/{case}?token=hidden-zarr-open");
        for key in [".zmetadata", "lat/0", "lon/0", "time/0"] {
            routes.push(Route::bytes(&format!("{root}/{key}"), std::fs::read(store.join(key)).unwrap()));
        }
        if case == "selected" {
            routes.push(Route::bytes(&format!("{root}/t/0.0.0"), std::fs::read(store.join("t/0.0.0")).unwrap()));
        }
        let step = if case == "first" { 0 } else { 1 };
        routes.push(Route { status: 503, ..Route::new(&format!("{root}/t/{step}.0.0"), "") });
    }
    let server = Server::new(routes);
    for case in ["first", "selected"] {
        let mut s = Session::new(Project::default());
        if case == "selected" {
            s.run("time.set", &json!({"dates":["2001-01-01","2001-02-01","2001-03-01"],"date":"2001-02-01"})).unwrap();
        }
        let url = format!("{}/{case}?token=hidden-zarr-open", server.base);
        let error = s.run("layer.addZarr", &json!({"url":url,"variable":"t","time":true})).unwrap_err();
        assert!(error.contains("503") && !error.contains("hidden-zarr-open"), "{case}: {error}");
        assert!(s.map().layers.is_empty(), "an unreadable initial slice must not add a layer");
        let mark = s.notice_mark();
        s.notify(error, true);
        let notices = s.notices_since(mark);
        assert!(notices.iter().any(|n| n.error && n.text.contains("503")), "{case}: {notices:?}");
        assert!(notices.iter().all(|n| !n.text.contains("hidden-zarr-open")), "{case}: {notices:?}");
    }
    let requests = server.requests();
    for (case, chunk) in [("/first", "t/0.0.0"), ("/selected", "t/0.0.0"), ("/selected", "t/1.0.0")] {
        assert!(
            requests.iter().any(|r| r.path == case && r.query.iter().any(|(key, value)| key == "token" && value.ends_with(chunk))),
            "the first and selected slices must actually be read: {requests:?}"
        );
    }
    let _ = std::fs::remove_dir_all(dir);
}

/// A window of a folder store keeps its store through a save and reopen: a series at a point is
/// read from it, as from a whole slice (#1885).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_windows_series_after_reopening() {
    let _cache = zarr_cache_lock();
    let (dir, path) = zarr_store_over_time("window-reopen");
    // Removed however the test ends.
    struct Gone(std::path::PathBuf);
    impl Drop for Gone {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    let _gone = Gone(dir.clone());
    let mut s = Session::new(Project::default());
    let id = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "index": {"time": 1}, "cells": [0, 0, 2, 2]})).unwrap()["layer"]
        .as_u64()
        .unwrap();
    // At 1°E 20°N: the stored row 1, column 0, so 100·k + 4 at step k.
    let at = json!({"layer": id, "lon": 1.0, "lat": 20.0});
    assert_eq!(s.run("zarr.series", &at).unwrap()["values"], json!([4.0, 104.0, 204.0]));
    let saved = dir.join("window.rgis");
    s.run("project.saveAs", &json!({"path": saved.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": saved.display().to_string()})).unwrap();
    let id = t.map().layers.iter().find(|l| l.raster.is_some()).unwrap().id;
    // Read again from its GeoTIFF: the window, not the whole slice.
    let data = t.map().layer(id).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!((data.width, data.height), (2, 2));
    let r = t.run("zarr.series", &json!({"layer": id, "lon": 1.0, "lat": 20.0})).unwrap();
    assert_eq!(r["values"], json!([4.0, 104.0, 204.0]));
}

/// A Zarr variable's series at a point (#555): the values along its time dimension at the cell
/// holding it, read from the chunks holding that cell, through a layer or the store itself.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_series_at_a_point() {
    let _cache = zarr_cache_lock();
    let (dir, path) = zarr_store_over_time("series");
    let mut s = Session::new(Project::default());
    // At 1°E 30°N: the stored row 2 (latitudes 10, 20, 30), column 0, so 100·k + 8 at step k.
    let at = json!({"path": path, "variable": "t", "lon": 1.0, "lat": 30.0});
    let r = s.run("zarr.series", &at).unwrap();
    assert_eq!(r["values"], json!([8.0, 108.0, 208.0]), "{r}");
    assert_eq!(r["labels"], json!(["2001-01-01 00:00", "2001-02-01 00:00", "2001-03-01 00:00"]));
    assert_eq!(
        (r["dimension"].as_str(), r["units"].as_str(), r["row"].as_u64(), r["col"].as_u64()),
        (Some("time"), Some("K"), Some(2), Some(0))
    );
    // A point between centres takes the nearest (the axis starts half a cell before the first
    // centre): 24°N is the 20°N row, 26°N the 30°N row.
    let mut at =
        |lat: f64| s.run("zarr.series", &json!({"path": path, "variable": "t", "lon": 1.0, "lat": lat})).unwrap()["values"].clone();
    let (twenty, thirty) = (at(20.0), at(30.0));
    assert_eq!(at(24.0), twenty);
    assert_eq!(at(26.0), thirty);
    assert_ne!(twenty, thirty);
    // Longitudes either way round the globe; another cell.
    let r = s.run("zarr.series", &json!({"path": path, "variable": "t", "lon": 363.5, "lat": 11.0})).unwrap();
    assert_eq!(r["values"], json!([3.0, 103.0, 203.0]), "{r}");
    // A period.
    let r = s.run("zarr.series", &json!({"path": path, "variable": "t", "lon": 1.0, "lat": 30.0, "start": "2001-01-15"})).unwrap();
    assert_eq!(r["values"], json!([108.0, 208.0]));
    // Through a layer: one that follows the slider (its period), and a slice (the whole axis).
    let late = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "time": true, "start": "2001-01-20"})).unwrap()["layer"]
        .as_u64()
        .unwrap();
    let r = s.run("zarr.series", &json!({"layer": late, "lon": 1.0, "lat": 30.0})).unwrap();
    assert_eq!(r["values"], json!([108.0, 208.0]));
    let slice = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "index": {"time": 1}})).unwrap()["layer"].as_u64().unwrap();
    let r = s.run("zarr.series", &json!({"layer": slice, "lon": 1.0, "lat": 30.0})).unwrap();
    assert_eq!(r["values"], json!([8.0, 108.0, 208.0]));
    for bad in [
        json!({"path": path, "variable": "t", "lon": 50.0, "lat": 30.0}),
        json!({"path": path, "variable": "t", "lon": 1.0, "lat": 95.0}),
        json!({"path": path, "variable": "t", "lat": 30.0}),
        json!({"path": path, "variable": "t", "lon": 1.0, "lat": 30.0, "start": "2003-01-01"}),
        json!({"path": path, "variable": "lat", "lon": 1.0, "lat": 30.0}),
        json!({"path": "/nowhere/x.zarr", "lon": 1.0, "lat": 30.0}),
    ] {
        assert!(s.run("zarr.series", &bad).is_err(), "{bad}");
    }
    // A layer that isn't Zarr.
    let mut w = Session::new(sample::world_project());
    assert!(w.run("zarr.series", &json!({"layer": "Countries", "lon": 1.0, "lat": 30.0})).is_err());
    let _ = std::fs::remove_dir_all(dir);
}

/// UTM zone 17N on NAD 27 as PROJ 9.8.1 writes it in WKT2 without a code, bound to WGS 84 by the
/// NTv2 grid `conus` (`+proj=utm +zone=17 +datum=NAD27 +nadgrids=conus +type=crs`), with the
/// geographic system it's on bound the same way, and the notice a system read from a file gives
/// for it.
#[cfg(not(target_arch = "wasm32"))]
fn nad27_bound_by_conus() -> (String, String, &'static str) {
    let datum = r#"DATUM["North American Datum 1927",ELLIPSOID["Clarke 1866",6378206.4,294.978698213898,LENGTHUNIT["metre",1]],ID["EPSG",6267]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8901]]"#;
    let geog = format!(
        r#"GEOGCRS["unknown",{datum},CS[ellipsoidal,2],AXIS["longitude",east,ORDER[1],ANGLEUNIT["degree",0.0174532925199433,ID["EPSG",9122]]],AXIS["latitude",north,ORDER[2],ANGLEUNIT["degree",0.0174532925199433,ID["EPSG",9122]]]]"#
    );
    let utm = format!(
        r#"PROJCRS["unknown",BASEGEOGCRS["unknown",{datum}],CONVERSION["UTM zone 17N",METHOD["Transverse Mercator",ID["EPSG",9807]],PARAMETER["Latitude of natural origin",0,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8801]],PARAMETER["Longitude of natural origin",-81,ANGLEUNIT["degree",0.0174532925199433],ID["EPSG",8802]],PARAMETER["Scale factor at natural origin",0.9996,SCALEUNIT["unity",1],ID["EPSG",8805]],PARAMETER["False easting",500000,LENGTHUNIT["metre",1],ID["EPSG",8806]],PARAMETER["False northing",0,LENGTHUNIT["metre",1],ID["EPSG",8807]],ID["EPSG",16017]],CS[Cartesian,2],AXIS["(E)",east,ORDER[1],LENGTHUNIT["metre",1,ID["EPSG",9001]]],AXIS["(N)",north,ORDER[2],LENGTHUNIT["metre",1,ID["EPSG",9001]]]]"#
    );
    let wgs84 = r#"GEOGCRS["WGS 84",DATUM["World Geodetic System 1984",ELLIPSOID["WGS 84",6378137,298.257223563,LENGTHUNIT["metre",1]]],PRIMEM["Greenwich",0,ANGLEUNIT["degree",0.0174532925199433]],CS[ellipsoidal,2],AXIS["latitude",north,ORDER[1],ANGLEUNIT["degree",0.0174532925199433]],AXIS["longitude",east,ORDER[2],ANGLEUNIT["degree",0.0174532925199433]],ID["EPSG",4326]]"#;
    let bound = |source: &str| {
        format!(
            r#"BOUNDCRS[SOURCECRS[{source}],TARGETCRS[{wgs84}],ABRIDGEDTRANSFORMATION["unknown to WGS84",METHOD["NTv2",ID["EPSG",9615]],PARAMETERFILE["Latitude and longitude difference file","conus",ID["EPSG",8656]]]]"#
        )
    };
    let said = "the file's NTv2 transformation to WGS 84 (conus) isn't applied, so positions may be off by as much as that shift";
    (bound(&utm), bound(&geog), said)
}

/// [`zarr_store_at`]'s store over three months with `attrs` added to `t`'s, and, when `projected`,
/// its map in UTM zone 17N's metres instead of degrees: 1 km apart, around 500 km E 4800 km N.
#[cfg(not(target_arch = "wasm32"))]
fn zarr_store_with(tag: &str, attrs: &Value, projected: bool) -> (std::path::PathBuf, String) {
    zarr_store_with_days(tag, attrs, projected, &[0, 31, 59])
}

/// [`zarr_store_with`] at `days` (as [`zarr_store_at`] takes them).
#[cfg(not(target_arch = "wasm32"))]
fn zarr_store_with_days(tag: &str, attrs: &Value, projected: bool, days: &[i32]) -> (std::path::PathBuf, String) {
    let (dir, path) = zarr_store_at(tag, days);
    let store = std::path::Path::new(&path);
    let mut meta: Value = serde_json::from_slice(&std::fs::read(store.join(".zmetadata")).unwrap()).unwrap();
    let m = meta["metadata"].as_object_mut().unwrap();
    for (k, v) in attrs.as_object().unwrap() {
        m["t/.zattrs"][k.as_str()] = v.clone();
    }
    if projected {
        let f32s = |v: &[f32]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
        m["t/.zattrs"]["_ARRAY_DIMENSIONS"] = json!(["time", "y", "x"]);
        for (from, to) in [("lat", "y"), ("lon", "x")] {
            let arr = m.remove(&format!("{from}/.zarray")).unwrap();
            m.insert(format!("{to}/.zarray"), arr);
            m.remove(&format!("{from}/.zattrs"));
            m.insert(format!("{to}/.zattrs"), json!({"_ARRAY_DIMENSIONS": [to], "units": "m"}));
            std::fs::create_dir_all(store.join(to)).unwrap();
        }
        std::fs::write(store.join("y/0"), f32s(&[4_799_000.0, 4_800_000.0, 4_801_000.0])).unwrap();
        std::fs::write(store.join("x/0"), f32s(&[499_000.0, 500_000.0, 501_000.0, 502_000.0])).unwrap();
    }
    std::fs::write(store.join(".zmetadata"), meta.to_string()).unwrap();
    (dir, path)
}

/// A geographic store's datum is used to locate a WGS 84 query, including near a cell boundary.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_series_uses_its_geographic_datum() {
    let _cache = zarr_cache_lock();
    for def in ["+proj=longlat +ellps=intl +towgs84=0,10000,0 +no_defs", "EPSG:4326"] {
        let crs = rustgis_data::raster::Crs::parse(def).unwrap();
        let at = crs.transformer().unwrap().to_lonlat(rustgis_data::Coord::new(1.49, 30.0)).unwrap();
        if def != "EPSG:4326" {
            assert!(at.x > 1.5, "without the datum conversion this selects the adjacent cell: {at:?}");
        }
        let (dir, path) = zarr_store_with("series-geographic-datum", &json!({"crs": def}), false);
        let mut s = Session::new(Project::default());
        let r = s.run("zarr.series", &json!({"path": path, "variable": "t", "lon": at.x, "lat": at.y})).unwrap();
        assert_eq!(r["values"], json!([8.0, 108.0, 208.0]), "{def}: {r}");
        std::fs::remove_dir_all(dir).unwrap();
    }
}

/// Slices and point series agree about degree-axis fallbacks, including a caller system that
/// isn't used. Explicit WGS 84 is not an assumption.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn zarr_slices_and_series_disclose_the_same_lonlat_fallback() {
    let _cache = zarr_cache_lock();
    for (attrs, typed, assumed, ignored) in [
        (json!({}), None, true, false),
        (json!({"crs":"EPSG:4326"}), None, false, false),
        (json!({"crs":"EPSG:32617"}), None, true, false),
        (json!({}), Some("EPSG:3035"), true, true),
        (json!({}), Some("EPSG:4326"), false, false),
        (json!({"crs":"EPSG:4230"}), Some("EPSG:3035"), false, false),
    ] {
        let (dir, path) = zarr_store_with("lonlat-fallback", &attrs, false);
        for command in ["layer.addZarr", "zarr.series"] {
            let mut s = Session::new(Project::default());
            let mark = s.notice_mark();
            let mut params = json!({"path":path,"variable":"t","index":{"time":0},"lon":1.0,"lat":30.0});
            if let Some(crs) = typed {
                params["crs"] = json!(crs);
            }
            let expected_crs = if attrs["crs"] == "EPSG:4230" {
                rustgis_data::raster::Crs::from_epsg(4230).unwrap()
            } else {
                rustgis_data::raster::Crs::LonLat
            };
            let result = s.run(command, &params).unwrap();
            if command == "zarr.series" {
                assert_eq!(result["values"], json!([8.0, 108.0, 208.0]));
            } else {
                let r = s.map().layers.last().unwrap().raster.as_ref().unwrap().data.as_ref().unwrap();
                assert_eq!(r.crs, expected_crs);
                assert_eq!(r.value(0, 0, 0), Some(8.0));
            }
            let notices = s.notices_since(mark);
            let fallbacks: Vec<_> = notices.iter().filter(|n| n.text.contains("so it's read as WGS 84")).collect();
            assert_eq!(fallbacks.len(), usize::from(assumed), "{command}, {attrs}, {typed:?}: {notices:?}");
            if ignored {
                assert!(fallbacks[0].text.contains("EPSG:3035") && fallbacks[0].text.contains("isn't used"), "{notices:?}");
                assert!(!fallbacks[0].text.contains("doesn't say"), "{notices:?}");
            }
        }
        std::fs::remove_dir_all(dir).unwrap();
    }
}

/// A store's own system bound to WGS 84 by a grid (NAD 27 by `conus`) isn't applied where a series
/// places its point, which it says once, on a longitude/latitude grid or a projected one; WGS 84's
/// systems say nothing (#1678).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_series_says_a_grid_its_store_doesnt_apply() {
    let _cache = zarr_cache_lock();
    let (utm, geog, said) = nad27_bound_by_conus();
    // Of the variable: no `crs` was given.
    let said = format!("t: {said}");
    let wgs84 = rustgis_data::raster::wkt::to_wkt(rustgis_data::raster::Crs::LonLat).unwrap();
    // On UTM zone 17N's central meridian, in the middle cell.
    let at = rustgis_data::raster::Crs::from_epsg(32617)
        .unwrap()
        .transformer()
        .unwrap()
        .to_lonlat(rustgis_data::Coord::new(500_000.0, 4_800_000.0))
        .unwrap();
    for (projected, attrs, expected) in [
        (false, json!({"crs_wkt": geog}), 1),
        (false, json!({"crs_wkt": wgs84}), 0),
        (true, json!({"crs_wkt": utm}), 1),
        (true, json!({"epsg_code": 32617}), 0),
    ] {
        let (dir, path) = zarr_store_with("series-grid", &attrs, projected);
        let (lon, lat) = if projected { (at.x, at.y) } else { (1.0, 30.0) };
        let mut s = Session::new(Project::default());
        let mark = s.notice_mark();
        let r = s.run("zarr.series", &json!({"path": path, "variable": "t", "lon": lon, "lat": lat})).unwrap();
        assert_eq!(r["values"].as_array().map(Vec::len), Some(3), "{attrs}: {r}");
        // The notice, and every notice of a transformation not applied or missing: only it, or none.
        let notices = s.notices_since(mark);
        let shifts = notices
            .iter()
            .filter(|n| {
                n.text.contains("isn't applied") || n.text.contains("has no transformation") || n.text.contains("has no conversion")
            })
            .count();
        assert_eq!((notices.iter().filter(|n| n.text == said).count(), shifts), (expected, expected), "{attrs}: {notices:?}");
        let _ = std::fs::remove_dir_all(dir);
    }
}

/// A `crs` typed for a Zarr store (UTM zone 17N on NAD 27, bound to WGS 84 by `conus`) says its
/// grid isn't applied only when the slice is in it: a store that gives no system of its own, as a
/// slice or a layer following the time slider. A store that gives its own (WGS 84's UTM zone 17N,
/// or the typed system itself) and a longitude/latitude grid don't use it, and say nothing of it:
/// the store that gives the typed system says its grid once, as its own (#1678).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_slice_says_a_typed_grid_only_when_it_uses_it() {
    let _cache = zarr_cache_lock();
    let (typed, _, _) = nad27_bound_by_conus();
    for (attrs, projected, expected) in
        [(json!({}), true, 1), (json!({"epsg_code": 32617}), true, 0), (json!({}), false, 0), (json!({"crs_wkt": typed}), true, 1)]
    {
        let (dir, path) = zarr_store_with("typed-grid", &attrs, projected);
        for following in [false, true] {
            let mut s = Session::new(Project::default());
            let mark = s.notice_mark();
            let mut p = json!({"path": path, "variable": "t", "crs": typed});
            if following {
                p["time"] = json!(true);
            } else {
                p["index"] = json!({"time": 1});
            }
            s.run("layer.addZarr", &p).unwrap();
            let notices = s.notices_since(mark);
            let shifts = notices.iter().filter(|n| n.text.contains("isn't applied") || n.text.contains("has no conversion")).count();
            let said = notices.iter().filter(|n| n.text.contains("(conus) isn't applied")).count();
            assert_eq!((said, shifts), (expected, expected), "{attrs} following={following}: {notices:?}");
            // The typed system's own notice only where it's used: a store that gives the same
            // system says it as the file's.
            let typed_said = notices.iter().filter(|n| n.text.contains("the definition's")).count();
            assert_eq!(typed_said, usize::from(attrs == json!({}) && projected), "{attrs} following={following}: {notices:?}");
        }
        let _ = std::fs::remove_dir_all(dir);
    }
}

/// A store by web address is kept in the project as a GeoTIFF, whose keys say the store's geographic
/// system: another body's (in an ESRI PE citation) as WGS 84 is (#2008). A system the keys couldn't
/// say is refused saying so (`zarr::write_project_slice`, tested in `zarr`).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_web_zarr_keeps_its_geographic_system_through_its_geotiff() {
    let f64s = |v: [f64; 2]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
    let coords = |dim: &str| {
        json!({"zarr_format": 3, "node_type": "array", "shape": [2], "data_type": "float64",
            "chunk_grid": {"name": "regular", "configuration": {"chunk_shape": [2]}},
            "codecs": [{"name": "bytes", "configuration": {"endian": "little"}}], "fill_value": 0, "dimension_names": [dim]})
    };
    let mars = r#"GEOGCS["Mars 2000",DATUM["D_Mars_2000",SPHEROID["Mars_2000_IAU_IAG",3396190,169.89444722361179]],PRIMEM["Reference_Meridian",0],UNIT["Degree",0.0174532925199433]]"#;
    for (name, crs_wkt, planetary) in [("mars", mars, true), ("wgs84", "EPSG:4326", false)] {
        let elev = json!({"zarr_format": 3, "node_type": "array", "shape": [2, 2], "data_type": "int16",
            "chunk_grid": {"name": "regular", "configuration": {"chunk_shape": [2, 2]}},
            "chunk_key_encoding": {"name": "default", "configuration": {"separator": "/"}},
            "codecs": [{"name": "bytes", "configuration": {"endian": "little"}}],
            "fill_value": 0, "dimension_names": ["lat", "lon"], "attributes": {"crs_wkt": crs_wkt}});
        let root = json!({"zarr_format": 3, "node_type": "group", "consolidated_metadata": {"kind": "inline", "metadata": {
            "elev": elev, "lat": coords("lat"), "lon": coords("lon")}}});
        let (base, _) = serve_ranged_files(vec![
            (format!("/{name}.zarr/zarr.json"), root.to_string().into_bytes()),
            (format!("/{name}.zarr/elev/c/0/0"), [1i16, 2, 3, 4].iter().flat_map(|v| v.to_le_bytes()).collect()),
            (format!("/{name}.zarr/lat/c/0"), f64s([43.1, 43.0])),
            (format!("/{name}.zarr/lon/c/0"), f64s([-79.1, -79.0])),
        ]);
        let mut s = Session::new(Project::default());
        let result = s.run("layer.addZarr", &json!({"url": format!("{base}/{name}.zarr"), "variable": "elev"}));
        let id = result.unwrap_or_else(|e| panic!("{name}: {e}"))["layer"].as_u64().unwrap() as u32;
        let raster = s.map().layer(id).unwrap().raster.as_ref().unwrap().data.as_ref().unwrap();
        assert!(raster.crs.is_geographic() && raster.crs.is_planetary() == planetary, "{name}: {:?}", raster.crs);
        assert_eq!(raster.crs == rustgis_data::raster::Crs::LonLat, !planetary, "{name}");
        // Mars's own ellipsoid, in degrees, not a sphere or another body's.
        if planetary {
            let def = raster.crs.custom_def().unwrap().proj4.clone();
            assert!(def.starts_with("+proj=longlat ") && def.contains("+a=3396190 ") && def.contains("+rf=169.8944472236"), "{def}");
            let at = raster.crs.transformer().unwrap().to_lonlat(rustgis_geom::Coord::new(-79.05, 43.05)).unwrap();
            assert!((at.x + 79.05).abs() < 1e-12 && (at.y - 43.05).abs() < 1e-12, "{at:?}");
        }
        assert_eq!(raster.bands[0].data, [1.0, 2.0, 3.0, 4.0], "{name}");
    }
}

/// A summary or trend of a store whose own system is bound to WGS 84 by a grid (UTM zone 17N on NAD
/// 27 by `conus`) says once that the grid isn't applied, as its slices do; WGS 84's zone says nothing
/// (#1678).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_summary_says_a_grid_its_store_doesnt_apply() {
    let _cache = zarr_cache_lock();
    let (utm, _, said) = nad27_bound_by_conus();
    for (attrs, expected) in [(json!({"crs_wkt": utm}), 1), (json!({"epsg_code": 32617}), 0)] {
        // Four dates, as a trend needs.
        let (dir, path) = zarr_store_with_days("reduce-grid", &attrs, true, &[0, 31, 59, 90]);
        // Zarr's own summary, and the data cube's summary and trend: each says it once, though a
        // trend adds four layers.
        for (cmd, extra) in [("zarr.reduce", json!({"stat": "mean"})), ("cube.reduce", json!({"stat": "mean"})), ("cube.trend", json!({}))]
        {
            let mut s = Session::new(Project::default());
            let mark = s.notice_mark();
            let mut p = json!({"path": path, "variable": "t"});
            p.as_object_mut().unwrap().extend(extra.as_object().unwrap().clone());
            s.run(cmd, &p).unwrap_or_else(|e| panic!("{cmd}: {e}"));
            let notices = s.notices_since(mark);
            let shifts = notices.iter().filter(|n| n.text.contains("isn't applied") || n.text.contains("has no transformation")).count();
            let of = notices.iter().filter(|n| n.text.ends_with(said)).count();
            assert_eq!((of, shifts), (expected, expected), "{cmd} {attrs}: {notices:?}");
        }
        let _ = std::fs::remove_dir_all(dir);
    }
}

/// A Zarr variable summarised over time (#556): each statistic, a season, a period and a layer's
/// period, into a raster layer kept in the project.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_variable_summarised_over_time() {
    let _cache = zarr_cache_lock();
    let (dir, path) = zarr_store_over_time("reduce");
    let mut s = Session::new(Project::default());
    // The first pixel (north up) is the stored cell 8: 8, 108 and 208 at the three steps.
    let first = |s: &Session, r: &Value| {
        let l = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
        let d = l.raster.as_ref().unwrap().data.clone().unwrap();
        d.bands[0].data[0]
    };
    for (stat, want) in [("mean", 108.0), ("min", 8.0), ("max", 208.0), ("sum", 324.0), ("count", 3.0)] {
        let r = s.run("zarr.reduce", &json!({"path": path, "variable": "t", "stat": stat})).unwrap();
        assert_eq!(first(&s, &r), want, "{stat}");
        assert_eq!(r["steps"], 3);
    }
    let r = s.run("zarr.reduce", &json!({"path": path, "variable": "t", "stat": "std"})).unwrap();
    assert!((first(&s, &r) - 81.649_66).abs() < 1e-3, "{}", first(&s, &r));
    let r = s.run("zarr.reduce", &json!({"path": path, "variable": "t", "stat": "countAbove", "above": 150})).unwrap();
    assert_eq!(first(&s, &r), 1.0);
    // A season (February alone), and a period.
    let r = s.run("zarr.reduce", &json!({"path": path, "variable": "t", "stat": "mean", "months": [2]})).unwrap();
    assert_eq!(first(&s, &r), 108.0);
    let name = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().name.clone();
    assert!(name.starts_with("t mean 2001-02-01–2001-02-01 (months 2)"), "{name}");
    let r = s.run("zarr.reduce", &json!({"path": path, "variable": "t", "stat": "mean", "start": "2001-01-15"})).unwrap();
    assert_eq!(first(&s, &r), 158.0);
    // Through a layer that follows the slider: its period.
    let late = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "time": true, "start": "2001-01-20"})).unwrap()["layer"]
        .as_u64()
        .unwrap();
    let r = s.run("zarr.reduce", &json!({"layer": late, "stat": "max", "name": "warmest"})).unwrap();
    assert_eq!(first(&s, &r), 208.0);
    assert!(s.map().layer_by_name("warmest").is_some());
    // Kept in the project as a GeoTIFF, read again.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t.map().layer_by_name("warmest").and_then(|l| l.raster.as_ref()).and_then(|r| r.data.clone()).unwrap();
    assert_eq!(again.bands[0].data[0], 208.0);
    // A step never written (its chunk absent) is Zarr's fill value: no value that step, so the
    // summary goes on with the others.
    let (gap_dir, gap) = zarr_store_over_time("reduce-gap");
    std::fs::remove_file(std::path::Path::new(&gap).join("t/1.0.0")).unwrap();
    let r = s.run("zarr.reduce", &json!({"path": gap, "variable": "t", "stat": "count"})).unwrap();
    assert_eq!(first(&s, &r), 2.0);
    let r = s.run("zarr.reduce", &json!({"path": gap, "variable": "t", "stat": "mean"})).unwrap();
    assert_eq!(first(&s, &r), 108.0);
    let _ = std::fs::remove_dir_all(gap_dir);
    for bad in [
        json!({"path": path, "variable": "t"}),
        json!({"path": path, "variable": "t", "stat": "median"}),
        json!({"path": path, "variable": "t", "stat": "countAbove"}),
        json!({"path": path, "variable": "t", "stat": "mean", "months": [13]}),
        json!({"path": path, "variable": "t", "stat": "mean", "months": "June"}),
        json!({"path": path, "variable": "t", "stat": "mean", "minValid": 1.5}),
        json!({"path": path, "variable": "t", "stat": "mean", "start": "2005-01-01"}),
        json!({"path": path, "variable": "lat", "stat": "mean"}),
    ] {
        assert!(s.run("zarr.reduce", &bad).is_err(), "{bad}");
    }
    let _ = std::fs::remove_dir_all(dir);
}

/// Where nothing but a shell waits on them (`rustgis-cli run`: `long_runs` set), a trend and a
/// summary tell their progress up to its end and give what they give anywhere else; and there a
/// STAC trend's or summary's search takes more items than in the app (a state's four MODIS tiles
/// over 25 years are 2,304).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_trend_where_nothing_waits_tells_its_progress() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    use std::sync::Mutex;
    // What was told, by this test alone: no other test sets `long_runs` with this `tell`.
    static TOLD: Mutex<Vec<(String, f64)>> = Mutex::new(Vec::new());
    fn tell(what: &str, share: f64) {
        assert!((0.0..=1.0).contains(&share), "{what}: {share}");
        TOLD.lock().unwrap().push((what.to_string(), share));
    }
    // The last share each run told: its end, 1, however soon it finished, and told only then.
    let ended = |what: &str| {
        let told = TOLD.lock().unwrap();
        let ends = told.iter().filter(|(w, x)| w == what && *x >= 1.0).count();
        assert!(ends <= 1, "{what} told its end {ends} times");
        told.iter().rev().find(|(w, _)| w == what).map(|(_, x)| *x)
    };
    let gt = GeoTransform { origin_x: -56.0, origin_y: -12.0, pixel_width: 0.01, pixel_height: -0.01 };
    let slope = |s: &mut Session| {
        let mut names = Vec::new();
        for (k, y) in (2013..2025).enumerate() {
            let name = format!("ndvi_{y}-07-01");
            let r = Raster::new(&name, 2, 1, vec![vec![0.3 + 0.02 * k as f32, 0.5]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32")
                .unwrap();
            let bytes = geotiff::write(&r, 0).unwrap();
            crate::cmd::raster::add_raster(s, &name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
            names.push(name);
        }
        let band = |s: &Session, r: &Value| {
            let id = r["layers"][0].as_u64().unwrap() as u32;
            s.map().layer(id).unwrap().raster.as_ref().unwrap().data.clone().unwrap().bands[0].data.clone()
        };
        let trend = s.run("cube.trend", &json!({"layers": names})).unwrap();
        let mean = s.run("cube.reduce", &json!({"layers": names, "stat": "mean"})).unwrap();
        (band(s, &trend), band(s, &mean))
    };
    let mut plain = Session::new(Project::default());
    let mut told = Session::new(Project::default());
    told.long_runs = Some(tell);
    let ((a, mean_a), (b, mean_b)) = (slope(&mut plain), slope(&mut told));
    assert_eq!(a, b);
    assert_eq!(mean_a, mean_b);
    assert!((a[0] - 0.02).abs() < 1e-4, "{a:?}");
    assert!((mean_a[0] - 0.41).abs() < 1e-5 && (mean_a[1] - 0.5).abs() < 1e-6, "{mean_a:?}");
    assert_eq!(ended("cube.trend"), Some(1.0), "the trend's progress is told to its end");
    assert_eq!(ended("cube.reduce"), Some(1.0), "the summary's progress is told to its end");
    // 2,100 items (a tile each, one day) in eleven pages of 200: too many for the time slider and
    // for a trend in the app, not for a trend or a summary where nothing waits, which go on to
    // read their first file (here on a closed port).
    let item = |k: usize| {
        format!(
            r#"{{"type": "Feature", "id": "i{k}", "collection": "c", "bbox": [10, 45, 11, 46], "geometry": null, "properties": {{"datetime": "2024-01-01T00:00:00Z", "bdc:tiles": ["t{k}"]}}, "assets": {{"NDVI": {{"href": "http://127.0.0.1:9/i{k}.tif"}}}}}}"#
        )
    };
    let page = |n: usize| {
        let items: Vec<String> = (n * 200..((n + 1) * 200).min(2100)).map(item).collect();
        let next = if (n + 1) * 200 < 2100 {
            format!(r#", "links": [{{"rel": "next", "href": "{{base}}/v1/search?page=p{:02}"}}]"#, n + 1)
        } else {
            String::new()
        };
        format!(r#"{{"type": "FeatureCollection", "features": [{}]{next}}}"#, items.join(","))
    };
    // The pages by their marks first: the search's own address is a prefix of theirs.
    const MARKS: [&str; 10] = [
        "/v1/search?page=p01",
        "/v1/search?page=p02",
        "/v1/search?page=p03",
        "/v1/search?page=p04",
        "/v1/search?page=p05",
        "/v1/search?page=p06",
        "/v1/search?page=p07",
        "/v1/search?page=p08",
        "/v1/search?page=p09",
        "/v1/search?page=p10",
    ];
    let mut routes: Vec<(&'static str, String)> = MARKS.iter().enumerate().map(|(i, m)| (*m, page(i + 1))).collect();
    routes.push(("/v1/search", page(0)));
    // Eleven pages for each of the four searches, with room to spare.
    let api = format!("{}/v1", serve_routes(routes, 60));
    let p = json!({"url": api, "collection": "c", "asset": "NDVI", "bbox": [10, 45, 11, 46], "start": "2024", "end": "2024"});
    let e = plain.run("stac.addCube", &p).unwrap_err();
    assert!(e.contains("more than 2000 items"), "{e}");
    let e = plain.run("cube.trend", &p).unwrap_err();
    assert!(e.contains("more than 2000 items"), "the app's trend doesn't take them: {e}");
    // Taken, they go on to the first file, which can't be read.
    let e = told.run("cube.trend", &p).unwrap_err();
    assert!(e.contains("127.0.0.1:9/i") && !e.contains("items"), "a trend takes them: {e}");
    let mut summary = p.clone();
    summary["stat"] = json!("mean");
    let e = told.run("cube.reduce", &summary).unwrap_err();
    assert!(e.contains("127.0.0.1:9/i") && !e.contains("items"), "a summary takes them: {e}");
}

/// A trend over a data cube (#579), from the three kinds of cube: a stack of raster layers dated
/// by their names, a raster whose bands are dates, and a Zarr variable along its time dimension.
/// A cell with a clear trend gets Sen's slope and a significant slope; noise gets a slope but no
/// significant one; a cell with too few values gets nothing.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_trend_over_a_data_cube() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let mut s = Session::new(Project::default());
    let gt = GeoTransform { origin_x: -56.0, origin_y: -12.0, pixel_width: 0.01, pixel_height: -0.01 };
    // Twelve years; cell 0 rises 0.02 a year, cell 1 is noise, cell 2 has three values only.
    let years: Vec<i32> = (2013..2025).collect();
    let noise = [0.03, -0.02, 0.05, -0.04, 0.01, 0.0, -0.05, 0.04, -0.01, 0.02, -0.03, 0.03];
    let cells = |k: usize| -> Vec<f32> {
        vec![0.3 + 0.02 * k as f32 + 0.002 * noise[k] as f32, 0.5 + noise[k] as f32, if k < 3 { 0.4 } else { f32::NAN }, 0.6]
    };
    let mut names = Vec::new();
    for (k, y) in years.iter().enumerate() {
        let name = format!("ndvi_{y}-07-01");
        let r = Raster::new(&name, 2, 2, vec![cells(k)], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
        let bytes = geotiff::write(&r, 0).unwrap();
        crate::cmd::raster::add_raster(&mut s, &name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
        names.push(name);
    }
    let value = |s: &Session, id: &Value, cell: usize| {
        s.map().layer(id.as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap().bands[0].data[cell]
    };
    let r = s.run("cube.trend", &json!({"layers": names})).unwrap();
    let ids = r["layers"].as_array().unwrap().clone();
    assert_eq!((ids.len(), r["dates"].as_u64()), (4, Some(12)), "{r}");
    let (slope, p, significant) = (&ids[0], &ids[2], &ids[3]);
    assert!((value(&s, slope, 0) - 0.02).abs() < 1e-3, "{}", value(&s, slope, 0));
    assert!(value(&s, p, 0) < 0.01 && (value(&s, significant, 0) - 0.02).abs() < 1e-3);
    assert!(value(&s, slope, 1).is_finite() && value(&s, p, 1) > 0.05 && value(&s, significant, 1).is_nan());
    assert!(value(&s, slope, 2).is_nan() && value(&s, p, 2).is_nan());
    // A constant cell: no slope, and nothing significant.
    assert_eq!(value(&s, slope, 3), 0.0);
    assert!(value(&s, significant, 3).is_nan());
    let name = |id: &Value| s.map().layer(id.as_u64().unwrap() as u32).unwrap().name.clone();
    assert_eq!(name(slope), "ndvi 2013-07-01–2024-07-01 Sen slope per year");
    assert!(name(&ids[1]).ends_with("Z (Hamed-Rao)"), "{}", name(&ids[1]));
    // Per decade, another test, a period, and the dates given.
    let r = s.run("cube.trend", &json!({"layers": names, "per": "decade", "test": "yueWang", "start": "2016", "name": "late"})).unwrap();
    let late = r["layers"][0].clone();
    assert_eq!(r["dates"], 9);
    assert!((value(&s, &late, 0) - 0.2).abs() < 1e-2, "{}", value(&s, &late, 0));
    // An end given as a year takes all of it: 2013 to 2020's July, eight dates (read as 1 January
    // 2020, it would leave 2020's out).
    let r = s.run("cube.trend", &json!({"layers": names, "end": "2020", "name": "to2020"})).unwrap();
    assert_eq!(r["dates"], 8, "{r}");
    let r = s.run("cube.trend", &json!({"layers": names, "end": "2020-06", "name": "toJune"})).unwrap();
    assert_eq!(r["dates"], 7, "a month ends with it: 2020's July date is after June: {r}");
    // A year given as a number reads the same.
    let r = s.run("cube.trend", &json!({"layers": names, "end": 2020, "name": "to2020n"})).unwrap();
    assert_eq!(r["dates"], 8, "{r}");
    // A full date is that day, as before: 1 January 2020 leaves 2020's July out, its 1 July keeps it.
    let r = s.run("cube.trend", &json!({"layers": names, "end": "2020-01-01", "name": "toNewYear"})).unwrap();
    assert_eq!(r["dates"], 7, "{r}");
    let r = s.run("cube.trend", &json!({"layers": names, "end": "2020-07-01", "name": "toJuly"})).unwrap();
    assert_eq!(r["dates"], 8, "{r}");
    let backwards: Vec<String> = (0..12).map(|k| format!("{}-01-01", 2030 - k)).collect();
    let r = s.run("cube.trend", &json!({"layers": names, "dates": backwards, "test": "original"})).unwrap();
    assert!(value(&s, &r["layers"][0], 0) < 0.0, "the dates given are used, in the layers' order");
    // A raster whose bands are the dates, named by them.
    let bands: Vec<Vec<f32>> = (0..12).map(cells).collect();
    let mut cube = Raster::new("stack", 2, 2, bands, gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    for (b, y) in cube.bands.iter_mut().zip(&years) {
        b.name = format!("NDVI {y}");
    }
    let bytes = geotiff::write(&cube, 0).unwrap();
    let id =
        crate::cmd::raster::add_raster(&mut s, "stack", rustgis_map::RasterLayer::from_bytes(cube, "stack.tif", bytes)).unwrap()["layer"]
            .clone();
    let r = s.run("cube.trend", &json!({"layer": id})).unwrap();
    assert!((value(&s, &r["layers"][0], 0) - 0.02).abs() < 1e-3);
    // Two bands on one date are refused, as two layers are.
    let same: Vec<String> = (0..12).map(|k| format!("{}-06-01", 2000 + k.max(1))).collect();
    let e = s.run("cube.trend", &json!({"layer": id, "dates": same})).unwrap_err();
    assert!(e.contains("same date"), "{e}");
    // A Zarr variable: every cell rises 100 a step.
    let (dir, path) = zarr_store_at("trend", &[0, 31, 59, 90, 120, 151, 181, 212]);
    let r = s.run("cube.trend", &json!({"path": path, "variable": "t", "test": "seasonal", "seasons": 4})).unwrap();
    assert_eq!(r["dates"], 8);
    assert!(value(&s, &r["layers"][0], 0) > 1000.0, "{}", value(&s, &r["layers"][0], 0));
    let _ = std::fs::remove_dir_all(dir);
    // A step never written (its chunk absent) has no value; the trend goes on with the others.
    let (gap_dir, gap) = zarr_store_at("trend-gap", &[0, 31, 59, 90, 120, 151, 181, 212]);
    std::fs::remove_file(std::path::Path::new(&gap).join("t/3.0.0")).unwrap();
    let r = s.run("cube.trend", &json!({"path": gap, "variable": "t", "test": "original"})).unwrap();
    assert!(value(&s, &r["layers"][0], 0) > 1000.0, "{}", value(&s, &r["layers"][0], 0));
    let _ = std::fs::remove_dir_all(gap_dir);
    // Refused: too few layers, no dates, dates of another length, unknown options.
    for bad in [
        json!({"layers": &names[..3]}),
        json!({"layers": names, "dates": ["2001", "2002"]}),
        json!({"layers": names, "test": "ols"}),
        json!({"layers": names, "alpha": 0.7}),
        json!({"layers": names, "per": "week"}),
        json!({"layers": names, "start": "2030"}),
        json!({"layer": names[0]}),
    ] {
        assert!(s.run("cube.trend", &bad).is_err(), "{bad}");
    }
    let undated = Raster::new("plain", 2, 2, vec![vec![0.0; 4]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let bytes = geotiff::write(&undated, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "plain", rustgis_map::RasterLayer::from_bytes(undated, "plain.tif", bytes)).unwrap();
    let mut no_date = names[..4].to_vec();
    no_date[1] = "plain".into();
    let e = s.run("cube.trend", &json!({"layers": no_date})).unwrap_err();
    assert!(e.contains("no date in the name of plain"), "{e}");
    // A run the app no longer keeps is said, never worked out again here.
    let e = s.run("cube.trend", &json!({"ran": 987_654_321u64})).unwrap_err();
    assert!(e.contains("no longer kept"), "{e}");
    // A run kept by one session is that session's: another one (Python, tests side by side)
    // doesn't take it, and it is added once.
    let kept = Raster::new("kept", 2, 2, vec![vec![0.0; 4]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let ran = crate::cmd::cube::land(&mut s, vec![kept], 12);
    let mut other = Session::new(Project::default());
    assert!(other.run("cube.trend", &json!({"ran": ran})).unwrap_err().contains("no longer kept"));
    assert_eq!(s.run("cube.trend", &json!({"ran": ran})).unwrap()["dates"], 12);
    assert!(s.run("cube.trend", &json!({"ran": ran})).is_err());
    let e = s.run("cube.trend", &json!({"layers": names, "minValid": 99})).unwrap_err();
    assert!(e.contains("more than the"), "{e}");
    // Two layers on one day would count twice in the test: refused.
    let mut twice: Vec<String> = (0..names.len()).map(|k| format!("{}-06-01", 2010 + k)).collect();
    twice[1] = twice[0].clone();
    let e = s.run("cube.trend", &json!({"layers": names, "dates": twice})).unwrap_err();
    assert!(e.contains("same date"), "{e}");
    // Seasons from the calendar: the 1st of every month is its month in every year, leap years
    // included, and a 16-day composite on the same day each year keeps its season.
    use crate::cmd::cube::season_of;
    let day = |d: &str| rustgis_data::time::parse_text(d).unwrap();
    for y in 2000..2010 {
        for m in 1..=12 {
            assert_eq!(season_of(day(&format!("{y}-{m:02}-01")), 12), m - 1, "{y}-{m}");
        }
        assert_eq!(season_of(day(&format!("{y}-01-17")), 23), 1, "{y}");
        assert_eq!(season_of(day(&format!("{y}-12-19")), 23), 22, "{y}");
    }
    // A monthly cube dated on the 1st, with a yearly cycle and a rise: the seasonal test finds it
    // per year and per decade alike.
    let mut monthly = Vec::new();
    for y in 2015..2021 {
        for m in 1..=12 {
            let k = (y - 2015) * 12 + (m - 1);
            let v = 0.5 + 0.2 * (std::f32::consts::TAU * (m - 1) as f32 / 12.0).sin() + 0.01 * k as f32 / 12.0;
            let name = format!("evi_{y}-{m:02}-01");
            let r = Raster::new(&name, 1, 1, vec![vec![v]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
            let bytes = geotiff::write(&r, 0).unwrap();
            crate::cmd::raster::add_raster(&mut s, &name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
            monthly.push(name);
        }
    }
    for (per, want) in [("year", 0.01), ("decade", 0.1)] {
        let r = s.run("cube.trend", &json!({"layers": monthly, "test": "seasonal", "per": per})).unwrap();
        let slope = value(&s, &r["layers"][0], 0);
        assert!((slope - want).abs() < want * 0.05, "{per}: {slope}");
        assert!(value(&s, &r["layers"][2], 0) < 0.01, "{per}: significant");
    }
}

/// A multi-band Float32 GeoTIFF in longitude/latitude, its bands' values interleaved, as GDAL
/// writes it: `descriptions` in its GDAL_METADATA tag when given, and -9999 for no-data.
#[cfg(not(target_arch = "wasm32"))]
pub(crate) fn multiband_tiff(w: u32, h: u32, bands: &[Vec<f32>], origin: (f64, f64), px: f64, descriptions: Option<&[String]>) -> Vec<u8> {
    let n = bands.len() as u16;
    let mut out = vec![b'I', b'I', 42, 0, 0, 0, 0, 0];
    for p in 0..(w * h) as usize {
        for b in bands {
            out.extend(b[p].to_le_bytes());
        }
    }
    let bytes = out.len() as u32 - 8;
    let shorts = |v: &[u16]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
    let longs = |v: &[u32]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
    let doubles = |v: &[f64]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
    let ascii = |s: &str| s.bytes().chain([0]).collect::<Vec<u8>>();
    let mut e: Vec<(u16, u16, u32, Vec<u8>)> = vec![
        (256, 4, 1, longs(&[w])),
        (257, 4, 1, longs(&[h])),
        (258, 3, u32::from(n), shorts(&vec![32; n as usize])),
        (259, 3, 1, shorts(&[1])),
        (262, 3, 1, shorts(&[1])),
        (273, 4, 1, longs(&[8])),
        (277, 3, 1, shorts(&[n])),
        (278, 4, 1, longs(&[h])),
        (279, 4, 1, longs(&[bytes])),
        (284, 3, 1, shorts(&[1])),
        (339, 3, u32::from(n), shorts(&vec![3; n as usize])),
        (33550, 12, 3, doubles(&[px, px, 0.0])),
        (33922, 12, 6, doubles(&[0.0, 0.0, 0.0, origin.0, origin.1, 0.0])),
        (34735, 3, 12, shorts(&[1, 1, 0, 2, 1024, 0, 1, 2, 2048, 0, 1, 4326])),
    ];
    if let Some(d) = descriptions {
        let items: String =
            d.iter().enumerate().map(|(k, d)| format!(r#"<Item name="DESCRIPTION" sample="{k}" role="description">{d}</Item>"#)).collect();
        let xml = ascii(&format!("<GDALMetadata>{items}</GDALMetadata>"));
        e.push((42112, 2, xml.len() as u32, xml));
    }
    let nodata = ascii("-9999");
    e.push((42113, 2, nodata.len() as u32, nodata));
    let ifd_at = out.len() + out.len() % 2;
    out.resize(ifd_at, 0);
    let values_at = ifd_at + 2 + 12 * e.len() + 4;
    let mut values: Vec<u8> = Vec::new();
    let mut dir = (e.len() as u16).to_le_bytes().to_vec();
    for (tag, ty, count, bytes) in &mut e {
        dir.extend(tag.to_le_bytes());
        dir.extend(ty.to_le_bytes());
        dir.extend(count.to_le_bytes());
        if bytes.len() <= 4 {
            bytes.resize(4, 0);
            dir.extend(bytes.iter());
        } else {
            dir.extend(((values_at + values.len()) as u32).to_le_bytes());
            values.extend(bytes.iter());
            // Each value on a word boundary.
            if values.len() % 2 == 1 {
                values.push(0);
            }
        }
    }
    out[4..8].copy_from_slice(&(ifd_at as u32).to_le_bytes());
    out.extend(dir);
    out.extend([0; 4]);
    out.extend(values);
    out
}

/// A trend over GeoTIFF files (#579, step 3): a stack of files dated by their names (ISO and MODIS
/// dates), two of them on other grids, resampled onto the first's; and a multi-band file, a date a
/// band, dated by the band descriptions GDAL writes in it or by the dates given. The cells with a
/// planted trend have a significant slope; the noisy ones have a slope but no significant one.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_trend_over_stacked_and_multiband_geotiffs() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let mut s = Session::new(Project::default());
    let dir = std::env::temp_dir().join(format!("rustgis-cube-files-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let (x0, y0, px) = (-56.0, -12.0, 0.01);
    // Twelve years on a grid of 4 × 2 cells: 0 and 5 rise 0.02 a year, 3 and 7 fall 0.01 a year,
    // 1, 2 and 6 are noise (the same noise turned over or around, never significant), and 4 has
    // three values only, the file's no-data value on the other dates.
    let noise = [0.03, -0.02, 0.05, -0.04, 0.01, 0.0, -0.05, 0.04, -0.01, 0.02, -0.03, 0.03];
    let cells = |k: usize| -> Vec<f32> {
        let rise = 0.3 + 0.02 * k as f32;
        let fall = 0.8 - 0.01 * k as f32;
        let wobble = (0.001 * noise[k]) as f32;
        vec![
            rise + wobble,
            0.5 + noise[k] as f32,
            0.5 - noise[k] as f32,
            fall - wobble,
            if k < 3 { 0.4 } else { -9999.0 },
            rise - wobble,
            0.5 + noise[11 - k] as f32,
            fall + wobble,
        ]
    };
    let years: Vec<i32> = (2013..2025).collect();
    let mut names = Vec::new();
    for (k, y) in years.iter().enumerate() {
        // Named by a date, or as MODIS names its files (1 July is day 182, 183 in a leap year).
        let name = if k % 2 == 0 { format!("ndvi_{y}-07-01") } else { format!("MOD13Q1.A{y}{}", if y % 4 == 0 { 183 } else { 182 }) };
        let v = cells(k);
        let (w, h, gt, data) = match k {
            // Cells half as wide: each value four times.
            5 => {
                let fine = (0..32).map(|i| v[(i / 16) * 4 + (i % 8) / 2]).collect();
                (8, 4, GeoTransform { origin_x: x0, origin_y: y0, pixel_width: px / 2.0, pixel_height: -px / 2.0 }, fine)
            }
            // A larger area, the grid's cells two columns and a row in from its corner.
            8 => {
                let inside = |i: usize| (2..6).contains(&(i % 7)) && (1..3).contains(&(i / 7));
                let wide = (0..28).map(|i| if inside(i) { v[(i / 7 - 1) * 4 + i % 7 - 2] } else { 9.0 }).collect();
                (7, 4, GeoTransform { origin_x: x0 - 2.0 * px, origin_y: y0 + px, pixel_width: px, pixel_height: -px }, wide)
            }
            _ => (4, 2, GeoTransform { origin_x: x0, origin_y: y0, pixel_width: px, pixel_height: -px }, v),
        };
        let r = Raster::new(&name, w, h, vec![data], gt, Crs::LonLat, Some(-9999.0), ColorHint::Gray, "Float32").unwrap();
        let path = dir.join(format!("{name}.tif"));
        std::fs::write(&path, geotiff::write(&r, 0).unwrap()).unwrap();
        s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
        names.push(name);
    }
    let band = |s: &Session, id: &Value| {
        s.map().layer(id.as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap().bands[0].data.clone()
    };
    // The planted trends are found; the noise, and the cell with three values, are left empty.
    let found = |s: &Session, r: &Value| {
        let (slope, p, significant) = (band(s, &r["layers"][0]), band(s, &r["layers"][2]), band(s, &r["layers"][3]));
        for (cell, want) in [(0, 0.02), (5, 0.02), (3, -0.01), (7, -0.01)] {
            assert!((significant[cell] - want).abs() < 1e-3, "cell {cell}: {} (p {})", significant[cell], p[cell]);
        }
        for cell in [1, 2, 6] {
            assert!(slope[cell].is_finite() && p[cell] > 0.05 && significant[cell].is_nan(), "cell {cell}: p {}", p[cell]);
        }
        assert!(slope[4].is_nan() && significant[4].is_nan());
    };
    let r = s.run("cube.trend", &json!({"layers": names})).unwrap();
    assert_eq!(r["dates"], 12, "{r}");
    found(&s, &r);
    let name = |s: &Session, id: &Value| s.map().layer(id.as_u64().unwrap() as u32).unwrap().name.clone();
    assert_eq!(name(&s, &r["layers"][0]), "ndvi 2013-07-01–2024-07-01 Sen slope per year");
    // Every date counts in every cell, the two resampled ones included, and cell 4 has its three;
    // the larger file's cells outside the grid are left out.
    let count = s.run("cube.reduce", &json!({"layers": names, "stat": "count"})).unwrap();
    assert_eq!(band(&s, &count["layers"][0]), [12.0, 12.0, 12.0, 12.0, 3.0, 12.0, 12.0, 12.0]);
    let max = s.run("cube.reduce", &json!({"layers": names, "stat": "max"})).unwrap();
    assert!(band(&s, &max["layers"][0]).iter().all(|v| *v < 1.0), "{:?}", band(&s, &max["layers"][0]));
    // The first layer listed gives the grid: listed first, the finer file gives its 8 × 4 cells.
    let mut fine_first = names.clone();
    fine_first.swap(0, 5);
    let r = s.run("cube.trend", &json!({"layers": fine_first, "name": "fine"})).unwrap();
    let fine = s.map().layer(r["layers"][0].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!((fine.width, fine.height), (8, 4));
    // A scan not yet georeferenced, on another grid, can't be resampled: refused before the run.
    let placed = Raster::new(
        "scan",
        3,
        3,
        vec![vec![0.5; 9]],
        GeoTransform { origin_x: x0, origin_y: y0, pixel_width: px, pixel_height: -px },
        Crs::LonLat,
        None,
        ColorHint::Gray,
        "Float32",
    )
    .unwrap();
    let bytes = geotiff::write(&placed, 0).unwrap();
    let mut scan = placed;
    scan.georeferenced = false;
    crate::cmd::raster::add_raster(&mut s, "scan_2030-07-01", rustgis_map::RasterLayer::from_bytes(scan, "scan.tif", bytes)).unwrap();
    let mut with_scan = names.clone();
    with_scan.push("scan_2030-07-01".into());
    let e = s.run("cube.trend", &json!({"layers": with_scan})).unwrap_err();
    assert!(e.contains("no coordinates"), "{e}");
    // A layer away from the first's area would give its date no value: refused.
    let gt_away = GeoTransform { origin_x: x0 + 10.0, origin_y: y0, pixel_width: px, pixel_height: -px };
    let away = Raster::new("away_2030-07-01", 3, 3, vec![vec![0.5; 9]], gt_away, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let bytes = geotiff::write(&away, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "away_2030-07-01", rustgis_map::RasterLayer::from_bytes(away, "away.tif", bytes)).unwrap();
    let mut with_away = names.clone();
    with_away.push("away_2030-07-01".into());
    let e = s.run("cube.trend", &json!({"layers": with_away})).unwrap_err();
    assert!(e.contains("outside the first layer's area"), "{e}");
    // A layer in another coordinate system (Web Mercator, 500 m cells) over the grid is resampled
    // onto it too, through longitude/latitude: every cell gets its date.
    let merc = |lon: f64, lat: f64| {
        (6_378_137.0 * lon.to_radians(), 6_378_137.0 * (std::f64::consts::FRAC_PI_4 + lat.to_radians() / 2.0).tan().ln())
    };
    let (mx, my) = merc(x0 - 0.05, y0 + 0.03);
    let gt_merc = GeoTransform { origin_x: mx, origin_y: my, pixel_width: 500.0, pixel_height: -500.0 };
    let m =
        Raster::new("merc_2030-07-01", 40, 40, vec![vec![0.5; 1600]], gt_merc, Crs::WebMercator, None, ColorHint::Gray, "Float32").unwrap();
    let bytes = geotiff::write(&m, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "merc_2030-07-01", rustgis_map::RasterLayer::from_bytes(m, "merc.tif", bytes)).unwrap();
    let mut with_merc = names.clone();
    with_merc.push("merc_2030-07-01".into());
    let count = s.run("cube.reduce", &json!({"layers": with_merc, "stat": "count", "name": "merc"})).unwrap();
    assert_eq!(band(&s, &count["layers"][0]), [13.0, 13.0, 13.0, 13.0, 4.0, 13.0, 13.0, 13.0]);
    // A multi-band file, a date a band, its bands named by the descriptions in it.
    let bands: Vec<Vec<f32>> = (0..12).map(cells).collect();
    let described: Vec<String> = years.iter().map(|y| format!("NDVI {y}-07-01")).collect();
    let path = dir.join("ndvi_bands.tif");
    std::fs::write(&path, multiband_tiff(4, 2, &bands, (x0, y0), px, Some(&described))).unwrap();
    s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    let file = s.map().layer_by_name("ndvi_bands").unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!((file.bands.len(), file.bands[0].name.as_str()), (12, "NDVI 2013-07-01"));
    let r = s.run("cube.trend", &json!({"layer": "ndvi_bands"})).unwrap();
    assert_eq!(r["dates"], 12, "{r}");
    found(&s, &r);
    // An `.aux.xml` next to the file names the bands it describes, the file's own tag the others.
    let path = dir.join("ndvi_side.tif");
    std::fs::write(&path, multiband_tiff(4, 2, &bands, (x0, y0), px, Some(&described))).unwrap();
    let sidecar = r#"<PAMDataset><PAMRasterBand band="1"><Description>NDVI 2012-07-01</Description></PAMRasterBand></PAMDataset>"#;
    std::fs::write(dir.join("ndvi_side.tif.aux.xml"), sidecar).unwrap();
    s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    let side = s.map().layer_by_name("ndvi_side").unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    assert_eq!((side.bands[0].name.as_str(), side.bands[1].name.as_str()), ("NDVI 2012-07-01", "NDVI 2014-07-01"));
    // What a sidecar leaves out is said as the file is added, and again as a project with it opens;
    // a raster read whole says nothing either time.
    let path = dir.join("ndvi_scaled.tif");
    std::fs::write(&path, multiband_tiff(4, 2, &bands, (x0, y0), px, Some(&described))).unwrap();
    let scaled = r#"<PAMDataset><PAMRasterBand band="1"><Scale>0.0001</Scale></PAMRasterBand></PAMDataset>"#;
    std::fs::write(dir.join("ndvi_scaled.tif.aux.xml"), scaled).unwrap();
    let said = "ndvi_scaled: its .aux.xml sidecar: 1 scale or offset(s) not applied: the values are as stored";
    let mark = s.notice_mark();
    s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    assert!(s.notices_since(mark).iter().any(|n| n.text == said), "{:?}", s.notices_since(mark));
    let project = dir.join("scaled.rgis");
    s.run("project.saveAs", &json!({"path": project.display().to_string()})).unwrap();
    let mark = s.notice_mark();
    s.run("project.open", &json!({"path": project.display().to_string()})).unwrap();
    let opened = s.notices_since(mark);
    assert_eq!(opened.iter().filter(|n| n.text == said).count(), 1, "{opened:?}");
    assert!(!opened.iter().any(|n| n.text.starts_with("ndvi_side:") || n.text.starts_with("ndvi_bands:")), "{opened:?}");
    // Two rasters that leave out the same thing are said in one notice that names them both.
    let twin = dir.join("ndvi_twin.tif");
    std::fs::write(&twin, multiband_tiff(4, 2, &bands, (x0, y0), px, Some(&described))).unwrap();
    std::fs::write(dir.join("ndvi_twin.tif.aux.xml"), scaled).unwrap();
    s.run("layer.addData", &json!({"path": twin.display().to_string()})).unwrap();
    s.run("project.saveAs", &json!({"path": project.display().to_string()})).unwrap();
    let mark = s.notice_mark();
    s.run("project.open", &json!({"path": project.display().to_string()})).unwrap();
    let both: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).filter(|n| n.contains("scale or offset")).collect();
    assert!(
        both.len() == 1
            && both[0].starts_with("2 rasters (")
            && both[0].contains("ndvi_scaled")
            && both[0].contains("ndvi_twin")
            && both[0].ends_with("): its .aux.xml sidecar: 1 scale or offset(s) not applied: the values are as stored"),
        "{both:?}"
    );
    // A layer file keeps the file's bytes, not its sidecar: a band name the file's own tag holds
    // past 256 characters is cut as it is added again from one, and said then too.
    let mut long = described.clone();
    long[0] = "n".repeat(300);
    let path = dir.join("ndvi_long.tif");
    std::fs::write(&path, multiband_tiff(4, 2, &bands, (x0, y0), px, Some(&long))).unwrap();
    s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    let lyr = dir.join("long.rgislyr");
    s.run("layer.save", &json!({"layer": "ndvi_long", "path": lyr.display().to_string()})).unwrap();
    let mark = s.notice_mark();
    s.run("layer.addData", &json!({"path": lyr.display().to_string()})).unwrap();
    let again = s.notices_since(mark);
    assert!(again.iter().any(|n| n.text == "ndvi_long (2): its GDAL metadata: 1 band or class name(s) cut to 256 characters"), "{again:?}");
    // Without descriptions, the dates are given.
    let path = dir.join("ndvi_plain.tif");
    std::fs::write(&path, multiband_tiff(4, 2, &bands, (x0, y0), px, None)).unwrap();
    s.run("layer.addData", &json!({"path": path.display().to_string()})).unwrap();
    let e = s.run("cube.trend", &json!({"layer": "ndvi_plain"})).unwrap_err();
    assert!(e.contains("give \"dates\""), "{e}");
    let typed: Vec<String> = years.iter().map(|y| format!("{y}-07-01")).collect();
    let r = s.run("cube.trend", &json!({"layer": "ndvi_plain", "dates": typed, "name": "typed"})).unwrap();
    found(&s, &r);
    let _ = std::fs::remove_dir_all(dir);
}

/// A data cube summarised over time (#579): each statistic over a stack of layers, a year or a
/// month of the year at a time, a cell needing a share of its group's dates, a raster's bands, and
/// a Zarr variable as `zarr.reduce` sums it up; each output kept in the project.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_data_cube_summarised_over_time() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let mut s = Session::new(Project::default());
    let gt = GeoTransform { origin_x: -44.0, origin_y: -7.0, pixel_width: 0.01, pixel_height: -0.01 };
    // March and September, 2020 to 2022: cell 0 is the date's place (0 to 5), cell 1 has no value
    // in 2021, cell 2 is the file's no-data value in March, and cell 3 never has a value.
    let dates = ["2020-03-01", "2020-09-01", "2021-03-01", "2021-09-01", "2022-03-01", "2022-09-01"];
    let mut names = Vec::new();
    for (k, d) in dates.iter().enumerate() {
        let name = format!("ndvi_{d}");
        let gap = if d.starts_with("2021") { f32::NAN } else { 1.0 };
        let march = if k % 2 == 0 { -9999.0 } else { 7.0 };
        let cells = vec![k as f32, gap, march, f32::NAN];
        let r = Raster::new(&name, 2, 2, vec![cells], gt, Crs::LonLat, Some(-9999.0), ColorHint::Gray, "Float32").unwrap();
        let bytes = geotiff::write(&r, 0).unwrap();
        crate::cmd::raster::add_raster(&mut s, &name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
        names.push(name);
    }
    let data = |s: &Session, id: &Value| s.map().layer(id.as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().data.clone().unwrap();
    let name = |s: &Session, id: &Value| s.map().layer(id.as_u64().unwrap() as u32).unwrap().name.clone();
    let one = |s: &mut Session, p: Value| {
        let r = s.run("cube.reduce", &p).unwrap();
        assert_eq!(r["layers"].as_array().map(Vec::len), Some(1), "{r}");
        data(s, &r["layers"][0]).bands[0].data.clone()
    };
    for (stat, want) in [("mean", 2.5), ("min", 0.0), ("max", 5.0), ("sum", 15.0), ("count", 6.0)] {
        assert_eq!(one(&mut s, json!({"layers": names, "stat": stat}))[0], want, "{stat}");
    }
    let std = one(&mut s, json!({"layers": names, "stat": "std"}))[0];
    assert!((std - 1.707_825).abs() < 1e-4, "{std}");
    assert_eq!(one(&mut s, json!({"layers": names, "stat": "countAbove", "above": 2.5}))[0], 3.0);
    // Gaps and no-data are skipped: cell 1 has four values, cell 2 three, cell 3 none (no mean,
    // a count of 0).
    assert_eq!(one(&mut s, json!({"layers": names, "stat": "count"})), [6.0, 4.0, 3.0, 0.0]);
    let mean = one(&mut s, json!({"layers": names, "stat": "mean"}));
    assert_eq!(&mean[..3], [2.5, 1.0, 7.0]);
    assert!(mean[3].is_nan());
    assert!(s.map().layer_by_name("ndvi mean 2020-03-01–2022-09-01").is_some());
    // A layer a year, named by it, each the mean of its two dates; cell 1 empty in 2021.
    let r = s.run("cube.reduce", &json!({"layers": names, "stat": "mean", "by": "year"})).unwrap();
    let ids = r["layers"].as_array().unwrap().clone();
    assert_eq!(r["dates"], 6);
    assert_eq!(ids.iter().map(|id| name(&s, id)).collect::<Vec<_>>(), ["ndvi mean 2020", "ndvi mean 2021", "ndvi mean 2022"]);
    assert_eq!(ids.iter().map(|id| data(&s, id).bands[0].data[0]).collect::<Vec<_>>(), [0.5, 2.5, 4.5]);
    assert!(data(&s, &ids[1]).bands[0].data[1].is_nan() && data(&s, &ids[2]).bands[0].data[1] == 1.0);
    // A share of each year's dates: 0.6 of two is two, so cell 2 (one value a year) is empty;
    // the name given, with the year.
    let r = s.run("cube.reduce", &json!({"layers": names, "stat": "count", "by": "year", "minValid": 0.6, "name": "anos"})).unwrap();
    let ids = r["layers"].as_array().unwrap().clone();
    assert_eq!(name(&s, &ids[0]), "anos 2020");
    let first = data(&s, &ids[0]).bands[0].data.clone();
    assert!(first[0] == 2.0 && first[1] == 2.0 && first[2].is_nan() && first[3].is_nan(), "{first:?}");
    // A layer a month of the year, across the years: March's cell 2 is always no-data.
    let r = s.run("cube.reduce", &json!({"layers": names, "stat": "mean", "by": "month"})).unwrap();
    let ids = r["layers"].as_array().unwrap().clone();
    assert_eq!(ids.iter().map(|id| name(&s, id)).collect::<Vec<_>>(), ["ndvi mean 2020–2022 month 03", "ndvi mean 2020–2022 month 09"]);
    let (march, september) = (data(&s, &ids[0]).bands[0].data.clone(), data(&s, &ids[1]).bands[0].data.clone());
    assert!(march[0] == 2.0 && march[2].is_nan() && september[0] == 3.0 && september[2] == 7.0, "{march:?} {september:?}");
    // A season across the years, a year at a time.
    let r = s.run("cube.reduce", &json!({"layers": names, "stat": "max", "by": "year", "months": [9]})).unwrap();
    let ids = r["layers"].as_array().unwrap().clone();
    assert_eq!(name(&s, &ids[0]), "ndvi max 2020 (months 9)");
    assert_eq!(ids.iter().map(|id| data(&s, id).bands[0].data[0]).collect::<Vec<_>>(), [1.0, 3.0, 5.0]);
    // A raster whose bands are the dates.
    let bands: Vec<Vec<f32>> = (0..6).map(|k| vec![k as f32 * 2.0]).collect();
    let mut cube = Raster::new("stack", 1, 1, bands, gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    for (b, d) in cube.bands.iter_mut().zip(&dates) {
        b.name = format!("NDVI {d}");
    }
    let bytes = geotiff::write(&cube, 0).unwrap();
    let id =
        crate::cmd::raster::add_raster(&mut s, "stack", rustgis_map::RasterLayer::from_bytes(cube, "stack.tif", bytes)).unwrap()["layer"]
            .clone();
    assert_eq!(one(&mut s, json!({"layer": id, "stat": "mean"})), [5.0]);
    // A Zarr variable: the same values as zarr.reduce's, cell for cell.
    let (dir, path) = zarr_store_over_time("cube-reduce");
    for stat in ["mean", "std", "max", "count"] {
        let r = s.run("zarr.reduce", &json!({"path": path, "variable": "t", "stat": stat})).unwrap();
        let zarr = data(&s, &r["layer"]).bands[0].data.clone();
        let cube = one(&mut s, json!({"path": path, "variable": "t", "stat": stat}));
        assert!(zarr.iter().zip(&cube).all(|(a, b)| a == b || (a.is_nan() && b.is_nan())) && zarr.len() == cube.len(), "{stat}");
    }
    let _ = std::fs::remove_dir_all(dir);
    // Kept in the project as GeoTIFFs, read again.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t.map().layer_by_name("anos 2020").and_then(|l| l.raster.as_ref()).and_then(|r| r.data.clone()).unwrap();
    assert_eq!(again.bands[0].data[0], 2.0);
    // Cancelled, it says so.
    let job = crate::cmd::cube::reduce_start(&mut s, &json!({"layers": names, "stat": "mean"})).unwrap();
    let e = job.run(&std::sync::atomic::AtomicBool::new(true), &std::sync::atomic::AtomicUsize::new(0)).unwrap_err();
    assert_eq!(e, "cancelled");
    // Refused, nothing added.
    let before = s.map().layers.len();
    for bad in [
        json!({"layers": names}),
        json!({"layers": names, "stat": "percentile"}),
        json!({"layers": names, "stat": "countAbove"}),
        json!({"layers": names, "stat": "mean", "by": "week"}),
        json!({"layers": names, "stat": "mean", "minValid": 1.5}),
        json!({"layers": names, "stat": "mean", "start": "2030"}),
    ] {
        assert!(s.run("cube.reduce", &bad).is_err(), "{bad}");
    }
    assert_eq!(s.map().layers.len(), before);
}

/// A summary takes a cube a trend can't: two dates are enough for a mean or a maximum, while a
/// trend still asks for its few, and each says which it is.
#[test]
fn a_short_cube_is_summarised_but_not_trended() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let mut s = Session::new(Project::default());
    let gt = GeoTransform { origin_x: -44.0, origin_y: -7.0, pixel_width: 0.01, pixel_height: -0.01 };
    let mut names = Vec::new();
    for (k, d) in ["2020-03-01", "2021-03-01"].iter().enumerate() {
        let name = format!("ndvi_{d}");
        let r = Raster::new(&name, 1, 1, vec![vec![k as f32 * 4.0 + 1.0]], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
        let bytes = geotiff::write(&r, 0).unwrap();
        crate::cmd::raster::add_raster(&mut s, &name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
        names.push(name);
    }
    for (stat, want) in [("mean", 3.0), ("max", 5.0)] {
        let r = s.run("cube.reduce", &json!({"layers": names, "stat": stat})).unwrap();
        let id = r["layers"][0].as_u64().unwrap() as u32;
        assert_eq!(s.map().layer(id).unwrap().raster.as_ref().unwrap().data.as_ref().unwrap().bands[0].data[0], want, "{stat}");
    }
    let e = s.run("cube.trend", &json!({"layers": names})).unwrap_err();
    assert!(e.contains("trend") && !e.contains("summary"), "{e}");
    // One date has nothing to summarise.
    let e = s.run("cube.reduce", &json!({"layers": [names[0]], "stat": "mean"})).unwrap_err();
    assert!(e.contains("summary's stack needs 2 layers"), "{e}");
}

/// A stack of land-cover maps summarised as classes: each cell's most frequent class (the least
/// of those tied) and how many dates had it, how many classes it had, how many times its class
/// changed and the class and length of its longest run, in date order (the layers added out of it), how many
/// dates it was in some classes, and a layer for each class with its count of dates. A cell left
/// without a class at a date (no data) is skipped. What isn't a class, too many classes, and a categorical
/// statistic asked of zarr.reduce are refused.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_categorical_stack_summarised_over_time() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster, geotiff};
    let gt = GeoTransform { origin_x: -44.0, origin_y: -7.0, pixel_width: 0.01, pixel_height: -0.01 };
    let add = |s: &mut Session, name: &str, cells: Vec<f32>| {
        let r = Raster::new(name, cells.len() as u32, 1, vec![cells], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
        let bytes = geotiff::write(&r, 0).unwrap();
        crate::cmd::raster::add_raster(s, name, rustgis_map::RasterLayer::from_bytes(r, format!("{name}.tif"), bytes)).unwrap();
    };
    let nan = f32::NAN;
    // Four cells over six years: 3 3 4 3 4 4; always 15; 21 21 33 with no data between; and
    // 5 7 7 7 5 5, whose mode (5, the least of two tied) isn't its longest run's class (7).
    let years: [(u32, [f32; 4]); 6] = [
        (2000, [3.0, 15.0, nan, 5.0]),
        (2001, [3.0, 15.0, 21.0, 7.0]),
        (2002, [4.0, 15.0, nan, 7.0]),
        (2003, [3.0, 15.0, 21.0, 7.0]),
        (2004, [4.0, 15.0, 33.0, 5.0]),
        (2005, [4.0, 15.0, nan, 5.0]),
    ];
    let mut s = Session::new(Project::default());
    let mut names = Vec::new();
    // Added out of date order: changes go by the dates, not the layers' order.
    for k in [3, 0, 5, 1, 4, 2] {
        let (y, cells) = years[k];
        let name = format!("cobertura_{y}");
        add(&mut s, &name, cells.to_vec());
        names.push(name);
    }
    let run = |s: &mut Session, p: Value| {
        let r = s.run("cube.reduce", &p).unwrap();
        let id = r["layers"][0].as_u64().unwrap() as u32;
        let l = s.map().layer(id).unwrap();
        (l.name.clone(), l.raster.as_ref().unwrap().data.as_ref().unwrap().bands[0].data.clone())
    };
    let (name, mode) = run(&mut s, json!({"layers": names, "stat": "mode"}));
    assert_eq!(mode, vec![3.0, 15.0, 21.0, 5.0]);
    assert_eq!(name, "cobertura mode 2000-01-01–2005-01-01");
    assert_eq!(run(&mut s, json!({"layers": names, "stat": "majority"})).1, mode);
    assert_eq!(run(&mut s, json!({"layers": names, "stat": "modeCount"})).1, vec![3.0, 6.0, 2.0, 3.0]);
    assert_eq!(run(&mut s, json!({"layers": names, "stat": "variety"})).1, vec![2.0, 1.0, 2.0, 2.0]);
    assert_eq!(run(&mut s, json!({"layers": names, "stat": "changes"})).1, vec![3.0, 0.0, 1.0, 2.0]);
    // Runs of 2 in 3 and in 4 (the least), 6 in 15, 21 through its gap, 3 in 7.
    assert_eq!(run(&mut s, json!({"layers": names, "stat": "longestRun"})).1, vec![3.0, 15.0, 21.0, 7.0]);
    assert_eq!(run(&mut s, json!({"layers": names, "stat": "longestRunLength"})).1, vec![2.0, 6.0, 2.0, 3.0]);
    assert_eq!(run(&mut s, json!({"layers": names, "stat": "countIn", "classes": [4, 33]})).1, vec![3.0, 0.0, 1.0, 0.0]);
    // A share of the dates: the third cell has a class at half of them, so it's left out at 0.6.
    let (_, half) = run(&mut s, json!({"layers": names, "stat": "mode", "minValid": 0.6}));
    assert_eq!((half[0], half[1], half[3]), (3.0, 15.0, 5.0));
    assert!(half[2].is_nan(), "{half:?}");
    // Frequency: a layer for each class met, each cell's count of dates in it.
    let layers = |s: &Session, r: &Value| -> Vec<(String, Vec<f32>)> {
        r["layers"]
            .as_array()
            .unwrap()
            .iter()
            .map(|id| {
                let l = s.map().layer(id.as_u64().unwrap() as u32).unwrap();
                (l.name.clone(), l.raster.as_ref().unwrap().data.as_ref().unwrap().bands[0].data.clone())
            })
            .collect()
    };
    let r = s.run("cube.reduce", &json!({"layers": names, "stat": "frequency"})).unwrap();
    let got = layers(&s, &r);
    let want: Vec<(String, Vec<f32>)> = [
        (3, [3.0, 0.0, 0.0, 0.0]),
        (4, [3.0, 0.0, 0.0, 0.0]),
        (5, [0.0, 0.0, 0.0, 3.0]),
        (7, [0.0, 0.0, 0.0, 3.0]),
        (15, [0.0, 6.0, 0.0, 0.0]),
        (21, [0.0, 0.0, 2.0, 0.0]),
        (33, [0.0, 0.0, 1.0, 0.0]),
    ]
    .iter()
    .map(|(c, n)| (format!("cobertura frequency 2000-01-01–2005-01-01 class {c}"), n.to_vec()))
    .collect();
    assert_eq!(got, want);
    // With a share, a cell with too few values is left out of every class's layer.
    let r = s.run("cube.reduce", &json!({"layers": names, "stat": "frequency", "minValid": 0.6, "name": "freq"})).unwrap();
    let got = layers(&s, &r);
    assert_eq!(got.len(), 7);
    assert!(got.iter().all(|(_, n)| n[2].is_nan()), "{got:?}");
    assert_eq!(got[0].0, "freq class 3");
    assert_eq!((got[0].1[0], got[0].1[1], got[0].1[3]), (3.0, 0.0, 0.0));
    // A raster whose bands are the years out of order, their dates given in the bands' order:
    // changes still go by the dates.
    let order = [3, 0, 5, 1, 4, 2];
    let bands: Vec<Vec<f32>> = order.iter().map(|&k| years[k].1.to_vec()).collect();
    let dates: Vec<String> = order.iter().map(|&k| format!("{}-01-01", years[k].0)).collect();
    let r = Raster::new("bandas", 4, 1, bands, gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let bytes = geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "bandas", rustgis_map::RasterLayer::from_bytes(r, "bandas.tif".to_string(), bytes)).unwrap();
    assert_eq!(run(&mut s, json!({"layer": "bandas", "dates": dates, "stat": "changes"})).1, vec![3.0, 0.0, 1.0, 2.0]);
    assert_eq!(run(&mut s, json!({"layer": "bandas", "dates": dates, "stat": "longestRun"})).1, vec![3.0, 15.0, 21.0, 7.0]);
    assert_eq!(run(&mut s, json!({"layer": "bandas", "dates": dates, "stat": "longestRunLength"})).1, vec![2.0, 6.0, 2.0, 3.0]);
    // By year, a change is one within the year: none, with one date a year.
    let r = s.run("cube.reduce", &json!({"layers": names, "stat": "changes", "by": "year"})).unwrap();
    assert_eq!(r["layers"].as_array().unwrap().len(), 6);
    // Every key a categorical summary takes is read, none said to be ignored.
    let mark = s.notice_mark();
    run(&mut s, json!({"layers": names, "stat": "countIn", "classes": [3], "minValid": 0.5, "name": "floresta"}));
    let ignored: Vec<String> = s.notices_since(mark).iter().map(|n| n.text.clone()).filter(|t| t.contains("ignores")).collect();
    assert!(ignored.is_empty(), "{ignored:?}");
    // Refused, nothing added.
    let before = s.map().layers.len();
    for (bad, said) in [
        (json!({"layers": names, "stat": "countIn"}), "countIn takes \"classes\""),
        (json!({"layers": names, "stat": "countIn", "classes": []}), "countIn takes \"classes\""),
        (json!({"layers": names, "stat": "countIn", "classes": [3.5]}), "whole numbers from 0 to 255"),
        (json!({"layers": names, "stat": "countIn", "classes": [256]}), "whole numbers from 0 to 255"),
        (json!({"layers": names, "stat": "countIn", "classes": "3"}), "countIn takes \"classes\""),
        (json!({"layers": names, "stat": "countIn", "classes": vec![3; 257]}), "countIn takes \"classes\""),
    ] {
        let e = s.run("cube.reduce", &bad).unwrap_err();
        assert!(e.contains(said), "{bad}: {e}");
    }
    // Values that aren't classes (an NDVI): said, with the value.
    let ndvi = ["ndvi_2020", "ndvi_2021"];
    for (k, name) in ndvi.iter().enumerate() {
        add(&mut s, name, vec![0.25 + k as f32 * 0.5]);
    }
    let before_ndvi = s.map().layers.len();
    for stat in ["mode", "variety", "changes", "countIn"] {
        let e = s.run("cube.reduce", &json!({"layers": ndvi, "stat": stat, "classes": [0]})).unwrap_err();
        assert!(e.contains("0.25 isn't a class") && e.contains(stat), "{stat}: {e}");
    }
    assert_eq!(s.map().layers.len(), before_ndvi);
    // More classes than a land-cover map has: refused, not a count for each.
    let many = ["muitas_2020", "muitas_2021"];
    for name in many {
        add(&mut s, name, (0..1001).map(|c| c as f32).collect());
    }
    let after_many = s.map().layers.len();
    let e = s.run("cube.reduce", &json!({"layers": many, "stat": "variety"})).unwrap_err();
    assert!(e.contains("more than 1000 classes") && e.contains("variety"), "{e}");
    assert_eq!(s.map().layers.len(), after_many);
    assert_eq!(before_ndvi - before, ndvi.len());
    // A Zarr axis out of date order (days 31, 0, 59) whose classes are 2, 1, 2 along it: in date
    // order they are 1, 2, 2, one change, not the axis's two, and a longest run in 2, where the
    // axis's runs are all of one date (and the least class, 1, would win).
    let (dir, path) = zarr_store_at("cube-reduce-classes-order", &[31, 0, 59]);
    for (t, class) in [(0, 2.0f32), (1, 1.0), (2, 2.0)] {
        let chunk: Vec<u8> = std::iter::repeat_n(class, 12).flat_map(|x| x.to_le_bytes()).collect();
        std::fs::write(std::path::Path::new(&path).join(format!("t/{t}.0.0")), chunk).unwrap();
    }
    assert_eq!(run(&mut s, json!({"path": path, "variable": "t", "stat": "changes"})).1, vec![1.0; 12]);
    assert_eq!(run(&mut s, json!({"path": path, "variable": "t", "stat": "longestRun"})).1, vec![2.0; 12]);
    assert_eq!(run(&mut s, json!({"path": path, "variable": "t", "stat": "longestRunLength"})).1, vec![2.0; 12]);
    let _ = std::fs::remove_dir_all(dir);
    // zarr.reduce doesn't take them: it points to cube.reduce.
    let (dir, path) = zarr_store_over_time("cube-reduce-classes");
    let e = s.run("zarr.reduce", &json!({"path": path, "variable": "t", "stat": "mode"})).unwrap_err();
    assert!(e.contains("cube.reduce"), "{e}");
    let _ = std::fs::remove_dir_all(dir);
}

/// A Zarr axis in decreasing order: a trend refuses it, a summary takes it and names its period from
/// the earliest date to the latest.
#[test]
fn a_summary_over_a_decreasing_zarr_axis_names_its_period_in_order() {
    let (dir, path) = zarr_store_at("cube-reduce-desc", &[59, 31, 0]);
    let mut s = Session::new(Project::default());
    let e = s.run("cube.trend", &json!({"path": path, "variable": "t"})).unwrap_err();
    assert!(e.contains("increasing order"), "{e}");
    let r = s.run("cube.reduce", &json!({"path": path, "variable": "t", "stat": "mean"})).unwrap();
    let name = s.map().layer(r["layers"][0].as_u64().unwrap() as u32).unwrap().name.clone();
    assert!(name.contains("2001-01-01–2001-03-01"), "{name}");
    let _ = std::fs::remove_dir_all(dir);
}

/// A STAC collection's band summarised over time, read in place as for a trend: each file's own
/// scale and offset taken, the whole period or a month at a time.
#[test]
fn a_stac_collection_summarised_over_time() {
    let (cog, _) = serve_ranges(rustgis_data::raster::cog::example(512, 256));
    let dates = ["2024-01-01", "2024-01-17", "2024-02-02", "2024-02-18", "2024-03-05", "2024-03-21"];
    let features: Vec<String> = dates
        .iter()
        .enumerate()
        .map(|(k, d)| {
            format!(
                r#"{{"type": "Feature", "id": "n{k}", "collection": "mod", "bbox": [10, 45, 11, 46], "geometry": null,
                   "properties": {{"datetime": "{d}T00:00:00Z"}},
                   "assets": {{"NDVI": {{"href": "{cog}/n{k}.tif", "eo:bands": [{{"scale": {}, "offset": {}}}]}}}}}}"#,
                (k + 1) as f64 * 1e-4,
                k as f64 * 0.01
            )
        })
        .collect();
    let search = format!(r#"{{"type": "FeatureCollection", "features": [{}]}}"#, features.join(","));
    let api = format!("{}/v1", serve_routes(vec![("/v1/search", search)], 8));
    let mut s = Session::new(Project::default());
    let mut run = |by: &str| {
        let p = json!({"url": api, "collection": "mod", "asset": "NDVI", "bbox": [10, 45, 11, 46], "start": "2024-01-01", "end": "2024-03", "stat": "mean", "by": by});
        let r = s.run("cube.reduce", &p).unwrap();
        let ids: Vec<u32> = r["layers"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect();
        ids.iter().map(|id| s.map().layer(*id).unwrap().raster.as_ref().unwrap().data.clone().unwrap()).collect::<Vec<_>>()
    };
    // Pixel (x, y) stores (x + y) % 256; date k reads it at a scale of k + 1 ten-thousandths and
    // an offset of k hundredths, so dates k0 to k1 average to (k0 + k1 + 2) / 2 ten-thousandths
    // of it plus (k0 + k1) / 2 hundredths.
    let mean = |x: usize, y: usize, k0: usize, k1: usize| {
        ((x + y) % 256) as f64 * (k0 + k1 + 2) as f64 / 2.0 * 1e-4 + (k0 + k1) as f64 / 2.0 * 0.01
    };
    let whole = run("all");
    assert_eq!(whole.len(), 1);
    assert_eq!((whole[0].width, whole[0].height), (512, 512), "the area on the full images' grid");
    let months = run("month");
    assert_eq!(months.len(), 3, "January, February and March");
    for (x, y) in [(10, 20), (300, 100), (0, 0), (511, 511)] {
        let at = y * 512 + x;
        let got = f64::from(whole[0].bands[0].data[at]);
        assert!((got - mean(x, y, 0, 5)).abs() < 1e-4, "({x}, {y}): {got} vs {}", mean(x, y, 0, 5));
        for (m, (k0, k1)) in [(0, 1), (2, 3), (4, 5)].into_iter().enumerate() {
            let got = f64::from(months[m].bands[0].data[at]);
            assert!((got - mean(x, y, k0, k1)).abs() < 1e-4, "month {m} ({x}, {y}): {got} vs {}", mean(x, y, k0, k1));
        }
    }
}

/// A Zarr variable follows the time slider (#554): the slice drawn is the step the slider is at,
/// the stretch is the same at every step, and the project keeps the layer by its store.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_variable_follows_the_time_slider() {
    let _cache = zarr_cache_lock();
    let (dir, path) = zarr_store_over_time("follow");
    let mut s = Session::new(Project::default());
    let id = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "time": true})).unwrap()["layer"].as_u64().unwrap() as u32;
    // The slider is on over the variable's three dates, at the first.
    let info = s.run("time.info", &Value::Null).unwrap();
    assert_eq!(info["steps"], 3, "{info}");
    let first = |s: &Session| s.map().layer(id).and_then(|l| l.raster.as_ref()).and_then(|r| r.data.as_ref()).map(|d| d.bands[0].data[0]);
    // North up: the last latitude row first; step k's values are 100·k + i.
    assert_eq!(first(&s), Some(8.0));
    let rl = s.map().layer(id).unwrap().raster.clone().unwrap();
    assert!(matches!(rl.style.stretch, rustgis_map::raster::Stretch::Custom { .. }), "{:?}", rl.style.stretch);
    assert!(s.map().layer(id).unwrap().name.ends_with(" t"), "{}", s.map().layer(id).unwrap().name);
    let stretch = rl.style.stretch;
    // Moving the slider moves the slice; the stretch stays.
    s.run("time.goTo", &json!({"step": 2})).unwrap();
    assert_eq!(first(&s), Some(208.0));
    s.run("time.step", &json!({"by": -1})).unwrap();
    assert_eq!(first(&s), Some(108.0));
    assert_eq!(s.map().layer(id).unwrap().raster.as_ref().unwrap().style.stretch, stretch);
    // Saved and opened again: the store and the step, read again.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.contains("\"time_zarr\"") && !text.contains("\"embedded\""), "kept by its store, not as a slice");
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t
        .map()
        .layers
        .iter()
        .find(|l| l.is_raster())
        .and_then(|l| l.raster.as_ref())
        .and_then(|r| r.data.as_ref())
        .map(|d| d.bands[0].data[0]);
    assert_eq!(again, Some(108.0));
    // A window with no step of the variable: nothing drawn.
    s.run("time.set", &json!({"dates": ["2000-06-01", "2001-01-01", "2001-02-01", "2001-03-01"], "date": "2000-06-01"})).unwrap();
    assert_eq!(first(&s), None);
    s.run("time.goTo", &json!({"step": 3})).unwrap();
    assert_eq!(first(&s), Some(208.0));
    // The animation reads each step's slice.
    let zip = std::env::temp_dir().join(format!("rustgis-zarr-frames-{}.zip", std::process::id()));
    let r = s.run("time.export", &json!({"path": zip.display().to_string(), "width": 64, "height": 48})).unwrap();
    assert_eq!(r["frames"], 4, "{r}");
    // After the export the slider is back at its step, and the layer shows it.
    assert_eq!(first(&s), Some(208.0), "the layer shows the step the slider is back at");
    let _ = std::fs::remove_file(zip);
    // A period: the steps from February on, the layer's first step the second of the axis.
    let id2 = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "time": true, "start": "2001-01-20", "name": "late"})).unwrap()
        ["layer"]
        .as_u64()
        .unwrap() as u32;
    let zt = s.map().layer(id2).unwrap().raster.as_ref().unwrap().time_zarr.clone().unwrap();
    assert_eq!((zt.offset, zt.dates.len(), zt.dim.as_str()), (1, 2, "time"));
    for bad in [
        json!({"path": path, "variable": "t", "time": true, "start": "2002-01-01"}),
        json!({"path": path, "variable": "t", "time": true, "start": "June"}),
        json!({"path": path, "variable": "t", "time": true, "ran": 1}),
        json!({"path": path, "variable": "lat", "time": true}),
    ] {
        assert!(s.run("layer.addZarr", &bad).is_err(), "{bad}");
    }
    // An axis with a date twice, or going back: each date is a step, so it can't be followed.
    let (dir2, twice) = zarr_store_over_time("twice");
    std::fs::write(std::path::Path::new(&twice).join("time/0"), [0i32, 31, 31].iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>())
        .unwrap();
    let e = s.run("layer.addZarr", &json!({"path": twice, "variable": "t", "time": true})).unwrap_err();
    assert!(e.contains("increasing order"), "{e}");
    // With no variable named, a folder's first one follows the slider.
    let mut plain = Session::new(Project::default());
    let r = plain.run("layer.addZarr", &json!({"path": path, "time": true})).unwrap();
    assert!(plain.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().raster.as_ref().unwrap().time_zarr.is_some());
    // A store whose first slice can't be read leaves the slider as it was.
    let (dir3, broken) = zarr_store_over_time("broken");
    std::fs::remove_file(std::path::Path::new(&broken).join("t/0.0.0")).unwrap();
    std::fs::write(std::path::Path::new(&broken).join("t/0.0.0"), b"short").unwrap();
    let mut fresh = Session::new(Project::default());
    assert!(fresh.run("layer.addZarr", &json!({"path": broken, "variable": "t", "time": true})).is_err());
    assert!(fresh.map().time.is_none(), "a store that can't be read leaves the slider as it was");
    let _ = std::fs::remove_dir_all(dir3);
    let _ = std::fs::remove_dir_all(dir2);
    let _ = std::fs::remove_dir_all(dir);
}

/// Manual reload reads changed chunks even when folder metadata is unchanged, and later time
/// steps cannot revive a cached pre-reload slice.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn manual_zarr_reload_reads_fresh_chunks_and_keeps_the_time_variable() {
    let _cache = zarr_cache_lock();
    let (dir, path) = zarr_store_over_time("manual-reload");
    let mut s = Session::new(Project::default());
    let id = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "time": true})).unwrap()["layer"].as_u64().unwrap() as u32;
    let snapshot =
        s.run("layer.addZarr", &json!({"path": path, "variable": "t[time=0]", "name": "Slice"})).unwrap()["layer"].as_u64().unwrap() as u32;
    let first = |s: &Session, id| s.map().layer(id).unwrap().raster.as_ref().unwrap().data.as_ref().unwrap().bands[0].data[0];
    assert_eq!(first(&s, id), 8.0);
    s.run("time.goTo", &json!({"step": 1})).unwrap();
    assert_eq!(first(&s, id), 108.0);
    s.run("time.goTo", &json!({"step": 0})).unwrap();
    let style = serde_json::to_value(&s.map().layer(id).unwrap().raster.as_ref().unwrap().style).unwrap();
    let prior = s.map().layer(id).unwrap().raster.as_ref().unwrap().time_zarr.clone().unwrap();
    crate::cmd::zarr::read_step(&prior, 2, crate::cmd::zarr::slice_key(&prior, 2)).unwrap();
    for step in 0..3 {
        let chunk: Vec<u8> = std::iter::repeat_n(500.0f32 + step as f32, 12).flat_map(|v| v.to_le_bytes()).collect();
        std::fs::write(std::path::Path::new(&path).join(format!("t/{step}.0.0")), chunk).unwrap();
    }
    s.run("layer.reloadData", &json!({"layer": id})).unwrap();
    assert_eq!(first(&s, id), 500.0);
    assert_eq!(first(&s, snapshot), 8.0, "each target reloads independently");
    let summary = s.run("zarr.reduce", &json!({"layer": id, "stat": "mean"})).unwrap()["layer"].as_u64().unwrap() as u32;
    assert_eq!(first(&s, summary), 501.0, "summaries must not reuse pre-reload slices");
    s.run("layer.reloadData", &json!({"layer": snapshot})).unwrap();
    assert_eq!(first(&s, snapshot), 500.0);
    for params in [json!({"layer": snapshot, "stat": "mean"}), json!({"path": path, "variable": "t", "stat": "mean"})] {
        let summary = s.run("zarr.reduce", &params).unwrap()["layer"].as_u64().unwrap() as u32;
        assert_eq!(first(&s, summary), 501.0, "ordinary and path analyses read fresh chunks");
        let cube = s.run("cube.reduce", &params).unwrap()["layers"][0].as_u64().unwrap() as u32;
        assert_eq!(first(&s, cube), 501.0, "cube analyses use the same fresh series policy");
    }
    // Reopening in this same process must not revive an older cached generation.
    let saved = serde_json::to_string(&s.project).unwrap();
    let mut reopened = Session::new(Project::default());
    reopened.run("project.openText", &json!({"text": saved})).unwrap();
    assert_eq!(first(&reopened, id), 500.0);
    // An old in-flight read may finish after the project reopened, but cannot match it.
    let key = crate::cmd::zarr::slice_key(&prior, 2);
    crate::cmd::zarr::read_step(&prior, 2, key).unwrap();
    reopened.run("time.goTo", &json!({"step": 2})).unwrap();
    assert_eq!(first(&reopened, id), 502.0);
    s.run("time.goTo", &json!({"step": 1})).unwrap();
    assert_eq!(first(&s, id), 501.0);
    let rl = s.map().layer(id).unwrap().raster.as_ref().unwrap();
    assert_eq!(rl.time_zarr.as_ref().unwrap().variable, "t");
    assert_eq!(serde_json::to_value(&rl.style).unwrap(), style);
    let old = rl.data.clone().unwrap();
    std::fs::write(std::path::Path::new(&path).join("t/1.0.0"), b"truncated").unwrap();
    assert!(s.run("layer.reloadData", &json!({"layer": id})).is_err());
    assert!(std::sync::Arc::ptr_eq(&old, s.map().layer(id).unwrap().raster.as_ref().unwrap().data.as_ref().unwrap()));
    std::fs::remove_dir_all(dir).unwrap();
}

/// Step `k`'s cells of [`zarr_store_at`]'s variable (`100 k + cell`), as its chunk file holds them.
#[cfg(not(target_arch = "wasm32"))]
fn f32s_of(base: i32) -> Vec<u8> {
    (0..12).flat_map(|i| ((base + i) as f32).to_le_bytes()).collect()
}

/// In the app a time slider move doesn't wait for a Zarr step (#1291 step 3): the step is read on
/// a thread of its own, the layer showing the step before until it lands; one that fails says why
/// once it lands. An animation's frames still read each step before they draw.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_zarr_step_is_read_off_the_frame_in_the_app() {
    let _cache = zarr_cache_lock();
    let (dir, path) = zarr_store_over_time("offframe");
    let mut s = Session::new(Project::default());
    s.zarr_off_frame = true;
    let id = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "time": true})).unwrap()["layer"].as_u64().unwrap() as u32;
    let first = |s: &Session| s.map().layer(id).and_then(|l| l.raster.as_ref()).and_then(|r| r.data.as_ref()).map(|d| d.bands[0].data[0]);
    assert_eq!(first(&s), Some(8.0));
    let landed = |s: &mut Session, want: Option<f32>| {
        let end = std::time::Instant::now() + std::time::Duration::from_secs(30);
        while first(s) != want {
            assert!(std::time::Instant::now() < end, "the step never landed: {:?}", first(s));
            s.follow_time_landed();
            std::thread::sleep(std::time::Duration::from_millis(5)); // test-wait: legacy polling for the requested Zarr step
        }
    };
    // The move returns at once: the layer shows the step before, then step 2 once it lands;
    // playing waits for it meanwhile.
    s.run("time.goTo", &json!({"step": 2})).unwrap();
    landed(&mut s, Some(208.0));
    assert!(!s.zarr_waiting(), "the step shown is the slider's");
    // A step read before shows at once.
    s.run("time.goTo", &json!({"step": 0})).unwrap();
    assert_eq!(first(&s), Some(8.0), "a kept step shows without waiting");
    // A step that can't be read empties the layer and says why, once.
    std::fs::write(std::path::Path::new(&path).join("t/1.0.0"), b"short").unwrap();
    let mark = s.notice_mark();
    s.run("time.goTo", &json!({"step": 1})).unwrap();
    landed(&mut s, None);
    let errors: Vec<_> = s.notices_since(mark).iter().filter(|n| n.error).map(|n| n.text.clone()).collect();
    assert_eq!(errors.len(), 1, "{errors:?}");
    s.follow_time_landed();
    assert_eq!(s.notices_since(mark).iter().filter(|n| n.error).count(), 1, "said once");
    // Two layers on the failing step: one notice, with a count.
    s.run("time.goTo", &json!({"step": 0})).unwrap();
    s.run("layer.addZarr", &json!({"path": path, "variable": "t", "time": true, "name": "again"})).unwrap();
    let mark = s.notice_mark();
    s.run("time.goTo", &json!({"step": 1})).unwrap();
    let end = std::time::Instant::now() + std::time::Duration::from_secs(30);
    while s.zarr_waiting() {
        assert!(std::time::Instant::now() < end, "the failing step never landed");
        s.follow_time_landed();
        std::thread::sleep(std::time::Duration::from_millis(5)); // test-wait: legacy polling for the failed Zarr step
    }
    let errors: Vec<_> = s.notices_since(mark).iter().filter(|n| n.error).map(|n| n.text.clone()).collect();
    assert!(errors.len() == 1 && errors[0].contains("and 1 more layer:"), "{errors:?}");
    // A script's line waits for its step, so the next line reads it.
    s.run("time.goTo", &json!({"step": 0})).unwrap();
    std::fs::write(std::path::Path::new(&path).join("t/1.0.0"), f32s_of(100)).unwrap();
    let ran = s.run("script.run", &json!({"script": "time.goTo {\"step\": 1}"})).unwrap();
    assert!(ran["ran"].as_array().is_some_and(|r| r.len() == 1), "{ran}");
    assert_eq!(first(&s), Some(108.0), "a script's move is read before its next line");
    // The animation's frames draw their own steps: step 2 is read before its frame.
    let zip = std::env::temp_dir().join(format!("rustgis-zarr-offframe-{}.zip", std::process::id()));
    s.run("time.goTo", &json!({"step": 0})).unwrap();
    let r = s.run("time.export", &json!({"path": zip.display().to_string(), "width": 64, "height": 48, "from": "2001-03-01"})).unwrap();
    assert_eq!(r["frames"], 1, "{r}");
    let _ = std::fs::remove_file(zip);
    let _ = std::fs::remove_dir_all(dir);
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn permission_review_zarr_actorless_scoped_moves_wait_for_the_requested_step() {
    use crate::policy::{AgentAccess, Call, Effects, Outcome, Revocation, Scope};
    use std::sync::Arc;
    struct Live;
    impl Revocation for Live {
        fn allows(&self, _: Effects) -> bool {
            true
        }
    }
    let _cache = zarr_cache_lock();
    for agent in [false, true] {
        let (dir, path) = zarr_store_over_time(if agent { "review-agent-step" } else { "review-assistant-step" });
        let mut s = Session::new(Project::default());
        s.zarr_off_frame = true;
        let id = s.run("layer.addZarr", &json!({"path":path,"variable":"t","time":true})).unwrap()["layer"].as_u64().unwrap() as u32;
        let live = Arc::new(Live);
        let scope =
            if agent { Scope::agent(AgentAccess::Allow, false, "zarr-actorless", None, live) } else { Scope::assistant(1461, live) };
        let call = Call::command("time.goTo", json!({"step":1}));
        if agent {
            assert!(matches!(s.review(&scope, &call), Outcome::Allowed));
            s.run_scoped(scope, &call).unwrap();
        } else {
            let Outcome::NeedsApproval(pending) = s.review(&scope, &call) else { panic!("the assistant's local read must ask") };
            s.run_permitted(scope, pending.allow(), &call).unwrap();
        }
        // No frame has landed a worker: the actual command must have shown its own requested step.
        let raster = s.map().layer(id).unwrap().raster.as_ref().unwrap();
        assert_eq!(raster.time_zarr.as_ref().unwrap().shown, Some(1));
        assert_eq!(raster.data.as_ref().unwrap().bands[0].data[0], 108.0);
        assert!(s.actor.is_none() && !s.zarr_waiting());
        std::fs::remove_dir_all(dir).unwrap();
    }
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn permission_review_zarr_worker_rechecks_captured_still_before_a_local_read() {
    if isolate_process_test("tests::permission_review_zarr_worker_rechecks_captured_still_before_a_local_read") {
        return;
    }
    use crate::policy::{AgentAccess, Effects, Revocation, Scope};
    use crate::render::rustgis_tiles::cache;
    use std::sync::{
        Arc, Mutex,
        atomic::{AtomicBool, Ordering},
        mpsc,
    };
    let _cache = zarr_cache_lock();
    struct Live;
    impl Revocation for Live {
        fn allows(&self, _: Effects) -> bool {
            true
        }
    }
    let mut failures = Vec::new();
    for (tag, revoke_before, revoke_after, foreign_poll, scoped_poll) in [
        ("native", false, false, false, false),
        ("revoked-before", true, false, false, false),
        ("revoked-after", false, true, false, false),
        ("other-session", true, false, true, false),
        ("foreign-scope", true, false, false, true),
    ] {
        let (dir, path) = zarr_store_over_time(&format!("review-worker-{tag}"));
        let mut s = Session::new(Project::default());
        s.zarr_off_frame = true;
        let id = s.run("layer.addZarr", &json!({"path":path,"variable":"t","time":true})).unwrap()["layer"].as_u64().unwrap() as u32;
        let zt = s.map().layer(id).unwrap().raster.as_ref().unwrap().time_zarr.as_ref().unwrap();
        let key = crate::cmd::zarr::slice_key(zt, 1);
        let caller = std::thread::current().id();
        let live = Arc::new(AtomicBool::new(true));
        let current = live.clone();
        let held = AtomicBool::new(false);
        let (started, entered) = mpsc::sync_channel(1);
        let (release, released) = mpsc::sync_channel(1);
        let released = Mutex::new(released);
        let still = Arc::new(move || {
            if std::thread::current().id() != caller && !held.swap(true, Ordering::SeqCst) {
                let _ = started.send(());
                if released.lock().unwrap().recv_timeout(std::time::Duration::from_secs(10)).is_err() {
                    return false;
                }
            }
            current.load(Ordering::SeqCst)
        });
        let mut completed = 0;
        crate::cmd::zarr::landed_since(&mut completed);
        let mark = s.notice_mark();
        cache::with_still(still, || s.run("time.goTo", &json!({"step":1}))).unwrap();
        entered.recv_timeout(std::time::Duration::from_secs(10)).expect("the actual worker checks its initiating predicate");
        assert_eq!(s.map().layer(id).unwrap().raster.as_ref().unwrap().time_zarr.as_ref().unwrap().shown, Some(0));
        live.store(!revoke_before, Ordering::SeqCst);
        release.send(()).unwrap();
        let end = std::time::Instant::now() + std::time::Duration::from_secs(10);
        // This isolated scenario has one worker: observe completion before any frame can consume it.
        while !crate::cmd::zarr::landed_since(&mut completed) {
            assert!(std::time::Instant::now() < end, "the held worker never completed");
            std::thread::sleep(std::time::Duration::from_millis(2)); // test-wait: legacy polling for worker completion before a frame consumes it
        }
        if revoke_after {
            live.store(false, Ordering::SeqCst);
        }
        if foreign_poll {
            let mut other = Session::new(Project::default());
            other.zarr_off_frame = true;
            other.follow_time_landed();
        }
        if scoped_poll {
            let scope = Scope::agent(AgentAccess::Refuse, false, "foreign-zarr", None, Arc::new(Live));
            assert!(!s.with_scope(scope, |s| s.follow_time_landed()).unwrap(), "foreign scope must not consume the native completion");
            assert_eq!(s.map().layer(id).unwrap().raster.as_ref().unwrap().time_zarr.as_ref().unwrap().shown, Some(0));
            assert!(s.zarr_waiting(), "the original completion remains for its owner");
        }
        while s.zarr_waiting() {
            assert!(std::time::Instant::now() < end, "the completed Zarr worker never landed");
            s.follow_time_landed();
            std::thread::sleep(std::time::Duration::from_millis(2)); // test-wait: legacy polling for the completed Zarr step
        }
        let revoked = revoke_before || revoke_after;
        let raster = s.map().layer(id).unwrap().raster.as_ref().unwrap();
        let value = raster.data.as_ref().map(|data| data.bands[0].data[0]);
        if raster.time_zarr.as_ref().unwrap().shown != Some(1) || value != if revoked { None } else { Some(108.0) } {
            failures.push(format!("{tag}: completed read applied {value:?}"));
        }
        if crate::cmd::zarr::kept_slice(&key).is_some() != !revoke_before {
            failures.push(format!("{tag}: invalid cache publication"));
        }
        let errors = s.notices_since(mark).iter().filter(|notice| notice.error).count();
        if errors != usize::from(revoked) {
            failures.push(format!("{tag}: expected one failure notice when revoked, got {errors}"));
        }
        std::fs::remove_dir_all(dir).unwrap();
    }
    assert!(failures.is_empty(), "{failures:?}");
}

/// A cached slice and a cold local read both require the current initiating carrier.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn permission_review_zarr_slice_cache_never_bypasses_a_revoked_reader() {
    use crate::render::rustgis_tiles::cache;
    let _cache = zarr_cache_lock();
    let mut failures = Vec::new();
    for cached in [false, true] {
        let (dir, path) = zarr_store_over_time(&format!("review-cache-owner-{cached}"));
        let mut s = Session::new(Project::default());
        let id = s.run("layer.addZarr", &json!({"path":path,"variable":"t","time":true})).unwrap()["layer"].as_u64().unwrap() as u32;
        let zt = s.map().layer(id).unwrap().raster.as_ref().unwrap().time_zarr.as_ref().unwrap();
        let key = crate::cmd::zarr::slice_key(zt, 1);
        if cached {
            crate::cmd::zarr::read_step(zt, 1, key.clone()).unwrap();
        }
        let result = cache::with_still(std::sync::Arc::new(|| false), || crate::cmd::zarr::read_step(zt, 1, key.clone()));
        if result.is_ok() || crate::cmd::zarr::kept_slice(&key).is_some() != cached {
            failures.push(format!("cached={cached}: revoked reader obtained or published pixels"));
        }
        std::fs::remove_dir_all(dir).unwrap();
    }
    assert!(failures.is_empty(), "{failures:?}");
}

/// A Zarr store in a folder: its variables listed (with time labels), a slice added by command
/// and by Add Data, saved by folder and selection and read again when the project opens; a slice
/// the app read itself handed over by id.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn zarr_stores_in_folders_and_handed_over() {
    let dir = std::env::temp_dir().join(format!("rustgis-zarr-{}", std::process::id()));
    let store = dir.join("air.zarr");
    let _ = std::fs::remove_dir_all(&dir);
    for d in ["t", "lat", "lon", "time"] {
        std::fs::create_dir_all(store.join(d)).unwrap();
    }
    let arr = |shape: &str, chunks: &str, dtype: &str| {
        serde_json::from_str::<Value>(&format!(
            r#"{{"shape":{shape},"chunks":{chunks},"dtype":"{dtype}","compressor":null,"fill_value":null,"filters":null,"order":"C","zarr_format":2}}"#
        ))
        .unwrap()
    };
    let meta = json!({"metadata": {
        ".zgroup": {"zarr_format": 2},
        "t/.zarray": arr("[2,3,4]", "[1,3,4]", "<f4"),
        "t/.zattrs": {"_ARRAY_DIMENSIONS": ["time","lat","lon"], "units": "K"},
        "lat/.zarray": arr("[3]", "[3]", "<f4"),
        "lat/.zattrs": {"_ARRAY_DIMENSIONS": ["lat"], "units": "degrees_north"},
        "lon/.zarray": arr("[4]", "[4]", "<f4"),
        "lon/.zattrs": {"_ARRAY_DIMENSIONS": ["lon"], "units": "degrees_east"},
        "time/.zarray": arr("[2]", "[2]", "<i4"),
        "time/.zattrs": {"_ARRAY_DIMENSIONS": ["time"], "units": "days since 2001-01-01"},
    }, "zarr_consolidated_format": 1});
    std::fs::write(store.join(".zmetadata"), meta.to_string()).unwrap();
    std::fs::write(store.join(".zgroup"), r#"{"zarr_format":2}"#).unwrap();
    let f32s = |v: &[f32]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
    std::fs::write(store.join("lat/0"), f32s(&[10.0, 20.0, 30.0])).unwrap();
    std::fs::write(store.join("lon/0"), f32s(&[1.0, 2.0, 3.0, 4.0])).unwrap();
    std::fs::write(store.join("time/0"), [0i32, 31].iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>()).unwrap();
    for t in 0..2 {
        let v: Vec<f32> = (0..12).map(|i| (t * 100 + i) as f32).collect();
        std::fs::write(store.join(format!("t/{t}.0.0")), f32s(&v)).unwrap();
    }
    let path = store.display().to_string();
    let mut s = Session::new(Project::default());
    let info = s.run("raster.zarrInfo", &json!({"path": path})).unwrap();
    assert_eq!(info["count"], 1);
    assert_eq!(info["variables"][0]["dims"][0]["labels"], json!(["2001-01-01", "2001-02-01"]));
    let r = s.run("layer.addZarr", &json!({"path": path, "variable": "t", "index": {"time": 1}})).unwrap();
    assert_eq!((r["width"].as_u64(), r["height"].as_u64()), (Some(4), Some(3)), "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    let ras = s.map().layer(id).unwrap().raster.clone().unwrap();
    assert_eq!(ras.subdataset.as_deref(), Some("t[time=1]"));
    let data = ras.data.clone().unwrap();
    // North up: the last latitude row (30°N) first.
    assert_eq!(data.bands[0].data[..4], [108.0, 109.0, 110.0, 111.0]);
    // The project names the folder and the slice, and reads it again.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t.map().layers.iter().find(|l| l.is_raster()).and_then(|l| l.raster.as_ref()).and_then(|r| r.data.clone()).unwrap();
    assert_eq!(again.bands[0].data[..4], [108.0, 109.0, 110.0, 111.0]);
    // Add Data on the folder: the first variable, first step.
    let r = s.run("layer.addData", &json!({"path": path})).unwrap();
    let first = s.map().layer(r["layer"].as_u64().unwrap() as u32).and_then(|l| l.raster.as_ref()).and_then(|r| r.data.clone()).unwrap();
    assert_eq!(first.bands[0].data[0], 8.0);
    // A slice the app read: its GeoTIFF handed over by id, named by its store and selection.
    let tif = rustgis_data::raster::geotiff::write(&again, 0).unwrap();
    let id = s.download_started();
    assert!(s.download_landed(id, tif));
    let r = s
        .run("layer.addZarr", &json!({"url": "https://example.org/data/air.zarr", "variable": "t", "index": {"time": 1}, "ran": id}))
        .unwrap();
    let l = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
    assert!(l.name.starts_with("air t[time=1]"), "{}", l.name);
    assert!(s.run("layer.addZarr", &json!({"url": "https://example.org/a.zarr", "ran": id})).is_err(), "used once");
    for bad in [
        json!({}),
        json!({"path": path, "variable": "nope"}),
        json!({"path": path, "variable": "t", "index": {"time": 9}}),
        json!({"path": "/nowhere/x.zarr"}),
    ] {
        assert!(s.run("layer.addZarr", &bad).is_err(), "{bad}");
    }
    let _ = std::fs::remove_dir_all(dir);
}

/// A stand-in S3 endpoint: answers a listing, an object and a redirect, and keeps each request's
/// head (path and headers) for the test to look at.
fn serve_s3() -> (String, std::sync::Arc<std::sync::Mutex<Vec<String>>>) {
    use std::io::{Read, Write};
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let seen = std::sync::Arc::new(std::sync::Mutex::new(Vec::new()));
    let log = seen.clone();
    std::thread::spawn(move || {
        for stream in listener.incoming() {
            let Ok(mut s) = stream else { continue };
            let mut buf = [0u8; 8192];
            let read = s.read(&mut buf).unwrap_or(0);
            let req = String::from_utf8_lossy(&buf[..read]).to_string();
            let path = req.split_whitespace().nth(1).unwrap_or("/").to_string();
            log.lock().unwrap().push(req);
            let (status, body): (&str, &[u8]) = if path.starts_with("/s3-test-bucket?list-type=2") {
                ("200 OK", br#"<ListBucketResult><Name>s3-test-bucket</Name><IsTruncated>false</IsTruncated><Contents><Key>data/places.geojson</Key><Size>120</Size><LastModified>2024-01-01T00:00:00.000Z</LastModified></Contents><CommonPrefixes><Prefix>data/more/</Prefix></CommonPrefixes></ListBucketResult>"#)
            } else if path == "/" {
                (
                    "200 OK",
                    br#"<ListAllMyBucketsResult><Buckets><Bucket><Name>s3-test-bucket</Name></Bucket></Buckets></ListAllMyBucketsResult>"#,
                )
            } else if path.starts_with("/s3-test-bucket/data/places.geojson") {
                ("200 OK", br#"{"type": "FeatureCollection", "features": [{"type": "Feature", "properties": {"n": 1}, "geometry": {"type": "Point", "coordinates": [10, 20]}}]}"#)
            } else if path.starts_with("/s3-test-bucket/moved.geojson") {
                ("301 Moved Permanently\r\nLocation: http://127.0.0.1:9/elsewhere.geojson", b"")
            } else {
                ("404 Not Found", b"<Error><Code>NoSuchKey</Code><Message>The specified key does not exist.</Message></Error>")
            };
            let _ = write!(s, "HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n", body.len());
            let _ = s.write_all(body);
        }
    });
    (base, seen)
}

/// S3 through a connection with credentials: listings and objects by s3:// address, signed for
/// the connection's endpoint only; the secret never in a result; a signed request isn't
/// redirected.
#[test]
fn s3_connections_listings_and_objects() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::s3_connections_listings_and_objects") {
        return;
    }
    let (base, seen) = serve_s3();
    let mut s = Session::new(Project::default());
    let r = s
        .run(
            "s3.connect",
            &json!({"name": "s3-test", "endpoint": base, "buckets": ["s3-test-bucket"], "accessKeyId": "AKIDTEST", "secretAccessKey": "very-secret-key", "sessionToken": "token-1"}),
        )
        .unwrap();
    assert_eq!((r["signed"].as_bool(), r["credentials"].as_str()), (Some(true), Some("keys")));
    assert!(!r.to_string().contains("very-secret-key"));
    let listed = s.run("s3.connections", &Value::Null).unwrap();
    assert!(listed.to_string().contains("s3-test") && !listed.to_string().contains("very-secret-key"));
    // A blank form is anonymous: never the environment's or a profile's keys unless asked for.
    let r = s.run("s3.connect", &json!({"name": "s3-blank", "region": ""})).unwrap();
    assert_eq!(
        (r["signed"].as_bool(), r["credentials"].as_str(), r["region"].as_str()),
        (Some(false), Some("anonymous"), Some("us-east-1"))
    );
    s.run("s3.disconnect", &json!({"name": "s3-blank"})).unwrap();
    // A level of the bucket, and the connection's buckets; listing isn't an edit of the project.
    assert!(!s.dirty() && !s.can_undo());
    let r = s.run("s3.list", &json!({"url": "s3://s3-test-bucket/data/"})).unwrap();
    assert!(!s.dirty() && !s.can_undo(), "a listing is no edit");
    assert_eq!(r["prefixes"], json!(["data/more/"]));
    assert_eq!(r["objects"][0]["url"], "s3://s3-test-bucket/data/places.geojson");
    let r = s.run("s3.list", &json!({"connection": "s3-test"})).unwrap();
    assert_eq!(r["buckets"], json!(["s3-test-bucket"]));
    // An object by its s3:// address, signed with the connection's key (never its secret).
    let r = s.run("layer.addUrl", &json!({"url": "s3://s3-test-bucket/data/places.geojson"})).unwrap();
    assert_eq!(r["features"], 1);
    {
        let heads = seen.lock().unwrap();
        let get = heads.iter().find(|h| h.contains("/s3-test-bucket/data/places.geojson")).unwrap().to_ascii_lowercase();
        assert!(get.contains("authorization: aws4-hmac-sha256 credential=akidtest/"), "{get}");
        assert!(get.contains("x-amz-security-token: token-1") && get.contains("x-amz-content-sha256: unsigned-payload"));
        assert!(heads.iter().all(|h| !h.contains("very-secret-key")));
    }
    // A redirect isn't followed by a signed request; a missing key says so.
    let e = s.run("layer.addUrl", &json!({"url": "s3://s3-test-bucket/moved.geojson"})).unwrap_err();
    assert!(e.contains("redirect"), "{e}");
    assert!(s.run("layer.addUrl", &json!({"url": "s3://s3-test-bucket/nope.geojson"})).unwrap_err().contains("404"));
    // Bad parameters; credentials from this computer don't go to another endpoint.
    for bad in [
        json!({"name": "x", "endpoint": "ftp://h"}),
        json!({"name": "x", "accessKeyId": "A"}),
        json!({"name": "x", "region": "no such"}),
        json!({"name": "x", "buckets": ["NO_"]}),
        json!({"name": "x", "endpoint": "https://elsewhere.example", "profile": "default"}),
    ] {
        assert!(s.run("s3.connect", &bad).is_err(), "{bad}");
    }
    for bad in [json!({"url": "s3://"}), json!({"bucket": "NO_"}), json!({"connection": "nope"}), json!({"url": "https://x.org"})] {
        assert!(s.run("s3.list", &bad).is_err(), "{bad}");
    }
    s.run("s3.disconnect", &json!({"name": "s3-test"})).unwrap();
    assert!(s.run("s3.disconnect", &json!({"name": "s3-test"})).is_err());
    // Plugins never connect (they'd choose where the user's credentials go).
    assert!(crate::cmd::plugins::user_only("s3.connect"));
}

/// A streamed layer outside its zoom range reads nothing for the view, as if hidden: it is not
/// drawn there, so its features are not fetched (#412). Back in range, it reads again.
#[test]
fn streamed_layer_outside_its_zoom_range_reads_nothing() {
    use rustgis_data::{Dataset, Feature, Field, FieldType, Geometry, GeometryType, Value};
    let mut ds = Dataset::new("grid", GeometryType::Point, vec![Field::new("n", FieldType::Integer)]);
    for i in 0..200u32 {
        for j in 0..200u32 {
            let c = rustgis_geom::Coord::new(-179.0 + 1.79 * f64::from(i), -80.0 + 0.8 * f64::from(j));
            let n = u64::from(i * 200 + j);
            ds.features.push(Feature { id: n + 1, geometry: Some(Geometry::Point(c)), attrs: vec![Value::Int(n as i64)] });
        }
    }
    let (base, sent) = serve_ranges(rustgis_data::source::fgb::write(&ds).unwrap());
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/grid.fgb")})).unwrap();
    assert_eq!(r["streamed"], true, "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    // Drawn only when zoomed in beyond 1:10,000,000.
    s.run("layer.scaleRange", &json!({"layer": id, "min": 1e7})).unwrap();
    let before = sent.load(std::sync::atomic::Ordering::Relaxed);
    // Zoomed out (an export, which waits for its reads): not drawn, so not read.
    let v = view_of(&mut s, rustgis_geom::Extent::new(-60.0, -40.0, 60.0, 40.0));
    assert!(s.map().scale() > 1e7);
    crate::render::render_png(s.map_mut(), &v).unwrap();
    let l = s.map().layer(id).unwrap();
    assert!(l.dataset.features.is_empty() && l.source.as_ref().unwrap().window().is_none());
    assert_eq!(sent.load(std::sync::atomic::Ordering::Relaxed), before);
    // Zoomed in, inside the range: read and drawn.
    let v = view_of(&mut s, rustgis_geom::Extent::new(10.0, 10.0, 12.0, 11.0));
    assert!(s.map().scale() < 1e7);
    crate::render::render_png(s.map_mut(), &v).unwrap();
    let l = s.map().layer(id).unwrap();
    assert!(!l.dataset.features.is_empty(), "{:?}", l.source.as_ref().unwrap().error);
    assert!(sent.load(std::sync::atomic::Ordering::Relaxed) > before);
}

/// Load All Features on a layer whose web source is still opening waits for it to open, rather
/// than fail with "the layer's source isn't open" (the server here holds its answers a while).
#[test]
fn load_all_features_waits_for_a_source_still_opening() {
    use rustgis_data::{Dataset, Feature, Geometry, GeometryType};
    let mut ds = Dataset::new("pts", GeometryType::Point, vec![]);
    for i in 0..100u32 {
        let c = rustgis_geom::Coord::new(f64::from(i) * 0.1, 1.0);
        ds.features.push(Feature { id: u64::from(i) + 1, geometry: Some(Geometry::Point(c)), attrs: vec![] });
    }
    let fgb = rustgis_data::source::fgb::write(&ds).unwrap();
    let (base, _) = serve_ranges(fgb.clone());
    let mut s = Session::new(Project::default());
    s.run("layer.addUrl", &json!({"url": format!("{base}/pts.fgb")})).unwrap();
    let text = serde_json::to_string(&s.project).unwrap();
    let gate = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let (slow, _) = serve_gated(fgb, true, Some(gate.clone()));
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text.replace(&base, &slow)})).unwrap();
    let layer = t.map().layers.iter().find(|l| l.is_streamed()).unwrap().clone();
    // Started as the view starts it, and held by the server: still opening when the load begins.
    let mut started = layer.source.clone().unwrap();
    started.open().unwrap();
    assert!(!started.is_open() && started.is_pending());
    let load = std::thread::spawn(move || layer.load_all());
    // Still waiting while the server holds its answers, rather than failed at once.
    std::thread::sleep(std::time::Duration::from_millis(300)); // test-wait: legacy delay before asserting the source load is still blocked
    assert!(!load.is_finished(), "the load didn't wait for the source: {:?}", load.join().unwrap().err());
    gate.store(true, std::sync::atomic::Ordering::Relaxed);
    assert_eq!(load.join().unwrap().unwrap().features.len(), 100);
}

/// A FlatGeobuf and a GeoParquet by their address are read in place, by range: a view fetches a
/// small part of the file; the project keeps the address and reads it again; asked to, a file is
/// downloaded whole instead.
#[test]
fn flatgeobuf_and_geoparquet_by_address_are_read_in_place() {
    use rustgis_data::{Dataset, Feature, Field, FieldType, Geometry, GeometryType, Value};
    let mut ds = Dataset::new("grid", GeometryType::Point, vec![Field::new("n", FieldType::Integer)]);
    for i in 0..200u32 {
        for j in 0..200u32 {
            let c = rustgis_geom::Coord::new(-179.0 + 1.79 * f64::from(i), -80.0 + 0.8 * f64::from(j));
            let n = u64::from(i * 200 + j);
            ds.features.push(Feature { id: n + 1, geometry: Some(Geometry::Point(c)), attrs: vec![Value::Int(n as i64)] });
        }
    }
    let fgb = rustgis_data::source::fgb::write(&ds).unwrap();
    let total = fgb.len();
    let (base, sent) = serve_ranges(fgb.clone());
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/grid.fgb")})).unwrap();
    assert_eq!((r["inPlace"].as_bool(), r["streamed"].as_bool(), r["features"].as_u64()), (Some(true), Some(true), Some(40_000)), "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    // A view: read as the screen reads, in the background.
    let view = rustgis_geom::Extent::new(10.0, 10.0, 14.0, 13.0);
    let sync = |s: &mut Session| {
        let scale = s.map().scale();
        let mut pending = s.map_mut().sync_sources(&view, scale, false);
        let start = std::time::Instant::now();
        while pending && start.elapsed() < std::time::Duration::from_secs(30) {
            std::thread::sleep(std::time::Duration::from_millis(5)); // test-wait: legacy polling for streamed source reads
            pending = s.map_mut().sync_sources(&view, scale, false);
        }
        assert!(!pending);
    };
    sync(&mut s);
    let l = s.map().layer(id).unwrap();
    let w = l.source.as_ref().unwrap().window().unwrap().extent;
    assert!(!l.dataset.features.is_empty(), "{:?}", l.source.as_ref().unwrap().error);
    assert!(l.dataset.features.iter().all(|f| w.contains(f.geometry.as_ref().unwrap().extent().center())));
    let read = sent.load(std::sync::atomic::Ordering::Relaxed);
    assert!(read < total / 4, "{read} of {total} bytes read");
    // The project keeps the address, and reads it again.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.contains("grid.fgb") && !text.contains("embedded"));
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    sync(&mut t);
    let again = t.map().layers.iter().find(|l| l.is_streamed()).unwrap();
    assert!(!again.dataset.features.is_empty(), "{:?}", again.source.as_ref().unwrap().error);
    // Load All Features: every feature, fetched.
    assert_eq!(again.load_all().unwrap().features.len(), 40_000);
    // A project layer whose file can't be read in place (here a server that ignores ranges; a
    // GeoParquet without a bbox covering alike) is downloaded whole, not left empty, and keeps its
    // symbology; the project still keeps the address.
    let (plain, _) = serve_file(fgb.clone(), false);
    let mut w = Session::new(Project::default());
    w.run("project.openText", &json!({"text": text.replace(&base, &plain)})).unwrap();
    let renderer = w.map().layers.iter().find(|l| l.is_streamed()).unwrap().renderer.clone();
    sync(&mut w);
    let whole = w.map().layers.iter().find(|l| l.is_streamed()).unwrap();
    assert!(!whole.dataset.features.is_empty(), "{:?}", whole.source.as_ref().unwrap().error);
    assert_eq!(whole.renderer, renderer);
    assert!(serde_json::to_string(&w.project).unwrap().contains(&plain));
    // A project written by another app may list no fields for a streamed layer: it gets the
    // source's, so its features keep their attributes (and a renderer on a field finds it).
    let mut bare: serde_json::Value = serde_json::from_str(&text).unwrap();
    for l in bare["maps"][0]["layers"].as_array_mut().unwrap() {
        l["dataset"]["fields"] = json!([]);
    }
    let mut v = Session::new(Project::default());
    v.run("project.openText", &json!({"text": bare.to_string()})).unwrap();
    // Load All Features before the layer has drawn keeps them too.
    let all = v.map().layers.iter().find(|l| l.is_streamed()).unwrap().load_all().unwrap();
    assert_eq!(all.fields.iter().map(|f| f.name.as_str()).collect::<Vec<_>>(), ["n"]);
    sync(&mut v);
    let l = v.map().layers.iter().find(|l| l.is_streamed()).unwrap();
    assert_eq!(l.dataset.fields.iter().map(|f| f.name.as_str()).collect::<Vec<_>>(), ["n"]);
    // The values themselves, not nulls padded in for a missing field.
    assert!(!l.dataset.features.is_empty());
    assert!(l.dataset.features.iter().all(|f| f.attrs.len() == 1 && matches!(f.attrs[0], Value::Int(_))));
    // Copies of a layer still opening (undo snapshots, Load All Features) all open: they share
    // what opening brought, none takes it from the others.
    // The server holds its answers, so the copies are made while the header is still on its way.
    let gate = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let (other, _) = serve_gated(fgb.clone(), true, Some(gate.clone()));
    let mut u = Session::new(Project::default());
    u.run("project.openText", &json!({"text": text.replace(&base, &other)})).unwrap();
    let mut a = u.map().layers.iter().find(|l| l.is_streamed()).unwrap().source.clone().unwrap();
    a.open().unwrap();
    assert!(!a.is_open() && a.is_pending(), "opened before its header was fetched");
    let mut b = a.clone();
    gate.store(true, std::sync::atomic::Ordering::Relaxed);
    a.wait_open(std::time::Duration::from_secs(60));
    b.wait_open(std::time::Duration::from_secs(60));
    assert!(a.is_open() && b.is_open(), "{:?} {:?}", a.error, b.error);

    // A GeoParquet (with its bbox covering), from its footer at the end.
    let pq = rustgis_data::source::parquet::write(&ds).unwrap();
    let (base, _) = serve_ranges(pq);
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/grid.parquet"), "name": "PQ"})).unwrap();
    assert_eq!(r["inPlace"].as_bool(), Some(true), "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    sync(&mut s);
    let l = s.map().layer(id).unwrap();
    assert!(!l.dataset.features.is_empty(), "{:?}", l.source.as_ref().unwrap().error);
    assert_eq!(l.name, "PQ");

    // Asked to: downloaded whole.
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/grid.parquet"), "whole": true, "name": "Whole"})).unwrap();
    assert!(r.get("inPlace").is_none(), "{r}");
    // A server that ignores ranges answers the footer's request with the whole, longer file:
    // downloaded whole instead, not an error.
    let mut pq = rustgis_data::source::parquet::write(&ds).unwrap();
    // Pad before the footer so compression cannot shrink this oversized-response fixture below
    // the initial footer request. Column offsets and the footer's metadata length stay valid.
    let footer_len = 8 + u32::from_le_bytes(pq[pq.len() - 8..pq.len() - 4].try_into().unwrap()) as usize;
    let footer = pq.split_off(pq.len() - footer_len);
    pq.resize(pq.len().max(256 << 10), 0);
    pq.extend(footer);
    assert!(pq.len() > 256 << 10);
    let (base, _) = serve_file(pq, false);
    let r = s.run("layer.addUrl", &json!({"url": format!("{base}/grid.parquet"), "name": "NoRanges"})).unwrap();
    assert!(r.get("inPlace").is_none(), "{r}");
    assert!(s.map().layer_by_name("NoRanges").is_some(), "{r}");
    // A file that isn't one: an error, not a hang.
    let (base, _) = serve_ranges(b"not a flatgeobuf at all".to_vec());
    assert!(s.run("layer.addUrl", &json!({"url": format!("{base}/x.fgb")})).is_err());
}

/// Data sources: what was added lands in Recent (once, newest first); favourites and saved
/// sources are kept and removed by command; nothing kept holds a secret; the library lists
/// well-known public sources.
#[test]
fn data_sources_recent_favourites_and_saved() {
    let dir = std::env::temp_dir().join(format!("rustgis-sources-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("towns.geojson");
    std::fs::write(
        &path,
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","properties":{},"geometry":{"type":"Point","coordinates":[1,2]}}]}"#,
    )
    .unwrap();
    let mut s = Session::new(Project::default());
    let p = path.display().to_string();
    s.run("layer.addData", &json!({"path": p})).unwrap();
    s.run("layer.addSample", &json!({"name": "cities"})).unwrap();
    // A failed add isn't a source.
    assert!(s.run("layer.addData", &json!({"path": dir.join("missing.geojson").display().to_string()})).is_err());
    let l = s.run("sources.list", &Value::Null).unwrap();
    let recent: Vec<&str> = l["recent"].as_array().unwrap().iter().filter_map(|r| r["address"].as_str()).collect();
    assert_eq!(recent, ["cities", p.as_str()]);
    assert_eq!(l["recent"][1]["name"], "towns");
    assert_eq!(l["recent"][1]["addWith"], "layer.addData {path}");
    assert!(l["library"].as_array().unwrap().iter().any(|x| x["group"] == "Catalogs" && x["kind"] == "stac"));
    // Favourites and saved services, kept without their secrets.
    s.run("sources.favourite", &json!({"kind": "file", "address": p})).unwrap();
    let r = s.run("sources.save", &json!({"kind": "service", "address": "https://me:pw@gis.example/wms?token=abc&map=m", "name": "My WMS", "extra": {"type": "wms", "password": "x"}})).unwrap();
    assert_eq!(r["address"], "https://gis.example/wms?map=m");
    s.run("sources.save", &json!({"kind": "database", "address": "postgres:host=h dbname=g user=u password=secret"})).unwrap();
    let text = s.sources.to_json();
    for secret in ["pw", "abc", "secret", "\"x\""] {
        assert!(!text.contains(secret), "{secret} in {text}");
    }
    // The app keeps them in its preferences and reads them back.
    let back = rustgis_engine_sources_roundtrip(&text);
    assert_eq!((back.favourites.len(), back.saved.len(), back.recent.len()), (1, 2, 2));
    // Removed by list, kind and address; an unknown one is an error.
    s.run("sources.favourite", &json!({"kind": "file", "address": p, "on": false})).unwrap();
    assert!(s.sources.favourites.is_empty());
    s.run("sources.remove", &json!({"list": "saved", "kind": "service", "address": "https://gis.example/wms?map=m"})).unwrap();
    assert_eq!(s.sources.saved.len(), 1);
    for bad in [
        json!({"list": "saved", "kind": "service", "address": "https://nowhere"}),
        json!({"list": "elsewhere", "kind": "file", "address": "x"}),
        json!({"kind": "nope", "address": "x"}),
    ] {
        assert!(s.run("sources.remove", &bad).is_err(), "{bad}");
    }
    assert!(s.run("sources.save", &json!({"kind": "nope", "address": "x"})).is_err());
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
fn layer_address_redaction_preserves_templates_and_local_paths() {
    let cases = [
        ("https://{switch:a,b}.host/{z}/{x}/{y}@2x.png?key=secret&map=m#token", "https://{switch:a,b}.host/{z}/{x}/{y}@2x.png?map=m"),
        ("HTTPS://u:p@host/data?token=secret&f=json", "HTTPS://host/data?f=json"),
        ("s3://u:p@bucket/data?X-Amz-Signature=secret", "s3://bucket/data"),
        ("/tmp/data?key=not-a-web-secret", "/tmp/data?key=not-a-web-secret"),
        ("upload:map?token=local", "upload:map?token=local"),
        ("postgres:host=localhost dbname=gis", "postgres:host=localhost dbname=gis"),
        ("postgresql://user@host.invalid/db%40tag", "postgresql://user@host.invalid/db%40tag"),
    ];
    for (original, expected) in cases {
        let address = match crate::durable::public_address(original) {
            crate::durable::Kept::Unchanged => original.to_owned(),
            crate::durable::Kept::Changed(address) => address,
            crate::durable::Kept::Withheld(_) => panic!("valid address was withheld: {original}"),
        };
        assert_eq!(address, expected);
    }
    let original = "postgresql://user:p@ss/word@host.invalid/db";
    let mut s = world();
    s.map_mut().layers[0].dataset.source = Some(original.into());
    let (text, report) = s.project.saved_text(None).unwrap();
    let saved: Value = serde_json::from_str(&text).unwrap();
    assert_eq!(saved["maps"][0]["layers"][0]["dataset"]["source"], "postgresql:");
    assert_eq!(report.withheld, 1, "ambiguous connection output is counted instead of retargeted");
    assert_eq!(s.map().layers[0].dataset.source.as_deref(), Some(original), "the live connection is unchanged");
    let prefix = crate::render::rustgis_tiles::s3::ANONYMOUS;
    let crate::durable::Kept::Changed(anonymous) =
        crate::durable::public_address(&format!("{prefix}https://bucket.example/a?token=secret"))
    else {
        panic!("anonymous address was not redacted")
    };
    assert_eq!(anonymous, format!("{prefix}https://bucket.example/a"));
}

/// A COG's look isn't a key: it stays in a saved address. The address's keys still go, and so does
/// any other fragment (OAuth and SAS links carry tokens there), however much it resembles a look.
#[test]
fn layer_address_redaction_keeps_a_cogs_look() {
    let prefix = crate::render::rustgis_tiles::s3::ANONYMOUS;
    let bound = rustgis_data::login_address::bind("0123456789abcdef", "https://h.example", "https://h.example/a.tif#range=0,1000").unwrap();
    let cases = [
        // Nothing to take out: no change at all.
        ("https://h.example/a.tif#range=0,1000".to_string(), "https://h.example/a.tif#range=0,1000".to_string()),
        (
            "s3://bucket/a.tif#bands=2,3,4&range=-0.5,0.5&dequantize=aef".into(),
            "s3://bucket/a.tif#bands=2,3,4&range=-0.5,0.5&dequantize=aef".into(),
        ),
        (format!("{prefix}https://h.example/a.tif#bands=1"), format!("{prefix}https://h.example/a.tif#bands=1")),
        // Its keys go, its look stays.
        ("https://u:p@h.example/a.tif?token=s3cret&v=1#range=0,1000".into(), "https://h.example/a.tif?v=1#range=0,1000".into()),
        ("https://u:p@h.example#range=0,1000".into(), "https://h.example#range=0,1000".into()),
        (format!("{prefix}https://h.example/a.tif?token=s3cret#bands=1"), format!("{prefix}https://h.example/a.tif#bands=1")),
        (bound, "https://h.example/a.tif#range=0,1000".into()),
        // Not a look: it goes as before.
        ("https://h.example/a.tif#access_token=s3cret".into(), "https://h.example/a.tif".into()),
        ("https://h.example/a.tif#range=0,1000&token=s3cret".into(), "https://h.example/a.tif".into()),
        ("https://h.example/a.tif#dequantize=s3cret".into(), "https://h.example/a.tif".into()),
        ("https://h.example/a.tif#range=0,1000?token=s3cret".into(), "https://h.example/a.tif".into()),
        ("https://h.example/a.tif#dequantize=aef?token=s3cret".into(), "https://h.example/a.tif".into()),
        // A word `dequantize` doesn't have: a reader takes it as a look, a saved file doesn't.
        ("https://h.example/a.tif#range=0,1000&dequantize=s3cret".into(), "https://h.example/a.tif".into()),
        ("cog:{z}/{x}/{y}@https://h.example/a.tif#dequantize=s3cret".into(), "cog:{z}/{x}/{y}@https://h.example/a.tif".into()),
        (
            rustgis_data::s3_address::bind("", "s3.example.org", "https://h.example/a.tif#dequantize=s3cret").unwrap(),
            rustgis_data::s3_address::bind("", "s3.example.org", "https://h.example/a.tif").unwrap(),
        ),
        // Its own words stay.
        ("https://h.example/a.tif#range=0,1000&dequantize=none".into(), "https://h.example/a.tif#range=0,1000&dequantize=none".into()),
        ("cog:{z}/{x}/{y}@https://h.example/a.tif#dequantize=aef".into(), "cog:{z}/{x}/{y}@https://h.example/a.tif#dequantize=aef".into()),
        ("https://h.example/a.tif#range=0,1000&cube=1".into(), "https://h.example/a.tif#range=0,1000&cube=1".into()),
        ("https://h.example/a.tif#cube=s3cret".into(), "https://h.example/a.tif".into()),
        // A look after another fragment: only the look stays.
        ("https://h.example/a.tif#sig=s3cret#range=0,1000".into(), "https://h.example/a.tif#range=0,1000".into()),
    ];
    for (given, expected) in &cases {
        let address = match crate::durable::public_address(given) {
            crate::durable::Kept::Unchanged => given.clone(),
            crate::durable::Kept::Changed(address) => address,
            crate::durable::Kept::Withheld(_) => panic!("valid address was withheld: {given}"),
        };
        assert_eq!(&address, expected, "from {given}");
    }
}

/// A data cube saved with one range for all its dates opens with that range, and saving it says
/// nothing about keys. A key among its addresses goes and is counted, and only that one.
#[test]
fn saved_cubes_keep_their_look() {
    let mut s = Session::new(Project::default());
    let mut cube = rustgis_map::TileLayer::new("Cube", rustgis_map::TileKind::Cog, "https://h.example/2021.tif#range=0,1000");
    cube.time_urls = vec![(1.0, "https://h.example/2020.tif#range=0,1000".into()), (2.0, "https://h.example/2021.tif#range=0,1000".into())];
    let expected = (cube.url.clone(), cube.time_urls.clone());
    s.map_mut().tiles.push(cube);
    let dir = std::env::temp_dir().join(format!("rustgis-cube-look-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("cube.rgis");

    // Clean: nothing was taken out, so nothing is said.
    let saved = s.run("project.saveAs", &json!({"path": path})).unwrap();
    assert_eq!(saved["stripped"], 0, "{saved}");
    assert!(!s.notices.iter().any(|n| n.text.contains("saved without their keys")));
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": path})).unwrap();
    let opened = &t.map().tiles[0];
    assert_eq!((opened.url.clone(), opened.time_urls.clone()), expected);

    // Lossy: one date's token goes and is counted; its look stays; the open project keeps it all.
    let with_key = "https://h.example/2020.tif?token=s3cret#range=0,1000";
    s.map_mut().tiles[0].time_urls[0].1 = with_key.into();
    let saved = s.run("project.saveAs", &json!({"path": path})).unwrap();
    assert_eq!(saved["stripped"], 1, "{saved}");
    assert!(s.notices.iter().any(|n| n.text.contains("1 layer address(es) were saved without their keys")));
    assert_eq!(s.map().tiles[0].time_urls[0].1, with_key);
    let text = std::fs::read_to_string(&path).unwrap();
    assert!(!text.contains("s3cret") && text.contains("https://h.example/2020.tif#range=0,1000"), "{text}");
    // Opened again before RustGIS closes, it has its token back, with its look.
    t.run("project.open", &json!({"path": path})).unwrap();
    assert_eq!(t.map().tiles[0].time_urls[0].1, with_key);

    // A cube of one file: its address is all that keeps it a tile layer when its project opens.
    let one_file = "https://h.example/2020.tif#range=0,1000&cube=1";
    let mut one = Session::new(Project::default());
    one.map_mut().tiles.push(rustgis_map::TileLayer::new("One date", rustgis_map::TileKind::Cog, one_file));
    let saved = one.run("project.saveAs", &json!({"path": path})).unwrap();
    assert_eq!(saved["stripped"], 0, "{saved}");
    t.run("project.open", &json!({"path": path})).unwrap();
    assert_eq!(t.map().tiles[0].url, one_file);
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
fn saved_layer_files_keep_no_address_secrets() {
    let mut s = world();
    let feature = s.map().layers[0].id;
    let dataset_url = "https://user:dataset-password@gis.example/features?access_token=dataset-token&f=json";
    let source_url = "https://gis.example/roads.fgb?sig=source-signature&sv=1&collection=roads";
    {
        let layer = s.map_mut().layer_mut(feature).unwrap();
        layer.dataset.source = Some(dataset_url.into());
        layer.source = Some(serde_json::from_value(json!({"path":source_url})).unwrap());
    }
    let added = s.run("layer.addDataBytes", &json!({"fileName":"dem.tif","name":"Protected raster","data":dem_b64()})).unwrap();
    let raster = added["layer"].as_u64().unwrap() as u32;
    let raster_url = "https://user:raster-password@gis.example/dem.tif?api_key=raster-key&band=1";
    let zarr_url = "https://gis.example/air.zarr?token=zarr-token&variable=air";
    {
        let layer = s.map_mut().layer_mut(raster).unwrap().raster.as_mut().unwrap();
        layer.path = Some(raster_url.into());
        layer.time_zarr = Some(rustgis_map::raster::ZarrTime { store: zarr_url.into(), ..Default::default() });
    }
    for id in [feature, raster] {
        let (_, bytes) = crate::cmd::items::item_bytes(&mut s, "layer", &json!({"layer":id})).unwrap();
        let exported: Value = serde_json::from_slice(&bytes).unwrap();
        if id == feature {
            assert_eq!(exported["dataset"]["source"], "https://gis.example/features?f=json");
            assert_eq!(exported["source"]["path"], "https://gis.example/roads.fgb?collection=roads");
        } else {
            assert_eq!(exported["raster"]["path"], "https://gis.example/dem.tif?band=1");
            assert_eq!(exported["raster"]["time_zarr"]["store"], "https://gis.example/air.zarr?variable=air");
        }
    }
    let layer = s.map().layer(feature).unwrap();
    assert_eq!(layer.dataset.source.as_deref(), Some(dataset_url));
    assert_eq!(layer.source.as_ref().unwrap().path.as_deref(), Some(source_url));
    let layer = s.map().layer(raster).unwrap().raster.as_ref().unwrap();
    assert_eq!(layer.path.as_deref(), Some(raster_url));
    assert_eq!(layer.time_zarr.as_ref().unwrap().store, zarr_url);
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn database_authorization_failures_do_not_wait_for_password() {
    use std::io::{Read, Write};
    for (name, message) in [("HBA blocked", "no pg_hba.conf entry for host"), ("Missing role", "role \"missing\" does not exist")] {
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let port = listener.local_addr().unwrap().port();
        let server = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().unwrap();
            stream.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();
            let mut length = [0; 4];
            stream.read_exact(&mut length).unwrap();
            let n = u32::from_be_bytes(length);
            assert!((4..=65536).contains(&n));
            stream.read_exact(&mut vec![0; (n - 4) as usize]).unwrap();
            let body = format!("SFATAL\0VFATAL\0C28000\0M{message}\0\0");
            stream.write_all(b"E").unwrap();
            stream.write_all(&((body.len() + 4) as u32).to_be_bytes()).unwrap();
            stream.write_all(body.as_bytes()).unwrap();
        });
        let dsn = format!("postgres:host=127.0.0.1 port={port} dbname=review_auth user=missing sslmode=disable");
        let mut project = world().project;
        project.map_mut().layers[0].source =
            Some(serde_json::from_value(json!({"postgis":{"database":dsn,"table":"roads","family":"Lines"}})).unwrap());
        let mut s = Session::new(Project::default());
        s.run("connection.new", &json!({"kind":"postgres","name":name,"address":dsn})).unwrap();
        s.run("project.openText", &json!({"text":serde_json::to_string(&project).unwrap()})).unwrap();
        server.join().unwrap();
        let source = s.map().layers[0].source.as_ref().unwrap();
        assert!(source.error.as_deref().unwrap().contains(message));
        assert!(!source.login, "{message} cannot be fixed by a password");
        assert!(!s.notices.iter().any(|n| n.text.contains(name)));
        assert!(s.run("connection.list", &Value::Null).unwrap()["connections"][0].get("waiting").is_none());
    }
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn database_layers_wait_for_their_connection_login() {
    use std::io::{Read, Write};
    let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
    let port = listener.local_addr().unwrap().port();
    std::thread::spawn(move || {
        for mut stream in listener.incoming().take(16).flatten() {
            stream.set_read_timeout(Some(std::time::Duration::from_secs(5))).unwrap();
            let mut length = [0; 4];
            if stream.read_exact(&mut length).is_err() {
                continue;
            }
            let n = u32::from_be_bytes(length);
            if !(4..=65536).contains(&n) {
                continue;
            }
            let mut startup = vec![0; (n - 4) as usize];
            if stream.read_exact(&mut startup).is_err() || stream.write_all(b"R\0\0\0\x08\0\0\0\x03").is_err() {
                continue;
            }
            let mut kind = [0];
            if stream.read_exact(&mut kind).is_err() || kind[0] != b'p' || stream.read_exact(&mut length).is_err() {
                continue;
            }
            let n = u32::from_be_bytes(length);
            if !(4..=65536).contains(&n) {
                continue;
            }
            let mut password = vec![0; (n - 4) as usize];
            if stream.read_exact(&mut password).is_err() {
                continue;
            }
            let body = b"SFATAL\0VFATAL\0C28P01\0Mpassword authentication failed for user \"me\"\0\0";
            let _ = stream.write_all(b"E");
            let _ = stream.write_all(&((body.len() + 4) as u32).to_be_bytes());
            let _ = stream.write_all(body);
        }
    });
    let dsn = format!("postgres:host=127.0.0.1 port={port} dbname=waiting_login user=me sslmode=disable");
    let down = "postgres:host=127.0.0.1 port=1 dbname=waiting_down user=me sslmode=disable";
    let mut s = world();
    for (layer, database) in s.map_mut().layers.iter_mut().zip([dsn.as_str(), dsn.as_str(), down]) {
        layer.source = Some(serde_json::from_value(json!({"postgis":{"database":database,"table":"roads","family":"Lines"}})).unwrap());
    }
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("connection.new", &json!({"kind":"postgres","name":"Production GIS","address":dsn})).unwrap();
    t.run("connection.new", &json!({"kind":"postgres","name":"Down","address":down})).unwrap();
    t.run("project.openText", &json!({"text":text})).unwrap();
    for layer in t.map().layers.iter().take(2) {
        // No password has been given: this exercises tokio-postgres's client-side config error,
        // before the later login attempts exercise the server's 28P01 response.
        assert!(layer.source.as_ref().unwrap().error.as_deref().unwrap().contains("password missing"));
        assert!(layer.source.as_ref().unwrap().login);
        assert_eq!(t.connections.for_layer(layer).unwrap().name, "Production GIS");
    }
    assert!(t.map().layers.iter().skip(3).all(|l| t.connections.for_layer(l).is_none()));
    let third = t.map().layers[2].source.as_ref().unwrap();
    assert!(third.error.is_some() && !third.login);
    assert!(t.notices.iter().any(|n| n.text.contains("2 layer(s)") && n.text.contains("Production GIS")));
    assert!(!t.notices.iter().any(|n| n.text.contains("Down")));
    let listed = t.run("connection.list", &Value::Null).unwrap();
    assert_eq!(listed["connections"][0]["waiting"], 2);
    assert!(listed["connections"][1].get("waiting").is_none());
    let result = t.run("connection.login", &json!({"id":"Production GIS","password":"wrong"})).unwrap();
    assert_eq!(result["reopened"], 0);
    assert_eq!(result["failed"], 2);
    assert!(t.map().layers.iter().take(2).all(|l| l.source.as_ref().unwrap().login));
    assert_eq!(t.run("connection.list", &Value::Null).unwrap()["connections"][0]["waiting"], 2);
    // Duplicate addresses have no inferred connection identity; either can be selected explicitly.
    t.run("connection.new", &json!({"kind":"postgres","name":"Same database","address":dsn})).unwrap();
    assert!(t.connections.for_layer(&t.map().layers[0]).is_none());
    let result = t.run("connection.login", &json!({"id":"Same database","password":"wrong"})).unwrap();
    assert_eq!(result["failed"], 2);
}

/// An autosaved recovery copy (#873) leaves out layer secrets as a save does, from a copy of the
/// project (the open one keeps them), and isn't registered as a file this process wrote: frequent
/// copies don't evict saved snapshots, and opening a copy's text restores no secret.
#[test]
fn recovery_copies_keep_no_layer_tokens_and_restore_none() {
    let mut s = world();
    let url = "https://gis.example/arcgis/rest/services/a/MapServer/tile/{z}/{y}/{x}?token=s3cret";
    s.run("map.addTiles", &json!({"url":url,"name":"Secured"})).unwrap();
    let text = s.project.clone().recovery_text().unwrap();
    assert!(!text.contains("s3cret") && text.contains("MapServer/tile/{z}/{y}/{x}"));
    assert!(s.map().tiles.iter().any(|t| t.url == url), "the open project keeps its token");
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text":text})).unwrap();
    assert!(t.map().tiles.iter().any(|t| t.url.contains("MapServer/tile")));
    assert!(!serde_json::to_string(&t.project).unwrap().contains("s3cret"));
}

#[test]
fn saved_projects_keep_no_layer_tokens() {
    let mut s = world();
    let url = "https://gis.example/arcgis/rest/services/a/MapServer/tile/{z}/{y}/{x}?token=s3cret-tile";
    // Its legend, built from the service's address, with the key in it too.
    let legend = "https://gis.example/wms?key=l3g-secret&SERVICE=WMS&REQUEST=GetLegendGraphic&LAYER=a";
    s.run("map.addTiles", &json!({"url":url,"name":"Secured","legend":legend})).unwrap();
    let layer = s.map().layers[0].id;
    s.map_mut().layers[0].dataset.source = Some("https://u:pw-secret@gis.example/f?f=json&access_token=tok2-secret".into());
    s.map_mut().service_groups.push(rustgis_map::ServiceGroup {
        id: 123,
        name: "Protected service".into(),
        url: "https://gis.example/wfs?key=k3y-secret&map=m".into(),
        kind: "wfs".into(),
        anonymous: false,
        expanded: true,
        children: vec![rustgis_map::ServiceChild {
            layer,
            collection: "roads".into(),
            source_url: "https://gis.example/roads?sig=x-secret&sv=1".into(),
        }],
    });
    let path = std::env::temp_dir().join(format!("rustgis-token-audit-{}.rgis", std::process::id()));
    let result = s.run("project.saveAs", &json!({"path":path})).unwrap();
    let text = std::fs::read_to_string(&path).unwrap();
    for secret in ["s3cret-tile", "pw-secret@", "tok2-secret", "k3y-secret", "sig=x-secret", "l3g-secret"] {
        assert!(!text.contains(secret), "{secret} leaked into the file");
    }
    assert!(text.contains("MapServer/tile/{z}/{y}/{x}") && text.contains("map=m") && text.contains("REQUEST=GetLegendGraphic"));
    assert!(result["stripped"].as_u64().unwrap() >= 4);
    assert!(s.notices.iter().any(|n| n.text.contains("saved without their keys")));
    assert!(s.map().tiles.iter().any(|t| t.url == url));
    // Every kind of item file, each with something in the project to write.
    s.run("style.new", &json!({"layer": "Cities", "name": "Cities"})).unwrap();
    s.run("gp.run", &json!({"tool": "buffer", "params": {"input": "Cities", "distance": 100}})).unwrap();
    s.run("task.new", &Value::Null).unwrap();
    s.run("model.new", &json!({"fromHistory": true})).unwrap();
    s.run("report.new", &json!({"layer": "Cities"})).unwrap();
    s.run("presentation.new", &Value::Null).unwrap();
    s.run("notebook.new", &Value::Null).unwrap();
    // Kinds that hold no layer addresses, or need more than the sample gives.
    let exempt = [
        ("ramps", "colour ramps hold no addresses"),
        ("dlPackage", "a trained model holds no addresses"),
        ("hostedImagery", "tiles rendered from a raster layer: pictures, not addresses"),
        ("linkChart", "needs relationships the sample lacks"),
    ];
    let mut report = Vec::new();
    for &(kind, _, _) in crate::cmd::items::ITEMS {
        if exempt.iter().any(|(k, _)| *k == kind) {
            continue;
        }
        let bytes = match crate::cmd::items::item_bytes(&mut s, kind, &Value::Null) {
            Ok((_, bytes)) => bytes,
            Err(e) => {
                report.push(format!("{kind}: {e}"));
                continue;
            }
        };
        let packaged = if bytes.starts_with(b"PK") {
            rustgis_data::zip::read_matching(&bytes, |_| true)
                .unwrap()
                .into_iter()
                .map(|(_, b)| String::from_utf8_lossy(&b).into_owned())
                .collect::<String>()
        } else {
            String::from_utf8_lossy(&bytes).into_owned()
        };
        for secret in ["s3cret-tile", "pw-secret@", "tok2-secret", "k3y-secret", "sig=x-secret", "l3g-secret"] {
            if packaged.contains(secret) {
                report.push(format!("{kind}: leaked {secret}"));
            }
        }
        if kind == "projectPackage" {
            // Even a hostile archive carrying the exact registered JSON must not restore it.
            let hostile = rustgis_data::zip::write(&[("exact.rgis".into(), text.as_bytes().to_vec())]).unwrap();
            let package_path = path.with_extension("rgispkg");
            std::fs::write(&package_path, hostile).unwrap();
            let mut opened = Session::new(Project::default());
            opened.run("project.open", &json!({"path":package_path})).unwrap();
            assert!(!serde_json::to_string(&opened.project).unwrap().contains("s3cret-tile"));
            opened.run("project.openText", &json!({"text":text,"package":true})).unwrap();
            assert!(!serde_json::to_string(&opened.project).unwrap().contains("s3cret-tile"));
            std::fs::remove_file(package_path).unwrap();
        }
    }
    assert!(report.is_empty(), "{report:#?}");
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path":path})).unwrap();
    assert!(t.map().tiles.iter().any(|t| t.url == url));
    assert!(t.map().layers[0].dataset.source.as_deref().unwrap().contains("tok2-secret"));
    let modified = text.replace("\"name\":\"Secured\"", "\"name\":\"Secures\"");
    assert_ne!(text, modified);
    t.run("project.openText", &json!({"text":modified})).unwrap();
    let live = serde_json::to_string(&t.project).unwrap();
    for secret in ["s3cret-tile", "pw-secret@", "tok2-secret", "k3y-secret", "sig=x-secret"] {
        assert!(!live.contains(secret), "{secret} restored into a modified hostile file");
    }
    let public = url.split('?').next().unwrap();
    let mut hand = world();
    hand.run("map.addTiles", &json!({"url":public,"name":"Hand made"})).unwrap();
    t.run("project.openText", &json!({"text":serde_json::to_string(&hand.project).unwrap()})).unwrap();
    assert!(t.map().tiles.iter().any(|t| t.url == public));
    assert!(!serde_json::to_string(&t.project).unwrap().contains("s3cret-tile"));
    std::fs::remove_file(path).unwrap();
}

#[test]
fn connections_commands() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::connections_commands") {
        return;
    }
    use crate::render::rustgis_tiles::s3;
    let mut s = Session::new(Project::default());
    let a = s.run("connection.new", &json!({"kind":"wms","address":"https://a.example/wms?token=t","name":"A"})).unwrap();
    assert_eq!(a["stripped"], true);
    assert_eq!(a["address"], "https://a.example/wms");
    s.run("connection.new", &json!({"kind":"wms","address":"https://a.example/wms","name":"B"})).unwrap();
    assert!(s.run("connection.new", &json!({"kind":"wms","address":"https://b.example/wms","name":"a"})).is_err());
    s.run("connection.edit", &json!({"id":"A","name":"C","group":"Work"})).unwrap();
    let listed = s.run("connection.list", &json!({"group":"work"})).unwrap();
    assert_eq!(listed["connections"][0]["id"], a["id"]);
    assert_eq!(listed["connections"][0]["name"], "C");
    let copy = s.run("connection.duplicate", &json!({"id":"C"})).unwrap();
    assert_eq!(copy["name"], "C (2)");
    s.run("connection.remove", &json!({"id":copy["id"]})).unwrap();
    assert!(s.connections.find(copy["id"].as_str().unwrap()).is_none());
    assert!(s.run("connection.edit", &json!({"id":"C","kind":"wfs"})).is_err());
    assert!(s.run("connection.edit", &json!({"id":"C","name":"b"})).is_err());
    assert!(s.run("connection.new", &json!({"kind":"s3","options":{"region":[1]}})).is_err());
    #[cfg(not(target_arch = "wasm32"))]
    {
        let db = s
            .run(
                "connection.new",
                &json!({"kind":"postgres","address":"postgres:host=127.0.0.1 port=9 dbname=connections_commands user=u"}),
            )
            .unwrap();
        s.run("connection.login", &json!({"id":db["id"],"password":"pw"})).unwrap();
        let list = s.run("connection.list", &json!({"kind":"postgres"})).unwrap();
        assert_eq!(list["connections"][0]["loggedIn"], true);
        assert!(!s.connections.to_json().contains("pw"));
        let copy = s.run("connection.duplicate", &json!({"id":db["id"]})).unwrap();
        assert_eq!(copy["loggedIn"], false, "a duplicate must not inherit another saved ID's session login");
        let edited = s
            .run("connection.edit", &json!({"id":db["id"],"address":"postgres:host=127.0.0.1 port=9 dbname=connections_other user=u"}))
            .unwrap();
        assert_eq!(edited["loggedIn"], false, "a different endpoint must not inherit the old password");
        s.run("connection.remove", &json!({"id":db["id"]})).unwrap();
        let list = s.run("connection.list", &json!({"kind":"postgres"})).unwrap();
        assert_eq!(list["connections"][0]["id"], copy["id"]);
        assert_eq!(list["connections"][0]["loggedIn"], false);
    }
    s.run("connection.new", &json!({"kind":"s3","name":"conn-test-s3","options":{"credentials":"keys","buckets":"b11"}})).unwrap();
    // A saved connection that uses keys reads them from the credential store (this session has none).
    assert!(s.run("connection.test", &json!({"id":"conn-test-s3"})).unwrap_err().contains("Saved S3 keys are unavailable"));
    s.run("connection.login", &json!({"id":"conn-test-s3","accessKeyId":"AKIDTEST","secretAccessKey":"very-secret-key"})).unwrap();
    assert!(s3::connection("conn-test-s3").is_some());
    assert!(!s.connections.to_json().contains("very-secret"));
    s.run("connection.edit", &json!({"id":"conn-test-s3","address":"https://other.example"})).unwrap();
    assert!(s3::connection("conn-test-s3").is_none());
    s.run("connection.new", &json!({"kind":"wms","name":"Closed","address":"http://127.0.0.1:9/wms"})).unwrap();
    assert!(s.run("connection.test", &json!({"id":"Closed"})).unwrap_err().contains("127.0.0.1:9"));
    // A service without a login method logs in to nothing: it is only chosen for its address.
    assert_eq!(s.run("connection.login", &json!({"id":"Closed"})).unwrap()["loggedIn"], false);
    assert!(s.run("connection.login", &json!({"id":"Closed","apiKey":"k"})).unwrap_err().contains("no login method"));
    s.run("connection.edit", &json!({"id":"Closed","kind":" wms "})).unwrap();
    let default = s.run("connection.new", &json!({"kind":"wms","address":"https://a.example/wms"})).unwrap();
    let renamed = s.run("connection.edit", &json!({"id":"B","name":""})).unwrap();
    assert_eq!(renamed["name"], "wms (2)");
    assert_ne!(default["id"], renamed["id"]);
    assert!(crate::sources::holds_secret(&json!({"id":"x","password":"p"})));
    for id in [
        "connection.new",
        "connection.edit",
        "connection.duplicate",
        "connection.remove",
        "connection.login",
        "connection.forgetPassword",
        "connection.forgetLogin",
        "connection.test",
        "connection.browse",
    ] {
        assert!(crate::cmd::plugins::user_only(id), "{id}");
    }
    assert!(!crate::cmd::plugins::user_only("connection.list"));
    assert!(!s.dirty() && !s.can_undo());
}

#[test]
fn connections_loaded_names_route_login_and_remove_to_the_right_endpoint() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::connections_loaded_names_route_login_and_remove_to_the_right_endpoint") {
        return;
    }
    use crate::render::rustgis_tiles::s3;
    let mut s = Session::new(Project::default());
    s.connections = crate::connections::Connections::from_json(&json!({"connections":[
        {"id":"c1","kind":"s3","name":"connections-alias-target","options":{"credentials":"keys"}},
        {"id":"connections-alias-target","kind":"postgres","name":"Database","address":"postgres:host=127.0.0.1 port=9 dbname=connections_alias user=u"}
    ]}).to_string());
    let name = s.connections.find("c1").unwrap().name.clone();
    assert_eq!(name, "connections-alias-target (2)");
    let logged_in = s.run("connection.login", &json!({"id":name,"accessKeyId":"AKIDTEST","secretAccessKey":"alias-test-secret"})).unwrap();
    assert_eq!(logged_in["id"], "c1");
    assert!(s3::connection(&name).is_some());
    let removed = s.run("connection.remove", &json!({"id":name})).unwrap();
    assert_eq!(removed["removed"], "c1");
    assert!(s3::connection(&name).is_none());
    assert_eq!(s.connections.find("connections-alias-target").unwrap().name, "Database");
}

#[test]
fn connections_s3_rename_cannot_inherit_a_destination_session() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::connections_s3_rename_cannot_inherit_a_destination_session") {
        return;
    }
    use crate::render::rustgis_tiles::s3;
    let mut s = Session::new(Project::default());
    let (old, destination, occupied) = ("rename-test-old", "rename-test-destination", "rename-test-occupied");
    let saved = s
        .run(
            "connection.new",
            &json!({
                "kind":"s3","name":old,"address":"https://saved.example","options":{"credentials":"keys"}
            }),
        )
        .unwrap();
    s.run("connection.login", &json!({"id":old,"accessKeyId":"SAVEDKEY","secretAccessKey":"saved-test-secret"})).unwrap();
    s.run(
        "s3.connect",
        &json!({
            "name":destination,"endpoint":"https://runtime.example","accessKeyId":"RUNTIMEKEY","secretAccessKey":"runtime-test-secret"
        }),
    )
    .unwrap();
    s.run("connection.new", &json!({"kind":"s3","name":occupied})).unwrap();
    assert!(s.run("connection.edit", &json!({"id":old,"name":occupied})).is_err());
    assert!(s3::connection(old).is_some(), "a rejected edit must preserve the original login");
    assert!(s3::connection(destination).is_some(), "a rejected edit must not disconnect another session");
    let grouped = s.run("connection.edit", &json!({"id":old,"group":"Work"})).unwrap();
    assert_eq!(grouped["loggedIn"], true, "a group-only edit must preserve the login");
    let renamed = s.run("connection.edit", &json!({"id":old,"name":destination})).unwrap();
    assert_eq!(renamed["id"], saved["id"]);
    assert_eq!(renamed["address"], "https://saved.example");
    assert_eq!(renamed["loggedIn"], false);
    assert!(s3::connection(old).is_none());
    assert!(s3::connection(destination).is_none());
    assert!(s.run("connection.test", &json!({"id":destination})).unwrap_err().contains("Saved S3 keys are unavailable"));
    s.run("connection.login", &json!({"id":destination,"accessKeyId":"NEWKEY","secretAccessKey":"new-test-secret"})).unwrap();
    assert_eq!(s3::connection(destination).unwrap().endpoint.as_deref(), Some("https://saved.example"));
    s.run("connection.remove", &json!({"id":destination})).unwrap();
}

#[test]
fn connection_test_expands_xyz_templates() {
    let mut s = Session::new(Project::default());
    for (kind, address, expected, zoom) in [
        ("service", "https://tiles.example/vt/lyrs=s&x={x}&y={y}&z={z}", "https://tiles.example/vt/lyrs=s&x=0&y=0&z=0", 0),
        ("wmts", "https://tiles.example/{z}/{x}/{y}.png", "https://tiles.example/0/0/0.png", 0),
        ("ogcapi", "https://tiles.example/tile.png?z={z}&x={x}&y={y}", "https://tiles.example/tile.png?z=0&x=0&y=0", 0),
        ("service", "https://{s}.tiles.example/{zoom}/{x}/{-y}.png", "https://a.tiles.example/0/0/0.png", 0),
        ("service", "https://tiles.example/{q}.jpg", "https://tiles.example/0.jpg", 1),
        ("service", "https://tiles.example/tile.jpg?tile={quadkey}", "https://tiles.example/tile.jpg?tile=0", 1),
    ] {
        let result = s.run("connection.test", &json!({"kind":kind,"address":address,"probe":true})).unwrap();
        assert_eq!(result["fetch"], expected, "{kind}");
        assert_eq!(result["tile"]["zoom"], zoom);
    }
    let ordinary = json!({"kind":"ogcapi","address":"https://tiles.example/collections#{z}/{x}/{y}","probe":true});
    assert_eq!(s.run("connection.test", &ordinary).unwrap()["fetch"], "https://tiles.example/collections?f=json");
}

#[test]
fn connection_xyz_default_name_and_path_key_notice() {
    let mut s = Session::new(Project::default());
    let mark = s.notice_mark();
    let url = "https://tiles.example/{z}/{x}/{y}.png";
    let added = s.run("connection.new", &json!({"kind":"service","address":url})).unwrap();
    assert_eq!(added["name"], "tiles.example");
    let subdomains = "https://{s}.basemaps.example/{z}/{x}/{y}.png";
    let added = s.run("connection.new", &json!({"kind":"service","address":subdomains})).unwrap();
    assert_eq!(added["name"], "basemaps.example");
    assert_eq!(added["address"], subdomains);
    assert!(s.notices_since(mark).is_empty());
    let with_key = "https://tiles.example/services;key=fixture/tiles/{z}/{x}/{y}.png";
    let added = s.run("connection.new", &json!({"kind":"service","address":with_key,"name":"Relief"})).unwrap();
    assert_eq!(added["name"], "Relief");
    assert_eq!(added["address"], with_key);
    let notices = s.notices_since(mark);
    assert!(notices.iter().any(|n| n.text.contains("URL path is saved as typed")));
    assert!(notices.iter().all(|n| !n.text.contains("fixture")));
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn connection_test_fetches_one_xyz_tile_with_the_selected_login() {
    use std::io::{BufRead, BufReader, Write};
    use std::net::TcpListener;
    use std::time::{Duration, Instant};

    let png = tiny_skia::Pixmap::new(1, 1).unwrap().encode_png().unwrap();
    for (status, body, expected) in [
        ("200 OK", png.as_slice(), Ok("received")),
        ("204 No Content", &[][..], Ok("missing")),
        ("404 Not Found", &[][..], Ok("missing")),
        ("401 Unauthorized", &[][..], Err("http status: 401")),
        ("200 OK", b"<html>Login required</html>", Err("not a usable tile")),
    ] {
        let listener = TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let port = listener.local_addr().unwrap().port();
        let body = body.to_vec();
        let server = std::thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(5);
            let (stream, _) = loop {
                match listener.accept() {
                    Ok(pair) => break pair,
                    Err(e) if e.kind() == std::io::ErrorKind::WouldBlock && Instant::now() < deadline => {
                        std::thread::sleep(Duration::from_millis(2)); // test-wait: pace accepts until the fixture deadline
                    }
                    Err(e) => panic!("sample request did not reach the fixture: {e}"),
                }
            };
            stream.set_nonblocking(false).unwrap();
            stream.set_read_timeout(Some(Duration::from_secs(5))).unwrap();
            let mut reader = BufReader::new(stream);
            let mut request = String::new();
            reader.read_line(&mut request).unwrap();
            let mut line = String::new();
            while reader.read_line(&mut line).unwrap() != 0 && line != "\r\n" {
                line.clear();
            }
            let mut stream = reader.into_inner();
            write!(stream, "HTTP/1.1 {status}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n", body.len()).unwrap();
            stream.write_all(&body).unwrap();
            request
        });
        let mut s = Session::new(Project::default());
        let url = format!("http://127.0.0.1:{port}/services;key=xyz-path-fixture/{{z}}/{{x}}/{{y}}.png");
        let c = s.run("connection.new", &json!({"kind":"service","address":url,"auth":"query","keyName":"rg_xyz_key"})).unwrap();
        let params = json!({"id":c["id"],"apiKey":"sample+key","allowInsecure":true});
        let mark = s.notice_mark();
        let result = s.run("connection.test", &params);
        match expected {
            Ok(expected) => assert_eq!(result.unwrap()["result"], json!({"kind":"xyz","tile":[0,0,0],"status":expected})),
            Err(expected) => {
                let error = result.unwrap_err();
                assert!(error.contains(expected) && !error.contains("sample") && !error.contains("xyz-path-fixture"), "{error}");
                let history = s.diagnostics.report(rustgis_data::diagnostics::Filter::All);
                assert!(history.contains(expected), "{history}");
                for key in ["xyz-path-fixture", "sample+key", "sample%2Bkey"] {
                    assert!(!history.contains(key), "{history}");
                }
            }
        }
        for notice in s.notices_since(mark) {
            for key in ["xyz-path-fixture", "sample+key", "sample%2Bkey"] {
                assert!(!notice.text.contains(key), "{notice:?}");
            }
        }
        assert_eq!(server.join().unwrap(), "GET /services;key=xyz-path-fixture/0/0/0.png?rg_xyz_key=sample%2Bkey HTTP/1.1\r\n");
    }
}

#[test]
fn connection_xyz_test_refuses_a_text_answer_and_an_unexpanded_placeholder() {
    use crate::connections::tile_test::{TEXT_ANSWER, UNEXPANDED};
    let mut s = Session::new(Project::default());
    let answer = json!({"kind":"service","address":"https://tiles.example/{z}/{x}/{y}.png","answer":"<html></html>"});
    let text = s.run("connection.test", &answer).unwrap_err();
    assert_eq!(text, TEXT_ANSWER);
    let unknown = json!({"kind":"service","address":"https://tiles.example/{z}/{x}/{y}/{foo}.png","probe":true});
    let unexpanded = s.run("connection.test", &unknown).unwrap_err();
    assert_eq!(unexpanded, UNEXPANDED);
    // Clean input still passes: the same template without the unknown placeholder probes.
    let clean = json!({"kind":"service","address":"https://tiles.example/{z}/{x}/{y}.png","probe":true});
    assert_eq!(s.run("connection.test", &clean).unwrap()["tile"]["zoom"], 0);
}

#[test]
fn connection_test_probes_and_answers() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::connection_test_probes_and_answers") {
        return;
    }
    use crate::render::rustgis_tiles::s3;
    let mut s = Session::new(Project::default());
    let mut wms = json!({"kind":"wms","address":"https://a.example/wms","probe":true});
    let v = s.run("connection.test", &wms).unwrap();
    let fetch = v["fetch"].as_str().unwrap();
    assert!(fetch.starts_with("https://a.example/wms") && fetch.contains("REQUEST=GetCapabilities"));
    assert!(v.get("connection").is_none());
    assert!(s.connections.connections.is_empty());
    wms.as_object_mut().unwrap().remove("probe");
    wms["answer"] = json!(
        r#"<WMS_Capabilities version="1.3.0" xmlns="http://www.opengis.net/wms" xmlns:xlink="http://www.w3.org/1999/xlink"><Service><Title>Local</Title></Service><Capability><Request><GetMap><Format>image/png</Format><DCPType><HTTP><Get><OnlineResource xlink:href="https://a.example/wms?"/></Get></HTTP></DCPType></GetMap></Request><Layer><CRS>EPSG:3857</CRS><Layer><Name>a</Name><Title>A</Title></Layer></Layer></Capability></WMS_Capabilities>"#
    );
    assert_eq!(s.run("connection.test", &wms).unwrap()["result"]["layers"][0]["name"], "a");
    assert_eq!(
        s.run("connection.test", &json!({"kind":"stac","address":"https://s.example/v1","probe":true})).unwrap()["fetch"],
        "https://s.example/v1/collections"
    );
    assert_eq!(
        s.run(
            "connection.test",
            &json!({"kind":"stac","address":"https://s.example/v1","answer":r#"{"collections":[{"id":"c1","title":"C"}]}"#})
        )
        .unwrap()["result"]["count"],
        1
    );
    let mut p = json!({"kind":"s3","name":"probe-s3","options":{"credentials":"none","buckets":"bkt1"},"probe":true});
    assert!(s.run("connection.test", &p).unwrap()["fetch"].as_str().unwrap().contains("bkt1"));
    p.as_object_mut().unwrap().remove("probe");
    p["answer"] = json!("<ListBucketResult><Contents><Key>a.tif</Key><Size>1</Size></Contents></ListBucketResult>");
    assert_eq!(s.run("connection.test", &p).unwrap()["result"]["count"], 1);
    p["options"].as_object_mut().unwrap().remove("buckets");
    p["probe"] = json!(true);
    assert!(s.run("connection.test", &p).unwrap_err().contains("name a bucket"));
    s3::disconnect("probe-s3");
    #[cfg(not(target_arch = "wasm32"))]
    assert!(
        s.run("connection.test", &json!({"kind":"postgres","address":"postgres:host=127.0.0.1 port=9 dbname=x user=u","probe":true}))
            .unwrap()["fetch"]
            .is_null()
    );
    assert!(s.run("connection.test", &json!({"probe":true})).unwrap_err().contains("id, or kind and address"));
    assert!(s.connections.connections.is_empty());
}

/// Browsing a saved connection lists what each kind offers, a level at a time, with the command
/// that adds each dataset; offline, with the answers supplied. A node that isn't the
/// connection's is refused, and nothing browsed is saved or undoable.
#[test]
fn connection_browse_levels_and_adds() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::connection_browse_levels_and_adds") {
        return;
    }
    use crate::render::rustgis_tiles::s3;
    let mut s = Session::new(Project::default());
    let new = |s: &mut Session, p: Value| s.run("connection.new", &p).unwrap();
    let wms_caps = r#"<WMS_Capabilities version="1.3.0" xmlns="http://www.opengis.net/wms" xmlns:xlink="http://www.w3.org/1999/xlink"><Service><Title>Local</Title></Service><Capability><Request><GetMap><Format>image/png</Format><DCPType><HTTP><Get><OnlineResource xlink:href="https://a.example/wms?"/></Get></HTTP></DCPType></GetMap></Request><Layer><CRS>EPSG:3857</CRS><Layer><Name>a</Name><Title>A</Title></Layer><Layer><Name>b</Name><Title>B</Title></Layer></Layer></Capability></WMS_Capabilities>"#;

    // WMS: the address read, its layers, and the add that adds one.
    new(&mut s, json!({"kind": "wms", "address": "https://a.example/wms", "name": "W"}));
    let v = s.run("connection.browse", &json!({"id": "W", "probe": true})).unwrap();
    assert!(v["fetch"].as_str().is_some_and(|f| f.contains("REQUEST=GetCapabilities")), "{v}");
    let v = s.run("connection.browse", &json!({"id": "W", "answer": wms_caps})).unwrap();
    assert_eq!(v["service"], json!({"url": "https://a.example/wms", "type": "wms"}));
    let first = v["children"][0].clone();
    assert_eq!(first["what"], "map");
    assert_eq!(first["name"], "A");
    assert_eq!(first["add"]["command"], "service.add");
    assert_eq!(first["add"]["params"]["url"], "https://a.example/wms");
    assert_eq!(first["add"]["params"]["type"], "wms");
    assert_eq!(first["add"]["params"]["layer"], "a");
    assert!(first["add"]["params"].get("source_url").is_some());
    assert_eq!(v["children"].as_array().unwrap().len(), 2);
    let before = s.map().tiles.len();
    let mut add = first["add"]["params"].clone();
    add["text"] = json!(wms_caps);
    s.run("service.add", &add).unwrap();
    assert_eq!(s.map().tiles.len(), before + 1);
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.map().tiles.len(), before);

    // ArcGIS: a directory's folder is a node of its own address.
    new(&mut s, json!({"kind": "arcgis", "address": "https://x.example.org/arcgis/rest/services", "name": "Arc"}));
    let dir = r#"{"currentVersion": 11, "folders": ["Hydro"], "services": [{"name": "Topo", "type": "MapServer"}]}"#;
    let v = s.run("connection.browse", &json!({"id": "Arc", "answer": dir})).unwrap();
    let folder = "service:arcgis:https://x.example.org/arcgis/rest/services/Hydro";
    let child = v["children"].as_array().unwrap().iter().find(|c| c["node"] == folder).unwrap_or_else(|| panic!("{v}"));
    assert_eq!(child["what"], "folder");
    assert_eq!(child["name"], "Hydro");
    let v = s.run("connection.browse", &json!({"id": "Arc", "node": folder, "probe": true})).unwrap();
    assert!(v["fetch"].as_str().is_some_and(|f| f.starts_with("https://x.example.org/arcgis/rest/services/Hydro")), "{v}");

    // CSW: a record, the service it links to as a node, and more records than listed.
    new(&mut s, json!({"kind": "csw", "address": "https://cat.example.org/csw", "name": "Cat"}));
    let records = r#"<csw:GetRecordsResponse xmlns:csw="http://www.opengis.net/cat/csw/2.0.2" xmlns:dc="http://purl.org/dc/elements/1.1/">
        <csw:SearchResults numberOfRecordsMatched="3" nextRecord="2"><csw:Record><dc:title>Forests</dc:title>
          <dc:URI protocol="OGC:WMS">https://geo.example.org/wms</dc:URI><dc:URI protocol="OGC:WFS">http://192.168.1.2/wfs</dc:URI>
        </csw:Record></csw:SearchResults></csw:GetRecordsResponse>"#;
    let v = s.run("connection.browse", &json!({"id": "Cat", "answer": records})).unwrap();
    assert_eq!(v["children"].as_array().unwrap().len(), 1, "{v}");
    assert_eq!(v["children"][0]["what"], "record");
    assert_eq!(v["children"][0]["children"][0]["node"], "service:wms:https://geo.example.org/wms");
    assert_eq!((v["matched"].as_u64(), v["truncated"].as_bool()), (Some(3), Some(true)));
    assert!(v.get("next").is_none());

    // STAC: collections, a collection's search, and an item's asset with the add of it.
    new(&mut s, json!({"kind": "stac", "address": "https://s.example/v1", "name": "Stac"}));
    let v = s.run("connection.browse", &json!({"id": "Stac", "probe": true})).unwrap();
    assert_eq!(v["fetch"], "https://s.example/v1/collections");
    let v = s.run("connection.browse", &json!({"id": "Stac", "answer": r#"{"collections":[{"id":"c1","title":"C"}]}"#})).unwrap();
    assert_eq!(v["children"][0]["node"], "collection:c1");
    assert_eq!(v["children"][0]["options"], true);
    let v = s.run("connection.browse", &json!({"id": "Stac", "node": "collection:c1", "probe": true})).unwrap();
    let fetch = v["fetch"].as_str().unwrap();
    assert!(fetch.contains("/search?") && fetch.contains("collections=c1") && fetch.contains("limit=20"), "{fetch}");
    let self_link = "https://s.example/v1/collections/c1/items/i1";
    let items = json!({"type": "FeatureCollection", "numberMatched": 1, "features": [{
        "type": "Feature", "id": "i1", "collection": "c1", "bbox": [0, 0, 1, 1], "geometry": null,
        "properties": {"datetime": "2024-01-01T00:00:00Z"},
        "assets": {"visual": {"href": "https://s.example/a.tif", "type": "image/tiff; application=geotiff"}},
        "links": [{"rel": "self", "href": self_link}]}]});
    let v = s.run("connection.browse", &json!({"id": "Stac", "node": "collection:c1", "answer": items.to_string()})).unwrap();
    assert_eq!(v["children"][0]["what"], "item");
    assert_eq!(
        v["children"][0]["children"][0]["add"],
        json!({"command": "stac.addAsset", "params": {"url": self_link, "asset": "visual", "name": "i1 visual", "connection": v["connection"]}})
    );
    assert!(v.get("truncated").is_none());

    // A static STAC catalog: catalogs and collections, then a collection's items, each opened
    // for its assets.
    new(&mut s, json!({"kind": "stac", "address": "https://s.example/static/catalog.json", "name": "Static"}));
    let root = json!({"type": "Catalog", "id": "r", "links": [{"rel": "child", "href": "./c1/collection.json", "title": "C1"}]});
    let v = s.run("connection.browse", &json!({"id": "Static", "answer": root.to_string()})).unwrap();
    assert_eq!(v["children"][0]["node"], "catalog:https://s.example/static/c1/collection.json");
    let collection = json!({"type": "Collection", "id": "c1", "links": [
        {"rel": "item", "href": "./i1/i1.json", "title": "Scene 1"}, {"rel": "child", "href": "./sub/catalog.json", "title": "Sub"}]});
    let node = "catalog:https://s.example/static/c1/collection.json";
    let v = s.run("connection.browse", &json!({"id": "Static", "node": node, "answer": collection.to_string()})).unwrap();
    let kinds: Vec<_> =
        v["children"].as_array().unwrap().iter().map(|c| (c["what"].as_str().unwrap(), c["node"].as_str().unwrap())).collect();
    assert_eq!(
        kinds,
        [("catalog", "catalog:https://s.example/static/c1/sub/catalog.json"), ("item", "item:https://s.example/static/c1/i1/i1.json")]
    );
    let item_node = "item:https://s.example/static/c1/i1/i1.json";
    let v = s.run("connection.browse", &json!({"id": "Static", "node": item_node, "probe": true})).unwrap();
    assert_eq!(v["fetch"], "https://s.example/static/c1/i1/i1.json");
    let item = json!({"type": "Feature", "id": "i1", "collection": "c1", "bbox": [0, 0, 1, 1], "geometry": null,
        "properties": {"datetime": "2024-01-01T00:00:00Z"},
        "assets": {"visual": {"href": "https://s.example/static/a.tif", "type": "image/tiff; application=geotiff"}},
        "links": [{"rel": "self", "href": "https://s.example/static/c1/i1/i1.json"}]});
    let v = s.run("connection.browse", &json!({"id": "Static", "node": item_node, "answer": item.to_string()})).unwrap();
    assert_eq!(
        v["children"][0]["add"],
        json!({"command": "stac.addAsset", "params": {"url": "https://s.example/static/c1/i1/i1.json", "asset": "visual", "name": "i1 visual", "connection": v["connection"]}})
    );
    // An asset's key names its item, so the same file under two items is two rows.
    assert_eq!(v["children"][0]["key"], "https://s.example/static/c1/i1/i1.json#visual");
    // A relative asset address is resolved against the item's own file.
    let relative = item.to_string().replace(r#""assets":{"#, r#""assets":{"data":{"href":"./data/b.tif","type":"image/tiff"},"#);
    let v = s.run("connection.browse", &json!({"id": "Static", "node": item_node, "answer": relative})).unwrap();
    let hrefs: Vec<&str> = v["children"].as_array().unwrap().iter().filter_map(|c| c["href"].as_str()).collect();
    assert!(hrefs.contains(&"https://s.example/static/c1/i1/data/b.tif"), "{hrefs:?}");
    // An item node belongs to a STAC connection, and is judged as its documents are.
    assert!(s.run("connection.browse", &json!({"id": "W", "node": item_node})).is_err());
    assert!(s.run("connection.browse", &json!({"id": "Static", "node": "item:http://127.0.0.1:9/i.json"})).is_err());
    // S3: buckets from the connection's options need no fetch; a bucket's level is read.
    new(&mut s, json!({"kind": "s3", "name": "BrowseB", "options": {"credentials": "none", "buckets": "bkt1"}}));
    let v = s.run("connection.browse", &json!({"id": "BrowseB", "probe": true})).unwrap();
    assert!(v["fetch"].is_null(), "{v}");
    let v = s.run("connection.browse", &json!({"id": "BrowseB"})).unwrap();
    assert_eq!(v["children"][0]["node"], "s3:bkt1/");
    let v = s.run("connection.browse", &json!({"id": "BrowseB", "node": "s3:bkt1/", "probe": true})).unwrap();
    assert!(v["fetch"].as_str().is_some_and(|f| f.contains("bkt1")), "{v}");
    let listing = "<ListBucketResult><CommonPrefixes><Prefix>p/</Prefix></CommonPrefixes><Contents><Key>p.tif</Key><Size>5</Size></Contents><Contents><Key>q/</Key><Size>0</Size></Contents></ListBucketResult>";
    let v = s.run("connection.browse", &json!({"id": "BrowseB", "node": "s3:bkt1/", "answer": listing})).unwrap();
    assert_eq!(v["children"][0]["node"], "s3:bkt1/p/");
    assert_eq!(v["children"][0]["name"], "p/");
    // Through a saved connection's login, a file's address names it: only that login reads it.
    let added = v["children"][1]["add"]["params"]["url"].as_str().unwrap();
    let bound = rustgis_data::s3_address::parse(added).unwrap().unwrap();
    let saved_id = &s.connections.find("BrowseB").unwrap().id;
    assert_eq!((bound.url, bound.endpoint, Some(bound.binding)), ("s3://bkt1/p.tif", "", s.s3_binding(saved_id)));
    assert_eq!(v["children"][1]["key"], "s3://bkt1/p.tif");
    assert_eq!(v["children"].as_array().unwrap().len(), 2, "{v}");
    s3::disconnect("BrowseB");

    // Nodes that aren't the connection's, and ones that are hostile.
    let long = "x".repeat(5000);
    for (id, node) in [
        ("W", "collection:x"),
        ("BrowseB", "s3:BAD_/"),
        ("W", long.as_str()),
        ("W", "service:ftp:x"),
        ("W", "service:wms:http://127.0.0.1:9/wms"),
        ("Stac", "catalog:http://127.0.0.1:9/c.json"),
        ("Stac", "s3:bkt1/"),
        ("W", "nope"),
        ("W", "a\u{7}b"),
    ] {
        let e = s.run("connection.browse", &json!({"id": id, "node": node})).unwrap_err();
        assert!(!e.is_empty());
    }
    assert!(s.run("connection.browse", &json!({"id": "missing"})).unwrap_err().contains("no connection"));
    #[cfg(not(target_arch = "wasm32"))]
    {
        new(&mut s, json!({"kind": "postgres", "address": "postgres:host=127.0.0.1 port=9 dbname=x user=u", "name": "Pg"}));
        assert!(!s.run("connection.browse", &json!({"id": "Pg"})).unwrap_err().is_empty());
    }
    // A catalogue's download link too long to be one (the parser keeps addresses to 2000 bytes) is not listed.
    let long_link = format!("https://files.example.org/{}.tif", "a".repeat(5000));
    let records = format!(
        r#"<csw:GetRecordsResponse xmlns:csw="http://www.opengis.net/cat/csw/2.0.2" xmlns:dc="http://purl.org/dc/elements/1.1/"><csw:SearchResults numberOfRecordsMatched="1"><csw:Record><dc:title>Files</dc:title>
          <dc:URI protocol="WWW:DOWNLOAD">https://files.example.org/a.tif</dc:URI><dc:URI protocol="WWW:DOWNLOAD">{long_link}</dc:URI></csw:Record></csw:SearchResults></csw:GetRecordsResponse>"#
    );
    let v = s.run("connection.browse", &json!({"id": "Cat", "answer": records})).unwrap();
    let links = v["children"][0]["children"].as_array().unwrap();
    assert_eq!(links.len(), 1, "{v}");
    assert_eq!(links[0]["add"]["params"]["url"], "https://files.example.org/a.tif");
    assert!(v.get("truncated").is_none(), "{v}");
    // An answer larger than a service document may be is refused before it is parsed.
    let huge = "x".repeat(65 << 20);
    assert!(s.run("connection.browse", &json!({"id": "W", "answer": huge})).unwrap_err().contains("too large"));
    assert!(
        s.run("connection.browse", &json!({"id": "W", "answer": "<x/>", "documents": [{"url": "https://a.example/x", "text": huge}]}))
            .unwrap_err()
            .contains("too large")
    );
    // An OGC API's feature collections are imported together: listed, with options, not added alone.
    new(&mut s, json!({"kind": "ogcapi", "address": "https://o.example/collections", "name": "Ogc"}));
    let collections = r#"{"collections":[{"id":"lakes","title":"Lakes","links":[{"rel":"items","type":"application/geo+json","href":"https://o.example/collections/lakes/items"}]}]}"#;
    let v = s.run("connection.browse", &json!({"id": "Ogc", "answer": collections})).unwrap();
    assert_eq!((v["children"][0]["what"].as_str(), v["children"][0]["options"].as_bool()), (Some("features"), Some(true)), "{v}");
    assert!(v["children"][0].get("add").is_none(), "{v}");
    let saved = s.connections.connections.len();
    assert!(saved >= 5);
    s.run("connection.browse", &json!({"id": "W", "answer": wms_caps})).unwrap();
    assert_eq!(s.connections.connections.len(), saved);
    assert!(!s.can_undo());
}

/// A kept field that only holds a secret once a source's details change is left out then, and
/// said then, not only at start (the start-up notice has already been shown).
#[test]
fn a_secret_left_out_when_a_source_changes_is_said() {
    let mut s = Session::new(Project::default());
    s.sources = crate::sources::Sources::from_json(r#"{"saved":[{"kind":"file","name":"A","address":"/a.csv","key":"abc"}]}"#);
    // Kept at start as a setting this version doesn't know: nothing beside it makes it a secret.
    assert!(!s.sources.unread().iter().any(|t| t.contains("password")), "{:?}", s.sources.unread());
    let mark = s.notices_given();
    s.run("sources.save", &json!({"kind": "file", "name": "A", "address": "/a.csv"})).unwrap();
    assert!(s.notices_since(mark).is_empty(), "{:?}", s.notices_since(mark));
    s.run("sources.save", &json!({"kind": "file", "name": "A", "address": "/a.csv", "extra": {"endpoint": "https://api.example"}}))
        .unwrap();
    assert!(
        s.notices_since(mark).iter().any(|n| n.text.starts_with("1 value in the saved data sources holds a password")),
        "{:?}",
        s.notices_since(mark)
    );
    assert!(!s.sources.to_json().contains("abc"));
}

fn rustgis_engine_sources_roundtrip(text: &str) -> crate::sources::Sources {
    crate::sources::Sources::from_json(text)
}

/// A DXF drawing through the commands: read natively (not through GDAL) by path and upload, its
/// own layers listed and picked with "layer", and its coordinates converted with "crs".
#[test]
fn dxf_drawings_by_path_and_upload() {
    use base64::Engine;
    let pairs: &[(i32, &str)] = &[
        (0, "SECTION"),
        (2, "ENTITIES"),
        (0, "LINE"),
        (8, "Roads"),
        (10, "500000"),
        (20, "4649776"),
        (11, "500100"),
        (21, "4649776"),
        (0, "POINT"),
        (8, "Wells"),
        (10, "500050"),
        (20, "4649800"),
        (0, "TEXT"),
        (8, "Wells"),
        (10, "500050"),
        (20, "4649800"),
        (1, "W1"),
        (0, "ENDSEC"),
        (0, "EOF"),
    ];
    let text: String = pairs.iter().map(|(c, v)| format!("{c:>3}\n{v}\n")).collect();
    assert!(!rustgis_data::source::gdal::is_gdal_name("site.dxf"));
    let dir = std::env::temp_dir().join(format!("rustgis-dxf-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("site.dxf");
    std::fs::write(&path, &text).unwrap();
    let path = path.display().to_string();
    let mut s = Session::new(Project::default());
    let listed = s.run("info.fileLayers", &json!({"path": path})).unwrap();
    assert_eq!(listed, json!({"count": 2, "layers": ["Roads", "Wells"]}));
    // Converted from UTM 33N: the line runs east from 15° E, 42° N.
    let r = s.run("layer.addData", &json!({"path": path, "crs": "EPSG:32633"})).unwrap();
    let mut names: Vec<String> = s.map().layers.iter().map(|l| l.name.clone()).collect();
    names.sort();
    assert_eq!(names, ["site lines", "site points"], "{r}");
    let e = s.map().layer_by_name("site lines").unwrap().extent();
    assert!((e.min_x - 15.0).abs() < 1e-6 && (e.min_y - 42.0).abs() < 0.01, "{e:?}");
    // The desktop read-ahead consumes the same options and lands the parsed layers.
    let mut ahead_session = Session::new(Project::default());
    let params = json!({"path": path, "crs": "EPSG:32633", "layer": "roads", "blocks": false});
    let ahead = crate::cmd::reads::read_ahead(&mut ahead_session, "layer.addData", &params).unwrap();
    assert!(ahead.reads());
    let read = ahead.run(&rustgis_analysis::control::Control::new()).unwrap();
    crate::cmd::reads::read_land(&mut ahead_session, read).unwrap();
    assert_eq!(ahead_session.map().layers.len(), 1);
    assert_eq!(ahead_session.map().layers[0].extent(), e);
    // One DXF layer, by its name.
    let mut t = Session::new(Project::default());
    t.run("layer.addData", &json!({"path": path, "layer": "wells", "crs": "EPSG:32633"})).unwrap();
    let only: Vec<String> = t.map().layers.iter().map(|l| l.name.clone()).collect();
    assert_eq!(only, ["site points"]);
    assert_eq!(t.map().layers[0].dataset.features.len(), 2);
    assert!(t.run("layer.addData", &json!({"path": path, "layer": "nope"})).unwrap_err().contains("nothing drawn on layer 'nope'"));
    // Without "crs" the coordinates are kept, and the user is told.
    let mut u = Session::new(Project::default());
    u.run("layer.addDataBytes", &json!({"fileName": "upload.dxf", "data": base64::engine::general_purpose::STANDARD.encode(&text)}))
        .unwrap();
    assert_eq!(u.map().layers.len(), 2);
    assert!(u.notices.iter().any(|n| n.text.contains("doesn't say its coordinate system")), "{:?}", u.notices);
    assert!(u.run("layer.addDataBytes", &json!({"fileName": "bad.dxf", "data": "AAAA"})).is_err());
    // Blocks (图块) are drawn unless "blocks" says not to: what is left out is counted.
    let blocked = "  0\nSECTION\n  2\nBLOCKS\n  0\nBLOCK\n  2\nB\n  0\nPOINT\n 10\n1\n 20\n1\n  0\nENDBLK\n  0\nENDSEC\n  0\nSECTION\n  2\nENTITIES\n  0\nINSERT\n  2\nB\n 10\n5\n 20\n5\n  0\nLINE\n  8\nRoads\n 10\n0\n 20\n0\n 11\n1\n 21\n0\n  0\nENDSEC\n  0\nEOF\n";
    let mut v = Session::new(Project::default());
    v.run("layer.addDataText", &json!({"fileName": "blocks.dxf", "text": blocked})).unwrap();
    assert_eq!(v.map().layers.len(), 2, "the block's point and the line");
    let mut w = Session::new(Project::default());
    w.run("layer.addDataText", &json!({"fileName": "blocks.dxf", "text": blocked, "blocks": false})).unwrap();
    let names: Vec<String> = w.map().layers.iter().map(|l| l.name.clone()).collect();
    assert_eq!(names, ["blocks lines"], "the line only");
    assert!(w.notices.iter().any(|n| n.text.contains("1 inserted blocks")), "{:?}", w.notices);
    // The text adapter must reject oversized drawings before parsing their records.
    let oversized = " ".repeat(1 << 20);
    let error = rustgis_data::io::with_max_bytes(1 << 19, || {
        s.run("layer.addDataText", &json!({"fileName": "large.dxf", "text": oversized})).unwrap_err()
    });
    assert!(error.contains("too large"), "{error}");
    let _ = std::fs::remove_dir_all(dir);
}

/// Overture and Source Cooperative refuse what they can't read before asking anything of the
/// network (their answers are read by the catalog modules' own tests).
#[test]
fn catalog_commands_refuse_bad_parameters() {
    let mut s = Session::new(Project::default());
    for bad in [
        json!({}),
        json!({"theme": "roads"}),
        json!({"theme": "buildings", "type": "segment"}),
        json!({"theme": "buildings", "release": "../x"}),
        json!({"theme": "buildings", "bbox": [1, 2, 3]}),
        json!({"theme": "buildings", "bbox": [10, 50, 0, 40]}),
        json!({"theme": "buildings", "bbox": "everywhere"}),
    ] {
        assert!(s.run("overture.add", &bad).is_err(), "{bad}");
    }
    for bad in [
        json!({}),
        json!({"account": "giswqs"}),
        json!({"account": "../etc", "product": "p"}),
        json!({"account": "a", "product": "p", "path": "../../x/"}),
    ] {
        assert!(s.run("sourcecoop.list", &bad).is_err(), "{bad}");
    }
    assert!(s.run("sourcecoop.products", &json!({"account": "a/b"})).is_err());
    assert!(s.map().layers.is_empty() && s.map().tiles.is_empty());
}

/// Overture's files are added all or none: one that can't be read takes the ones added before it
/// out again, so trying again doesn't add them twice.
/// Runs the local catalog fixture through admission, as the real Overture handler does.
fn catalog_files(s: &mut Session, urls: &[String]) -> crate::CmdResult {
    if s.registry.get("test.catalogFiles").is_none() {
        s.registry.commands.push(
            crate::CommandSpec::new("test.catalogFiles", "Local catalog files", "Test", |s, p| {
                let urls = p["urls"].as_array().unwrap().iter().map(|url| url.as_str().unwrap().to_string()).collect::<Vec<_>>();
                crate::cmd::catalogs::add_files(s, "building", &urls)
            })
            .params(r#"{"urls": [text]}"#)
            .effects(crate::policy::Effects::NONE.with(crate::policy::Effect::Network))
            .roles(&[]),
        );
    }
    s.run("test.catalogFiles", &json!({"urls":urls}))
}

/// Overture's files are added all or none; the fixture retains their real command authority.
#[test]
fn overture_files_are_added_all_or_none() {
    use rustgis_data::{Dataset, Feature, Field, FieldType, Geometry, GeometryType, Value};
    let mut ds = Dataset::new("b", GeometryType::Point, vec![Field::new("n", FieldType::Integer)]);
    for i in 0..50u32 {
        let c = rustgis_geom::Coord::new(7.0 + 0.01 * f64::from(i), 46.0);
        ds.features.push(Feature { id: u64::from(i) + 1, geometry: Some(Geometry::Point(c)), attrs: vec![Value::Int(i64::from(i))] });
    }
    let (good, _) = serve_ranges(rustgis_data::source::fgb::write(&ds).unwrap());
    let (bad, _) = serve_ranges(b"not a flatgeobuf at all".to_vec());
    let mut s = Session::new(Project::default());
    let before = s.map().layers.len();
    let urls = vec![format!("{good}/part-0.fgb"), format!("{bad}/part-1.fgb")];
    let e = catalog_files(&mut s, &urls).unwrap_err();
    assert!(e.contains("none of the 2 files was added"), "{e}");
    assert!(e.to_ascii_lowercase().contains("flatgeobuf"), "the actual bad file was reached: {e}");
    assert_eq!(s.map().layers.len(), before, "the first file's layer was taken out again");
    // The app's way (the files found and opened already) takes Overture's own files only: any
    // other address is refused before anything is read.
    let files = json!([format!("{good}/part-0.fgb"), format!("{bad}/part-1.fgb")]);
    let e = s.run("overture.add", &json!({"theme": "buildings", "files": files})).unwrap_err();
    assert!(e.contains("not one of Overture's release files"), "{e}");
    assert_eq!(s.map().layers.len(), before);
    for bad_files in [json!([]), json!("x"), json!(["https://x.org/a.png"]), json!(vec![format!("{good}/a.fgb"); 7])] {
        assert!(s.run("overture.add", &json!({"theme": "buildings", "files": bad_files})).is_err(), "{bad_files}");
    }
    assert_eq!(s.map().layers.len(), before);
    // Both readable: both added, numbered.
    let urls = vec![format!("{good}/part-0.fgb"), format!("{good}/part-1.fgb")];
    let r = catalog_files(&mut s, &urls).unwrap();
    assert_eq!(r["files"], 2);
    let names: Vec<&str> = s.map().layers.iter().map(|l| l.name.as_str()).collect();
    assert!(names.contains(&"Overture building (1/2)") && names.contains(&"Overture building (2/2)"), "{names:?}");
}

/// A multi-file add that fails puts the map back exactly: the same layers in the same order, and
/// the same active layer.
#[test]
fn a_failed_multi_file_add_leaves_the_map_as_it_was() {
    use rustgis_data::{Dataset, Feature, Field, FieldType, Geometry, GeometryType, Value};
    let mut ds = Dataset::new("b", GeometryType::Point, vec![Field::new("n", FieldType::Integer)]);
    for i in 0..20u32 {
        let c = rustgis_geom::Coord::new(7.0 + 0.01 * f64::from(i), 46.0);
        ds.features.push(Feature { id: u64::from(i) + 1, geometry: Some(Geometry::Point(c)), attrs: vec![Value::Int(i64::from(i))] });
    }
    let (good, _) = serve_ranges(rustgis_data::source::fgb::write(&ds).unwrap());
    let (bad, _) = serve_ranges(b"not a flatgeobuf at all".to_vec());
    let mut s = world();
    // A layer other than the last added is active.
    let rivers = s.map().layer_by_name("Rivers").unwrap().id;
    s.active_layer = Some(rivers);
    let project = serde_json::to_string(&s.project).unwrap();
    let urls = vec![format!("{good}/part-0.fgb"), format!("{good}/part-1.fgb"), format!("{bad}/part-2.fgb")];
    assert!(catalog_files(&mut s, &urls).is_err());
    assert_eq!(serde_json::to_string(&s.project).unwrap(), project, "the same layers, in the same order");
    assert_eq!(s.active_layer, Some(rivers));
    // A box across the antimeridian (west past east) is an area, not an error.
    let fiji = crate::cmd::catalogs::area(&s, &json!({"bbox": [178.0, -18.0, -178.0, -17.0]})).unwrap();
    assert_eq!(fiji, [178.0, -18.0, -178.0, -17.0]);
    assert!(crate::cmd::catalogs::area(&s, &json!({"bbox": [200.0, 0.0, 10.0, 1.0]})).unwrap_err().contains("antimeridian"));
}

/// World files (#2075): a JPEG a `.jgw` and a `.prj` place opens as a placed raster, not a photo;
/// a camera JPEG with a stray world file and no `.prj` stays a photo; `"as": "scan"` ignores the
/// world file, and a scan reopened from a project stays one.
#[test]
fn a_jpeg_with_a_world_file_opens_placed_not_as_a_photo() {
    use rustgis_data::photo;
    let dir = std::env::temp_dir().join(format!("rustgis-jgw-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    let path = |f: &str| dir.join(f).display().to_string();
    image::RgbImage::from_pixel(8, 4, image::Rgb([200, 100, 50])).save(dir.join("aerial.jpg")).unwrap();
    std::fs::write(dir.join("aerial.jgw"), "0.25\n0\n0\n-0.25\n-96.875\n33.125\n").unwrap();
    std::fs::write(
        dir.join("aerial.prj"),
        r#"GEOGCS["GCS_WGS_1984",DATUM["D_WGS_1984",SPHEROID["WGS_1984",6378137.0,298.257223563]],PRIMEM["Greenwich",0.0],UNIT["Degree",0.0174532925199433]]"#,
    )
    .unwrap();
    let mut s = Session::new(Project::default());
    s.run("layer.addData", &json!({"path": path("aerial.jpg")})).unwrap();
    assert!(s.map().layer_by_name("Photos").is_none());
    let l = s.map().layer_by_name("aerial").unwrap();
    let r = l.raster.as_ref().and_then(|r| r.data.as_ref()).unwrap();
    assert!(r.georeferenced);
    let e = r.extent();
    assert!((e.min_x + 97.0).abs() < 1e-9 && (e.max_y - 33.25).abs() < 1e-9, "{e:?}");

    // A camera's photo with a stray world file and no `.prj` stays a photo, at its GPS position.
    std::fs::write(dir.join("camera.jpg"), photo::example(true, (43.4674, "N"), (11.8851, "E"))).unwrap();
    std::fs::write(dir.join("camera.wld"), "1\n0\n0\n-1\n0\n0\n").unwrap();
    s.run("layer.addData", &json!({"path": path("camera.jpg")})).unwrap();
    assert_eq!(s.map().layer_by_name("Photos").map(|l| l.dataset.features.len()), Some(1));

    // As a scan, the world file is passed over; the project reopens it as one.
    let mut t = Session::new(Project::default());
    t.run("layer.addData", &json!({"path": path("aerial.jpg"), "as": "scan", "name": "scan"})).unwrap();
    // (Laid over a placement, and georeferenced or not.)
    let scan = |t: &Session| {
        t.map()
            .layer_by_name("scan")
            .and_then(|l| l.raster.as_ref())
            .map(|r| (r.placement.is_some(), r.data.as_ref().map(|d| d.georeferenced)))
    };
    assert_eq!(scan(&t), Some((true, Some(false))));
    let text = serde_json::to_string(&t.project).unwrap();
    let mut u = Session::new(Project::default());
    u.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(scan(&u), Some((true, Some(false))));

    // A picture that opened without coordinates for want of a .prj reopens as it was added, laid
    // over the view: a .prj that turns up later doesn't move it (the notice says to add it again).
    image::GrayImage::from_pixel(4, 2, image::Luma([7])).save(dir.join("plan.png")).unwrap();
    std::fs::write(dir.join("plan.pgw"), "0.5\n0\n0\n-0.5\n10.25\n49.75\n").unwrap();
    let mut v = Session::new(Project::default());
    v.run("layer.addData", &json!({"path": path("plan.png")})).unwrap();
    let plan = |v: &Session| {
        v.map()
            .layer_by_name("plan")
            .and_then(|l| l.raster.as_ref())
            .map(|r| (r.placement.is_some(), r.data.as_ref().map(|d| d.georeferenced)))
    };
    assert_eq!(plan(&v), Some((true, Some(false))));
    assert!(v.notices.iter().any(|n| n.text.contains("add it again")), "the missing .prj is said");
    let text = serde_json::to_string(&v.project).unwrap();
    std::fs::copy(dir.join("aerial.prj"), dir.join("plan.prj")).unwrap();
    let mut w = Session::new(Project::default());
    w.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(plan(&w), Some((true, Some(false))));
    // Added now, it is placed; a project that kept it placed still opens it when the .prj is
    // gone, and says it has no coordinates now, rather than drawing it near 0°, 0° without a word.
    let mut z = Session::new(Project::default());
    z.run("layer.addData", &json!({"path": path("plan.png")})).unwrap();
    assert_eq!(plan(&z), Some((false, Some(true))));
    let text = serde_json::to_string(&z.project).unwrap();
    std::fs::remove_file(dir.join("plan.prj")).unwrap();
    let mut gone = Session::new(Project::default());
    gone.run("project.openText", &json!({"text": text})).unwrap();
    let lost = gone.map().layer_by_name("plan").and_then(|l| l.raster.as_ref()).and_then(|r| r.data.as_ref()).map(|d| d.lost.clone());
    assert!(lost.as_ref().is_some_and(|l| l.iter().any(|m| m.contains("no coordinates now"))), "{lost:?}");
    std::fs::copy(dir.join("aerial.prj"), dir.join("plan.prj")).unwrap();

    // A GeoTIFF added as a scan reopens as one, without its own coordinates.
    let placed = rustgis_data::raster::read_path(&dir.join("plan.png")).unwrap();
    rustgis_data::raster::cogwrite::write_file(&placed, 0, &dir.join("tagged.tif")).unwrap();
    let mut x = Session::new(Project::default());
    x.run("layer.addData", &json!({"path": path("tagged.tif"), "as": "scan"})).unwrap();
    let tagged = |x: &Session| {
        x.map().layer_by_name("tagged").and_then(|l| l.raster.as_ref()).and_then(|r| r.data.as_ref()).map(|d| d.georeferenced)
    };
    assert_eq!(tagged(&x), Some(false));
    let text = serde_json::to_string(&x.project).unwrap();
    let mut y = Session::new(Project::default());
    y.run("project.openText", &json!({"text": text})).unwrap();
    assert_eq!(tagged(&y), Some(false));
    std::fs::remove_dir_all(&dir).unwrap();
}

/// Geotagged photos: a folder of them becomes a point layer with each photo's time, camera and
/// thumbnail; photos without a position are named, not added; an upload joins the Photos layer;
/// a project keeps the thumbnails.
#[test]
fn geotagged_photos_become_a_photo_layer() {
    use base64::Engine;
    use rustgis_data::photo;
    let dir = std::env::temp_dir().join(format!("rustgis-photos-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    std::fs::write(dir.join("a.jpg"), photo::example(true, (43.4674, "N"), (11.8851, "E"))).unwrap();
    std::fs::write(dir.join("b.JPEG"), photo::example(false, (43.4671, "N"), (11.8853, "E"))).unwrap();
    // A JPEG without EXIF, and a file that isn't a photo.
    std::fs::write(dir.join("plain.jpg"), b"\xFF\xD8\xFF\xD9").unwrap();
    std::fs::write(dir.join("notes.txt"), b"x").unwrap();
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addPhotos", &json!({"folder": dir.display().to_string()})).unwrap();
    assert_eq!((r["photos"].as_u64(), r["skipped"].as_u64()), (Some(2), Some(1)), "{r}");
    assert!(s.notices.iter().any(|n| n.text.contains("plain.jpg")), "the photo without EXIF is named");
    let l = s.map().layer_by_name("Photos").unwrap();
    assert!(photo::is_photo_layer(&l.dataset));
    let f = &l.dataset.features[0];
    assert_eq!(f.attrs[0], rustgis_data::Value::Text("a".into()));
    assert_eq!(f.attrs[2], rustgis_data::Value::Text("2008-10-22 16:29:49".into()));
    assert!(matches!(&f.attrs[6], rustgis_data::Value::Text(t) if t.starts_with("data:image/jpeg;base64,")));
    // An upload (the web app's way, one file at a time) joins the Photos layer.
    let one = base64::engine::general_purpose::STANDARD.encode(photo::example(true, (43.468, "N"), (11.881, "E")));
    s.run("layer.addDataBytes", &json!({"fileName": "c.jpg", "data": one})).unwrap();
    assert_eq!(s.map().layers.iter().filter(|l| l.name == "Photos").count(), 1);
    assert_eq!(s.map().layer_by_name("Photos").unwrap().dataset.features.len(), 3);
    // So does a photo added by its path.
    s.run("layer.addData", &json!({"path": dir.join("a.jpg").display().to_string()})).unwrap();
    assert_eq!(s.map().layer_by_name("Photos").unwrap().dataset.features.len(), 4);
    // The project keeps them, thumbnails and all.
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let again = t.map().layer_by_name("Photos").unwrap();
    assert_eq!(again.dataset.features.len(), 4);
    assert!(photo::is_photo_layer(&again.dataset));
    // Nothing to add: an error, and nothing added.
    assert!(s.run("layer.addPhotos", &json!({})).is_err());
    assert!(s.run("layer.addPhotos", &json!({"paths": [dir.join("plain.jpg").display().to_string()]})).is_err());
    // Joining a layer one photo short of full: the first photo by name is added, the rest are
    // left out (and never read), and the map zooms to the photo added, not the far-off one.
    let near = dir.join("near-full");
    std::fs::create_dir_all(&near).unwrap();
    std::fs::write(near.join("b-far.jpg"), photo::example(true, (10.0, "S"), (50.0, "W"))).unwrap();
    std::fs::write(near.join("a-near.jpg"), photo::example(true, (43.4674, "N"), (11.8851, "E"))).unwrap();
    let id = s.map().layer_by_name("Photos").unwrap().id;
    let l = s.map_mut().layer_mut(id).unwrap();
    let first = l.dataset.features[0].clone();
    while l.dataset.features.len() < photo::MAX_PHOTOS - 1 {
        l.dataset.push(first.geometry.clone(), first.attrs.clone());
    }
    let r = s.run("layer.addPhotos", &json!({"folder": near.display().to_string()})).unwrap();
    assert_eq!((r["photos"].as_u64(), r["skipped"].as_u64()), (Some(1), Some(1)), "{r}");
    let l = s.map().layer_by_name("Photos").unwrap();
    assert_eq!(l.dataset.features.len(), photo::MAX_PHOTOS);
    assert_eq!(l.dataset.features.last().unwrap().attrs[0], rustgis_data::Value::Text("a-near".into()));
    let c = rustgis_geom::merc_to_lonlat(s.map().camera.center);
    assert!((c.x - 11.8851).abs() < 0.01 && (c.y - 43.4674).abs() < 0.01, "zoomed to {c:?}");
    // Full: nothing more is added, and that's said.
    let r = s.run("layer.addPhotos", &json!({"folder": near.display().to_string()}));
    assert!(r.is_err_and(|e| e.contains("up to")));
    assert_eq!(s.map().layer_by_name("Photos").unwrap().dataset.features.len(), photo::MAX_PHOTOS);
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
fn coverage_answers_that_are_not_geotiffs_are_errors() {
    use crate::cmd::service::coverage_check;
    assert!(coverage_check("c", b"II*\0rest").is_ok());
    assert!(coverage_check("c", b"MM\0*rest").is_ok());
    assert!(coverage_check("c", b"II+\0rest").is_ok());
    for bad in [&b"<ows:ExceptionReport/>"[..], b"Service unavailable", b"", b"\xff\xd8\xff", b"MM: service down", b"II"] {
        let e = coverage_check("c", bad).err().unwrap_or_default();
        assert!(e.starts_with("c: the service answered with an error"), "{e}");
    }
}

/// The keys a command's source reads from its parameters, found by scanning `src/cmd/*.rs`: the
/// command's function (or closure) and the functions it passes its parameters to (in its own
/// file, or another's as `module::name(…)`), a few calls deep.
/// Scans top-level Rust modules; helper subdirectories are not source files or command entries.
fn keys_read_by_commands() -> Vec<(String, std::collections::BTreeSet<String>)> {
    use std::collections::{BTreeMap, BTreeSet};
    type Fn = (Vec<String>, String);
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/cmd");
    // Each module's functions: their `&Value` arguments and bodies.
    let mut modules: BTreeMap<String, (String, BTreeMap<String, Fn>)> = BTreeMap::new();
    for entry in std::fs::read_dir(dir).unwrap() {
        let path = entry.unwrap().path();
        if !path.is_file() || path.extension().is_none_or(|ext| ext != "rs") {
            continue;
        }
        let stem = path.file_stem().unwrap().to_string_lossy().to_string();
        let src = std::fs::read_to_string(&path).unwrap();
        let mut fns: BTreeMap<String, Fn> = BTreeMap::new();
        let mut rest = src.as_str();
        while let Some(at) = rest.find("fn ") {
            let after = &rest[at + 3..];
            let name: String = after.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
            let Some(open) = after.find('{') else { break };
            let body = balanced(&after[open..]);
            fns.entry(name).or_insert((value_args(&after[..open]), body.to_string()));
            rest = &after[open..];
        }
        modules.insert(stem, (src, fns));
    }
    let mut out = Vec::new();
    for (stem, (src, fns)) in &modules {
        let mut rest = src.as_str();
        while let Some(at) = rest.find("C::new(") {
            let call = balanced(&rest[at + 6..]);
            rest = &rest[at + 6..];
            let parts: Vec<&str> = call.splitn(2, '"').collect();
            let id: String = parts.get(1).unwrap_or(&"").chars().take_while(|c| *c != '"').collect();
            // After the three strings: a function name or a closure.
            let mut tail = call;
            for _ in 0..6 {
                tail = &tail[tail.find('"').map_or(tail.len(), |i| i + 1)..];
            }
            let tail = tail.trim_start_matches([',', ' ', '\n']);
            let mut keys = BTreeSet::new();
            let mut todo: Vec<(String, Fn)> = Vec::new();
            if let Some(closure) = tail.strip_prefix('|') {
                let args = closure[..closure.find('|').unwrap()].split(',').map(|a| a.trim().to_string()).skip(1).collect();
                todo.push((stem.clone(), (args, tail.to_string())));
            } else {
                let name: String = tail.chars().take_while(|c| c.is_alphanumeric() || *c == '_').collect();
                todo.extend(fns.get(&name).cloned().map(|f| (stem.clone(), f)));
            }
            let mut seen = BTreeSet::new();
            let mut depth = 0;
            while !todo.is_empty() && depth < 6 {
                for (module, (args, body)) in std::mem::take(&mut todo) {
                    let args: Vec<&String> = args.iter().filter(|a| !a.starts_with('_')).collect();
                    for a in &args {
                        // The helpers that read a key: `ps(p, "key")`…
                        for h in ["ps", "f", "b", "uint", "s_req", "color", "get_color", "band", "point", "limit", "method"] {
                            keys.extend(literal_keys(&body, &format!("{h}({a}, \"")));
                        }
                        keys.extend(literal_keys(&body, &format!("{a}.get(\"")));
                        keys.extend(literal_keys(&body, &format!("{a}[\"")));
                        if body.contains(&format!("layer_id({a})")) || body.contains(&format!("layer_id(&{a})")) {
                            keys.insert("layer".to_string());
                        }
                        if body.contains(&format!("table_index({a})")) {
                            keys.insert("table".to_string());
                        }
                    }
                    // The functions it passes one of its parameter values to, at any position.
                    for (m, (_, mfns)) in &modules {
                        for (name, f) in mfns {
                            let qualified = if m == "mod" { format!("super::{name}") } else { format!("{m}::{name}") };
                            let call = if *m == module { name.as_str() } else { qualified.as_str() };
                            let key = format!("{m}::{name}");
                            // A dispatcher by kind: its arms read keys for other commands.
                            if matches!(key.as_str(), "items::item_bytes" | "items::item_output") {
                                continue;
                            }
                            if !seen.contains(&key) && args.iter().any(|a| calls(&body, call, a)) {
                                seen.insert(key);
                                todo.push((m.clone(), f.clone()));
                            }
                        }
                    }
                }
                depth += 1;
            }
            out.push((id, keys));
        }
    }
    out
}

/// `s` from its opening bracket to the matching close, skipping strings, raw strings and chars.
fn balanced(s: &str) -> &str {
    let b = s.as_bytes();
    let (mut depth, mut i) = (0i32, 0);
    while i < b.len() {
        match b[i] {
            b'r' if b.get(i + 1) == Some(&b'#') && b.get(i + 2) == Some(&b'"') => {
                i += s[i + 3..].find("\"#").map_or(b.len(), |n| n + 4);
            }
            b'"' => {
                i += 1;
                while i < b.len() && b[i] != b'"' {
                    i += if b[i] == b'\\' { 2 } else { 1 };
                }
            }
            b'\'' if b.get(i + 2) == Some(&b'\'') => i += 2,
            b'\'' if b.get(i + 1) == Some(&b'\\') && b.get(i + 3) == Some(&b'\'') => i += 3,
            b'{' | b'(' | b'[' => depth += 1,
            b'}' | b')' | b']' => {
                depth -= 1;
                if depth == 0 {
                    return &s[..=i];
                }
            }
            _ => {}
        }
        i += 1;
    }
    s
}

/// Whether `body` calls `name(…)` (not as part of a longer name) with `arg` itself as one of its
/// arguments (`p`, `&p`, `p.clone()`).
fn calls(body: &str, name: &str, arg: &str) -> bool {
    let word = |c: Option<char>| c.is_some_and(|c| c.is_alphanumeric() || c == '_');
    body.match_indices(&format!("{name}(")).any(|(i, m)| {
        let before = body[..i].chars().next_back();
        if word(before) || before == Some('.') || (!name.contains("::") && before == Some(':')) {
            return false;
        }
        let args = balanced(&body[i + m.len() - 1..]);
        let inner = &args[1..args.len().saturating_sub(1)];
        // The arguments, split at top-level commas.
        let (mut depth, mut start, mut found) = (0i32, 0, false);
        for (j, c) in inner.char_indices().chain([(inner.len(), ',')]) {
            match c {
                '(' | '[' | '{' => depth += 1,
                ')' | ']' | '}' => depth -= 1,
                ',' if depth == 0 => {
                    let a = inner[start..j].trim();
                    found |= [arg.to_string(), format!("&{arg}"), format!("{arg}.clone()")].contains(&a.to_string());
                    start = j + 1;
                }
                _ => {}
            }
        }
        found
    })
}

/// The names of the `&Value` arguments in a function signature.
fn value_args(sig: &str) -> Vec<String> {
    sig.split([',', '('])
        .filter_map(|a| {
            a.split_once(':').filter(|(_, t)| t.trim().starts_with("&") && t.contains("Value")).map(|(n, _)| n.trim().to_string())
        })
        .collect()
}

/// The string literals that follow `prefix` (not part of a longer name) in `body`.
fn literal_keys(body: &str, prefix: &str) -> Vec<String> {
    body.match_indices(prefix)
        .filter(|(i, _)| !body[..*i].chars().next_back().is_some_and(|c| c.is_alphanumeric() || c == '_'))
        .map(|(i, _)| body[i + prefix.len()..].chars().take_while(|c| *c != '"').collect::<String>())
        .filter(|k| !k.is_empty())
        .collect()
}

/// Checks every discovered command's declared keys, even when helper directories accompany modules.
#[test]
fn params_name_every_key_a_command_reads() {
    // Read by a shared helper but of no use to the command.
    let unused = [
        ("gp.spatialJoin", "input"),
        ("gp.zonalStats", "input"),
        ("gp.zonalStats", "target"),
        ("profile.alongSelected", "row"),
        ("sources.remove", "name"),
        ("sources.remove", "extra"),
    ];
    let s = Session::new(Project::default());
    let mut missing = Vec::new();
    let found = keys_read_by_commands();
    assert!(found.len() > 300, "the scan found {} commands", found.len());
    for (id, keys) in found {
        let Some(spec) = s.registry.get(&id) else { continue };
        let named = spec.param_keys().unwrap_or_default();
        let absent: Vec<_> = keys
            .iter()
            .filter(|k| {
                !named.contains(&k.as_str()) && !spec.params.contains(&format!("\"{k}\"")) && !unused.contains(&(id.as_str(), k.as_str()))
            })
            .collect();
        if !absent.is_empty() {
            missing.push(format!("{id}: {absent:?} (params {})", spec.params));
        }
    }
    assert!(missing.is_empty(), "{} commands read keys their params don't name:\n{}", missing.len(), missing.join("\n"));
}

#[test]
fn needs_input_reads_descriptions() {
    use crate::needs_input;
    assert!(!needs_input("{}"));
    assert!(!needs_input(r#"{"layer"?, "name"?: text}"#));
    assert!(needs_input(r#"{"layer": raster, "points"?: [[column, row, lon, lat], …]}"#));
    assert!(needs_input(r#"{"path": folder | "url": "https://…", "name"?: text}"#));
    assert!(needs_input(r#"{"url": "https://…/x.json?f=json"}"#));
    assert!(!needs_input(r#"{"steps"?: [{"required": value}], "url"?: "https://…/?q=x"}"#));
    assert!(needs_input("a GeoJSON text: {type: …}"));
    assert!(!needs_input("a GeoJSON text"));
    assert!(needs_input("a service URL: https://…/query?f=json"));
    let s = Session::new(Project::default());
    assert!(s.registry.get("raster.georeference").is_some_and(crate::CommandSpec::needs_input));
    assert!(s.registry.get("map.zoomIn").is_some_and(|c| !c.needs_input()));
}

/// A description splits into one entry per parameter, for help that lists them (#662): commas
/// inside quotes, parentheses, brackets or braces stay in their entry.
#[test]
fn param_list_splits_a_description_into_entries() {
    use crate::{Param, param_list};
    let desc =
        r#"{"layer"?, "class"?: name (none: the Default class, by whatever name it has), "steps"?: [{"tool": id}, …], "where": "a, b"}"#;
    let list = param_list(desc).unwrap();
    let keys: Vec<(&str, bool)> = list.iter().map(|p| (p.key, p.optional)).collect();
    assert_eq!(keys, [("layer", true), ("class", true), ("steps", true), ("where", false)]);
    assert_eq!(list[1].text, r#""class"?: name (none: the Default class, by whatever name it has)"#);
    assert_eq!(param_list("{}"), Some(Vec::<Param>::new()));
    // An escaped quote (a plugin's description may have one) doesn't end a value early.
    let escaped = param_list(r#"{"title"?: "a \"quoted, word\"", "n": number}"#).unwrap();
    assert_eq!(escaped.iter().map(|p| p.key).collect::<Vec<_>>(), ["title", "n"]);
    // Nor a key early: it's the whole key, as `param_keys` reads it.
    let key = param_list(r#"{"a\"b"?: text}"#).unwrap();
    assert_eq!(key.iter().map(|p| (p.key, p.optional)).collect::<Vec<_>>(), [(r#"a\"b"#, true)]);
    assert_eq!(crate::param_keys(r#"{"a\"b"?: text}"#), Some(vec![r#"a\"b"#]));
    assert_eq!(param_list("a GeoJSON text"), None);
    // Every command's description splits into entries, each led by a key `param_keys` finds: one
    // cut in the wrong place (an unclosed bracket or quote in its prose) would lead with another.
    let s = Session::new(Project::default());
    for c in &s.registry.commands {
        let list = param_list(c.params).unwrap_or_else(|| panic!("{}: {}", c.id, c.params));
        let keys = c.param_keys().unwrap_or_default();
        for p in &list {
            assert!(keys.contains(&p.key), "{}: entry {:?} in {}", c.id, p.text, c.params);
        }
    }
}

/// Quoted text is read as JSON has it (#741): strings and their quotes aren't code, and a
/// backslash escapes the char after it only in a string.
#[test]
fn quotes_read_text_as_json_does() {
    use crate::{Quotes, string_end};
    let code = |s: &str| {
        let (mut q, mut out) = (Quotes::default(), String::new());
        for c in s.chars() {
            if q.read(c) {
                out.push(c);
            }
        }
        out
    };
    assert_eq!(code(r#"{"a": "b,c", "d": 1}"#), "{: , : 1}");
    assert_eq!(code(r#"{"a\"b": 1}"#), "{: 1}", "an escaped quote");
    assert_eq!(code(r#"{"a\\": 1}"#), "{: 1}", "an escaped backslash");
    assert_eq!(code(r#"x \"a" y"#), r#"x \ y"#, "a backslash outside a string escapes nothing");
    assert_eq!(code("ñ \"é\" ü"), "ñ  ü", "chars, not bytes");
    let mut q = Quotes::default();
    for c in r#"{"a": "b"#.chars() {
        q.read(c);
    }
    assert!(q.quoted(), "ends in a string");
    assert_eq!(string_end(r#"a\"b", 1"#), Some(4));
    assert_eq!(string_end("é\""), Some(2), "a byte index");
    assert_eq!(string_end(r#"a\""#), None, "nothing closes it");
    assert_eq!(string_end(""), None);
}

#[test]
fn param_keys_reads_descriptions() {
    use crate::param_keys;
    assert_eq!(param_keys("{}"), Some(vec![]));
    assert_eq!(param_keys(r#"{"layer"?, "name": string}"#), Some(vec!["layer", "name"]));
    // Values, nested objects and prose are not keys.
    assert_eq!(
        param_keys(r#"{"mode": "a"|"b", "steps"?: [{"tool": id}], "extent"?: [w, s, e, n] (clip, "view")}"#),
        Some(vec!["mode", "steps", "extent"])
    );
    // Alternatives.
    assert_eq!(param_keys(r#"{"path": folder | "url": "https://…", "name"?: text}"#), Some(vec!["path", "url", "name"]));
    assert_eq!(param_keys(r#"{"lon" | "x": number, "lat" | "y": number}"#), Some(vec!["lon", "x", "lat", "y"]));
    assert_eq!(param_keys(r##"{"color": "#RRGGBB"|"#RRGGBBAA"}"##), Some(vec!["color"]));
    // A quote after a backslash doesn't end a string (a Script line's value may have one); one
    // after an escaped backslash does.
    assert_eq!(param_keys(r#"{"lon": 2, "note": "a\"b", "lat": 3, ""#), Some(vec!["lon", "note", "lat"]));
    assert_eq!(param_keys(r#"{"a": "x\\", "b": 1}"#), Some(vec!["a", "b"]));
    assert_eq!(param_keys(r#"{"a": "x\"#), Some(vec!["a"]), "an unclosed string");
    assert_eq!(param_keys("a GeoJSON text"), None);
    // Every command's description reads as keys, and names a key once.
    for c in &Session::new(Project::default()).registry.commands {
        let keys = c.param_keys().unwrap_or_else(|| panic!("{}: params {} are not an object", c.id, c.params));
        let mut unique = keys.clone();
        unique.sort_unstable();
        unique.dedup();
        assert_eq!(unique.len(), keys.len(), "{}: {}", c.id, c.params);
    }
}

/// The keys that take an expression say so by their type, `sql` or `expression`, which the Script
/// reads to complete them; quoted prose for another language (a database's, a service's) isn't
/// one. Every command whose expression it reads is listed, so a description losing the word, or a
/// new expression key, shows here.
#[test]
fn expression_keys_are_marked_by_their_type() {
    use crate::expression_keys;
    assert_eq!(expression_keys(r#"{"layer"?, "where": sql, "mode"?: "new"|"add"}"#), vec!["where"]);
    assert_eq!(expression_keys(r#"{"size"?: expression|null (points), "fill"?: expression|null}"#), vec!["size", "fill"]);
    assert_eq!(expression_keys(r#"{"where": "an SQL condition on the table's columns"}"#), Vec::<&str>::new(), "prose");
    assert_eq!(expression_keys(r#"{"db"?: sqlite file, "list"?: expressions}"#), Vec::<&str>::new(), "a longer word");
    assert_eq!(expression_keys("a GeoJSON text"), Vec::<&str>::new());
    let mut marked: Vec<String> = Session::new(Project::default())
        .registry
        .commands
        .iter()
        .flat_map(|c| expression_keys(c.params).into_iter().map(move |k| format!("{} {k}", c.id)))
        .collect();
    marked.sort_unstable();
    let expected = [
        "data.attributeRule expression",
        "edit.calculateField expression",
        "labels.by angle",
        "labels.by color",
        "labels.by size",
        "labels.by text",
        "labels.class.add where",
        "labels.class.update where",
        "layer.definitionQuery where",
        "layer.symbolBy angle",
        "layer.symbolBy fill",
        "layer.symbolBy size",
        "layer.symbolBy stroke",
        "layer.symbolBy strokeWidth",
        "layer.symbology expression",
        "report.new where",
        "report.update where",
        "select.byAttributes where",
    ];
    assert_eq!(marked, expected);
}

/// A STAC trend's keys are cube.trend's own: given, none is said to be ignored (they sat inside
/// the description's "collection" note, where the key reader doesn't look).
#[test]
fn a_stac_trends_keys_are_read() {
    let mut s = world();
    let keys = s.registry.get("cube.trend").and_then(|c| c.param_keys()).unwrap();
    for k in ["collection", "url", "asset", "bbox", "maxCloud", "cellSize", "resampling", "start", "end"] {
        assert!(keys.contains(&k), "{k}: {keys:?}");
    }
    let mark = s.notice_mark();
    // A cell size of 0: refused before any search, so nothing reaches the network, after the keys
    // are read.
    let p = json!({"collection": "c", "url": "http://127.0.0.1:9/v1", "asset": "NDVI", "bbox": [0, 0, 1, 1], "maxCloud": 20, "cellSize": 0, "resampling": "average", "start": "2020", "end": "2021"});
    let e = s.run("cube.trend", &p).unwrap_err();
    assert!(e.contains("cellSize"), "{e}");
    let said: Vec<&str> = s.notices_since(mark).iter().map(|n| n.text.as_str()).collect();
    assert!(said.iter().all(|t| !t.contains("ignores")), "{said:?}");
}

#[test]
fn unknown_params_are_said() {
    let mut s = world();
    let mark = s.notice_mark();
    s.run("layer.moveDown", &json!({"layer": "Cities", "steps": 13})).unwrap();
    let said: Vec<&str> = s.notices_since(mark).iter().map(|n| n.text.as_str()).collect();
    assert_eq!(said, ["layer.moveDown ignores 'steps' (it reads layer)"]);
    // Known keys, and commands that take none, say nothing more.
    let mark = s.notice_mark();
    s.run("layer.rename", &json!({"layer": "Cities", "name": "Towns"})).unwrap();
    assert!(s.notices_since(mark).is_empty());
    s.run("layout.close", &json!({"x": 1})).unwrap();
    assert_eq!(s.notices_since(mark).first().map(|n| n.text.as_str()), Some("layout.close ignores 'x' (it reads no parameters)"));
    // Many or long keys are said briefly.
    let mut junk = serde_json::Map::new();
    for i in 0..1000 {
        junk.insert(format!("{i:04}{}", "k".repeat(500)), Value::Null);
    }
    let mark = s.notice_mark();
    s.run("layout.close", &Value::Object(junk)).unwrap();
    let said = s.notices_since(mark).first().map(|n| n.text.clone()).unwrap_or_default();
    assert!(said.len() < 500 && said.contains("995 more"), "{said}");
}

/// A GeometryCollection of several members is refused by what is wrong with it.
#[test]
fn a_geometry_collection_of_several_is_refused_as_such() {
    use rustgis_data::{Coord, Geometry};
    let mut s = world();
    let point = json!({"type": "Point", "coordinates": [1, 2]});
    let two = json!({"type": "GeometryCollection", "geometries": [point, point]});
    let nested = json!({"type": "GeometryCollection", "geometries": [two]});
    let empty = json!({"type": "GeometryCollection", "geometries": []});
    for cmd in ["edit.addFeature", "edit.setGeometry"] {
        for g in [&two, &nested, &empty] {
            let e = s.run(cmd, &json!({"layer": "Cities", "row": 0, "geometry": g})).unwrap_err();
            assert!(e.contains("a GeometryCollection must hold exactly one geometry"), "{cmd}: {e}");
        }
        let e = s.run(cmd, &json!({"layer": "Cities", "row": 0, "geometry": {"type": "Blob"}})).unwrap_err();
        assert!(e.contains("geometry must be a GeoJSON geometry"), "{cmd}: {e}");
    }
    // One member, at any depth, is the geometry.
    let one = json!({"type": "GeometryCollection", "geometries": [{"type": "GeometryCollection", "geometries": [point]}]});
    let before = s.map().layer_by_name("Cities").unwrap().dataset.features.len();
    let added = s.run("edit.addFeature", &json!({"layer": "Cities", "geometry": one})).unwrap();
    let row = added["row"].as_u64().unwrap() as usize;
    assert_eq!((row, s.map().layer_by_name("Cities").unwrap().dataset.features.len()), (before, before + 1));
    s.run("edit.setGeometry", &json!({"layer": "Cities", "row": 0, "geometry": one})).unwrap();
    let cities = &s.map().layer_by_name("Cities").unwrap().dataset;
    for r in [row, 0] {
        assert_eq!(cities.features[r].geometry, Some(Geometry::Point(Coord::new(1.0, 2.0))), "row {r}");
    }
}

#[test]
fn geojson_collection_import_reports_loss_even_without_surviving_geometry() {
    let collection = json!({"type":"GeometryCollection", "geometries":[
        {"type":"Point", "coordinates":[1,2]},
        {"type":"Polygon", "coordinates":[[[0,0],[4,0],[4,4],[0,0]]]}
    ]});
    let mut s = Session::new(Project::default());
    s.run("layer.addDataText", &json!({"fileName":"collection.geojson", "text":collection.to_string()})).unwrap();
    assert!(s.notices.iter().any(|n| n.text.contains("1 features had unreadable geometry")));
    assert!(s.map().layers.is_empty(), "a partial geometry must never become a layer");

    let mut clean = Session::new(Project::default());
    clean.run("layer.addDataText", &json!({"fileName":"point.geojson", "text":r#"{"type":"Point","coordinates":[1,2]}"#})).unwrap();
    assert!(!clean.notices.iter().any(|n| n.text.contains("unreadable geometry")));
}

#[test]
fn geojson_read_in_place_when_asked_or_large() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut ds = Dataset::new("pts", GeometryType::Point, vec![Field::new("i", FieldType::Integer)]);
    for i in 0..500 {
        ds.push(Some(Geometry::Point(Coord::new(-170.0 + i as f64 * 0.68, (i % 50) as f64))), vec![V::Int(i)]);
    }
    let p = std::env::temp_dir().join(format!("rustgis-engine-{}-pts.geojson", std::process::id()));
    rustgis_data::io::write_path(&ds, &p).unwrap();
    // Small: loaded whole, as before.
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addData", &json!({"path": p.display().to_string()})).unwrap();
    assert!(!s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().is_streamed());
    // Asked to stream: read in place, saved as its file, opened again in place.
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addData", &json!({"path": p.display().to_string(), "stream": true})).unwrap();
    assert_eq!(r["streamed"], true, "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    let v = view_of(&mut s, rustgis_geom::Extent::new(-180.0, -10.0, 180.0, 60.0));
    crate::render::render_png(s.map_mut(), &v).unwrap();
    assert_eq!(s.map().layer(id).unwrap().dataset.features.len(), 500);
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    assert!(t.map().layers[0].is_streamed() && t.map().layers[0].source.as_ref().unwrap().is_open());
    // Load All Features: the same features as a whole read.
    s.run("layer.loadAll", &json!({"layer": id})).unwrap();
    let whole = rustgis_data::io::read_path(&p).unwrap().0;
    assert_eq!(s.map().layer(id).unwrap().dataset.features, whole.features);
    // Larger than IN_PLACE_ABOVE (trailing whitespace pads it): read in place without being asked,
    // and streamed past STREAM_ABOVE features.
    let n = rustgis_map::source::STREAM_ABOVE as usize + 1;
    let mut many = Dataset::new("many", GeometryType::Point, vec![Field::new("i", FieldType::Integer)]);
    for i in 0..n {
        many.push(Some(Geometry::Point(Coord::new(-179.0 + 358.0 * i as f64 / n as f64, 0.0))), vec![V::Int(i as i64)]);
    }
    let large = std::env::temp_dir().join(format!("rustgis-engine-{}-large.geojson", std::process::id()));
    let mut text = rustgis_data::io::to_geojson(&many).to_string().into_bytes();
    let json_len = text.len();
    let pad = (rustgis_data::source::geojson::IN_PLACE_ABOVE as usize + 1).saturating_sub(text.len());
    text.resize(text.len() + pad, b' ');
    std::fs::write(&large, &text).unwrap();
    let mut u = Session::new(Project::default());
    let r = u.run("layer.addData", &json!({"path": large.display().to_string()})).unwrap();
    assert_eq!(r["streamed"], true, "{r}");
    assert_eq!(r["features"], n as u64, "{r}");
    // A large file that isn't JSON says why, rather than falling back to a whole read.
    text.truncate(json_len / 2);
    text.resize(rustgis_data::source::geojson::IN_PLACE_ABOVE as usize + 1, b' ');
    std::fs::write(&large, &text).unwrap();
    let e = u.run("layer.addData", &json!({"path": large.display().to_string()})).unwrap_err();
    assert!(e.contains("GeoJSON") && !e.contains("too large"), "{e}");
    let _ = std::fs::remove_file(&large);
    // A document that isn't a FeatureCollection is read whole even when asked to stream.
    let one = std::env::temp_dir().join(format!("rustgis-engine-{}-one.geojson", std::process::id()));
    std::fs::write(&one, r#"{"type":"Point","coordinates":[1,2]}"#).unwrap();
    let r = s.run("layer.addData", &json!({"path": one.display().to_string(), "stream": true})).unwrap();
    assert!(!s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().is_streamed());
    let _ = std::fs::remove_file(p);
    let _ = std::fs::remove_file(one);
}

/// Emptying the Shapefile index cache keeps the index of a layer that's open, says so, and the
/// layer still reads (#1259).
#[test]
fn emptying_the_index_cache_keeps_indexes_in_use() {
    let p = line_of_points_shp("index-cache", 20);
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addData", &json!({"path": p.display().to_string(), "stream": true})).unwrap();
    let mark = s.notice_mark();
    let out = s.run("cache.emptyIndexes", &Value::Null).unwrap();
    assert!(out["inUse"].as_u64().unwrap() >= 1, "{out}");
    assert!(out["removed"].is_u64() && out["freedBytes"].is_u64(), "{out}");
    let notices = s.notices_since(mark);
    assert!(notices.iter().any(|n| n.text.contains("in use") && !n.error), "{notices:?}");
    let layer = s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap();
    assert_eq!(layer.load_all().unwrap().features.len(), 20);
    drop(s);
    remove_shp(&p);
}

/// Emptying the index cache tells the user only what it couldn't do: nothing when all went (#1259).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn emptying_the_index_cache_notices_only_what_stayed() {
    use crate::cmd::workspace::empty_notices;
    let mut e = rustgis_data::source::shp::Emptied::default();
    assert!(empty_notices(&e).is_empty());
    e.removed = 3;
    e.removed_bytes = 4096;
    assert!(empty_notices(&e).is_empty(), "what it freed is in the result, not a notice");
    e.in_use = 1;
    e.in_use_bytes = 2048;
    e.kept_bytes = 3 * 1024 * 1024;
    e.failed.push("/somewhere: refused".to_string());
    let notices = empty_notices(&e);
    assert!(notices.iter().any(|(t, error)| *error && t.contains("/somewhere: refused")), "{notices:?}");
    assert!(notices.iter().any(|(t, error)| !*error && t.contains("1 index in use") && t.contains("2.0 KB")), "{notices:?}");
    assert!(notices.iter().any(|(t, error)| !*error && t.contains("not removed") && t.contains("3.0 MB")), "{notices:?}");
}

/// A Shapefile of `n` points along the equator, numbered.
fn line_of_points_shp(name: &str, n: usize) -> std::path::PathBuf {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    let mut ds = Dataset::new(name, GeometryType::Point, vec![Field::new("i", FieldType::Integer)]);
    for i in 0..n {
        ds.push(Some(Geometry::Point(Coord::new(-179.0 + 358.0 * i as f64 / n.max(2) as f64, 0.0))), vec![V::Int(i as i64)]);
    }
    let p = std::env::temp_dir().join(format!("rustgis-engine-{}-{name}.shp", std::process::id()));
    rustgis_data::io::write_path(&ds, &p).unwrap();
    p
}

/// Removes a Shapefile written by [`line_of_points_shp`] with its sidecar files.
fn remove_shp(p: &std::path::Path) {
    for ext in ["shp", "shx", "dbf", "prj", "cpg"] {
        let _ = std::fs::remove_file(p.with_extension(ext));
    }
}

#[test]
fn shapefiles_too_large_to_load_whole_still_open() {
    // Few records, but a .shp or .dbf past what the whole-file reader takes (#1055): opened and
    // kept in place, so it never has to fit in memory whole, rather than refused as too large.
    // Grown sparse where the file system allows.
    for grown in ["dbf", "shp"] {
        let p = line_of_points_shp(&format!("wide-{grown}"), 20);
        std::fs::OpenOptions::new().write(true).open(p.with_extension(grown)).unwrap().set_len(rustgis_data::io::BYTES_FLOOR + 1).unwrap();
        let path = p.display().to_string();
        // With and without a coordinate system given for it.
        for params in [json!({"path": path}), json!({"path": path, "crs": "EPSG:4326"})] {
            let mut s = Session::new(Project::default());
            let r = s.run("layer.addData", &params).unwrap();
            assert_eq!(r["features"], 20, "{grown}: {r}");
            assert_eq!(r["streamed"], true, "{grown}: {r}");
            assert!(s.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().is_streamed());
        }
        // "stream": false still asks for the whole-file reader, which refuses it where it takes
        // no more than the floor (it would read it whole on a computer whose reader takes more).
        let mut s = Session::new(Project::default());
        let e = rustgis_data::io::with_max_bytes(rustgis_data::io::BYTES_FLOOR, || {
            s.run("layer.addData", &json!({"path": path, "stream": false})).unwrap_err()
        });
        assert!(e.contains("too large"), "{grown}: {e}");
        remove_shp(&p);
    }
}

#[test]
fn large_shapefiles_are_read_in_place() {
    // Small: loaded whole, so it can be edited.
    let small = line_of_points_shp("small-shp", 50);
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addData", &json!({"path": small.display().to_string()})).unwrap();
    let id = r["layer"].as_u64().unwrap() as u32;
    assert!(!s.map().layer(id).unwrap().is_streamed());
    assert_eq!(s.map().layer(id).unwrap().dataset.features.len(), 50);

    // Past the streaming threshold: read in place, a view at a time.
    let n = rustgis_map::source::STREAM_ABOVE as usize + 1;
    let big = line_of_points_shp("big-shp", n);
    let mut s = Session::new(Project::default());
    let r = s.run("layer.addData", &json!({"path": big.display().to_string()})).unwrap();
    assert_eq!(r["streamed"], true, "{r}");
    assert_eq!(r["features"], n as u64, "{r}");
    let id = r["layer"].as_u64().unwrap() as u32;
    let v = view_of(&mut s, rustgis_geom::Extent::new(-10.0, -5.0, 10.0, 5.0));
    crate::render::render_png(s.map_mut(), &v).unwrap();
    let l = s.map().layer(id).unwrap();
    assert!(l.is_streamed());
    assert!(!l.dataset.features.is_empty() && l.dataset.features.len() < n);

    // Saved as its file, opened again in place.
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(text.len() < 20_000, "{}", text.len());
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    assert!(t.map().layers[0].is_streamed() && t.map().layers[0].source.as_ref().unwrap().is_open());

    // Load All Features: every point, editable.
    let r = s.run("layer.loadAll", &json!({"layer": id})).unwrap();
    assert_eq!(r["features"], n as u64);
    assert!(!s.map().layer(id).unwrap().is_streamed());
    // "stream": false loads even a large one whole.
    let mut u = Session::new(Project::default());
    let r = u.run("layer.addData", &json!({"path": big.display().to_string(), "stream": false})).unwrap();
    assert!(!u.map().layer(r["layer"].as_u64().unwrap() as u32).unwrap().is_streamed());
    for p in [small, big] {
        remove_shp(&p);
    }
}

/// A PostGIS layer in a project names its connection without the password, and opening the
/// project never sends the user's own credentials: a server that wants one is reported, with how
/// to connect again.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn postgis_layers_reopen_without_secrets() {
    // Nothing listens on port 1: the connection is refused at once.
    let mut s = Session::new(Project::default());
    let mut src: rustgis_map::source::SourceLayer = serde_json::from_value(json!({
        "postgis": {"database": "postgres:host=127.0.0.1 port=1 dbname=gis user=me", "table": "roads", "family": "Lines"}
    }))
    .unwrap();
    let e = src.open().unwrap_err();
    assert!(e.contains("connect again with Home › Add › Add Data › Database"), "{e}");
    assert!(!src.is_open());
    // Saved again, it keeps its table and never a password.
    let saved = serde_json::to_string(&src).unwrap();
    assert!(saved.contains("\"table\":\"roads\"") && !saved.contains("password"), "{saved}");
    // A connection that isn't there fails as an error, never a panic, and adds nothing.
    let before = s.map().layers.len();
    let e = s.run("layer.addDatabase", &json!({"database": "postgres:host=127.0.0.1 port=1 dbname=gis", "password": "pw"})).unwrap_err();
    assert!(e.starts_with("gis: ") && !e.contains("pw"), "{e}");
    let e = s.run("info.databaseTables", &json!({"database": "postgresql://u:pw@127.0.0.1:1/gis"})).unwrap_err();
    assert!(!e.contains(":pw"), "{e}");
    assert_eq!(s.map().layers.len(), before);
}

/// A live PostGIS database through the commands: `RUSTGIS_TEST_POSTGIS="postgres:host=… dbname=…
/// user=… password=…"` names one with PostGIS's `us_cities`-style tables (any will do); every
/// table is added, drawn, saved and opened again.
#[cfg(not(target_arch = "wasm32"))]
#[test]
#[ignore = "needs a live PostGIS database with geometry tables in RUSTGIS_TEST_POSTGIS"]
fn postgis_live_end_to_end() {
    let Ok(dsn) = std::env::var("RUSTGIS_TEST_POSTGIS") else { return };
    let mut s = Session::new(Project::default());
    let listed = s.run("info.databaseTables", &json!({"database": dsn})).unwrap();
    let names: Vec<String> = listed["layers"].as_array().unwrap().iter().filter_map(|v| v.as_str()).map(str::to_string).collect();
    assert!(!names.is_empty());
    let r = s.run("layer.addDatabase", &json!({"database": dsn, "layer": names[0]})).unwrap();
    assert!(r["features"].as_u64().unwrap() > 0, "{r}");
    // Streamed when asked: saved without its features or the password, read again when opened.
    let r = s.run("layer.addDatabase", &json!({"database": dsn, "layer": names[0], "stream": true, "name": "live"})).unwrap();
    assert_eq!(r["streamed"], true);
    let id = r["layer"].as_u64().unwrap() as u32;
    assert!(s.map().layer(id).unwrap().source.as_ref().unwrap().postgis.is_some());
    let dir = std::env::temp_dir().join(format!("rustgis-engine-postgis-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let png = dir.join("map.png");
    s.run("share.exportMap", &json!({"path": png.display().to_string()})).unwrap();
    assert!(std::fs::metadata(&png).unwrap().len() > 1000);
    let text = serde_json::to_string(&s.project).unwrap();
    assert!(!text.contains("password"), "the project keeps no password");
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let l = t.map().layer_by_name("live").unwrap();
    assert!(l.source.as_ref().unwrap().is_open(), "{:?}", l.source.as_ref().unwrap().error);
    let _ = std::fs::remove_dir_all(&dir);
}

/// A MySQL or MariaDB layer in a project names its connection without the password, and opening
/// the project never sends one it wasn't given this session (`MYSQL_PWD` included).
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn mysql_layers_reopen_without_secrets() {
    let mut s = Session::new(Project::default());
    let mut src: rustgis_map::source::SourceLayer = serde_json::from_value(json!({
        "mysql": {"database": "mysql://me@127.0.0.1:1/gis?ssl-mode=DISABLED", "table": "roads", "family": "Lines"}
    }))
    .unwrap();
    let e = src.open().unwrap_err();
    assert!(e.contains("connect again with Home › Add › Add Data › Database"), "{e}");
    assert!(!src.is_open());
    let saved = serde_json::to_string(&src).unwrap();
    assert!(saved.contains("\"mysql\":{") && saved.contains("\"table\":\"roads\"") && !saved.contains("password"), "{saved}");
    // A connection that isn't there fails as an error, never a panic, and adds nothing; the
    // password, in the address or given beside it, is in no message.
    let before = s.map().layers.len();
    let e = s.run("layer.addDatabase", &json!({"database": "mysql://me:s3cret@127.0.0.1:1/gis", "password": "pw"})).unwrap_err();
    assert!(e.starts_with("gis: ") && !e.contains("s3cret") && !e.contains("pw"), "{e}");
    let e = s.run("info.databaseTables", &json!({"database": "mariadb://u:s3cret@127.0.0.1:1"})).unwrap_err();
    assert!(e.starts_with("mysql: ") && !e.contains("s3cret"), "{e}");
    // An address that can't be read is said so.
    let e = s.run("layer.addDatabase", &json!({"database": "mysql://h:port/gis"})).unwrap_err();
    assert!(e.contains("port 'port'"), "{e}");
    // SQL queries don't run on one.
    let e = s.run("layer.addSql", &json!({"sql": "SELECT 1", "database": "mysql://h/gis"})).unwrap_err();
    assert!(e.contains("MySQL"), "{e}");
    assert_eq!(s.map().layers.len(), before);
}

/// A live MySQL or MariaDB database through the commands: `RUSTGIS_TEST_MYSQL="mysql://user:
/// password@host:port/database"` names one with tables of geometry (any will do); every table is
/// added, drawn, saved and opened again.
#[cfg(not(target_arch = "wasm32"))]
#[test]
#[ignore = "needs a live MySQL or MariaDB database with geometry tables in RUSTGIS_TEST_MYSQL"]
fn mysql_live_end_to_end() {
    let Ok(address) = std::env::var("RUSTGIS_TEST_MYSQL") else { return };
    let mut s = Session::new(Project::default());
    let listed = s.run("info.databaseTables", &json!({"database": address})).unwrap();
    let names: Vec<String> = listed["layers"].as_array().unwrap().iter().filter_map(|v| v.as_str()).map(str::to_string).collect();
    assert!(!names.is_empty());
    // Every table: a column of mixed types becomes a layer per type.
    let r = s.run("layer.addDatabase", &json!({"database": address})).unwrap();
    assert!(r["layers"].as_array().unwrap().len() >= names.len(), "{r}");
    assert!(r["features"].as_u64().unwrap() > 0, "{r}");
    // Streamed when asked: saved without its features or the password, read again when opened.
    let r = s.run("layer.addDatabase", &json!({"database": address, "layer": names[0], "stream": true, "name": "live"})).unwrap();
    assert_eq!(r["streamed"], true);
    let id = r["layer"].as_u64().unwrap() as u32;
    assert!(s.map().layer(id).unwrap().source.as_ref().unwrap().mysql.is_some());
    let dir = std::env::temp_dir().join(format!("rustgis-engine-mysql-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let png = dir.join("map.png");
    s.run("share.exportMap", &json!({"path": png.display().to_string()})).unwrap();
    assert!(std::fs::metadata(&png).unwrap().len() > 1000);
    let text = serde_json::to_string(&s.project).unwrap();
    let password = address.split_once("://").and_then(|(_, r)| r.split_once('@')).and_then(|(u, _)| u.split_once(':')).map(|(_, p)| p);
    assert!(password.is_none_or(|p| !text.contains(&format!(":{p}@"))), "the project keeps no password");
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let l = t.map().layer_by_name("live").unwrap();
    assert!(l.source.as_ref().unwrap().is_open(), "{:?}", l.source.as_ref().unwrap().error);
    let _ = std::fs::remove_dir_all(&dir);
}

/// SQL Server project reopening and failed commands never expose credentials or add layers.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn sqlserver_layers_reopen_without_secrets() {
    let mut s = Session::new(Project::default());
    let mut src: rustgis_map::source::SourceLayer = serde_json::from_value(json!({
        "sqlserver": {"database": "mssql://me@127.0.0.1:1/gis?encrypt=false", "table": "roads", "family": "Lines"}
    }))
    .unwrap();
    let e = src.open().unwrap_err();
    assert!(e.contains("connect again with Home › Add › Add Data › Database"), "{e}");
    assert!(!src.is_open());
    let saved = serde_json::to_string(&src).unwrap();
    assert!(saved.contains("\"sqlserver\":{") && saved.contains("\"table\":\"roads\"") && !saved.contains("password"), "{saved}");
    let before = s.map().layers.len();
    let e = s.run("layer.addDatabase", &json!({"database": "mssql://me:s3cret@127.0.0.1:1/gis", "password": "pw"})).unwrap_err();
    assert!(e.starts_with("gis: ") && !e.contains("s3cret") && !e.contains("pw"), "{e}");
    let e = s.run("layer.addDatabase", &json!({"database": "mssql://h:port/gis"})).unwrap_err();
    assert!(e.contains("port 'port'"), "{e}");
    let e = s.run("layer.addSql", &json!({"sql": "SELECT 1", "database": "mssql://h/gis"})).unwrap_err();
    assert!(e.contains("SQL Server"), "{e}");
    #[cfg(not(windows))]
    {
        let e = s.run("info.databaseTables", &json!({"database": "mssql://127.0.0.1:1/gis"})).unwrap_err();
        assert!(e.contains("give a SQL Server login"), "{e}");
    }
    assert_eq!(s.map().layers.len(), before);
}

