#[cfg(not(target_arch = "wasm32"))]
#[test]
fn geopackage_saved_defaults_and_trigger_values_become_baseline() {
    use rustgis_data::source::{Request, open_path};
    use rustgis_data::{Coord, Geometry, Value};

    let fixture = GpkgRegressionFixture::new("stored-values");
    let db = rusqlite::Connection::open(fixture.path()).unwrap();
    let mut s = fixture.session();
    let p = json!({"layer": "R"});
    let add = |name: &str| json!({"layer": "R", "geometry": {"type": "Point", "coordinates": [10, 20]}, "attributes": {"name": name}});
    let row_of = |s: &Session, key: u64| s.map().layer_by_name("R").unwrap().dataset.features.iter().position(|f| f.id == key).unwrap();
    let lanes_of = |s: &Session, key: u64| {
        let dataset = &s.map().layer_by_name("R").unwrap().dataset;
        dataset.value(row_of(s, key), dataset.field_index("lanes").unwrap()).clone()
    };
    let name_of = |s: &Session, key: u64| {
        let dataset = &s.map().layer_by_name("R").unwrap().dataset;
        dataset.value(row_of(s, key), dataset.field_index("name").unwrap()).clone()
    };
    let geometry_of = |s: &Session, key: u64| s.map().layer_by_name("R").unwrap().dataset.features[row_of(s, key)].geometry.clone();
    let stored_lanes = |key: u64| -> i64 { db.query_row("SELECT lanes FROM roads WHERE fid = ?1", [key as i64], |r| r.get(0)).unwrap() };

    s.run("edit.addFeature", &add("default")).unwrap();
    let saved = s.run("gpkg.saveEdits", &p).unwrap();
    let default_key = saved["keys"][0].as_u64().unwrap();
    assert_eq!(lanes_of(&s, default_key), Value::Int(2), "omitted attributes must reflect SQLite defaults after saving");
    assert_eq!(stored_lanes(default_key), 2);
    assert_gpkg_regression_clean(&mut s);
    let row = row_of(&s, default_key);
    s.run("edit.setValue", &json!({"layer": "R", "row": row, "field": "name", "value": "default renamed"})).unwrap();
    assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["updated"], 1);
    assert_eq!(stored_lanes(default_key), 2, "a later name edit must not replace the stored default with NULL");
    assert_gpkg_regression_clean(&mut s);

    db.execute_batch("CREATE TABLE normalized_shapes (kind TEXT PRIMARY KEY, geom BLOB);").unwrap();
    for (kind, x, y) in [("insert", 30.0, 40.0), ("update", 31.0, 41.0)] {
        db.execute("INSERT INTO normalized_shapes VALUES (?1, ?2)", rusqlite::params![kind, GpkgRegressionFixture::point_blob(x, y)])
            .unwrap();
    }
    db.execute_batch(
        "CREATE TRIGGER normalize_insert AFTER INSERT ON roads BEGIN
             UPDATE roads SET name = upper(trim(NEW.name)), lanes = 7,
                 geom = (SELECT geom FROM normalized_shapes WHERE kind = 'insert') WHERE fid = NEW.fid;
         END;
         CREATE TRIGGER normalize_update AFTER UPDATE OF name ON roads
             WHEN NEW.name != upper(trim(NEW.name)) BEGIN
             UPDATE roads SET name = upper(trim(NEW.name)), lanes = NEW.lanes + 1,
                 geom = (SELECT geom FROM normalized_shapes WHERE kind = 'update') WHERE fid = NEW.fid;
         END;",
    )
    .unwrap();
    s.run("edit.addFeature", &add(" inserted ")).unwrap();
    let key = s.run("gpkg.saveEdits", &p).unwrap()["keys"][0].as_u64().unwrap();
    assert_eq!(name_of(&s, key), Value::Text("INSERTED".into()));
    assert_eq!(lanes_of(&s, key), Value::Int(7));
    assert_eq!(geometry_of(&s, key), Some(Geometry::Point(Coord::new(30.0, 40.0))));
    assert_gpkg_regression_clean(&mut s);

    let row = row_of(&s, key);
    s.run("edit.setValue", &json!({"layer": "R", "row": row, "field": "name", "value": " updated "})).unwrap();
    assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["updated"], 1);
    assert_eq!(name_of(&s, key), Value::Text("UPDATED".into()));
    assert_eq!(lanes_of(&s, key), Value::Int(8));
    assert_eq!(geometry_of(&s, key), Some(Geometry::Point(Coord::new(31.0, 41.0))));
    assert_gpkg_regression_clean(&mut s);

    let row = row_of(&s, key);
    s.run("edit.setValue", &json!({"layer": "R", "row": row, "field": "name", "value": "NEXT"})).unwrap();
    assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["updated"], 1);
    let stored: (String, i64) =
        db.query_row("SELECT name, lanes FROM roads WHERE fid = ?1", [key as i64], |r| Ok((r.get(0)?, r.get(1)?))).unwrap();
    assert_eq!(stored, ("NEXT".into(), 8), "an ordinary later edit must retain trigger-normalized attributes");
    let batch = open_path(&fixture.path(), Some("roads")).unwrap().read(&Request::all()).unwrap();
    assert_eq!(
        batch.features.iter().find(|f| f.id == key).unwrap().geometry,
        Some(Geometry::Point(Coord::new(31.0, 41.0))),
        "an ordinary later edit must retain trigger-normalized geometry",
    );
    assert_gpkg_regression_clean(&mut s);
    assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["saved"], false);
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn geopackage_insert_reserves_externally_deleted_loaded_keys() {
    use rustgis_data::Value;

    let fixture = GpkgRegressionFixture::new("reserved-keys");
    let db = rusqlite::Connection::open(fixture.path()).unwrap();
    let mut s = fixture.session();
    let p = json!({"layer": "R"});
    db.execute("DELETE FROM roads WHERE fid = 3", []).unwrap();
    s.run("edit.addFeature", &json!({"layer": "R", "geometry": {"type": "Point", "coordinates": [10, 20]}, "attributes": {"name": "new"}}))
        .unwrap();
    let saved = s.run("gpkg.saveEdits", &p).unwrap();
    let key = saved["keys"][0].as_u64().unwrap();
    assert!(key > 3, "a newly committed row must not alias the externally deleted loaded key: {saved}");
    {
        let dataset = &s.map().layer_by_name("R").unwrap().dataset;
        assert_eq!(dataset.features.len(), 4);
        let ids: std::collections::HashSet<_> = dataset.features.iter().map(|f| f.id).collect();
        assert_eq!(ids.len(), 4, "the unchanged stale feature and inserted feature must remain distinguishable");
        let name = dataset.field_index("name").unwrap();
        assert_eq!(dataset.features.iter().find(|f| f.id == 3).unwrap().attrs[name], Value::Text("c".into()));
        assert_eq!(dataset.features.iter().find(|f| f.id == key).unwrap().attrs[name], Value::Text("new".into()));
    }
    assert_gpkg_regression_clean(&mut s);
    for _ in 0..2 {
        assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["saved"], false, "saving again must not insert a phantom duplicate");
    }
    let rows: Vec<(i64, String)> = db
        .prepare("SELECT fid, name FROM roads ORDER BY fid")
        .unwrap()
        .query_map([], |r| Ok((r.get(0)?, r.get(1)?)))
        .unwrap()
        .collect::<Result<_, _>>()
        .unwrap();
    assert_eq!(rows, vec![(1, "a".into()), (2, "b".into()), (key as i64, "new".into())]);
    assert_eq!(s.run("gpkg.discardEdits", &p).unwrap()["features"], 3);
    let features = &s.map().layer_by_name("R").unwrap().dataset.features;
    assert!(!features.iter().any(|f| f.id == 3));
    assert!(features.iter().any(|f| f.id == key));
    assert_gpkg_regression_clean(&mut s);
}

/// The declaration is compared with the one loaded, not with a table reopened just before saving.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn geopackage_command_save_refuses_a_declaration_changed_since_loading() {
    for (mutation, label) in [
        ("UPDATE gpkg_geometry_columns SET geometry_type_name = 'MULTIPOINT'", "type"),
        ("UPDATE gpkg_geometry_columns SET z = 1", "z"),
        ("UPDATE gpkg_geometry_columns SET m = 1", "m"),
    ] {
        let fixture = GpkgRegressionFixture::new(&format!("declaration-{label}"));
        let db = rusqlite::Connection::open(fixture.path()).unwrap();
        let name_of = || -> String { db.query_row("SELECT name FROM roads WHERE fid = 1", [], |r| r.get(0)).unwrap() };
        let mut s = fixture.session();
        let p = json!({"layer": "R"});
        db.execute(mutation, []).unwrap();
        s.run("edit.setValue", &json!({"layer": "R", "row": 0, "field": "name", "value": "must not save"})).unwrap();
        let e = s.run("gpkg.saveEdits", &p).unwrap_err();
        assert!(e.contains("changed shape"), "{label}: {e}");
        assert_eq!(name_of(), "a", "{label}");
        // Discard reloads the current declaration, after which attribute saves work again.
        s.run("gpkg.discardEdits", &p).unwrap();
        s.run("edit.setValue", &json!({"layer": "R", "row": 0, "field": "name", "value": "after reload"})).unwrap();
        assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["updated"], 1, "{label}");
        assert_eq!(name_of(), "after reload", "{label}");
    }
}

/// Reopened projects keep exact coordinates (no edits appear, nothing is rewritten), and the
/// globe locator's simplified sketches can't be saved over the source.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn geopackage_reopened_polygons_stay_clean_and_locator_sketches_are_unbound() {
    use rustgis_data::raster::Crs;
    use rustgis_data::source::gpkg;
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value};

    let fixture = GpkgRegressionFixture::new("locator-sketch");
    let path = fixture.dir.join("parcels.gpkg");
    let mut data = Dataset::new("parcels", GeometryType::Polygon, vec![Field::new("name", FieldType::Text)]);
    for k in 1..=3 {
        let centre = 10.0 * f64::from(k);
        // Many irregular vertices: coordinates whose shortest decimal form needs exact parsing.
        let ring = (0..=64)
            .map(|i| {
                let j = i % 64;
                let a = std::f64::consts::TAU * f64::from(j) / 64.0;
                Coord::new(centre + 5.0 * a.cos() + 0.01 * f64::from(j % 3), centre + 5.0 * a.sin())
            })
            .collect();
        data.push(Some(Geometry::Polygon(vec![vec![ring]])), vec![Value::Text(format!("p{k}"))]);
    }
    gpkg::write_in(&data, &path, Crs::LonLat).unwrap();
    let db = rusqlite::Connection::open(&path).unwrap();
    let blobs = || -> Vec<Vec<u8>> {
        db.prepare("SELECT geom FROM parcels ORDER BY fid").unwrap().query_map([], |r| r.get(0)).unwrap().collect::<Result<_, _>>().unwrap()
    };
    let before = blobs();
    let mut s = Session::new(Project::default());
    s.run("gpkg.addLayer", &json!({"path": path, "table": "parcels", "name": "P"})).unwrap();
    let project = fixture.dir.join("parcels.rgis");
    s.run("project.saveAs", &json!({"path": project})).unwrap();

    let mut s = Session::new(Project::default());
    s.run("project.open", &json!({"path": project})).unwrap();
    s.map_mut().editing.settings.enabled = true;
    let p = json!({"layer": "P"});
    let pending = s.run("gpkg.pendingEdits", &p).unwrap();
    assert_eq!((pending["inserts"].as_u64(), pending["updates"].as_u64(), pending["deletes"].as_u64()), (Some(0), Some(0), Some(0)));
    assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["saved"], false);
    assert_eq!(blobs(), before, "reopening a project must not rewrite untouched rows");

    let locator = s.run("layout.publication", &json!({"locator": "globe"})).unwrap()["locator"].as_str().unwrap().to_string();
    let sketch = s.project.maps.iter().find(|m| m.name == locator).unwrap();
    let layer = sketch.layer_by_name("P").unwrap();
    assert!(layer.gpkg.is_none() && layer.postgis.is_none(), "a simplified sketch must not keep the source binding");
    s.run("map.activate", &json!({"name": locator})).unwrap();
    let e = s.run("gpkg.saveEdits", &p).unwrap_err();
    assert!(e.contains("not a GeoPackage layer loaded for editing"), "{e}");
    assert_eq!(blobs(), before);
}

/// A layer bound to both sources (a hand-made project) reserves both baselines' keys.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn geopackage_new_features_avoid_keys_of_either_bound_baseline() {
    let fixture = GpkgRegressionFixture::new("dual-binding");
    let mut s = fixture.session();
    let id = s.map().layer_by_name("R").unwrap().id;
    s.map_mut().layer_mut(id).unwrap().postgis = Some(rustgis_map::source::PostgisEdit {
        origin: rustgis_map::source::PostgisOrigin {
            database: "postgres:host=127.0.0.1 port=1 dbname=gis".into(),
            table: "roads".into(),
            family: None,
            crs: None,
        },
        key: "fid".into(),
        srid: 4326,
        writable: false,
        condition: None,
        limit: 0,
        versions: Default::default(),
    });
    let r3 = s.map().layer(id).unwrap().dataset.features.iter().position(|f| f.id == 3).unwrap();
    s.map_mut().layer_mut(id).unwrap().selection = vec![r3];
    s.active_layer = Some(id);
    s.run("edit.delete", &json!({})).unwrap();
    s.run("edit.addFeature", &json!({"layer": "R", "geometry": {"type": "Point", "coordinates": [10, 20]}})).unwrap();
    let ids: Vec<u64> = s.map().layer(id).unwrap().dataset.features.iter().map(|f| f.id).collect();
    assert!(!ids.contains(&3), "a new feature must not take the GeoPackage key it deleted: {ids:?}");
    assert!(ids.iter().any(|&k| k > 3), "{ids:?}");
}

#[cfg(not(target_arch = "wasm32"))]
#[test]
fn geopackage_discard_refreshes_renamed_key_and_geometry() {
    use rustgis_data::source::{Request, open_path};
    use rustgis_data::{Coord, Geometry};

    let fixture = GpkgRegressionFixture::new("renamed-columns");
    let db = rusqlite::Connection::open(fixture.path()).unwrap();
    let mut s = fixture.session();
    let p = json!({"layer": "R"});
    db.execute_batch(
        "ALTER TABLE roads RENAME COLUMN fid TO id;
         ALTER TABLE roads RENAME COLUMN geom TO shape;
         UPDATE gpkg_geometry_columns SET column_name = 'shape' WHERE table_name = 'roads';",
    )
    .unwrap();
    assert_eq!(s.run("gpkg.discardEdits", &p).unwrap()["features"], 3);
    let layer = s.map().layer_by_name("R").unwrap();
    let binding = layer.gpkg.as_ref().unwrap();
    assert_eq!(binding.key, "id");
    assert_eq!(binding.geometry, "shape");
    let id = layer.id;
    let row = layer.dataset.features.iter().position(|f| f.id == 1).unwrap();
    s.run("edit.setValue", &json!({"layer": "R", "row": row, "field": "name", "value": "renamed columns work"})).unwrap();
    let moved = Geometry::Point(Coord::new(15.0, 25.0));
    {
        let layer = s.map_mut().layer_mut(id).unwrap();
        layer.dataset.features[row].geometry = Some(moved.clone());
        layer.touch_geometry();
    }
    assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["updated"], 1);
    assert_eq!(db.query_row("SELECT name FROM roads WHERE id = 1", [], |r| r.get::<_, String>(0)).unwrap(), "renamed columns work");
    let batch = open_path(&fixture.path(), Some("roads")).unwrap().read(&Request::all()).unwrap();
    assert_eq!(batch.features.iter().find(|f| f.id == 1).unwrap().geometry, Some(moved));
    assert_eq!(batch.features.len(), 3);
    assert_gpkg_regression_clean(&mut s);
    assert_eq!(s.run("gpkg.saveEdits", &p).unwrap()["saved"], false);
}

#[test]
fn raster_tools_read_projected_zone_files_without_reprojecting_twice() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    use rustgis_data::{Dataset, Geometry, GeometryType, Value};
    let dir = std::env::temp_dir().join(format!("rustgis-zonal-crs-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let mut s = Session::new(Project::default());
    let gt = GeoTransform { origin_x: 622_000.0, origin_y: 5_164_000.0, pixel_width: 100.0, pixel_height: -100.0 };
    let tr = Crs::Epsg(25832).transformer().unwrap();
    let mut zones = Dataset::new("zones", GeometryType::Polygon, vec![]);
    let ring = [(1.0, 1.0), (3.0, 1.0), (3.0, 3.0), (1.0, 3.0), (1.0, 1.0)]
        .into_iter()
        .map(|(x, y)| tr.to_lonlat(gt.to_world(x, y)).unwrap())
        .collect();
    zones.push(Some(Geometry::Polygon(vec![vec![ring]])), vec![]);
    s.map_mut().add_layer(rustgis_map::Layer::new(0, zones));
    let nw = tr.to_lonlat(gt.to_world(0.0, 0.0)).unwrap();
    let se = tr.to_lonlat(gt.to_world(4.0, 4.0)).unwrap();
    let geographic = GeoTransform { origin_x: nw.x, origin_y: nw.y, pixel_width: (se.x - nw.x) / 4.0, pixel_height: (se.y - nw.y) / 4.0 };
    for (name, transform, crs) in [("utm", gt, Crs::Epsg(25832)), ("geographic", geographic, Crs::LonLat)] {
        let raster =
            Raster::new(name, 4, 4, vec![(1..=16).map(|v| v as f32).collect()], transform, crs, None, ColorHint::Gray, "Float32").unwrap();
        s.map_mut().add_raster(name, rustgis_map::RasterLayer::from_path(raster, format!("{name}.tif")));
    }
    for epsg in [4326, 25832, 32632, 3003, 3857] {
        for ext in ["gpkg", "shp"] {
            let path = dir.join(format!("zones_{epsg}.{ext}")).display().to_string();
            s.run("share.exportLayer", &json!({"layer": "zones", "path": path, "crs": format!("EPSG:{epsg}")})).unwrap();
            let loaded = s.run("layer.addData", &json!({"path": path, "name": "loaded_zones"})).unwrap()["layer"].clone();
            let input = s.map().layer(loaded.as_u64().unwrap() as u32).unwrap().dataset.clone();
            assert_eq!(input.crs.map(|c| c.label()).unwrap_or_else(|| "EPSG:4326".into()), format!("EPSG:{epsg}"), "{ext}");
            assert!(
                input.lonlat_extent().contains(tr.to_lonlat(gt.to_world(2.0, 2.0)).unwrap()),
                "{epsg}, {ext}: {:?}",
                input.lonlat_extent()
            );
            for raster in ["utm", "geographic"] {
                let depth = s.undo_depth();
                s.run(
                    "gp.run",
                    &json!({"tool": "zonalStats", "params": {"raster": raster, "polygons": "loaded_zones", "output": "stats"}}),
                )
                .unwrap();
                let out = &s.map().layer_by_name("stats").unwrap().dataset;
                for (stat, expected) in [("count", Value::Int(4)), ("mean", Value::Float(8.5)), ("sum", Value::Float(34.0))] {
                    let field = out.field_index(&format!("{raster}_{stat}")).unwrap();
                    assert_eq!(out.value(0, field), &expected, "EPSG:{epsg}, {ext}, {raster}, {stat}");
                }
                // In longitude/latitude, where the tool works (the input is held in its file's system).
                assert_eq!(out.in_lonlat().unwrap().features[0].geometry, input.in_lonlat().unwrap().features[0].geometry);
                assert_eq!(out.crs, input.crs);
                assert_eq!(s.undo_depth(), depth + 1);
                assert!(s.undo());
                assert!(s.map().layer_by_name("stats").is_none());
                assert!(s.redo());
                assert!(s.map().layer_by_name("stats").is_some());
                assert!(s.undo());
                s.run("raster.process", &json!({"layer": raster, "operation": "clip", "polygon": "loaded_zones", "name": "clipped"}))
                    .unwrap();
                let clipped = s.map().layer_by_name("clipped").unwrap().raster.as_ref().unwrap().data.as_ref().unwrap();
                assert_eq!((clipped.width, clipped.height, clipped.bands[0].stats.count), (2, 2, 4), "{epsg}, {ext}, {raster}");
                assert_eq!(clipped.bands[0].data.iter().sum::<f32>(), 34.0, "{epsg}, {ext}, {raster}");
                assert!(s.undo());
            }
            s.run("layer.remove", &json!({"layer": loaded})).unwrap();
        }
    }
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
fn gp_zonal_stats_end_to_end_and_undo() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value};
    use rustgis_geom::Coord;

    let mut s = world();

    let (w, h) = (10u32, 10u32);
    let mut data = Vec::with_capacity((w * h) as usize);
    for row in 0..h {
        for col in 0..w {
            data.push((col * 10 + row) as f32);
        }
    }
    let gt = GeoTransform { origin_x: 0.0, origin_y: 10.0, pixel_width: 1.0, pixel_height: -1.0 };
    let raster = Raster::new("dem", w, h, vec![data], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let raster_layer = rustgis_map::RasterLayer::from_path(raster, "dem.tif");
    s.map_mut().add_raster("dem", raster_layer);

    let mut poly_ds = Dataset::new("districts", GeometryType::Polygon, vec![Field::new("code", FieldType::Text)]);
    let sq = |x0: f64, y0: f64, x1: f64, y1: f64| {
        Geometry::Polygon(vec![vec![vec![
            Coord::new(x0, y0),
            Coord::new(x1, y0),
            Coord::new(x1, y1),
            Coord::new(x0, y1),
            Coord::new(x0, y0),
        ]]])
    };
    poly_ds.push(Some(sq(1.0, 7.0, 3.0, 9.0)), vec![Value::Text("D1".into())]);
    poly_ds.push(Some(sq(50.0, 50.0, 52.0, 52.0)), vec![Value::Text("D2".into())]);
    s.map_mut().add_layer(rustgis_map::Layer::new(0, poly_ds));

    let layers_before = s.map().layers.len();

    let res = s.run(
        "gp.zonalStats",
        &json!({
            "raster": "dem",
            "polygons": "districts",
            "output": "zonal_out",
        }),
    );
    assert!(res.is_ok(), "gp.zonalStats failed: {res:?}");
    assert_eq!(s.map().layers.len(), layers_before + 1);

    let out_layer = s.map().layer_by_name("zonal_out").expect("output layer should exist");
    assert_eq!(out_layer.dataset.features.len(), 2);

    let mean_idx = out_layer.dataset.field_index("dem_mean").expect("dem_mean field");
    let count_idx = out_layer.dataset.field_index("dem_count").expect("dem_count field");
    let min_idx = out_layer.dataset.field_index("dem_min").expect("dem_min field");
    let max_idx = out_layer.dataset.field_index("dem_max").expect("dem_max field");
    let sum_idx = out_layer.dataset.field_index("dem_sum").expect("dem_sum field");
    let stddev_idx = out_layer.dataset.field_index("dem_stddev").expect("dem_stddev field");

    assert_eq!(out_layer.dataset.value(0, 0), &Value::Text("D1".into()));
    assert_eq!(out_layer.dataset.value(0, count_idx), &Value::Int(4));
    assert_eq!(out_layer.dataset.value(0, mean_idx), &Value::Float(16.5));
    assert_eq!(out_layer.dataset.value(0, min_idx), &Value::Float(11.0));
    assert_eq!(out_layer.dataset.value(0, max_idx), &Value::Float(22.0));
    assert_eq!(out_layer.dataset.value(0, sum_idx), &Value::Float(66.0));
    let std = out_layer.dataset.value(0, stddev_idx).as_f64().unwrap();
    assert!((std - 25.25f64.sqrt()).abs() < 1e-10);

    assert_eq!(out_layer.dataset.value(1, 0), &Value::Text("D2".into()));
    assert_eq!(out_layer.dataset.value(1, count_idx), &Value::Int(0));
    assert_eq!(out_layer.dataset.value(1, mean_idx), &Value::Null);
    assert_eq!(out_layer.dataset.value(1, min_idx), &Value::Null);
    assert_eq!(out_layer.dataset.value(1, max_idx), &Value::Null);
    assert_eq!(out_layer.dataset.value(1, sum_idx), &Value::Null);
    assert_eq!(out_layer.dataset.value(1, stddev_idx), &Value::Null);

    assert!(s.undo());
    assert_eq!(s.map().layers.len(), layers_before);
    assert!(s.map().layer_by_name("zonal_out").is_none());

    assert!(s.redo());
    assert_eq!(s.map().layers.len(), layers_before + 1);
    assert!(s.map().layer_by_name("zonal_out").is_some());

    let run_res = s.run(
        "gp.run",
        &json!({
            "tool": "zonalStats",
            "params": {
                "raster": "dem",
                "polygons": "districts",
                "stats": ["mean", "count"],
                "output": "via_gp_run",
            }
        }),
    );
    assert!(run_res.is_ok(), "gp.run with zonalStats failed: {run_res:?}");
    let run_layer = s.map().layer_by_name("via_gp_run").expect("via_gp_run layer should exist");
    assert!(run_layer.dataset.field_index("dem_mean").is_some());
    assert!(run_layer.dataset.field_index("dem_count").is_some());
    assert!(run_layer.dataset.field_index("dem_min").is_none());

    // Loaded WebMercator data already uses longitude/latitude geometry.
    let mut merc_ds = Dataset::new("merc_districts", GeometryType::Polygon, vec![Field::new("code", FieldType::Text)]);
    merc_ds.crs = Some(Crs::WebMercator);
    merc_ds.push(Some(sq(1.0, 7.0, 3.0, 9.0)), vec![Value::Text("M1".into())]);
    s.map_mut().add_layer(rustgis_map::Layer::new(0, merc_ds));

    let merc_res = s.run(
        "gp.zonalStats",
        &json!({
            "raster": "dem",
            "polygons": "merc_districts",
            "output": "merc_out",
            "bands": [1.0],
        }),
    );
    assert!(merc_res.is_ok(), "gp.zonalStats with WebMercator failed: {merc_res:?}");
    let merc_layer = s.map().layer_by_name("merc_out").expect("merc_out should exist");
    assert_eq!(merc_layer.dataset.crs, Some(Crs::WebMercator));
    let m_count_idx = merc_layer.dataset.field_index("dem_count").unwrap();
    let m_mean_idx = merc_layer.dataset.field_index("dem_mean").unwrap();
    assert_eq!(merc_layer.dataset.value(0, m_count_idx), &Value::Int(4));
    assert_eq!(merc_layer.dataset.value(0, m_mean_idx), &Value::Float(16.5));

    let multiband = Raster::new(
        "multi",
        w,
        h,
        vec![vec![2.0; (w * h) as usize], vec![7.0; (w * h) as usize]],
        gt,
        Crs::LonLat,
        None,
        ColorHint::Gray,
        "Float32",
    )
    .unwrap();
    s.map_mut().add_raster("multi", rustgis_map::RasterLayer::from_path(multiband, "multi.tif"));

    // "bands": "all"
    let all_res = s.run(
        "gp.zonalStats",
        &json!({
            "raster": "multi",
            "polygons": "districts",
            "output": "all_bands_out",
            "bands": "all",
        }),
    );
    assert!(all_res.is_ok(), "gp.zonalStats with bands: all failed: {all_res:?}");

    assert!(s.run("gp.zonalStats", &json!({})).is_err());
    assert!(s.run("gp.zonalStats", &json!({"raster": "nonexistent", "polygons": "districts"})).is_err());
    let all_layer = s.map().layer_by_name("all_bands_out").unwrap();
    for (field, expected) in [("multi_b1_mean", 2.0), ("multi_b2_mean", 7.0)] {
        let idx = all_layer.dataset.field_index(field).expect("all bands must be expanded");
        assert_eq!(all_layer.dataset.value(0, idx), &Value::Float(expected));
    }
    let error = s.run("gp.zonalStats", &json!({"raster": "dem", "polygons": "Cities"})).unwrap_err();
    assert!(error.contains("needs polygon geometries"), "{error}");
    for (band, fragment) in [
        (json!(999), "raster has bands"),
        (json!(0), "positive"),
        (json!(-1), "positive"),
        (json!(1.5), "integers"),
        (json!(4294967297u64), "raster has bands"),
    ] {
        let error = s.run("gp.zonalStats", &json!({"raster": "dem", "polygons": "districts", "bands": [band]})).unwrap_err();
        assert!(error.contains(fragment), "{error}");
    }
}

#[test]
fn raster_clip_polygon_selection_semantics_and_partial_failure() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value};
    use rustgis_geom::Coord;

    let mut s = world();

    // 10x10 raster: origin (0.0, 10.0), cell size (1.0, -1.0)
    let (w, h) = (10u32, 10u32);
    let mut data = Vec::with_capacity((w * h) as usize);
    for row in 0..h {
        for col in 0..w {
            data.push((col * 10 + row) as f32);
        }
    }
    let gt = GeoTransform { origin_x: 0.0, origin_y: 10.0, pixel_width: 1.0, pixel_height: -1.0 };
    let raster = Raster::new("dem", w, h, vec![data], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let raster_layer = rustgis_map::RasterLayer::from_path(raster, "dem.tif");
    s.map_mut().add_raster("dem", raster_layer);

    let sq = |x0: f64, y0: f64, x1: f64, y1: f64| {
        Geometry::Polygon(vec![vec![vec![
            Coord::new(x0, y0),
            Coord::new(x1, y0),
            Coord::new(x1, y1),
            Coord::new(x0, y1),
            Coord::new(x0, y0),
        ]]])
    };

    let mut poly_ds = Dataset::new("clip_zones", GeometryType::Polygon, vec![Field::new("name", FieldType::Text)]);
    // Feature 0: [1.0, 7.0] to [3.0, 9.0]
    poly_ds.push(Some(sq(1.0, 7.0, 3.0, 9.0)), vec![Value::Text("Z1".into())]);
    // Feature 1: [2.0, 6.0] to [4.0, 8.0] (overlaps with Z1)
    poly_ds.push(Some(sq(2.0, 6.0, 4.0, 8.0)), vec![Value::Text("Z2".into())]);
    // Feature 2: [6.0, 1.0] to [8.0, 3.0] (separate area)
    poly_ds.push(Some(sq(6.0, 1.0, 8.0, 3.0)), vec![Value::Text("Z3".into())]);
    // Feature 3: Degenerate hole (< 3 coords) -> should trigger rejection of this feature
    let bad_hole_poly = Geometry::Polygon(vec![vec![
        vec![Coord::new(4.0, 4.0), Coord::new(6.0, 4.0), Coord::new(6.0, 6.0), Coord::new(4.0, 6.0), Coord::new(4.0, 4.0)],
        vec![Coord::new(4.5, 4.5), Coord::new(5.0, 5.0)], // invalid hole with only 2 points
    ]]);
    poly_ds.push(Some(bad_hole_poly), vec![Value::Text("Z4_bad".into())]);

    let poly_layer_id = s.map_mut().add_layer(rustgis_map::Layer::new(0, poly_ds));

    // Test 1: selectedOnly: "invalid" or non-boolean returns validation error
    let err_type = s.run(
        "raster.process",
        &json!({
            "layer": "dem",
            "operation": "clip",
            "polygon": "clip_zones",
            "selectedOnly": "yes",
        }),
    );
    assert!(err_type.is_err());
    assert!(err_type.unwrap_err().contains("must be a boolean"));

    // Test 2: selectedOnly: true with empty selection returns error
    let err_empty_sel = s.run(
        "raster.process",
        &json!({
            "layer": "dem",
            "operation": "clip",
            "polygon": "clip_zones",
            "selectedOnly": true,
        }),
    );
    assert!(err_empty_sel.is_err());
    assert!(err_empty_sel.unwrap_err().contains("no features are selected"));

    // Test 3: selectedOnly: true with Feature 0 selected
    {
        let l = s.map_mut().layer_mut(poly_layer_id).unwrap();
        l.selection = vec![0];
    }
    let res_sel = s.run(
        "raster.process",
        &json!({
            "layer": "dem",
            "operation": "clip",
            "polygon": "clip_zones",
            "selectedOnly": true,
            "name": "dem_sel_0",
        }),
    );
    assert!(res_sel.is_ok(), "clip selected failed: {res_sel:?}");
    let sel_layer = s.map().layer_by_name("dem_sel_0").expect("dem_sel_0 exists");
    let sel_raster = sel_layer.raster.as_ref().unwrap().data.as_ref().unwrap();
    // Feature 0 covers x: [1.0, 3.0], y: [7.0, 9.0] -> 2 cols x 2 rows
    assert_eq!(sel_raster.width, 2);
    assert_eq!(sel_raster.height, 2);

    // Test 4: Overlapping polygons combined coverage (Features 0 and 1)
    {
        let l = s.map_mut().layer_mut(poly_layer_id).unwrap();
        l.selection = vec![0, 1];
    }
    let res_overlap = s.run(
        "raster.process",
        &json!({
            "layer": "dem",
            "operation": "clip",
            "polygon": "clip_zones",
            "selectedOnly": true,
            "name": "dem_overlap",
        }),
    );
    assert!(res_overlap.is_ok(), "clip overlap failed: {res_overlap:?}");
    let ov_layer = s.map().layer_by_name("dem_overlap").expect("dem_overlap exists");
    let ov_raster = ov_layer.raster.as_ref().unwrap().data.as_ref().unwrap();
    // Features 0 & 1 union bounding box: x: [1.0, 4.0], y: [6.0, 9.0] -> 3 cols x 3 rows
    assert_eq!(ov_raster.width, 3);
    assert_eq!(ov_raster.height, 3);

    // Test 5: selectedOnly: false ignores active selection and clips using all valid features
    let res_all = s.run(
        "raster.process",
        &json!({
            "layer": "dem",
            "operation": "clip",
            "polygon": "clip_zones",
            "selectedOnly": false,
            "name": "dem_all",
        }),
    );
    assert!(res_all.is_ok(), "clip all failed: {res_all:?}");
    let all_layer = s.map().layer_by_name("dem_all").expect("dem_all exists");
    let all_raster = all_layer.raster.as_ref().unwrap().data.as_ref().unwrap();
    // Features 0, 1, 2 bounding box spans x: [1.0, 8.0], y: [1.0, 9.0] -> 7 cols x 8 rows
    assert_eq!(all_raster.width, 7);
    assert_eq!(all_raster.height, 8);

    // Test 6: Partial failure reporting: Feature 0 (valid) + Feature 3 (invalid hole)
    // Feature 3 should be skipped with a warning, Feature 0 should succeed
    {
        let l = s.map_mut().layer_mut(poly_layer_id).unwrap();
        l.selection = vec![0, 3];
    }
    let res_partial = s.run(
        "raster.process",
        &json!({
            "layer": "dem",
            "operation": "clip",
            "polygon": "clip_zones",
            "selectedOnly": true,
            "name": "dem_partial",
        }),
    );
    let partial_result = res_partial.expect("clip partial should succeed for valid feature");
    let warning = partial_result["messages"][0].as_str().expect("partial failures must be visible in command output");
    assert!(warning.contains("skipped 1 feature(s)"), "{warning}");
    let partial_layer = s.map().layer_by_name("dem_partial").expect("dem_partial exists");
    let partial_raster = partial_layer.raster.as_ref().unwrap().data.as_ref().unwrap();
    assert_eq!(partial_raster.width, 2);
    assert_eq!(partial_raster.height, 2);

    // Test 7: Total failure when all selected features fail validation (only Feature 3 selected)
    {
        let l = s.map_mut().layer_mut(poly_layer_id).unwrap();
        l.selection = vec![3];
    }
    let res_bad = s.run(
        "raster.process",
        &json!({
            "layer": "dem",
            "operation": "clip",
            "polygon": "clip_zones",
            "selectedOnly": true,
            "name": "dem_bad",
        }),
    );
    assert!(res_bad.is_err());
    let err_msg = res_bad.unwrap_err();
    assert!(err_msg.contains("has no valid polygon geometries"));
    assert!(err_msg.contains("feature 4"));
    assert!(err_msg.contains("hole 1 is invalid"));
}

#[test]
fn layer_selection_replaces_toggles_and_extends() {
    let mut s = world();
    let name = |s: &Session, id: u32| s.map().layer(id).map(|l| l.name.clone()).unwrap_or_default();
    let picked = |s: &Session| s.selected_layers().into_iter().map(|id| name(s, id)).collect::<Vec<_>>();
    let id = |s: &Session, n: &str| s.map().layer_by_name(n).map(|l| l.id).unwrap();
    let depth = s.undo_depth();
    s.run("layer.select", &json!({"layer": "Cities"})).unwrap();
    assert_eq!(picked(&s), ["Cities"]);
    // Toggled in, the layer becomes active; toggled out, another of the selection does.
    s.run("layer.select", &json!({"layer": "Lakes", "mode": "toggle"})).unwrap();
    assert_eq!(picked(&s), ["Cities", "Lakes"]);
    assert_eq!(s.active_layer, Some(id(&s, "Lakes")));
    s.run("layer.select", &json!({"layer": "Lakes", "mode": "toggle"})).unwrap();
    assert_eq!(picked(&s), ["Cities"]);
    assert_eq!(s.active_layer, Some(id(&s, "Cities")));
    // Extended by a list; the last of it is active. A plain select starts over.
    s.run("layer.select", &json!({"layer": ["Rivers", "Countries", "Rivers"], "mode": "extend"})).unwrap();
    assert_eq!(picked(&s), ["Cities", "Rivers", "Countries"]);
    assert_eq!(s.active_layer, Some(id(&s, "Countries")));
    s.run("layer.select", &json!({"layer": "Rivers"})).unwrap();
    assert_eq!(picked(&s), ["Rivers"]);
    // Choosing layers is not an undo step. A bad layer, mode or list changes nothing.
    assert_eq!(s.undo_depth(), depth);
    s.run("layer.select", &json!({"layer": ["Cities", "Lakes"]})).unwrap();
    for p in [
        json!({"layer": ["Cities", "Nope"]}),
        json!({"layer": [], "mode": "toggle"}),
        json!({"layer": [null]}),
        json!({"layer": [[1]]}),
        json!({"layer": "Cities", "mode": "sideways"}),
    ] {
        assert!(s.run("layer.select", &p).is_err(), "{p}");
    }
    assert_eq!(picked(&s), ["Cities", "Lakes"]);
    // Setting the active layer on its own (adding data, a removal) leaves the selection behind.
    s.active_layer = Some(id(&s, "Rivers"));
    assert_eq!(picked(&s), ["Rivers"]);
}

#[test]
fn layer_commands_act_on_the_whole_layer_selection() {
    let mut s = world();
    let names = |s: &Session| s.map().layers.iter().map(|l| l.name.clone()).collect::<Vec<_>>();
    assert_eq!(names(&s), ["Cities", "Rivers", "Lakes", "Countries"]);
    // Hidden and shown layers swap to one state: the opposite of the active layer's (the last
    // one listed, Rivers, hidden: all are shown).
    s.run("layer.visibility", &json!({"layer": "Rivers", "visible": false})).unwrap();
    s.run("layer.select", &json!({"layer": ["Countries", "Rivers"]})).unwrap();
    s.run("layer.visibility", &Value::Null).unwrap();
    let shown = |s: &Session, n: &str| s.map().layer_by_name(n).unwrap().visible;
    assert!(shown(&s, "Rivers") && shown(&s, "Countries"));
    s.run("layer.visibility", &json!({"visible": false})).unwrap();
    assert!(!shown(&s, "Rivers") && !shown(&s, "Countries") && shown(&s, "Cities"));
    // To the top and to the bottom, keeping their order, each one undo step.
    s.run("layer.move", &json!({"to": 0})).unwrap();
    assert_eq!(names(&s), ["Rivers", "Countries", "Cities", "Lakes"]);
    s.run("layer.move", &json!({"to": 1e9})).unwrap();
    assert_eq!(names(&s), ["Cities", "Lakes", "Rivers", "Countries"]);
    assert!(s.run("layer.move", &json!({"to": 1})).is_err(), "several layers can't go to the middle");
    // "to" is where the topmost of them lands, as for one layer: 2 of 4 at 2 is the bottom.
    s.run("edit.undo", &Value::Null).unwrap();
    s.run("layer.move", &json!({"to": 2})).unwrap();
    assert_eq!(names(&s), ["Cities", "Lakes", "Rivers", "Countries"]);
    s.run("edit.undo", &Value::Null).unwrap();
    s.run("layer.move", &json!({"to": 3})).unwrap();
    assert_eq!(names(&s), ["Cities", "Lakes", "Rivers", "Countries"]);
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(names(&s), ["Rivers", "Countries", "Cities", "Lakes"]);
    // Selectable on all of them.
    s.run("layer.selectable", &json!({"on": false})).unwrap();
    assert!(!s.map().layer_by_name("Rivers").unwrap().selectable && !s.map().layer_by_name("Countries").unwrap().selectable);
    assert!(s.map().layer_by_name("Cities").unwrap().selectable);
    // Zoom to both: a view command, no undo step.
    let depth = s.undo_depth();
    s.run("layer.zoomTo", &Value::Null).unwrap();
    assert_eq!(s.undo_depth(), depth);
    // Removing: one undo step; the layer that takes the topmost one's place is active alone.
    s.run("layer.remove", &Value::Null).unwrap();
    assert_eq!(names(&s), ["Cities", "Lakes"]);
    assert_eq!(s.undo_depth(), depth + 1);
    assert_eq!(s.selected_layers(), vec![s.active_layer.unwrap()]);
    assert_eq!(s.active_layer, s.map().layer_by_name("Cities").map(|l| l.id));
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(names(&s), ["Rivers", "Countries", "Cities", "Lakes"]);
    // A list with an unknown layer removes nothing.
    assert!(s.run("layer.remove", &json!({"layer": ["Rivers", "Nope"]})).is_err());
    assert_eq!(names(&s).len(), 4);
}

#[test]
fn layer_selection_survives_a_failed_project_open() {
    let mut s = world();
    s.run("layer.select", &json!({"layer": ["Cities", "Lakes"]})).unwrap();
    let before = s.selected_layers();
    // Another project replaces this one and fails: the selection comes back with it.
    let _ = s.run("project.openText", &json!({"text": "not a project"}));
    assert_eq!(s.selected_layers(), before);
}

#[test]
fn several_layers_move_to_the_top_with_one_in_a_group() {
    let mut s = world();
    let names = |s: &Session| s.map().layers.iter().map(|l| l.name.clone()).collect::<Vec<_>>();
    s.run("group.add", &json!({"layers": ["Lakes", "Countries"]})).unwrap();
    assert_eq!(names(&s), ["Cities", "Rivers", "Lakes", "Countries"]);
    s.run("layer.select", &json!({"layer": ["Rivers", "Countries"]})).unwrap();
    // A layer out of a group goes to the map's top; one in a group, to its group's top.
    let depth = s.undo_depth();
    s.run("layer.move", &json!({"to": 0})).unwrap();
    assert_eq!(names(&s), ["Rivers", "Cities", "Countries", "Lakes"]);
    assert_eq!(s.undo_depth(), depth + 1);
    s.run("layer.move", &json!({"to": 1e9})).unwrap();
    assert_eq!(names(&s), ["Cities", "Lakes", "Countries", "Rivers"]);
    let group = |s: &Session, n: &str| s.map().layer_by_name(n).and_then(|l| s.map().group_of(l.id)).map(|g| g.name.clone());
    assert_eq!(group(&s, "Countries").as_deref(), Some("New Group"));
}

#[test]
fn several_layers_go_into_and_out_of_a_group_in_one_step() {
    let mut s = world();
    let group = |s: &Session, n: &str| s.map().layer_by_name(n).and_then(|l| s.map().group_of(l.id)).map(|g| g.name.clone());
    s.run("group.add", &json!({"name": "Water", "layers": ["Lakes"]})).unwrap();
    s.run("layer.select", &json!({"layer": ["Cities", "Rivers"]})).unwrap();
    let depth = s.undo_depth();
    s.run("layer.group", &json!({"group": "Water"})).unwrap();
    assert_eq!(group(&s, "Cities").as_deref(), Some("Water"));
    assert_eq!(group(&s, "Rivers").as_deref(), Some("Water"));
    assert_eq!(s.undo_depth(), depth + 1);
    s.run("layer.group", &json!({"layer": ["Cities", "Rivers"], "group": null})).unwrap();
    assert_eq!(group(&s, "Cities"), None);
    assert_eq!(group(&s, "Rivers"), None);
    assert_eq!(group(&s, "Lakes").as_deref(), Some("Water"));
    // "before" places one layer; an unknown one fails the whole list.
    assert!(s.run("layer.group", &json!({"layer": ["Cities", "Rivers"], "group": "Water", "before": "Lakes"})).is_err());
    assert!(s.run("layer.group", &json!({"layer": ["Cities", "Nope"], "group": "Water"})).is_err());
    assert_eq!(group(&s, "Cities"), None);
}

#[test]
fn another_project_starts_with_no_layer_selection() {
    let mut s = world();
    let text = serde_json::to_string(&s.project).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.openText", &json!({"text": text})).unwrap();
    let opened_active = t.active_layer.and_then(|id| t.map().layer(id)).map(|l| l.name.clone()).unwrap();
    // Picked around the layer the next project starts active on, with the same ids there.
    let other = if opened_active == "Lakes" { "Cities" } else { "Lakes" };
    s.run("layer.select", &json!({"layer": [other, opened_active.as_str()]})).unwrap();
    s.run("project.openText", &json!({"text": text})).unwrap();
    assert!(s.selected_layers().len() <= 1, "{:?}", s.selected_layers());
}

#[test]
fn a_layer_selection_left_behind_stays_gone() {
    let mut s = world();
    let id = |s: &Session, n: &str| s.map().layer_by_name(n).map(|l| l.id).unwrap();
    s.run("layer.select", &json!({"layer": ["Cities", "Lakes"]})).unwrap();
    let lakes = id(&s, "Lakes");
    // Another layer becomes active on its own (as adding data does), then Lakes again.
    s.active_layer = Some(id(&s, "Rivers"));
    s.run("layer.visibility", &json!({"layer": "Rivers", "visible": true})).unwrap();
    s.active_layer = Some(lakes);
    assert_eq!(s.selected_layers(), vec![lakes]);
}

#[test]
fn a_one_layer_list_names_that_layer_not_the_active_one() {
    let mut s = world();
    let group = |s: &Session, n: &str| s.map().layer_by_name(n).and_then(|l| s.map().group_of(l.id)).map(|g| g.name.clone());
    s.run("group.add", &json!({"name": "Water", "layers": ["Lakes"]})).unwrap();
    s.run("layer.select", &json!({"layer": "Rivers"})).unwrap();
    s.run("layer.group", &json!({"layer": ["Cities"], "group": "Water"})).unwrap();
    assert_eq!(group(&s, "Cities").as_deref(), Some("Water"));
    assert_eq!(group(&s, "Rivers"), None);
}

#[test]
fn a_layer_list_needs_no_active_layer() {
    let mut s = world();
    s.active_layer = None;
    s.run("layer.visibility", &json!({"layer": ["Cities", "Rivers"], "visible": false})).unwrap();
    s.run("layer.selectable", &json!({"layer": ["Cities"], "on": false})).unwrap();
    assert!(!s.map().layer_by_name("Rivers").unwrap().visible);
    assert!(!s.map().layer_by_name("Cities").unwrap().selectable);
}

#[test]
fn toggling_out_the_only_picked_layer_leaves_none_active() {
    let mut s = world();
    s.run("layer.select", &json!({"layer": "Cities"})).unwrap();
    s.run("layer.select", &json!({"layer": "Cities", "mode": "toggle"})).unwrap();
    assert_eq!(s.active_layer, None);
    assert!(s.selected_layers().is_empty());
    assert!(s.run("layer.remove", &Value::Null).is_err(), "nothing picked, nothing removed");
}

#[test]
fn a_layout_exports_to_svg_with_each_element_its_own_group() {
    let mut s = world();
    s.run("layout.new", &json!({"page": "a4", "orientation": "landscape"})).unwrap();
    let title = s
        .run("layout.addElement", &json!({"kind": "text", "text": "Cities & rivers <2026>", "x": 20, "y": 10, "w": 150, "h": 15}))
        .unwrap()["element"]
        .as_u64()
        .unwrap();
    s.run("layout.addElement", &json!({"kind": "rectangle", "x": 5, "y": 5, "w": 40, "h": 20})).unwrap();
    let out = std::env::temp_dir().join(format!("rustgis-layout-{}.svg", std::process::id()));
    let mark = s.notice_mark();
    let r = s.run("layout.export", &json!({"path": out.to_string_lossy(), "dpi": 72})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("as pictures, not vectors")), "nothing too large for vectors");
    let svg = std::fs::read_to_string(&out).unwrap();
    let _ = std::fs::remove_file(&out);
    assert_eq!(r["bytes"].as_u64(), Some(svg.len() as u64));
    // A page in millimetres, as the layout is.
    assert!(
        svg.starts_with("<?xml") && svg.contains(r#"width="297mm" height="210mm" viewBox="0 0 297 210""#),
        "{}",
        svg.chars().take(300).collect::<String>()
    );
    let layout = &s.project.layouts[0];
    for e in layout.elements.iter().filter(|e| e.visible) {
        assert!(svg.contains(&format!(r#"<g id="element-{}""#, e.id)), "element {} ({}) has a group", e.id, e.name);
    }
    // Text stays text, escaped; shapes stay shapes; map frames and surrounds are vectors.
    assert!(svg.contains("Cities &amp; rivers &lt;2026&gt;</text>"), "the title is text");
    assert!(svg.contains(&format!(r#"<g id="element-{title}""#)));
    assert!(svg.contains("<rect"), "the rectangle is a shape");
    assert!(svg.contains(r#"<g clip-path="url(#clip"#) && svg.matches("<path ").count() > 50, "the map frame is vectors, cut to the frame");
    assert!(svg.contains("<use xlink:href=\"#glyph"), "its labels and the surrounds' text are glyphs");
    assert!(svg.trim_end().ends_with("</svg>"));
    // SVG exports only the current series page, even when allPages is supplied.
    s.run("layout.series", &json!({"layer": "Lakes", "nameField": "name"})).unwrap();
    s.run("layout.seriesPage", &json!({"page": "next"})).unwrap();
    s.run("layout.update", &json!({"element": title, "text": "Page {page} of {pages}: {pageName}"})).unwrap();
    let before = s.project.layouts[0].clone();
    s.run("layout.export", &json!({"path": out.to_string_lossy(), "dpi": 36, "allPages": true})).unwrap();
    let svg = std::fs::read_to_string(&out).unwrap();
    assert!(svg.contains("Page 2 of "));
    assert_eq!(s.project.layouts[0], before, "export keeps the selected page and frame");
    let _ = std::fs::remove_file(&out);
    // A required map-source failure is reported without leaving an incomplete file.
    let dir = std::env::temp_dir().join(format!("rustgis-svg-failure-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let missing = dir.join("missing.shp");
    let layer_name = s.map().layers[0].name.clone();
    let mut source = rustgis_map::source::SourceLayer::default();
    source.path = Some(missing.display().to_string());
    s.map_mut().layers[0].source = Some(source);
    // Use a world view so the missing layer is visible on the exported page.
    s.run("layout.frameZoom", &json!({"to": "full"})).unwrap();
    let error = s.run("layout.export", &json!({"path": out.to_string_lossy(), "dpi": 36})).unwrap_err();
    for detail in [layer_name.as_str(), missing.to_str().unwrap(), "Repair Data Source"] {
        assert!(error.contains(detail), "missing {detail:?} in {error:?}");
    }
    assert!(!out.exists());
    let _ = std::fs::remove_dir_all(&dir);
}

#[test]
fn manual_breaks_are_the_ones_given() {
    use rustgis_map::{ClassMethod, Renderer};
    let mut s = world();
    let breaks = |s: &Session| match &s.map().layer_by_name("Countries").unwrap().renderer {
        Renderer::Graduated { breaks, method, .. } => (breaks.clone(), *method),
        r => panic!("{r:?}"),
    };
    let l = s.map().layer_by_name("Countries").unwrap();
    let fi = l.dataset.field_index("pop_est").unwrap();
    let max = (0..l.dataset.features.len()).filter_map(|r| l.dataset.value(r, fi).as_f64()).fold(f64::MIN, f64::max);
    let manual = |b: Value| json!({"layer": "Countries", "type": "graduated", "field": "pop_est", "method": "manual", "breaks": b});
    // The bounds as typed; the field's maximum closes the last class, so every country has one.
    s.run("layer.symbology", &manual(json!([1e6, 1e7, 1e8]))).unwrap();
    assert_eq!(breaks(&s), (vec![1e6, 1e7, 1e8, max], ClassMethod::Manual));
    // Out of order or repeated, they come back sorted, once.
    s.run("layer.symbology", &manual(json!([5e7, 1e6, 5e7]))).unwrap();
    assert_eq!(breaks(&s).0, vec![1e6, 5e7, max]);
    // "breaks" alone means manual.
    let mut p = manual(json!([2e7]));
    p.as_object_mut().unwrap().remove("method");
    s.run("layer.symbology", &p).unwrap();
    assert_eq!(breaks(&s), (vec![2e7, max], ClassMethod::Manual));
    // Manual with no bounds keeps the layer's current ones, so switching to it changes nothing.
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "graduated", "field": "pop_est", "method": "quantile", "classes": 4}))
        .unwrap();
    let q = breaks(&s).0;
    s.run("layer.symbology", &json!({"layer": "Countries", "type": "graduated", "field": "pop_est", "method": "manual"})).unwrap();
    assert_eq!(breaks(&s), (q, ClassMethod::Manual));
    // Bounds with a method that works them out are refused rather than ignored.
    let mut p = manual(json!([2e7]));
    p["method"] = json!("quantile");
    assert!(s.run("layer.symbology", &p).is_err());
    // Not numbers, none, or more than twelve classes are refused, and the layer keeps its style.
    for bad in [json!([]), json!(["a lot"]), json!((1..=13).map(|i| i as f64 * 1e6).collect::<Vec<_>>())] {
        let before = breaks(&s);
        assert!(s.run("layer.symbology", &manual(bad.clone())).is_err(), "{bad}");
        assert_eq!(breaks(&s), before);
    }
}

/// Manual classes on a layer read in place (#2497): its features are those of the last view read,
/// so its range is unknown. The first class takes every value up to its bound and one more class
/// every value past the last, whatever the view holds, and the classes are saved with the project.
#[test]
fn manual_breaks_on_a_layer_read_in_place_are_open_at_both_ends() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    use rustgis_map::symbology::{OPEN_ABOVE, OPEN_BELOW};
    use rustgis_map::{ClassMethod, Renderer};
    // Heights 1 to 40 along the equator, each at its own longitude.
    let mut ds = Dataset::new("buildings", GeometryType::Point, vec![Field::new("height", FieldType::Double)]);
    for h in 1..=40 {
        ds.push(Some(Geometry::Point(Coord::new(f64::from(h), 0.0))), vec![V::Float(f64::from(h))]);
    }
    struct Dir(std::path::PathBuf);
    impl Drop for Dir {
        fn drop(&mut self) {
            let _ = std::fs::remove_dir_all(&self.0);
        }
    }
    let nanos = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_nanos());
    let dir = Dir(std::env::temp_dir().join(format!("rustgis-open-classes-{}-{nanos}", std::process::id())));
    std::fs::create_dir_all(&dir.0).unwrap();
    let path = dir.0.join("buildings.fgb");
    rustgis_data::io::write_path(&ds, &path).unwrap();
    let mut s = Session::new(Project::default());
    let id =
        s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true})).unwrap()["layer"].as_u64().unwrap() as u32;
    let layer = |s: &Session| s.map().layer(id).unwrap().clone();
    assert!(layer(&s).is_streamed() && layer(&s).dataset.features.is_empty());
    let classes = |s: &Session| match layer(s).renderer {
        Renderer::Graduated { breaks, min, method, .. } => (breaks, min, method),
        r => panic!("{r:?}"),
    };
    let labels = |s: &Session| layer(s).renderer.legend().into_iter().map(|e| e.label).collect::<Vec<_>>();
    let manual = |b: Value| json!({"layer": id, "type": "graduated", "field": "height", "method": "manual", "breaks": b});
    // With no bounds given or kept and no view read yet, the refusal says what to do.
    let refused = s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "manual"}));
    assert_eq!(
        refused.unwrap_err().to_string(),
        "'height' has no values in the view read so far: give manual breaks, or read a view where it has some"
    );
    s.run("layer.symbology", &manual(json!([4, 7, 10, 15, 25]))).unwrap();
    assert_eq!(classes(&s), (vec![4.0, 7.0, 10.0, 15.0, 25.0, OPEN_ABOVE], OPEN_BELOW, ClassMethod::Manual));
    assert_eq!(labels(&s), ["up to 4", "4 – 7", "7 – 10", "10 – 15", "15 – 25", "more than 25"]);
    // A view holding only low heights is read: they set no bound.
    let v = view_of(&mut s, rustgis_geom::Extent::new(0.5, -1.0, 3.5, 1.0));
    crate::render::render_png(s.map_mut(), &v).unwrap();
    let read: Vec<f64> = layer(&s).dataset.features.iter().filter_map(|f| f.attrs.first()?.as_f64()).collect();
    assert!(!read.is_empty() && read.iter().all(|h| *h < 20.0), "{read:?}");
    s.run("layer.symbology", &manual(json!([5, 20]))).unwrap();
    assert_eq!(classes(&s), (vec![5.0, 20.0, OPEN_ABOVE], OPEN_BELOW, ClassMethod::Manual));
    assert_eq!(labels(&s), ["up to 5", "5 – 20", "more than 20"]);
    // Manual with no bounds keeps the current classes, with one open class at the top.
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "manual"})).unwrap();
    assert_eq!(classes(&s).0, [5.0, 20.0, OPEN_ABOVE]);
    // Twelve classes from the view switch to Manual as twelve: the open class takes the place of
    // the bound that closed them at the largest value read.
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "equalInterval", "classes": 12}))
        .unwrap();
    let twelve = classes(&s).0;
    assert_eq!(twelve.len(), 12);
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "manual"})).unwrap();
    let (breaks, min, _) = classes(&s);
    assert_eq!((breaks.len(), breaks.get(..11), breaks.last(), min), (12, twelve.get(..11), Some(&OPEN_ABOVE), OPEN_BELOW));
    // Manual with no bounds to keep starts from the view's classes, open at both ends.
    s.run("layer.symbology", &json!({"layer": id, "type": "single"})).unwrap();
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "manual", "classes": 3})).unwrap();
    let (breaks, min, method) = classes(&s);
    assert_eq!((breaks.len(), breaks.last(), min, method), (3, Some(&OPEN_ABOVE), OPEN_BELOW, ClassMethod::Manual));
    // A label and colour set by hand stay when the classes turn open: each feature keeps its class.
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "equalInterval", "classes": 3}))
        .unwrap();
    s.run("layer.classStyle", &json!({"layer": id, "index": 1, "label": "Tall", "color": "#ff0000"})).unwrap();
    let red = layer(&s).renderer.legend()[1].symbol.fill;
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "manual"})).unwrap();
    assert_eq!((classes(&s).0.last(), labels(&s)[1].as_str()), (Some(&OPEN_ABOVE), "Tall"));
    assert_eq!(layer(&s).renderer.legend()[1].symbol.fill, red);
    // One class stays one, of every value.
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "equalInterval", "classes": 1}))
        .unwrap();
    assert_eq!(classes(&s).0.len(), 1);
    s.run("layer.symbology", &json!({"layer": id, "type": "graduated", "field": "height", "method": "manual"})).unwrap();
    assert_eq!(classes(&s).0, [OPEN_ABOVE]);
    assert_eq!(labels(&s), ["every value"]);
    s.run("layer.symbology", &manual(json!([5, 20]))).unwrap();
    // Saved and opened again, the classes are the same.
    let saved = layer(&s).renderer;
    let project = dir.0.join("open.rgis");
    s.run("project.saveAs", &json!({"path": project.display().to_string()})).unwrap();
    let mut t = Session::new(Project::default());
    t.run("project.open", &json!({"path": project.display().to_string()})).unwrap();
    let opened = t.map().layer_by_name("buildings").unwrap();
    assert!(opened.is_streamed());
    assert_eq!(opened.renderer, saved);
}

/// On a GeoParquet read in place, manual classes close at the field's range from the column
/// statistics, and classes worked out from the view say so (#2497).
#[test]
fn classes_on_a_geoparquet_read_in_place_close_at_its_statistics_and_say_what_comes_from_the_view() {
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    use rustgis_map::Renderer;
    let mut ds = Dataset::new("buildings", GeometryType::Point, vec![Field::new("height", FieldType::Double)]);
    for h in 1..=40 {
        ds.push(Some(Geometry::Point(Coord::new(f64::from(h), 0.0))), vec![V::Float(f64::from(h))]);
    }
    let dir = std::env::temp_dir().join(format!("rustgis-classes-in-view-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("buildings.parquet");
    rustgis_data::io::write_path(&ds, &path).unwrap();
    let mut s = Session::new(Project::default());
    let id =
        s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true})).unwrap()["layer"].as_u64().unwrap() as u32;
    assert!(s.map().layer(id).unwrap().is_streamed());
    let classes = |s: &Session| match &s.map().layer(id).unwrap().renderer {
        Renderer::Graduated { breaks, min, .. } => (breaks.clone(), *min),
        r => panic!("{r:?}"),
    };
    // What a run said about the view.
    let run = |s: &mut Session, mut p: Value| {
        p["layer"] = json!(id);
        if p.get("field").is_none() {
            p["field"] = json!("height");
        }
        let mark = s.notice_mark();
        s.run("layer.symbology", &p).unwrap();
        s.notices_since(mark).iter().filter(|n| n.text.contains("of the view read so far")).map(|n| n.text.clone()).collect::<Vec<_>>()
    };
    // Manual breaks close at the file's smallest and largest values, before any view is read.
    assert!(run(&mut s, json!({"type": "graduated", "breaks": [4, 7, 10, 15, 25]})).is_empty());
    assert_eq!(classes(&s), (vec![4.0, 7.0, 10.0, 15.0, 25.0, 40.0], 1.0));
    // Kept, they stay as they are; a bound past the largest value is one of its own.
    run(&mut s, json!({"type": "graduated", "method": "manual"}));
    assert_eq!(classes(&s).0, [4.0, 7.0, 10.0, 15.0, 25.0, 40.0]);
    run(&mut s, json!({"type": "graduated", "breaks": [5, 50]}));
    run(&mut s, json!({"type": "graduated", "method": "manual"}));
    assert_eq!(classes(&s).0, [5.0, 50.0]);
    // A view of low heights is read: quantiles and unique values come from it, and say so.
    let v = view_of(&mut s, rustgis_geom::Extent::new(0.5, -1.0, 3.5, 1.0));
    crate::render::render_png(s.map_mut(), &v).unwrap();
    let n = s.map().layer(id).unwrap().dataset.features.len();
    assert!(n > 0 && n < 40, "{n}");
    // One notice: the layer, the count of features read, and where values elsewhere go.
    let says = |said: &[String], then: &str| {
        let [one] = said else { panic!("{said:?}") };
        assert!(one.starts_with("buildings: ") && one.contains(&format!(" {n} features of the view read so far")), "{one}");
        assert!(one.contains(then), "{one}");
    };
    says(&run(&mut s, json!({"type": "graduated", "method": "quantile", "classes": 2})), "first or last class");
    says(&run(&mut s, json!({"type": "unique"})), "<all other values>");
    // Manual from the view's classes: its inner bounds come from the view, its ends from the file.
    run(&mut s, json!({"type": "single"}));
    says(&run(&mut s, json!({"type": "graduated", "method": "manual", "classes": 2})), "file's smallest and largest values");
    let (breaks, min) = classes(&s);
    assert_eq!((breaks.len(), breaks.last(), min), (2, Some(&40.0), 1.0));
    // The field named in another case finds the file's range too; a bound below it keeps the
    // first class open.
    run(&mut s, json!({"type": "graduated", "field": "HEIGHT", "breaks": [0.5, 4]}));
    assert_eq!(classes(&s), (vec![0.5, 4.0, 40.0], rustgis_map::symbology::OPEN_BELOW));
    let _ = std::fs::remove_dir_all(dir);
}

/// On a GeoParquet read in place, with a view of part of the file, a label and colour set by hand
/// on the view's classes stay when Manual closes them at the file's range, and only while the
/// inner bounds stay; the notice of the view is for a view that isn't the whole source (#2497).
#[test]
fn hand_edits_and_the_notice_on_a_geoparquet_read_in_place_follow_the_view() {
    use rustgis_data::source::{Batch, FeatureSource, Request, SourceInfo};
    use rustgis_data::{Coord, Dataset, Field, FieldType, Geometry, GeometryType, Value as V};
    use rustgis_map::source::{PostgisOrigin, SourceLayer};
    // A source that counts its features as told.
    struct Says(SourceInfo);
    impl FeatureSource for Says {
        fn info(&self) -> &SourceInfo {
            &self.0
        }
        fn read(&self, _: &Request) -> rustgis_data::Result<Batch> {
            Ok(Batch::default())
        }
    }
    let mut ds = Dataset::new("buildings", GeometryType::Point, vec![Field::new("height", FieldType::Double)]);
    for h in 1..=40 {
        ds.push(Some(Geometry::Point(Coord::new(f64::from(h), 0.0))), vec![V::Float(f64::from(h))]);
    }
    let dir = std::env::temp_dir().join(format!("rustgis-hand-edits-in-view-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("buildings.parquet");
    rustgis_data::io::write_path(&ds, &path).unwrap();
    let mut s = Session::new(Project::default());
    let id =
        s.run("layer.addData", &json!({"path": path.display().to_string(), "stream": true})).unwrap()["layer"].as_u64().unwrap() as u32;
    let run = |s: &mut Session, mut p: Value| {
        p["layer"] = json!(id);
        p["type"] = json!("graduated");
        p["field"] = json!("height");
        let mark = s.notice_mark();
        s.run("layer.symbology", &p).unwrap();
        s.notices_since(mark).iter().filter(|n| n.text.contains("of the view read so far")).count()
    };
    let red = rustgis_map::Rgba::rgb(255, 0, 0);
    let legend = |s: &Session| s.map().layer(id).unwrap().renderer.legend();
    let kept = |s: &Session| {
        legend(s).iter().enumerate().filter(|(_, c)| c.label == "Tall" || c.symbol.fill == red).map(|(i, _)| i).collect::<Vec<_>>()
    };
    // Both edits, on the class they were made on.
    let both = |s: &Session| legend(s)[1].label == "Tall" && legend(s)[1].symbol.fill == red;
    // Part of the file: three classes of the view's, the middle one edited by hand.
    let edited = |s: &mut Session| {
        run(s, json!({"type": "graduated", "breaks": [99]}));
        assert_eq!(run(s, json!({"method": "equalInterval", "classes": 3})), 1);
        s.run("layer.classStyle", &json!({"layer": id, "index": 1, "label": "Tall", "color": "#ff0000"})).unwrap();
        assert_eq!(kept(s), [1]);
        match &s.map().layer(id).unwrap().renderer {
            rustgis_map::Renderer::Graduated { breaks, .. } => breaks.clone(),
            r => panic!("{r:?}"),
        }
    };
    let v = view_of(&mut s, rustgis_geom::Extent::new(0.5, -1.0, 3.5, 1.0));
    crate::render::render_png(s.map_mut(), &v).unwrap();
    assert!(s.map().layer(id).unwrap().dataset.features.len() < 40);
    let b = edited(&mut s);
    run(&mut s, json!({"method": "manual"}));
    assert_eq!((kept(&s), both(&s), legend(&s)[2].label.ends_with("40")), (vec![1], true, true));
    // The same inner bounds, typed.
    edited(&mut s);
    run(&mut s, json!({"breaks": [b[0], b[1]]}));
    assert_eq!((kept(&s), both(&s)), (vec![1], true));
    // Other inner bounds, one fewer, one more, or a closing bound of one's own: none is kept.
    for other in [vec![b[0], b[1] + 1.0], vec![b[0]], vec![b[0], b[1], b[2]], vec![b[0], b[1], 50.0]] {
        edited(&mut s);
        run(&mut s, json!({"breaks": other}));
        assert!(kept(&s).is_empty(), "{other:?}: {:?}", kept(&s));
    }
    // Nor those of a class past the file's largest value, once its bound is taken out.
    run(&mut s, json!({"breaks": [5, 50]}));
    s.run("layer.classStyle", &json!({"layer": id, "index": 1, "label": "Tall", "color": "#ff0000"})).unwrap();
    run(&mut s, json!({"breaks": [5]}));
    assert!(kept(&s).is_empty());
    // Open classes a project saved before they closed at the file's range keep theirs too.
    edited(&mut s);
    let l = s.map_mut().layer_mut(id).unwrap();
    l.renderer = l.renderer.opened().unwrap();
    run(&mut s, json!({"method": "manual"}));
    assert_eq!((kept(&s), both(&s), legend(&s)[2].label.ends_with("40")), (vec![1], true, true));
    // Nor when the classes are worked out again from another view.
    edited(&mut s);
    let v = view_of(&mut s, rustgis_geom::Extent::new(-5.0, -5.0, 45.0, 5.0));
    crate::render::render_png(s.map_mut(), &v).unwrap();
    let l = s.map().layer(id).unwrap();
    assert_eq!((l.dataset.features.len(), l.feature_count()), (40, Some(40)));
    // The view now holds the whole source: nothing to say.
    let classes = json!({"method": "equalInterval", "classes": 3});
    assert_eq!(run(&mut s, classes.clone()), 0);
    assert!(kept(&s).is_empty());
    // The same 40 features of a source that doesn't count them, counts more, or whose count can
    // be an estimate (a database's): the notice stays.
    let source = s.map().layer(id).unwrap().source.as_ref().unwrap();
    let info = source.info().unwrap().clone();
    let says = |count| Box::new(Says(SourceInfo { count, ..info.clone() }));
    let origin = PostgisOrigin { database: "postgres:host=h".into(), table: "t".into(), family: None, crs: None };
    for (source, said) in [
        (SourceLayer::from_path("b.parquet", None, says(None)), 1),
        (SourceLayer::from_path("b.parquet", None, says(Some(41))), 1),
        (SourceLayer::from_postgis(origin, says(Some(40))), 1),
        (SourceLayer::from_path("b.parquet", None, says(Some(40))), 0),
    ] {
        s.map_mut().layer_mut(id).unwrap().source = Some(source);
        assert_eq!(run(&mut s, classes.clone()), said);
    }
    let _ = std::fs::remove_dir_all(dir);
}

/// Raster-side projection failures retain good multipart coverage and reach both command results.
#[test]
fn raster_projection_failures_are_reported_for_zonal_statistics_and_clipping() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    use rustgis_data::{Dataset, Geometry, GeometryType};
    use rustgis_geom::Coord;

    let mut s = world();
    let gt = GeoTransform { origin_x: 500_000.0, origin_y: 4_500_000.0, pixel_width: 1_000.0, pixel_height: -1_000.0 };
    let raster = Raster::new("utm", 10, 10, vec![vec![7.0; 100]], gt, Crs::Epsg(32617), None, ColorHint::Gray, "Float32").unwrap();
    let ring: Vec<_> = [(1.0, 1.0), (9.0, 1.0), (9.0, 9.0), (1.0, 9.0)]
        .into_iter()
        .map(|(x, y)| raster.transformer().to_lonlat(gt.to_world(x, y)).unwrap())
        .collect();
    let invalid = vec![Coord::new(-81.0, 100.0), Coord::new(-80.0, 100.0), Coord::new(-80.0, 101.0)];
    assert!(raster.transformer().from_lonlat(invalid[0]).is_none());
    s.map_mut().add_raster("utm", rustgis_map::RasterLayer::from_path(raster, "utm.tif"));
    let mut zones = Dataset::new("parts", GeometryType::Polygon, vec![]);
    zones.push(Some(Geometry::Polygon(vec![vec![ring], vec![invalid]])), vec![]);
    s.map_mut().add_layer(rustgis_map::Layer::new(0, zones));

    s.run("gp.zonalStats", &json!({"raster": "utm", "polygons": "parts", "output": "stats"})).unwrap();
    let messages = &s.project.gp_history.last().unwrap().messages;
    assert!(messages.iter().any(|message| message.contains("1 polygon part(s) could not be projected")), "{messages:?}");
    let out = &s.map().layer_by_name("stats").unwrap().dataset;
    assert_eq!(out.value(0, out.field_index("utm_count").unwrap()), &rustgis_data::Value::Int(64));
    assert_eq!(out.value(0, out.field_index("utm_mean").unwrap()), &rustgis_data::Value::Float(7.0));

    let clip = s.run("raster.process", &json!({"layer": "utm", "operation": "clip", "polygon": "parts", "name": "clipped"})).unwrap();
    assert!(clip["messages"].to_string().contains("skipped 1 polygon part(s)"), "{clip}");
    let data = s.map().layer_by_name("clipped").unwrap().raster.as_ref().unwrap().data.as_ref().unwrap();
    assert_eq!((data.width, data.height), (8, 8));
}

#[test]
fn simplify_large_tolerances_keep_a_small_polygon_and_one_step_undo() {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value};
    use rustgis_geom::Coord;
    let mut s = world();
    let ring = (0..=40)
        .map(|i| {
            let angle = (i % 40) as f64 * std::f64::consts::TAU / 40.0;
            Coord::new(10.5 + 0.05 * angle.cos(), 46.5 + 0.05 * angle.sin())
        })
        .collect();
    let mut zones = Dataset::new("zones", GeometryType::Polygon, vec![Field::new("code", FieldType::Text)]);
    zones.push(Some(Geometry::Polygon(vec![vec![ring]])), vec![Value::Text("Z1".into())]);
    s.map_mut().add_layer(rustgis_map::Layer::new(0, zones.clone()));
    let mut previous = zones.features[0].geometry.as_ref().unwrap().coord_count();
    for tolerance in [0.1, 0.5, 1.0, 2.0, 5.0, 25.0, 100.0] {
        let depth = s.undo_depth();
        s.run("gp.run", &json!({"tool":"simplify", "params":{"input":"zones", "tolerance":tolerance, "output":"simple"}})).unwrap();
        let out = &s.map().layer_by_name("simple").unwrap().dataset;
        assert_eq!(out.features.len(), 1);
        assert_eq!(out.features[0].attrs, zones.features[0].attrs);
        let count = out.features[0].geometry.as_ref().unwrap().coord_count();
        assert!((4..=previous).contains(&count), "{tolerance} km: {count} > {previous}");
        previous = count;
        assert_eq!(s.map().layer_by_name("zones").unwrap().dataset, zones);
        assert_eq!(s.undo_depth(), depth + 1);
        assert!(s.undo());
        assert!(s.map().layer_by_name("simple").is_none());
        assert!(s.redo());
        assert_eq!(s.map().layer_by_name("simple").unwrap().dataset.features[0].geometry.as_ref().unwrap().coord_count(), count);
        assert!(s.undo());
    }
    assert_eq!(previous, 4);
}

#[test]
fn publication_locator_keeps_small_islands_across_the_antimeridian() {
    use rustgis_data::{Dataset, Geometry, GeometryType};
    use rustgis_geom::Coord;
    for (lon, lat) in [(0.0_f64, -5.0), (180.0, -5.0), (-180.0, 70.0)] {
        let mut s = world();
        let ring: Vec<_> = [(-0.0005, 0.0), (0.0005, 0.0), (0.0005, 0.001), (-0.0005, 0.001), (-0.0005, 0.0)]
            .into_iter()
            .map(|(x, y)| Coord::new((lon + x + 180.0).rem_euclid(360.0) - 180.0, lat + y))
            .collect();
        let original = Geometry::Polygon(vec![vec![ring]]);
        let mut island = Dataset::new("island", GeometryType::Polygon, vec![]);
        island.push(Some(original.clone()), vec![]);
        s.map_mut().add_layer(rustgis_map::Layer::new(0, island));
        let r = s.run("layout.publication", &json!({"extent": [-46.8, -11.6, -38.5, -2.2]})).unwrap();
        let locator = s.project.maps.iter().find(|m| Some(m.name.as_str()) == r["locator"].as_str()).unwrap();
        let geometry = &locator.layer_by_name("island").unwrap().dataset.features[0].geometry;
        assert_eq!(geometry.as_ref(), Some(&original), "island at {lon}, {lat}");
    }
}

#[test]
fn calculate_geometry_updates_ellipsoidal_lengths_in_one_undo_step() {
    use rustgis_data::{Dataset, Field, FieldType, Geometry, GeometryType, Value};
    use rustgis_geom::Coord;
    let mut s = world();
    let mut routes = Dataset::new("routes", GeometryType::Polyline, vec![Field::new("code", FieldType::Text)]);
    routes.push(Some(Geometry::Line(vec![vec![Coord::new(0.0, 0.0), Coord::new(1.0, 0.0)]])), vec![Value::Text("R1".into())]);
    s.map_mut().add_layer(rustgis_map::Layer::new(0, routes.clone()));
    let depth = s.undo_depth();
    s.run("gp.run", &json!({"tool":"calculateGeometry", "params":{"input":"routes"}})).unwrap();
    let out = &s.map().layer_by_name("routes").unwrap().dataset;
    let length = out.field_index("length_km").unwrap();
    assert!((out.value(0, length).as_f64().unwrap() - 111.31949079327356).abs() < 1e-6);
    assert_eq!(out.features[0].geometry, routes.features[0].geometry);
    assert_eq!(out.value(0, 0), &Value::Text("R1".into()));
    assert_eq!(s.undo_depth(), depth + 1);
    assert!(s.undo());
    assert_eq!(s.map().layer_by_name("routes").unwrap().dataset, routes);
    assert!(s.redo());
    let out = &s.map().layer_by_name("routes").unwrap().dataset;
    assert!((out.value(0, length).as_f64().unwrap() - 111.31949079327356).abs() < 1e-6);
}

/// Actual reads, including desktop read-ahead and script children, reach exported provenance.
/// Outputs aren't inputs; old projects and exported entries without provenance still load.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn session_log_records_input_fingerprints_and_version() {
    use crate::cmd::reads::{read_ahead, read_land};
    use crate::project_log::LogEntry;
    let dir = std::env::temp_dir().join(format!("rustgis-log-provenance-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("points.csv");
    let contents = b"x,y,name\n1,2,A\n";
    std::fs::write(&path, contents).unwrap();
    let params = json!({"path": path, "x": "x", "y": "y"});
    let mut s = world();
    s.run("layer.addData", &params).unwrap();
    let entry = s.log.entries().last().unwrap();
    assert_eq!(entry.rustgis_version.as_deref(), Some(env!("CARGO_PKG_VERSION")));
    let input = entry.inputs.iter().find(|f| f.path == path.to_string_lossy() && f.sha256.is_some()).unwrap();
    assert_eq!(input.size, Some(contents.len() as u64));
    assert_eq!(
        input.modified_ns,
        Some(std::fs::metadata(&path).unwrap().modified().unwrap().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos().to_string())
    );
    assert_eq!(input.sha256.as_deref(), Some("219f018d3f821dbd36cfffae3dfea5f6d4c6554b9e9dbf62b90dc0297680ae32"));
    assert_eq!(input.hash_unavailable, None);
    let first = input.clone();
    // The desktop worker's reads belong to the admitted command that consumes them.
    let ahead = read_ahead(&mut s, "layer.addData", &params).unwrap();
    let read = std::thread::spawn(move || ahead.run(&rustgis_analysis::control::Control::new()).unwrap()).join().unwrap();
    read_land(&mut s, read).unwrap();
    assert!(s.log.entries().last().unwrap().inputs.contains(&first));
    // A worker admitted while logging is off must not stat or hash its reads for the log.
    s.log.set_on(false);
    let ahead = read_ahead(&mut s, "layer.addData", &params).unwrap();
    let read = std::thread::spawn(move || ahead.run(&rustgis_analysis::control::Control::new()).unwrap()).join().unwrap();
    assert!(read.inputs.is_empty(), "logging off must disable capture on the worker");
    s.log.set_on(true);
    read_land(&mut s, read).unwrap();
    assert!(s.log.entries().last().unwrap().inputs.is_empty());
    // A nested command contributes to its enclosing script's single entry.
    s.run("script.run", &json!({"script": format!("layer.addData {params}")})).unwrap();
    assert!(s.log.entries().last().unwrap().inputs.contains(&first));
    // Mutating a file of the same size is visible in the recorded hash.
    std::fs::write(&path, b"x,y,name\n1,2,B\n").unwrap();
    s.run("layer.addData", &params).unwrap();
    assert!(s.log.entries().last().unwrap().inputs.iter().any(|f| f.path == first.path && f.sha256.is_some() && f.sha256 != first.sha256));
    // A WAL can hold newer input even when the database file's metadata hasn't changed.
    let gpkg = dir.join("points.gpkg");
    rustgis_data::io::write_path(&s.map().layer_by_name("points").unwrap().dataset, &gpkg).unwrap();
    let db = rusqlite::Connection::open(&gpkg).unwrap();
    db.execute_batch("PRAGMA journal_mode=WAL; CREATE TABLE log_probe (id INTEGER);").unwrap();
    s.run("layer.addData", &json!({"path": gpkg})).unwrap();
    let wal = format!("{}-wal", gpkg.display());
    assert!(s.log.entries().last().unwrap().inputs.iter().any(|f| f.path == wal && f.size.is_some() && f.hash_unavailable.is_some()));
    drop(db);
    let out = dir.join("log.jsonl");
    s.run("project.exportLog", &json!({"path": out})).unwrap();
    let entries: Vec<LogEntry> = std::fs::read_to_string(&out).unwrap().lines().map(|l| serde_json::from_str(l).unwrap()).collect();
    assert!(entries.iter().any(|e| e.inputs.contains(&first) && e.rustgis_version.is_some()));
    assert!(s.log.entries().last().unwrap().inputs.is_empty(), "export destination isn't a read");
    let old: LogEntry = serde_json::from_value(json!({"at": 1, "command": "layer.addData", "ok": true})).unwrap();
    assert!(old.inputs.is_empty() && old.rustgis_version.is_none() && old.inputs_omitted == 0);
    s.run("project.openText", &json!({"text": include_str!("../../../schema/fixtures/empty.rgis")})).unwrap();
    assert!(s.project.maps.iter().all(|m| m.layers.is_empty()));
    std::fs::remove_dir_all(dir).unwrap();
}

/// Reopening a replaced output is not an input read; the export worker's true source still is.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn session_log_export_inputs_exclude_output_reloads() {
    use crate::cmd::exports::{export_land, export_start};
    let dir = std::env::temp_dir().join(format!("rustgis-log-exports-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("source.gpkg");
    let mut s = world();
    s.run("share.exportLayer", &json!({"layer": "Cities", "path": path})).unwrap();
    s.run("layer.addData", &json!({"path": path, "layer": "Cities", "stream": true, "name": "InPlace"})).unwrap();
    let copy = dir.join("copy.gpkg");
    let work = export_start(&mut s, "share.exportLayer", &json!({"layer": "InPlace", "path": copy})).unwrap();
    let started = work.started();
    let done = std::thread::spawn(move || work.run(&rustgis_analysis::control::Control::new())).join().unwrap();
    export_land(&mut s, started, done).unwrap();
    let inputs = &s.log.entries().last().unwrap().inputs;
    assert!(inputs.iter().any(|i| i.path == path.display().to_string()));
    assert!(!inputs.iter().any(|i| i.path == copy.display().to_string()));
    let params = json!({"layer": "Countries", "path": path, "mode": "replaceTable", "tableName": "Cities"});
    s.run("share.exportLayer", &params).unwrap();
    assert!(s.log.entries().last().unwrap().inputs.is_empty());
    let work = export_start(&mut s, "share.exportLayer", &params).unwrap();
    let started = work.started();
    let done = std::thread::spawn(move || work.run(&rustgis_analysis::control::Control::new())).join().unwrap();
    export_land(&mut s, started, done).unwrap();
    assert!(s.log.entries().last().unwrap().inputs.is_empty());
    assert_eq!(
        s.map().layer_by_name("InPlace").unwrap().load_all().unwrap().features.len(),
        s.map().layer_by_name("Countries").unwrap().dataset.features.len()
    );
    drop(s);
    std::fs::remove_dir_all(dir).unwrap();
}

/// DuckDB cache payloads never become inputs, including retained and restored streamed reads.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn session_log_duckdb_inputs_exclude_conversion_cache() {
    use crate::cmd::layer::{add_converted, duckdb_parts};
    use rustgis_data::source::{Family, duckdb};
    let dir = std::env::temp_dir().join(format!("rustgis-log-duckdb-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let database = dir.join("source.duckdb");
    std::fs::write(&database, b"source identity").unwrap();
    let cache = dir.join("generated.parquet");
    let mut s = world();
    rustgis_data::io::write_path(&s.map().layer_by_name("Cities").unwrap().dataset, &cache).unwrap();
    let params = json!({"stream": true});
    let added = s
        .command_epilogue("layer.addSql", &params, |s| {
            let out = duckdb::Output {
                parts: vec![duckdb::Part { path: cache.clone(), family: Family::Points, count: 1, zm_dropped: 0 }],
                skipped: 0,
                other_family: 0,
            };
            let parts = duckdb_parts(s, "Converted", out, |family| rustgis_map::source::DuckdbOrigin {
                sql: Some("SELECT * FROM cities".into()),
                database: Some(database.display().to_string()),
                table: None,
                crs: None,
                family,
            });
            add_converted(s, &params, "the query", &database.display().to_string(), parts)
        })
        .unwrap();
    let inputs = &s.log.entries().last().unwrap().inputs;
    assert_eq!(inputs.len(), 1);
    assert_eq!(inputs[0].path, database.display().to_string());
    // Opening the saved stream's concrete reader also retains the original file identity.
    let text = serde_json::to_string(&s.project).unwrap();
    s.run("project.openText", &json!({"text": text})).unwrap();
    s.run("layer.loadAll", &json!({"layer": added["layer"]})).unwrap();
    let inputs = &s.log.entries().last().unwrap().inputs;
    assert_eq!(inputs.len(), 1);
    assert_eq!(inputs[0].path, database.display().to_string());
    std::fs::remove_dir_all(&dir).unwrap();
}

/// Large input lists stay bounded, including merged entries, and disclose the missing count.
#[test]
fn session_log_bounds_input_fingerprints() {
    use crate::project_log::LOG_LIST_ITEMS;
    use rustgis_data::provenance::{Fingerprint, record};
    let inputs = |from, to| {
        (from..to).map(|i| Fingerprint {
            path: format!("/inputs/{i:04}.csv"),
            size: Some(14),
            modified_ns: Some("123456789".into()),
            sha256: None,
            hash_unavailable: Some("streamed input".into()),
            incomplete: None,
        })
    };
    let mut s = world();
    let mark = s.notice_mark();
    s.command_epilogue("project.rename", &json!({"name": "Clean"}), |_| {
        record(inputs(0, 2));
        Ok(Value::Null)
    })
    .unwrap();
    let clean = s.log.entries().last().unwrap();
    assert_eq!(clean.inputs.len(), 2);
    assert_eq!(clean.inputs_omitted, 0);
    assert!(s.notices_since(mark).is_empty());
    assert!(serde_json::to_value(clean).unwrap().get("inputs_omitted").is_none());
    let total = LOG_LIST_ITEMS + 7;
    s.command_epilogue("project.rename", &json!({"name": "Many"}), |_| {
        record(inputs(0, total));
        Ok(Value::Null)
    })
    .unwrap();
    let entry = s.log.entries().last().unwrap();
    assert_eq!(entry.inputs, inputs(0, LOG_LIST_ITEMS).collect::<Vec<_>>());
    assert_eq!(entry.inputs_omitted, 7);
    assert_eq!(s.notices_since(mark).len(), 1);
    assert!(s.notices_since(mark)[0].text.contains("7 input fingerprints"));
    assert!(!s.notices_since(mark)[0].error);
    let mut jsonl = Vec::new();
    s.log.write(&mut jsonl, false).unwrap();
    let jsonl = String::from_utf8(jsonl).unwrap();
    let exported: crate::project_log::LogEntry = serde_json::from_str(jsonl.lines().last().unwrap()).unwrap();
    assert_eq!(exported.inputs_omitted, 7);
    assert_eq!(exported.inputs, entry.inputs);
    let mut csv = Vec::new();
    s.log.write(&mut csv, true).unwrap();
    let csv = String::from_utf8(csv).unwrap();
    assert!(csv.lines().last().unwrap().ends_with(",7"));
    // A later step reusing two inputs and reading two new ones cannot grow a joined entry.
    let mut next = entry.clone();
    next.inputs = inputs(LOG_LIST_ITEMS - 2, LOG_LIST_ITEMS + 2).collect();
    next.inputs_omitted = 0;
    s.log_entry(next, true);
    let joined = s.log.entries().last().unwrap();
    assert_eq!(joined.inputs.len(), LOG_LIST_ITEMS);
    assert_eq!(joined.inputs_omitted, 9);
    assert_eq!(s.notices_since(mark).len(), 1);
    assert!(s.notices_since(mark)[0].text.contains("9 input fingerprints"));
    let mut unchanged = joined.clone();
    unchanged.inputs.clear();
    unchanged.inputs_omitted = 0;
    s.log_entry(unchanged, true);
    assert_eq!(s.notices_since(mark).len(), 1);
    assert!(s.notices_since(mark)[0].text.contains("9 input fingerprints"));
    s.notices.clear();
    let mut later = s.log.entries().last().unwrap().clone();
    later.inputs = inputs(LOG_LIST_ITEMS, LOG_LIST_ITEMS + 1).collect();
    later.inputs_omitted = 0;
    s.log_entry(later, true);
    assert!(s.notices.is_empty(), "a consumed notice is not repeated per joined step");
    let mut separate = s.log.entries().last().unwrap().clone();
    separate.inputs_omitted = 3;
    s.log_entry(separate, false);
    assert_eq!(s.notices.len(), 1);
    assert!(s.notices[0].text.contains("3 input fingerprints"));
}

/// A mark saying an entry's inputs are incomplete there is kept when the list is cut, so a cut
/// list never looks complete; a list without marks is cut as before (#2639).
#[test]
fn session_log_keeps_incomplete_marks_when_it_cuts_inputs() {
    use crate::project_log::LOG_LIST_ITEMS;
    use rustgis_data::provenance::{Fingerprint, record};
    let file = |i: usize| Fingerprint {
        path: format!("/inputs/{i:04}.csv"),
        size: Some(1),
        modified_ns: None,
        sha256: None,
        hash_unavailable: Some("streamed input".into()),
        incomplete: None,
    };
    let mark = Fingerprint {
        path: "/inputs/zz.gdb".into(),
        size: None,
        modified_ns: None,
        sha256: None,
        hash_unavailable: None,
        incomplete: Some("more than 1000 files; only the first 1000 are named".into()),
    };
    let mut s = world();
    let total = LOG_LIST_ITEMS + 5;
    s.command_epilogue("project.rename", &json!({"name": "Marked"}), |_| {
        record((0..total).map(file).chain([mark.clone()]));
        Ok(Value::Null)
    })
    .unwrap();
    let entry = s.log.entries().last().unwrap();
    assert_eq!(entry.inputs.len(), LOG_LIST_ITEMS);
    assert_eq!(entry.inputs_omitted, 6);
    assert_eq!(entry.inputs.last(), Some(&mark), "the mark, sorted last, survives the cut");
    assert_eq!(entry.inputs.iter().filter(|i| i.incomplete.is_some()).count(), 1);
    let mut jsonl = Vec::new();
    s.log.write(&mut jsonl, false).unwrap();
    assert!(String::from_utf8(jsonl).unwrap().contains(r#""incomplete":"more than 1000 files"#));
    // Without marks, nothing says incomplete.
    s.command_epilogue("project.rename", &json!({"name": "Clean"}), |_| {
        record((0..total).map(file));
        Ok(Value::Null)
    })
    .unwrap();
    let entry = s.log.entries().last().unwrap();
    assert_eq!(entry.inputs, (0..LOG_LIST_ITEMS).map(file).collect::<Vec<_>>());
    assert!(entry.inputs.iter().all(|i| i.incomplete.is_none()));
}

/// The session log (#797): a command run by itself that changes the project, or reaches a file
/// or a service, is logged once (a script's lines inside it), with its outcome; reading isn't.
/// Undo keeps the entries and is logged with the step it took back (not when there is none).
/// Secrets are taken out and large values clipped; the log is capped and kept for the session
/// only, across the projects opened in it; it can be read by filter, written out, cleared and
/// turned off, none of which changes the project.
#[test]
fn the_session_log_records_each_command_run_in_the_session() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::the_session_log_records_each_command_run_in_the_session") {
        return;
    }
    use crate::project_log::{LOG_LIMIT, LOG_PARAMS_BYTES, LOG_PLUGIN_LIMIT, LogEntry};
    let mut s = world();
    // The sample project's making is its first entry: counted from after it.
    assert_eq!(s.log.clear(), 1);
    let commands = |s: &Session| s.log.entries().map(|e| e.command.clone()).collect::<Vec<_>>();
    let last = |s: &Session| s.log.entries().last().cloned().unwrap();
    s.run("project.rename", &json!({"name": "Atlas"})).unwrap();
    s.run("info.project", &Value::Null).unwrap();
    s.run("map.zoomIn", &Value::Null).unwrap();
    s.run("script.run", &json!({"script": "project.rename {\"name\": \"A\"}\nproject.rename {\"name\": \"B\"}"})).unwrap();
    assert_eq!(commands(&s), ["project.rename", "script.run"], "reading and moving the view aren't logged, nor a script's lines");
    let first = s.log.entries().next().cloned().unwrap();
    assert!(first.ok && first.error.is_none() && first.at > 1_700_000_000_000, "{first:?}");
    assert_eq!(first.params, json!({"name": "Atlas"}));
    // Undone: the entries stay, and the undo says what it took back.
    s.run("edit.undo", &Value::Null).unwrap();
    assert_eq!(s.project.name, "Atlas");
    assert_eq!(commands(&s), ["project.rename", "script.run", "edit.undo"]);
    assert_eq!(s.log.entries().nth(2).unwrap().params, json!({"step": "Run Script"}));
    // A failure is logged with its error; a service's address without its token.
    assert!(s.run("project.rename", &json!({"name": " "})).is_err());
    let failed = last(&s);
    assert!(!failed.ok && failed.error.as_deref().is_some_and(|e| e.contains("name")), "{failed:?}");
    let _ = s.run("service.layers", &json!({"url": "https://x.org/wms?token=S3CRET&layers=a", "text": "not a capabilities document"}));
    let service = last(&s);
    assert_eq!(service.command, "service.layers");
    assert!(!service.params.to_string().contains("S3CRET"), "{service:?}");
    // A document given as text is kept as its size only: it may hold secrets no redaction finds.
    let qgs = format!("<qgis version=\"3.42.0\"><title>{}</title></qgis>", "rustgis-s3:TOKEN:s3://b/k ".repeat(20));
    let _ = s.run("project.importQgis", &json!({"text": qgs}));
    let doc = last(&s);
    assert_eq!(doc.params["text"], json!(format!("(a document of {} characters)", qgs.chars().count())), "{doc:?}");
    // A step joined to the newest entry (a held key's nudges) is a change too, so a view of the
    // log reads it again.
    let nudge = |millis| LogEntry {
        at: 1,
        command: "layout.nudge".into(),
        params: json!({"dx": 1}),
        ok: true,
        error: None,
        millis,
        ..Default::default()
    };
    s.log.push(nudge(2));
    let before = s.log.changes();
    s.log.join_last(nudge(3));
    assert!(s.log.changes() != before && last(&s).millis == 5, "{:?}", last(&s));
    // So is one after a byte-order mark (a QGIS project read from a file that has one).
    let marked = format!("\u{feff}{qgs}");
    let _ = s.run("project.importQgis", &json!({"text": marked}));
    let doc = last(&s);
    assert!(doc.params["text"].as_str().is_some_and(|t| t.starts_with("(a document of")), "{doc:?}");
    // A secret in the JSON a text holds (a script's command line) is taken out too.
    let line = r#"s3.connect {"accessKeyId": "AKIA", "secretAccessKey": "S3CRETKEY", "region": "x"}"#;
    let _ = s.run("script.run", &json!({"script": line}));
    let script = last(&s);
    assert!(!script.params.to_string().contains("S3CRETKEY") && script.params.to_string().contains("s3.connect"), "{script:?}");
    // Nor where the clip cuts the object short: what follows its `{` goes.
    // The secret comes first and a long field after it, past the cut.
    let long = format!(r#"s3.connect {{"secretAccessKey": "S3CRETKEY", "notes": "{}"}}"#, "x".repeat(5000));
    let _ = s.run("script.run", &json!({"script": long}));
    let cut = last(&s);
    assert!(!cut.params.to_string().contains("S3CRET"), "{}", cut.params);
    // Nor in an object that doesn't parse (a trailing comma), while text such as `{name}` stays.
    let broken = r#"s3.connect {"secretAccessKey": "S3CRETKEY", "region": "x",} # see {name}"#;
    let _ = s.run("script.run", &json!({"script": broken}));
    let kept = last(&s).params.to_string();
    assert!(!kept.contains("S3CRET") && kept.contains("s3.connect"), "{kept}");
    let _ = s.run("script.run", &json!({"script": "# keep {name} as it is"}));
    assert!(last(&s).params.to_string().contains("{name}"));
    // A long list is "…" once its texts are cut to fit, its count with it.
    let long: Vec<String> = (0..5_000).map(|i| format!("{i}{}", "y".repeat(100))).collect();
    let _ = s.run("project.rename", &json!({"name": "Long", "tags": long}));
    let tags = last(&s).params.to_string();
    assert_eq!(last(&s).params, json!({"name": "Long", "tags": "…"}), "{tags}");
    // Large values clipped. The long text is a key the command doesn't know, because a long name is
    // now refused before it is logged.
    s.run("project.rename", &json!({"name": "Big", "text": "x".repeat(20_000), "note": vec![1; 5_000]})).ok();
    let big = last(&s);
    assert!(serde_json::to_vec(&big.params).unwrap().len() <= LOG_PARAMS_BYTES, "{}", big.params.to_string().len());
    // The project carries none of it: a saved project, or its recovery copy, holds no log.
    assert!(!s.project.saved_text(None).unwrap().0.contains("\"log\""));
    assert!(!s.project.clone().recovery_text().unwrap().contains("\"log\""));
    // Read by filter, newest last.
    let r = s.run("project.log", &json!({"command": "project.rename", "failed": true})).unwrap();
    assert_eq!((r["count"].as_u64(), r["entries"][0]["command"].as_str()), (Some(1), Some("project.rename")));
    assert_eq!(s.run("project.log", &json!({"limit": 2})).unwrap()["entries"].as_array().map(Vec::len), Some(2));
    assert!(s.run("project.log", &json!({"limit": 0})).is_err());
    assert!(s.run("project.log", &json!({"limit": 0.5})).unwrap_err().contains("whole number"));
    // Steps merged into one undo step (a held arrow key) are one entry, with the last parameters.
    let n = s.log.len();
    for name in ["Nudged 1", "Nudged 2", "Nudged 3"] {
        s.merge_undo("nudge");
        s.run("project.rename", &json!({"name": name})).unwrap();
    }
    assert_eq!(s.log.len(), n + 1);
    assert_eq!(last(&s).params["name"], json!("Nudged 3"));
    // Times as decimals too; a negative time, or a filter that isn't true or false, is refused.
    assert_eq!(s.run("project.log", &json!({"since": 1.7e12, "limit": 1})).unwrap()["entries"].as_array().map(Vec::len), Some(1));
    assert!(s.run("project.log", &json!({"since": -1})).is_err());
    assert!(s.run("project.log", &json!({"failed": "true"})).is_err());
    assert!(s.run("project.log", &json!({"command": 7})).is_err());
    // An error that starts as a spreadsheet formula is written as text in the CSV.
    let formula = LogEntry {
        at: 2,
        command: "x".into(),
        params: Value::Null,
        ok: false,
        error: Some("=HYPERLINK(1)".into()),
        millis: 0,
        ..Default::default()
    };
    s.log.push(formula);
    // A session plugin's request between its commands keeps its attribution in both.
    s.log.push(LogEntry {
        at: 3,
        command: "host.addLayer".into(),
        params: Value::Null,
        ok: true,
        error: None,
        millis: 0,
        plugin: Some("globe".into()),
        ..Default::default()
    });
    // Written out as CSV and JSON Lines.
    let dir = std::env::temp_dir().join(format!("rustgis-session-log-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let csv = dir.join("log.csv");
    s.run("project.exportLog", &json!({"path": csv.to_string_lossy()})).unwrap();
    let csv_text = std::fs::read_to_string(&csv).unwrap();
    assert!(
        csv_text.starts_with("time_utc,at,command,ok,millis,error,params,plugin,project,rustgis_version,inputs,inputs_omitted\n")
            && csv_text.contains("\"edit.undo\""),
        "{csv_text}"
    );
    assert!(csv_text.contains("\"'=HYPERLINK(1)\"") && !csv_text.contains(",\"=HYPERLINK"), "{csv_text}");
    // The plugin precedes the project, version, inputs and omitted count (empty or zero here).
    let plugin_cell = |l: &str| l.rsplit(',').nth(4).map(str::to_string);
    assert!(csv_text.lines().any(|l| l.contains("\"host.addLayer\"") && plugin_cell(l).as_deref() == Some("\"globe\"")), "{csv_text}");
    assert!(
        csv_text.lines().any(|l| l.contains("\"edit.undo\"") && plugin_cell(l).as_deref() == Some("\"\"")),
        "the user's own carry none: {csv_text}"
    );
    let jsonl = dir.join("log.jsonl");
    s.run("project.exportLog", &json!({"path": jsonl.to_string_lossy()})).unwrap();
    let lines: Vec<LogEntry> = std::fs::read_to_string(&jsonl).unwrap().lines().map(|l| serde_json::from_str(l).unwrap()).collect();
    assert_eq!(lines.len() + 1, s.log.len(), "every entry but the export's own");
    assert!(lines.iter().any(|e| e.plugin.as_deref() == Some("globe")));
    let _ = std::fs::remove_dir_all(&dir);
    // Cleared, it says so; off, nothing goes in; on again, it does. Neither changes the project,
    // which holds no log, nor takes an undo step.
    for id in ["project.clearLog", "project.logCommands"] {
        assert!(!s.registry.get(id).unwrap().mutates, "{id}");
    }
    let steps = s.undo.len();
    s.mark_saved();
    assert!(s.run("project.clearLog", &Value::Null).unwrap()["cleared"].as_u64().unwrap() > 5);
    assert_eq!(commands(&s), ["project.clearLog"]);
    assert!(!s.dirty() && s.undo.len() == steps, "the project doesn't change");
    s.run("project.logCommands", &json!({"on": false})).unwrap();
    s.run("project.rename", &json!({"name": "Quiet"})).unwrap();
    assert_eq!(commands(&s), ["project.clearLog", "project.logCommands"], "turned off, and said so");
    s.run("project.logCommands", &json!({"on": true})).unwrap();
    assert_eq!(commands(&s), ["project.clearLog", "project.logCommands", "project.logCommands"]);
    // A .json path is refused: JSON Lines isn't one JSON document. A format given doesn't let
    // the log go over another kind of file, nor disagree with the path's extension.
    assert!(s.run("project.exportLog", &json!({"path": "log.json"})).is_err());
    for (path, format) in [("log.json", "jsonl"), ("map.rgis", "csv"), ("log.csv", "jsonl"), ("log", "xml")] {
        let e = s.run("project.exportLog", &json!({"path": path, "format": format})).unwrap_err();
        assert!(e.contains("not a .") || e.contains("doesn't match") || e.contains("format is"), "{path}: {e}");
    }
    assert!(s.run("project.exportLog", &json!({"path": "log"})).unwrap_err().contains("give a .csv"));
    // The log lasts for the session: making a project adds to it and keeps what was there.
    let mut made = world();
    let before = made.log.len();
    made.run("project.new", &json!({"name": "Fresh"})).unwrap();
    assert_eq!(made.log.len(), before + 1);
    assert_eq!(made.log.entries().last().unwrap().command, "project.new");
    // Cleared while off, it still says so.
    s.run("project.logCommands", &json!({"on": false})).unwrap();
    s.run("project.clearLog", &Value::Null).unwrap();
    assert_eq!(commands(&s), ["project.clearLog"]);
    s.run("project.logCommands", &json!({"on": true})).unwrap();
    // Capped: the oldest go first.
    for i in 0..LOG_LIMIT + 5 {
        s.log.push(LogEntry {
            at: i as u64,
            command: "x".into(),
            params: Value::Null,
            ok: true,
            error: None,
            millis: 0,
            ..Default::default()
        });
    }
    assert_eq!(s.log.len(), LOG_LIMIT);
    assert_eq!(s.log.entries().next().unwrap().at, 5);
    // A session plugin's requests between its commands count with the plugins': past their limit
    // they make room among themselves, not by pushing out the user's entries.
    let user = s.log.entries().next().unwrap().at;
    for i in 0..LOG_PLUGIN_LIMIT + 5 {
        let e = LogEntry {
            at: 1_000_000 + i as u64,
            command: "host.addLayer".into(),
            params: Value::Null,
            ok: true,
            error: None,
            millis: 0,
            plugin: Some("globe".into()),
            ..Default::default()
        };
        s.log.push(e);
    }
    assert_eq!(s.log.entries().filter(|e| e.plugin.is_some()).count(), LOG_PLUGIN_LIMIT);
    assert_eq!(s.log.entries().next().unwrap().at, user + LOG_PLUGIN_LIMIT as u64);
    // What was dropped is counted, and an export says so; a clear starts the count again.
    assert!(s.log.dropped() >= 5, "{}", s.log.dropped());
    let out = std::env::temp_dir().join(format!("rustgis-log-dropped-{}.csv", std::process::id()));
    let mark = s.notice_mark();
    s.run("project.exportLog", &json!({"path": out.display().to_string()})).unwrap();
    assert!(
        s.notices_since(mark)
            .iter()
            .any(|n| n.text.contains("; not in it: ") && n.text.contains("oldest entries were dropped past the log's limit of 10000")),
        "{:?}",
        s.notices_since(mark)
    );
    let _ = std::fs::remove_file(&out);
    s.log.clear();
    assert_eq!(s.log.dropped(), 0);
    // A clean export says nothing of it.
    let mark = s.notice_mark();
    s.run("project.exportLog", &json!({"path": out.display().to_string()})).unwrap();
    assert!(!s.notices_since(mark).iter().any(|n| n.text.contains("were dropped past")), "{:?}", s.notices_since(mark));
    let _ = std::fs::remove_file(&out);
    // Undo or redo with nothing to take back changes nothing, and isn't logged.
    s.clear_history();
    let n = s.log.len();
    assert!(s.run("edit.undo", &Value::Null).is_err() && s.run("edit.redo", &Value::Null).is_err());
    assert_eq!(s.log.len(), n, "nothing to undo or redo: not logged");
}

/// Each entry names the project it ran in (the one it opened, for a command that opens one), and
/// another project of the same name is told apart; parameters cut to fit or without their secrets
/// are said to be partial, as they wouldn't run as they ran; a saved log keeps the project's name.
#[test]
fn session_log_entries_name_their_project_and_say_when_their_params_are_partial() {
    #[cfg(not(target_arch = "wasm32"))]
    if isolate_process_test("tests::session_log_entries_name_their_project_and_say_when_their_params_are_partial") {
        return;
    }
    let mut s = world();
    s.log.clear();
    let last = |s: &Session| s.log.entries().last().cloned().unwrap();
    s.run("project.rename", &json!({"name": "Atlas"})).unwrap();
    let renamed = last(&s);
    assert_eq!((renamed.project.as_str(), renamed.opened, renamed.partial), ("Atlas", s.opened, false), "{renamed:?}");
    s.run("project.new", &json!({"name": "Atlas"})).unwrap();
    let made = last(&s);
    assert_eq!((made.command.as_str(), made.project.as_str(), made.opened), ("project.new", "Atlas", s.opened));
    assert_ne!(made.opened, renamed.opened, "the same name, another project");
    // A script with nothing to take out is kept as written, its spacing too: not partial.
    let script = "map.new {\"name\": \"Third\"}\n# a { that isn't JSON";
    s.run("script.run", &json!({"script": script})).unwrap();
    let ran = last(&s);
    assert_eq!((ran.params["script"].as_str(), ran.partial), (Some(script), false), "{ran:?}");
    // A secret's key written twice is read as its last value: the first isn't kept as written.
    let _ = s.run("script.run", &json!({"script": "map.new {\"name\": \"M\", \"secretAccessKey\": \"zzzz\", \"secretAccessKey\": \"\"}"}));
    let twice = last(&s);
    assert!(!twice.params.to_string().contains("zzzz") && twice.partial, "{twice:?}");
    // Nor with its name escaped, nor a key a plain name blanks only for its value, nor deeper in;
    // and a key only logs leave out (`passphrase`) isn't kept either, nor one past eight levels.
    for script in [
        r#"map.new {"name": "M", "passphrase": "zzzz"}"#,
        r#"map.new {"name": "M", "a": [[[[[[[[[{"passphrase": "zzzz"}]]]]]]]]]}"#,
        r#"map.new {"name": "M", "\u0074oken": "zzzz", "\u0074oken": ""}"#,
        r#"map.new {"name": "M", "key": "AKIAIOSFODNN7zzzz", "key": ""}"#,
        r#"map.new {"name": "M", "style": {"token": "zzzz", "token": ""}}"#,
    ] {
        let before = s.log.len();
        let _ = s.run("script.run", &json!({"script": script}));
        let e = last(&s);
        assert_eq!((s.log.len(), e.command.as_str()), (before + 1, "script.run"), "{script}: its own entry");
        assert!(!e.params.to_string().contains("zzzz") && e.partial, "{script}: {e:?}");
    }
    // A name past the bound is cut, and says so.
    s.project.name = "n".repeat(crate::cmd::MAX_NAME + 5);
    s.run("map.new", &json!({"name": "Long"})).unwrap();
    assert_eq!(last(&s).project, format!("{}…", "n".repeat(crate::cmd::MAX_NAME)));
    s.project.name = "Atlas".into();
    // A script past the log's bound is cut: partial, so it isn't run again as a part.
    let long = format!("# {}", "x".repeat(crate::project_log::LOG_PARAMS_BYTES * 2));
    s.run("script.run", &json!({"script": long})).unwrap();
    assert!(last(&s).partial);
    // An address without its token: partial too.
    let _ = s.run("service.layers", &json!({"url": "https://x.org/wms?token=zzzz&layers=a", "text": "not a capabilities document"}));
    let service = last(&s);
    assert_eq!(service.command, "service.layers", "{service:?}");
    assert!(!service.params.to_string().contains("zzzz") && service.partial, "{service:?}");
    // And `project.log` says so: `partial` is in its answer.
    let answer = s.run("project.log", &json!({"command": "service.layers", "limit": 1})).unwrap();
    assert_eq!(answer["entries"][0]["partial"], json!(true), "{answer}");
    // Saved: the project precedes version and inputs in CSV; in JSON, the name, and `partial` only when so.
    let mut csv = Vec::new();
    s.log.write(&mut csv, true).unwrap();
    let csv = String::from_utf8(csv).unwrap();
    let suffix = format!(",\"Atlas\",\"{}\",\"[]\",0", env!("CARGO_PKG_VERSION"));
    assert!(csv.lines().nth(1).is_some_and(|row| row.ends_with(&suffix)), "{csv}");
    let json = serde_json::to_value(&renamed).unwrap();
    assert_eq!(json["project"], "Atlas");
    assert!(json.get("opened").is_none() && json.get("partial").is_none(), "{json}");
}

/// What the session log keeps of a command's parameters: bounded in bytes, keys and time, and
/// without secrets, those in JSON a text holds and in SQL `CREATE … SECRET` options included.
#[test]
fn the_session_log_keeps_parameters_bounded_and_without_secrets() {
    // Many keys with short values still fit the bound.
    let wide: serde_json::Map<String, Value> = (0..40).map(|i| (format!("{i:02}{}", "k".repeat(62)), json!("é".repeat(64)))).collect();
    let kept = crate::project_log::kept_params(&Value::Object(wide));
    assert!(serde_json::to_vec(&kept).unwrap().len() <= crate::project_log::LOG_PARAMS_BYTES, "{kept}");
    assert!(kept.as_object().is_some_and(|o| o.len() > 1 && o.len() < 40));
    assert_eq!(kept["…"], json!("40 keys in all"));
    // Keys alike in their first 64 characters: the first stays, the other counted as left out.
    let mut alike: serde_json::Map<String, Value> = (0..40).map(|i| (format!("{i:02}{}", "k".repeat(62)), json!("v".repeat(64)))).collect();
    // Sorts right after the first key, and is the same once cut to 64 characters.
    alike.insert(format!("00{}a", "k".repeat(62)), json!(2));
    let kept = crate::project_log::kept_params(&Value::Object(alike));
    assert_eq!(kept["…"], json!("41 keys in all"));
    assert_eq!(kept[format!("00{}", "k".repeat(62))], json!("v".repeat(64)), "the first stays");
    assert!(kept.as_object().is_some_and(|o| !o.values().any(|v| *v == json!(2))), "{kept}");
    // A crafted text costs its length, not its braces times its length: 200,000 braces are
    // milliseconds once, and would be hours if each `{` scanned the rest (a bound far from both).
    let crafted = "{1".repeat(200_000);
    let started = std::time::Instant::now();
    assert_eq!(crate::project_log::json_in_text_redacted(&crafted).len(), crafted.len());
    assert!(started.elapsed() < std::time::Duration::from_secs(60), "{:?}", started.elapsed());
    // A key cut short keeps no value: a secret's name may be past the cut.
    let long_key = format!("{}secretAccessKey", "x".repeat(195));
    let kept = crate::project_log::kept_params(&json!({long_key: "S3CRET"}));
    assert!(!kept.to_string().contains("S3CRET"), "{kept}");
    // An SQL secret's options, written as plain words, go; the statement's shape stays.
    let sql = "CREATE OR REPLACE SECRET s3 (TYPE s3, KEY_ID 'AKIA1', SECRET 'S3CRET'); SELECT 1 / 2";
    let kept = crate::project_log::kept_params(&json!({"sql": sql}));
    assert_eq!(kept["sql"], json!("CREATE OR REPLACE SECRET s3 (…); SELECT 1 / 2"));
    assert_eq!(crate::project_log::sql_secrets_removed("create table t (a int)"), "create table t (a int)");
    assert_eq!(crate::project_log::sql_secrets_removed("create table secret (a int)"), "create table secret (a int)");
    // A file's contents in base64 (`layer.addDataBytes`) are kept as their size: a secret's name
    // can't be seen in them. A long text that isn't base64 is clipped as before.
    let encoded = "eyJ0b2tlbiI6ICJTM0NSRVQifQ==".repeat(20);
    for data in [encoded.clone(), format!("data:application/json;base64,{encoded}")] {
        let kept = crate::project_log::kept_params(&json!({"fileName": "a.geojson", "data": data}));
        assert_eq!(kept["data"], json!(format!("(file contents of {} characters, base64)", data.len())), "{kept}");
    }
    let prose = crate::project_log::kept_params(&json!({"note": "word ".repeat(100)}));
    assert!(prose["note"].as_str().is_some_and(|n| n.starts_with("word word")), "{prose}");
    // `create` inside another word starts no statement.
    for t in ["recreate secret s (key 'a')", "created secret (key 'a')"] {
        assert_eq!(crate::project_log::sql_secrets_removed(t), t);
    }
    assert_eq!(crate::project_log::sql_secrets_removed("CREATE PERSISTENT SECRET (TYPE s3, SECRET 'x')"), "CREATE PERSISTENT SECRET (…)");
    // An unquoted secret key in an object that doesn't parse goes, with the rest of the text;
    // a format string's braces stay.
    let line = crate::project_log::kept_params(&json!({"script": "s3.connect {secretAccessKey: \"S3CRET\"}\nprint(f\"{x:.2f}\")"}));
    assert!(!line.to_string().contains("S3CRET"), "{line}");
    let fmt = crate::project_log::kept_params(&json!({"script": "print(f\"{x:.2f}\")"}));
    assert_eq!(fmt["script"], json!("print(f\"{x:.2f}\")"));
    // A quoted secret key in such an object goes too, its value with it, double or single quotes.
    for line in [r#"s3.connect {a: "x", "secretAccessKey": "S3CRET",}"#, "s3.connect {a: 'x', 'secretAccessKey': 'S3CRET',}"] {
        let kept = crate::project_log::kept_params(&json!({"script": line}));
        assert!(!kept.to_string().contains("S3CRET") && kept.to_string().contains("s3.connect"), "{kept}");
    }
    // A response is logged as its own size, also when the rest makes the entry large.
    let answer = "a".repeat(41);
    let notes: Vec<Value> = (0..50).map(|_| json!("n".repeat(200))).collect();
    let kept = crate::project_log::kept_params(&json!({"answer": answer, "notes": notes}));
    assert_eq!(kept["answer"], json!("(a response of 41 characters)"), "{kept}");
    let kept = crate::project_log::kept_params(&json!({"answer": "short"}));
    assert_eq!(kept["answer"], json!("(a response of 5 characters)"), "{kept}");
}

/// Plugins can neither empty the session log nor turn it off, nor push the user's entries out of
/// it; writing the log out, or reading it, reaches a file.
#[test]
fn plugins_can_neither_clear_the_session_log_nor_crowd_out_the_users_entries() {
    use crate::project_log::LogEntry;
    // Plugins' commands keep at most their own share of the log: the user's entries stay.
    let mut log = crate::project_log::SessionLog::default();
    let entry = |command: &str| LogEntry {
        at: 1,
        command: command.into(),
        params: Value::Null,
        ok: true,
        error: None,
        millis: 0,
        ..Default::default()
    };
    log.push(entry("layer.rename"));
    for _ in 0..crate::project_log::LOG_PLUGIN_LIMIT + 5 {
        log.push(entry("plugin:p/flood"));
    }
    assert_eq!(log.len(), crate::project_log::LOG_PLUGIN_LIMIT + 1);
    assert_eq!(log.entries().next().unwrap().command, "layer.rename");
    // A plugin never empties the log or turns it off; writing it out is reaching a file.
    assert!(crate::cmd::plugins::user_only("project.clearLog") && crate::cmd::plugins::user_only("project.logCommands"));
    {
        use crate::cmd::plugins::{Reach, reaches};
        let export = crate::cmd::all().into_iter().find(|c| c.id == "project.exportLog").unwrap();
        assert_eq!(reaches(&export, &json!({"path": "log.csv"})), Some(Reach::Files));
        // Reading it too: it names the files and addresses the user's commands used.
        let read = crate::cmd::all().into_iter().find(|c| c.id == "project.log").unwrap();
        assert_eq!(reaches(&read, &json!({})), Some(Reach::Files));
    }
}

/// `raster.project` puts a raster on a grid of another coordinate system, cell size, origin and
/// extent, or on another raster's grid: grids of the same cell and origin line up, a polygon
/// layer's selection gives the extent, and bad parameters are refused before anything is made.
#[test]
fn a_raster_projected_onto_a_chosen_grid() {
    use rustgis_data::raster::{ColorHint, Crs, GeoTransform, Raster};
    let mut s = world();
    // 40 × 40 pixels of 0.001° near Teresina, value = column + 100 · row.
    let gt = GeoTransform { origin_x: -42.82, origin_y: -5.08, pixel_width: 0.001, pixel_height: -0.001 };
    let v: Vec<f32> = (0..1600).map(|i| (i % 40 + 100 * (i / 40)) as f32).collect();
    let r = Raster::new("the", 40, 40, vec![v], gt, Crs::LonLat, None, ColorHint::Gray, "Float32").unwrap();
    let bytes = rustgis_data::raster::geotiff::write(&r, 0).unwrap();
    crate::cmd::raster::add_raster(&mut s, "the", rustgis_map::RasterLayer::from_bytes(r, "the.tif", bytes)).unwrap();

    // SIRGAS 2000 / UTM 23S, 200 m cells averaged: about 22 × 22 cells, means within the values.
    let v = s.run("raster.project", &json!({"layer": "the", "crs": 31983, "cellSize": 200, "resampling": "average"})).unwrap();
    assert_eq!(
        (v["crs"].as_str(), v["resampling"].as_str(), v["name"].as_str()),
        (Some("EPSG:31983"), Some("average"), Some("the projected"))
    );
    let out = out_raster(&s, &v);
    assert!((22..=24).contains(&out.width) && (22..=24).contains(&out.height), "{} × {}", out.width, out.height);
    let mid = out.value(0, i64::from(out.width) / 2, i64::from(out.height) / 2).unwrap();
    assert!((0.0..=3939.0).contains(&mid) && mid.fract() != 0.0, "a mean of several pixels: {mid}");
    // Cell corners on whole multiples of the cell (origin [0, 0]), here and over a part of it.
    let on_grid = |v: &Value| {
        let c = &v["corner"];
        (c[0].as_f64().unwrap() / 200.0).fract() == 0.0 && (c[1].as_f64().unwrap() / 200.0).fract() == 0.0
    };
    assert!(on_grid(&v));
    let part = s
        .run(
            "raster.project",
            &json!({"layer": "the", "crs": "EPSG:31983", "cellSize": 200, "extent": [-42.81, -5.11, -42.79, -5.09], "name": "part"}),
        )
        .unwrap();
    assert!(on_grid(&part) && part["width"].as_u64() < v["width"].as_u64(), "{part}");
    // Another origin moves the corners with it.
    let moved =
        s.run("raster.project", &json!({"layer": "the", "crs": 31983, "cellSize": 200, "origin": [50, 50], "name": "moved"})).unwrap();
    // An origin with anything but two numbers is refused, not read from the numbers left.
    for bad in [json!(["x", 1, 2]), json!([0, 0, "EPSG"]), json!([1])] {
        assert!(s.run("raster.project", &json!({"layer": "the", "crs": 31983, "cellSize": 200, "origin": bad})).is_err(), "{bad}");
    }
    // Projected again with the default name: the name reported is the one the layer got.
    let first = s.run("raster.project", &json!({"layer": "the", "crs": 31983, "cellSize": 500})).unwrap();
    let again = s.run("raster.project", &json!({"layer": "the", "crs": 31983, "cellSize": 500})).unwrap();
    assert_ne!(first["name"], again["name"]);
    for r in [&first, &again] {
        assert!(s.map().layer_by_name(r["name"].as_str().unwrap()).is_some(), "{r}");
    }
    // An extent or a grid of the wrong kind is refused, not read as the view or left out.
    for bad in [json!({"extent": 5}), json!({"extent": {}}), json!({"extent": true}), json!({"grid": 5}), json!({"grid": ["the"]})] {
        let mut p = bad.clone();
        p["layer"] = json!("the");
        let e = s.run("raster.project", &p).unwrap_err();
        assert!(e.contains("extent is") || e.contains("grid is"), "{bad}: {e}");
    }
    assert_eq!((moved["corner"][0].as_f64().unwrap() - 50.0).rem_euclid(200.0), 0.0, "{moved}");

    // Onto that grid exactly, by nearest neighbour (the default).
    let again = s.run("raster.project", &json!({"layer": "the", "grid": "the projected", "name": "again"})).unwrap();
    let a = out_raster(&s, &again);
    assert_eq!((a.width, a.height, a.transform, a.crs), (out.width, out.height, out.transform, out.crs));
    assert_eq!(again["resampling"], "nearest");

    // The extent of a polygon layer's selection: Brazil, in 50 km cells.
    s.run("select.byAttributes", &json!({"layer": "Countries", "where": "name = 'Brazil'"})).unwrap();
    let br =
        s.run("raster.project", &json!({"layer": "the", "crs": 31983, "cellSize": 50_000, "extent": "Countries", "name": "br"})).unwrap();
    let (w, h) = (br["width"].as_u64().unwrap(), br["height"].as_u64().unwrap());
    assert!((70..=130).contains(&w) && (70..=130).contains(&h), "{w} × {h}");

    // Refused: a grid with its own settings, bad cells, origins, extents and methods, a grid too
    // large to hold, and a file that isn't a GeoTIFF.
    let bad = [
        json!({"layer": "the", "grid": "the projected", "crs": 31983}),
        json!({"layer": "the", "grid": "Countries"}),
        json!({"layer": "the", "cellSize": -1}),
        json!({"layer": "the", "cellSize": [1, 0]}),
        json!({"layer": "the", "cellSize": "x"}),
        json!({"layer": "the", "origin": "x"}),
        json!({"layer": "the", "origin": [1, f64::NAN]}),
        json!({"layer": "the", "extent": [170.0, -10.0, -170.0, 10.0]}),
        json!({"layer": "the", "extent": "Nowhere"}),
        json!({"layer": "the", "resampling": "lanczos"}),
        json!({"layer": "the", "crs": 31983, "cellSize": 0.001}),
        json!({"layer": "the", "crs": "nonsense"}),
        json!({"layer": "the", "path": "out.png"}),
    ];
    let before = s.map().layers.len();
    for p in bad {
        assert!(s.run("raster.project", &p).is_err(), "{p}");
    }
    assert_eq!(s.map().layers.len(), before, "nothing added by a refused run");
    let e = s.run("raster.project", &json!({"layer": "the", "crs": 31983, "cellSize": 0.001})).unwrap_err();
    assert!(e.contains("give a larger cellSize"), "{e}");
}

/// Importing a project must preserve the current map, styles, inherited opacity and undo.
#[test]
fn geolibre_import_inline_styles_groups_and_undo() {
    let mut s = world();
    let maps = s.project.maps.len();
    let original = s.map().name.clone();
    let feature = json!({"type":"FeatureCollection","features":[{"type":"Feature","geometry":{"type":"Point","coordinates":[0,0]},"properties":{"kind":"a","value":10}}]});
    let text=json!({"version":"0.2.0","name":"Imported","mapView":{"center":[10,20],"zoom":5,"bearing":15},"basemapStyleUrl":"","layerGroups":[{"id":"g","name":"Half","opacity":0.5,"visible":false}],"layers":[{"id":"a","name":"Points","type":"geojson","geojson":feature,"groupId":"g","opacity":0.5,"style":{"vectorStyleMode":"categorized","vectorStyleProperty":"kind","vectorStyleStops":[{"value":"a","color":"#ff0000"}],"labels":{"enabled":true,"field":"kind"}}}],"bookmarks":[{"name":"Place","lng":1,"lat":2,"zoom":3}]}).to_string();
    let out = s.run("project.importGeolibre", &json!({"text":text})).unwrap();
    assert_eq!(out["layers"], json!(["Points"]));
    assert_eq!(s.project.maps.len(), maps + 1);
    let layer = &s.map().layers[0];
    assert!(layer.visible);
    assert_eq!(layer.transparency, 50.0);
    assert!(!s.map().groups[0].visible);
    assert_eq!(s.map().groups[0].transparency, 50.0);
    assert!(matches!(layer.renderer, rustgis_map::Renderer::Unique { .. }));
    assert!(layer.labels.enabled);
    assert_eq!(s.map().groups[0].children, vec![layer.id]);
    assert_eq!(s.map().bookmarks[0].name, "Place");
    assert_eq!(s.map().camera.bearing, 15.0);
    s.run("edit.undo", &json!({})).unwrap();
    assert_eq!(s.project.maps.len(), maps);
    assert_eq!(s.map().name, original);
    assert!(crate::cmd::plugins::user_only("project.importGeolibre"));
}

#[test]
fn geolibre_input_channels_missing_sources_and_malformed_data() {
    use base64::Engine;
    let text=json!({"version":"0.2.0","name":"Empty","mapView":{},"basemapStyleUrl":"","layers":[{"name":"Missing","type":"geojson","sourcePath":"/no/such/geolibre-data.geojson"},{"name":"Video","type":"video"}]}).to_string();
    for p in [json!({"text":text}), json!({"data":base64::engine::general_purpose::STANDARD.encode(&text)})] {
        let mut s = world();
        let out = s.run("project.importGeolibre", &p).unwrap();
        assert_eq!(out["layers"], json!([]));
        assert_eq!(out["notes"].as_array().unwrap().len(), 2);
    }
    let mut s = world();
    let maps = s.project.maps.len();
    for p in [json!({"text":"{"}), json!({"text":"null"}), json!({"data":"!!!!"}), json!({"url":"file:///etc/passwd"})] {
        assert!(s.run("project.importGeolibre", &p).is_err());
        assert_eq!(s.project.maps.len(), maps);
    }
}

#[test]
fn geolibre_moved_local_source_uses_project_directory() {
    let dir = std::env::temp_dir().join(format!("rustgis-geolibre-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let data = dir.join("points.geojson");
    std::fs::write(
        &data,
        r#"{"type":"FeatureCollection","features":[{"type":"Feature","geometry":{"type":"Point","coordinates":[0,0]},"properties":{}}]}"#,
    )
    .unwrap();
    let path = dir.join("map.geolibre");
    std::fs::write(&path,json!({"version":"0.2.0","name":"Moved","mapView":{},"basemapStyleUrl":"","layers":[{"name":"Points","type":"geojson","sourcePath":"C:/old/place/points.geojson"}]}).to_string()).unwrap();
    let mut s = world();
    let out = s.run("project.importGeolibre", &json!({"path":path})).unwrap();
    assert_eq!(out["layers"], json!(["Points"]));
    assert_eq!(s.map().layers[0].dataset.features.len(), 1);
    std::fs::remove_dir_all(dir).unwrap();
}

#[test]
fn geolibre_download_finishes_in_its_original_map_and_position() {
    let mut s = world();
    let mut ds = rustgis_data::Dataset::new("Points", rustgis_data::GeometryType::Point, Vec::new());
    ds.source = Some("geolibre-pending:test".into());
    let target = s.project.active_map;
    let id = s.map_mut().add_dataset(ds);
    s.map_mut().layer_mut(id).unwrap().name = "Renamed while downloading".into();
    s.map_mut().layer_mut(id).unwrap().visible = false;
    s.map_mut().layer_mut(id).unwrap().transparency = 35.0;
    let camera = s.map().camera;
    s.run("map.new", &json!({"name":"Other"})).unwrap();
    let active = s.project.active_map;
    let download = s.download_started();
    s.download_landed(download,br#"{"type":"FeatureCollection","features":[{"type":"Feature","geometry":{"type":"Point","coordinates":[0,0]},"properties":{"value":1}}]}"#.to_vec());
    let out=s.run("layer.addDownload",&json!({"id":download,"url":"https://example.org/points.geojson","name":"Points","geolibreLayer":{"token":"geolibre-pending:test","record":{"style":{"circleRadius":9}}}})).unwrap();
    assert_eq!(out["layer"], id);
    assert_eq!(s.project.active_map, active);
    let map = &s.project.maps[target];
    let loaded = map.layer(id).unwrap();
    assert_eq!(loaded.dataset.features.len(), 1);
    assert_eq!(loaded.name, "Renamed while downloading");
    assert!(!loaded.visible);
    assert_eq!(loaded.transparency, 35.0);
    assert_eq!(loaded.dataset.name, loaded.name);
    assert_eq!(loaded.renderer.base_symbol().size, 18.0);
    assert_eq!(map.camera, camera);
    assert!(s.map().layers.is_empty());
    // Completion and an earlier map switch must not resurrect the consumed reservation.
    for _ in 0..2 {
        s.run("edit.undo", &json!({})).unwrap();
        assert!(s.project.saved_text(None).is_ok());
        assert!(s.project.maps.iter().all(|m| m.layers.iter().all(|l| l.dataset.source.as_deref() != Some("geolibre-pending:test"))));
    }
    for _ in 0..2 {
        s.run("edit.redo", &json!({})).unwrap();
        assert!(s.project.saved_text(None).is_ok());
    }
    assert_eq!(s.project.maps[target].layer(id).unwrap().dataset.features.len(), 1);
}

/// The import calls `request_import_url` itself, which sets the flag in the import's own scope: it
/// edited the project, so it keeps its undo step (#2637).
#[test]
fn geolibre_import_that_leaves_a_download_is_one_undo_step() {
    let mut s = world();
    s.leave_downloads = true;
    let undo = s.undo.len();
    let text = json!({"version":"0.2.0","name":"Remote","mapView":{},"basemapStyleUrl":"","layers":[{"id":"g","name":"Remote","type":"geojson","source":{"url":"https://example.org/a.geojson"}}]}).to_string();
    s.run("project.importGeolibre", &json!({"text": text})).unwrap();
    assert_eq!(s.take_url_requests().len(), 1);
    assert_eq!(s.undo.len(), undo + 1, "the import takes its step");
}

#[test]
fn geolibre_tile_sources_keep_visibility_opacity_and_order() {
    let mut s = world();
    let layers:Vec<_>=["xyz","wms","wmts","vector-tiles"].into_iter().enumerate().map(|(i,kind)|json!({"id":kind,"name":kind,"type":kind,"visible":false,"opacity":0.3,"source":{"tiles":[format!("https://example.org/{i}/{{z}}/{{x}}/{{y}}.png")]}})).collect();
    let out = s
        .run(
            "project.importGeolibre",
            &json!({"text":json!({"version":"0.2.0","name":"Tiles","mapView":{},"basemapStyleUrl":"","layers":layers}).to_string()}),
        )
        .unwrap();
    assert_eq!(out["layers"].as_array().unwrap().len(), 4);
    assert_eq!(s.map().tiles.len(), 4);
    assert!(s.map().tiles.iter().all(|t| !t.visible && t.opacity == 0.3));
    assert_eq!(s.map().tiles[0].name, "vector-tiles");
    assert_eq!(s.map().tiles[3].name, "xyz");
}

/// A file is let go of with its last layer, however that went (Windows won't move or delete a file
/// SQLite has open), and one still on a map keeps its connections for the next tile.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn mbtiles_files_are_let_go_of_with_their_last_layer() {
    use rustgis_data::mbtiles::{close, is_open, tile_path};
    struct Cleanup(std::path::PathBuf);
    impl Drop for Cleanup {
        fn drop(&mut self) {
            // Also clean up if an assertion fails with the file still open.
            close(&self.0);
            let _ = std::fs::remove_file(&self.0);
        }
    }
    let path = std::env::temp_dir().join(format!("rustgis-mbtiles-release-{}.mbtiles", std::process::id()));
    let _ = std::fs::remove_file(&path);
    let _cleanup = Cleanup(path.clone());
    let db = rusqlite::Connection::open(&path).unwrap();
    db.execute_batch("CREATE TABLE metadata(name TEXT,value TEXT); CREATE TABLE tiles(zoom_level INTEGER,tile_column INTEGER,tile_row INTEGER,tile_data BLOB); INSERT INTO metadata VALUES('format','png'),('minzoom','0'),('maxzoom','0'); INSERT INTO tiles VALUES(0,0,0,x'00');").unwrap();
    drop(db);
    let mut s = Session::new(Project::default());
    s.run("map.addTiles", &json!({"url": path.display().to_string(), "kind": "mbtiles"})).unwrap();
    // The pool is the process's, and another test's command can close the file at any moment, so
    // this asks only that a command leave it open once: it fails if every command closes it.
    let stays_open = |s: &mut Session| {
        (0..100).any(|_| {
            tile_path(&path, 0, 0, 0).unwrap();
            s.run("map.graticule", &json!({})).unwrap();
            is_open(&path)
        })
    };
    assert!(stays_open(&mut s), "a layer on the map keeps its connections");
    s.run("map.addTiles", &json!({"url": path.display().to_string(), "kind": "mbtiles", "overlay": true})).unwrap();
    s.run("map.removeTiles", &json!({"index": 0})).unwrap();
    assert!(stays_open(&mut s), "the file's other layer keeps them");
    s.run("map.removeTiles", &json!({})).unwrap();
    assert!(!is_open(&path), "the layer removed");
    s.run("edit.undo", &json!({})).unwrap();
    assert!(stays_open(&mut s), "the layer back");
    s.run("project.new", &json!({})).unwrap();
    assert!(!is_open(&path), "the project closed");
    std::fs::remove_file(&path).unwrap();
}

/// A file replaced after its last layer went is read again: its metadata, the style made from them
/// and its tiles, not what was kept of the old one.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn a_replaced_mbtiles_file_is_read_again() {
    use crate::render::rustgis_tiles::{cache, mbtiles, source};
    struct Cleanup(std::path::PathBuf);
    impl Drop for Cleanup {
        fn drop(&mut self) {
            rustgis_data::mbtiles::close(&self.0);
            let _ = std::fs::remove_file(&self.0);
        }
    }
    let path = std::env::temp_dir().join(format!("rustgis-mbtiles-replaced-{}.mbtiles", std::process::id()));
    let _ = std::fs::remove_file(&path);
    let _cleanup = Cleanup(path.clone());
    let write = |size: u32, max_zoom: u8| {
        if path.exists() {
            std::fs::remove_file(&path).unwrap();
        }
        let mut png = Vec::new();
        image::RgbaImage::new(size, size).write_to(&mut std::io::Cursor::new(&mut png), image::ImageFormat::Png).unwrap();
        let db = rusqlite::Connection::open(&path).unwrap();
        db.execute_batch("CREATE TABLE metadata(name TEXT,value TEXT); CREATE TABLE tiles(zoom_level INTEGER,tile_column INTEGER,tile_row INTEGER,tile_data BLOB);").unwrap();
        db.execute("INSERT INTO metadata VALUES('format','png'),('minzoom','0'),('maxzoom',?1),('attribution',?1)", [max_zoom.to_string()])
            .unwrap();
        db.execute("INSERT INTO tiles VALUES(0,0,0,?1)", [png]).unwrap();
    };
    let url = path.display().to_string();
    let tile = mbtiles::template(&url).replace("{z}", "0").replace("{x}", "0").replace("{y}", "0");
    let tile_width = || {
        for _ in 0..1000 {
            match cache::get_tile(&tile, cache::Want::Image) {
                cache::State::Ready(payload) => match &*payload {
                    cache::Payload::Image(image) => return image.width(),
                    _ => panic!("not an image"),
                },
                cache::State::Failed(e) => panic!("{e}"),
                cache::State::Pending => std::thread::sleep(std::time::Duration::from_millis(10)), // test-wait: legacy polling for the legend image
            }
        }
        panic!("the tile never came");
    };
    let credits = |s: &Session| {
        for _ in 0..1000 {
            match source::resolve(&crate::render::tile_spec(&s.map().tiles[0])) {
                source::Resolve::Ready(style) => return style.attribution.clone(),
                source::Resolve::Failed(e) => panic!("{e}"),
                _ => std::thread::sleep(std::time::Duration::from_millis(10)), // test-wait: legacy polling for tile source attribution
            }
        }
        panic!("the style never came");
    };
    let mut s = Session::new(Project::default());
    write(2, 1);
    s.run("map.addTiles", &json!({"url": url, "kind": "mbtiles"})).unwrap();
    assert_eq!((mbtiles::info(&url).unwrap().max_zoom, credits(&s), tile_width()), (1, vec!["1".to_string()], 2));
    s.run("map.removeTiles", &json!({})).unwrap();
    write(4, 5);
    s.run("map.addTiles", &json!({"url": url, "kind": "mbtiles"})).unwrap();
    assert_eq!((mbtiles::info(&url).unwrap().max_zoom, credits(&s), tile_width()), (5, vec!["5".to_string()], 4));
}

/// Sources authored by this test exercise the dispatch for every supported local data kind.
#[cfg(not(target_arch = "wasm32"))]
#[test]
fn geolibre_local_source_kinds_and_archives() {
    let dir = std::env::temp_dir().join(format!("rustgis-geolibre-kinds-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let (ds,_)=rustgis_data::io::read_bytes("points.geojson",br#"{"type":"FeatureCollection","features":[{"type":"Feature","geometry":{"type":"Point","coordinates":[0,0]},"properties":{"value":1}}]}"#).unwrap();
    for (file, ext) in [("points.fgb", "fgb"), ("points.parquet", "parquet")] {
        std::fs::write(dir.join(file), rustgis_data::io::write_bytes(&ds, ext).unwrap().0).unwrap();
    }
    std::fs::write(dir.join("points.las"), las_bytes(&[(10.5, 50.5, 300.0, 2)])).unwrap();
    let raster = rustgis_data::raster::ascii::read(
        "ncols 2\nnrows 2\nxllcorner 0\nyllcorner 0\ncellsize 1\nNODATA_value -9999\n1 2\n3 4\n",
        "grid",
        Some(rustgis_data::raster::Crs::LonLat),
    )
    .unwrap();
    let tif = rustgis_data::raster::geotiff::write(&raster, 0).unwrap();
    std::fs::write(dir.join("grid.tif"), &tif).unwrap();
    let mut tile = tiny_skia::Pixmap::new(1, 1).unwrap();
    tile.fill(tiny_skia::Color::from_rgba8(10, 20, 30, 255));
    let png = tile.encode_png().unwrap();
    let archive = crate::render::rustgis_tiles::pmtiles::NewArchive {
        tile_type: crate::render::rustgis_tiles::pmtiles::TileType::Png,
        gzipped_tiles: false,
        bounds: [-180.0, -85.0, 180.0, 85.0],
        metadata: json!({}),
    };
    std::fs::write(
        dir.join("tiles.pmtiles"),
        crate::render::rustgis_tiles::pmtiles::write(vec![(0, 0, 0, png.clone())], &archive).unwrap(),
    )
    .unwrap();
    let db = rusqlite::Connection::open(dir.join("tiles.mbtiles")).unwrap();
    db.execute_batch("CREATE TABLE metadata(name TEXT,value TEXT); CREATE TABLE tiles(zoom_level INTEGER,tile_column INTEGER,tile_row INTEGER,tile_data BLOB); INSERT INTO metadata VALUES('format','png'),('minzoom','0'),('maxzoom','0');").unwrap();
    db.execute("INSERT INTO tiles VALUES(0,0,0,?1)", [png]).unwrap();
    drop(db);
    let store = dir.join("grid.zarr");
    std::fs::create_dir_all(&store).unwrap();
    let arr = |shape: Value, chunks: Value| json!({"zarr_format":2,"shape":shape,"chunks":chunks,"dtype":"<f8","compressor":null,"filters":null,"order":"C","fill_value":null});
    let meta = json!({"zarr_consolidated_format":1,"metadata":{
        ".zgroup":{"zarr_format":2},
        "value/.zarray":arr(json!([2,2,2]),json!([1,2,2])),"value/.zattrs":{"_ARRAY_DIMENSIONS":["time","lat","lon"]},
        "lat/.zarray":arr(json!([2]),json!([2])),"lat/.zattrs":{"_ARRAY_DIMENSIONS":["lat"],"units":"degrees_north"},
        "lon/.zarray":arr(json!([2]),json!([2])),"lon/.zattrs":{"_ARRAY_DIMENSIONS":["lon"],"units":"degrees_east"}
    }});
    std::fs::write(store.join(".zmetadata"), meta.to_string()).unwrap();
    for (path, values) in [
        ("value/0.0.0", vec![1.0f64, 2.0, 3.0, 4.0]),
        ("value/1.0.0", vec![101.0f64, 102.0, 103.0, 104.0]),
        ("lat/0", vec![0.5, 1.5]),
        ("lon/0", vec![0.5, 1.5]),
    ] {
        let path = store.join(path);
        std::fs::create_dir_all(path.parent().unwrap()).unwrap();
        std::fs::write(path, values.iter().flat_map(|v| v.to_le_bytes()).collect::<Vec<_>>()).unwrap();
    }
    let sources = [
        ("flatgeobuf", "points.fgb"),
        ("geoparquet", "points.parquet"),
        ("lidar", "points.las"),
        ("raster", "grid.tif"),
        ("cog", "grid.tif"),
        ("zarr", "grid.zarr"),
        ("pmtiles", "tiles.pmtiles"),
        ("mbtiles", "tiles.mbtiles"),
    ];
    let layers: Vec<_> = sources
        .iter()
        .map(|(kind, file)| json!({"id":kind,"name":kind,"type":kind,"sourcePath":file,"source":{"variable":"value","index":{"time":1}}}))
        .collect();
    let mut s = world();
    let out=s.run("project.importGeolibre",&json!({"dir":dir,"text":json!({"version":"0.2.0","name":"Sources","mapView":{},"basemapStyleUrl":"","layers":layers}).to_string()})).unwrap();
    assert_eq!(out["layers"].as_array().unwrap().len(), sources.len(), "{out}");
    assert_eq!(s.map().layers.len(), 6);
    assert_eq!(s.map().tiles.len(), 2);
    let raster = s.map().layer_by_name("zarr").unwrap().raster.as_ref().unwrap().data.as_ref().unwrap();
    assert!(raster.bands[0].data.iter().all(|v| *v >= 101.0 && *v <= 104.0), "saved time slice must survive native import");
    // The archives stay open while the session draws them (MBTiles metadata is read on a
    // background thread), and Windows refuses to delete an open file: release them, and treat
    // the cleanup as best effort like the other tests do.
    drop(s);
    rustgis_data::mbtiles::close(&dir.join("tiles.mbtiles"));
    std::fs::remove_dir_all(&dir).ok();
}

